// Define a function to manage the dynamic array of TX_POWER_REPORT_INDICATION_T structures
TX_POWER_REPORT_INDICATION_T* manage_tx_power_report_indication(int N) {
    // Check if the input parameter is valid
    if (N <= 0) {
        return NULL;
    }

    // Allocate memory for the dynamic array of TX_POWER_REPORT_INDICATION_T structures
    TX_POWER_REPORT_INDICATION_T* tx_power_report_indications = malloc(N * sizeof(TX_POWER_REPORT_INDICATION_T));
    if (tx_power_report_indications == NULL) {
        return NULL;
    }

    // Initialize the dynamic array with empty structures
    for (int i = 0; i < N; ++i) {
        tx_power_report_indications[i].rx_ue_information = RX_UE_INFORMATION_TAG_EMPTY;
        tx_power_report_indications[i].rnti = 0;
        tx_power_report_indications[i].crc_indication_rel8 = CRC_INDICATION_REL8_TAG_EMPTY;
    }

    // Generate unique RNTIs for each structure in the dynamic array
    int current_rnti = 1;
    for (int i = 0; i < N; ++i) {
        while (true) {
            bool duplicate = false;
            for (int j = 0; j < i; ++j) {
                if (tx_power_report_indications[j].rnti == current_rnti) {
                    duplicate = true;
                    break;
                }
            }
            if (!duplicate) {
                tx_power_report_indications[i].rnti = current_rnti;
                break;
            }
            ++current_rnti;
        }
    }

    // Return the pointer to the dynamic array of TX_POWER_REPORT_INDICATION_T structures
    return tx_power_report_indications;
}
