    int key;
} IntKey;

typedef struct {
    int value;
} Record;

void allocateMemory(int numRecords) {
    // calculate total memory required for arrays
    size_t longOffsetSize = sizeof(LongOffset) * numRecords;
    size_t intKeySize = sizeof(IntKey) * numRecords;
    size_t recordSize = sizeof(Record) * numRecords;
    size_t totalMemoryRequired = longOffsetSize + intKeySize + recordSize;

    // check if total memory required exceeds 1 MB
    if (totalMemoryRequired > 1000000) {
        fprintf(stderr, "Error: Total memory required exceeds 1 MB.\n");
        exit(EXIT_FAILURE);
    }

    // allocate memory for arrays using custom memory management strategy
    LongOffset* longOffsets = (LongOffset*) malloc(longOffsetSize);
    IntKey* intKeys = (IntKey*) malloc(intKeySize);
    Record* records = (Record*) malloc(recordSize);

    if (!longOffsets || !intKeys || !records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    // initialize arrays with random values within specified range
    srand(time(NULL));
    for (int i = 0; i < numRecords; ++i) {
        longOffsets[i].offset = rand() % 1000000;
        intKeys[i].key = rand() % 500000;
        records[i].value = rand() % 1000000;
    }
}

void releaseMemory(LongOffset* longOffsets, IntKey* intKeys, Record* records) {
    free(longOffsets);
    free(intKeys);
    free(records);
}
