    fclose(file);
}

// Function to process each input file in a separate thread
void* process_file(void* arg) {
    // Get the thread-specific data from the argument
    thread_data_t* data = (thread_data_t*)arg;

    // Open the file for reading
    FILE* file = open_file(data->filename);

    // Process the file based on the mode
