            // Extract unique words from the file
            char* line = NULL;
            size_t len = 0;
            while (getline(&line, &len, file) != -1) {
                // Tokenize the line using whitespace as delimiter
                char* word = strtok(line, " \t\n");
                while (word != NULL) {
                    printf("%s ", word);
                    word = strtok(NULL, " \t\n");
                }
            }
            printf("\n");
            break;
        case CALCULATE_SIZE:
            // Calculate the size of the file in bytes
            long int file_size = 0;
            fseek(file, 0, SEEK_END);
            file_size = ftell(file);
            printf("File %s is %ld bytes.\n", data->filename, file_size);
            break;
        default:
            // Unsupported mode
            printf("Unsupported mode: %d\n", data->mode);
            break;
    }

    // Close the file handle
    close_file(file);

    // Free the thread-specific data
    free(data);
    return NULL;
}

int main(int argc, char* argv[]) {
    // Check if any files were specified
    if (argc < 3) {
        print_usage();
        exit(EXIT_FAILURE);
    }

    // Parse the command-line arguments
    int mode = -1;
    char* filename = NULL;
    for (int i = 2; i < argc; i++) {
        if (strcmp(argv[i], "-c") == 0 || strcmp(argv[i], "--count") == 0) {
            mode = COUNT_LINES;
        } else if (strcmp(argv[i], "-w") == 0 || strcmp(argv[i], "--words") == 0) {
            mode = EXTRACT_WORDS;
        } else if (strcmp(argv[i], "-s") == 0 || strcmp(argv[i], "--size") == 0) {
            mode = CALCULATE_SIZE;
        } else {
            filename = argv[i];
        }
    }

    // Check if a valid mode was specified
    if (mode < 0) {
        printf("Error: Invalid mode specified\n");
        print_usage();
        exit(EXIT_FAILURE);
    }

    // Check if a file was specified
    if (filename == NULL) {
        printf("Error: No files specified\n");
        print_usage();
        exit(EXIT_FAILURE);
    }

    // Create a new thread for each input file
    pthread_t* threads = malloc(sizeof(pthread_t) * (argc - 2));
    for (int i = 0; i < argc - 2; i++) {
        // Allocate memory for the thread-specific data
        thread_data_t* data = malloc(sizeof(thread_data_t));

        // Initialize the thread-specific data
        data->mode = mode;
        data->filename = argv[i + 2];
        data->file = NULL;

        // Create a new thread for processing the file
        pthread_create(&threads[i], NULL, process_file, (void*)data);
    }

    // Wait for all threads to finish
    for (int i = 0; i < argc - 2; i++) {
        void* retval = NULL;
        pthread_join(threads[i], &retval);
    }

    // Clean up
    free(threads);
    return 0;
}
