// function to efficiently read and parse a binary file
void* readFile(const char* filename) {
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        fprintf(stderr, "Error: failed to open input file\n");
        return NULL;
    }

    // determine size of file
    fseek(fp, 0, SEEK_END);
    long size = ftell(fp);
    rewind(fp);

    // allocate memory for buffer and read file into it
    char* buffer = malloc(size + 1);
    if (buffer == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for input file\n");
        return NULL;
    }
    size_t bytesRead = fread(buffer, 1, size, fp);
    buffer[bytesRead] = '\0';

    // close file and return buffer
    fclose(fp);
    return buffer;
}

