#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_LINE_LENGTH 1024
#define DNS_SERVER "8.8.8.8" // Google's public DNS server

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <file path> <hostname>\n", argv[0]);
        return 1;
    }

    // Parse command-line arguments
    const char *file_path = argv[1];
    const char *hostname = argv[2];

    // Open the file and check for errors
    FILE *fp = fopen(file_path, "r");
    if (fp == NULL) {
        perror("Error opening file");
        return 1;
    }

    // Initialize variables for DNS resolution and average calculation
    double average = 0.0;
    int line_count = 0;

    // Iterate through the lines of the file
    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, fp) != NULL) {
        // Parse the last two numeric fields from the current line
        int start = 0;
        for (int i = strlen(line) - 1; i >= 0 && line[i] != ' '; --i) {
            if (!isdigit(line[i])) {
                start = i + 1;
                break;
            }
        }
        int end = start;
        for (int i = start; i < strlen(line); ++i) {
            if (!isdigit(line[i])) {
                end = i;
                break;
            }
        }

        // Resolve the DNS hostname using Google's public DNS server
        struct addrinfo hints, *res;
        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_INET;
        hints.ai_socktype = SOCK_STREAM;
        if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
            fprintf(stderr, "Error resolving DNS hostname\n");
            return 1;
        }

        // Calculate the average of the last two numeric fields from the current line
        double num1 = atof(&line[start]);
        double num2 = atof(&line[end]);
        average += (num1 + num2) / 2.0;

        // Free memory allocated by getaddrinfo()
        freeaddrinfo(res);
    }

    // Close the file and print the average
    fclose(fp);
    printf("Average: %f\n", average / line_count);
    return 0;
}
```
