#include <stdint.h>
#include <pthread.h>
#include <stdbool.h>

// Circular buffer structure to store log entries
struct circular_buffer {
    uint8_t *data; // data array for storing log messages
    size_t capacity; // maximum number of log messages that can be stored in the buffer
    size_t head; // index of the next available slot in the buffer
    size_t tail; // index of the oldest log message in the buffer
    bool full; // flag to indicate if the buffer is full
};

// Initialize a circular buffer with a given capacity
void cb_init(struct circular_buffer *cb, size_t capacity) {
    cb->data = malloc(capacity);
    cb->capacity = capacity;
    cb->head = 0;
    cb->tail = 0;
    cb->full = false;
}

// Add a log message to the circular buffer, returning true if successful and false otherwise
bool cb_add(struct circular_buffer *cb, char *msg, size_t len) {
    // Check if the buffer is full
    if (cb->full) {
        return false;
    }

    // Write the log message to the buffer at the current head index
    memcpy(cb->data + cb->head, msg, len);

    // Increment the head index and update the full flag accordingly
    cb->head = (cb->head + len) % cb->capacity;
    if (cb->head == cb->tail) {
        cb->full = true;
    }

    return true;
}

// Read a log message from the circular buffer, returning true if successful and false otherwise
bool cb_read(struct circular_buffer *cb, char **msg, size_t *len) {
    // Check if the buffer is empty
    if (cb->tail == cb->head) {
        return false;
    }

    // Read the log message from the buffer at the current tail index
    memcpy(*msg, cb->data + cb->tail, len);

    // Increment the tail index and update the full flag accordingly
    cb->tail = (cb->tail + *len) % cb->capacity;
    if (cb->tail == cb->head) {
        cb->full = false;
    }

    return true;
}

// Clean up a circular buffer
void cb_destroy(struct circular_buffer *cb) {
    free(cb->data);
}
