    private List<String> getTypes(JSONObject json) {
        JSONArray types = json.getJSONArray("types");
        List<String> typeList = new ArrayList<>();
        for (int i = 0; i < types.length(); i++) {
            typeList.add(types.getString(i));
        }
        return typeList;
    }

    private Map<String, String> getWeaknesses(JSONObject json) {
        JSONArray weaknesses = json.getJSONArray("weaknesses");
        Map<String, String> weaknessMap = new HashMap<>();
        for (int i = 0; i < weaknesses.length(); i++) {
            JSONObject weakness = weaknesses.getJSONObject(i);
            weaknessMap.put(weakness.getString("type"), "Weakness");
        }
        return weaknessMap;
    }

    private Map<String, String> getResistances(JSONObject json) {
        JSONArray resistances = json.getJSONArray("resistances");
        Map<String, String> resistanceMap = new HashMap<>();
        for (int i = 0; i < resistances.length(); i++) {
            JSONObject resistance = resistances.getJSONObject(i);
            resistanceMap.put(resistance.getString("type"), "Resistance");
        }
        return resistanceMap;
    }
}
