#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <dlfcn.h>
#include <errno.h>

// Define the structure to hold information about a cryptographic algorithm
typedef struct {
    const char *name; // Name of the algorithm
    void (*init)();  // Initialization function
    void (*free)();  // Free function
    int (*hash)(const unsigned char *input, size_t input_len, unsigned char *output); // Hash function
    int (*encrypt)(const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext, size_t ciphertext_len);  // Encryption function
} Algorithm;

// Define a hash table to store the loaded algorithms
Algorithm *algorithms = NULL;
size_t num_algorithms = 0;

// Function to load and initialize an algorithm from a shared library
int load_algorithm(const char *libname, const char *algoname) {
    // Load the shared library
    void *handle = dlopen(libname, RTLD_NOW);
    if (!handle) {
        printf("Error loading shared library: %s\n", dlerror());
        return -1;
    }

    // Get the address of the initialization function
    void (*init_func)(void) = dlsym(handle, "init");
    if (!init_func) {
        printf("Error getting init function: %s\n", dlerror());
        return -1;
    }

    // Get the address of the hash function
    int (*hash_func)(const unsigned char *input, size_t input_len, unsigned char *output) = dlsym(handle, "hash");
    if (!hash_func) {
        printf("Error getting hash function: %s\n", dlerror());
        return -1;
    }

    // Get the address of the encryption function
    int (*encrypt_func)(const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext, size_t ciphertext_len) = dlsym(handle, "encrypt");
    if (!encrypt_func) {
        printf("Error getting encryption function: %s\n", dlerror());
        return -1;
    }

    // Allocate memory for the algorithm structure and initialize it
    Algorithm *alg = malloc(sizeof(Algorithm));
    if (!alg) {
        printf("Error allocating memory for algorithm: %s\n", strerror(errno));
        return -1;
    }

    // Set the name of the algorithm
    alg->name = algoname;

    // Initialize the algorithm
    init_func();

    // Store the address of the initialization and free functions in the structure
    alg->init = init_func;
    alg->free = dlsym(handle, "free");
    if (!alg->free) {
        printf("Error getting free function: %s\n", dlerror());
        return -1;
    }

    // Store the address of the hash and encryption functions in the structure
    alg->hash = hash_func;
    alg->encrypt = encrypt_func;

    // Add the algorithm to the list of loaded algorithms
    algorithms[num_algorithms++] = alg;

    return 0;
}

// Function to retrieve an algorithm by name
Algorithm *get_algorithm(const char *name) {
    for (int i = 0; i < num_algorithms; i++) {
        if (strcmp(name, algorithms[i]->name) == 0) {
            return algorithms[i];
        }
    }

    // If the algorithm is not found, return NULL
    return NULL;
}

// Function to free an algorithm structure and its associated shared library
void free_algorithm(Algorithm *alg) {
    if (alg->free) {
        alg->free();
    }

    dlclose(dlhandle);
    free(alg);
}

// Function to perform cryptographic operations using loaded algorithms
int crypt(const char *libname, const char *algoname, int mode, const unsigned char *input, size_t input_len, unsigned char *output) {
    Algorithm *alg = get_algorithm(algoname);
    if (!alg) {
        printf("Algorithm not found: %s\n", algoname);
        return -1;
    }

    // Perform the cryptographic operation based on the mode
    switch (mode) {
        case 0: // Hash
            return alg->hash(input, input_len, output);
        case 1: // Encrypt
            return alg->encrypt(input, input_len, output);
        default:
            printf("Invalid mode specified: %d\n", mode);
            return -1;
    }
}
```
This code implements a modular cryptographic library that dynamically loads and initializes algorithms from shared libraries. The `load_algorithm` function loads a shared library and gets the addresses of the initialization, hash, and encryption functions, and stores them in an `Algorithm` structure. The `get_algorithm` function retrieves an algorithm by name, and the `free_algorithm` function frees the memory allocated for the algorithm structure and its associated shared library. The `crypt` function performs cryptographic operations using loaded algorithms based on the mode specified.

This implementation ensures that new algorithms can be added without recompiling the main application, making it easy to extend the system with new algorithms in the future. It also provides detailed logs for troubleshooting and robust handling of potential errors. Additionally, the use of shared libraries allows for efficient sharing of code between different parts of the system, reducing the overall memory footprint of the system. However, as the number of supported algorithms increases, the performance overhead of frequent calls to `load_algorithm` and `get_algorithm` may become noticeable. To mitigate this, the system can use a caching mechanism to store the addresses of loaded libraries in memory, reducing the frequency of calls to these functions.']

