#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>
#include <assert.h>

// Semaphore struct to store semaphore data
struct semaphore {
    int value;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
};

// Array of semaphores to store all semaphores created by the library
static struct semaphore* semaphores[50];

// Initializes a semaphore with an initial value and returns its index in the array
int init_semaphore(int initial_value) {
    // Check if there is enough space to store a new semaphore
    if (num_semaphores >= 50) {
        fprintf(stderr, "Error: Too many semaphores created. Please clean up unused semaphores.\n");
        return -1;
    }

    // Create a new semaphore struct and initialize its value and mutex
    struct semaphore* sem = malloc(sizeof(struct semaphore));
    sem->value = initial_value;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);

    // Add the new semaphore to the array of semaphores and return its index
    int i = 0;
    while (semaphores[i] != NULL) {
        i++;
    }
    semaphores[i] = sem;
    num_semaphores++;
    return i;
}

// Destroys a semaphore and releases its resources
void destroy_semaphore(int index) {
    // Check if the specified index is within bounds of the array
    if (index < 0 || index >= num_semaphores) {
        fprintf(stderr, "Error: Invalid semaphore index.\n");
        return;
    }

    // Acquire the mutex for the specified semaphore
    pthread_mutex_lock(&semaphores[index]->mutex);

    // Destroy the condition variable and mutex
    pthread_cond_destroy(&semaphores[index]->cond);
    pthread_mutex_destroy(&semaphores[index]->mutex);

    // Free the semaphore struct
    free(semaphores[index]);

    // Remove the destroyed semaphore from the array of semaphores
    for (int i = index; i < num_semaphores - 1; i++) {
        semaphores[i] = semaphores[i + 1];
    }
    num_semaphores--;

    // Release the mutex
    pthread_mutex_unlock(&semaphores[index - 1]->mutex);
}

// Waits for a semaphore to become available, either blocking or non-blocking
void wait_for_semaphore(int index, int block) {
    // Check if the specified index is within bounds of the array
    if (index < 0 || index >= num_semaphores) {
        fprintf(stderr, "Error: Invalid semaphore index.\n");
        return;
    }

    // Acquire the mutex for the specified semaphore
    pthread_mutex_lock(&semaphores[index]->mutex);

    // While the semaphore is not available, either block or continue
    while (semaphores[index]->value == 0) {
        if (!block) {
            break;
        } else {
            pthread_cond_wait(&semaphores[index]->cond, &semaphores[index]->mutex);
        }
    }

    // Decrement the value of the semaphore and release the mutex
    semaphores[index]->value--;
    pthread_mutex_unlock(&semaphores[index]->mutex);
}

// Signals a semaphore, either increasing its value or returning immediately if it cannot be acquired
void signal_semaphore(int index) {
    // Check if the specified index is within bounds of the array
    if (index < 0 || index >= num_semaphores) {
        fprintf(stderr, "Error: Invalid semaphore index.\n");
        return;
    }

    // Acquire the mutex for the specified semaphore
    pthread_mutex_lock(&semaphores[index]->mutex);

    // If the semaphore is not currently available, do nothing
    if (semaphores[index]->value == 0) {
        pthread_mutex_unlock(&semaphores[index]->mutex);
        return;
    }

    // Increment the value of the semaphore and signal any waiting threads
    semaphores[index]->value++;
    pthread_cond_signal(&semaphores[index]->cond);

    // Release the mutex
    pthread_mutex_unlock(&semaphores[index]->mutex);
}

// Clean up all semaphores when the program terminates
void cleanup_semaphores() {
    for (int i = 0; i < num_semaphores; i++) {
        destroy_semaphore(i);
    }
}
```
This implementation uses a fixed array of semaphores to store all created semaphores, with each semaphore having its own mutex and condition variable. The `init_semaphore` function creates a new semaphore struct, initializes its value and mutex, and adds it to the array of semaphores. The `destroy_semaphore` function destroys a semaphore by destroying its condition variable and mutex, freeing the semaphore struct, and removing it from the array of semaphores.

The `wait_for_semaphore` function waits for a semaphore to become available either blocking or non-blocking depending on the value of the `block` parameter. It acquires the mutex for the specified semaphore, while the semaphore is not available either blocks or continues. Once the semaphore becomes available it decrements its value and releases the mutex.

The `signal_semaphore` function signals a semaphore by incrementing its value and signaling any waiting threads. If the semaphore is currently not available, do nothing. It acquires the mutex for the specified semaphore and checks if it is currently available. If it is not available, release the mutex and return. If it is available, increment its value and signal any waiting threads by releasing the mutex.

The `cleanup_semaphores` function cleans up all created semaphores when the program terminates by destroying each semaphore and removing it from the array of semaphores.']

['```rust
use actix_web::{App, HttpServer};
use std::fs::File;
use std::io::Read;
use serde_yaml::from_str as deserialize_yaml;

fn generate_api_server(config_path: &str) -> Result<(), Box<dyn std::error::Error>> {
    // Load configuration file
    let mut config_file = File::open(config_path)?;
    let mut config_contents = String::new();
    config_file.read_to_string(&mut config_contents)?;
    let config: Config = deserialize_yaml(config_contents)?;

    // Create Actix-web App instance
    let app = App::new()?;

    // Set up middleware and rate limiting policies
    let mut middleware = Vec::new();
    for endpoint in &config.middleware {
        let middleware_fn = |req: HttpRequest| -> Result<HttpResponse, Box<dyn std::error::Error>> {
            // Apply custom middleware to request
            Ok(req)
        };
        middleware.push(middleware_fn);
    }
    let rate_limiters = config.rate_limiters;
    for (endpoint, limiter) in &rate_limiters {
        let limiter_fn = |req: HttpRequest| -> Result<HttpResponse, Box<dyn std::error::Error>> {
            // Apply rate limiting to request
            Ok(req)
        };
        middleware.push(limiter_fn);
    }
    let app = app.with_middleware(middleware);

    // Set up routes and response templates
    for (endpoint, template) in &config.routes {
        let route = Route::new()?;
        route.route(Method::GET, "/{endpoint}", |req| {
            // Return custom response based on request data
            Ok(Response::builder().body(template))
        });
        app.with_route(route);
    }

    // Start server with config values
    let port = config.port;
    let addr = ("0.0.0.0", port);
    HttpServer::new(app)?.bind(addr)?.run()?;

    Ok(())
}
```
