```php
<?php

function manageUserAccount($request) {
    // Validate request data
    $validationResult = validateRequestData($request);
    if (!$validationResult['valid']) {
        return array(
            'status' => 400,
            'message' => $validationResult['errors']
        );
    }

    // Perform action based on sub_action parameter
    switch ($request['sub_action']) {
        case 'create':
            createUser($request);
            break;
        case 'update':
            updateUser($request);
            break;
        case 'delete':
            deleteUser($request);
            break;
    }
}

function validateRequestData($request) {
    // Check if id is provided and valid
    if (isset($request['id']) && !ctype_digit($request['id'])) {
        return array(
            'valid' => false,
            'errors' => array('Invalid ID format')
        );
    }

    // Check if name is provided and not empty
    if (!isset($request['name']) || trim($request['name']) === '') {
        return array(
            'valid' => false,
            'errors' => array('Name is required')
        );
    }

    // Check if email is provided and valid
    if (!isset($request['email']) || !filter_var($request['email'], FILTER_VALIDATE_EMAIL)) {
        return array(
            'valid' => false,
            'errors' => array('Invalid email format')
        );
    }

    // Check if password is provided and meets complexity requirements
    if (!isset($request['password']) || strlen($request['password']) < 8) {
        return array(
            'valid' => false,
            'errors' => array('Password must be at least 8 characters long')
        );
    }

    // Check if confirm_password is provided and matches password
    if (isset($request['confirm_password']) && $request['password'] !== $request['confirm_password']) {
        return array(
            'valid' => false,
            'errors' => array('Password and confirmation password do not match')
        );
    }

    // Check if sub_action is provided and valid
    if (!isset($request['sub_action']) || !in_array($request['sub_action'], array('create', 'update', 'delete'))) {
        return array(
            'valid' => false,
            'errors' => array('Invalid sub_action')
        );
    }

    // If validation is successful, return true
    return array(
        'valid' => true
    );
}

function createUser($request) {
    // Generate unique username if none provided
    $username = generateUniqueUsername($request['name']);

    // Save user details in database
    $saveResult = saveUserDetails($request, $username);
    if (!$saveResult['success']) {
        return array(
            'status' => 500,
            'message' => 'Error saving user details'
        );
    }

    // Log successful creation operation
    logOperation('create', $request['id'], $username);

    // Return JSON response with success status and username
    return array(
        'status' => 200,
        'message' => 'User created successfully',
        'data' => array(
            'username' => $username
        )
    );
}

function updateUser($request) {
    // Save user details in database
    $saveResult = saveUserDetails($request);
    if (!$saveResult['success']) {
        return array(
            'status' => 500,
            'message' => 'Error updating user details'
        );
    }

    // Log successful update operation
    logOperation('update', $request['id']);

    // Return JSON response with success status and username
    return array(
        'status' => 200,
        'message' => 'User updated successfully',
        'data' => array(
            'username' => $request['name']
        )
    );
}

function deleteUser($request) {
    // Delete user details from database
    $deleteResult = deleteUserDetails($request);
    if (!$deleteResult['success']) {
        return array(
            'status' => 500,
            'message' => 'Error deleting user details'
        );
    }

    // Log successful delete operation
    logOperation('delete', $request['id']);

    // Return JSON response with success status and username
    return array(
        'status' => 200,
        'message' => 'User deleted successfully'
    );
}

function generateUniqueUsername($name) {
    // Generate unique username by appending a number to the end of the name
    $username = $name . '_' . rand(1000, 9999);

    // Check if username is already taken in database
    $checkResult = checkUsernameTaken($username);
    if ($checkResult['taken']) {
        return generateUniqueUsername($name);
    }

    return $username;
}

function saveUserDetails($request, $username) {
    // Save user details in database using PDO
    try {
        $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'root', 'password');
        $statement = $db->prepare('INSERT INTO users (id, name, email, password, username) VALUES (:id, :name, :email, :password, :username)');
        $statement->bindValue(':id', $request['id'], PDO::PARAM_INT);
        $statement->bindValue(':name', $request['name']);
        $statement->bindValue(':email', $request['email']);
        $statement->bindValue(':password', $request['password']);
        $statement->bindValue(':username', $username, PDO::PARAM_STR);
        $result = $statement->execute();
        return array(
            'success' => true,
            'data' => $statement->fetchAll()
        );
    } catch (PDOException $e) {
        return array(
            'success' => false,
            'message' => $e->getMessage()
        );
    }
}

function deleteUserDetails($request) {
    // Delete user details from database using PDO
    try {
        $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'root', 'password');
        $statement = $db->prepare('DELETE FROM users WHERE id = :id');
        $statement->bindValue(':id', $request['id'], PDO::PARAM_INT);
        $result = $statement->execute();
        return array(
            'success' => true,
            'data' => $statement->fetchAll()
        );
    } catch (PDOException $e) {
        return array(
            'success' => false,
            'message' => $e->getMessage()
        );
    }
}

function checkUsernameTaken($username) {
    // Check if username is already taken in database using PDO
    try {
        $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'root', 'password');
        $statement = $db->prepare('SELECT COUNT(*) as total FROM users WHERE username = :username');
        $statement->bindValue(':username', $username, PDO::PARAM_STR);
        $result = $statement->execute();
        return array(
            'taken' => $result['total'] > 0
        );
    } catch (PDOException $e) {
        return array(
            'success' => false,
            'message' => $e->getMessage()
        );
    }
}

function logOperation($operation, $id = null, $username = null) {
    // Log operation using PDO
    try {
        $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'root', 'password');
        $statement = $db->prepare('INSERT INTO operations (operation, id, username) VALUES (:operation, :id, :username)');
        $statement->bindValue(':operation', $operation);
        $statement->bindValue(':id', $id, PDO::PARAM_INT);
        $statement->bindValue(':username', $username, PDO::PARAM_STR);
        $result = $statement->execute();
    } catch (PDOException $e) {
        echo 'Error logging operation: ' . $e->getMessage();
    }
}
```
