    public class HttpPostRequestHandler {
        private readonly PageSectionService _pageSectionService;

        public HttpPostRequestHandler(PageSectionService pageSectionService) {
            _pageSectionService = pageSectionService;
        }

        public async Task<HttpResponseMessage> HandlePostRequestAsync(string pageSectionId, string elementId, string htmlContent) {
            if (string.IsNullOrWhiteSpace(pageSectionId)) {
                throw new ArgumentException("Page section ID cannot be null or whitespace.", nameof(pageSectionId));
            }
            if (string.IsNullOrWhiteSpace(elementId)) {
                throw new ArgumentException("Element ID cannot be null or whitespace.", nameof(elementId));
            }
            if (htmlContent == null) {
                throw new ArgumentNullException(nameof(htmlContent));
            }

            try {
                await _pageSectionService.UpdateHtmlContentAsync(pageSectionId, elementId, htmlContent);
                return new HttpResponseMessage(HttpStatusCode.OK) {
                    Content = new StringContent("Page should be refreshed", Encoding.UTF8, "text/plain")
                };
            } catch (Exception e) {
                // Log error and return 500 Internal Server Error
                Console.WriteLine(e);
                return new HttpResponseMessage(HttpStatusCode.InternalServerError);
            }
        }
    }
}
