          // If a test fails, retry up to the maximum number of retries specified
          for (let j = 0; j < maxRetries; j++) {
            try {
              // Retry the test
              await f();
              break;
            } catch (error) {}
          }
        }
      });
    }
  });

  // Provide summary statistics on the log of test results
  afterAll(() => {
    const failedTests = [];
    const passedTests = [];
    for (const test of tests) {
      if (test.failed()) {
        failedTests.push(test);
      } else {
        passedTests.push(test);
