2. C++ function for forward list:
```
void insertAfter(std::forward_list<std::string> &list, const std::string &target, const std::string &newString) {
  // Find the first occurrence of the target string in the list
  auto it = std::find(list.begin(), list.end(), target);

  // If the target string is not found, append the new string to the end of the list
  if (it == list.end()) {
    list.push_back(newString);
  } else {
    // Insert the new string after the first occurrence of the target string
    auto nextIt = std::next(it);
    list.insert_after(nextIt, newString);
  }
}
```
