  private static final long PAUSE_DURATION = 5000L; // milliseconds
  private static final long RANDOM_DELAY_MIN = 2000L; // milliseconds
  private static final long RANDOM_DELAY_MAX = 5000L; // milliseconds

  private boolean isPaused;
  private ConcurrentLinkedQueue<byte[]> buffer;
  private Random random;

  public DataIngestionService() {
    this.buffer = new ConcurrentLinkedQueue<>();
    this.random = new Random();
    this.isPaused = false;
  }

  public void ingest(byte[] data) {
    if (this.isPaused) {
      logStateToMonitoringSystem();
    } else {
      buffer.offer(data);
    }
  }

  private void logStateToMonitoringSystem() {
    // implement logging to monitoring system here
  }

  public void pauseIngestion() {
    this.isPaused = true;
  }

  public void resumeIngestion() {
    this.isPaused = false;
  }

  private void handleRandomDelay() {
    long randomDelay = random.nextLong(RANDOM_DELAY_MIN, RANDOM_DELAY_MAX);
    try {
      Thread.sleep(randomDelay);
    } catch (InterruptedException e) {
      // ignore
    }
  }
}
