        instances.get(instanceId).start();
    }

    public void stopInstance(String instanceId) {
        instances.get(instanceId).stop();
    }

    public void updateMetrics(String instanceId, Map<String, String> metrics) {
        ServiceInstance instance = instances.get(instanceId);
        if (instance == null) {
            return;
        }
        instance.updateCPUUtilization(Double.parseDouble(metrics.get("cpu_utilization")));
        instance.updateMemoryConsumption(Long.parseLong(metrics.get("memory_consumption")));
    }

    public void updateHealthChecks(String instanceId, Map<String, String> healthChecks) {
        ServiceInstance instance = instances.get(instanceId);
        if (instance == null) {
            return;
        }
        instance.updateLatency(Long.parseLong(healthChecks.get("latency")));
    }

    public void updateInstanceLogs(String instanceId, String logs) {
        ServiceInstance instance = instances.get(instanceId);
        if (instance == null) {
            return;
        }
        instance.updateLogs(logs);
    }

    public Map<String, Object> getInstanceMetrics(String instanceId) {
        ServiceInstance instance = instances.get(instanceId);
        if (instance == null) {
            return null;
        }
        return instance.getMetrics();
    }

    private class ServiceInstance {
        private String id;
        private boolean running = false;
        private long startTime = 0;
        private long stopTime = 0;
        private double cpuUtilization = 0;
        private long memoryConsumption = 0;
        private long latency = 0;
        private String logs = "";

        public ServiceInstance(String id) {
            this.id = id;
        }

        public void start() {
            if (running) {
                return;
            }
            running = true;
            startTime = System.currentTimeMillis();
        }

        public void stop() {
            if (!running) {
                return;
            }
            running = false;
            stopTime = System.currentTimeMillis();
        }

        public void updateCPUUtilization(double cpuUtilization) {
            this.cpuUtilization = cpuUtilization;
        }

        public void updateMemoryConsumption(long memoryConsumption) {
            this.memoryConsumption = memoryConsumption;
        }

        public void updateLatency(long latency) {
            this.latency = latency;
        }

        public void updateLogs(String logs) {
            this.logs = logs;
        }

        public Map<String, Object> getMetrics() {
            return Map.of("id", id, "running", running, "startTime", startTime, "stopTime", stopTime, "cpuUtilization", cpuUtilization, "memoryConsumption", memoryConsumption, "latency", latency, "logs", logs);
        }
    }
}
```
This code defines a `ServiceInstanceManager` class that manages a fleet of service instances operating in a cloud environment. Each instance is represented by a `ServiceInstance` object, which tracks the instance's running state, start and stop times, CPU utilization, memory consumption, latency, and logs. The manager provides methods to add, remove, start, stop, update metrics, perform health checks, update instance logs, and retrieve instance metrics.

The `ServiceInstanceManager` class also defines a static constant for the CPU utilization threshold (25%), the memory consumption ratio (0.5), and the latency threshold (1000 milliseconds). These constants are used throughout the code to determine when an instance should be terminated or when it should be scaled up or down.

The `ServiceInstance` class contains methods for starting, stopping, updating metrics, performing health checks, updating logs, and retrieving instance metrics. It also tracks the instance's running state, start and stop times, CPU utilization, memory consumption, latency, and logs. The `updateMetrics()` method takes a map of metrics and updates the instance's CPU utilization, memory consumption, and latency accordingly. The `updateHealthChecks()` method takes a map of health checks and updates the instance's latency accordingly. The `updateInstanceLogs()` method takes a string of logs and updates the instance's logs accordingly. The `getInstanceMetrics()` method returns a map of the instance's metrics, including its ID, running state, start and stop times, CPU utilization, memory consumption, latency, and logs.

Overall, this code provides a flexible framework for managing service instances in a cloud environment, allowing developers to configure instance settings and scaling policies, monitor instance performance, and integrate with external monitoring systems.']

