function generateDynamicCredentials(length, directoryPath, password, optionalSeed) {
  // Read the file from the specified directory path and convert its contents to a string
  const fileContents = readFileSync(directoryPath);
  const characterSet = fileContents.split('');

  // Create a new instance of the default hashing algorithm provided by JavaScript's crypto module
  const hash = crypto.createHash('sha256');

  // If an optional seed is provided, use it to seed the random number generator
  if (optionalSeed) {
    hash.seed(optionalSeed);
  }

  // Generate a random string of the specified length using the character set derived from the file contents
  const randomString = hash.randomBytes(length).toString('hex');

  // Hash the password using the default hashing algorithm provided by JavaScript's crypto module
  const hashedPassword = hash.update(password).digest('hex');

  // Combine the length of the string and the hashed password to create a checksum
  const checksum = `${randomString.length}${hashedPassword}`;

  return {
    randomString,
    hashedPassword,
    checksum: checksum,
  };
}

function readFileSync(directoryPath) {
  try {
    // Read the file from the specified directory path and convert its contents to a string
    const fileContents = fs.readFileSync(directoryPath).toString();

    return fileContents;
  } catch (error) {
    console.log(`Error reading file from ${directoryPath}: ${error.message}`);
    return null;
  }
}
