["function getPrivateKeyAndCertificate(accessToken) {
  return new Promise((resolve, reject) => {
    const url = `https://api.example.com/oauth2/user/${accessToken}`;
    const headers = {
      'Authorization': `Bearer ${accessToken}`,
      'Content-Type': 'application/json'
    };
