      headers,
      signal: abortController.signal
    };

    fetch(url, requestOptions)
      .then(response => response.json())
      .then(data => {
        if (data.error) {
          reject(new Error(`Error retrieving private key and certificate: ${data.error}`));
        } else {
          const privateKey = data.private_key;
          const certificate = data.certificate;
          const pemData = `${privateKey}\n${certificate}`;
          resolve(pemData);
        }
      })
      .catch(error => {
        reject(new Error(`Error retrieving private key and certificate: ${error}`));
      });
  });
}

function streamDataFromSocket(socket, onData) {
  return new Promise((resolve, reject) => {
    const buffer = [];
    socket.on('data', data => {
      buffer.push(data);
      if (buffer.length > 1024 * 1024) { // 1 MB
        onData(Buffer.concat(buffer).toString());
        buffer.length = 0;
      }
    });
    socket.on('close', () => {
      resolve();
    });
    socket.on('error', error => {
      reject(new Error(`Error streaming data from socket: ${error}`));
    });
  });
}

function handlePauseAndResume() {
  if (buffer.length === 0) return; // No need to pause/resume if buffer is empty
  const currentTime = Date.now();
  const timeSinceLastData = currentTime - lastDataTimestamp;
  if (timeSinceLastData > 1000) { // 1 second
    socket.pause();
    console.log('Pausing data streaming due to inactivity...');
    setTimeout(() => {
      socket.resume();
      console.log('Resuming data streaming...');
    }, 5000); // 5 seconds
  } else {
    console.log(`Still receiving data, no need to pause/resume (${timeSinceLastData}ms since last data)`);
  }
}

function manageBuffer() {
  const currentTime = Date.now();
  const bufferSize = buffer.length;
  if (bufferSize > 1024 * 1024 * 5) { // 5 MB
    console.log('Buffer size exceeded, clearing data...');
    buffer.length = 0;
  } else if (bufferSize > 1024 * 1024) { // 1 MB
    const oldData = buffer.shift();
    console.log(`Clearing oldest data (age: ${currentTime - oldData.timestamp}ms)`);
  }
}

function processRealTimeData(data) {
  console.log('Processing real-time data...');
  // Process data here
}

function main() {
