            threat_scores[index].timestamp = time(NULL);
        }
    }

    // Release the mutex
    pthread_mutex_unlock(&mutex);
}

// Define a function to compute the threat score for a given connection
double compute_threat_score(int size, int frequency) {
    double score = 0.0;

    // Compute the threat score based on packet size and inter-packet frequency
    if (size > PACKET_SIZE || frequency < INTER_PACKET_FREQUENCY) {
        score += 1.0;
    }

    return score;
}

// Define a function to find the index of a connection in the connections array based on its socket descriptor
int find_connection_index(int socket) {
    for (int i = 0; i < num_connections; i++) {
        if (connections[i].socket == socket) {
            return i;
        }
    }

    return -1;
}

// Define a function to handle incoming packets and update the threat scores for each connection
void packet_handler(int sockfd, struct sockaddr* client_address, int address_len) {
    // Acquire the mutex
    pthread_mutex_lock(&mutex);

    // Update the threat score for the incoming connection
    update_threat_score(sockfd);

    // Release the mutex
    pthread_mutex_unlock(&mutex);
}

// Define a function to handle an incoming request and return the highest threat score along with its associated connection identifier
void* handle_request() {
    int highest_threat_score = 0;
    int highest_connection_index = -1;

    // Acquire the mutex
