// Define the structure to hold configuration settings
typedef struct {
    char *name;
    char *value;
} Setting;

// Define a function to read the configuration file and return an array of settings
Setting **read_settings(char *path) {
    // Open the configuration file for reading
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    // Get the size of the file in bytes
    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("fstat");
        close(fd);
        exit(1);
    }

    // Allocate memory for the settings array
    Setting **settings = malloc(sizeof(Setting *) * st.st_size);
    if (settings == NULL) {
        perror("malloc");
        close(fd);
        exit(1);
    }

    // Read the file contents into the settings array
    size_t i = 0;
    ssize_t nread;
    char buffer[4096];
    while ((nread = read(fd, buffer, sizeof(buffer))) > 0) {
        for (char *p = buffer; p < buffer + nread; p++) {
            if (*p == '=') {
                Setting *setting = malloc(sizeof(Setting));
                setting->name = strndup(buffer, p - buffer);
                setting->value = strdup(p + 1);
                settings[i++] = setting;
            }
        }
    }

    // Close the file descriptor
    close(fd);

    // Return the array of settings
    return settings;
}

// Define a function to free the memory allocated for the settings
void free_settings(Setting **settings) {
    if (settings == NULL) {
        return;
    }
    for (int i = 0; settings[i] != NULL; i++) {
        free(settings[i]->name);
        free(settings[i]->value);
        free(settings[i]);
    }
    free(settings);
}

