    if (!file) {
        return NULL;
    }

    struct stat fileStat;
    if (fstat(fileno(file), &fileStat)) {
        fclose(file);
        return NULL;
    }

    unsigned long size = fileStat.st_size;
    char* data = malloc(size + 1);
    if (!data) {
        fclose(file);
        return NULL;
    }

    // Read the entire file into memory
    size_t bytesRead = fread(data, 1, size, file);
    if (bytesRead < size) {
        free(data);
        fclose(file);
        return NULL;
    }

    data[size] = '\0';
    fclose(file);

    // Create a new theme resource struct and populate it with the file's contents
    struct ThemeResource* resource = malloc(sizeof(struct ThemeResource));
    if (!resource) {
        free(data);
        return NULL;
    }

    resource->filename = filename;
    resource->size = size;
    resource->data = data;

    return resource;
}

// Function to load a theme from a file and add it to the cache
void loadTheme(const char* filename, struct ThemeCache* cache) {
    // Create a new theme resource from the file
    struct ThemeResource* resource = createThemeResource(filename);
    if (!resource) {
        return;
    }

    // Check if there is enough space in the cache to store the new resource
    if (cache->count >= cache->capacity) {
        // If not, remove the oldest resource from the cache
        struct ThemeResource* oldResource = cache->resources[0];
        free(oldResource->data);
        cache->resources[0] = NULL;
        cache->count--;
    }

    // Add the new resource to the cache
    cache->resources[cache->count++] = resource;
}

// Function to retrieve a theme from the cache
struct ThemeResource* getTheme(const char* filename, struct ThemeCache* cache) {
    for (int i = 0; i < cache->count; i++) {
        if (!strcmp(cache->resources[i]->filename, filename)) {
            // Return the theme resource from the cache
            return cache->resources[i];
        }
    }

    // If not found in the cache, load it from disk and add it to the cache
    loadTheme(filename, cache);

    return getTheme(filename, cache);
}

// Function to process a text file line by line, converting it into comma-separated format with average of last two fields
void processTextFile(const char* filename) {
    // Open the file and read its contents into memory
    FILE* file = fopen(filename, "r");
    if (!file) {
        return;
    }

    struct stat fileStat;
    if (fstat(fileno(file), &fileStat)) {
        fclose(file);
        return;
    }

    unsigned long size = fileStat.st_size;
    char* data = malloc(size + 1);
    if (!data) {
        fclose(file);
        return;
    }

    // Read the entire file into memory
    size_t bytesRead = fread(data, 1, size, file);
    if (bytesRead < size) {
        free(data);
        fclose(file);
        return;
    }

    data[size] = '\0';
    fclose(file);

    // Iterate over each line in the file and process it
    char* line = strtok(data, "\n");
    while (line) {
        char* lastField = NULL;
        char* penultimateField = NULL;

        char* token = strtok(line, ",");
        while (token) {
            if (!penultimateField) {
                penultimateField = token;
            } else if (!lastField) {
                lastField = token;
            } else {
                // Calculate the average of the last two fields and append it to the end of the line
                double average = (strtod(penultimateField, NULL) + strtod(lastField, NULL)) / 2.0;
                char* averageString = malloc(16);
                if (!averageString) {
                    break;
                }

                snprintf(averageString, 16, "%f", average);
                lastField = strcat(token, ",");
                lastField = strcat(lastField, averageString);

                penultimateField = NULL;
            }

            token = strtok(NULL, ",");
        }

        line = strtok(NULL, "\n");
    }

    free(data);
}

// Function to handle memory management and optimize for leaks and varying line lengths
void processTextFiles(const char* filePaths[], int numFiles) {
    // Create a cache of theme resources
    struct ThemeCache cache;
    cache.capacity = 10;
    cache.count = 0;
    cache.resources = malloc(cache.capacity * sizeof(struct ThemeResource*));
    for (int i = 0; i < cache.capacity; i++) {
        cache.resources[i] = NULL;
    }

    // Iterate over each file in the list and process it
    for (int i = 0; i < numFiles; i++) {
        processTextFile(filePaths[i]);
    }

    // Free the cache and any resources that were allocated during processing
    for (int i = 0; i < cache.count; i++) {
        free(cache.resources[i]->data);
        cache.resources[i] = NULL;
    }

    free(cache.resources);
}
```
This code implements the following functionalities:

1. Creating a struct to represent a theme resource and a cache structure to hold the theme resources.
2. A function to create a new theme resource from a file, which reads the entire file into memory and creates a new theme resource struct with the file's contents.
3. A function to load a theme from a file and add it to the cache, which checks if there is enough space in the cache to store the new resource and removes the oldest resource if necessary before adding the new resource.
4. A function to retrieve a theme from the cache, which searches for a matching theme resource in the cache and adds the new resource if not found.
5. A function to process a text file line by line, converting each line into comma-separated format with average of last two fields.
6. A function to handle memory management and optimize for leaks and varying line lengths.
7. A main function that reads the file paths from a command-line argument and calls the processing functions.']

