typedef struct {
  uint16_t bits_per_sample;
  uint16_t sample_per_pixel;
  uint32_t number_of_extra_samples;
  unsigned char md5_hash[MD5_DIGEST_LENGTH];
} metadata_and_hash_t;

metadata_and_hash_t ProcessImageAndComputeHash(const char* filename, const char* string) {
  TIFF *tif = NULL;
  uint16_t bits_per_sample = 0;
  uint16_t sample_per_pixel = 0;
  uint32_t number_of_extra_samples = 0;
  unsigned char md5_hash[MD5_DIGEST_LENGTH];

  // Open the TIFF file and check for errors
  tif = TIFFOpen(filename, "r");
  if (tif == NULL) {
    fprintf(stderr, "Error: Could not open TIFF file %s\n", filename);
    return;
  }

  // Read the image metadata and check for errors
  TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bits_per_sample);
  if (bits_per_sample > 12) {
    fprintf(stderr, "Warning: Bits per sample exceeds 12 bits\n");
  }
  TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &sample_per_pixel);
  if (sample_per_pixel > 4) {
    fprintf(stderr, "Warning: Sample per pixel exceeds 4\n");
  }
  TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &number_of_extra_samples);

  // Compute the MD5 hash of the provided string and store the result
  MD5((unsigned char*)string, strlen(string), md5_hash);

  // Close the TIFF file and return the struct containing metadata and hash
  TIFFClose(tif);
  return (metadata_and_hash_t){ bits_per_sample, sample_per_pixel, number_of_extra_samples, md5_hash };
}
