        // Handle ambiguous cases where first character does not clearly indicate a file type
        return "Invalid file type";
    }

    // Append even and odd digits to new filename
    sprintf(new_filename, "%s%d%d", filename, even_digit_count, odd_digit_count);

    // Determine extension based on file type
    if (strcmp(file_type, "txt") == 0) {
        extension = ".txt";
    } else if (strcmp(file_type, "log") == 0) {
        extension = ".log";
    } else if (strcmp(file_type, "dat") == 0) {
