struct ctx {
    algorithm_type alg; // algorithm type (AES, Camellia, etc.)
    size_t key_size; // key size in bytes
    unsigned char key[MAX_KEY_SIZE]; // key data
    unsigned char iv[MAX_BLOCK_SIZE]; // initialization vector data
};

// function to generate a random key
int gen_random_key(struct key *key) {
    if (key->length > MAX_KEY_SIZE || key->length == 0) {
        return ERR_INVALID_KEY;
    }
    // generate random bytes for the key
    unsigned char rand[key->length];
    int ret = RAND_bytes(rand, key->length);
    if (ret != 1) {
        return ERR_MEMORY_ERROR;
    }
    memcpy(key->data, rand, key->length);
    return ERR_OK;
}

// function to generate a random initialization vector
int gen_random_iv(struct iv *iv) {
    if (iv->length > MAX_BLOCK_SIZE || iv->length == 0) {
        return ERR_INVALID_KEY;
    }
    // generate random bytes for the initialization vector
    unsigned char rand[iv->length];
    int ret = RAND_bytes(rand, iv->length);
    if (ret != 1) {
        return ERR_MEMORY_ERROR;
    }
    memcpy(iv->data, rand, iv->length);
    return ERR_OK;
}

// function to initialize an encryption/decryption context
int init_ctx(struct ctx *ctx, algorithm_type alg, size_t key_size) {
    if (key_size > MAX_KEY_SIZE || key_size == 0) {
        return ERR_INVALID_KEY;
    }
    if (!alg) {
        return ERR_INVALID_ALGORITHM;
    }
    ctx->alg = alg;
    ctx->key_size = key_size;
    // generate a random key for the context
    gen_random_key(&ctx->key);
    // generate a random initialization vector for the context
    gen_random_iv(&ctx->iv);
    return ERR_OK;
}

// function to encrypt data using an encryption/decryption context
int encrypt(struct ctx *ctx, const unsigned char *data, size_t data_len) {
    if (data_len > MAX_BLOCK_SIZE || data_len == 0) {
        return ERR_INVALID_DATA;
    }
    // encrypt the data using the context's algorithm and key
    switch (ctx->alg) {
        case AES:
            return AES_encrypt(data, ctx->key, data_len);
        case CAMELLIA:
            return Camellia_encrypt(data, ctx->key, data_len);
        case MD5:
            return MD5_hash(data, data_len, NULL);
        case SHA:
            return SHA_hash(data, data_len, NULL);
        case RSA:
            return RSA_encrypt(data, ctx->key, data_len);
        case CHACHA20:
            return ChaCha20_encrypt(data, ctx->key, data_len);
        case POLY1305:
            return Poly1305_hash(data, data_len, NULL);
    }
}

// function to decrypt data using an encryption/decryption context
int decrypt(struct ctx *ctx, const unsigned char *data, size_t data_len) {
    if (data_len > MAX_BLOCK_SIZE || data_len == 0) {
        return ERR_INVALID_DATA;
    }
    // decrypt the data using the context's algorithm and key
    switch (ctx->alg) {
        case AES:
            return AES_decrypt(data, ctx->key, data_len);
        case CAMELLIA:
            return Camellia_decrypt(data, ctx->key, data_len);
        case MD5:
            return MD5_hash(data, data_len, NULL);
        case SHA:
            return SHA_hash(data, data_len, NULL);
        case RSA:
            return RSA_decrypt(data, ctx->key, data_len);
        case CHACHA20:
            return ChaCha20_decrypt(data, ctx->key, data_len);
        case POLY1305:
            return Poly1305_hash(data, data_len, NULL);
    }
}

// main function for testing the library
int main() {
    // generate a random key for use in the encryption/decryption context
    struct key key;
    gen_random_key(&key);
    // initialize an encryption/decryption context with the key and algorithm
    struct ctx ctx;
    init_ctx(&ctx, AES, key.length);
    // encrypt a block of data using the encryption/decryption context
    unsigned char data[MAX_BLOCK_SIZE];
    size_t data_len = 16;
    int ret = encrypt(&ctx, data, data_len);
    if (ret != ERR_OK) {
        printf("Error: %s\n", get_error_message(ret));
        return 1;
    }
    // decrypt the encrypted block of data using the encryption/decryption context
    unsigned char decrypted[MAX_BLOCK_SIZE];
    size_t decrypted_len = data_len;
    ret = decrypt(&ctx, data, data_len);
    if (ret != ERR_OK) {
        printf("Error: %s\n", get_error_message(ret));
        return 1;
    }
    // print the original and decrypted blocks of data for verification
    printf("Original: ");
    for (size_t i = 0; i < data_len; i++) {
        printf("%02x ", data[i]);
    }
    printf("\n");
    printf("Decrypted: ");
    for (size_t i = 0; i < decrypted_len; i++) {
        printf("%02x ", decrypted[i]);
    }
    printf("\n");
}
