    public static async Task<string> DeployWebsiteAsync(string directoryPath, string siteName, IConfiguration configuration)
    {
        try
        {
            // Check if web.config file exists in the directory
            var webConfigFilePath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(webConfigFilePath))
                return null;

            // Validate directory path and read/write permissions
            if (!Directory.Exists(directoryPath) || !Directory.GetAccessControl(directoryPath).AreAccessRulesProtected)
            {
                throw new UnauthorizedAccessException("The specified directory does not exist or has insufficient read/write permissions.");
            }

            // Modify web.config file to use HTTPS if necessary
            var webConfigFile = File.ReadAllText(webConfigFilePath);
            if (!webConfigFile.Contains("<bindings>"))
            {
