            }
            else if (!webConfigFile.Contains("<binding protocol=\"https\" />"))
            {
                var updatedWebConfig = webConfigFile.Replace("<bindings>", "<bindings><binding protocol=\"https\" />");
                File.WriteAllText(webConfigFilePath, updatedWebConfig);
            }

            // Commit changes to the directory
            DirectoryInfo directoryInfo = new DirectoryInfo(directoryPath);
            directoryInfo.Refresh();

            // Start the process using the Process class
            var startInfo = new ProcessStartInfo()
            {
