// Function to verify the presence and validity of session data fields
bool validate_session(const json_object *session) {
    // Check for missing or malformed JSON data
    if (!session || !json_object_is_type(session, json_type_object)) {
        return false;
    }

    // Get the session ID and user ID
    const char *session_id = json_object_get_string(json_object_object_get(session, "session_id"));
    const char *user_id = json_object_get_string(json_object_object_get(session, "user_id"));

    // Check if the session ID is a unique identifier
    if (!session_id || strlen(session_id) == 0) {
        return false;
    }

    // Check if the user ID is valid
    if (!user_id || strlen(user_id) == 0) {
        return false;
    }

    // Get the expiration time and last activity timestamp
    long int expiration_time = json_object_get_int(json_object_object_get(session, "expiration_time"));
    long int last_activity_timestamp = json_object_get_int(json_object_object_get(session, "last_activity_timestamp"));

    // Check if the expiration time is a positive integer
    if (expiration_time <= 0) {
        return false;
    }

    // Check if the last activity timestamp is within a reasonable timeframe (not older than 15 minutes)
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);
    long int diff = now.tv_sec - last_activity_timestamp;
    if (diff > 900) { // 900 seconds = 15 minutes
        return false;
    }

    // Verify that the session is active and reliable by comparing timestamps with an external timestamp validation service
    json_object *response = json_object_new_string("{\"valid\": true}");
    bool valid = json_object_get_boolean(json_object_object_get(response, "valid"));
    if (!valid) {
        return false;
    }

    // Return true if all verification checks pass
    return true;
}
