using System;
using System.Data;
using System.IO;
using System.Threading.Tasks;

namespace MyProject {
    public static class FileProcessor {
        private const int CacheSize = 100;
        private static readonly object CacheLock = new object();
        private static Dictionary<string, Bitmap> ThemeCache = new Dictionary<string, Bitmap>();
        private static DirectoryInfo DefaultThemeDirectory = new DirectoryInfo("default_theme_directory");

        public static async Task<DataTableReader> ProcessFileAsync(byte[] fileContents) {
            // Check if the file is already in the cache
            string fileName = GetFileName(fileContents);
            Bitmap bitmap;
            lock (CacheLock) {
                if (!ThemeCache.TryGetValue(fileName, out bitmap)) {
                    // Load the theme from disk if not found in cache
                    bitmap = await LoadBitmapFromDiskAsync(fileName);
                    ThemeCache[fileName] = bitmap;
                }
            }

            // Process the file line by line and convert each line to a comma-separated format
            var lines = GetLines(fileContents);
            var result = new List<string>();
            foreach (var line in lines) {
                var values = GetValues(line);
                if (values.Length < 2) continue;
                double average = (double)values[values.Length - 1] + (double)values[values.Length - 2]) / 2;
                result.Add($"{string.Join(",", values)}{average}");
            }

            // Create a DataTableReader from the resulting data
            var table = new DataTable("Result");
            table.Columns.Add("Line", typeof(string));
            foreach (var line in result) {
                table.Rows.Add(line);
            }
            return table.CreateDataReader();
        }

        private static string GetFileName(byte[] fileContents) {
            using (var stream = new MemoryStream(fileContents)) {
                var reader = new StreamReader(stream);
                return reader.ReadLine().Split(',')[0];
            }
        }

        private static string[] GetLines(byte[] fileContents) {
            using (var stream = new MemoryStream(fileContents)) {
                var reader = new StreamReader(stream);
                return reader.ReadToEnd().Split('\n');
            }
        }

        private static int[] GetValues(string line) {
            return line.Split(',').Select(int.Parse).ToArray();
        }

        private async Task<Bitmap> LoadBitmapFromDiskAsync(string fileName) {
            // Try to load the theme from cache first
            Bitmap bitmap;
            if (ThemeCache.TryGetValue(fileName, out bitmap)) return bitmap;

            // If not found in cache, load it from disk and add to cache
            var filePath = Path.Combine(DefaultThemeDirectory.FullName, fileName);
            using (var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read)) {
                bitmap = await LoadBitmapAsync(stream);
                lock (CacheLock) {
                    ThemeCache[fileName] = bitmap;
                }
            }
            return bitmap;
        }

        private async Task<Bitmap> LoadBitmapAsync(Stream stream) {
            var image = new Bitmap(stream);
            // Perform any necessary image processing here
            return image;
        }
    }
}
```
