class InterfaceTable {
public:
  virtual string FindVmUuidFromMetadataIp(string metadataIp) = 0;
};

class TestDoubleInterfaceTable : public InterfaceTable {
public:
  string FindVmUuidFromMetadataIp(string metadataIp) override {
    // Implement your own logic for finding the VM UUID from metadata IP
    return "vm-uuid";
  }
};

class GraphManager {
private:
  adjacency_list<vecS, vecS, undirectedS> graph;
  TestDoubleInterfaceTable* interfaceTable;
  boost::property_map<adjacency_list<vecS, vecS, undirectedS>, std::string, std::string, edge_bundle_t>::type label;
  int numRequests = 0;
  int numProxySessions = 0;
  int numInternalErrors = 0;
  int numSuccessfulOperations = 0;

public:
  GraphManager(TestDoubleInterfaceTable* interfaceTable) {
    this->interfaceTable = interfaceTable;
  }

  void AddVertex(string metadataIp, vector<string> labels) {
    // Create a vertex with the given metadata IP and labels
    auto vmUuid = interfaceTable->FindVmUuidFromMetadataIp(metadataIp);
    graph.add_vertex(vmUuid, labels);
  }

  void AddEdge(string srcMetadataIp, string destMetadataIp) {
    // Create an edge between the vertices with the given metadata IPs
    auto srcVmUuid = interfaceTable->FindVmUuidFromMetadataIp(srcMetadataIp);
    auto destVmUuid = interfaceTable->FindVmUuidFromMetadataIp(destMetadataIp);
    graph.add_edge(srcVmUuid, destVmUuid);
  }

  void RemoveVertex(string metadataIp) {
    // Remove the vertex with the given metadata IP
    auto vmUuid = interfaceTable->FindVmUuidFromMetadataIp(metadataIp);
    graph.remove_vertex(vmUuid);
  }

  void RemoveEdge(string srcMetadataIp, string destMetadataIp) {
    // Remove the edge between the vertices with the given metadata IPs
    auto srcVmUuid = interfaceTable->FindVmUuidFromMetadataIp(srcMetadataIp);
    auto destVmUuid = interfaceTable->FindVmUuidFromMetadataIp(destMetadataIp);
    graph.remove_edge(srcVmUuid, destVmUuid);
  }

  void PrintMetrics() {
    cout << "Number of requests: " << numRequests << endl;
    cout << "Number of proxy sessions: " << numProxySessions << endl;
    cout << "Number of internal errors: " << numInternalErrors << endl;
    cout << "Number of successful operations: " << numSuccessfulOperations << endl;
  }
};']

