typedef struct {
    double celsius;
    double fahrenheit;
    char metadata[];
} TemperatureRecord;

// Function to manage dynamic memory allocation and initialization for an array of temperature records
void manageTemperatureRecords(char **files, int numFiles, int *numRecords) {
    // Initialize the array with a fixed size that can accommodate the maximum number of records from all files
    TemperatureRecord *records = malloc(sizeof(TemperatureRecord) * (*numRecords));
    if (!records) {
        perror("Error allocating memory for temperature records");
        return;
    }

    // Read temperature data from each file and add it to the array
    for (int i = 0; i < numFiles; i++) {
        FILE *file = fopen(files[i], "r");
        if (!file) {
            perror("Error opening file for reading");
            continue;
        }

        // Read each record from the file and add it to the array
        while (fscanf(file, "%lf,%lf%*[^\\n]", &records[(*numRecords)].celsius, &records[(*numRecords)].fahrenheit) == 2) {
            (*numRecords)++;
            if (*numRecords > records.size / sizeof(TemperatureRecord)) {
                // If the array is full, resize it by a fixed increment to accommodate more records
                records = realloc(records, (records.size + INCREMENT) * sizeof(TemperatureRecord));
                if (!records) {
                    perror("Error resizing memory for temperature records");
                    return;
                }
            }
        }

        // Close the file and handle any errors
        if (fclose(file) == EOF) {
            perror("Error closing file");
        }
    }

    // Print the array of temperature records for debugging purposes
    printf("Temperature Records:\n");
    for (int i = 0; i < *numRecords; i++) {
        printf("%.2f, %.2f\n", records[i].celsius, records[i].fahrenheit);
    }

    // Free the memory allocated for the array of temperature records
    free(records);
}
