void *manageDynamicResources(int num_records) {
    // Allocate memory for the arrays
    double *temperatures = (double *)malloc(num_records * sizeof(double));
    char *bytes = (char *)malloc(num_records * sizeof(char));
    struct Temperature *temperature_structs = (struct Temperature *)malloc(num_records * sizeof(struct Temperature));

    // Check for memory allocation errors
    if (!temperatures || !bytes || !temperature_structs) {
        fprintf(stderr, "Error allocating memory: %s\n", strerror(errno));
        return NULL;
    }

    // Read data from the file and populate the arrays
    FILE *file = fopen("temperatures.txt", "r");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return NULL;
    }

    // Loop through each record in the file and populate the arrays
    for (int i = 0; i < num_records; i++) {
        char buffer[256];
        if (fgets(buffer, sizeof(buffer), file)) {
            double celsius, fahrenheit;
            sscanf(buffer, "%lf %lf", &celsius, &fahrenheit);
            temperatures[i] = celsius;
            bytes[i] = (char)fahrenheit;
            temperature_structs[i].celsius = celsius;
            temperature_structs[i].fahrenheit = fahrenheit;
