// Define a struct to represent an array of integers
struct IntArray {
    int *data;
    int size;
};

// Define a function to read the input from standard input and store it in a dynamically allocated array
void readInput(int maxSize, struct IntArray *arr) {
    // Read the input from standard input
    char input[1024];
    fgets(input, 1024, stdin);

    // Tokenize the input and store it in a temporary array
    int tempSize = strlen(input) - 1; // Account for newline character
    int *tempArr = malloc(sizeof(int) * tempSize);
    if (tempArr == NULL) {
        printf("Error: Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }
    int i = 0;
    for (i = 0; i < tempSize; i++) {
        tempArr[i] = input[i] - '0';
    }

    // Check if the input size is greater than or equal to the maximum size limit
    if (tempSize >= maxSize) {
        printf("Error: Input size exceeds the maximum limit!\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the dynamic array and copy the temporary array to it
    arr->data = malloc(sizeof(int) * tempSize);
    if (arr->data == NULL) {
        printf("Error: Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }
    for (i = 0; i < tempSize; i++) {
        arr->data[i] = tempArr[i];
    }
    arr->size = tempSize;
}

// Define a function to determine the largest integer in an array
int findLargest(struct IntArray *arr) {
    int largest = INT_MIN;
    for (int i = 0; i < arr->size; i++) {
        if (arr->data[i] > largest) {
            largest = arr->data[i];
        }
    }
    return largest;
}

// Define a function to check for disjoint pairs of elements in an array using the Union-Find data structure
void checkDisjointPairs(struct IntArray *arr, int maxSize) {
    // Initialize the Union-Find structure with each element as its own set
    struct UFStruct {
        int *data;
        int size;
    };
    struct UFStruct uf = {{}, 0};
    for (int i = 0; i < maxSize; i++) {
        uf.data[i] = i;
        uf.size++;
    }

    // Loop through the array and check for disjoint pairs of elements
    for (int i = 0; i < arr->size - 1; i++) {
        int root1 = findRoot(uf, arr->data[i]);
        for (int j = i + 1; j < arr->size; j++) {
            int root2 = findRoot(uf, arr->data[j]);
            if (root1 == root2) {
                // If the two elements belong to the same set, print an error message
                printf("Error: Input contains disjoint pairs of elements!\n");
                break;
            } else {
                // If the two elements do not belong to the same set, merge them
                unionSets(uf, root1, root2);
            }
        }
    }
}

// Define a function to validate the input range of integers and filter out invalid inputs
void validateInputRange(struct IntArray *arr) {
    // Loop through the array and check for valid integer inputs
    for (int i = 0; i < arr->size; i++) {
        if (!isValidInteger(arr->data[i])) {
            // If an invalid integer is found, print an error message and exit the program
            printf("Error: Input contains invalid or malformed entries!\n");
            exit(EXIT_FAILURE);
        }
    }
}

// Define a function to handle memory allocation failures gracefully
void memAllocFail() {
    printf("Error: Memory allocation failed!\n");
    exit(EXIT_FAILURE);
}

int main(int argc, char *argv[]) {
    // Check if the maximum size limit has been provided as a command-line argument
    if (argc != 2) {
        printf("Error: No maximum size limit provided!\n");
        exit(EXIT_FAILURE);
    }

    // Convert the command-line argument to an integer and store it in maxSize
    int maxSize = atoi(argv[1]);
    if (maxSize <= 0) {
        printf("Error: Maximum size limit must be a positive integer!\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the struct to store the input array and read it from standard input
    struct IntArray arr;
    arr.data = NULL;
    arr.size = 0;
    readInput(maxSize, &arr);

    // Check if the input is empty
    if (arr.size == 0) {
        printf("Error: No input provided!\n");
        exit(EXIT_FAILURE);
    }

    // Determine the largest integer in the array and store it in largest
    int largest = findLargest(&arr);

    // Check for disjoint pairs of elements in the array using the Union-Find data structure
    checkDisjointPairs(&arr, maxSize);

    // Validate the input range of integers and filter out invalid inputs
    validateInputRange(&arr);

    // Print the output
    printf("Largest integer: %d\n", largest);

    return 0;
}

int isValidInteger(int num) {
    if (num >= INT_MIN && num <= INT_MAX) {
        return 1;
    } else {
        return 0;
    }
}

int findRoot(struct UFStruct uf, int element) {
    while (uf.data[element] != element) {
        // Path compression optimization: update the parent of the current element to its root
        uf.data[element] = uf.data[uf.data[element]];
        element = uf.data[element];
    }
    return element;
}

void unionSets(struct UFStruct uf, int element1, int element2) {
    // Find the roots of the two elements
    int root1 = findRoot(uf, element1);
    int root2 = findRoot(uf, element2);

    // If the two elements belong to the same set, merge them
    if (root1 != root2) {
        uf.data[root1] = root2;
        uf.size--;
    }
}']

