import java.awt.image.BufferedImage;
import java.io.File;
import java.util.ArrayList;
import java.util.List;

public class ImageProcessingPipeline {
    private List<Filter> filters = new ArrayList<>();
    private int currentIndex = 0;
    private boolean isInitialized = false;

    public void addFilter(Filter filter) {
        filters.add(filter);
    }

    public void init() {
        if (!isInitialized) {
            for (int i = 0; i < filters.size(); i++) {
                Filter filter = filters.get(i);
                filter.init();
            }
            isInitialized = true;
        }
    }

    public void applyFilters(BufferedImage image) {
        if (!isInitialized) {
            init();
        }
        for (int i = 0; i < filters.size(); i++) {
            Filter filter = filters.get(i);
            BufferedImage filteredImage = filter.applyFilter(image);
            image = filteredImage;
        }
    }

    public void reset() {
        currentIndex = 0;
    }

    public boolean hasNext() {
        return currentIndex < filters.size();
    }

    public Filter next() {
        if (!hasNext()) {
            return null;
        }
        Filter filter = filters.get(currentIndex);
        currentIndex++;
        return filter;
    }

    public void setFilterSettings(String filterName, Object... settings) {
        for (Filter filter : filters) {
            if (filter.getName().equals(filterName)) {
                filter.setSettings(settings);
            }
        }
    }

    public void saveResults(File outputDir) {
        // Save the processed image to a file in the specified directory
    }

    public String getSummary() {
        StringBuilder summary = new StringBuilder();
        for (Filter filter : filters) {
            summary.append(filter.getName()).append(": ").append(filter.getSettings());
        }
        return summary.toString();
    }
}

interface Filter {
    String getName();
    void init();
    BufferedImage applyFilter(BufferedImage image);
    void setSettings(Object... settings);
}

class GrayscaleFilter implements Filter {
    private double intensity = 0.5;

    @Override
    public String getName() {
        return "Grayscale";
    }

    @Override
    public void init() {
        // No initialization required
    }

    @Override
    public BufferedImage applyFilter(BufferedImage image) {
        BufferedImage filteredImage = new BufferedImage(image.getWidth(), image.getHeight(), image.getType());
        for (int i = 0; i < image.getWidth(); i++) {
            for (int j = 0; j < image.getHeight(); j++) {
                int color = image.getRGB(i, j);
                int red = (color >> 16) & 0xFF;
                int green = (color >> 8) & 0xFF;
                int blue = color & 0xFF;
                int gray = (int) (red * intensity + green * intensity + blue * intensity);
                filteredImage.setRGB(i, j, gray);
            }
        }
        return filteredImage;
    }

    @Override
    public void setSettings(Object... settings) {
        if (settings.length > 0 && settings[0] instanceof Double) {
            intensity = (Double) settings[0];
        }
    }
}

class EdgeDetectionFilter implements Filter {
