struct IntegerWithIndex {
    int value;
    size_t index;
};

// Define a comparison function for sorting the integers in ascending order
int compareIntegers(const void* a, const void* b) {
    struct IntegerWithIndex* ia = (struct IntegerWithIndex*)a;
    struct IntegerWithIndex* ib = (struct IntegerWithIndex*)b;
    return ia->value - ib->value;
}

// Define a function for finding the largest integer in an array of integers
void findLargestInteger(int* arr, size_t n) {
