import os
import hashlib
from threading import Lock

class FileHasher:
    def __init__(self, file_path, block_size=1024*1024):
        self.file_path = file_path
        self.block_size = block_size
        self.hash = hashlib.md5()
        self.progress = 0
        self.lock = Lock()

    def calculate_hash(self, skip_first=False):
        with open(self.file_path, "rb") as f:
            while True:
                data = f.read(self.block_size)
                if not data:
                    break
                self.lock.acquire()
                try:
                    if skip_first and self.progress < 10:
                        self.progress += 1
                        continue
                    self.hash.update(data)
                    self.progress += len(data)
                finally:
                    self.lock.release()
        return (self.hash.hexdigest(), self.progress)

