                            hasher.progress += 1
                            continue
                        hasher.hash.update(data)
                        hasher.progress += len(data)
                    finally:
                        hasher.lock.release()
                return (hasher.hash.hexdigest(), hasher.progress)
        except requests.exceptions.ConnectionError:
            # Implement retry mechanisms and fallback strategies to handle network-related issues
            pass
    return None
