#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdbool.h>
#include <stddef.h>
#include <assert.h>

// Structure to represent a power report indication
typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
} TX_POWER_REPORT_INDICATION_T;

// Structure to represent a cache of allocated memory for power report indications
typedef struct {
    TX_POWER_REPORT_INDICATION_T *memory;
    size_t capacity;
    size_t count;
} POWER_REPORT_CACHE_T;

// Structure to represent a database of allocated RNTIs
typedef struct {
    uint32_t *rnti_db;
    size_t capacity;
    size_t count;
} RNTI_DB_T;

// Function to allocate memory for the power report indication cache and initialize it with a given number of structures
POWER_REPORT_CACHE_T *power_report_cache_alloc(size_t num_structures) {
    // Allocate memory for the power report indication cache
    POWER_REPORT_CACHE_T *cache = (POWER_REPORT_CACHE_T *)malloc(sizeof(POWER_REPORT_CACHE_T));
    if (!cache) {
        return NULL;
    }

    // Allocate memory for the power report indications themselves
    cache->memory = (TX_POWER_REPORT_INDICATION_T *)malloc(num_structures * sizeof(TX_POWER_REPORT_INDICATION_T));
    if (!cache->memory) {
        free(cache);
        return NULL;
    }

    // Initialize the cache's capacity and count
    cache->capacity = num_structures;
    cache->count = 0;

    return cache;
}

// Function to deallocate memory for a power report indication cache
void power_report_cache_free(POWER_REPORT_CACHE_T *cache) {
    if (!cache) {
        return;
    }

    // Deallocate the memory for the power report indications themselves
    free(cache->memory);

    // Deallocate the cache structure itself
    free(cache);
}

// Function to allocate a new RNTI value from the database and add it to the cache
uint32_t alloc_rnti(POWER_REPORT_CACHE_T *cache, RNTI_DB_T *db) {
    // If there is space in the cache, allocate a new RNTI value from the database and add it to the cache
    if (cache->count < cache->capacity) {
        uint32_t rnti = db->rnti_db[db->count++];
        cache->memory[cache->count++].rnti = rnti;
        return rnti;
    }

    // If there is no space in the cache, allocate a new RNTI value from the database and add it to the cache
    uint32_t rnti = db->rnti_db[db->count++];
    cache->memory[cache->count - 1].rnti = rnti;
    return rnti;
}

// Function to free an RNTI value from the cache and add it back to the database
void free_rnti(uint32_t rnti, POWER_REPORT_CACHE_T *cache, RNTI_DB_T *db) {
    // If there are any structures in the cache with the given RNTI value, remove them and add them back to the database
    size_t i;
    for (i = 0; i < cache->count; i++) {
        if (cache->memory[i].rnti == rnti) {
            break;
        }
    }
    if (i < cache->count) {
        TX_POWER_REPORT_INDICATION_T tmp = cache->memory[i];
        memmove(&cache->memory[i], &cache->memory[i + 1], sizeof(TX_POWER_REPORT_INDICATION_T) * (cache->count - i - 1));
        db->rnti_db[--db->count] = tmp.rnti;
    }
}

// Function to generate a random CRC flag value
uint8_t crc_flag(void) {
    return (uint8_t)(rand() % 256);
}

// Function to populate the power report indications with RNTIs and CRC flags
TX_POWER_REPORT_INDICATION_T *populate_power_report_indications(size_t num_structures, POWER_REPORT_CACHE_T *cache, RNTI_DB_T *db) {
    // Allocate memory for the power report indications
    TX_POWER_REPORT_INDICATION_T *indications = (TX_POWER_REPORT_INDICATION_T *)malloc(num_structures * sizeof(TX_POWER_REPORT_INDICATION_T));
    if (!indications) {
        return NULL;
    }

    // Populate the power report indications with RNTIs and CRC flags
    size_t i;
    for (i = 0; i < num_structures; i++) {
        uint32_t rnti = alloc_rnti(cache, db);
        indications[i].rx_ue_information_tag = (uint16_t)(rand() % UINT16_MAX);
        indications[i].rnti = rnti;
        indications[i].crc_indication_rel8_tag = crc_flag();
    }

    return indications;
}

// Function to deallocate memory for power report indications
void free_power_report_indications(TX_POWER_REPORT_INDICATION_T *indications, size_t num_structures) {
    // Deallocate the memory for the power report indications
    free(indications);
}

// Function to create a new RNTI database and populate it with values
RNTI_DB_T *create_rnti_db(size_t num_values) {
    // Allocate memory for the RNTI database
    RNTI_DB_T *db = (RNTI_DB_T *)malloc(sizeof(RNTI_DB_T));
    if (!db) {
        return NULL;
    }

    // Populate the RNTI database with values
    size_t i;
    for (i = 0; i < num_values; i++) {
        db->rnti_db[i] = (uint32_t)(rand() % UINT32_MAX);
    }

    return db;
}

// Function to deallocate memory for an RNTI database
void free_rnti_db(RNTI_DB_T *db) {
    // Deallocate the memory for the RNTI database
    free(db);
}

int main() {
    // Set the number of power report indications to allocate
    size_t num_structures = 10;

    // Allocate memory for the power report indication cache and RNTI database
    POWER_REPORT_CACHE_T *cache = power_report_cache_init(num_structures);
    RNTI_DB_T *db = create_rnti_db(UINT32_MAX);

    // Populate the power report indications with RNTIs and CRC flags
    TX_POWER_REPORT_INDICATION_T *indications = populate_power_report_indications(num_structures, cache, db);

    // Display the populated power report indications
    size_t i;
    for (i = 0; i < num_structures; i++) {
        printf("%d: rnti=%d, crc_indication_rel8_tag=%d\n", i, indications[i].rnti, indications[i].crc_indication_rel8_tag);
    }

    // Free the memory for the power report indications and RNTI database
    free_power_report_indications(indications, num_structures);
    free_rnti_db(db);

    return 0;
}
