        readings[i].humidity = 0.0f;
        readings[i].reliability = false;
    }

    // Collect readings from multiple sensors over the network connection
    for (i = 0; i < numReadings; i++) {
        struct sensorData data;
        bool success = getSensorData(&conn, &data);
        if (!success) {
            logError("Failed to retrieve sensor data");
            continue;
        }
