dataPoint* allocateDataPoints(size_t size, float min_value, float max_value, time_t initial_timestamp, unsigned int concurrency) {
    // Check for zero-sized arrays or invalid input parameters
    if (size == 0 || min_value > max_value) {
        return NULL;
    }

    // Calculate the number of data points to allocate based on the concurrency level
    size_t num_data_points = size * concurrency;

    // Allocate memory for the array of dataPoints
    dataPoint* data_points = (dataPoint*)malloc(num_data_points * sizeof(dataPoint));
    if (!data_points) {
        return NULL;
    }

    // Initialize metadata fields for each data point
    time_t current_timestamp = initial_timestamp;
    unsigned int sequence_number = 0;
    for (size_t i = 0; i < num_data_points; ++i) {
        data_points[i].timestamp = current_timestamp++;
        data_points[i].value = min_value + (float)(rand() % (max_value - min_value));
        data_points[i].validity = true;
        data_points[i].ref_count = 0;
        data_points[i].last_modified = initial_timestamp;
    }

    // Log allocation and initialization of the array in external logging service
    logAllocation(data_points, num_data_points);

    return data_points;
}

