    logUpdate(data_point);
}

// Function to retrieve a data point based on its timestamp
dataPoint* getDataPointByTimestamp(dataPoint* data_points, size_t num_data_points, time_t timestamp) {
    // Check for zero-sized arrays or invalid input parameters
    if (num_data_points == 0 || timestamp < 0) {
        return NULL;
    }

    // Binary search to find the data point with the matching timestamp
    size_t low = 0, high = num_data_points - 1;
    while (low <= high) {
        size_t mid = (low + high) / 2;
        if (data_points[mid].timestamp == timestamp) {
            return &data_points[mid];
        } else if (data_points[mid].timestamp < timestamp) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    // If the timestamp is not found, return NULL
    return NULL;
}

