// Define a structure to represent a system process information
typedef struct {
    int process_id;
    PROCESS_STATUS_T status;
    time_t timestamp;
} SYSTEM_PROCESS_INFO;

// Define a hash map to quickly identify duplicate PROCESS_IDs
#define HASH_MAP_SIZE 1024
struct {
    int *process_ids;
    size_t count;
} process_id_map = {NULL, 0};

// Function to manage the dynamic list of SYSTEM_PROCESS_INFO structures
int create_system_process(SYSTEM_PROCESS_INFO **processes, int n) {
    // Allocate memory for the processes array
    *processes = malloc(n * sizeof(**processes));
    if (*processes == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    // Initialize the hash map for duplicate PROCESS_ID detection
    process_id_map.process_ids = calloc(HASH_MAP_SIZE, sizeof(*process_id_map.process_ids));
    if (process_id_map.process_ids == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    // Populate the processes array with unique PROCESS_IDs and statuses
    for (int i = 0; i < n; i++) {
        int process_id;
        PROCESS_STATUS_T status = get_random_process_status();

        // Generate a new PROCESS_ID until it is unique
        do {
            process_id = generate_unique_process_id(i);
        } while (check_duplicate_process_id(process_id));

        (*processes)[i].process_id = process_id;
        (*processes)[i].status = status;
        (*processes)[i].timestamp = time(NULL);
    }

    // Free the hash map when no longer needed
    pthread_mutex_lock(&process_id_map.mutex);
    if (--process_id_map.count == 0) {
        free(process_id_map.process_ids);
    }
    pthread_mutex_unlock(&process_id_map.mutex);

    return n;
}

// Function to check if a PROCESS_ID has already been used in the current session
int check_duplicate_process_id(int process_id) {
    pthread_mutex_lock(&process_id_map.mutex);
    int *found = process_id_map.process_ids[process_id];
    pthread_mutex_unlock(&process_id_map.mutex);

    return found != NULL;
}

// Function to generate a unique PROCESS_ID for a new system process
int generate_unique_process_id(int index) {
    int process_id = (index % HASH_MAP_SIZE) + 1;
    while (check_duplicate_process_id(process_id)) {
        process_id++;
        if (process_id > HASH_MAP_SIZE) {
            process_id = 1;
        }
    }

    return process_id;
}

// Function to get a random process status for a new system process
PROCESS_STATUS_T get_random_process_status() {
    int status = rand() % (NUM_STATUSES - 1);
    return status;
}
