    if (fp == NULL) {
        printf("Error: unable to open file %s\n", path);
        return NULL;
    }

    // Allocate memory for the array of records and initialize it
    Record *records = malloc(sizeof(Record) * 1024);
    if (records == NULL) {
        printf("Error: unable to allocate memory for records\n");
        fclose(fp);
        return NULL;
    }
    memset(records, 0, sizeof(Record) * 1024);

    // Allocate memory for the array of offsets and initialize it
    long *offsets = malloc(sizeof(long) * 1024);
    if (offsets == NULL) {
        printf("Error: unable to allocate memory for offsets\n");
        free(records);
        fclose(fp);
        return NULL;
    }
    memset(offsets, 0, sizeof(long) * 1024);

    // Allocate memory for the array of integers and initialize it
    int *keys = malloc(sizeof(int) * 1024);
    if (keys == NULL) {
        printf("Error: unable to allocate memory for keys\n");
        free(records);
        free(offsets);
        fclose(fp);
        return NULL;
    }
    memset(keys, 0, sizeof(int) * 1024);

    // Initialize the progress indicator
    int progress = 0;

    // Read the file in chunks and compute the MD5 hash for each chunk
    while (!feof(fp)) {
        // Read a chunk of the file into memory
        char *chunk = malloc(1024);
        if (chunk == NULL) {
            printf("Error: unable to allocate memory for chunk\n");
            free(records);
            free(offsets);
            free(keys);
            fclose(fp);
            return NULL;
