        size_t nread = fread(chunk, 1, 1024, fp);

        // Compute the MD5 hash for the chunk
        unsigned char md5[MD5_DIGEST_LENGTH];
        MD5((unsigned char *)chunk, nread, md5);

        // Store the offset and key values for each record in the array of records
        for (int i = 0; i < nread; i++) {
            Record *record = &records[progress + i];
            record->offset = offsets[progress + i] = ftell(fp) - nread + i;
            record->key = keys[progress + i] = rand() % 1024;
        }

        // Update the progress indicator
        progress += nread;
    }

    // Close the file
    fclose(fp);

    // Compute the MD5 hash of the entire file
    unsigned char md5_file[MD5_DIGEST_LENGTH];
    MD5((unsigned char *)offsets, sizeof(long) * 1024, md5_file);

    // Free memory for the arrays of records, offsets, and keys
    free(records);
    free(offsets);
    free(keys);

    // Return the hexadecimal representation of the MD5 hash and the array of records
    char *md5_hex = malloc(MD5_DIGEST_LENGTH * 2 + 1);
    if (md5_hex == NULL) {
