    size_t num_records; // Number of records in the array
} DataStructure;

// Function to initialize a new record with the given key, offset, and string
Record* create_record(int key, long offset, const char* string) {
    Record* record = malloc(sizeof(Record));
    if (!record) {
        return NULL; // Memory allocation failed
    }

    record->key = key;
    record->offset = offset;
    record->string = strdup(string); // Copy the string
    if (!record->string) {
        free(record); // Free the record if the string copy fails
        return NULL;
    }

    return record;
}

// Function to insert a new record into the data structure
int insert_record(DataStructure* ds, Record* record) {
    pthread_mutex_lock(&ds->mutex); // Lock the mutex before modifying the data structure
    if (ds->num_records == ds->size) { // If the array is full, resize it
        size_t new_size = ds->size * 2;
        Record** new_records = realloc(ds->records, new_size * sizeof(Record*));
        if (!new_records) {
            pthread_mutex_unlock(&ds->mutex); // Unlock the mutex and return an error code
            free(record); // Free the record that was created but not inserted
            return -1; // Memory allocation failed
        }
        ds->records = new_records;
        ds->size = new_size;
    }

    // Add the new record to the end of the array and increase the number of records
    ds->records[ds->num_records] = record;
    ds->num_records++;

    pthread_mutex_unlock(&ds->mutex); // Unlock the mutex
    return 0; // Success
}

// Function to retrieve a record from the data structure using its key
Record* get_record(DataStructure* ds, int key) {
    pthread_mutex_lock(&ds->mutex); // Lock the mutex before modifying the data structure

    for (size_t i = 0; i < ds->num_records; i++) {
        if (ds->records[i]->key == key) {
            pthread_mutex_unlock(&ds->mutex); // Unlock the mutex and return the record
            return ds->records[i];
        }
    }

    pthread_mutex_unlock(&ds->mutex); // Unlock the mutex and return NULL if no matching record is found
    return NULL;
}

// Function to delete a record from the data structure using its key
int delete_record(DataStructure* ds, int key) {
    pthread_mutex_lock(&ds->mutex); // Lock the mutex before modifying the data structure

    for (size_t i = 0; i < ds->num_records; i++) {
        if (ds->records[i]->key == key) {
            Record* record = ds->records[i];
            free(record->string); // Free the string allocated by create_record()
            free(record); // Free the record
            ds->num_records--; // Decrease the number of records
            memmove(&ds->records[i], &ds->records[i + 1], (ds->num_records - i) * sizeof(Record*)); // Shift the remaining records down
            break;
        }
    }

    pthread_mutex_unlock(&ds->mutex); // Unlock the mutex
    return 0; // Success
}
