int is_session_id_in_use(int session_id) {
    // Lock the mutex to prevent race conditions when checking the map
    pthread_mutex_lock(&session_id_map_mutex);

    // Check if the given session ID is already in use
    int in_use = (session_id_map.find(session_id) != session_id_map.end());

    // Unlock the mutex
    pthread_mutex_unlock(&session_id_map_mutex);

    return in_use;
}

// Function to allocate a new unique session ID
int alloc_unique_session_id() {
    int session_id = 0;

    // Lock the mutex to prevent race conditions when populating the map
    pthread_mutex_lock(&session_id_map_mutex);

    // Loop until a unique session ID is found or a timeout occurs
    while (is_session_id_in_use(session_id)) {
        session_id++;
        if (session_id > MAX_SESSION_ID) {
            break;
        }
    }

    // If a unique session ID was found, add it to the map
    if (session_id <= MAX_SESSION_ID) {
        session_id_map.insert(std::make_pair(session_id, true));
    }

    // Unlock the mutex
    pthread_mutex_unlock(&session_id_map_mutex);

    return session_id;
}

// Function to deallocate a USER_CONNECTION_RECORD_T structure
void dealloc_connection(USER_CONNECTION_RECORD_T *conn) {
    // Lock the mutex to prevent race conditions when accessing the map
    pthread_mutex_lock(&session_id_map_mutex);

    // Remove the session ID from the map
    session_id_map.erase(conn->session_id);

    // Unlock the mutex
    pthread_mutex_unlock(&session_id_map_mutex);

    // Free the memory for the structure
    free(conn);
}

