    for (int i = 0; i < n; i++) {
        int session_id = alloc_unique_session_id();
        if (session_id == -1) {
            break;
        }

        connections[i] = alloc_connection(session_id);
    }

    // Loop through the array and deallocate structures that have been deallocated
