// Struct to represent a record in the array of records
struct Record {
    int key; // Key for the record
    uint8_t hash[SHA256_DIGEST_LENGTH]; // SHA-256 hash value for the record
};

// Function to dynamically manage memory and compute SHA-256 hash of a file
int hashFile(const char* path, struct Record** records, int* numRecords, bool useFixedSizeBuffer) {
    // Check if file exists and is accessible
    if (access(path, F_OK | R_OK)) {
        printf("Error: File %s does not exist or is not accessible\n", path);
        return -1;
    }

    // Open the file for reading
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        printf("Error: Could not open file %s\n", path);
        return -1;
    }

    // Get the file size
    struct stat st;
    fstat(fd, &st);
    off_t fileSize = st.st_size;

    // Determine how many records to allocate based on the file size
    *numRecords = (int)ceil((double)fileSize / SHA256_BUFFER_SIZE);

    // Allocate memory for the array of records
    *records = (struct Record*)malloc(*numRecords * sizeof(struct Record));
    if (*records == NULL) {
        printf("Error: Could not allocate memory for %d records\n", *numRecords);
        return -1;
    }

    // Initialize the array of records with keys and hash values
    int i;
    for (i = 0; i < *numRecords; i++) {
        (*records)[i].key = i;
        memset((*records)[i].hash, 0x0, SHA256_DIGEST_LENGTH);
    }

    // Compute the hash value for each record
    uint8_t buffer[SHA256_BUFFER_SIZE];
    off_t offset = 0;
    int chunkSize;
    while (offset < fileSize) {
        if (fileSize - offset > SHA256_BUFFER_SIZE) {
            chunkSize = SHA256_BUFFER_SIZE;
        } else {
            chunkSize = (int)(fileSize - offset);
        }

        ssize_t bytesRead = read(fd, buffer, chunkSize);
        if (bytesRead < 0) {
            printf("Error: Could not read from file %s\n", path);
            return -1;
        } else if (bytesRead == 0) {
            break;
        }

        // Compute the hash value for the current chunk
        SHA256_CTX shaCtx;
        SHA256_Init(&shaCtx);
        SHA256_Update(&shaCtx, buffer, bytesRead);
        SHA256_Final((*records)[i].hash, &shaCtx);

        offset += chunkSize;
    }

    // Close the file descriptor
    close(fd);

    return 0;
}

// Function to release allocated resources upon completion or termination
void cleanup(struct Record** records) {
    if (*records != NULL) {
        free(*records);
        *records = NULL;
    }
}
