// Memory pool for reusing SYSTEM_PROCESS_INFO structures
#define MEMORY_POOL_SIZE 1024 // Size of the memory pool in bytes
static SYSTEM_PROCESS_INFO *memory_pool = NULL;
static size_t memory_pool_index = 0;

// Duplicate PROCESS_ID detection mechanism
#define MAX_DUPLICATE_CHECKS 10 // Maximum number of duplicate checks per process ID
static int duplicate_checks[MAX_DUPLICATE_CHECKS];

void allocate_process(size_t n) {
    if (n > MEMORY_POOL_SIZE) {
        // Reallocate the memory pool to handle a larger number of processes
        memory_pool = realloc(memory_pool, n * sizeof(SYSTEM_PROCESS_INFO));
        if (!memory_pool) {
            // Handle out-of-memory error
            return;
        }
    }
    for (size_t i = 0; i < n; i++) {
        SYSTEM_PROCESS_INFO *process = &memory_pool[i];
        process->process_id = generate_unique_process_id();
        process->status = generate_random_process_status();
        process->timestamp = time(NULL);
    }
}

int generate_unique_process_id() {
    int process_id;
    size_t duplicate_checks_index = 0;
    do {
        // Generate a new PROCESS_ID and check for duplicates
        process_id = rand();
        for (size_t i = 0; i < MAX_DUPLICATE_CHECKS; i++) {
            if (duplicate_checks[i] == process_id) {
                // Found a duplicate, generate a new PROCESS_ID
                process_id = rand();
                break;
            }
        }
        // Add the generated PROCESS_ID to the duplicate check list
        duplicate_checks[duplicate_checks_index++] = process_id;
    } while (duplicate_checks_index < MAX_DUPLICATE_CHECKS);
    return process_id;
}

PROCESS_STATUS_T generate_random_process_status() {
    // Generate a random PROCESS_STATUS_T value
    int status = rand();
    return (PROCESS_STATUS_T)status;
}

void deallocate_process(size_t n) {
    if (n > MEMORY_POOL_SIZE) {
        // Reallocate the memory pool to handle a smaller number of processes
        memory_pool = realloc(memory_pool, n * sizeof(SYSTEM_PROCESS_INFO));
        if (!memory_pool) {
            // Handle out-of-memory error
            return;
        }
    }
    for (size_t i = 0; i < n; i++) {
        SYSTEM_PROCESS_INFO *process = &memory_pool[i];
        process->process_id = -1; // Mark the process as deallocated
        process->status = PROCESS_STATUS_T::NONE;
    }
}
