#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <assert.h>

// A structure to represent each item in the collection
typedef struct {
  int id; // unique identifier for the item
  char *name; // dynamically allocated string for the name of the item
  int quantity; // integer value for the quantity of the item
} Item;

// A hash table to store all items in the collection, using a linked list as the bucket implementation
typedef struct {
  Item **items; // array of pointers to items
  size_t capacity; // current capacity of the hash table
  size_t size; // number of items stored in the hash table
} HashTable;

// A function to create a new item with the given id and name
Item* new_item(int id, char *name) {
  Item *item = malloc(sizeof(Item));
  assert(item != NULL);
  item->id = id;
  item->name = strdup(name);
  item->quantity = rand() % 100 + 1; // random integer between 1 and 100
  return item;
}

// A function to insert a new item into the hash table
void insert_item(HashTable *table, Item *item) {
  assert(table != NULL);
  assert(item != NULL);

  // check if the table needs to be resized
  if (table->size >= table->capacity) {
    resize_table(table);
  }

  // insert the item into the hash table
  int index = hash(item->id);
  Item *head = table->items[index];
  Item **prev = &head;
  while (*prev != NULL && (*prev)->id < item->id) {
    prev = &((*prev)->next);
  }
  item->next = *prev;
  *prev = item;

  // increment the size of the table
  table->size++;
}

// A function to remove an item from the hash table
void remove_item(HashTable *table, int id) {
  assert(table != NULL);

  // find the index of the item in the hash table
  int index = hash(id);

  // check if the item exists in the hash table
  Item **prev = &table->items[index];
  while (*prev != NULL && (*prev)->id != id) {
    prev = &((*prev)->next);
  }

  // remove the item from the linked list
  if (*prev != NULL) {
    Item *item = *prev;
    *prev = item->next;

    // decrement the size of the table
    table->size--;

    // free the memory allocated for the item
    free(item->name);
    free(item);
  }
}

// A function to update an item in the hash table
void update_item(HashTable *table, Item *item) {
  assert(table != NULL);
  assert(item != NULL);

  // find the index of the item in the hash table
  int index = hash(item->id);

  // check if the item exists in the hash table
  Item **prev = &table->items[index];
  while (*prev != NULL && (*prev)->id != item->id) {
    prev = &((*prev)->next);
  }

  // update the item in the linked list
  if (*prev != NULL) {
    Item *item = *prev;
    item->quantity = rand() % 100 + 1; // random integer between 1 and 100
  }
}

// A function to search for an item in the hash table by its id
Item* find_item(HashTable *table, int id) {
  assert(table != NULL);

  // find the index of the item in the hash table
  int index = hash(id);

  // check if the item exists in the hash table
  Item **prev = &table->items[index];
  while (*prev != NULL && (*prev)->id != id) {
    prev = &((*prev)->next);
  }

  return *prev;
}

// A function to resize the hash table when it needs to be resized
void resize_table(HashTable *table) {
  assert(table != NULL);

  // create a new hash table with twice the capacity of the current one
  HashTable new_table;
  new_table.items = malloc(2 * table->capacity * sizeof(Item*));
  assert(new_table.items != NULL);
  new_table.capacity = 2 * table->capacity;

  // copy all items from the old hash table to the new one
  for (int i = 0; i < table->capacity; i++) {
    Item **prev = &table->items[i];
    while (*prev != NULL) {
      int index = hash((*prev)->id);
      Item *head = new_table.items[index];
      Item **next = &head;
      while (*next != NULL && (*next)->id < (*prev)->id) {
        next = &((*next)->next);
      }
      (*prev)->next = *next;
      *next = *prev;
      prev = &((*prev)->next);
    }
  }

  // free the memory allocated for the old hash table
  free(table->items);

  // update the size and capacity of the new hash table
  table->size = new_table.size;
  table->capacity = new_table.capacity;
}

// A function to compute the hash value for an item id
int hash(int id) {
  return id % (sizeof(HashTable) / sizeof(Item*));
}

// A function to allocate memory for a new hash table and initialize its size and capacity
HashTable *init_table() {
  HashTable *table = malloc(sizeof(HashTable));
  assert(table != NULL);
  table->items = malloc(100 * sizeof(Item*));
  assert(table->items != NULL);
  table->capacity = 100;
  table->size = 0;
  return table;
}

// A function to deallocate memory for a hash table and all its items
void destroy_table(HashTable *table) {
  assert(table != NULL);

  // free the memory allocated for each item in the hash table
  for (int i = 0; i < table->capacity; i++) {
    Item **prev = &table->items[i];
    while (*prev != NULL) {
      Item *item = *prev;
      free(item->name);
      free(item);
      prev = &((*prev)->next);
    }
  }

  // free the memory allocated for the hash table itself
  free(table->items);
  free(table);
}
```
This code creates a simple hash table that can store and retrieve items by their ids. It uses a linked list to store the items in each bucket of the hash table, so that it can handle collisions efficiently. The `init_table` function allocates memory for the hash table and initializes its size and capacity. The `destroy_table` function deallocates memory for the hash table and all its items. The `insert` function inserts a new item into the hash table, and the `remove` function removes an item from the hash table. The `find` function searches for an item in the hash table by its id. The `update` function updates an item in the hash table. The `resize_table` function resizes the hash table when it needs to be resized.

In this code, we use the `assert` macro to check whether the memory allocation was successful before using the allocated memory. We also use the `sizeof` operator to compute the size of a data structure in bytes, which helps us to allocate enough memory for the hash table and its items. We use the `%` operator to compute the hash value for an item id, which is used to determine the index of the bucket where the item should be stored.

Note that this code is just a simple example of how you can implement a hash table in C, and it may not be suitable for production use. For example, it does not handle collisions efficiently, and it does not provide any error handling or recovery mechanisms. It also uses a linked list to store the items in each bucket, which can be inefficient if there are many collisions.

In practice, you may want to use a different data structure to store the items in each bucket, such as an array or a vector, and implement collision resolution techniques such as chaining or open addressing. You may also want to provide error handling and recovery mechanisms to handle unexpected inputs or errors gracefully.']

