// A structure to represent an item in the collection
typedef struct {
    int id;
    char *name;
    int quantity;
} Item;

// The dynamic array of pointers to items
static Item **items = NULL;

// The number of items currently stored in the collection
static size_t num_items = 0;

// The maximum capacity of the collection
#define MAX_CAPACITY 10000

// The total allocated memory size for the collection
static size_t total_allocated_size = 0;

// Memory pool for allocating and deallocating memory efficiently
static char *memory_pool = NULL;

// Log file for maintaining detailed logs of memory allocation and deallocation events
FILE *log_file = NULL;

// Initialize the collection with an initial capacity of 1,000 items
void init_collection() {
    // Allocate memory for the dynamic array of pointers to items
    items = malloc(MAX_CAPACITY * sizeof(Item *));
    assert(items != NULL);
    total_allocated_size += MAX_CAPACITY * sizeof(Item *);

    // Initialize each item in the collection with a unique identifier, name, and quantity
    for (int i = 0; i < MAX_CAPACITY; i++) {
        items[i] = malloc(sizeof(Item));
        assert(items[i] != NULL);
        total_allocated_size += sizeof(Item);
        items[i]->id = i + 1;
        items[i]->name = NULL;
        items[i]->quantity = 0;
    }

    // Allocate memory for the memory pool and initialize it with a fixed size of 1 MB
    memory_pool = malloc(1024 * 1024);
    assert(memory_pool != NULL);
    total_allocated_size += 1024 * 1024;
}

// Add an item to the collection, with a unique identifier, name, and quantity
void add_item(int id, char *name, int quantity) {
    // Check if the number of items exceeds the maximum capacity of the collection
    if (num_items == MAX_CAPACITY) {
        // Resize the dynamic array of pointers to items by doubling its capacity
        Item **new_items = realloc(items, 2 * MAX_CAPACITY * sizeof(Item *));
        assert(new_items != NULL);
        total_allocated_size += 2 * MAX_CAPACITY * sizeof(Item *);
        items = new_items;
    }

    // Allocate memory for the item's name and initialize it with the given value
    size_t len = strlen(name) + 1;
    char *new_name = malloc(len);
    assert(new_name != NULL);
    total_allocated_size += len;
    memcpy(new_name, name, len);

    // Add the item to the collection at its next available index
    Item *new_item = malloc(sizeof(Item));
    assert(new_item != NULL);
    total_allocated_size += sizeof(Item);
    items[num_items] = new_item;
    new_item->id = id;
    new_item->name = new_name;
    new_item->quantity = quantity;

    // Increment the number of items in the collection
    num_items++;
}

// Get an item from the collection by its unique identifier, or NULL if not found
Item *get_item(int id) {
    for (int i = 0; i < num_items; i++) {
        if (items[i]->id == id) {
            return items[i];
        }
    }
    return NULL;
}

// Update an item's quantity in the collection, or add it if not found
void update_item(int id, int quantity) {
    // Get the item from the collection by its unique identifier
    Item *item = get_item(id);
    if (item != NULL) {
        // Update the item's quantity in the collection
        item->quantity = quantity;
    } else {
        // Add a new item to the collection with the given unique identifier, name, and quantity
        add_item(id, "default", quantity);
    }
}

// Serialize the collection of items to a binary file for persistence
void serialize_collection() {
    // Open the log file for writing and maintaining detailed logs of memory allocation and deallocation events
    log_file = fopen("log.txt", "a");
    assert(log_file != NULL);

    // Write the number of items in the collection to the binary file
    size_t num_items_size = sizeof(num_items);
    fwrite(&num_items, 1, num_items_size, log_file);

    // Serialize each item in the collection to the binary file
    for (int i = 0; i < num_items; i++) {
        Item *item = items[i];
        size_t id_size = sizeof(item->id);
        fwrite(&item->id, 1, id_size, log_file);

        size_t name_size = strlen(item->name) + 1;
        fwrite(item->name, 1, name_size, log_file);

        size_t quantity_size = sizeof(item->quantity);
        fwrite(&item->quantity, 1, quantity_size, log_file);
    }

    // Close the log file and maintain detailed logs of memory allocation and deallocation events
    fclose(log_file);
}

// Deserialize the collection of items from a binary file for persistence
void deserialize_collection() {
    // Open the log file for reading and maintaining detailed logs of memory allocation and deallocation events
    log_file = fopen("log.txt", "r");
    assert(log_file != NULL);

    // Read the number of items in the collection from the binary file
    size_t num_items_size = sizeof(num_items);
    fread(&num_items, 1, num_items_size, log_file);

    // Deserialize each item in the collection from the binary file
    for (int i = 0; i < num_items; i++) {
        Item *item = malloc(sizeof(Item));
        assert(item != NULL);
        total_allocated_size += sizeof(Item);

        size_t id_size = sizeof(item->id);
        fread(&item->id, 1, id_size, log_file);

        size_t name_size = strlen(item->name) + 1;
        char *new_name = malloc(name_size);
        assert(new_name != NULL);
        total_allocated_size += name_size;
        memcpy(new_name, item->name, name_size);

        size_t quantity_size = sizeof(item->quantity);
        fread(&item->quantity, 1, quantity_size, log_file);
    }

    // Close the log file and maintain detailed logs of memory allocation and deallocation events
    fclose(log_file);
}

// Free all memory allocated by the collection of items
void free_collection() {
    for (int i = 0; i < num_items; i++) {
        Item *item = items[i];
        free(item->name);
        free(item);
    }
