// Define the structure to store network connection information
typedef struct {
    int CONNECTION_ID;
    int CONNECTION_STATE;
    char* sourceIP;
    char* destIP;
    time_t timestamp;
} NETWORK_CONNECTION_INFO;

// Define the hash map to quickly identify duplicate CONNECTION_IDs
typedef struct {
    int CONNECTION_ID;
    bool isDuplicate;
} CONNECTION_ID_MAP;

// Initialize a memory pool for reuse of NETWORK_CONNECTION_INFO structures
NETWORK_CONNECTION_INFO* connectionInfoPool = NULL;
int connectionInfoPoolSize = 0;
int connectionInfoIndex = -1;

// Function to allocate and populate a new network connection information structure
NETWORK_CONNECTION_INFO* createNetworkConnectionInfo(void) {
    // Check if the memory pool is empty and needs to be replenished
    if (connectionInfoPool == NULL || connectionInfoIndex >= connectionInfoPoolSize - 1) {
        // Replenish the memory pool with new structures
        connectionInfoPool = realloc(connectionInfoPool, (++connectionInfoPoolSize) * sizeof(NETWORK_CONNECTION_INFO));
    }

    // Increment the index to the next available structure in the pool
    ++connectionInfoIndex;

    NETWORK_CONNECTION_INFO* connectionInfo = &connectionInfoPool[connectionInfoIndex];

    // Generate a unique CONNECTION_ID and check if it has already been used
    int newConnectionId = generateUniqueConnectionId();
    while (isDuplicateConnectionId(newConnectionId)) {
        newConnectionId = generateUniqueConnectionId();
    }

    connectionInfo->CONNECTION_ID = newConnectionId;
    connectionInfo->CONNECTION_STATE = generateRandomConnectionState();
    connectionInfo->sourceIP = generateRandomSourceIpAddress();
    connectionInfo->destIP = generateRandomDestinationIpAddress();
    connectionInfo->timestamp = time(NULL);

    return connectionInfo;
}

// Function to free a network connection information structure and add it back to the memory pool
void freeNetworkConnectionInfo(NETWORK_CONNECTION_INFO* connectionInfo) {
    // Check if the memory pool is full and needs to be shrunk
    if (connectionInfoPool == NULL || connectionInfoIndex < 0) {
        // Shrink the memory pool by one structure
        connectionInfoPool = realloc(connectionInfoPool, --connectionInfoPoolSize * sizeof(NETWORK_CONNECTION_INFO));
    }

    // Decrement the index to the next available structure in the pool
    --connectionInfoIndex;

    free(connectionInfo);
}

// Function to check if a given CONNECTION_ID has already been used in the current session
bool isDuplicateConnectionId(int connectionId) {
    // Check if the hash map contains the CONNECTION_ID and return true if it does
    for (int i = 0; i < connectionInfoIndex + 1; ++i) {
        if (connectionInfoPool[i].CONNECTION_ID == connectionId) {
            return true;
        }
    }

    // If the hash map doesn't contain the CONNECTION_ID, insert it and return false
    CONNECTION_ID_MAP* newMapEntry = malloc(sizeof(CONNECTION_ID_MAP));
    newMapEntry->CONNECTION_ID = connectionId;
    newMapEntry->isDuplicate = false;
    connectionInfoPool[connectionInfoIndex + 1].hashMapEntries = realloc(connectionInfoPool[connectionInfoIndex + 1].hashMapEntries, (connectionInfoIndex + 2) * sizeof(CONNECTION_ID_MAP));
    connectionInfoPool[connectionInfoIndex + 1].hashMapEntries[connectionInfoIndex + 1] = newMapEntry;
    return false;
}

// Function to generate a unique CONNECTION_ID
int generateUniqueConnectionId(void) {
    int randomNumber = rand() % INT_MAX;
    while (isDuplicateConnectionId(randomNumber)) {
        randomNumber = rand() % INT_MAX;
    }
    return randomNumber;
}

// Function to generate a random connection state
int generateRandomConnectionState(void) {
    int randomNumber = rand() % 3;
    return randomNumber == 0 ? CONNECTION_STATE_ESTABLISHED : (randomNumber == 1 ? CONNECTION_STATE_CLOSED : CONNECTION_STATE_TIMED_OUT);
}

// Function to generate a random source IP address
char* generateRandomSourceIpAddress(void) {
    char ipAddress[16];
    sprintf(ipAddress, "%u.%u.%u.%u", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
    return strdup(ipAddress);
}

// Function to generate a random destination IP address
char* generateRandomDestinationIpAddress(void) {
    char ipAddress[16];
    sprintf(ipAddress, "%u.%u.%u.%u", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
    return strdup(ipAddress);
}
