#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include "blueslip.h"

/* Function to read input from standard input */
int read_input(char *input, int limit) {
    char c;
    int i = 0;
    while ((c = getchar()) != EOF && i < limit) {
        if (isdigit(c)) {
            input[i] = c;
            i++;
        } else {
            fprintf(stderr, "Invalid input character. Exiting...\n");
            return -1;
        }
    }
    return i;
}

/* Function to generate random values within a specified range */
int rand_val(int min, int max) {
    srand(time(NULL));
    int val = (rand() % (max - min + 1)) + min;
    return val;
}

/* Function to allocate memory dynamically */
void *allocate_memory(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Memory allocation failed. Exiting...\n");
        exit(-1);
    }
    return ptr;
}

/* Function to handle memory management errors */
void free_memory(void *ptr) {
    if (ptr != NULL) {
        free(ptr);
    }
}

/* Function to find the largest integer in an array of integers */
int find_largest(int *arr, int size) {
    int largest = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

/* Function to print the largest integer in an array of integers */
void print_largest(int *arr, int size) {
    printf("The largest integer is %d\n", find_largest(arr, size));
}

/* Main function to process input and output */
int main() {
    char input[10000];
    int i = 0;
    while ((i = read_input(input, 10000)) != EOF) {
        if (i > 0) {
            /* Allocate memory for the integer array */
            int *arr = allocate_memory(sizeof(int) * i);
            if (!arr) {
                fprintf(stderr, "Error: Memory allocation failed. Exiting...\n");
                exit(-1);
            }
            /* Assign random values within the specified range */
            for (int j = 0; j < i; j++) {
                arr[j] = rand_val(1, 10000);
            }
            /* Print the largest integer in the array */
            print_largest(arr, i);
            /* Release memory allocated for the integer array */
            free_memory(arr);
        } else {
            fprintf(stderr, "Error: Invalid input. Exiting...\n");
            exit(-1);
        }
    }
    return 0;
}
