typedef enum {
    CONN_STATUS_DISCONNECTED,
    CONN_STATUS_CONNECTING,
    CONN_STATUS_CONNECTED
} CONN_STATUS_T;

struct USER_CONNECTION_INFO {
    int userId;
    CONN_STATUS_T status;
    time_t timestamp;
};

void manageUserConnectionInfo(int numUsers) {
    // Initialize an array of USER_CONNECTION_INFO structures to hold the connections
    struct USER_CONNECTION_INFO *userConnections = (struct USER_CONNECTION_INFO *)malloc(numUsers * sizeof(struct USER_CONNECTION_INFO));
    if (!userConnections) {
        perror("Error allocating memory for user connections");
        exit(1);
    }

    // Initialize a hash map to quickly identify duplicate USER_IDs
    struct hashmap *idMap = (struct hashmap *)malloc(sizeof(struct hashmap));
    if (!idMap) {
        perror("Error allocating memory for ID map");
        exit(1);
    }

    // Initialize the hash map with a reasonable size
    hm_init(idMap, numUsers / 2);

    // Populate the USER_CONNECTION_INFO structures and add them to the hash map
    for (int i = 0; i < numUsers; i++) {
        struct USER_CONNECTION_INFO *connInfo = &userConnections[i];
        connInfo->userId = i;
        connInfo->status = CONN_STATUS_DISCONNECTED;
        connInfo->timestamp = 0;

        // Check if the ID is already in use and generate a new one if necessary
        while (hm_contains(idMap, connInfo->userId)) {
            connInfo->userId++;
        }

        hm_put(idMap, connInfo->userId, connInfo);
    }

    // Clean up the hash map and free the memory when done
    hm_destroy(idMap);

    // Free the memory for the USER_CONNECTION_INFO structures
    free(userConnections);
}
