    while ((entry = readdir(dir)) != NULL && num_images < MAX_IMAGES) {
        char* filename = entry->d_name;
        if (strlen(filename) > MAX_FILENAME_LEN) {
            continue;
        }

        // Check if the file is a supported image format
        if (!is_supported_image(filename)) {
            continue;
        }

        // Dynamically allocate memory for the filename
        char* filename_copy = malloc(strlen(filename) + 1);
        if (filename_copy == NULL) {
            perror("Failed to allocate memory");
            return;
        }
        strcpy(filename_copy, filename);

        // Add the image to the batch
        images[num_images].filename = filename_copy;
        images[num_images].width = 0;
        images[num_images].height = 0;
        num_images++;
    }
    closedir(dir);

    // Check if there were more than 10,000 images in the directory
    if (num_images > MAX_IMAGES) {
        printf("More than %d images found in %s. Only processing first %d.\n", num_images, directory, MAX_IMAGES);
    }

    // Loop through each image and process it
    for (int i = 0; i < num_images; i++) {
