        if (sem_wait(sem) == -1) {
            perror("Failed to acquire semaphore");
            return;
        }

        // Load and validate the image using an external library
        process_image(images[i].filename);

        // Release the semaphore
        if (sem_post(sem) == -1) {
            perror("Failed to release semaphore");
            return;
        }
    }

    // Clean up the memory allocated for the filenames
    for (int i = 0; i < num_images; i++) {
        free(images[i].filename);
    }

    // Close the semaphore
    if (sem_close(sem) == -1) {
        perror("Failed to close semaphore");
        return;
    }
}

