#define MAX_POINTS 20000
#define MAX_MEMORY 2097152 // 2 MB
#define POINT_SIZE 8 // sizeof(struct point)

typedef struct {
    double x, y;
} point_t;

struct point {
    int x, y;
};

struct mempool {
    void* pool;
    size_t size;
};

struct mempool* create_mempool(size_t size) {
    struct mempool* mp = malloc(sizeof(struct mempool));
    if (mp == NULL) {
        return NULL;
    }
    mp->pool = calloc(size, sizeof(char));
    if (mp->pool == NULL) {
        free(mp);
        return NULL;
    }
    mp->size = size;
    return mp;
}

void* mempool_alloc(struct mempool* mp, size_t size) {
    if (mp == NULL || size > mp->size) {
        return NULL;
    }
    void* ptr = mp->pool;
    mp->pool += size;
    mp->size -= size;
    return ptr;
}

void mempool_free(struct mempool* mp, void* ptr) {
    if (mp == NULL || ptr < mp->pool || ptr > mp->pool + mp->size) {
        return;
    }
    mp->size += (char*)ptr - mp->pool;
    mp->pool = (char*)ptr;
}

void* allocate_memory(size_t size) {
    struct mempool* mp = create_mempool(MAX_MEMORY);
    if (mp == NULL) {
        return NULL;
    }
    void* ptr = mempool_alloc(mp, size);
    if (ptr == NULL) {
        free(mp);
        return NULL;
    }
    return ptr;
}

void release_memory(void* ptr) {
    if (ptr == NULL) {
        return;
    }
    struct mempool* mp = create_mempool(MAX_MEMORY);
    if (mp == NULL) {
        return;
    }
    mempool_free(mp, ptr);
}

void initialize_arrays(int num_points, double** double_arr, char** char_arr, struct point** point_arr) {
    *double_arr = allocate_memory(num_points * sizeof(double));
    if (*double_arr == NULL) {
        fprintf(stderr, "Failed to allocate memory for doubles array.\n");
        return;
    }
    *char_arr = allocate_memory(num_points * sizeof(char));
    if (*char_arr == NULL) {
        release_memory(*double_arr);
        fprintf(stderr, "Failed to allocate memory for chars array.\n");
        return;
    }
    *point_arr = allocate_memory(num_points * sizeof(struct point));
    if (*point_arr == NULL) {
        release_memory(*double_arr);
        release_memory(*char_arr);
        fprintf(stderr, "Failed to allocate memory for points array.\n");
        return;
    }
    srand(time(NULL));
    for (int i = 0; i < num_points; ++i) {
        (*double_arr)[i] = rand() % 100 / 10.0;
        (*char_arr)[i] = rand() % 26 + 'A';
        (*point_arr)[i].x = rand() % 100 - 50;
        (*point_arr)[i].y = rand() % 100 - 50;
    }
}

void populate_points(int num_points, double* double_arr, char* char_arr, struct point* point_arr) {
    for (int i = 0; i < num_points; ++i) {
        // Use a hash table to track unique points and prevent duplicate coordinates.
        int x = rand() % 100 - 50;
        int y = rand() % 100 - 50;
        while (hash_table_contains(x, y)) {
            x = rand() % 100 - 50;
            y = rand() % 100 - 50;
        }
        double_arr[i] = x * x + y * y;
        char_arr[i] = (char)(x + y);
        point_arr[i].x = x;
        point_arr[i].y = y;
    }
}

int hash_table_contains(int key, int value) {
    // Implement a simple hash table using an array of pointers.
    static struct hash_entry* hash_table = NULL;
    if (hash_table == NULL) {
        hash_table = malloc(sizeof(struct hash_entry) * 100);
        for (int i = 0; i < 100; ++i) {
            hash_table[i] = NULL;
        }
    }
    int index = key % 100;
    struct hash_entry* entry = hash_table[index];
    while (entry != NULL && entry->key != key) {
        entry = entry->next;
    }
    if (entry == NULL) {
        return false;
    }
    return entry->value == value;
}

struct hash_entry* create_hash_entry(int key, int value) {
    struct hash_entry* entry = malloc(sizeof(struct hash_entry));
    if (entry == NULL) {
        fprintf(stderr, "Failed to allocate memory for hash table.\n");
        return NULL;
    }
    entry->key = key;
    entry->value = value;
    entry->next = NULL;
    return entry;
}

void render_points(int num_points, double* double_arr, char* char_arr, struct point* point_arr) {
    // Implement a simple rendering algorithm using OpenGL.
    glBegin(GL_POINTS);
    for (int i = 0; i < num_points; ++i) {
        glVertex2f(point_arr[i].x, point_arr[i].y);
    }
    glEnd();
}

void render_text(int num_points, double* double_arr, char* char_arr, struct point* point_arr) {
    // Implement a simple text rendering algorithm using OpenGL.
    int font_size = 16;
    GLfloat font_color[] = {0.0f, 0.0f, 0.0f};
