#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <errno.h>

typedef struct {
    L2_MESSAGE message;
    MAC_HEADER header;
} MAC_PDU;

int init_mac_pdu(MAC_PDU *pdu, void *data, size_t data_len) {
    // Check for insufficient memory
    if (data_len < sizeof(L2_MESSAGE)) {
        return -ENOMEM;
    }

    // Initialize the L2 message structure
    memcpy(&pdu->message, data, sizeof(L2_MESSAGE));

    // Validate the message format
    if (!is_valid_l2_message(pdu->message)) {
        return -EINVAL;
    }

    // Allocate memory for the MAC header
    pdu->header = malloc(sizeof(MAC_HEADER));
    if (pdu->header == NULL) {
        return -ENOMEM;
    }

    // Initialize the MAC header structure
    memcpy(pdu->header, data + sizeof(L2_MESSAGE), sizeof(MAC_HEADER));

    // Validate the MAC header format
    if (!is_valid_mac_header(pdu->header)) {
        free(pdu->header);
        pdu->header = NULL;
        return -EINVAL;
    }

    return 0;
}

void destroy_mac_pdu(MAC_PDU *pdu) {
    // Free the MAC header structure
    free(pdu->header);
    pdu->header = NULL;

    // Reset the L2 message structure to its initial state
    memset(&pdu->message, 0, sizeof(L2_MESSAGE));
}

int main() {
    MAC_PDU *pdu;
    size_t data_len = 1000; // Arbitrary length of L2 message data
    void *data = malloc(data_len);

    if (data == NULL) {
        printf("Error: Failed to allocate memory for L2 message\n");
        return -ENOMEM;
    }

    pdu = malloc(sizeof(MAC_PDU));
    if (pdu == NULL) {
        free(data);
        printf("Error: Failed to allocate memory for MAC PDU\n");
        return -ENOMEM;
    }

    int ret = init_mac_pdu(pdu, data, data_len);
    if (ret != 0) {
        free(data);
        free(pdu);
        printf("Error: Failed to initialize MAC PDU\n");
        return ret;
    }

    // Use the initialized MAC PDU

    destroy_mac_pdu(pdu);
    free(data);
    free(pdu);

    return 0;
}
```
