        tx_power_report->RNTI = rand() % 1000;
        srand((unsigned)time(NULL)); // Re-seed the random number generator with a new seed
        for (size_t j = 0; j < 4; j++) {
            tx_power_report->CRCFLAG[j] = rand() % 256;
        }
        memcpy(tx_power.pool + i * sizeof(TX_POWER_REPORT_INDICATION_T), tx_power_report, sizeof(TX_POWER_REPORT_INDICATION_T));
    }

    // Free the memory allocated for 'record' structures and 'TX_POWER_REPORT_INDICATION_T' structures when they are no longer needed
    free(records.records);
    free(tx_power.pool);
}
