```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <sys/time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>

// Predefined log level schema
enum LogLevel {
    TRACE,
    DEBUG,
    INFO,
    WARN,
    ERROR,
};

// Logging buffer structure
struct LogBuffer {
    size_t size;      // Size of the buffer in bytes
    char* data;       // Pointer to the buffer data
    size_t used;     // Number of bytes written to the buffer so far
};

// Log file structure
struct LogFile {
    FILE* handle;   // File handle for the log file
    size_t size;    // Size of the log file in bytes
};

// Logging system configuration
struct LogConfig {
    enum LogLevel level;     // Current log level setting
    size_t bufferSize;      // Size of the logging buffer
    struct LogFile* file;   // Pointer to the log file structure
};

// Global logging system variables
struct LogBuffer logBuf;
struct LogFile logFile;
struct LogConfig config;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void logInit(const char* filename, size_t bufferSize) {
    // Initialize the logging system configuration
    config.level = TRACE;
    config.bufferSize = bufferSize;
    if (filename != NULL) {
        config.file = malloc(sizeof(struct LogFile));
        config.file->handle = fopen(filename, "a");
        if (config.file->handle == NULL) {
            perror("Error opening log file");
            exit(-1);
        }
    } else {
        config.file = NULL;
    }

    // Initialize the logging buffer
    logBuf.size = bufferSize;
    logBuf.data = malloc(logBuf.size);
    if (logBuf.data == NULL) {
        perror("Error allocating memory for log buffer");
        exit(-1);
    }
    logBuf.used = 0;

    // Initialize the mutex
    pthread_mutex_init(&mutex, NULL);
}

void logWrite(const char* message) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Validate the log level and buffer size
    if (config.level < 0 || config.level > 9) {
        fprintf(stderr, "Invalid log level: %d\n", config.level);
    } else if (logBuf.used + strlen(message) >= logBuf.size) {
        fprintf(stderr, "Log buffer is full.\n");
    }

    // Write the message to the buffer
    memcpy(logBuf.data + logBuf.used, message, strlen(message));
    logBuf.used += strlen(message);

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

void logFlush() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Flush the buffer to disk
    if (config.file != NULL) {
        fwrite(logBuf.data, 1, logBuf.used, config.file->handle);
    }

    // Clear the buffer and unlock the mutex
    logBuf.used = 0;
    pthread_mutex_unlock(&mutex);
}

void logClose() {
    // Close the log file if it was opened
    if (config.file != NULL) {
        fclose(config.file->handle);
        free(config.file);
    }

    // Free the buffer data and destroy the mutex
    free(logBuf.data);
    pthread_mutex_destroy(&mutex);
}
```
The `logInit` function initializes the logging system with a specified file name and buffer size. It validates the log level and buffer size, and opens the log file for writing if it was specified. If an error occurs during initialization, the function exits with an error message.

The `logWrite` function writes a message to the log buffer. It first locks the mutex to prevent concurrent access, then validates the log level and buffer size. If the message is too long to fit in the buffer, it is truncated to fit. The message is then written to the buffer, and the mutex is unlocked.

The `logFlush` function flushes the log buffer to disk. It first locks the mutex to prevent concurrent access, then writes the buffer data to the log file if it was opened. Finally, the mutex is unlocked.

The `logClose` function closes the log file if it was opened and frees the memory used by the buffer. It also destroys the mutex.

To integrate with an external asynchronous I/O library, you can use a signal handler to handle SIGIO signals sent by the asynchronous I/O library when the buffer is full or when the log file needs to be flushed. The signal handler should call `logFlush` and `logClose` as necessary, and then unblock the SIGIO signal so that it can be sent again if necessary.

To optimize performance, you can use techniques such as caching, prefetching, and data compression to minimize memory bandwidth usage and improve cache locality. You can also use techniques such as batching and throttling to reduce the frequency of I/O operations and improve overall throughput.']

