    int *key_array;
    record_t **record_array;
} data_store_t;

// Function to manage dynamic data store for 'record' objects
void manage_data_store(data_store_t *data_store, size_t max_size) {
    // Allocate memory for array of record structures
    data_store->record_array = (record_t **)malloc(max_size * sizeof(record_t *));
    if (!data_store->record_array) {
        printf("Failed to allocate memory for record array\n");
        exit(1);
    }

    // Allocate memory for associated offset and key arrays
    data_store->offset_array = (long *)malloc(max_size * sizeof(long));
    if (!data_store->offset_array) {
        printf("Failed to allocate memory for offset array\n");
        exit(1);
    }
    data_store->key_array = (int *)malloc(max_size * sizeof(int));
    if (!data_store->key_array) {
        printf("Failed to allocate memory for key array\n");
        exit(1);
    }

    // Initialize secondary array of pointers to facilitate efficient access based on keys
    int i;
    for (i = 0; i < max_size; i++) {
        data_store->record_array[i] = NULL;
    }

    // Verify that allocated memory does not exceed maximum size constraint and check for inconsistencies in offset and key mappings to maintain data integrity
    if (data_store->offset_array == NULL || data_store->key_array == NULL) {
        printf("Failed to allocate memory for offset or key array\n");
        exit(1);
    }
    for (i = 0; i < max_size; i++) {
        if (data_store->offset_array[i] != -1 && data_store->key_array[i] == -1) {
            printf("Inconsistent offset and key mappings detected\n");
            exit(1);
        }
    }

    // Synchronize access to the data store from multiple threads
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);
    pthread_mutex_lock(&mutex);

    // Implement mechanisms to handle potential overflow conditions when initializing offset and key arrays
    size_t current_size = 0;
    while (current_size < max_size) {
        if (data_store->offset_array[current_size] == -1 && data_store->key_array[current_size] == -1) {
            // Allocate memory for record structure and initialize offset and key values
            data_store->record_array[current_size] = (record_t *)malloc(sizeof(record_t));
            if (!data_store->record_array[current_size]) {
                printf("Failed to allocate memory for record structure\n");
                exit(1);
            }
            data_store->offset_array[current_size] = current_size;
            data_store->key_array[current_size] = current_size;
            current_size++;
        } else {
            // Increment offset and key values for existing records
            data_store->offset_array[current_size] = current_size;
            data_store->key_array[current_size] = current_size;
            current_size++;
        }
    }

    // Release memory for array of record structures, associated offset and key arrays, and secondary array of pointers to facilitate efficient access based on keys
    free(data_store->record_array);
    free(data_store->offset_array);
    free(data_store->key_array);

    // Release mutex lock to prevent race conditions and ensure data consistency
    pthread_mutex_unlock(&mutex);
}
