#define MAX_KEYS 1000000
#define MAX_OFFSETS 1000000
#define MAX_RECORDS 1000000
#define MIN_INT -2147483648
#define MAX_INT 2147483647
#define MAX_RAND INT(MAX_INT-MIN_INT) + MIN_INT

typedef struct record {
    int value;
} record;

struct data_structures {
    long *offsets;
    int *keys;
    record **records;
};

int initialize_data_structures(struct data_structures *ds, size_t num_records) {
    // Allocate memory for the arrays of offsets and keys
    ds->offsets = (long *)malloc(num_records * sizeof(long));
    if (!ds->offsets) {
        printf("Failed to allocate memory for offsets\n");
        return 1;
    }
    ds->keys = (int *)malloc(num_records * sizeof(int));
    if (!ds->keys) {
        printf("Failed to allocate memory for keys\n");
        free(ds->offsets);
        return 1;
    }
    // Allocate memory for the array of records
    ds->records = (record **)malloc(num_records * sizeof(record *));
    if (!ds->records) {
        printf("Failed to allocate memory for records\n");
        free(ds->offsets);
        free(ds->keys);
        return 1;
    }
    // Initialize the offsets and keys arrays with random values within a specified range
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        ds->offsets[i] = rand() % MAX_OFFSETS;
        ds->keys[i] = rand() % MAX_KEYS;
    }
    // Initialize the records array with random values within a specified range
    for (size_t i = 0; i < num_records; i++) {
        ds->records[i] = malloc(sizeof(record));
        if (!ds->records[i]) {
            printf("Failed to allocate memory for record %zu\n", i);
            free(ds->offsets);
            free(ds->keys);
            return 1;
        }
        ds->records[i]->value = rand() % MAX_INT;
    }
    return 0;
}

int load_php_web_application(struct data_structures *ds) {
