    system("php -c config.ini > /dev/null 2>&1");
    return 0;
}

void *initialize_data_structures_thread(void *arg) {
    struct data_structures *ds = (struct data_structures *)arg;
    int result = initialize_data_structures(ds, MAX_RECORDS);
    if (result != 0) {
        printf("Failed to initialize data structures\n");
        return NULL;
    }
    return NULL;
}

void *load_php_web_application_thread(void *arg) {
    struct data_structures *ds = (struct data_structures *)arg;
    int result = load_php_web_application(ds);
    if (result != 0) {
        printf("Failed to load PHP web application\n");
        return NULL;
    }
    return NULL;
}

int main() {
    struct data_structures ds;
    // Initialize the data structures in a separate thread to avoid blocking the main function's execution
    pthread_t initialize_data_structures_thread;
    int result = pthread_create(&initialize_data_structures_thread, NULL, initialize_data_structures_thread, &ds);
    if (result != 0) {
        printf("Failed to create thread for initializing data structures\n");
        return 1;
    }
    // Load the PHP web application in a separate thread to avoid blocking the main function's execution
    pthread_t load_php_web_application_thread;
    result = pthread_create(&load_php_web_application_thread, NULL, load_php_web_application_thread, &ds);
    if (result != 0) {
        printf("Failed to create thread for loading PHP web application\n");
        return 1;
    }
    // Wait for the threads to complete before exiting
    pthread_join(initialize_data_structures_thread, NULL);
    pthread_join(load_php_web_application_thread, NULL);
    return 0;
}
