struct TXPowerReportIndication {
    rx_ue_information_tag: RXUEInformationTag,
    rnti: u32,
    crc_indication_rel8_tag: CRCIndicationRel8Tag,
}

impl TXPowerReportIndication {
    fn new(rx_ue_information_tag: RXUEInformationTag) -> Self {
        let rnti = random::<u32>(); // randomly generate a unique RNTI
        let crc_indication_rel8_tag = CRCIndicationRel8Tag::new(rnti);
        TXPowerReportIndication {
            rx_ue_information_tag,
            rnti,
            crc_indication_rel8_tag,
        }
    }
}

struct TXPowerReportIndicationsPool<T> where T: TXPowerReportIndication {
    pool: Vec<Arc<Mutex<T>>>,
}

impl<T> TXPowerReportIndicationsPool<T> where T: TXPowerReportIndication {
    fn new() -> Self {
        TXPowerReportIndicationsPool { pool: vec![] }
    }

    fn allocate(&mut self, rx_ue_information_tag: RXUEInformationTag) -> Arc<Mutex<T>> {
        if let Some(index) = self.pool.iter().position(|elem| elem.lock().unwrap().rnti == rx_ue_information_tag.rnti) {
            // reuse existing element
            return self.pool[index].clone();
        }

        // create new element
        let mutex = Mutex::new(TXPowerReportIndication::new(rx_ue_information_tag));
        let arc = Arc::new(mutex);
        self.pool.push(arc.clone());
        arc
    }
}

struct TXPowerReportIndicationsManager {
    pool: TXPowerReportIndicationsPool<TXPowerReportIndication>,
    max_size: usize,
    config: ConfigService,
}

impl TXPowerReportIndicationsManager {
    fn new(config: ConfigService) -> Self {
        TXPowerReportIndicationsManager {
            pool: TXPowerReportIndicationsPool::new(),
            max_size: 1024, // default maximum size
            config,
        }
    }

    fn allocate(&mut self, rx_ue_information_tag: RXUEInformationTag) -> Arc<Mutex<TXPowerReportIndication>> {
        if let Some(index) = self.pool.iter().position(|elem| elem.lock().unwrap().rnti == rx_ue_information_tag.rnti) {
            // reuse existing element
            return self.pool[index].clone();
        }

        // create new element if size is not exceeded
        if self.pool.len() < self.max_size {
            return self.pool.allocate(rx_ue_information_tag);
        }

        // handle overflow by reusing the least recently used element
        let index = (self.pool.len() - 1) % self.max_size;
        let elem = self.pool[index].lock().unwrap();
        *elem = TXPowerReportIndication::new(rx_ue_information_tag);
        Arc::clone(&self.pool[index])
    }

    fn update_max_size(&mut self, new_size: usize) {
        // handle potential delays in receiving updated configuration settings
        if new_size <= 0 {
            return;
        }

        // ensure the function remains responsive during periods of high demand
        self.max_size = std::cmp::min(new_size, self.pool.len());
    }
}
