};

// Define a function to find and print the largest integer in the array
void find_largest_integer(int *array, size_t size) {
    // Initialize the structure to store the largest integer
    struct largest_integer largest = {INT_MIN, 0};

    // Loop through the array and find the largest integer
    for (size_t i = 0; i < size; i++) {
        if (array[i] > largest.value) {
            largest.value = array[i];
            largest.index = i;
        }
    }

    // Print the largest integer and its index
    printf("Largest integer: %d, Index: %zu\n", largest.value, largest.index);
