typedef enum {
    PROCESS_STATE_T_RUNNING,
    PROCESS_STATE_T_STOPPED
} PROCESS_STATE_T;

typedef struct {
    int process_id;
    PROCESS_STATE_T state;
    char* executable_name;
    int* open_file_descriptors;
    time_t start_time;
    time_t end_time;
} PROCESS_STATE;

static unsigned long srand_seed = 0;

void process_state_init(PROCESS_STATE** states, size_t count) {
    for (size_t i = 0; i < count; i++) {
        PROCESS_STATE* state = malloc(sizeof(PROCESS_STATE));
        state->process_id = getpid();
        state->state = PROCESS_STATE_T_RUNNING;
        state->executable_name = "./myprogram";
        state->open_file_descriptors = NULL;
        state->start_time = time(NULL);
        state->end_time = 0;
        states[i] = state;
    }
}

void process_state_deinit(PROCESS_STATE** states, size_t count) {
    for (size_t i = 0; i < count; i++) {
        free(states[i]);
    }
}

int process_state_generate_id(void) {
    return getpid();
}

PROCESS_STATE* process_state_create(PROCESS_STATE** states, size_t count) {
    int id = process_state_generate_id();
    for (size_t i = 0; i < count; i++) {
        if (states[i]->process_id == id) {
            continue;
        }
        states[i]->process_id = id;
        return states[i];
    }
    PROCESS_STATE* state = malloc(sizeof(PROCESS_STATE));
    state->process_id = id;
    state->state = PROCESS_STATE_T_RUNNING;
    state->executable_name = "./myprogram";
    state->open_file_descriptors = NULL;
    state->start_time = time(NULL);
    state->end_time = 0;
    return state;
}

void process_state_update(PROCESS_STATE** states, size_t count) {
    for (size_t i = 0; i < count; i++) {
        if (states[i]->process_id == getpid()) {
            states[i]->state = PROCESS_STATE_T_RUNNING;
            return;
        }
    }
}

void process_state_destroy(PROCESS_STATE** states, size_t count) {
    for (size_t i = 0; i < count; i++) {
        free(states[i]);
    }
}
