// Function to handle memory allocation errors and retry if necessary
void* malloc_with_retry(size_t size) {
    void* ptr = NULL;
    while (ptr == NULL) {
        ptr = malloc(size);
        if (ptr == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory. Retrying...\n");
            sleep(1); // Sleep for 1 second before retrying
        }
    }
    return ptr;
}

// Function to handle memory deallocation errors and log if necessary
void free_with_logging(void* ptr) {
    if (ptr != NULL) {
        free(ptr);
    } else {
        fprintf(stderr, "Warning: Attempted to free null pointer\n");
    }
}

