#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define the record structure
struct Record {
    int value;
    time_t timestamp;
    unsigned int id;
};

// Define the array of offset values
long offsets[10];

// Define the array of keys
int keys[10];

// Define the array of records
struct Record records[10];

// Define the linked list node structure
struct Node {
    struct Record record;
    struct Node* next;
};

// Define the head and tail pointers of the linked list
struct Node* head = NULL;
struct Node* tail = NULL;

// Define the maximum number of records to maintain
#define MAX_RECORDS 10

// Define the synchronization mechanism for multi-threaded access
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initRecord(struct Record* record) {
    // Initialize the record with a random value and current time
    record->value = rand() % 100 + 1;
    record->timestamp = time(NULL);
    record->id = 0;
}

int addRecord(struct Record* record) {
    // Acquire the lock for multi-threaded access
    pthread_mutex_lock(&lock);

    // Check if the linked list is full
    if (tail == NULL || tail->next != NULL) {
        // If the linked list is full, prune it to maintain MAX_RECORDS records
        struct Node* node = head;
        while (node->next != NULL && node->next->next != NULL) {
            node = node->next;
        }
        tail = node;
    }

    // Add the record to the linked list and update the head pointer if necessary
    struct Node* newNode = malloc(sizeof(struct Node));
    newNode->record = *record;
    newNode->next = NULL;
    if (head == NULL) {
        head = tail = newNode;
    } else {
        tail->next = newNode;
        tail = newNode;
    }

    // Update the offset and key arrays
    offsets[tail->record.id] = tail->record.value - 1;
    keys[tail->record.id] = tail->record.id;

    // Release the lock for multi-threaded access
    pthread_mutex_unlock(&lock);
}

int deleteRecord(struct Record* record) {
    // Acquire the lock for multi-threaded access
    pthread_mutex_lock(&lock);

    // Find the node in the linked list corresponding to the given record
    struct Node* node = head;
    while (node != NULL && &(node->record) != record) {
        node = node->next;
    }

    // If the node is found, remove it from the linked list and update the offset and key arrays
    if (node != NULL) {
        struct Node* prevNode = head;
        while (prevNode->next != node) {
            prevNode = prevNode->next;
        }
        prevNode->next = node->next;
        free(node);
        if (tail == node) {
            tail = prevNode;
        }
        offsets[record->id] = -1;
        keys[record->id] = -1;
    }

    // Release the lock for multi-threaded access
    pthread_mutex_unlock(&lock);
}

struct Record* getRecord(int id) {
    // Acquire the lock for multi-threaded access
    pthread_mutex_lock(&lock);

    // Find the node in the linked list corresponding to the given ID
    struct Node* node = head;
    while (node != NULL && node->record.id != id) {
        node = node->next;
    }

    // If the node is found, return a copy of its record
    if (node != NULL) {
        struct Record* record = malloc(sizeof(struct Record));
        *record = node->record;
        return record;
    }

    // Release the lock for multi-threaded access
    pthread_mutex_unlock(&lock);

    return NULL;
}
