// Define the structure for storing records
typedef struct {
    int key;
    long *offset;
    int ref_count;
} record;

// Define the function to allocate memory for the arrays
void alloc_memory(int num_keys, int num_offsets) {
    // Allocate memory for the keys array
    int *keys = (int *)malloc(num_keys * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for keys\n");
        return;
    }

    // Initialize the reference count for each key
    for (int i = 0; i < num_keys; i++) {
        keys[i] = 0;
    }

    // Allocate memory for the offsets array
    long *offsets = (long *)malloc(num_offsets * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        return;
    }

    // Initialize the reference count for each offset
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = 0;
    }

    // Return the memory for the keys and offsets arrays
    return keys, offsets;
}

// Define the function to update a record's value
void update_record(record *rec) {
    // Generate a random value within the specified range
    int val = rand() % 10 + 1;

    // Set the record's value and reference count
    rec->key = val;
    rec->ref_count++;
}

// Define the function to increment a record's reference count
void inc_ref(record *rec) {
    // Increment the reference count for the record
    rec->ref_count++;
}

// Define the function to decrement a record's reference count
void dec_ref(record *rec) {
    // Decrement the reference count for the record
    rec->ref_count--;

    // Check if the reference count has reached zero and deallocate the record if necessary
    if (rec->ref_count == 0) {
        free(rec->offset);
