// Seed the random number generator correctly to ensure reproducibility across function calls
void seed_rng() {
    time_t t;
    time(&t);
    rng.seed((unsigned long)t);
}

// Allow users to specify a custom random number range, with logic to default to a safe range if the specified range is invalid
int get_random_number(int min, int max) {
    if (min > max || min < 0 || max < 0) {
        return generate_random_number(-1000000000, 1000000000); // Default to a safe range if the specified range is invalid
    } else {
        return generate_random_number(min, max);
    }
}

