    for (int i = 0; i < INITIAL_ARRAY_SIZE; i++) {
        (*metrics)[i] = (struct MetricRecord *)malloc(sizeof(struct MetricRecord));
        (*metrics)[i]->count = 1;
        (*metrics)[i]->average = (*dataPoints)[i];
        (*metrics)[i]->status = 'N';
    }
}

void addMetricRecord(long timestamp, double dataPoint, struct MetricRecord **metrics) {
    // Check if the array needs to be resized
    int currentSize = sizeof((*metrics)) / sizeof((*metrics)[0]);
    if (currentSize == MAX_ARRAY_SIZE) {
        return;
    }

    // Add new record to the end of the array
    (*timestamps)[currentSize] = timestamp;
    (*dataPoints)[currentSize] = dataPoint;
    struct MetricRecord *newMetric = (struct MetricRecord *)malloc(sizeof(struct MetricRecord));
    newMetric->count = 1;
    newMetric->average = dataPoint;
    newMetric->status = 'N';
    (*metrics)[currentSize] = newMetric;
}

void updateMetricRecord(long timestamp, double dataPoint, struct MetricRecord **metrics) {
    // Find the index of the record to be updated
    int index = findIndex(timestamp, *timestamps, currentSize);

    // Update the record
    (*metrics)[index]->count++;
    (*metrics)[index]->average += dataPoint;
}

int findIndex(long timestamp, long *timestamps, int size) {
    for (int i = 0; i < size; i++) {
        if (timestamp == timestamps[i]) {
            return i;
        }
    }
    // If the record is not found, add it to the end of the array
    return currentSize;
}

