    for (int i = 0; i < currentSize; i++) {
        newTimestamps[i] = (*timestamps)[i];
        newDataPoints[i] = (*dataPoints)[i];
        newMetrics[i] = (*metrics)[i];
    }

    // Set the new arrays as the current ones
    *timestamps = newTimestamps;
    *dataPoints = newDataPoints;
    *metrics = newMetrics;
}

