// Structure to hold the metric data and metadata
typedef struct Metric {
    long timestamp;
    double value;
    char status;
} Metric;

// Function to dynamically allocate memory for the arrays
void* alloc_arrays(size_t num_metrics, size_t num_data_points) {
    // Calculate the total size of the arrays
    size_t total_size = (num_metrics * sizeof(Metric)) + (num_data_points * sizeof(double));

    // Allocate memory for the arrays
    void* mem = malloc(total_size);
    if (!mem) {
        printf("Error: failed to allocate memory\n");
        return NULL;
    }

    // Initialize the metadata pointers array
    Metric** metadata = (Metric**)mem;
    for (size_t i = 0; i < num_metrics; i++) {
        metadata[i] = mem + (i * sizeof(Metric));
    }

    // Initialize the data points array
    double* data_points = (double*)((char*)mem + (num_metrics * sizeof(Metric)));

    return mem;
}

// Function to handle memory allocation failures gracefully
void handle_memory_allocation_failure() {
    printf("Error: failed to allocate memory\n");
}

// Function to process the data and perform encryption/decryption
int process_data(EVP_CIPHER* cipher, void* mem) {
    // Get the metadata pointers array
    Metric** metadata = (Metric**)mem;

    // Get the number of metrics
    size_t num_metrics = sizeof(metadata) / sizeof(Metadata);

    // Get the data points array
    double* data_points = (double*)((char*)mem + (num_metrics * sizeof(Metric)));

    // Iterate over the data points and perform encryption/decryption
    for (size_t i = 0; i < num_data_points; i++) {
        // Encrypt/decrypt the data point using the chosen cipher
        if (EVP_EncryptUpdate(cipher, NULL, &data_points[i], sizeof(double))) {
            printf("Error: failed to encrypt/decrypt data point\n");
            return 1;
        }
    }

    // Return successfully
    return 0;
}

// Function to handle missing or late data entries
void handle_missing_data() {
    printf("Warning: received missing or late data entry\n");
}

// Function to manage memory allocation failures without crashing the system
void handle_memory_allocation_failure() {
    printf("Error: failed to allocate memory\n");
}

// Main function to implement the cryptographic ciphers
int main(int argc, char* argv[]) {
    // Check the command-line arguments
    if (argc != 2) {
        printf("Usage: %s <cipher mode>\n", argv[0]);
        return 1;
    }

    // Initialize the OpenSSL library
    SSL_library_init();

    // Select the cipher based on the command-line argument
    EVP_CIPHER* cipher = NULL;
    switch (argv[1]) {
        case "ECB":
            cipher = EVP_des_ecb();
            break;
        case "EDE":
            cipher = EVP_des_ede();
            break;
        case "EDE3":
            cipher = EVP_des_ede3();
            break;
        case "CFB":
            cipher = EVP_des_cfb();
            break;
    }

    // Allocate memory for the arrays
    void* mem = alloc_arrays(10, 10);
    if (!mem) {
        handle_memory_allocation_failure();
        return 1;
    }

    // Initialize the metadata pointers array
    Metric** metadata = (Metric**)mem;

    // Initialize the data points array
    double* data_points = (double*)((char*)mem + (sizeof(metadata) / sizeof(Metadata)));

    // Process the data and perform encryption/decryption
    if (process_data(cipher, mem)) {
        handle_memory_allocation_failure();
        return 1;
    }

    // Free the memory allocated for the arrays
    free(mem);

    // Return successfully
    return 0;
}
