    // Initialize the SHA-256 context
    SHA256_CTX ctx;
    if (SHA256_Init(&ctx) != 1) {
        printf("Error initializing SHA-256 context: %s\n", strerror(errno));
        return -1;
    }

    // Update the SHA-256 context with the data chunk
    if (SHA256_Update(&ctx, data, data_length) != 1) {
        printf("Error updating SHA-256 context: %s\n", strerror(errno));
        return -1;
    }

    // Finalize the SHA-256 hash and get the result
    unsigned char digest[SHA256_DIGEST_LENGTH];
    if (SHA256_Final(&ctx, digest) != 1) {
        printf("Error finalizing SHA-256 hash: %s\n", strerror(errno));
        return -1;
    }

    // Copy the result to the output buffer
    memcpy(hash, digest, SHA256_DIGEST_LENGTH);

    return 0;
}

// Define the function to release all allocated memory when the function is complete
void sha256_cleanup() {
    // Free any memory that was allocated for the Records and hash values
    free(records);
    for (int i = 0; i < num_records; i++) {
        free(records[i].hash_value);
    }
}
