// Define a record structure for storing an int value
typedef struct {
    int value;
} Record;

// Define a function to allocate memory for an array of records
void* alloc_records(size_t num_records, size_t record_size) {
    // Calculate the total size of the array
    size_t total_size = num_records * record_size;

    // Ensure that the total size does not exceed 1 MB
    if (total_size > 1024*1024) {
        fprintf(stderr, "Error: Memory allocation failed. Total size exceeds 1 MB.\n");
        return NULL;
    }

    // Allocate memory for the array
    void* ptr = malloc(total_size);

    // Check if memory allocation was successful
    if (ptr == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    // Initialize the array with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        Record* record = ptr + i * record_size;
        record->value = rand() % 1000;
    }

    return ptr;
}

// Define a function to release memory for an array of records
void free_records(void* ptr, size_t num_records, size_t record_size) {
    // Calculate the total size of the array
    size_t total_size = num_records * record_size;

    // Release memory for the array
    free(ptr);
}

// Define a function to set the value of each record's int field to a random value within a specified range
void set_random_values(Record* records, size_t num_records, int min_value, int max_value) {
    // Set the seed for reproducibility
    srand(time(NULL));

    // Loop through each record and set its value to a random value within the specified range
    for (int i = 0; i < num_records; i++) {
        Record* record = records + i;
        record->value = rand() % (max_value - min_value + 1) + min_value;
    }
}

// Define a function to generate random numbers within a specified range
int generate_random(int min_value, int max_value) {
    // Set the seed for reproducibility
    srand(time(NULL));

    // Generate a random number within the specified range
    return rand() % (max_value - min_value + 1) + min_value;
}

int main() {
    // Allocate memory for an array of records
    size_t num_records = 1000;
    size_t record_size = sizeof(Record);
    Record* records = alloc_records(num_records, record_size);

    if (records == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return 1;
    }

    // Set the value of each record's int field to a random value within a specified range
    set_random_values(records, num_records, 0, 1000);

    // Release memory for the array of records
    free_records(records, num_records, record_size);

    return 0;
}
