// Custom memory allocator to minimize fragmentation and optimize for cache locality
struct MemoryAllocator {
  // Fixed-size blocks of memory
  struct Block {
    size_t capacity;   // Size of the block in bytes
    size_t used;       // Amount of memory used in the block
    char* buffer;      // Pointer to the start of the block
  };

  // Slab allocation strategy for managing blocks
  struct Slab {
    size_t capacity;   // Total capacity of the slab in bytes
    size_t used;       // Amount of memory used in the slab
    char* buffer;      // Pointer to the start of the slab
  };

  // List of blocks for managing memory allocation and deallocation
  struct BlockList {
    size_t capacity;   // Total capacity of the list in bytes
    size_t used;       // Amount of memory used in the list
    char* buffer;      // Pointer to the start of the list
  };

  // Custom allocator functions for managing memory allocation and deallocation
  void* (*alloc)(size_t);   // Allocate memory from the slab
  void (*free)(void*);      // Free memory back to the slab
};

// Memory pool for managing memory allocation and deallocation
struct MemoryPool {
  size_t capacity;         // Total capacity of the pool in bytes
  size_t used;             // Amount of memory used in the pool
  char* buffer;            // Pointer to the start of the pool
};

// In-memory database system for managing records
struct Database {
  struct MemoryPool* memory_pool;   // Memory pool for managing memory allocation and deallocation
  struct BlockList block_list;      // List of blocks for managing memory allocation and deallocation
  struct Slab slab;                // Slab allocation strategy for managing blocks
};

// Initialize the database system
void init_database(struct Database* db) {
  db->memory_pool = create_memory_pool();
  db->block_list.capacity = 1024 * 1024; // 1 MB
  db->block_list.used = 0;
  db->block_list.buffer = NULL;
}

// Insert a record into the database
void insert(struct Database* db, long offset, int key, int value) {
  struct Block* block = find_block(db, offset);
  if (block == NULL) {
    // Allocate a new block if the requested offset is not found
    block = allocate_block(db, offset);
  }

  // Insert the record into the block
  struct Record* record = find_record(block, key);
  if (record == NULL) {
    record = allocate_record(block, key, value);
  } else {
    // Update the existing record with the new value
    record->value = value;
  }
}

// Retrieve a record from the database
void* retrieve(struct Database* db, long offset, int key) {
  struct Block* block = find_block(db, offset);
  if (block == NULL) {
    return NULL;
  }

  struct Record* record = find_record(block, key);
  if (record == NULL) {
    return NULL;
  }

  // Return the value of the found record
  return &record->value;
}

// Delete a record from the database
void delete(struct Database* db, long offset, int key) {
  struct Block* block = find_block(db, offset);
  if (block == NULL) {
    return;
  }

  struct Record* record = find_record(block, key);
  if (record != NULL) {
    // Free the record and update the block's metadata
    free_record(record);
  }
}

// Find a block in the database based on its offset
struct Block* find_block(struct Database* db, long offset) {
  struct BlockList* list = &db->block_list;
  for (size_t i = 0; i < list->capacity; i++) {
    struct Block* block = &list->buffer[i];
    if (block->offset == offset) {
      return block;
    }
  }

  // If the requested block is not found, allocate a new one
  struct Block* block = allocate_block(db, offset);
  list->used++;
  return block;
}

// Allocate a new block in the database based on its offset
struct Block* allocate_block(struct Database* db, long offset) {
  struct MemoryPool* pool = db->memory_pool;
  size_t block_size = sizeof(struct Block);
  char* buffer = pool->buffer + (offset * block_size);
  return (struct Block*)buffer;
}

// Find a record in a block based on its key
struct Record* find_record(struct Block* block, int key) {
  for (size_t i = 0; i < block->capacity; i++) {
    struct Record* record = &block->buffer[i];
    if (record->key == key) {
      return record;
    }
  }

  // If the requested record is not found, allocate a new one
  struct Record* record = allocate_record(block, key);
  block->used++;
  return record;
}

// Allocate a new record in a block based on its key and value
struct Record* allocate_record(struct Block* block, int key, int value) {
  size_t record_size = sizeof(struct Record);
  char* buffer = block->buffer + (block->used * record_size);
  struct Record* record = (struct Record*)buffer;
  record->key = key;
  record->value = value;
  return record;
}

