    for (int i = 0; i < 100; i++) {
        if (string_pool[i] == NULL) {
            return string_pool[i];
        }
    }

    // If no free slots are found, return NULL to indicate failure
    return NULL;
}

// Function to release a previously allocated string identifier
void release_string(char *str) {
    // Find the corresponding slot in the string pool and mark it as unused
    for (int i = 0; i < 100; i++) {
        if (string_pool[i] == str) {
            string_pool[i] = NULL;
            break;
        }
    }
}

