    // If the reference count is zero, release the identifier
    if (record->refcount == 0) {
        release_string(record->data.identifier);
    }
}

// Function to iterate over all records and update their string identifiers
void update_string_identifiers(void) {
    // Iterate through the global record list and update each record's identifier
    for (struct record *record = get_first_record(); record != NULL; record = get_next_record()) {
        // If the record's identifier is not currently in use, request a new one from the string pool
        if (!is_string_in_use(record->data.identifier)) {
