    PROCESS_STATUS_T status;
    time_t timestamp;
} SYSTEM_PROCESS_INFO;

// Function to allocate and populate a new SYSTEM_PROCESS_INFO structure
SYSTEM_PROCESS_INFO* allocate_process(int num_processes) {
    // Allocate memory for the array of structures
    SYSTEM_PROCESS_INFO* processes = (SYSTEM_PROCESS_INFO*)malloc(sizeof(SYSTEM_PROCESS_INFO) * num_processes);
    if (!processes) {
        fprintf(stderr, "Error: Failed to allocate memory for process structures\n");
        return NULL;
    }

    // Initialize the array of structures with unique PROCESS_IDs and random statuses
    int i;
    for (i = 0; i < num_processes; i++) {
        processes[i].PROCESS_ID = get_unique_process_id();
        processes[i].status = get_random_process_status();
        processes[i].timestamp = time(NULL);
    }

    return processes;
}

// Function to check if a given PROCESS_ID has already been used in the current session
int is_duplicate_process_id(int process_id, SYSTEM_PROCESS_INFO* processes) {
    int i;
    for (i = 0; i < num_processes; i++) {
        if (processes[i].PROCESS_ID == process_id) {
            return 1;
        }
    }
    return 0;
}

// Function to generate a unique PROCESS_ID that has not been used before in the current session
int get_unique_process_id() {
    int process_id = rand() % (INT_MAX - INT_MIN) + INT_MIN;
    while (is_duplicate_process_id(process_id, processes)) {
        process_id = rand() % (INT_MAX - INT_MIN) + INT_MIN;
    }
    return process_id;
}

// Function to get a random status for a new process
