// Define a record structure that contains an integer key and a long offset value
typedef struct {
  int key;
  long offset;
} Record;

// Define a linked list node structure that holds a reference to the next node
typedef struct Node {
  Record *record;
  struct Node *next;
} Node;

// Define a hash table structure that stores a collection of records
typedef struct {
  int size;
  int capacity;
  int count;
  Node **buckets;
} HashTable;

// Initialize a new hash table with the given initial capacity
HashTable *init_hash_table(int capacity) {
  // Allocate memory for the hash table structure
  HashTable *ht = malloc(sizeof(HashTable));
  if (ht == NULL) {
    return NULL;
  }

  // Initialize the size, capacity, and count of the hash table
  ht->size = 0;
  ht->capacity = capacity;
  ht->count = 0;

  // Allocate memory for the buckets array
  ht->buckets = malloc(sizeof(Node *) * capacity);
  if (ht->buckets == NULL) {
    free(ht);
    return NULL;
  }

  // Initialize all buckets to null
  memset(ht->buckets, 0, sizeof(Node *) * capacity);

  return ht;
}

// Insert a new record into the hash table
int insert_record(HashTable *ht, int key, long offset) {
  // Check if the hash table is empty
  if (ht->size == 0) {
    // If so, allocate memory for the initial bucket
    ht->buckets[key % ht->capacity] = malloc(sizeof(Node));
    if (ht->buckets[key % ht->capacity] == NULL) {
      return -1;
    }
  } else {
    // If not, check if the key is already present in the hash table
    int index = key % ht->capacity;
    Node *node = ht->buckets[index];
    while (node != NULL) {
      if (node->record->key == key) {
        return 0;
      }
      node = node->next;
    }

    // If the key is not present, allocate memory for a new bucket
    ht->buckets[index] = malloc(sizeof(Node));
    if (ht->buckets[index] == NULL) {
      return -1;
    }
  }

  // Allocate memory for the record structure
  Record *record = malloc(sizeof(Record));
  if (record == NULL) {
    return -1;
  }

  // Initialize the record fields and insert it into the linked list
  record->key = key;
  record->offset = offset;
  Node *node = ht->buckets[index];
  node->record = record;
  node->next = NULL;

  // Increment the size of the hash table and count of records
  ht->size++;
  ht->count++;

  return 1;
}

// Search for a record in the hash table by key
Record *search_record(HashTable *ht, int key) {
  // Check if the hash table is empty
  if (ht->size == 0) {
    return NULL;
  }

  // Compute the index of the bucket for the given key
  int index = key % ht->capacity;

  // Search for the record in the linked list starting from the bucket
  Node *node = ht->buckets[index];
  while (node != NULL) {
    if (node->record->key == key) {
      return node->record;
    }
    node = node->next;
  }

  // If the record is not found, return null
  return NULL;
}

// Delete a record from the hash table by key
int delete_record(HashTable *ht, int key) {
  // Check if the hash table is empty
  if (ht->size == 0) {
    return 0;
  }

  // Compute the index of the bucket for the given key
  int index = key % ht->capacity;

  // Search for the record in the linked list starting from the bucket
  Node *node = ht->buckets[index];
  while (node != NULL) {
    if (node->record->key == key) {
      // If found, remove it from the linked list and free its memory
      Record *record = node->record;
      if (ht->count == 1) {
        free(ht->buckets[index]);
        ht->buckets[index] = NULL;
      } else {
        Node *prev = node->next;
        while (prev->next != NULL && prev->next->record->key != key) {
          prev = prev->next;
        }
        if (prev->next == NULL) {
          return 0;
        }
        free(prev->next);
        prev->next = NULL;
      }
      ht->count--;
      free(record);
      return 1;
    }
    node = node->next;
  }

  // If the record is not found, return null
  return 0;
}

// Resize the hash table to a new capacity
int resize_hash_table(HashTable *ht, int new_capacity) {
  // Check if the new capacity is larger than the current size
  if (new_capacity <= ht->size) {
    return -1;
  }

  // Allocate memory for the new buckets array
  Node **new_buckets = malloc(sizeof(Node *) * new_capacity);
  if (new_buckets == NULL) {
    return -1;
  }

  // Initialize all new buckets to null
  memset(new_buckets, 0, sizeof(Node *) * new_capacity);

  // Iterate over the old buckets and move each record to the corresponding new bucket
  for (int i = 0; i < ht->capacity; i++) {
    Node *node = ht->buckets[i];
    while (node != NULL) {
      int index = node->record->key % new_capacity;
      if (new_buckets[index] == NULL) {
        // Allocate memory for the first record in the new bucket
        new_buckets[index] = malloc(sizeof(Node));
        if (new_buckets[index] == NULL) {
          return -1;
        }
      } else {
        // Iterate over existing records in the new bucket to find a place for the current record
        Node *prev = new_buckets[index];
        while (prev->next != NULL && prev->next->record->key != node->record->key) {
          prev = prev->next;
        }
        if (prev->next == NULL) {
          // Allocate memory for the current record in the new bucket
          Node *new_node = malloc(sizeof(Node));
          if (new_node == NULL) {
            return -1;
          }
          prev->next = new_node;
        }
      }
      // Copy the current record into the new bucket
      Node *new_node = new_buckets[index];
      Record *record = malloc(sizeof(Record));
      if (record == NULL) {
        return -1;
      }
      record->key = node->record->key;
      record->offset = node->record->offset;
      new_node->record = record;
      new_node->next = NULL;
      ht->count--;
      node = node->next;
    }
  }

  // Free the old buckets array and set the new one
  free(ht->buckets);
  ht->buckets = new_buckets;
  ht->capacity = new_capacity;

  return 1;
}

// Print the contents of the hash table to the console
void print_hash_table(HashTable *ht) {
  for (int i = 0; i < ht->capacity; i++) {
    Node *node = ht->buckets[i];
    while (node != NULL) {
      Record *record = node->record;
      printf("%d ", record->key);
      node = node->next;
    }
  }
}

int main() {
