#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Structure definition
typedef struct {
    int RX_UE_INFORMATION_TAG;
    char *RNTI;
    int CRC_INDICATION_REL8_TAG;
} TX_POWER_REPORT_INDICATION_T;

// Function to manage dynamic array of structures
void mangeDynamicArray(int N) {
    // Allocate memory for up to N structures
    TX_POWER_REPORT_INDICATION_T **array = (TX_POWER_REPORT_INDICATION_T **)malloc(N * sizeof(TX_POWER_REPORT_INDICATION_T));
    if (!array) {
        // Handle allocation failure gracefully
        printf("Failed to allocate memory for dynamic array\n");
        return;
    }

    // Initialize array with invalid values
    memset(array, -1, N * sizeof(TX_POWER_REPORT_INDICATION_T));

    // Mutex to synchronize access to the array
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Function to check if RNTI is already in use
    int rntiInUse(const char *rnti) {
        for (int i = 0; i < N; ++i) {
            if (!strcmp(array[i]->RNTI, rnti)) {
                return true;
            }
        }
        return false;
    }

    // Function to allocate a new structure
    TX_POWER_REPORT_INDICATION_T *allocateStructure() {
        for (int i = 0; i < N; ++i) {
            if (!array[i]) {
                return array[i];
            }
        }
        // Handle allocation failure gracefully
        printf("Failed to allocate memory for new structure\n");
        return NULL;
    }

    // Function to insert a new RNTI in the array
    void insertRnti(const char *rnti) {
        pthread_mutex_lock(&mutex);
        TX_POWER_REPORT_INDICATION_T *structure = allocateStructure();
        if (structure) {
            structure->RNTI = rnti;
            pthread_mutex_unlock(&mutex);
        } else {
            pthread_mutex_unlock(&mutex);
            // Handle allocation failure gracefully
            printf("Failed to insert RNTI in the array\n");
        }
    }

    // Function to delete a RNTI from the array
    void deleteRnti(const char *rnti) {
        pthread_mutex_lock(&mutex);
        for (int i = 0; i < N; ++i) {
            if (!strcmp(array[i]->RNTI, rnti)) {
                array[i] = NULL;
                break;
            }
        }
        pthread_mutex_unlock(&mutex);
    }
}
