['```c++
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <cstdint>
#include <cmath>
#include <algorithm>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>

class DynamicFileHasher {
public:
    struct Record {
        uint64_t key;
        std::string hash;
    };

    DynamicFileHasher(const std::string& filePath, bool useFixedSizeBuffer) :
        _filePath(filePath), _useFixedSizeBuffer(useFixedSizeBuffer) {}

    void init() {
        // Initialize the vector of records
        _records.reserve(_numRecords);

        // Open the file and determine its size
        std::ifstream file(_filePath, std::ios::binary | std::ios::ate);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open file: " + _filePath);
        }
        auto fileSize = file.tellg();
        file.close();

        // Determine the number of records based on the file size and fixed buffer size
        if (_useFixedSizeBuffer) {
            _numRecords = std::ceil(fileSize / _fixedBufferSize);
        } else {
            _numRecords = 1;
        }
    }

    void computeHash() {
        // Initialize the progress counter and condition variable
        int progressCounter = 0;
        std::condition_variable cv;

        // Launch a thread to update the progress bar
        std::thread progressThread([&] {
            while (true) {
                std::unique_lock<std::mutex> lock(cv);
                cv.wait(lock, [&] { return progressCounter == _numRecords; });
                break;
            }

            // Update the progress bar
            std::cout << "Progress: " << progressCounter * 100 / _numRecords << "%\r";
        });

        // Compute the hash for each record
        auto start = std::chrono::high_resolution_clock::now();
        for (int i = 0; i < _numRecords; ++i) {
            // Read a chunk of the file and compute its SHA-256 hash
            std::string chunk;
            if (_useFixedSizeBuffer) {
                chunk = readFileChunk(_filePath, i * _fixedBufferSize);
            } else {
                chunk = readFileChunk(_filePath, 0, fileSize - (i * _fixedBufferSize));
            }
            std::string hash = computeHash(chunk);

            // Add the record to the vector of records
            _records.push_back({ i, hash });

            // Update the progress counter and notify the condition variable
            ++progressCounter;
            cv.notify_all();
        }
        auto end = std::chrono::high_resolution_clock::now();
        std::cout << "Processed " << _numRecords << " records in "
                  << std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count()
                  << " milliseconds" << std::endl;

        // Join the progress thread
        progressThread.join();
    }

    void getHash(int key) const {
        // Check if the record exists and return its hash
        if (key < _records.size()) {
            return _records[key].hash;
        } else {
            throw std::runtime_error("Invalid key: " + std::to_string(key));
        }
    }

private:
    // Read a chunk of the file based on its path and offset
    static std::string readFileChunk(const std::string& filePath, int64_t offset) {
        // Open the file and seek to the specified offset
        std::ifstream file(filePath, std::ios::binary);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open file: " + filePath);
        }
        file.seekg(offset, std::ios::beg);

        // Read the chunk of data and return it as a string
        std::string chunk;
        for (int i = 0; i < _fixedBufferSize; ++i) {
            char byte;
            if (!file.read(&byte, sizeof(char))) {
                break;
            }
            chunk += byte;
        }
        return chunk;
    }

    // Compute the SHA-256 hash of a string and return it as a hexadecimal string
    static std::string computeHash(const std::string& data) {
        // Use the SHA-256 algorithm to generate the hash
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256_CTX ctx;
        SHA256_Init(&ctx);
        SHA256_Update(&ctx, data.c_str(), data.size());
        SHA256_Final(hash, &ctx);

        // Convert the hash to a hexadecimal string
        std::stringstream ss;
        for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
            ss << std::hex << std::setfill('0') << std::setw(2) << static_cast<int>(hash[i]);
        }
        return ss.str();
    }

    // Members
    const std::string _filePath;
    const bool _useFixedSizeBuffer;
    const int _fixedBufferSize = 1024 * 1024; // 1 MB
    const int _numRecords;
    std::vector<std::pair<int, std::string>> _records;
};
