### Python

```python
import hashlib
import os

class SHA256:
    def __init__(self, file_path):
        self.file_path = file_path
        self.hashes = []

    def compute(self):
        with open(self.file_path, 'rb') as f:
            while True:
                data = f.read(1024 * 1024) # 1 MB
                if not data:
                    break
                hash = hashlib.sha256(data).hexdigest()
                self.hashes.append(hash)
        return self.hashes
