    @file_path = file_path
    @hashes = []
  end

  def compute
    File.open(@file_path, 'rb') do |f|
      while chunk = f.read(1024 * 1024) # 1 MB
        hash = Digest::SHA256.hexdigest(chunk)
        @hashes << hash
      end
    end
    @hashes
  end
