int num_entries = 0;
sem_t *entry_lock = NULL;

// Function to dynamically allocate and initialize an array of USER_CONTEXT_T structures for a specified number of users
USER_CONTEXT_T* allocate_user_contexts(int num_users) {
    // Allocate memory for the user contexts
    USER_CONTEXT_T* user_contexts = (USER_CONTEXT_T*)malloc(num_users * sizeof(USER_CONTEXT_T));
    if (!user_contexts) {
        return NULL;
    }

    // Initialize the user contexts
    for (int i = 0; i < num_users; ++i) {
        user_contexts[i].user_id = i + 1;
        user_contexts[i].session_id = 0;
        user_contexts[i].last_activity_timestamp = time(NULL);
    }

    return user_contexts;
}

// Function to dynamically allocate and initialize an array of entry structures for the hash table
entry* allocate_entries(int num_entries) {
    // Allocate memory for the entries
    entry* entries = (entry*)malloc(num_entries * sizeof(entry));
    if (!entries) {
        return NULL;
    }

    // Initialize the entries with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_entries; ++i) {
        char key[16];
        snprintf(key, sizeof(key), "%d", rand() % 1000);
        entries[i].key = strdup(key);
        entries[i].value = rand() % 1000;
    }

    return entries;
}

// Function to dynamically resize the array of entry structures for the hash table
int resize_entries(int new_num_entries) {
    // If the new number of entries is less than or equal to the current number of entries, do nothing
    if (new_num_entries <= num_entries) {
        return 0;
    }

    // Acquire the entry lock
    sem_wait(entry_lock);

    // Reallocate memory for the entries
    entry* new_entries = (entry*)realloc(entries, new_num_entries * sizeof(entry));
    if (!new_entries) {
        // Release the entry lock and return an error code
        sem_post(entry_lock);
        return -1;
    }
    entries = new_entries;

    // Initialize any newly allocated entries with random values within the specified range
    srand(time(NULL));
    for (int i = num_entries; i < new_num_entries; ++i) {
        char key[16];
        snprintf(key, sizeof(key), "%d", rand() % 1000);
        entries[i].key = strdup(key);
        entries[i].value = rand() % 1000;
    }

    num_entries = new_num_entries;

    // Release the entry lock and return success
    sem_post(entry_lock);
    return 0;
}

// Function to insert a key-value pair into the hash table
int insert_key_value(char* key, int value) {
    // If the key already exists in the hash table, do nothing and return success
    if (find_entry(key)) {
        return 0;
    }

    // Acquire the entry lock
    sem_wait(entry_lock);

    // Resize the array of entries if necessary to accommodate a new key-value pair
    int num_entries = resize_entries(num_entries + 1);
    if (num_entries < 0) {
        // Release the entry lock and return an error code
        sem_post(entry_lock);
        return -1;
    }

    // Add the key-value pair to the hash table
    entries[num_entries].key = strdup(key);
    entries[num_entries].value = value;

    // Release the entry lock and return success
    sem_post(entry_lock);
    return 0;
}

// Function to find an entry in the hash table by key
entry* find_entry(char* key) {
    // Acquire the entry lock
    sem_wait(entry_lock);

    // Search for the specified key in the hash table
    for (int i = 0; i < num_entries; ++i) {
        if (!strcmp(key, entries[i].key)) {
            // Release the entry lock and return the found entry
            sem_post(entry_lock);
            return &entries[i];
        }
    }

    // If no entry was found, release the entry lock and return NULL
    sem_post(entry_lock);
    return NULL;
}

// Function to remove an entry from the hash table by key
int remove_entry(char* key) {
    // Acquire the entry lock
    sem_wait(entry_lock);

    // Search for the specified key in the hash table
    int index = -1;
    for (int i = 0; i < num_entries; ++i) {
        if (!strcmp(key, entries[i].key)) {
            index = i;
            break;
        }
    }

    // If the key was not found, release the entry lock and return an error code
    if (index < 0) {
        sem_post(entry_lock);
        return -1;
    }

    // Remove the found entry from the hash table by shifting all subsequent entries one position to the left
    for (int i = index; i < num_entries - 1; ++i) {
        entries[i].key = entries[i + 1].key;
        entries[i].value = entries[i + 1].value;
    }

    // Resize the array of entries if necessary to remove the last entry
    int new_num_entries = num_entries - 1;
    resize_entries(new_num_entries);

    // Release the entry lock and return success
    sem_post(entry_lock);
    return 0;
}

// Function to print all entries in the hash table
void print_all_entries() {
    // Acquire the entry lock
    sem_wait(entry_lock);

    // Print all entries in the hash table
    for (int i = 0; i < num_entries; ++i) {
        printf("%s: %d\n", entries[i].key, entries[i].value);
    }

    // Release the entry lock and return success
    sem_post(entry_lock);
}

// Function to free all memory allocated by the hash table
void free_hash_table() {
    // Acquire the entry lock
    sem_wait(entry_lock);

    // Free all entries in the hash table
    for (int i = 0; i < num_entries; ++i) {
        free(entries[i].key);
    }

    // Release the entry lock and return success
    sem_post(entry_lock);
}

