    insert_key_value("apple", 5);
    insert_key_value("banana", 20);
    insert_key_value("orange", 3);
    insert_key_value("grape", 4);
    insert_key_value("pineapple", 10);

    // Find an entry in the hash table by key
    entry* apple = find_entry("apple");
