// Define function to manage dynamic array of ORDER_RECORD_T structures
int manage_orders(ORDER_RECORD_T** orders, int max_orders) {
    // Check if memory allocation fails or duplicate order ID is detected
    if (!*orders || !(*orders = realloc(*orders, sizeof(ORDER_RECORD_T) * (max_orders + 1)))) {
        return -1;
    }

    // Allocate new ORDER_ID if duplicate is detected within time frame
    int current_order_id = 0;
    while (current_order_id < max_orders && (*orders)[current_order_id].order_id != 0) {
        current_order_id++;
    }
    if (current_order_id == max_orders) {
        return -1;
    }
    int new_order_id = current_order_id + 1;

    // Initialize new ORDER_RECORD_T structure and assign new ORDER_ID
    (*orders)[new_order_id] = (ORDER_RECORD_T) {0};
    (*orders)[new_order_id].order_id = new_order_id;

    return 0;
}

