int numElements = 0; // Number of elements in the array
pthread_mutex_t mutex; // Mutex for thread-safe access to the array

// Function to allocate memory for the array and populate it with random values
void initArray(int N) {
    // Allocate memory for the array
    array = (TX_POWER_REPORT_INDICATION_T*)malloc(sizeof(TX_POWER_REPORT_INDICATION_T)*N);
    numElements = N;

    // Initialize the mutex for thread-safe access to the array
    pthread_mutex_init(&mutex, NULL);

    // Populate the array with random values
    srand(time(NULL));
    for (int i=0; i<N; i++) {
        // Generate a unique RNTI value
        int RNTI = rand();
        while (RNTI == 0) {
            RNTI = rand();
        }

        // Set the RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG values randomly
        array[i].RX_UE_INFORMATION_TAG = i;
        array[i].CRC_INDICATION_REL8_TAG = rand()%100;

        // Set the RNTI value for this element
        array[i].RNTI = RNTI;
    }
}

// Function to check if a given RNTI value exists in the array
bool contains(int RNTI) {
    bool found = false;

    // Lock the mutex to ensure thread-safe access to the array
    pthread_mutex_lock(&mutex);

    // Iterate over each element in the array
    for (int i=0; i<numElements; i++) {
        if (array[i].RNTI == RNTI) {
            found = true;
            break;
        }
    }

    // Unlock the mutex when done
    pthread_mutex_unlock(&mutex);

    return found;
}

// Function to add a new element to the array with a unique RNTI value and random CRC indication
void addElement(int RX_UE_INFORMATION_TAG, int CRC_INDICATION_REL8_TAG) {
    // Lock the mutex to ensure thread-safe access to the array
    pthread_mutex_lock(&mutex);

    // Generate a unique RNTI value
    int RNTI = rand();
    while (RNTI == 0) {
        RNTI = rand();
    }

    // Set the RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG values randomly
    TX_POWER_REPORT_INDICATION_T newElement;
    newElement.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newElement.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    // Set the RNTI value for this element
    newElement.RNTI = RNTI;

    // Add the new element to the array
    array[numElements++] = newElement;

    // Unlock the mutex when done
    pthread_mutex_unlock(&mutex);
}

// Function to remove an element from the array with a given RNTI value
void removeElement(int RNTI) {
    // Lock the mutex to ensure thread-safe access to the array
    pthread_mutex_lock(&mutex);

    // Iterate over each element in the array
    for (int i=0; i<numElements; i++) {
        if (array[i].RNTI == RNTI) {
            // Shift all elements after this one to fill the gap
            for (int j=i; j<numElements-1; j++) {
                array[j] = array[j+1];
            }

            // Decrement the number of elements in the array
            numElements--;

            // Unlock the mutex when done
            pthread_mutex_unlock(&mutex);

            return;
        }
    }

    // Unlock the mutex when done
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve an element from the array with a given RNTI value
TX_POWER_REPORT_INDICATION_T* getElement(int RNTI) {
    // Lock the mutex to ensure thread-safe access to the array
    pthread_mutex_lock(&mutex);

    // Iterate over each element in the array
    for (int i=0; i<numElements; i++) {
        if (array[i].RNTI == RNTI) {
            // Unlock the mutex and return the element
            pthread_mutex_unlock(&mutex);
            return &array[i];
        }
    }

    // If the element was not found, unlock the mutex and return NULL
    pthread_mutex_unlock(&mutex);
    return NULL;
}

// Function to destroy the array and free its memory
void destroyArray() {
    // Lock the mutex to ensure thread-safe access to the array
    pthread_mutex_lock(&mutex);

    // Free the memory allocated for the array
    free(array);

    // Set the number of elements in the array to 0
