// Define a struct to represent a network packet
typedef struct {
    unsigned char* data; // Pointer to the packet data
    size_t length; // Length of the packet data
} NetworkPacket;

// Define a struct to represent a dynamic array of network packets
typedef struct {
    NetworkPacket* packets; // Array of network packets
    size_t count; // Number of packets in the array
    size_t capacity; // Maximum number of packets that can be stored in the array
} PacketArray;

// Function to allocate memory for a new packet and add it to the end of the array
void AddPacket(PacketArray* arr, const unsigned char* data, size_t length) {
    // Check if there is enough capacity to store the new packet
    if (arr->count == arr->capacity) {
        // Reallocate memory for the array with a larger capacity
        arr->packets = realloc(arr->packets, sizeof(NetworkPacket) * arr->capacity * 2);
        if (!arr->packets) {
            printf("Error: Out of memory\n");
            return;
        }
        // Update the new capacity
        arr->capacity *= 2;
    }

    // Allocate memory for the new packet
    NetworkPacket* packet = malloc(sizeof(NetworkPacket));
    if (!packet) {
        printf("Error: Out of memory\n");
        return;
    }
    // Copy the packet data into the newly allocated memory
    packet->data = malloc(length);
    if (!packet->data) {
        free(packet);
        printf("Error: Out of memory\n");
        return;
    }
    memcpy(packet->data, data, length);
    packet->length = length;

    // Add the new packet to the end of the array
    arr->packets[arr->count++] = *packet;
}

// Function to deallocate memory for a specific packet in the array
void RemovePacket(PacketArray* arr, size_t index) {
    // Check if the specified index is valid
    if (index >= arr->count) {
        printf("Error: Invalid index\n");
        return;
    }

    // Deallocate memory for the packet data and the packet struct itself
    NetworkPacket* packet = &arr->packets[index];
    free(packet->data);
    free(packet);

    // Shift all subsequent packets down one index to fill the gap
    memmove(&arr->packets[index], &arr->packets[index + 1], sizeof(NetworkPacket) * (arr->count - index - 1));
}

// Function to remove all packets from the array
void ClearPackets(PacketArray* arr) {
    // Deallocate memory for each packet in the array
    for (size_t i = 0; i < arr->count; ++i) {
        RemovePacket(arr, i);
    }

    // Reset the count and capacity of the array
    arr->count = 0;
    arr->capacity = 16;
}

// Function to handle network packets and maintain the packet array
void HandlePackets(PacketArray* arr, const unsigned char* data, size_t length) {
    // Check if there is enough capacity to store the new packet
    if (arr->count == arr->capacity) {
        // Reallocate memory for the array with a larger capacity
        arr->packets = realloc(arr->packets, sizeof(NetworkPacket) * arr->capacity * 2);
        if (!arr->packets) {
            printf("Error: Out of memory\n");
            return;
        }
        // Update the new capacity
        arr->capacity *= 2;
    }

    // Allocate memory for the new packet
    NetworkPacket* packet = malloc(sizeof(NetworkPacket));
    if (!packet) {
        printf("Error: Out of memory\n");
        return;
    }
    // Copy the packet data into the newly allocated memory
    packet->data = malloc(length);
    if (!packet->data) {
        free(packet);
        printf("Error: Out of memory\n");
        return;
    }
    memcpy(packet->data, data, length);
    packet->length = length;

    // Add the new packet to the end of the array
    arr->packets[arr->count++] = *packet;
}

// Function to retrieve a specific packet from the array by index
NetworkPacket* GetPacket(PacketArray* arr, size_t index) {
    // Check if the specified index is valid
    if (index >= arr->count) {
        printf("Error: Invalid index\n");
        return NULL;
    }

    return &arr->packets[index];
}

// Function to retrieve all packets from the array
NetworkPacket** GetAllPackets(PacketArray* arr) {
    // Create an array of packet pointers and populate it with the packets in the array
    NetworkPacket** packets = malloc(sizeof(NetworkPacket*) * arr->count);
    for (size_t i = 0; i < arr->count; ++i) {
        packets[i] = &arr->packets[i];
    }

    return packets;
}

// Function to retrieve the number of packets in the array
size_t GetPacketCount(PacketArray* arr) {
    return arr->count;
}
