// Modular C function for managing a dynamic cache of up to 5000 unique records
void cacheManager(int key, long offset, double value, char* metadata) {
    // Check if the record already exists in the cache
    if (recordExists(key)) {
        // Update the existing record with the new values
        updateRecord(key, offset, value, metadata);
    } else {
        // Insert a new record into the cache
        insertNewRecord(key, offset, value, metadata);
    }
}

// Check if a record exists in the cache by searching for its key
bool recordExists(int key) {
    // Iterate through all records in the cache and check if the key matches
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].key == key) {
            return true;
        }
    }
    return false;
}

// Update an existing record in the cache with new values
void updateRecord(int key, long offset, double value, char* metadata) {
    // Iterate through all records in the cache and find the one to update
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].key == key) {
            cache[i].offset = offset;
            cache[i].value = value;
            cache[i].metadata = metadata;
            return;
        }
    }
}

// Insert a new record into the cache with unique key and values
void insertNewRecord(int key, long offset, double value, char* metadata) {
    // Check if the cache is full and needs to be resized
    if (cacheFull()) {
        resizeCache();
    }
    // Add the new record to the end of the cache
    cache[cacheSize++] = {key, offset, value, metadata};
}

// Resize the cache by doubling its capacity
void resizeCache() {
    // Create a new array with twice the size of the current cache
    int newCapacity = 2 * CACHE_SIZE;
    Record* newCache = (Record*) malloc(newCapacity * sizeof(Record));
    // Copy all records from the old cache to the new one
    for (int i = 0; i < cacheSize; i++) {
        newCache[i] = cache[i];
    }
    free(cache);
    cache = newCache;
    CACHE_SIZE = newCapacity;
}

// Check if the cache is full by comparing its size to its capacity
bool cacheFull() {
    return cacheSize == CACHE_SIZE;
}

// Compression algorithm for metadata strings
void compressMetadata(char* metadata) {
    // Split the metadata string into a vector of words
    char* words[MAX_METADATA_WORDS];
    int wordCount = splitString(metadata, " ", MAX_METADATA_WORDS, words);
    // Remove stop words from the vector
    removeStopWords(words, wordCount);
    // Join the remaining words into a new metadata string
    char* compressedMetadata = joinStrings(words, wordCount, " ");
    return compressedMetadata;
}

// Decompression algorithm for metadata strings
void decompressMetadata(char* compressedMetadata) {
    // Split the compressed metadata string into a vector of words
    char* words[MAX_METADATA_WORDS];
    int wordCount = splitString(compressedMetadata, " ", MAX_METADATA_WORDS, words);
    // Add the words to the metadata string
    for (int i = 0; i < wordCount; i++) {
        addWordToMetadata(words[i]);
    }
}

// Split a string into a vector of substrings by delimiter
int splitString(char* str, char delim, int maxWords, char** words) {
    // Initialize the word count and current position in the string
    int wordCount = 0;
    int pos = 0;
    // Iterate through the string until the end is reached
    while (pos < strlen(str)) {
        // Find the next delimiter or end of the string
        int nextDelim = findNextDelimiter(str, delim, pos);
        // Add the substring to the vector of words
        char* word = substr(str, pos, nextDelim - pos);
        words[wordCount++] = word;
        if (wordCount == maxWords) {
            break;
        }
        // Update the position to continue searching from the delimiter
        pos = nextDelim + 1;
    }
    return wordCount;
}

// Find the next occurrence of a delimiter in a string starting from a given position
int findNextDelimiter(char* str, char delim, int start) {
    // Iterate through the string until the end is reached
    for (int i = start; i < strlen(str); i++) {
        if (str[i] == delim) {
            return i;
        }
    }
