// Join a vector of substrings into a single string by delimiter
char* joinStrings(char** words, int wordCount, char delim) {
    // Calculate the length of the resulting string
    int len = 0;
    for (int i = 0; i < wordCount; i++) {
        len += strlen(words[i]);
    }
    // Create a new string with the combined length
    char* str = (char*) malloc((len + wordCount - 1) * sizeof(char));
    // Iterate through the words and add them to the string
    for (int i = 0; i < wordCount; i++) {
        if (i > 0) {
            strcat(str, &delim);
        }
        strcat(str, words[i]);
    }
    return str;
}

// Add a word to the metadata string
void addWordToMetadata(char* word) {
    // Concatenate the word with the existing metadata string
    char* newMetadata = (char*) malloc((strlen(metadata) + strlen(word)) * sizeof(char));
    if (metadata != NULL) {
        strcpy(newMetadata, metadata);
        free(metadata);
    }
    strcat(newMetadata, word);
    metadata = newMetadata;
}

// Remove stop words from a vector of substrings
void removeStopWords(char** words, int wordCount) {
    // Create a set of stop words
    char* stopWords[] = {"the", "a", "an"};
    // Iterate through the words and remove any that are in the stop word list
    for (int i = 0; i < wordCount; i++) {
        for (int j = 0; j < sizeof(stopWords) / sizeof(char*); j++) {
            if (strcmp(words[i], stopWords[j]) == 0) {
                words[i] = NULL;
                break;
            }
        }
    }
}']

