void alloc_nfapi_crc_indication_pdu(int n) {
    // Check if the input value is valid
    if (n <= 0) {
        printf("Error: Invalid input value for 'n'. Must be a positive integer.\n");
        return;
    }

    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (!pdu) {
        printf("Error: Failed to allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures.\n");
        return;
    }

    // Initialize the array with a random CRCFLAG value and populate each structure with a valid RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        // Generate a random CRCFLAG value
        uint32_t crcflag = rand() % 1000 + 1;

        // Allocate memory for the RX_UE_INFORMATION_TAG structure
        pdu[i].rx_ue_information_tag = (RX_UE_INFORMATION_TAG *)malloc(sizeof(RX_UE_INFORMATION_TAG));
        if (!pdu[i].rx_ue_information_tag) {
            printf("Error: Failed to allocate memory for the RX_UE_INFORMATION_TAG structure.\n");
            free(pdu);
            return;
        }

        // Populate the RX_UE_INFORMATION_TAG structure with a valid value
        pdu[i].rx_ue_information_tag->rx_indication = 10;

        // Allocate memory for the CRC_INDICATION_REL8_TAG structure
        pdu[i].crc_indication_rel8_tag = (CRC_INDICATION_REL8_TAG *)malloc(sizeof(CRC_INDICATION_REL8_TAG));
        if (!pdu[i].crc_indication_rel8_tag) {
            printf("Error: Failed to allocate memory for the CRC_INDICATION_REL8_TAG structure.\n");
            free(pdu);
            return;
        }

        // Populate the CRC_INDICATION_REL8_TAG structure with a valid value
        pdu[i].crc_indication_rel8_tag->crflag = crcflag;
    }

    // Validate that all RNTI values are unique within the array
    int rnti_count[10] = {0};
    for (int i = 0; i < n; i++) {
        if (rnti_count[pdu[i].rnti]) {
            printf("Error: Duplicate RNTI value found in the array. Reallocating memory to exclude duplicates.\n");

            // Reallocate memory to exclude duplicates and re-populate the array accordingly
            NFAPI_CRC_INDICATION_PDU_T *new_pdu = (NFAPI_CRC_INDICATION_PDU_T *)realloc(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (n - rnti_count[pdu[i].rnti]));
            if (!new_pdu) {
                printf("Error: Failed to reallocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures.\n");
                free(pdu);
                return;
            }
            pdu = new_pdu;
            n -= rnti_count[pdu[i].rnti];
        } else {
            rnti_count[pdu[i].rnti]++;
        }
    }

    // Ensure that memory allocation is performed efficiently and handle potential errors gracefully
    if (n < 0) {
        printf("Error: Invalid input value for 'n'. Must be a positive integer.\n");
        free(pdu);
        return;
    } else if (n == 0) {
        printf("Warning: No memory allocated for the array of NFAPI_CRC_INDICATION_PDU_T structures. Returning NULL.\n");
        pdu = NULL;
    }

    // Ensure that the array of NFAPI_CRC_INDICATION_PDU_T structures is freed when it is no longer needed
    if (pdu) {
        for (int i = 0; i < n; i++) {
            free(pdu[i].rx_ue_information_tag);
            free(pdu[i].crc_indication_rel8_tag);
        }
        free(pdu);
    }
}

