    for (int i = 0; i < num_records; i++) {
        printf("%d\n", keys[i]);
    }

    // Print the array of records
    printf("Array of records:\n");
    for (int i = 0; i < num_records; i++) {
        printf("%ld, %d, %d\n", records[i].timestamp, records[i].status_flag, records[i].integer_value);
    }
}
