    scanf("%d", &size);

    // Allocate memory for the file data
    data = (char*)malloc(size * sizeof(char));
    if (data == NULL) {
      handleMemoryAllocationFailure();
      return 1;
    }

    // Read the file data from disk
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
      printf("Error: Failed to open file\n");
      return 1;
    }
    size_t bytesRead = fread(data, sizeof(char), size, file);
    if (bytesRead != size) {
      printf("Error: Failed to read from file\n");
      return 1;
    }

    // Upload the file data to the server
    int res = uploadFile(filename, size, data);
    if (res != 0) {
      handleCurlError("Failed to upload file");
      return 1;
    }

    // Download the uploaded file from the server
    res = downloadFile(filename, data);
    if (res != 0) {
      handleCurlError("Failed to download file");
      return 1;
    }

    // List all available files on the server
    res = listFiles();
    if (res != 0) {
      handleCurlError("Failed to list files");
      return 1;
    }

    // Clean up memory and resources
    cleanUp();

    return 0;
  }
