// Helper function to find the largest integer in an array
int largest_integer(integer_array_t *arr) {
    if (arr->size == 0) return INT_MIN; // No integers, return smallest possible value
    int largest = arr->data[0];
    for (int i = 1; i < arr->size; i++) {
        if (arr->data[i] > largest) largest = arr->data[i];
    }
    return largest;
