    std::string filename;
    size_t filesize;
};

// Memory block structure
struct MemoryBlock {
    void* data;
    size_t size;
};

// Global variables
std::vector<FileMetadata> file_metadata;
std::map<std::string, MemoryBlock> memory_blocks;
std::mutex memory_lock;
std::condition_variable memory_cond;

// Function to handle HTTP POST requests for uploading files
void upload_file(const std::string& filename, const char* data, size_t length) {
    // Acquire lock on memory block list
    std::lock_guard<std::mutex> lock(memory_lock);

    // Check if file already exists in metadata
    auto it = std::find_if(file_metadata.begin(), file_metadata.end(), [&](const FileMetadata& m) {
        return m.filename == filename;
    });

    // If file does not exist, create a new entry in metadata and memory blocks
    if (it == file_metadata.end()) {
        FileMetadata meta = {filename, length};
        memory_blocks[filename] = MemoryBlock{data, length};
        file_metadata.push_back(meta);
    } else { // If file already exists, update its metadata and memory block
        it->filesize += length;
        memory_blocks[filename].size += length;
    }
}

// Function to handle HTTP GET requests for downloading files
void download_file(const std::string& filename) {
    // Acquire lock on memory block list
    std::lock_guard<std::mutex> lock(memory_lock);

    // Check if file exists in metadata and memory blocks
    auto it = std::find_if(file_metadata.begin(), file_metadata.end(), [&](const FileMetadata& m) {
        return m.filename == filename;
    });

    if (it != file_metadata.end()) { // If file exists, stream its contents to the client
        auto block = memory_blocks[filename];
        std::ostringstream oss;
        oss << block.data;
        send_file(oss.str().c_str(), block.size);
    } else { // If file does not exist, return a 404 response
        return 404;
    }
}

// Function to handle HTTP OPTIONS requests for listing files
void list_files() {
    // Acquire lock on memory block list
    std::lock_guard<std::mutex> lock(memory_lock);

    // Return a list of all file metadata in the system
    send_json(file_metadata.data(), file_metadata.size());
}

// Function to handle HTTP DELETE requests for deleting files
void delete_file(const std::string& filename) {
    // Acquire lock on memory block list
    std::lock_guard<std::mutex> lock(memory_lock);

    // Check if file exists in metadata and memory blocks
    auto it = std::find_if(file_metadata.begin(), file_metadata.end(), [&](const FileMetadata& m) {
        return m.filename == filename;
    });

    if (it != file_metadata.end()) { // If file exists, remove its metadata and memory block
        it = file_metadata.erase(it);
        memory_blocks.erase(filename);
    } else { // If file does not exist, return a 404 response
        return 404;
    }
}

// Function to handle memory allocation failures gracefully
void handle_memory_allocation_failure() {
    std::cout << "Memory allocation failure detected." << std::endl;
}

int main() {
    // Start the Java-based service management component in a separate thread
    std::thread java_service(start_java_service);

    // Create HTTP server with 10 threads for handling concurrent requests
    HttpServer server(NUM_THREADS);

    // Add HTTP routes for file uploads, downloads, and listings
    server.addRoute("/upload", &upload_file);
    server.addRoute("/download", &download_file);
    server.addRoute("/list", &list_files);
    server.addRoute("/delete", &delete_file);

    // Start the HTTP server and listen for incoming requests
    server.start();

    // Wait for Java-based service management component to stop
    java_service.join();

    return 0;
}
