        if (entry->d_type == DT_REG && strcmp(entry->d_name + strlen(entry->d_name) - 4, ".jpg") == 0) {
            char *filename = (char *)malloc(strlen(entry->d_name));
            if (!filename) {
                printf("Error: unable to allocate memory for filename\n");
                continue;
            }
            strcpy(filename, entry->d_name);

            // Dynamically allocate memory for the image filenames based on the number of images read
            char **imageFilenames = (char **)malloc((numImages + 1) * sizeof(char *));
            if (!imageFilenames) {
                printf("Error: unable to allocate memory for image filenames\n");
                continue;
            }

            // Dynamically allocate memory for the data points and initialize them with sequentially increasing timestamps and randomly generated floating-point values within the specified range
            struct dataPoint *dataPoints = (struct dataPoint *)malloc(numImages * sizeof(struct dataPoint));
