#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG *rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_CRC_INDICATION_ARRAY {
    size_t capacity;
    size_t count;
    pthread_mutex_t *lock;
    NFAPI_CRC_INDICATION_PDU_T *elements;
} NFAPI_CRC_INDICATION_ARRAY;

static void init_array(NFAPI_CRC_INDICATION_ARRAY *array) {
    array->capacity = 1024;
    array->count = 0;
    array->lock = (pthread_mutex_t *) malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(array->lock, NULL);
    array->elements = (NFAPI_CRC_INDICATION_PDU_T *) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * array->capacity);
}

static void destroy_array(NFAPI_CRC_INDICATION_ARRAY *array) {
    pthread_mutex_destroy(array->lock);
    free(array->elements);
    free(array->lock);
}

static int add_element(NFAPI_CRC_INDICATION_ARRAY *array, RX_UE_INFORMATION_TAG *rx_ue_information, RNTI rnti) {
    pthread_mutex_lock(array->lock);
    if (array->count == array->capacity) {
        // Expand the array if it is full
        NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T *) realloc(array->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * 2 * array->capacity);
        if (!new_elements) {
            pthread_mutex_unlock(array->lock);
            return -1;
        }
        array->elements = new_elements;
        array->capacity *= 2;
    }
    // Insert the element at the end of the array
    array->elements[array->count].rx_ue_information = rx_ue_information;
    array->elements[array->count].rnti = rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    // Generate a random seed for reproducibility
    unsigned int seed = rand();
    crc_indication.CRCFlag = (seed % 2 == 0) ? true : false;
    array->elements[array->count].crc_indication = crc_indication;
    array->count++;
    pthread_mutex_unlock(array->lock);
    return 0;
}

static int remove_element(NFAPI_CRC_INDICATION_ARRAY *array, size_t index) {
    if (index >= array->count) {
        // Out of bounds
        return -1;
    }
    pthread_mutex_lock(array->lock);
    // Shift the elements after the removed element to fill the gap
    memmove(&array->elements[index], &array->elements[index + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (array->count - index));
    array->count--;
    pthread_mutex_unlock(array->lock);
    return 0;
}

static NFAPI_CRC_INDICATION_PDU_T *get_element(NFAPI_CRC_INDICATION_ARRAY *array, size_t index) {
    if (index >= array->count) {
        // Out of bounds
        return NULL;
    }
    pthread_mutex_lock(array->lock);
    NFAPI_CRC_INDICATION_PDU_T *element = &array->elements[index];
    pthread_mutex_unlock(array->lock);
    return element;
}

static void clear_array(NFAPI_CRC_INDICATION_ARRAY *array) {
    pthread_mutex_lock(array->lock);
    array->count = 0;
    pthread_mutex_unlock(array->lock);
}

static int expand_array(NFAPI_CRC_INDICATION_ARRAY *array, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T *) realloc(array->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (!new_elements) {
        return -1;
    }
    array->elements = new_elements;
    array->capacity = new_capacity;
    return 0;
}

static int compress_array(NFAPI_CRC_INDICATION_ARRAY *array, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T *) realloc(array->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (!new_elements) {
        return -1;
    }
    array->elements = new_elements;
    array->capacity = new_capacity;
    return 0;
}

static int garbage_collect(NFAPI_CRC_INDICATION_ARRAY *array, size_t threshold) {
    if (array->count <= threshold) {
        // There are enough elements to avoid garbage collection
        return 0;
    }
    // Sort the array by age or frequency of access
    qsort(array->elements, array->count, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare);
    int removed = 0;
    for (size_t i = threshold; i < array->count; i++) {
        // Remove elements that are older than the threshold or have not been accessed recently enough
        remove_element(array, i - removed);
        removed++;
    }
    return 0;
}

static int compare(const void *a, const void *b) {
    const NFAPI_CRC_INDICATION_PDU_T *element1 = a;
    const NFAPI_CRC_INDICATION_PDU_T *element2 = b;
    // Sort by age or frequency of access
    return element1->age - element2->age;
}
