void dynamic_memory_manager(int num_records, int* keys, long** offsets, void*** records) {
  // Set memory constraints
  const size_t MAX_MEMORY = 1024 * 1024; // 1 MB
  const size_t MIN_OFFSET_SIZE = 512;
  const size_t MIN_KEYS_SIZE = 64;
  const size_t MAX_RECORD_SIZE = 1024 * 32; // 32 KB

  // Validate input parameters
  if (num_records < 0 || num_records > 10000) {
    return -1;
  }

  // Allocate memory for offset and keys arrays
  size_t offset_size = MAX(MIN_OFFSET_SIZE, MIN(MAX_MEMORY / num_records, MAX_RECORD_SIZE));
  size_t keys_size = MAX(MIN_KEYS_SIZE, MIN(offset_size * 2, MAX_RECORD_SIZE));
  long* offsets = malloc(offset_size * sizeof(long));
  int* keys = malloc(keys_size * sizeof(int));
  if (offsets == NULL || keys == NULL) {
    return -1;
  }

  // Initialize offset and keys arrays
  for (int i = 0; i < num_records; i++) {
    offsets[i] = rand() % MAX_RECORD_SIZE + MIN_OFFSET_SIZE;
    keys[i] = rand();
  }

  // Allocate memory for records array
  size_t record_size = MAX(MIN_RECORD_SIZE, offset_size);
  void** records = malloc(record_size * sizeof(void*));
  if (records == NULL) {
    return -1;
  }

  // Initialize records array
  for (int i = 0; i < num_records; i++) {
    records[i] = malloc(offsets[i]);
    if (records[i] == NULL) {
      return -1;
    }
  }

  // Seed random number generator
  srand((unsigned int) time(NULL));

  // Generate random numbers for offsets and keys
  for (int i = 0; i < num_records; i++) {
    offsets[i] = rand() % MAX_RECORD_SIZE + MIN_OFFSET_SIZE;
    keys[i] = rand();
  }

  // Clean up memory
  for (int i = 0; i < num_records; i++) {
    free(records[i]);
  }
  free(offsets);
  free(keys);
  free(records);

  return 0;
}
