int integrate_dns(const char* hostname, struct record** records, size_t* record_count) {
    // Check input parameters
    if (hostname == NULL || records == NULL || record_count == NULL) {
        return -1;
    }

    // Initialize variables
    int ret = 0;
    int sockfd = 0;
    struct addrinfo hints, *res;
