    if (ret != 0) {
        fprintf(stderr, "getaddrinfo() failed: %s\n", gai_strerror(ret));
        return -1;
    }

    // Allocate memory for IP addresses and offset values
    struct in_addr** ip_addrs = (struct in_addr**)malloc(sizeof(struct in_addr*) * res->ai_addrlen);
    if (ip_addrs == NULL) {
        fprintf(stderr, "Failed to allocate memory for IP addresses\n");
        return -1;
    }

    long* offset_values = (long*)malloc(sizeof(long) * res->ai_addrlen);
    if (offset_values == NULL) {
        fprintf(stderr, "Failed to allocate memory for offset values\n");
        return -1;
    }

    // Initialize arrays of records
    struct record* rec_arr = (struct record*)malloc(sizeof(struct record) * res->ai_addrlen);
    if (rec_arr == NULL) {
        fprintf(stderr, "Failed to allocate memory for record array\n");
        return -1;
    }

    // Fill arrays with random integers within a specified range
    srand(time(NULL));
    for (int i = 0; i < res->ai_addrlen; ++i) {
        ip_addrs[i] = (struct in_addr*)malloc(sizeof(struct in_addr));
        if (ip_addrs[i] == NULL) {
            fprintf(stderr, "Failed to allocate memory for IP address %d\n", i);
            return -1;
        }
        rec_arr[i].value = rand() % 100 + 1;
    }

    // Close socket and free resources on failure
    if (sockfd > 0) {
        close(sockfd);
    }
    if (ip_addrs != NULL) {
        for (int i = 0; i < res->ai_addrlen; ++i) {
            if (ip_addrs[i] != NULL) {
                free(ip_addrs[i]);
            }
        }
    }
    if (offset_values != NULL) {
        free(offset_values);
    }
    if (rec_arr != NULL) {
        free(rec_arr);
    }

    // Return success or failure depending on input parameters
    if (hostname == NULL || records == NULL || record_count == NULL) {
        return -1;
    } else {
        *records = rec_arr;
        *record_count = res->ai_addrlen;
        return 0;
    }
}
