void add_item(int id, char* name, int quantity) {
    // Check if the array is full and needs to be resized
    if (num_items == max_items) {
        max_items *= 2; // Double the maximum number of items
        items = realloc(items, max_items * sizeof(item_t));
        assert(items != NULL);
    }

    // Add the new item to the array
    items[num_items].id = id;
    items[num_items].name = strdup(name);
    items[num_items].quantity = quantity;
    num_items++;
}

// Function to retrieve an item from the collection by index
item_t* get_item(size_t index) {
    if (index >= num_items) return NULL;
    return &items[index];
}

// Function to remove an item from the collection by value
bool remove_item(int id) {
    // Find the index of the item with the specified ID
    size_t i = 0;
    for (; i < num_items; i++) {
        if (items[i].id == id) break;
    }

    // Check if the item was found and remove it from the array
    if (i < num_items) {
        free(items[i].name);
        memmove(&items[i], &items[i + 1], (num_items - i - 1) * sizeof(item_t));
        num_items--;
        return true;
    } else {
        return false;
    }
}

// Function to calculate the average CRCFLAG value across all structures in the array
double get_average_crcflag() {
    if (num_items == 0) return -1; // Return -1 if the array is empty

    double sum = 0;
    for (size_t i = 0; i < num_items; i++) {
        sum += items[i].crcflag;
    }
    return sum / num_items;
}

// Function to free all allocated memory when the function is no longer in use
void cleanup() {
    // Free each item's name string and then the array of items itself
    for (size_t i = 0; i < num_items; i++) {
        free(items[i].name);
