        // Handle memory allocation failure
        return;
    }

    // Populate the arrays with random integers within the specified range
    for (int i = 0; i < num_records; i++) {
        long offset = rand() % max_value;
        int key = rand() % max_value;

        (*offsets)[i] = offset;
        (*keys)[i] = key;

        record_t* record = malloc(sizeof(record_t));
        if (record == NULL) {
            // Handle memory allocation failure
            return;
        }

        (*records)[i] = record;
        (*record)->value = rand() % max_value;
    }
}

// Function to handle potential DNS resolution failures gracefully, returning an appropriate error code.
// Ensure that all dynamically allocated memory is properly managed to prevent leaks, considering both success and failure scenarios.
int resolve_hostname_with_retry(const char* hostname, size_t* num_ips) {
    // Initialize the return value
    *num_ips = 0;

    // Retry logic with exponential backoff
    int retries = 5;
    while (retries > 0) {
        char** ips = resolve_hostname(hostname, num_ips);

        if (ips == NULL) {
            free(*num_ips * sizeof(char*));

            // Sleep for a random amount of time before retrying
            int sleep_time = rand() % 10;
            printf("DNS resolution failed. Retrying in %d seconds...\n", sleep_time);
            sleep(sleep_time);
        } else {
            return ips;
        }

        retries--;
    }

    // Handle DNS resolution failure after all retries have been exhausted
    printf("DNS resolution failed. Giving up.\n");
    return NULL;
}
