class InsertAfterFirstOccurrence {
public:
    // Constructor to initialize the forward list and other parameters.
    InsertAfterFirstOccurrence(std::forward_list<std::string>& flist, const std::string& first_str, const std::string& insertion_str) : 
        flist_(flist), first_str_(first_str), insertion_str_(insertion_str) {}

    // Function to search for the first occurrence of the first string argument within the forward list.
    // If found, it inserts the third string argument immediately after it.
    // Otherwise, it appends the third string argument to the end of the forward list.
    void insertAfterFirstOccurrence() {
        std::unique_lock<std::mutex> lock(mutex_);
        bool found = false;

        // Search for the first occurrence of the first string argument within the forward list.
        for (auto it = flist_.begin(); it != flist_.end(); ++it) {
            if (*it == first_str_) {
                found = true;
                break;
            }
        }

        // If the first string argument is not found, append the third string argument to the end of the forward list.
        if (!found) {
            flist_.push_back(insertion_str_);
        } else {
            // Insert the third string argument immediately after the first occurrence of the first string argument.
            std::vector<std::string> temp;
            for (auto it = flist_.begin(); it != flist_.end(); ++it) {
                if (*it == first_str_) {
                    temp.push_back(insertion_str_);
                }
                temp.push_back(*it);
            }
            flist_ = std::forward_list<std::string>(temp.begin(), temp.end());
        }
    }

private:
    // Mutex for synchronizing access to the forward list.
    std::mutex mutex_;

    // Forward list of strings.
    std::forward_list<std::string>& flist_;

    // First string argument.
    const std::string& first_str_;

    // Third string argument.
