// Custom memory pool for packet headers
struct PacketHeaderPool {
  size_t capacity; // Total number of packets that can be stored in the pool
  size_t count;    // Number of packets currently stored in the pool
  void** packets;  // Array of pointers to packet headers
};

// Custom memory pool for metadata fields
struct MetadataPool {
  size_t capacity; // Total number of metadata fields that can be stored in the pool
  size_t count;    // Number of metadata fields currently stored in the pool
  void** metadata; // Array of pointers to metadata fields
};

// Data structure for managing a dynamic list of network packet headers
struct PacketHeaderList {
  struct PacketHeaderPool* pool;      // Memory pool for packet headers
  struct MetadataPool* metadata_pool; // Memory pool for metadata fields
  size_t count;                       // Number of packets currently stored in the list
  pthread_mutex_t mutex;             // Mutex to synchronize access from multiple threads
};

// Initialize a packet header list with the given capacity and memory pools
struct PacketHeaderList* packet_header_list_init(size_t capacity, struct PacketHeaderPool* pool, struct MetadataPool* metadata_pool) {
  struct PacketHeaderList* list = malloc(sizeof(struct PacketHeaderList));
  if (list == NULL) {
    return NULL;
  }

  // Initialize the memory pools
  pool->capacity = capacity;
  pool->count = 0;
  pool->packets = malloc(sizeof(void*) * capacity);
  metadata_pool->capacity = capacity;
  metadata_pool->count = 0;
  metadata_pool->metadata = malloc(sizeof(void*) * capacity);

  // Initialize the list with a mutex to synchronize access from multiple threads
  pthread_mutex_init(&list->mutex, NULL);
  list->pool = pool;
  list->metadata_pool = metadata_pool;
  list->count = 0;

  return list;
}

// Add a packet header to the list with the given timestamp and source IP address
int packet_header_list_add(struct PacketHeaderList* list, uint64_t timestamp, const char* src_ip) {
  int ret = 0;

  // Lock the mutex before accessing the list from multiple threads
  pthread_mutex_lock(&list->mutex);

  // Check if there is enough space in the memory pool to add a new packet header
  if (list->pool->count == list->pool->capacity) {
    ret = -1; // Return an error code if there is no space available
    goto unlock;
  }

  // Allocate a new packet header and copy the timestamp and source IP address
  void* new_packet = malloc(sizeof(struct PacketHeader));
  struct PacketHeader* new_header = (struct PacketHeader*)new_packet;
  new_header->timestamp = timestamp;
  strncpy(new_header->src_ip, src_ip, INET6_ADDRSTRLEN);

  // Add the packet header to the memory pool and increment the count
  list->pool->packets[list->pool->count++] = new_packet;
  list->count++;

unlock:
  pthread_mutex_unlock(&list->mutex);
  return ret;
}

// Delete a packet header from the list with the given timestamp and source IP address
int packet_header_list_delete(struct PacketHeaderList* list, uint64_t timestamp, const char* src_ip) {
  int ret = 0;

  // Lock the mutex before accessing the list from multiple threads
  pthread_mutex_lock(&list->mutex);

  // Find the packet header with the given timestamp and source IP address
  size_t i = 0;
  for (i = 0; i < list->pool->count; i++) {
    struct PacketHeader* header = (struct PacketHeader*)list->pool->packets[i];
    if (header->timestamp == timestamp && strncmp(header->src_ip, src_ip, INET6_ADDRSTRLEN) == 0) {
      break;
    }
  }

  // Check if the packet header was found in the list
  if (i == list->pool->count) {
    ret = -1; // Return an error code if the packet header is not found
    goto unlock;
  }

  // Delete the packet header from the memory pool and decrement the count
  free(list->pool->packets[i]);
  list->pool->count--;
  for (size_t j = i; j < list->pool->count; j++) {
    list->pool->packets[j] = list->pool->packets[j + 1];
  }
  list->count--;

unlock:
  pthread_mutex_unlock(&list->mutex);
  return ret;
}

// Retrieve a packet header from the list with the given timestamp and source IP address
struct PacketHeader* packet_header_list_get(struct PacketHeaderList* list, uint64_t timestamp, const char* src_ip) {
  struct PacketHeader* ret = NULL;

  // Lock the mutex before accessing the list from multiple threads
  pthread_mutex_lock(&list->mutex);

  // Find the packet header with the given timestamp and source IP address
  size_t i = 0;
  for (i = 0; i < list->pool->count; i++) {
    struct PacketHeader* header = (struct PacketHeader*)list->pool->packets[i];
    if (header->timestamp == timestamp && strncmp(header->src_ip, src_ip, INET6_ADDRSTRLEN) == 0) {
      break;
    }
  }

  // Check if the packet header was found in the list
  if (i != list->pool->count) {
    ret = (struct PacketHeader*)list->pool->packets[i];
  }

unlock:
  pthread_mutex_unlock(&list->mutex);
  return ret;
}

// Free the memory used by the packet header list and its associated resources
void packet_header_list_free(struct PacketHeaderList* list) {
  // Lock the mutex before accessing the list from multiple threads
  pthread_mutex_lock(&list->mutex);

  // Free the memory used by the memory pool and its associated resources
  for (size_t i = 0; i < list->pool->count; i++) {
    free(list->pool->packets[i]);
  }
  free(list->pool);

  // Free the memory used by the packet header list itself
  free(list);
}

int main() {
  struct PacketHeaderList* list = packet_header_list_init();

  // Add a few packet headers to the list
  packet_header_list_add(list, 1000, "192.168.1.1");
  packet_header_list_add(list, 2000, "192.168.1.2");
  packet_header_list_add(list, 3000, "192.168.1.3");

  // Delete a packet header from the list
  packet_header_list_delete(list, 1000, "192.168.1.1");

  // Retrieve a packet header from the list
  struct PacketHeader* header = packet_header_list_get(list, 3000, "192.168.1.3");
  if (header) {
    printf("Found packet header with timestamp %llu and source IP %s\n", header->timestamp, header->src_ip);
  } else {
    printf("Packet header not found\n");
  }

  // Free the memory used by the list and its associated resources
  packet_header_list_free(list);

  return 0;
}']

