    // allocate memory for the arrays of floats, identifiers, items, and statuses
    data->floats = (float *)malloc(n * sizeof(float));
    data->identifiers = (char **)malloc(n * sizeof(char *));
    data->items = (struct item *)malloc(n * sizeof(struct item));
    data->statuses = (enum status *)malloc(n * sizeof(enum status));

    // initialize all values to 0 or null
    for (int i = 0; i < n; ++i) {
        data->floats[i] = 0.0f;
        data->identifiers[i] = NULL;
        data->items[i].name = "";
        data->items[i].quantity = 0;
        data->items[i].price = 0.0f;
        data->statuses[i] = (enum status)0;
    }
}

void set_item(data_t *data, int i, const char *name, int quantity, float price) {
    // validate input parameters
    if (i < 0 || i >= data->n) {
        fprintf(stderr, "Invalid index %d\n", i);
        return;
    }
    if (!name || !quantity || !price) {
        fprintf(stderr, "Invalid input: name = %s, quantity = %d, price = %.2f\n", name, quantity, price);
        return;
    }

    // allocate memory for the item's name if necessary
    if (data->items[i].name != NULL) {
        free(data->items[i].name);
    }
    data->items[i].name = strdup(name);

    // update the item's quantity and price fields
    data->items[i].quantity = quantity;
    data->items[i].price = roundf(quantity * price);
}

void set_status(data_t *data, int i, enum status new_status) {
    // validate input parameters
    if (i < 0 || i >= data->n) {
        fprintf(stderr, "Invalid index %d\n", i);
        return;
    }
    if (!new_status) {
        fprintf(stderr, "Invalid status: %d\n", new_status);
        return;
    }

    // update the item's status field
    data->items[i].status = new_status;
}

void calculate_total_value(data_t *data) {
    float total_value = 0.0f;
    for (int i = 0; i < data->n; ++i) {
        if (data->items[i].name != NULL && data->items[i].quantity > 0 && data->items[i].price > 0) {
            total_value += roundf(data->items[i].quantity * data->items[i].price);
        }
    }
    printf("Total value: %.2f\n", total_value);
}

void free_data(data_t *data) {
    // free all allocated memory
    for (int i = 0; i < data->n; ++i) {
        if (data->items[i].name != NULL) {
            free(data->items[i].name);
        }
    }
    free(data->floats);
    free(data->identifiers);
    free(data->items);
    free(data->statuses);
}
