GraphDatabase* createGraphDatabase(int numUsers) {
    // Allocate memory for the arrays and initialize them to 0
    GraphDatabase* db = malloc(sizeof(GraphDatabase));
    if (!db) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    db->keys = calloc(numUsers, sizeof(int));
    db->offsets = calloc(numUsers, sizeof(long));
    db->numRecords = numUsers;
    return db;
