        free(values);
        return false;
    }
    hashmap->size++;
    return true;
}

// Function to remove a record with the specified key from the hashmap
bool remove_record(int key) {
    struct hashmap *hashmap = get_hashmap();
    if (hashmap == NULL) {
        fprintf(stderr, "Failed to get hashmap\n");
        return false;
    }
    void **keys = hashmap->keys;
    void **values = hashmap->values;
    for (int i = 0; i < hashmap->size; i++) {
        if (*(int *)keys[i] == key) {
            free(keys[i]);
            free(values[i]);
            keys[i] = NULL;
            values[i] = NULL;
            hashmap->size--;
            return true;
        }
    }
    fprintf(stderr, "Failed to find record with key %d\n", key);
    return false;
}

// Function to check if a record exists in the hashmap with the specified key
bool has_record(int key) {
    struct hashmap *hashmap = get_hashmap();
    if (hashmap == NULL) {
        fprintf(stderr, "Failed to get hashmap\n");
        return false;
    }
    void **keys = hashmap->keys;
    for (int i = 0; i < hashmap->size; i++) {
        if (*(int *)keys[i] == key) {
            return true;
        }
    }
    fprintf(stderr, "Failed to find record with key %d\n", key);
    return false;
}

// Function to get the hashmap
struct hashmap *get_hashmap() {
    int shmid;
    struct hashmap *hashmap = NULL;
    if ((shmid = shmget(IPC_PRIVATE, sizeof(struct hashmap), 0644 | IPC_CREAT)) < 0) {
        fprintf(stderr, "Failed to get shared memory segment\n");
        return NULL;
    }
    if ((hashmap = shmat(shmid, (char *)0, 0)) == (struct hashmap *)-1) {
        fprintf(stderr, "Failed to attach to shared memory segment\n");
        return NULL;
    }
    return hashmap;
}

// Function to initialize the hashmap
bool init_hashmap() {
    struct hashmap *hashmap = get_hashmap();
    if (hashmap == NULL) {
        fprintf(stderr, "Failed to get hashmap\n");
        return false;
    }
    hashmap->keys = NULL;
    hashmap->values = NULL;
    hashmap->size = 0;
    return true;
}

// Function to destroy the hashmap
bool destroy_hashmap() {
    struct hashmap *hashmap = get_hashmap();
    if (hashmap == NULL) {
        fprintf(stderr, "Failed to get hashmap\n");
        return false;
    }
    void **keys = hashmap->keys;
    void **values = hashmap->values;
    for (int i = 0; i < hashmap->size; i++) {
        free(keys[i]);
        free(values[i]);
    }
    if (shmdt((const void *)hashmap) == -1) {
        fprintf(stderr, "Failed to detach from shared memory segment\n");
        return false;
    }
    if (shmctl(IPC_PRIVATE, SHM_DESTROY, 0) < 0) {
        fprintf(stderr, "Failed to destroy shared memory segment\n");
        return false;
    }
    return true;
}
