// Structure to store user connection information
struct USER_CONNECTION_INFO {
    int USER_ID;
    CONN_STATUS_T status;
    time_t timestamp;
};

// Hash map for duplicate USER_ID detection
typedef struct {
    int size; // Size of the hash map
    int *keys; // Array of keys (USER_IDs)
    int *values; // Array of values (indices in the user connection info array)
} HashMap;

// Function to initialize a hash map with a given size
void initHashMap(HashMap *map, int size) {
    map->size = size;
    map->keys = malloc(sizeof(int) * size);
    map->values = malloc(sizeof(int) * size);
}

// Function to insert a new key-value pair into the hash map
void putHashMap(HashMap *map, int key, int value) {
    // Check if the key is already present in the map
    for (int i = 0; i < map->size; i++) {
        if (map->keys[i] == key) {
            return;
        }
    }

    // If the key is not present, insert it and update the values array
    int index = (key % map->size) - 1;
    while (map->values[++index] != -1);
    map->keys[index] = key;
    map->values[index] = value;
}

// Function to retrieve a value from the hash map given a key
int getHashMap(HashMap *map, int key) {
    for (int i = 0; i < map->size; i++) {
        if (map->keys[i] == key) {
            return map->values[i];
        }
    }
    return -1; // Key not found
}

// Function to delete a key-value pair from the hash map given a key
void delHashMap(HashMap *map, int key) {
    for (int i = 0; i < map->size; i++) {
        if (map->keys[i] == key) {
            map->keys[i] = -1;
            map->values[i] = -1;
            return;
        }
    }
}

// Function to check if a key is present in the hash map
int containsHashMap(HashMap *map, int key) {
    for (int i = 0; i < map->size; i++) {
        if (map->keys[i] == key) {
            return 1;
        }
    }
    return 0; // Key not found
}

// Function to generate a unique USER_ID and add it to the hash map
int generateUniqueUserId(HashMap *map) {
    int id = 0;
    while (containsHashMap(map, id)) {
        id++;
    }
    putHashMap(map, id, id);
    return id;
}

// Function to allocate memory for a dynamic array of user connection info structures
