    struct USER_CONNECTION_INFO *array = malloc(sizeof(struct USER_CONNECTION_INFO) * size);
    if (!array) {
        perror("Error allocating memory for user connection info array");
        exit(EXIT_FAILURE);
    }
    return array;
}

// Function to populate a dynamic array of user connection info structures with unique USER_IDs and random connection statuses
void populateUserConnectionInfoArray(struct USER_CONNECTION_INFO *array, int size) {
    HashMap map; // Hash map for duplicate USER_ID detection
    initHashMap(&map, size);

    for (int i = 0; i < size; i++) {
        int id = generateUniqueUserId(&map);
        array[i].USER_ID = id;
        array[i].status = CONN_STATUS_T_RANDOM(); // Random connection status
        array[i].timestamp = time(NULL);
    }
}

// Function to allocate memory for a dynamic array of user connection info structures with a given size
struct USER_CONNECTION_INFO *allocateAndPopulateMemory(int size) {
    struct USER_CONNECTION_INFO *array = allocateMemory(size);
    populateUserConnectionInfoArray(array, size);
    return array;
}

// Function to free memory for a dynamic array of user connection info structures
