        if (user_session_states[i].session_id == session_id) {
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    // Add the new user session to the array
    UserSessionState* new_session = malloc(sizeof(UserSessionState));
    if (new_session == NULL) {
        pthread_mutex_unlock(&mutex);
        return;
    }
    new_session->session_id = session_id;
    new_session->connection_state = connection_state;
    user_session_states[CONFIG_MAX_USERS] = new_session;

    // Unlock the mutex after adding the user session
    pthread_mutex_unlock(&mutex);
}

void remove_user_session(int session_id) {
    // Lock the mutex before accessing the array
    pthread_mutex_lock(&mutex);

    // Find the index of the user session in the array
    for (int i = 0; i < CONFIG_MAX_USERS; i++) {
        if (user_session_states[i].session_id == session_id) {
            break;
        }
    }

    // Remove the user session from the array
    UserSessionState* removed_session = user_session_states[i];
    for (int j = i + 1; j < CONFIG_MAX_USERS; j++) {
        user_session_states[j - 1] = user_session_states[j];
    }
    free(removed_session);

    // Unlock the mutex after removing the user session
    pthread_mutex_unlock(&mutex);
}

void update_user_session(int session_id, char connection_state) {
    // Lock the mutex before accessing the array
    pthread_mutex_lock(&mutex);

    // Find the index of the user session in the array
    for (int i = 0; i < CONFIG_MAX_USERS; i++) {
        if (user_session_states[i].session_id == session_id) {
