    UserSessionState* updated_session = user_session_states[i];
    updated_session->connection_state = connection_state;

    // Unlock the mutex after updating the user session
    pthread_mutex_unlock(&mutex);
}

void print_user_sessions() {
    // Lock the mutex before accessing the array
    pthread_mutex_lock(&mutex);

    // Print all user sessions in the array
    for (int i = 0; i < CONFIG_MAX_USERS; i++) {
