// Initialize a pool of network packet headers with the given size
struct PacketPool* initPool(int size) {
    struct PacketPool* pool = (struct PacketPool*) malloc(sizeof(struct PacketPool));
    if (!pool) {
        printf("Error: Failed to allocate memory for packet pool\n");
        return NULL;
    }

    pool->size = size;
    pool->used = 0;
    pthread_mutex_init(&pool->mutex, NULL);

    // Allocate memory for the packet headers
    pool->pool = (struct PacketHeader*) malloc(sizeof(struct PacketHeader) * size);
    if (!pool->pool) {
        printf("Error: Failed to allocate memory for packet headers\n");
        free(pool);
        return NULL;
    }

    return pool;
}

// Add a network packet header to the pool
int addPacket(struct PacketPool* pool, struct PacketHeader* header) {
    if (!pool || !header) {
        printf("Error: Invalid arguments\n");
        return -1;
    }

    pthread_mutex_lock(&pool->mutex);

    // Validate IP addresses and ensure timestamps are within range
    if (validateIP(header->sourceIP) && validateIP(header->destIP) && isTimestampValid(header->timestamp)) {
        if (pool->used < pool->size) {
            memcpy(&pool->pool[pool->used++], header, sizeof(struct PacketHeader));
            pthread_mutex_unlock(&pool->mutex);
            return 0;
        } else {
            printf("Error: Packet pool is full\n");
            pthread_mutex_unlock(&pool->mutex);
            return -1;
        }
    } else {
        printf("Warning: Invalid packet header detected\n");
        pthread_mutex_unlock(&pool->mutex);
        return 0;
    }
}

// Retrieve a network packet header from the pool
struct PacketHeader* getPacket(struct PacketPool* pool) {
    if (!pool) {
        printf("Error: Invalid arguments\n");
        return NULL;
    }

    pthread_mutex_lock(&pool->mutex);
    struct PacketHeader* header = &pool->pool[--pool->used];
    pthread_mutex_unlock(&pool->mutex);

    return header;
}

// Delete a network packet header from the pool
int deletePacket(struct PacketPool* pool, struct PacketHeader* header) {
    if (!pool || !header) {
        printf("Error: Invalid arguments\n");
        return -1;
    }

    pthread_mutex_lock(&pool->mutex);
    int i = 0;
    while (i < pool->used && &pool->pool[i] != header) {
        ++i;
    }
    if (i == pool->used) {
        printf("Error: Packet not found in pool\n");
        pthread_mutex_unlock(&pool->mutex);
        return -1;
    }

    // Move the last packet to the deleted position and update used count
    --pool->used;
    memcpy(header, &pool->pool[pool->used], sizeof(struct PacketHeader));

    pthread_mutex_unlock(&pool->mutex);
    return 0;
}

