        printf("Invalid RX_UE_INFORMATION_TAG value\n");
        return;
    }
    int RNTI = json_get_int(root, "rnti");
    if (RNTI < 0 || RNTI > 65535) {
        printf("Invalid RNTI value\n");
        return;
    }
    int CRC_INDICATION_REL8_TAG = json_get_int(root, "crc_indication_rel8_tag");
    if (CRC_INDICATION_REL8_TAG < 0 || CRC_INDICATION_REL8_TAG > 127) {
        printf("Invalid CRC_INDICATION_REL8_TAG value\n");
        return;
    }
    int CRCFLAG = json_get_int(root, "crcflag");
    if (CRCFLAG < 0 || CRCFLAG > 1) {
        printf("Invalid CRCFLAG value\n");
