public static class ExecuteDynamicDatabaseQuery
{
    public static async Task<IDataReader> ExecuteAsync(string sqlCommandTemplate, string connectionString)
    {
        // Validate input parameters
        if (string.IsNullOrEmpty(sqlCommandTemplate))
            throw new ArgumentException("SQL command template cannot be null or empty", nameof(sqlCommandTemplate));
        if (string.IsNullOrEmpty(connectionString))
            throw new ArgumentException("Connection string cannot be null or empty", nameof(connectionString));

        // Create a new SqlConnection with the provided connection string
        using var connection = new SqlConnection(connectionString);

        try
        {
            // Open the connection and execute the SQL command template
            await connection.OpenAsync();
            using var command = new SqlCommand(sqlCommandTemplate, connection);
            var resultSet = await command.ExecuteReaderAsync();

            // Return the IDataReader for the result set
            return resultSet;
        }
        catch (SqlException ex)
        {
            // Handle SQL exceptions gracefully
            throw new Exception("SQL exception occurred", ex);
        }
        finally
