// Define a struct to represent a log entry
struct LOG_RECORD {
    int timestamp;
    char event_type[32];
    int transaction_id;
};

// Define an array to hold the log entries
static struct LOG_RECORD *log_entries = NULL;
static size_t log_size = 0;
static size_t log_capacity = 100000;

// Mutex for synchronizing access to the log entries
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new log entry to the array
void add_log_entry(struct LOG_RECORD *new_entry) {
    // Check if we have reached the maximum capacity of the log entries
    if (log_size == log_capacity) {
        // If so, allocate more memory for the log entries
        size_t new_capacity = log_capacity * 2;
        struct LOG_RECORD *new_entries = realloc(log_entries, new_capacity);
        if (new_entries == NULL) {
            // If allocation fails, return an error message
            printf("Error: Failed to allocate more memory for the log entries.\n");
            return;
        }
        log_entries = new_entries;
        log_capacity = new_capacity;
    }

    // Add the new log entry to the end of the array
    pthread_mutex_lock(&log_mutex);
    log_entries[log_size++] = *new_entry;
    pthread_mutex_unlock(&log_mutex);
}

// Function to remove a log entry from the array
void remove_log_entry(int index) {
    // Check if the given index is valid
    if (index < 0 || index >= log_size) {
        printf("Error: Invalid index for removing a log entry.\n");
        return;
    }

    // Remove the log entry from the array
    pthread_mutex_lock(&log_mutex);
    log_entries[index] = log_entries[--log_size];
    pthread_mutex_unlock(&log_mutex);
}

// Function to retrieve a log entry from the array
struct LOG_RECORD *get_log_entry(int index) {
    // Check if the given index is valid
    if (index < 0 || index >= log_size) {
        printf("Error: Invalid index for retrieving a log entry.\n");
        return NULL;
    }

    // Return the log entry at the given index
    pthread_mutex_lock(&log_mutex);
    struct LOG_RECORD *entry = &log_entries[index];
    pthread_mutex_unlock(&log_mutex);
    return entry;
}

// Function to free the allocated memory for the log entries
void free_log_entries() {
    // Check if there are any log entries to free
    if (log_entries != NULL) {
        free(log_entries);
        log_entries = NULL;
        log_size = 0;
        log_capacity = 0;
    }
}
```
