int allocate_memory(size_t num_records, size_t max_memory) {
    // Calculate the required memory for the records
    size_t record_size = sizeof(struct record);
    size_t total_mem_required = num_records * record_size;

    // Check if the total memory required exceeds the maximum allowed
    if (total_mem_required > max_memory) {
        return -1;
    }

    // Allocate the memory for the records
    struct record* records = malloc(total_mem_required);
    if (!records) {
        return -2;
    }

    return (int)records;
}

void initialize_random_values(struct record* records, size_t num_records, int min_val, int max_val, unsigned long seed) {
    // Initialize the random number generator using the provided seed
    srand(seed);

    // Initialize each record with a random value within the specified range
    for (size_t i = 0; i < num_records; i++) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }
}

void free_memory(struct record* records, size_t num_records) {
    // Free the memory allocated for the records
    free(records);
}

