#include <string.h>

// Define a structure to hold the TX power report indication data
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} TX_POWER_REPORT_INDICATION_T;

// Define a dynamic array to hold the TX power report indications
typedef struct {
    TX_POWER_REPORT_INDICATION_T** data;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DYNAMIC_ARRAY_T;

// Initialize the dynamic array with a given capacity
DYNAMIC_ARRAY_T* dynamic_array_init(size_t capacity) {
    DYNAMIC_ARRAY_T* arr = malloc(sizeof(DYNAMIC_ARRAY_T));
    if (!arr) return NULL;
    arr->data = calloc(capacity, sizeof(TX_POWER_REPORT_INDICATION_T*));
    if (!arr->data) {
        free(arr);
        return NULL;
    }
    arr->capacity = capacity;
    arr->count = 0;
    pthread_mutex_init(&arr->mutex, NULL);
    return arr;
}

// Add a new TX power report indication to the dynamic array
int dynamic_array_add(DYNAMIC_ARRAY_T* arr, const TX_POWER_REPORT_INDICATION_T* ind) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->count >= arr->capacity) {
        // Grow the capacity of the dynamic array by a factor of 2
        size_t new_capacity = arr->capacity * 2;
        TX_POWER_REPORT_INDICATION_T** new_data = realloc(arr->data, new_capacity * sizeof(TX_POWER_REPORT_INDICATION_T*));
        if (!new_data) {
            pthread_mutex_unlock(&arr->mutex);
            return -1;
        }
        arr->data = new_data;
        arr->capacity = new_capacity;
    }
    // Allocate memory for the new structure and populate it with the given data
    TX_POWER_REPORT_INDICATION_T* new_ind = malloc(sizeof(TX_POWER_REPORT_INDICATION_T));
    if (!new_ind) {
        pthread_mutex_unlock(&arr->mutex);
        return -1;
    }
    memcpy(new_ind, ind, sizeof(TX_POWER_REPORT_INDICATION_T));
    // Generate a unique RNTI for the new structure and set it
    uint32_t rnti = rand();
    while (rnti == 0) {
        rnti = rand();
    }
    new_ind->RNTI = rnti;
    // Generate a random CRC flag for the new structure and set it
    uint8_t crc_flag = rand() % 256;
    while (crc_flag == 0) {
        crc_flag = rand() % 256;
    }
    new_ind->CRC_INDICATION_REL8_TAG = crc_flag;
    // Add the new structure to the dynamic array and increment the count
    arr->data[arr->count] = new_ind;
    arr->count++;
    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

// Remove a TX power report indication from the dynamic array
void dynamic_array_remove(DYNAMIC_ARRAY_T* arr, size_t index) {
    pthread_mutex_lock(&arr->mutex);
    assert(index < arr->count);
    // Free the memory for the structure and shift the remaining structures in the array
    free(arr->data[index]);
    for (size_t i = index; i < arr->count - 1; i++) {
        arr->data[i] = arr->data[i + 1];
    }
    // Decrement the count and reallocate memory if necessary
    arr->count--;
    size_t new_capacity = arr->count * 2;
    TX_POWER_REPORT_INDICATION_T** new_data = NULL;
    if (new_capacity > 0) {
        new_data = realloc(arr->data, new_capacity * sizeof(TX_POWER_REPORT_INDICATION_T*));
        if (!new_data) {
            pthread_mutex_unlock(&arr->mutex);
            return;
        }
    }
    arr->data = new_data;
    arr->capacity = new_capacity;
    pthread_mutex_unlock(&arr->mutex);
}

// Update a TX power report indication in the dynamic array
void dynamic_array_update(DYNAMIC_ARRAY_T* arr, size_t index, const TX_POWER_REPORT_INDICATION_T* ind) {
    pthread_mutex_lock(&arr->mutex);
    assert(index < arr->count);
    memcpy(arr->data[index], ind, sizeof(TX_POWER_REPORT_INDICATION_T));
    pthread_mutex_unlock(&arr->mutex);
}

// Retrieve a TX power report indication from the dynamic array by index
const TX_POWER_REPORT_INDICATION_T* dynamic_array_get(DYNAMIC_ARRAY_T* arr, size_t index) {
    pthread_mutex_lock(&arr->mutex);
    assert(index < arr->count);
    const TX_POWER_REPORT_INDICATION_T* ind = arr->data[index];
    pthread_mutex_unlock(&arr->mutex);
    return ind;
}

// Retrieve the number of structures currently stored in the dynamic array
size_t dynamic_array_count(DYNAMIC_ARRAY_T* arr) {
    size_t count = 0;
    pthread_mutex_lock(&arr->mutex);
    count = arr->count;
    pthread_mutex_unlock(&arr->mutex);
    return count;
}

// Retrieve the total allocated memory for the dynamic array
size_t dynamic_array_memory(DYNAMIC_ARRAY_T* arr) {
    size_t memory = 0;
    pthread_mutex_lock(&arr->mutex);
    memory = (arr->count * sizeof(TX_POWER_REPORT_INDICATION_T*)) + (arr->count * sizeof(TX_POWER_REPORT_INDICATION_T));
    pthread_mutex_unlock(&arr->mutex);
    return memory;
}

// Retrieve the number of reallocations for the dynamic array
size_t dynamic_array_reallocations(DYNAMIC_ARRAY_T* arr) {
    size_t reallocations = 0;
    pthread_mutex_lock(&arr->mutex);
    reallocations = arr->reallocations;
    pthread_mutex_unlock(&arr->mutex);
    return reallocations;
}

// Free the memory for the dynamic array
void dynamic_array_free(DYNAMIC_ARRAY_T* arr) {
    pthread_mutex_lock(&arr->mutex);
    for (size_t i = 0; i < arr->count; i++) {
        free(arr->data[i]);
    }
    free(arr->data);
    pthread_mutex_unlock(&arr->mutex);
}
