static const int MAX_USERS = 10000; // maximum number of users allowed
static pthread_mutex_t mutex; // mutex for thread safety
static pthread_cond_t cond; // condition variable for waiting until a unique ID is available
static USER_CONNECTION_INFO *user_info_pool; // memory pool for reusing structures
static int user_count = 0; // number of users currently connected
static int user_allocated = 0; // number of structs allocated from the pool
static int user_used = 0; // number of structs in use (i.e., not available)

// generate a unique ID for a new connection
int generate_id(void) {
    static int id = 0; // start with 1 to avoid 0 being used as a special value
    pthread_mutex_lock(&mutex);
    while (id <= MAX_USERS && user_info_pool[id].connected) { // check if the ID is already in use
        id++;
    }
    if (id > MAX_USERS) { // handle race condition where all IDs are used up before we find a free one
        printf("All %d users are connected. Please disconnect some users to allow new connections.\n", MAX_USERS);
        pthread_mutex_unlock(&mutex);
        return -1;
    } else {
        user_info_pool[id].connected = true; // mark the struct as in use
        user_used++; // increment the number of used structs
        pthread_cond_broadcast(&cond); // notify other threads that a new ID is available
        pthread_mutex_unlock(&mutex);
        return id; // return the newly generated ID
    }
}

// allocate a USER_CONNECTION_INFO struct from the pool, if possible
USER_CONNECTION_INFO *allocate(int user_id) {
    pthread_mutex_lock(&mutex);
    while (user_used == user_allocated && user_count >= MAX_USERS) { // wait until a struct is available or the pool is full
        pthread_cond_wait(&cond, &mutex);
    }
    if (user_allocated < user_count) { // handle race condition where another thread allocated a new struct while we were waiting
        user_allocated++;
    }
    USER_CONNECTION_INFO *struct_ptr = &user_info_pool[user_id]; // get the pointer to the struct
    if (struct_ptr->connected) { // handle race condition where another thread allocated a new struct with this ID while we were waiting
        printf("ID %d is already in use. Please disconnect the user first.\n", user_id);
        pthread_mutex_unlock(&mutex);
        return NULL;
    } else {
        struct_ptr->connected = true; // mark the struct as in use
        user_used++; // increment the number of used structs
        pthread_cond_broadcast(&cond); // notify other threads that a new ID is available
        pthread_mutex_unlock(&mutex);
        return struct_ptr; // return the allocated struct
    }
}

// deallocate a USER_CONNECTION_INFO struct from the pool
void deallocate(USER_CONNECTION_INFO *struct_ptr) {
    pthread_mutex_lock(&mutex);
    if (!struct_ptr->connected) { // handle race condition where another thread deallocated this struct while we were waiting
        printf("ID %d is already disconnected. Please connect the user first.\n", struct_ptr->user_id);
        pthread_mutex_unlock(&mutex);
        return;
    } else {
        struct_ptr->connected = false; // mark the struct as available for allocation
        user_used--; // decrement the number of used structs
        if (user_allocated > user_count) { // handle race condition where another thread deallocated a new struct while we were waiting
            user_allocated--;
        }
        pthread_cond_broadcast(&cond); // notify other threads that a struct is available for allocation
        pthread_mutex_unlock(&mutex);
    }
}

