void get_user_state(USER_CONNECTION_INFO **users) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < user_count; i++) {
        users[i] = &user_info_pool[i];
    }
    pthread_mutex_unlock(&mutex);
}

// main function that manages the dynamic list of USER_CONNECTION_INFO structures
