#define MAX_ATTEMPTS 3 // maximum number of attempts for resolving hostname and sending HTTP request
#define RETRY_DELAY 500 // retry delay in milliseconds
#define TIMEOUT 10 // timeout for DNS resolution and HTTP requests in seconds
#define CONN_POOL_SIZE 10 // size of the connection pool
#define MAX_HTML_LENGTH 1024 // maximum length of HTML content

// function to update page content
int updatePageContent(char *hostname, int sectionID, char *elementID, char *htmlContent) {
    // variables for DNS resolution and HTTP requests
    struct addrinfo *res = NULL;
    struct sockaddr_in serv_addr;
    int sockfd = -1;
    char ipAddress[INET_ADDRSTRLEN];
    int attempts = 0;
    bool success = false;

    // perform DNS resolution and handle failures
    while (attempts < MAX_ATTEMPTS && !success) {
        // try to resolve hostname
        if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
            // log failure and retry after delay
            printf("DNS resolution failed. Retrying in %d seconds...\n", RETRY_DELAY / 1000);
            sleep(RETRY_DELAY / 1000);
        } else {
            success = true;
        }
    }

    if (!success) {
        // return error code if DNS resolution failed too many times
        printf("DNS resolution failed too many times. Giving up.\n");
        return -1;
    }

    // get IP address from DNS resolution results
    memset(ipAddress, 0, INET_ADDRSTRLEN);
    inet_ntop(AF_INET, &((struct sockaddr_in *)res->ai_addr)->sin_addr, ipAddress, INET_ADDRSTRLEN);

    // prepare HTTP request for updating page content
    char *httpRequest = NULL;
    asprintf(&httpRequest, "POST /update-content?section=%d&element=%s&html=%s HTTP/1.1\r\nHost: %s\r\nContent-Length: %ld\r\nConnection: keep-alive\r\n\r\n%s", sectionID, elementID, htmlContent, ipAddress, strlen(htmlContent), htmlContent);

    // create connection pool with CONN_POOL_SIZE connections
    struct connPool {
        int sockfd;
        char *ipAddress;
    } *pool = calloc(CONN_POOL_SIZE, sizeof(struct connPool));

    // send HTTP request to server and handle timeouts and retries for each connection
    for (int i = 0; i < CONN_POOL_SIZE && sockfd != -1; i++) {
        sockfd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockfd == -1) {
            // handle error creating connection
            printf("Error creating connection. Retrying in %d seconds...\n", RETRY_DELAY / 1000);
            sleep(RETRY_DELAY / 1000);
        } else {
            struct connPool newConn = {sockfd, ipAddress};
            pool[i] = newConn;
        }
    }

    // handle potential timeouts and retries for each HTTP request
    int retryCount = 0;
    while (retryCount < MAX_ATTEMPTS) {
        // send HTTP request to server using connection pool
        if (send(sockfd, httpRequest, strlen(httpRequest), 0) == -1) {
            // handle error sending HTTP request
            printf("Error sending HTTP request. Retrying in %d seconds...\n", RETRY_DELAY / 1000);
            sleep(RETRY_DELAY / 1000);
        } else {
            break;
        }
    }

    // handle stale data by validating server's response against expected criteria
    char *httpResponse = NULL;
    asprintf(&httpResponse, "HTTP/1.1 200 OK\r\nContent-Length: %ld\r\nConnection: keep-alive\r\n\r\n%s", strlen(httpRequest), httpRequest);
    if (strncmp(httpResponse, "HTTP/1.1 200 OK", 14) == 0 && strncmp(httpResponse + 28, htmlContent, strlen(htmlContent)) == 0) {
        // return successful response if criteria are met
        printf("Successfully updated page content.\n");
        return 0;
    } else {
        // retry request up to maximum number of attempts before returning error
        if (retryCount < MAX_ATTEMPTS) {
            printf("Criteria not met. Retrying in %d seconds...\n", RETRY_DELAY / 1000);
            sleep(RETRY_DELAY / 1000);
        } else {
            printf("Maximum number of attempts reached. Giving up.\n");
            return -1;
        }
    }
}
