#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <pthread.h>

// Define struct for record data
struct record {
    int key;
    long offset;
};

// Define struct for cache data
struct cache_data {
    struct record* records;
    size_t capacity; // maximum number of records in the cache
    size_t size; // current number of records in the cache
    pthread_mutex_t mutex; // mutex for thread safety
};

// Define function to initialize cache data
void init_cache(struct cache_data* cache) {
    cache->records = NULL;
    cache->capacity = 1000;
    cache->size = 0;
    pthread_mutex_init(&cache->mutex, NULL);
}

// Define function to destroy cache data
void destroy_cache(struct cache_data* cache) {
    free(cache->records);
    pthread_mutex_destroy(&cache->mutex);
}

// Define function to add record to cache
int add_record(struct cache_data* cache, struct record* record) {
    // Lock mutex for thread safety
    pthread_mutex_lock(&cache->mutex);

    // Check if cache is full
    if (cache->size == cache->capacity) {
        // Evict least recently used record from cache
        int evicted_record = 0;
        for (int i = 0; i < cache->size; i++) {
            if (cache->records[i].last_accessed < cache->records[evicted_record].last_accessed) {
                evicted_record = i;
            }
        }
        // Free memory for evicted record
        free(cache->records[evicted_record].key);
        free(cache->records[evicted_record].offset);
        cache->size--;
    }

    // Add new record to cache
    cache->records[cache->size] = *record;
    cache->records[cache->size].last_accessed = time(NULL);
    cache->size++;

    // Unlock mutex for thread safety
    pthread_mutex_unlock(&cache->mutex);
}

// Define function to retrieve record from cache
struct record* get_record(struct cache_data* cache, int key) {
    // Lock mutex for thread safety
    pthread_mutex_lock(&cache->mutex);

    // Check if record is in cache
    for (int i = 0; i < cache->size; i++) {
        if (cache->records[i].key == key) {
            // Update last accessed time
            cache->records[i].last_accessed = time(NULL);

            // Unlock mutex for thread safety
            pthread_mutex_unlock(&cache->mutex);

            // Return record
            return &cache->records[i];
        }
    }

    // Unlock mutex for thread safety
    pthread_mutex_unlock(&cache->mutex);

    // Return NULL if record not found in cache
    return NULL;
}

// Define function to fetch additional records from remote REST API
int fetch_records(struct cache_data* cache, int max_records) {
    // Lock mutex for thread safety
    pthread_mutex_lock(&cache->mutex);

    // Check if cache is full
    if (cache->size == cache->capacity) {
        // Unlock mutex for thread safety
        pthread_mutex_unlock(&cache->mutex);
        return 0;
    }

    // Fetch records from remote REST API
    int num_records = max_records - cache->size;
    struct record* new_records = fetch_records_from_api(num_records);
    if (new_records == NULL) {
        // Unlock mutex for thread safety
        pthread_mutex_unlock(&cache->mutex);
        return 0;
    }

    // Add new records to cache
    for (int i = 0; i < num_records; i++) {
        add_record(cache, &new_records[i]);
    }

    // Unlock mutex for thread safety
    pthread_mutex_unlock(&cache->mutex);

    // Return number of records fetched
    return num_records;
}

// Define function to fetch random values from cache
int get_random_values(struct cache_data* cache, int num_values) {
    // Lock mutex for thread safety
    pthread_mutex_lock(&cache->mutex);

    // Check if cache is empty
    if (cache->size == 0) {
        // Unlock mutex for thread safety
        pthread_mutex_unlock(&cache->mutex);
        return 0;
    }

    // Select random records from cache
    int num_records = num_values / 2;
    struct record* selected_records = malloc(num_records * sizeof(struct record));
    for (int i = 0; i < num_records; i++) {
        selected_records[i] = cache->records[rand() % cache->size];
    }

    // Unlock mutex for thread safety
    pthread_mutex_unlock(&cache->mutex);

    // Return number of records retrieved
    return num_records;
}
