// Struct for storing records
struct Record {
    int key;
    long offset;
};

// Function to dynamically allocate memory for and initialize an array of 'Record' structures
void allocateMemory(int numRecords, int maxMemorySize) {
    // Check if the input is valid
    if (numRecords < 0 || maxMemorySize < 0) {
        std::cerr << "Invalid input: negative values are not allowed." << std::endl;
        return;
    }

    // Calculate the maximum size of each record based on the given memory limit
    int maxRecordSize = sizeof(int) + sizeof(long);
    if (maxMemorySize < numRecords * maxRecordSize) {
        std::cerr << "Invalid input: the maximum memory limit is too small." << std::endl;
        return;
    }

    // Allocate memory for the array of records
    Record* records = static_cast<Record*>(std::malloc(numRecords * maxRecordSize));
    if (records == nullptr) {
        std::cerr << "Failed to allocate memory: out of memory." << std::endl;
        return;
    }

    // Initialize the records with random values within a specified range
    for (int i = 0; i < numRecords; ++i) {
        records[i].key = rand() % 1000000;
        records[i].offset = rand() % maxMemorySize;
    }

    // Log the successful allocation and initialization of the records
    std::ofstream logFile("memory_allocation.log", std::ios::app);
    if (!logFile) {
        std::cerr << "Failed to open log file: " << std::strerror(errno) << std::endl;
        return;
    }
    logFile << "Successfully allocated and initialized " << numRecords << " records with random values." << std::endl;
    logFile.close();
}

// Function to handle potential memory allocation failures gracefully
void handleMemoryAllocationFailure() {
    // Check if the allocation failed due to a lack of memory
    if (std::get_errno() == ENOMEM) {
        std::cerr << "Failed to allocate memory: out of memory." << std::endl;
        return;
    }

    // Retry the allocation with a reduced memory limit
    int newNumRecords = numRecords / 2;
    if (newNumRecords < 1) {
        std::cerr << "Failed to allocate memory: insufficient memory." << std::endl;
        return;
    }

    // Log the retry attempt and continue with the reduced memory limit
    std::ofstream logFile("memory_allocation.log", std::ios::app);
    if (!logFile) {
        std::cerr << "Failed to open log file: " << std::strerror(errno) << std::endl;
        return;
    }
    logFile << "Retrying allocation with reduced memory limit (" << newNumRecords << " records)." << std::endl;
    logFile.close();

    // Recursively call the function to retry the allocation with the reduced memory limit
    allocateMemory(newNumRecords, maxMemorySize / 2);
}

// Main function to demonstrate the usage of the allocation function
int main() {
    // Define the number of records and maximum memory size for the allocation
    int numRecords = 100;
    int maxMemorySize = 1000000;

    // Call the allocation function with the given input
    allocateMemory(numRecords, maxMemorySize);

    // Handle potential memory allocation failures gracefully
    if (std::get_errno() != ENOMEM) {
        handleMemoryAllocationFailure();
    }

    return 0;
}']

