    while (i < MAX_RECORDS && mempool[i] != NULL) {
        ++i;
    }
    if (i == MAX_RECORDS) {
        // Memory pool is full, allocate a new record directly from the heap
        pthread_mutex_unlock(&mempool_lock);
        return malloc(size);
    } else {
        void* ptr = mempool[i];
        mempool[i] = NULL;
        pthread_mutex_unlock(&mempool_lock);
        return ptr;
    }
}

// Define a function to deallocate a record
void cache_free(void* ptr) {
    pthread_mutex_lock(&mempool_lock);
    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (mempool[i] == NULL) {
            mempool[i] = ptr;
            break;
        }
    }
    pthread_mutex_unlock(&mempool_lock);
}

// Define a function to update the last accessed time for a record
void cache_update(CACHE_RECORD* record) {
    pthread_mutex_lock(&cache_lock);
    record->last_accessed = time(NULL);
    pthread_mutex_unlock(&cache_lock);
}

// Define a function to get the current size of the cache
int cache_size() {
    int size = 0;
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (cache[i] != NULL) {
            ++size;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return size;
}

// Define a function to get the record at a given index in the cache
CACHE_RECORD* cache_get(int index) {
    if (index < 0 || index >= MAX_RECORDS) {
        // Invalid index, return NULL
        return NULL;
    }
    pthread_mutex_lock(&cache_lock);
    CACHE_RECORD* record = cache[index];
    if (record == NULL) {
        // Record not found, return NULL
        pthread_mutex_unlock(&cache_lock);
        return NULL;
    } else {
        // Update the last accessed time for the record
        cache_update(record);
        pthread_mutex_unlock(&cache_lock);
        return record;
    }
}

// Define a function to add a new record to the cache
void cache_add(CACHE_RECORD* record) {
    if (record == NULL) {
        // Invalid record, do nothing
        return;
    }
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (cache[i] == NULL) {
            cache[i] = record;
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);
}

// Define a function to remove a record from the cache
void cache_remove(CACHE_RECORD* record) {
    if (record == NULL) {
        // Invalid record, do nothing
        return;
    }
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (cache[i] == record) {
            cache[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);
}
```
This implementation uses a hash map to store the records and their associated offsets, and a memory pool to allocate and deallocate records efficiently. The `cache_alloc` function allocates a new record from the memory pool if it is not full, or directly from the heap if the memory pool is full. The `cache_free` function deallocates a record back to the memory pool if possible, or frees it directly from the heap otherwise.

The `cache_update` function updates the last accessed time for a record in the cache. The `cache_size` function returns the current size of the cache. The `cache_get` function returns the record at a given index in the cache if it exists, or NULL otherwise. The `cache_add` function adds a new record to the cache if there is space available. The `cache_remove` function removes a record from the cache if it exists.

The implementation also includes support for concurrent access from multiple threads through thread-safe operations and synchronization mechanisms, such as mutex locks around the hash map and memory pool operations. This ensures that the cache is accessed correctly by multiple threads.']

