// Define structure for database table record
typedef struct {
    int key;
    char *value;
} Record;

// Define function to set integer field value randomly within range
void randomize_integer(Record *record, int min, int max) {
    srand(time(NULL));
    record->key = rand() % (max - min + 1) + min;
}

// Define function to update character string in each record
void update_string(Record *record, char *new_value) {
    // Check if new value is null or empty
    if (new_value == NULL || strlen(new_value) == 0) {
        return;
    }

    // Update string field in record
    free(record->value);
    record->value = malloc(strlen(new_value) + 1);
    strcpy(record->value, new_value);
}

// Define function to manage memory for database table
void manage_memory(Record *records, int num_records, int max_size) {
    // Check if number of records exceeds maximum size limit
    if (num_records > max_size) {
        return;
    }

    // Allocate memory for array of integers
    int *offsets = malloc(sizeof(int) * num_records);
    if (offsets == NULL) {
        return;
    }

    // Allocate memory for array of keys
    int *keys = malloc(sizeof(int) * num_records);
    if (keys == NULL) {
        free(offsets);
        return;
    }

    // Allocate memory for array of records
    Record *table = malloc(sizeof(Record) * num_records);
    if (table == NULL) {
        free(offsets);
        free(keys);
        return;
    }

    // Initialize arrays with default values
    for (int i = 0; i < num_records; i++) {
        offsets[i] = -1;
        keys[i] = -1;
        table[i].key = -1;
        table[i].value = "default";
    }

    // Set integer field value randomly within range
    for (int i = 0; i < num_records; i++) {
        randomize_integer(&table[i], 0, max_size);
    }

    // Update character string in each record
    for (int i = 0; i < num_records; i++) {
        update_string(&table[i], "new value");
    }

    // Free memory for arrays and table
    free(offsets);
    free(keys);
    free(table);
}
```
