```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <errno.h>

// Structure to store bitmap data
struct Bitmap {
    char* data;
    size_t size;
};

// Structure to store text file data
struct TextFile {
    char* data;
    size_t size;
    int num_lines;
};

// Structure to store the cache data
struct Cache {
    struct Bitmap** bitmaps;
    struct TextFile** text_files;
    size_t capacity;
    size_t num_entries;
    pthread_mutex_t mutex;
};

void* allocate_cache(size_t size) {
    return calloc(1, size);
}

void free_cache(void* cache) {
    struct Cache* c = (struct Cache*)cache;
    for (int i = 0; i < c->num_entries; ++i) {
        free(c->bitmaps[i]);
        free(c->text_files[i]);
    }
    free(c);
}

void* allocate_bitmap(size_t size) {
    struct Bitmap* b = malloc(sizeof(struct Bitmap));
    if (b == NULL) {
        return NULL;
    }
    b->data = calloc(1, size);
    if (b->data == NULL) {
        free(b);
        return NULL;
    }
    b->size = size;
    return b;
}

void free_bitmap(struct Bitmap* b) {
    free(b->data);
    free(b);
}

void* allocate_text_file(size_t size) {
    struct TextFile* tf = malloc(sizeof(struct TextFile));
    if (tf == NULL) {
        return NULL;
    }
    tf->data = calloc(1, size);
    if (tf->data == NULL) {
        free(tf);
        return NULL;
    }
    tf->size = size;
    return tf;
}

void free_text_file(struct TextFile* tf) {
    free(tf->data);
    free(tf);
}

int load_bitmap(const char* path, struct Bitmap* b) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        return -1;
    }
    off_t size = lseek(fd, 0, SEEK_END);
    void* buffer = mmap(NULL, size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (buffer == MAP_FAILED) {
        close(fd);
        return -1;
    }
    memcpy(b->data, buffer, b->size);
    munmap(buffer, size);
    close(fd);
    return 0;
}

int load_text_file(const char* path, struct TextFile* tf) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        return -1;
    }
    off_t size = lseek(fd, 0, SEEK_END);
    void* buffer = mmap(NULL, size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (buffer == MAP_FAILED) {
        close(fd);
        return -1;
    }
    char* line = strtok(buffer, "\n");
    int num_lines = 0;
    while (line != NULL) {
        ++num_lines;
        line = strtok(NULL, "\n");
    }
    tf->data = calloc(1, size);
    if (tf->data == NULL) {
        munmap(buffer, size);
        close(fd);
        return -1;
    }
    tf->size = size;
    tf->num_lines = num_lines;
    memcpy(tf->data, buffer, size);
    munmap(buffer, size);
    close(fd);
    return 0;
}

int process_text_file(struct TextFile* tf, int line) {
    if (line < 0 || line >= tf->num_lines) {
        return -1;
    }
    char* data = strtok(tf->data + line * (tf->size / tf->num_lines), ",");
    while (data != NULL) {
        int value = atoi(data);
        free(data);
        data = strtok(NULL, ",");
    }
    return 0;
}

int cache_bitmap(const char* path, struct Cache* c) {
    pthread_mutex_lock(&c->mutex);
    for (int i = 0; i < c->num_entries; ++i) {
        if (strcmp(c->bitmaps[i]->data, path) == 0) {
            pthread_mutex_unlock(&c->mutex);
            return 1;
        }
    }
    struct Bitmap* b = allocate_bitmap(sizeof(struct Bitmap));
    if (b == NULL) {
        pthread_mutex_unlock(&c->mutex);
        return -1;
    }
    int rc = load_bitmap(path, b);
    if (rc != 0) {
        free_bitmap(b);
        pthread_mutex_unlock(&c->mutex);
        return -1;
    }
    c->bitmaps[c->num_entries] = b;
    ++c->num_entries;
    pthread_mutex_unlock(&c->mutex);
    return 0;
}

int cache_text_file(const char* path, struct Cache* c) {
    pthread_mutex_lock(&c->mutex);
    for (int i = 0; i < c->num_entries; ++i) {
        if (strcmp(c->text_files[i]->data, path) == 0) {
            pthread_mutex_unlock(&c->mutex);
            return 1;
        }
    }
    struct TextFile* tf = allocate_text_file(sizeof(struct TextFile));
    if (tf == NULL) {
        pthread_mutex_unlock(&c->mutex);
        return -1;
    }
    int rc = load_text_file(path, tf);
    if (rc != 0) {
        free_text_file(tf);
        pthread_mutex_unlock(&c->mutex);
        return -1;
    }
    c->text_files[c->num_entries] = tf;
    ++c->num_entries;
    pthread_mutex_unlock(&c->mutex);
    return 0;
}

int cache_line(const char* path, int line) {
    struct Cache c;
    c.bitmaps = calloc(100, sizeof(struct Bitmap*));
    if (c.bitmaps == NULL) {
        return -1;
    }
    c.text_files = calloc(100, sizeof(struct TextFile*));
    if (c.text_files == NULL) {
        free(c.bitmaps);
        return -1;
    }
    pthread_mutex_init(&c.mutex, NULL);
    int rc = cache_bitmap(path, &c);
    if (rc != 0) {
        pthread_mutex_destroy(&c.mutex);
        free(c.text_files);
        free(c.bitmaps);
        return -1;
    }
    rc = cache_text_file(path, &c);
    if (rc != 0) {
        pthread_mutex_destroy(&c.mutex);
        free(c.text_files);
        free(c.bitmaps);
        return -1;
    }
    process_text_file(c.text_files[line], line);
    pthread_mutex_destroy(&c.mutex);
    free(c.text_files);
    free(c.bitmaps);
    return 0;
}

int main() {
    int rc = cache_line("example.txt", 10);
    if (rc != 0) {
        printf("Error: %d\n", rc);
        return -1;
    }
    return 0;
}
