        hash %= USER_SESSIONS_HASH_SIZE;
    }

    // If no existing session was found, allocate memory for the new session
    if (user_sessions[hash] == NULL) {
        USER_SESSION_INFO_T *new_session = malloc(sizeof(USER_SESSION_INFO_T));
        assert(new_session != NULL);
        new_session->user_id = user_id;
        new_session->session_key = session_key;
        new_session->last_active_time = last_active_time;
        user_sessions[hash] = new_session;
    }
}

// Remove an inactive user session from the hash table
void remove_inactive_user_session(int user_id, time_t last_active_time) {
    // Calculate the hash value for the user ID
    int hash = user_id % USER_SESSIONS_HASH_SIZE;

    // Check if a session with the same user ID exists in the hash table
    while (user_sessions[hash] != NULL && user_sessions[hash]->user_id == user_id) {
        // If the last active time is older than the provided timestamp, remove the session
        if (user_sessions[hash]->last_active_time < last_active_time) {
            free(user_sessions[hash]);
            user_sessions[hash] = NULL;
            break;
        }
        ++hash;
        hash %= USER_SESSIONS_HASH_SIZE;
    }
}

// Update the last active time for a user session
void update_last_active_time(int user_id, time_t new_last_active_time) {
    // Calculate the hash value for the user ID
    int hash = user_id % USER_SESSIONS_HASH_SIZE;

    // Check if a session with the same user ID exists in the hash table
    while (user_sessions[hash] != NULL && user_sessions[hash]->user_id == user_id) {
        // Update the last active time of the session
        user_sessions[hash]->last_active_time = new_last_active_time;
        break;
    }
}

// Retrieve a user session from the hash table
USER_SESSION_INFO_T *get_user_session(int user_id) {
    // Calculate the hash value for the user ID
    int hash = user_id % USER_SESSIONS_HASH_SIZE;

    // Check if a session with the same user ID exists in the hash table
    while (user_sessions[hash] != NULL && user_sessions[hash]->user_id == user_id) {
        return user_sessions[hash];
    }

    return NULL;
}

// Free memory for all user sessions when the program exits
void user_session_manager_free(void) {
    for (int i = 0; i < USER_SESSIONS_HASH_SIZE; ++i) {
        if (user_sessions[i] != NULL) {
            free(user_sessions[i]);
            user_sessions[i] = NULL;
        }
    }
}
#endif /* USER_SESSION_MANAGER_H */
