// Define data structure for a single data point
typedef struct {
    int timestamp; // Timestamp in milliseconds since epoch
    float value; // Floating-point value
    bool validity_flag; // Validity flag (true if record is valid, false otherwise)
    int ref_count; // Reference count for concurrent access
    int last_modified; // Timestamp of last modification in milliseconds since epoch
} dataPoint;

// Define data structure for an array of data points
typedef struct {
    dataPoint* records; // Array of data point structures
    size_t capacity; // Maximum number of records that can be stored
    size_t size; // Current number of records in the array
} recordArray;

// Define custom deallocation function for recordArray structure
void freeRecordArray(recordArray* arr) {
    if (arr != NULL && arr->records != NULL) {
        free(arr->records);
        arr->capacity = 0;
        arr->size = 0;
    }
}

// Define function for dynamically managing an array of data points
recordArray* createRecordArray(size_t capacity, size_t max_size) {
    if (max_size > 10000 || capacity > 500000) {
        // Prevent excessive memory allocation or fragmentation
        return NULL;
    }

    recordArray* arr = malloc(sizeof(recordArray));
    if (arr == NULL) {
        return NULL;
    }

    arr->records = calloc(capacity, sizeof(dataPoint));
    if (arr->records == NULL) {
        freeRecordArray(arr);
        return NULL;
    }

    arr->capacity = capacity;
    arr->size = 0;

    // Set initial values for metadata fields
    int i;
    for (i = 0; i < capacity; i++) {
        arr->records[i].ref_count = 1;
        arr->records[i].last_modified = time(NULL);
    }

    return arr;
}

// Define function for adding a new record to the array
bool addRecordToArray(recordArray* arr, int timestamp, float value) {
    if (arr == NULL || arr->size >= arr->capacity) {
        // Prevent excessive memory allocation or fragmentation
        return false;
    }

    dataPoint* record = &arr->records[arr->size];
    record->timestamp = timestamp;
    record->value = value;
    record->validity_flag = true;
    arr->size++;

    // Update metadata fields for concurrent access
    int i;
    for (i = 0; i < arr->capacity; i++) {
        if (arr->records[i].ref_count > 1) {
            arr->records[i].ref_count--;
            arr->records[i].last_modified = time(NULL);
        }
    }

    return true;
}

// Define function for updating a record in the array
bool updateRecordInArray(recordArray* arr, int index, int timestamp, float value) {
    if (arr == NULL || index >= arr->capacity) {
        // Prevent out-of-bounds access or invalid indices
        return false;
    }

    dataPoint* record = &arr->records[index];
    record->timestamp = timestamp;
    record->value = value;

    // Update metadata fields for concurrent access
    int i;
    for (i = 0; i < arr->capacity; i++) {
        if (&arr->records[i] != record) {
            arr->records[i].ref_count--;
            arr->records[i].last_modified = time(NULL);
        }
    }

    return true;
}

// Define function for retrieving a record from the array
dataPoint* getRecordFromArray(recordArray* arr, int index) {
    if (arr == NULL || index >= arr->capacity) {
        // Prevent out-of-bounds access or invalid indices
        return NULL;
    }

    return &arr->records[index];
}

// Define function for iterating over all records in the array
void iterateOverRecordsInArray(recordArray* arr, void (*callback)(dataPoint* record)) {
    if (arr == NULL || callback == NULL) {
        // Prevent invalid inputs or null pointers
        return;
    }

    int i;
    for (i = 0; i < arr->size; i++) {
        dataPoint* record = getRecordFromArray(arr, i);
        if (record != NULL) {
            callback(record);
        }
    }
}
