    // Check that the pointer is valid and has not been freed already
    if (ptr == NULL || *((size_t*)ptr - 1) != sizeof(Record)) {
        printf("Error: Attempt to deallocate invalid or freed memory.\n");
        return;
    }

    // Free the allocated memory using free()
    free(ptr);
}
