#define MAX_RECORDS 10000
#define MEMORY_LIMIT (1024 * 1024) // 1 MB
#define RANDOM_RANGE_MIN 1
#define RANDOM_RANGE_MAX 1000000
#define RANDOM_DEFAULT_RANGE RANDOM_RANGE_MIN, RANDOM_RANGE_MAX

typedef struct {
    long offset;
    int key;
} record;

void* allocateMemory(size_t size) {
    void* memory = NULL;
    if (size > 0 && size <= MEMORY_LIMIT) {
        memory = malloc(size);
        if (!memory) {
            fprintf(stderr, "Failed to allocate %zu bytes of memory\n", size);
            assert(false);
        }
    } else {
        fprintf(stderr, "Invalid memory allocation request: %zu bytes\n", size);
        assert(false);
    }
    return memory;
}

record* generateRandomRecords(int num_records, int random_range) {
    if (num_records <= 0 || num_records > MAX_RECORDS) {
        fprintf(stderr, "Invalid number of records: %d\n", num_records);
        assert(false);
    }
    size_t total_size = sizeof(record) * num_records;
    record* records = allocateMemory(total_size);
    if (!records) {
        return NULL;
    }
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        record* r = &records[i];
        r->offset = rand() % random_range + 1; // generate random offset within range
        r->key = rand(); // generate random key
    }
    return records;
}

void releaseMemory(void* memory) {
    free(memory);
}

int main() {
    int num_records = 5000; // default number of records per allocation cycle
    int random_range = RANDOM_DEFAULT_RANGE; // default random range for record generation
    record* records = generateRandomRecords(num_records, random_range);
    if (!records) {
        return 1;
    }
    printf("Generated %d records with offsets:", num_records);
    for (int i = 0; i < num_records; i++) {
        record* r = &records[i];
        printf(" [%ld:%d]", r->offset, r->key);
    }
    printf("\n");
    releaseMemory(records);
    return 0;
}
