#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/mman.h>
#include <pthread.h>
#include <limits.h>
#include <errno.h>
#include <assert.h>

#define MAX_USERS 10000
#define MIN_RANGE 0
#define MAX_RANGE 1000000
#define BLOCK_SIZE 4096
#define KEY_LEN 64
#define VALUE_LEN 32
#define NUM_BUCKETS 1024
#define CONCURRENT_ACCESS 8

struct user {
    char *user_id;
    char *session_id;
    long last_activity_timestamp;
};

struct key_value_pair {
    char *key;
    int value;
};

struct hash_table {
    struct key_value_pair *buckets[NUM_BUCKETS];
    pthread_mutex_t mutexes[CONCURRENT_ACCESS];
};

// Global variables
struct hash_table *hash_table;
struct user users[MAX_USERS];
int num_users = 0;

void init_hash_table(struct hash_table *ht) {
    for (int i = 0; i < NUM_BUCKETS; i++) {
        ht->buckets[i] = NULL;
    }
}

// Thread-safe insertion of a key-value pair into the hash table
void insert(struct hash_table *ht, char *key, int value) {
    pthread_mutex_lock(&ht->mutexes[hash(key)]);
    struct key_value_pair *kvp = malloc(sizeof(struct key_value_pair));
    kvp->key = key;
    kvp->value = value;
    ht->buckets[hash(key)] = kvp;
    pthread_mutex_unlock(&ht->mutexes[hash(key)]);
}

// Thread-safe lookup of a key-value pair in the hash table
int lookup(struct hash_table *ht, char *key) {
    int result = -1;
    pthread_mutex_lock(&ht->mutexes[hash(key)]);
    struct key_value_pair *kvp = ht->buckets[hash(key)];
    if (kvp != NULL && strcmp(kvp->key, key) == 0) {
        result = kvp->value;
    }
    pthread_mutex_unlock(&ht->mutexes[hash(key)]);
    return result;
}

// Thread-safe deletion of a key-value pair from the hash table
void delete(struct hash_table *ht, char *key) {
    pthread_mutex_lock(&ht->mutexes[hash(key)]);
    struct key_value_pair *kvp = ht->buckets[hash(key)];
    if (kvp != NULL && strcmp(kvp->key, key) == 0) {
        ht->buckets[hash(key)] = NULL;
    }
    pthread_mutex_unlock(&ht->mutexes[hash(key)]);
}

// Thread-safe iteration over the hash table's key-value pairs
void iterate(struct hash_table *ht, void (*callback)(char *, int)) {
    for (int i = 0; i < NUM_BUCKETS; i++) {
        pthread_mutex_lock(&ht->mutexes[i]);
        struct key_value_pair *kvp = ht->buckets[i];
        while (kvp != NULL) {
            callback(kvp->key, kvp->value);
            kvp = kvp->next;
        }
        pthread_mutex_unlock(&ht->mutexes[i]);
    }
}

// Thread-safe allocation of memory for the hash table and its buckets
void *allocate(size_t size) {
    void *ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
    if (ptr == NULL) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Thread-safe deallocation of memory for the hash table and its buckets
void deallocate(void *ptr, size_t size) {
    if (munmap(ptr, size) < 0) {
        perror("munmap");
        exit(EXIT_FAILURE);
    }
}

// Thread-safe error handling and logging for the hash table's operations
void handle_error(char *msg) {
    fprintf(stderr, "%s\n", msg);
    perror("handle_error");
    exit(EXIT_FAILURE);
}

// Thread-safe initialization of the distributed key-value store environment
void init_environment() {
    // Initialize the hash table
    hash_table = allocate(sizeof(struct hash_table));
    if (hash_table == NULL) {
        handle_error("Error allocating memory for hash table");
    }
    init_hash_table(hash_table);

    // Initialize the users array
    for (int i = 0; i < MAX_USERS; i++) {
        users[i].user_id = NULL;
        users[i].session_id = NULL;
        users[i].next = NULL;
    }

    // Initialize the user counter
    int user_counter = 0;
}

// Thread-safe addition of a new user to the distributed key-value store environment
void add_user(char *user_id, char *session_id) {
    if (user_counter >= MAX_USERS) {
        handle_error("Maximum number of users reached");
    }

    // Allocate memory for the new user and its session ID
    size_t id_len = strlen(user_id);
    size_t sid_len = strlen(session_id);
    char *new_user_id = allocate(id_len + 1);
    char *new_session_id = allocate(sid_len + 1);

    // Add the new user to the users array and increment the user counter
    strcpy(new_user_id, user_id);
    strcpy(new_session_id, session_id);
    users[user_counter].user_id = new_user_id;
    users[user_counter].session_id = new_session_id;
    user_counter++;
}

// Thread-safe removal of a user from the distributed key-value store environment
void remove_user(char *user_id) {
    // Find the user in the users array and remove it
    int index = -1;
    for (int i = 0; i < MAX_USERS; i++) {
        if (users[i].user_id != NULL && strcmp(users[i].user_id, user_id) == 0) {
            index = i;
            break;
        }
    }

    // If the user was found, remove it from the users array and free its memory
    if (index != -1) {
        deallocate(users[index].user_id, strlen(users[index].user_id));
        deallocate(users[index].session_id, strlen(users[index].session_id));
        users[index] = NULL;
    }
}

// Thread-safe lookup of a user's session ID in the distributed key-value store environment
char *lookup_user(char *user_id) {
    // Find the user in the users array and return its session ID
    int index = -1;
    for (int i = 0; i < MAX_USERS; i++) {
        if (users[i].user_id != NULL && strcmp(users[i].user_id, user_id) == 0) {
            index = i;
            break;
        }
    }

    // If the user was found, return its session ID
    if (index != -1) {
        return users[index].session_id;
    } else {
        return NULL;
    }
}
