// Define the structure to hold process information
typedef struct SYSTEM_PROCESS_INFO {
    int PROCESS_ID;
    int STATUS;
    time_t TIMESTAMP;
} SYSTEM_PROCESS_INFO;

// Define a memory pool for reusing SYSTEM_PROCESS_INFO structures
#define MEMORY_POOL_SIZE 1024 // adjust as needed
SYSTEM_PROCESS_INFO *memoryPool = NULL;

// Function to allocate and initialize a new SYSTEM_PROCESS_INFO structure
SYSTEM_PROCESS_INFO* allocProcessInfo() {
    // Check if the memory pool is empty
    if (memoryPool == NULL) {
        // If the memory pool is empty, allocate a new block of memory
        memoryPool = malloc(MEMORY_POOL_SIZE * sizeof(SYSTEM_PROCESS_INFO));
        if (memoryPool == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for process info\n");
            return NULL;
        }
    }

    // Return the next available structure from the memory pool
    SYSTEM_PROCESS_INFO *processInfo = &memoryPool[0];
    memoryPool += sizeof(SYSTEM_PROCESS_INFO);
    return processInfo;
}

// Function to generate a unique PROCESS_ID and initialize a new SYSTEM_PROCESS_INFO structure
int generateProcessId() {
    int pid = 0; // Initialize the PROCESS_ID to 0
    while (1) {
        // Check if the generated PROCESS_ID is already in use
        for (int i = 0; i < MEMORY_POOL_SIZE; i++) {
            if (memoryPool[i].PROCESS_ID == pid) {
                // If the PROCESS_ID is already in use, generate a new one
                pid++;
                break;
            }
        }
        // If the generated PROCESS_ID is not in use, return it
        if (pid > 0 && pid < INT_MAX) {
            return pid;
        }
    }
}

// Function to populate a new SYSTEM_PROCESS_INFO structure with a unique PROCESS_ID and random STATUS
void initProcessInfo(SYSTEM_PROCESS_INFO *processInfo) {
    processInfo->PROCESS_ID = generateProcessId();
    processInfo->STATUS = (rand() % 2 == 0) ? 1 : 0; // Randomly set the STATUS to either 1 or 0
    processInfo->TIMESTAMP = time(NULL);
}

// Function to check if a PROCESS_ID is already in use and generate a new one if necessary
int checkProcessId(int pid) {
    for (int i = 0; i < MEMORY_POOL_SIZE; i++) {
        if (memoryPool[i].PROCESS_ID == pid) {
            return 1; // Return 1 if the PROCESS_ID is already in use
        }
    }
    return 0; // Return 0 if the PROCESS_ID is not in use
}

// Function to allocate and initialize a new SYSTEM_PROCESS_INFO structure with a unique PROCESS_ID
SYSTEM_PROCESS_INFO* allocProcessInfoWithUniqueId() {
    int pid = generateProcessId();
    while (checkProcessId(pid)) {
        pid++;
    }
    SYSTEM_PROCESS_INFO *processInfo = allocProcessInfo();
    initProcessInfo(processInfo);
    processInfo->PROCESS_ID = pid;
    return processInfo;
}

// Function to free a SYSTEM_PROCESS_INFO structure and release its memory
void freeProcessInfo(SYSTEM_PROCESS_INFO *processInfo) {
    // Check if the memory pool is empty
    if (memoryPool == NULL) {
        return;
    }

    // Free the process information structure
    free(processInfo);

    // Update the memory pool size
    MEMORY_POOL_SIZE--;
}
