// Structure to represent a network packet header
struct PacketHeader {
    uint8_t protocolType;
    char sourceIp[16];
    char destIp[16];
    uint32_t payloadLength;
    uint32_t checksum;
};

// Structure to represent a dynamic array of network packet headers
struct PacketHeaderArray {
    struct PacketHeader **headers;
    size_t capacity;
    size_t count;
};

// Mutex lock for synchronizing access to shared resources
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize a dynamic array of network packet headers
struct PacketHeaderArray *packetHeaderArrayInit(size_t capacity) {
    struct PacketHeaderArray *array = malloc(sizeof(struct PacketHeaderArray));
    if (array == NULL) {
        return NULL;
    }
    array->headers = calloc(capacity, sizeof(struct PacketHeader *));
    if (array->headers == NULL) {
        free(array);
        return NULL;
    }
    array->capacity = capacity;
    array->count = 0;
    return array;
}

// Function to insert a network packet header into the dynamic array
void packetHeaderArrayInsert(struct PacketHeaderArray *array, struct PacketHeader header) {
    // Acquire mutex lock for synchronizing access to shared resources
    pthread_mutex_lock(&mutex);

    // Validate IP addresses before inserting the header
    if (!validateIpAddresses(header.sourceIp, header.destIp)) {
        printf("Invalid IP address detected in packet header\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Calculate checksum for the header and validate it
    uint32_t checksum = calculateChecksum(header.protocolType, header.sourceIp, header.destIp, header.payloadLength);
    if (!validateChecksum(checksum)) {
        printf("Invalid checksum detected in packet header\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Insert the header into the array
    if (array->count < array->capacity) {
        struct PacketHeader *newHeader = malloc(sizeof(struct PacketHeader));
        memcpy(newHeader, &header, sizeof(struct PacketHeader));
        newHeader->checksum = checksum;
        array->headers[array->count] = newHeader;
        array->count++;
    } else {
        printf("Array capacity exceeded\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Release mutex lock for synchronizing access to shared resources
    pthread_mutex_unlock(&mutex);
}

