int read_measurements(const char* config_file, measurement** measurements) {
    FILE* fp = NULL;
    size_t num_measurements = 0;
    int retval = 0;

    // Open the configuration file
    fp = fopen(config_file, "r");
    if (fp == NULL) {
        printf("Error opening configuration file: %s\n", config_file);
        return -1;
    }

    // Read the number of measurements from the file
    retval = fscanf(fp, "%zu", &num_measurements);
    if (retval != 1) {
        printf("Error reading number of measurements\n");
        fclose(fp);
        return -1;
    }

    // Allocate memory for the array of measurements
    *measurements = (measurement*)malloc(num_measurements * sizeof(measurement));
    if (*measurements == NULL) {
        printf("Error allocating memory for measurements\n");
        fclose(fp);
        return -1;
    }

    // Initialize each measurement's fields with data from the log files
    for (size_t i = 0; i < num_measurements; i++) {
        char timestamp_str[256];
        float temperature = 0.0f;

        // Read a line from the file
        retval = fscanf(fp, "%s %f", timestamp_str, &temperature);
        if (retval != 2) {
            printf("Error reading measurement data\n");
            fclose(fp);
            return -1;
        }

        // Convert the timestamp to a long integer
        char* endptr = NULL;
        (*measurements)[i].timestamp = strtol(timestamp_str, &endptr, 10);
        if (endptr == timestamp_str || *endptr != '\0') {
            printf("Error parsing timestamp: %s\n", timestamp_str);
            fclose(fp);
            return -1;
        }

        // Store the temperature in the measurement struct
        (*measurements)[i].temperature = temperature;
    }

    // Close the file
    fclose(fp);

    return 0;
}
