    strcpy(logFile, "stream_processing.log");

    // Define stream and thread-safe variables
    int *stream = NULL;
    size_t streamSize = 0;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    bool memoryAllocated = false;
    bool memoryOverrun = false;
    bool threadSafeError = false;

    // Read input stream from standard input
    while (true) {
        int number;
        scanf("%d", &number);
        if (number == 0) {
            break;
        } else {
            streamSize++;
            if (streamSize > MAX_INTEGERS) {
                printf("Maximum integer limit exceeded. Exiting.\n");
                exit(1);
            }
            allocateMemory(sizeof(int));
            stream = realloc(stream, sizeof(int) * streamSize);
            stream[streamSize - 1] = number;
        }
    }

    // Process the stream in a separate thread to ensure thread-safety
    pthread_t thread;
    int rc = pthread_create(&thread, NULL, processStream, (void *)stream);
    if (rc != 0) {
        logThreadSafeError();
        exit(1);
    }

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    // Print the resulting stream
    printStream(stream, streamSize);

    // Release memory allocated during processing
    deallocateMemory();

    return 0;
}

// Processes a stream of integers from standard input
void processStream(int *stream) {
    size_t streamSize = sizeof(int) * stream;
    int remainingIntegers = streamSize / sizeof(int);
    int generatedNumbers = 0;

    // Generate random numbers for each integer in the stream, ensuring no duplicates
    generateRandomNumbers(stream, streamSize);

    // Process the stream and count the number of generated numbers
    for (int i = 0; i < remainingIntegers; i++) {
        if (!isDuplicate(stream, i, stream[i])) {
            addUniqueNumber(stream, i, stream[i]);
            generatedNumbers++;
        }
    }

    // Log the number of generated numbers and remaining integers in the stream
    logRandomNumberGeneration(generatedNumbers, remainingIntegers);
}

// Checks if memory allocation is possible with the given size
bool checkMemoryAllocation(size_t size) {
    return (MEMORY_ALLOCATED + size < MAX_MEMORY);
}

// Allocates memory for a stream of integers
void allocateMemory(size_t size) {
    if (!checkMemoryAllocation(size)) {
        logMemoryOverrun();
        exit(1);
    }
    MEMORY_ALLOCATED += size;
}

// Deallocates memory for a stream of integers
void deallocateMemory() {
    MEMORY_ALLOCATED = 0;
}

// Generates random numbers within the specified range for each integer in the stream
void generateRandomNumbers(int *stream, int streamSize) {
    // Lock the mutex to ensure thread-safety
    pthread_mutex_lock(&mutex);

    // Check if memory is allocated for the stream
    if (!memoryAllocated) {
        allocateMemory(sizeof(int) * streamSize);
        memoryAllocated = true;
    }

    // Generate random numbers for each integer in the stream
    for (int i = 0; i < streamSize / sizeof(int); i++) {
        stream[i] = generateRandomNumber(MAX_RANGE) + 1;
        if (!isDuplicate(stream, i, stream[i])) {
            addUniqueNumber(stream, i, stream[i]);
        } else {
            // Log an error and exit the function if a duplicate is encountered
            logError("Duplicate number generated", 1);
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    // Unlock the mutex to ensure thread-safety
    pthread_mutex_unlock(&mutex);
}

// Adds a unique number to the array at the specified index
void addUniqueNumber(int *array, int index, int number) {
    for (int i = 0; i < index + 1; i++) {
        if (number == array[i]) {
            return;
        }
    }
    array[index] = number;
}

// Checks if a number is already in the array at the specified index
bool isDuplicate(int *array, int index, int number) {
    for (int i = 0; i < index + 1; i++) {
        if (number == array[i]) {
            return true;
        }
    }
    return false;
}

// Prints the resulting stream
void printStream(int *stream, int streamSize) {
    for (int i = 0; i < streamSize / sizeof(int); i++) {
        printf("%d\n", stream[i]);
    }
}
