// Structure for a record
typedef struct {
    int value;
} Record;

// Global variables for memory allocation
size_t max_alloc_size = 1024 * 1024 * 1024; // 1GB
size_t alloc_size = 0;
void* allocated_memory = NULL;
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory for arrays of long and int values
Record* allocate_arrays(int num_records, size_t max_record_size) {
    // Check if there is enough available memory to allocate the arrays
    if (max_alloc_size - alloc_size < (num_records * max_record_size)) {
        return NULL;
    }

    // Lock the memory allocation mutex to prevent concurrent access
    pthread_mutex_lock(&memory_lock);

    // Allocate memory for the arrays of long and int values
    size_t array_size = num_records * max_record_size;
    void* long_array = mmap(NULL, array_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    void* int_array = mmap(NULL, array_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    // Check if memory allocation failed
    if (long_array == NULL || int_array == NULL) {
        pthread_mutex_unlock(&memory_lock);
        return NULL;
    }

    // Allocate memory for an array of 'Record' structures
    Record* record_array = mmap(NULL, num_records * sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    // Check if memory allocation failed
    if (record_array == NULL) {
        pthread_mutex_unlock(&memory_lock);
        return NULL;
    }

    // Initialize the values in the arrays of long and int values
    for (int i = 0; i < num_records; ++i) {
        ((long*)long_array)[i] = rand() % max_record_size;
        ((int*)int_array)[i] = rand();
    }

    // Initialize the values in the array of 'Record' structures
    for (int i = 0; i < num_records; ++i) {
        record_array[i].value = rand() % max_record_size;
    }

    // Unlock the memory allocation mutex
    pthread_mutex_unlock(&memory_lock);

    return record_array;
}

// Function to handle memory allocation failures gracefully
void* allocate_with_backoff(int num_records, size_t max_record_size) {
    // Try allocating the arrays with a backoff strategy
    for (int i = 0; i < 5; ++i) {
        Record* record_array = allocate_arrays(num_records, max_record_size);
        if (record_array != NULL) {
            return record_array;
        }
        sleep(pow(2, i)); // Backoff strategy to reduce contention and maximize throughput
    }

    return NULL;
}
