    for (int i = 0; i < num_records; i++) {
        int random_key = rand() % 100000 + 1;
        while (i > 0 && key_array[i - 1] == random_key) {
            random_key = rand() % 100000 + 1;
        }
        record_array[i].key = random_key;
    }

    // Handle memory allocation failures and handle them gracefully by returning an appropriate error code
    if (offset_array == NULL || key_array == NULL || record_array == NULL) {
        return -2;
    }

    // Synchronize the access to the arrays to ensure thread safety
