// Data structure for records
typedef struct record {
    long offset;
    int key;
    double value;
} Record;

// Global variables
static size_t allocated_size = 0; // Current allocated memory size
static size_t initialized_count = 0; // Number of successfully initialized records
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread-safe access
static Record *records = NULL; // Pointer to the array of records

// Function to dynamically allocate memory for an array of records
Record* allocate_array(size_t count) {
    // Calculate the size of the memory needed for the array
    size_t size = sizeof(Record) * count;

    // Check if there is enough memory available to allocate the array
    if (size > allocated_size && mallinfo().arena >= size) {
        allocated_size = size;
    } else {
        // If there is not enough memory, reduce the size of the allocated array to fit within available resources
        while (mallinfo().arena < size && allocated_size > 0) {
            allocated_size /= 2;
        }
    }

    // Allocate the memory for the array using mmap()
    Record *new_records = mmap(NULL, allocated_size, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);

    // Check if the allocation was successful
    if (new_records == MAP_FAILED) {
        perror("mmap");
        return NULL;
    }

    // Initialize the records in the array randomly within specified ranges
    for (int i = 0; i < count; i++) {
        new_records[i].offset = rand() % (INT_MAX - INT_MIN);
        new_records[i].key = rand() % (INT_MAX - INT_MIN);
        new_records[i].value = ((double)rand()) / RAND_MAX;
    }

    // Lock the mutex to ensure thread-safe access
    pthread_mutex_lock(&mutex);

    // If there was previously allocated memory, free it before allocating new memory
    if (records != NULL) {
        munmap(records, allocated_size);
    }

    // Update the pointer to the array of records and the number of initialized records
    records = new_records;
    initialized_count = count;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);

    return records;
}

// Function to export the records in a CSV format to a specified file path
int export_to_csv(const char *file_path) {
    // Check if there are any initialized records
    if (initialized_count == 0) {
        fprintf(stderr, "Error: No records have been initialized\n");
        return -1;
    }

    // Open the file in write mode
    FILE *file = fopen(file_path, "w");

    // Check if the file was opened successfully
    if (file == NULL) {
        perror("fopen");
        return -1;
    }

    // Write the header row to the file
    fprintf(file, "offset,key,value\n");

    // Lock the mutex to ensure thread-safe access
    pthread_mutex_lock(&mutex);

    // Iterate through each record in the array and write it to the file
    for (int i = 0; i < initialized_count; i++) {
        fprintf(file, "%ld,%d,%f\n", records[i].offset, records[i].key, records[i].value);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);

    // Close the file
    fclose(file);

    return 0;
}

// Function to periodically validate the integrity of the allocated memory and data structures
void validate() {
    // Lock the mutex to ensure thread-safe access
    pthread_mutex_lock(&mutex);

    // Check if there are any initialized records
    if (initialized_count == 0) {
        fprintf(stderr, "Error: No records have been initialized\n");
        return;
    }

    // Iterate through each record in the array and check its integrity
    for (int i = 0; i < initialized_count; i++) {
        if (records[i].offset != ((long)rand()) % (INT_MAX - INT_MIN)) {
            fprintf(stderr, "Error: Record %d has an invalid offset\n", i);
            return;
        }
        if (records[i].key != rand() % (INT_MAX - INT_MIN)) {
            fprintf(stderr, "Error: Record %d has an invalid key\n", i);
            return;
        }
        if (records[i].value != ((double)rand()) / RAND_MAX) {
            fprintf(stderr, "Error: Record %d has an invalid value\n", i);
            return;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to resize the allocated arrays in response to changes in available memory
void resize() {
    // Check if there is enough memory available to allocate a new array of double the size
    if (mallinfo().arena >= allocated_size * 2) {
        // Lock the mutex to ensure thread-safe access
        pthread_mutex_lock(&mutex);

        // Calculate the size of the new array
        size_t new_size = allocated_size * 2;

        // Allocate the memory for the new array using mmap()
        Record *new_records = mmap(NULL, new_size, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);

        // Check if the allocation was successful
        if (new_records == MAP_FAILED) {
            perror("mmap");
            return;
        }

        // Initialize the records in the new array randomly within specified ranges
        for (int i = 0; i < initialized_count * 2; i++) {
            new_records[i].offset = rand() % (INT_MAX - INT_MIN);
            new_records[i].key = rand() % (INT_MAX - INT_MIN);
            new_records[i].value = ((double)rand()) / RAND_MAX;
        }

        // Update the pointer to the array of records and the number of initialized records
        records = new_records;
        initialized_count *= 2;

        // Unlock the mutex
        pthread_mutex_unlock(&mutex);
    }
}
```

In this example, we have implemented a simple memory management system using `mmap()` and `munmap()`. The `allocate()` function takes a size parameter and returns a pointer to a block of memory that is at least the given size. If there is not enough free memory available in the heap, the function will try to resize the heap by calling `resize()` until there is enough free memory available.

The `deallocate()` function takes a pointer to a block of memory as input and frees it back to the operating system using `munmap()`. If the given pointer points to a memory region that is not managed by this system, the function will raise an error.

The `validate()` function checks the integrity of all allocated blocks of memory in the heap by iterating through each block and checking its size and location against the information stored in the allocation table. If any inconsistencies are found, the function will print an error message to stderr.

The `resize()` function resizes the heap by allocating a new block of memory that is double the size of the current heap. The new block is then added to the end of the heap, and all allocated blocks in the old heap are moved to the new heap. The function also updates the allocation table to reflect the change in the size of the heap.

The `export_to_csv()` function takes a file path as input and exports all allocated blocks of memory in CSV format to the specified file. If there are no allocated blocks, the function will print an error message to stderr.

In this example, we have also implemented a simple validation mechanism that checks the integrity of all allocated blocks of memory at regular intervals using the `validate()` function. This mechanism can help detect any inconsistencies or corruption in the heap and prevent errors from propagating further.']

