// Implement robust validation mechanisms to ensure that the input fits within these limits, preventing buffer overflows and resource exhaustion.
// Optimize memory usage by minimizing fragmentation and leveraging existing memory pools where possible.
void allocateArrays(int *keyCount, long *offsetCount, Record **records) {
    // Check if the user input is within the valid range
    if (*keyCount <= 0 || *keyCount > 10000 || *offsetCount <= 0 || *offsetCount > 1000000) {
        printf("Invalid input. The key and offset counts must be between 1 and 10,000 respectively.\n");
        return;
    }

    // Calculate the total memory required for the arrays
    long totalMemoryRequired = (*keyCount + *offsetCount) * sizeof(Record);

    // Check if the total allocated memory exceeds 1 MB
    if (totalMemoryRequired > 1000000) {
        printf("Invalid input. The total allocated memory must not exceed 1 MB.\n");
        return;
    }

    // Dynamically allocate memory for the arrays using malloc
    long *offsets = malloc(*offsetCount * sizeof(long));
    int *keys = malloc(*keyCount * sizeof(int));
    Record *recordsArray = malloc(totalMemoryRequired);

    if (offsets == NULL || keys == NULL || recordsArray == NULL) {
        printf("Error: Memory allocation failed. Ensure that there is enough memory available.\n");
        return;
    }

    // Initialize the arrays with random values
    srand(time(NULL));
    for (int i = 0; i < *offsetCount; i++) {
        offsets[i] = rand() % 1000;
    }
    for (int i = 0; i < *keyCount; i++) {
        keys[i] = rand() % 1000;
    }
    for (int i = 0; i < (*keyCount + *offsetCount); i++) {
        recordsArray[i].key = keys[i];
        recordsArray[i].offset = offsets[i];
    }

    // Assign the pointers to the output parameters
    *records = recordsArray;
}

