// This feature introduces a trade-off between flexibility and potential for subtle bugs, emphasizing the importance of selecting appropriate default ranges.
void generateRandomNumbersWithRange(int *randomInts, int count, int minValue, int maxValue) {
    // Check if the user provided values are within the acceptable limits
    if (minValue >= 0 && maxValue > 0 && minValue < maxValue) {
        for (int i = 0; i < count; i++) {
            randomInts[i] = rand() % maxValue + minValue;
        }
    } else {
        // Default to a safe range of -100 to 100 if the user-provided values are outside acceptable limits
        for (int i = 0; i < count; i++) {
            randomInts[i] = rand() % 200 - 100;
        }
    }
}

