    int size;
    int count;
} mem_pool_t;

// Function to initialize the memory pool
void init_mem_pool(mem_pool_t *pool, int size) {
    pool->size = size;
    pool->count = 0;
    pool->pool = malloc(sizeof(tx_power_report_indication_t *) * size);
}

// Function to allocate a new TX power report indication structure from the memory pool
tx_power_report_indication_t* alloc_tx_power_report_indication(mem_pool_t *pool) {
    if (pool->count < pool->size) {
        tx_power_report_indication_t *ind = malloc(sizeof(tx_power_report_indication_t));
        pool->pool[pool->count] = ind;
        pool->count++;
        return ind;
    } else {
        // Memory pool is full, return NULL
        return NULL;
    }
}

// Function to release a TX power report indication structure from the memory pool
void free_tx_power_report_indication(mem_pool_t *pool, tx_power_report_indication_t *ind) {
    int i;
    for (i = 0; i < pool->count; i++) {
        if (pool->pool[i] == ind) {
            free(ind);
            pool->count--;
            return;
