#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <math.h>
#include <limits.h>
#include <time.h>

// Define the data structure to hold the mixed data
typedef struct {
    float *floats;
    char *identifiers;
    struct item *items;
    enum status *statuses;
} mixed_data_t;

// Function to dynamically allocate and initialize a mixed data structure
mixed_data_t* create_mixed_data(int num_floats, int num_idents, int num_items, int num_statuses) {
    // Check the inputs for validity
    if (num_floats < 0 || num_idents < 0 || num_items < 0 || num_statuses < 0) {
        printf("Invalid input: at least one of the number of floats, identifiers, items, and statuses is negative\n");
        return NULL;
    }

    // Allocate memory for the data structure
    mixed_data_t *data = malloc(sizeof(mixed_data_t));
    if (data == NULL) {
        printf("Failed to allocate memory for the data structure\n");
        return NULL;
    }

    // Initialize the floats array
    data->floats = malloc(num_floats * sizeof(float));
    if (data->floats == NULL) {
        printf("Failed to allocate memory for the floats array\n");
        free(data);
        return NULL;
    }

    // Initialize the identifiers array
    data->identifiers = malloc(num_idents * sizeof(char));
    if (data->identifiers == NULL) {
        printf("Failed to allocate memory for the identifiers array\n");
        free(data->floats);
        free(data);
        return NULL;
    }

    // Initialize the items array
    data->items = malloc(num_items * sizeof(struct item));
    if (data->items == NULL) {
        printf("Failed to allocate memory for the items array\n");
        free(data->floats);
        free(data->identifiers);
        free(data);
        return NULL;
    }

    // Initialize the statuses array
    data->statuses = malloc(num_statuses * sizeof(enum status));
    if (data->statuses == NULL) {
        printf("Failed to allocate memory for the statuses array\n");
        free(data->floats);
        free(data->identifiers);
        free(data->items);
        free(data);
        return NULL;
    }

    // Initialize the data structure fields
    data->num_floats = num_floats;
    data->num_idents = num_idents;
    data->num_items = num_items;
    data->num_statuses = num_statuses;

    return data;
}

// Function to populate the mixed data structure with sequentially increasing timestamps, randomly generated floating-point values within the specified range, and initialize metadata fields based on concurrent updates
void populate_mixed_data(mixed_data_t *data) {
    // Initialize the timestamps array
    int *timestamps = malloc(sizeof(int) * data->num_floats);
    for (int i = 0; i < data->num_floats; i++) {
        timestamps[i] = (int)(time(NULL)) + i;
    }

    // Initialize the floats array with random values within the specified range
    float *random_floats = malloc(sizeof(float) * data->num_floats);
    for (int i = 0; i < data->num_floats; i++) {
        random_floats[i] = rand() / (RAND_MAX + 1.0) * (data->max_float - data->min_float) + data->min_float;
    }

    // Initialize the identifiers array with randomly generated strings
    char **identifiers = malloc(sizeof(char *) * data->num_idents);
    for (int i = 0; i < data->num_idents; i++) {
        int identifier_len = rand() % 10 + 5; // Generate a random length between 5 and 15 characters
        identifiers[i] = malloc(identifier_len * sizeof(char));
        for (int j = 0; j < identifier_len; j++) {
            identifiers[i][j] = 'a' + rand() % ('z' - 'a'); // Generate a random character between 'a' and 'z'
        }
    }

    // Initialize the items array with randomly generated names, quantities, and prices
    struct item *items = malloc(sizeof(struct item) * data->num_items);
    for (int i = 0; i < data->num_items; i++) {
        items[i].name = identifiers[rand() % data->num_idents]; // Select a random identifier
        items[i].quantity = rand() % 10 + 1; // Generate a random quantity between 1 and 10
        items[i].price = (int)round(items[i].quantity * random_floats[rand() % data->num_floats]); // Calculate the price based on the quantity and a random float value
    }

    // Initialize the statuses array with randomly generated flags
    enum status *statuses = malloc(sizeof(enum status) * data->num_statuses);
    for (int i = 0; i < data->num_statuses; i++) {
        statuses[i] = rand() % 2 ? AVAILABLE : UNAVAILABLE; // Select a random flag between AVAILABLE and UNAVAILABLE
    }

    // Free the temporary memory used for generation
    free(timestamps);
    free(random_floats);
    for (int i = 0; i < data->num_idents; i++) {
        free(identifiers[i]);
    }
    free(identifiers);
    free(items);
    free(statuses);
}

// Function to calculate the minimum and maximum values of a float array
void calculate_float_range(float *array, int length) {
    // Initialize the minimum and maximum values to the first element in the array
    float min = array[0];
    float max = array[0];

    // Loop through the remaining elements in the array
    for (int i = 1; i < length; i++) {
        // If the current element is less than the minimum value, update it
        if (array[i] < min) {
            min = array[i];
        }
        // If the current element is greater than the maximum value, update it
        else if (array[i] > max) {
            max = array[i];
        }
    }

    // Print the minimum and maximum values
    printf("Minimum value: %f\n", min);
    printf("Maximum value: %f\n", max);
}

// Function to calculate the average of a float array
float calculate_average(float *array, int length) {
    // Initialize the sum variable
    float sum = 0;

    // Loop through the elements in the array
    for (int i = 0; i < length; i++) {
        // Add the current element to the sum
        sum += array[i];
    }

    // Calculate the average by dividing the sum by the length of the array
    float average = sum / length;

    // Return the average
    return average;
}

int main() {
    // Create a mixed data structure with 10 floats, 5 identifiers, and 3 statuses
    mixed_data_t *data = create_mixed_data(10, 5, 3);

    // Populate the mixed data structure with sequentially increasing timestamps, randomly generated floating-point values within the specified range, and initialize metadata fields based on concurrent updates
    populate_mixed_data(data);

    // Calculate the minimum and maximum values of the floats in the array
    calculate_float_range(data->floats, data->num_floats);

    // Calculate the average of the floats in the array
    float average = calculate_average(data->floats, data->num_floats);

    // Print the results
    printf("Average: %f\n", average);

    // Free the mixed data structure
    free_mixed_data(data);

    return 0;
}
