        free(result);
        return NULL;
    }
    size_t key_size = sizeof(int) * key_capacity;
    result->keys = malloc(key_size);
    if (!result->keys) {
        fprintf(stderr, "Error: failed to allocate memory for array of keys\n");
        free(result->offsets);
        free(result);
        return NULL;
    }

    // Initialize the arrays of offsets and keys.
    memset(result->offsets, 0, offset_size);
    memset(result->keys, 0, key_size);

    // Allocate memory for the array of records.
    size_t record_size = sizeof(*result->records) * num_records;
    result->records = malloc(record_size);
    if (!result->records) {
        fprintf(stderr, "Error: failed to allocate memory for array of records\n");
        free(result->keys);
        free(result->offsets);
        free(result);
        return NULL;
    }

    // Initialize the array of records.
    for (size_t i = 0; i < num_records; ++i) {
        result->records[i].key = generate_random_value(min, max);
    }

    return result;
}

void free_array_of_records(struct array_of_records* array) {
    if (!array) return;
    free(array->offsets);
    free(array->keys);
    free(array->records);
    free(array);
}

int main() {
    // Set the maximum number of records to allocate.
    const size_t max_num_records = 100;

