#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>

// Define the structure for a record
typedef struct {
    int value;
} Record;

// Define the function to manage memory for the arrays
void *manage_memory(int num_records, int max_threads) {
    // Check if the input is valid
    if (num_records <= 0 || max_threads <= 0) {
        return NULL;
    }

    // Calculate the size of each array based on the number of records and maximum threads
    int offset_size = sizeof(long) * num_records;
    int key_size = sizeof(int) * num_records;
    int record_size = sizeof(Record) * num_records;

    // Allocate memory for the arrays
    long *offsets = malloc(offset_size);
    int *keys = malloc(key_size);
    Record *records = malloc(record_size);

    // Check if the memory was allocated successfully
    if (offsets == NULL || keys == NULL || records == NULL) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize the arrays with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        offsets[i] = rand() % max_threads;
        keys[i] = rand();
        records[i].value = rand();
    }

    // Create a mutex to protect the arrays from concurrent access
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Define a function to check and release unused memory periodically
    void *check_and_release(void) {
        // Acquire the mutex before checking the memory usage
        pthread_mutex_lock(&mutex);

        // Check if there is any unused memory that can be released
        int unused = 0;
        for (int i = 0; i < num_records; ++i) {
            if (offsets[i] == -1 || keys[i] == -1 || records[i].value == -1) {
                unused++;
            }
        }

        // Release the mutex after checking the memory usage
        pthread_mutex_unlock(&mutex);

        // If there is any unused memory, release it
        if (unused > 0) {
            free(offsets + unused);
            free(keys + unused);
            free(records + unused);
        }
    }

    // Create a thread to check and release unused memory periodically
    pthread_t thread;
    if (pthread_create(&thread, NULL, check_and_release, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return NULL;
    }

    // Return the memory management structure
    struct memory_management *mm = malloc(sizeof(*mm));
    mm->offsets = offsets;
    mm->keys = keys;
    mm->records = records;
    mm->mutex = mutex;
    mm->num_records = num_records;
    return mm;
}

// Define a function to safely handle simultaneous access from multiple threads
void *acquire_record(struct memory_management *mm, int index) {
    // Acquire the mutex before accessing the record
    pthread_mutex_lock(&mm->mutex);

    // Check if the record is in use or has been released
    if (index < 0 || index >= mm->num_records || offsets[index] == -1) {
        pthread_mutex_unlock(&mm->mutex);
        return NULL;
    }

    // Return the record to the caller
    Record *record = &records[index];
    pthread_mutex_unlock(&mm->mutex);
    return record;
}

// Define a function to release an acquired record
void release_record(struct memory_management *mm, int index) {
    // Acquire the mutex before releasing the record
    pthread_mutex_lock(&mm->mutex);

    // Set the record to -1 to indicate that it is no longer in use
    offsets[index] = -1;
    keys[index] = -1;
    records[index].value = -1;

    // Release the mutex after releasing the record
    pthread_mutex_unlock(&mm->mutex);
}
