SECTION_NAME = "encrypted_metadata"

# Define the placeholder names and their corresponding values
PLACEHOLDERS: Dict[str, str] = {
    "NODE_ID": "node-1234",
    "METADATA": "encrypted_metadata"
}

def replace_placeholders(config_file: str) -> None:
    """Replace placeholders in the YAML configuration file with actual values"""

    # Load the YAML configuration file as a dictionary
    config = yq.load(config_file, yq.LoadOpts())

    # Replace each placeholder with its corresponding value
    for placeholder, value in PLACEHOLDERS.items():
        config = yq.replace(config, placeholder, value)

    # Dump the updated configuration to a new file
    with open("updated_config.yml", "w") as f:
        yq.dump(config, f, yq.DumpOpts())

def add_encrypted_metadata() -> None:
    """Add encrypted node-specific metadata to the YAML configuration file"""

    # Load the updated configuration file as a dictionary
    config = yq.load("updated_config.yml", yq.LoadOpts())

    # Add a new section to the configuration with the encrypted metadata
    config[SECTION_NAME] = {"encrypted_metadata": "some_encrypted_data"}

    # Dump the updated configuration to a new file
    with open("updated_config.yml", "w") as f:
        yq.dump(config, f, yq.DumpOpts())

def main() -> None:
    """Main function"""

    # Replace placeholders in the YAML configuration file with actual values
    replace_placeholders(CONFIG_FILE)

    # Add encrypted node-specific metadata to the YAML configuration file
    add_encrypted_metadata()
