Here is an example implementation of a C function that dynamically allocates memory for a complex data structure comprising multiple interdependent components:
```c
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct Node {
    char* string;
    double value;
    unsigned long hash;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct List {
    Node* head;
    Node* tail;
    size_t num_nodes;
} List;

List* create_list(size_t max_num_nodes) {
    if (max_num_nodes == 0) {
        return NULL;
    }

    List* list = malloc(sizeof(List));
    if (!list) {
        return NULL;
    }

    list->head = NULL;
    list->tail = NULL;
    list->num_nodes = 0;

    for (size_t i = 0; i < max_num_nodes && list->num_nodes < max_num_nodes; i++) {
        Node* node = malloc(sizeof(Node));
        if (!node) {
            free(list);
            return NULL;
        }

        // Generate random string and hash value
        char str[10];
        for (size_t j = 0; j < 10; j++) {
            str[j] = 'a' + rand() % ('z' - 'a');
        }

        node->string = strdup(str);
        node->value = (double)rand() / RAND_MAX * 10.0;
        node->hash = hash(node->string);

        // Insert node into list
        if (!list->head) {
            list->head = node;
            list->tail = node;
        } else {
            node->prev = list->tail;
            list->tail->next = node;
            list->tail = node;
        }

        list->num_nodes++;
    }

    return list;
}

void free_list(List* list) {
    if (!list) {
        return;
    }

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    free(list);
}

void insert_node(List* list, size_t index, const char* string, double value) {
    if (!list || index >= list->num_nodes) {
        return;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        return;
    }

    // Generate random string and hash value
    char str[10];
    for (size_t j = 0; j < 10; j++) {
        str[j] = 'a' + rand() % ('z' - 'a');
    }

    new_node->string = strdup(str);
    new_node->value = value;
    new_node->hash = hash(new_node->string);

    // Insert node into list
    Node* current = list->head;
    for (size_t i = 0; i < index && current; i++) {
        current = current->next;
    }

    if (!current) {
        return;
    }

    new_node->prev = current->prev;
    current->prev->next = new_node;
    current->prev = new_node;
    new_node->next = current;
}

void delete_node(List* list, size_t index) {
    if (!list || index >= list->num_nodes) {
        return;
    }

    Node* current = list->head;
    for (size_t i = 0; i < index && current; i++) {
        current = current->next;
    }

    if (!current) {
        return;
    }

    current->prev->next = current->next;
    current->next->prev = current->prev;

    free(current);
}

void modify_node(List* list, size_t index, const char* string, double value) {
    if (!list || index >= list->num_nodes) {
        return;
    }

    Node* current = list->head;
    for (size_t i = 0; i < index && current; i++) {
        current = current->next;
    }

    if (!current) {
        return;
    }

    free(current->string);
    current->string = strdup(string);
    current->value = value;
    current->hash = hash(current->string);
}
```
