// Data structure to represent a dynamic list of NFDataPdu_t structures
typedef struct {
    int size; // Size of the list
    int capacity; // Capacity of the list
    NFDataPdu_t *data; // Pointer to the array of data
} List;

// Function to create a new dynamic list
List* create_list() {
    List *list = malloc(sizeof(List));
    if (list == NULL) {
        printf("Failed to allocate memory for the list\n");
        return NULL;
    }
    list->size = 0;
    list->capacity = 16; // Initial capacity of the list
    list->data = malloc(sizeof(NFDataPdu_t) * list->capacity);
    if (list->data == NULL) {
        printf("Failed to allocate memory for the list data\n");
        free(list);
        return NULL;
    }
    return list;
}

// Function to add a new entry to the dynamic list
bool list_add(List *list, NFDataPdu_t *entry) {
    if (list->size == list->capacity) {
        // If the list is full, double its capacity and reallocate memory
        int new_capacity = 2 * list->capacity;
        NFDataPdu_t *new_data = realloc(list->data, sizeof(NFDataPdu_t) * new_capacity);
        if (new_data == NULL) {
            printf("Failed to allocate memory for the list data\n");
            free(list->data);
            return false;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->size++] = *entry;
    return true;
}

// Function to update an entry in the dynamic list based on Rnti
bool list_update(List *list, NFDataPdu_t *entry) {
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].Rnti == entry->Rnti) {
            // Update the existing entry with the new values
            memcpy(&list->data[i], entry, sizeof(NFDataPdu_t));
            return true;
        }
    }
    return false;
}

// Function to retrieve an entry from the dynamic list based on Rnti
bool list_get(List *list, int Rnti, NFDataPdu_t **entry) {
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].Rnti == Rnti) {
            // Return the pointer to the entry
            *entry = &list->data[i];
            return true;
        }
    }
    return false;
}

// Function to destroy a dynamic list
void list_destroy(List *list) {
    free(list->data);
    free(list);
}
