// Define a struct to store integer values and their corresponding indices
struct IntValue {
    int value;
    size_t index;
};

// Define a function to read an integer from standard input and validate it
int readInt(int *value) {
    // Read the next character from standard input
    char c = fgetc(stdin);

    // Check if the character is a digit
    if (isdigit(c)) {
        // Convert the character to an integer and store it in the value pointer
        *value = atoi(&c);

        // Return 1 to indicate that the value was read successfully
        return 1;
    } else {
        // Return 0 to indicate that the value was not read successfully
        return 0;
    }
}

// Define a function to validate an integer within a specified range
int validateInt(int value, int min, int max) {
    if (value >= min && value <= max) {
        // Return 1 to indicate that the value is within the specified range
        return 1;
    } else {
        // Return 0 to indicate that the value is not within the specified range
        return 0;
    }
}

// Define a function to generate a random integer within a specified range
int getRandomInt(int min, int max) {
    // Generate a random number between the minimum and maximum values
    int random = rand() % (max - min + 1) + min;

    return random;
}

// Define a function to find the largest integer in an array of integers
int findLargestInt(struct IntValue *array, size_t size) {
    // Initialize the largest value and its index to the first element of the array
    int largest = array[0].value;
    size_t largestIndex = 0;

    // Iterate over each element in the array
    for (size_t i = 1; i < size; i++) {
        // Check if the current element is larger than the largest value found so far
        if (array[i].value > largest) {
            // Update the largest value and its index to the current element
            largest = array[i].value;
            largestIndex = i;
        }
    }

    return largestIndex;
}

