    int right = size - 1;

    // Iterate until the largest value is found
    while (left <= right) {
        // Calculate the middle index of the current range
        int middle = (left + right) / 2;

        // Check if the middle element is larger than the largest value found so far
        if (array[middle].value > array[0].value) {
