    if (!arr) {
        fprintf(stderr, "Memory allocation failed. Retrying...\n");
        for (size_t i = 0; i < RETRY_COUNT; ++i) {
            arr = malloc(sizeof(integer_array_t));
            if (arr) break;
            usleep(10000); // 10 milliseconds
        }
        if (!arr) {
            fprintf(stderr, "Memory allocation failed three times. Aborting...\n");
            return NULL;
        }
    }
    arr->length = length;
    arr->integers = malloc(sizeof(int) * length);
