        arr->integers[i] = rand() % RANDOM_RANGE + RANDOM_RANGE / 2;
    }

    // Set the value of each integer in the array to a random value within a specified range
    for (size_t i = 0; i < arr->length; ++i) {
        if (arr->integers[i] == arr->integers[i - 1]) {
            // Handle duplicates appropriately
            int random_value = rand() % RANDOM_RANGE + RANDOM_RANGE / 2;
            while (random_value == arr->integers[i - 1]) {
                random_value = rand() % RANDOM_RANGE + RANDOM_RANGE / 2;
            }
            arr->integers[i] = random_value;
        }
    }

    // Integrate with an external library for generating random numbers
    extern int *generate_random_numbers(size_t length);
    integer_array_t *random_arr = generate_random_numbers(length);
    if (!random_arr) {
        fprintf(stderr, "Random number generation failed. Retrying...\n");
        for (size_t i = 0; i < RETRY_COUNT; ++i) {
            random_arr = generate_random_numbers(length);
            if (random_arr) break;
            usleep(10000); // 10 milliseconds
        }
        if (!random_arr) {
            fprintf(stderr, "Random number generation failed three times. Aborting...\n");
            free(arr->integers);
            free(arr);
            return NULL;
        }
    }

    // Combine the generated random numbers with the original array
    for (size_t i = 0; i < arr->length; ++i) {
        arr->integers[i] = rand() % RANDOM_RANGE + RANDOM_RANGE / 2;
    }

    // Release memory allocated for the integer array
    free(arr->integers);
    free(arr);

    return NULL;
}

int is_integer_valid(int i) {
    return (i >= INT_MIN && i <= INT_MAX);
}
