// Custom memory pool structure
typedef struct {
    void* data;
    size_t size;
} MemPool;

// Record structure for storing metadata
typedef struct {
    int key;
    long offset;
    char status;
    char* message;
} Record;

// Function to dynamically manage memory for storing metadata
Record* parseConfigFile(const char* filename) {
    // Open the configuration file
    FILE* fp = fopen(filename, "r");
    if (!fp) {
        printf("Error: Could not open %s\n", filename);
        return NULL;
    }

    // Initialize a linked list to store record structures
    Record* head = NULL;
    Record* current = NULL;
    size_t totalRecords = 0;

    // Memory pool for efficient allocation and deallocation of memory
    MemPool* memPool = (MemPool*) malloc(sizeof(MemPool));
    if (!memPool) {
        printf("Error: Could not allocate memory for the memory pool\n");
        fclose(fp);
        return NULL;
    }

    // Parse the file line by line
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Skip empty lines and comments
        if (strlen(line) == 0 || line[0] == '#') {
            continue;
        }

        // Split the line into its components
        char* delimiter = " :";
        char* keyString = strtok(line, delimiter);
        char* offsetString = strtok(NULL, delimiter);
        char* statusString = strtok(NULL, delimiter);
        char* messageString = strtok(NULL, delimiter);

        // Check for invalid input formats
        if (!keyString || !offsetString || !statusString || !messageString) {
            printf("Error: Invalid input format\n");
            free(line);
            fclose(fp);
            return NULL;
        }

        // Convert the components to integers and longs
        int key = atoi(keyString);
        long offset = strtol(offsetString, NULL, 10);
        char status = *statusString == 'Y' ? true : false;

        // Allocate memory for the message string
        size_t msgLen = strlen(messageString);
        if (msgLen > MAX_MESSAGE_LEN) {
            printf("Error: Message is too long\n");
            free(line);
            fclose(fp);
            return NULL;
        }
        char* msg = (char*) malloc(msgLen + 1);
        if (!msg) {
            printf("Error: Could not allocate memory for the message\n");
            free(line);
            fclose(fp);
            return NULL;
        }
        strcpy(msg, messageString);

        // Add a new record to the linked list
        if (!head) {
            head = (Record*) malloc(sizeof(Record));
            current = head;
        } else {
            current->next = (Record*) malloc(sizeof(Record));
            current = current->next;
        }
        current->key = key;
        current->offset = offset;
        current->status = status;
        current->message = msg;

        // Add the record to the memory pool
        memPool->data = current;
        memPool->size = sizeof(Record);
    }

    // Free the memory allocated for the line buffer
    free(line);

    // Close the configuration file
    fclose(fp);

    // Return the head of the linked list and the total count of records processed
    return head;
}
```
