void init_pipeline(int num_statuses, int num_iterations) {
    // Allocate memory for status structures
    struct Status *statuses = (struct Status *)malloc(sizeof(struct Status) * num_statuses);
    if (!statuses) {
        perror("Failed to allocate memory for status structures");
        exit(EXIT_FAILURE);
    }

