void filter_transactions(int size, int* age, int* count, double* weighted_sum, int* max_weighted_sum) {
    for (int i = 0; i < size; i++) {
        struct record *record = &records[i];
        if (record->valid && record->age >= age && record->count >= count && record->weighted_sum >= weighted_sum) {
            max_weighted_sum = record->weighted_sum;
            return record;
        }
    }
    return NULL;
}

void update_metrics(struct record* record, double metric_value) {
    record->metric += metric_value;
    if (record->metric > max_weighted_sum) {
        max_weighted_sum = record->metric;
    }
