    struct point* points = (struct point*)malloc(sizeof(struct point) * num_points);
    if (!points) {
        fprintf(stderr, "Error: Out of memory!\n");
        return;
    }
    struct timespec start, end;
    clock_gettime(CLOCK_REALTIME, &start);

    // Populate points with unique coordinates within a specified rectangular boundary
    for (i = 0; i < num_points; ++i) {
        points[i].x = ((double)rand() / RAND_MAX) * 100.0 - 50.0;
        points[i].y = ((double)rand() / RAND_MAX) * 100.0 - 50.0;
    }

    // Check for overlapping points and adjust coordinates accordingly
    for (i = 0; i < num_points; ++i) {
        for (j = i + 1; j < num_points; ++j) {
            if (distance(points[i], points[j]) <= 2.0) {
                points[j].x += 0.5 * (points[j].x - points[i].x);
                points[j].y += 0.5 * (points[j].y - points[i].y);
            }
        }
    }

    // Initialize and start threads for rendering
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);
    for (i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], &attr, render_thread, points)) {
            fprintf(stderr, "Error: Failed to create thread %d!\n", i + 1);
            return;
        }
