        fprintf(stderr, "Error: too many values provided. Maximum size is %d.\n", MAX_SIZE);
        exit(1);
    }

    // allocate memory for dataset
    float* dataset = malloc(sizeof(float) * num_values);
    if (dataset == NULL) {
        fprintf(stderr, "Error: unable to allocate memory for dataset. Out of memory?\n");
        exit(1);
    }

    // copy input data into allocated memory
    memcpy(dataset, data, num_values * sizeof(float));

    // integrate with external library for generating random floating-point numbers
    srand(time(NULL));
    float rand_value = (float)rand() / RAND_MAX;

    // implement linear scaling transformation to map each number to a range between 0 and 1
    for (int i = 0; i < num_values; i++) {
        dataset[i] = (dataset[i] + rand_value) / 2.0;
    }

    // optimize function for real-time performance
    #pragma omp parallel for collapse(2) reduction(+:total) schedule(static, 10)
    for (int i = 0; i < num_values; i++) {
        for (int j = 0; j < num_values; j++) {
            float sum = 0.0;
            // implement mathematical operations to meet strict latency requirements
