    double timestamp;
    float value;
    bool valid;
} DataPoint;

void process_image_batch(char** filenames, int num_images) {
    // Check if the number of images exceeds the maximum allowed
    if (num_images > MAX_IMAGES) {
        printf("Warning: Number of images exceeds maximum limit. Only processing first %d images.\n", MAX_IMAGES);
        num_images = MAX_IMAGES;
    }

    // Allocate memory for image filenames and initialize array
    char** filename_array = malloc(num_images * sizeof(char*));
    if (filename_array == NULL) {
        printf("Error: Failed to allocate memory for image filenames. Returning.\n");
        return;
    }

    // Loop through each image and load it using the image processing library
    int i = 0;
    while (i < num_images) {
        char* filename = filenames[i];
        ImageData* image = load_image(filename);
        if (image == NULL) {
            printf("Error: Failed to load image %s. Skipping.\n", filename);
            continue;
        }

        // Check image dimensions and file integrity
        if (image->width < MIN_IMAGE_DIMENSIONS || image->height < MIN_IMAGE_DIMENSIONS) {
            printf("Warning: Image %s has invalid dimensions. Skipping.\n", filename);
            continue;
        }

        // Apply filter to each image
        apply_filter(image, FILTERING_TIMEOUT_MS);

        // Add image data to the array
        filename_array[i] = image->filename;
        i++;
    }

    // Release memory for loaded images
    for (int j = 0; j < num_images; j++) {
        ImageData* image = load_image(filename_array[j]);
        free_image(image);
    }

    // Release memory for image filenames array
    free(filename_array);
}

// Loads an image using the image processing library and checks its integrity
ImageData* load_image(char* filename) {
    ImageData* image = malloc(sizeof(ImageData));
    if (image == NULL) {
        printf("Error: Failed to allocate memory for image data. Returning.\n");
        return NULL;
    }

    // Load the image using the image processing library
    image->filename = filename;
    image->width = 0;
    image->height = 0;
    image->pixels = load_image_from_file(filename);

    if (image->pixels == NULL) {
        printf("Error: Failed to load image %s. Returning.\n", filename);
        free(image);
        return NULL;
    }

    // Check image dimensions and file integrity
    image->width = get_image_width(image);
    image->height = get_image_height(image);
    if (image->width < MIN_IMAGE_DIMENSIONS || image->height < MIN_IMAGE_DIMENSIONS) {
        printf("Warning: Image %s has invalid dimensions. Skipping.\n", filename);
        free(image->pixels);
        free(image);
        return NULL;
    }

    // Apply filter to each image
    apply_filter(image, FILTERING_TIMEOUT_MS);

    return image;
}

// Frees memory allocated for an image data structure
void free_image(ImageData* image) {
    if (image == NULL) {
        return;
    }
    free(image->pixels);
    free(image);
}
