#include <semaphore.h>
#include <assert.h>

#define MAX_INPUT_SIZE 10000
#define MAX_MEMORY_ALLOCATION 1024 * 1024
#define MEMORY_POOL_SIZE 16384
#define NUM_PROCESS_INFO 500
#define PROCESS_ID_LEN 16
#define RANDOM_NUM_GENERATION_LIMIT 1000000
#define TIMEOUT 1000 // in milliseconds

struct SYSTEM_PROCESS_INFO {
    char process_id[PROCESS_ID_LEN];
    int status;
};

struct ProcessInfoQueueNode {
    struct SYSTEM_PROCESS_INFO *process_info;
    struct ProcessInfoQueueNode *next;
};

int num_processes = 0;
int num_processes_allocated = 0;
int memory_allocated = 0;
struct ProcessInfoQueueNode *process_info_queue_head = NULL;
pthread_mutex_t process_info_queue_lock = PTHREAD_MUTEX_INITIALIZER;
sem_t semaphore;

void init_memory_pool(char **memory_pool) {
    for (int i = 0; i < MEMORY_POOL_SIZE / sizeof(struct SYSTEM_PROCESS_INFO); ++i) {
        memory_pool[i] = malloc(sizeof(struct SYSTEM_PROCESS_INFO));
        assert(memory_pool[i]);
    }
}

void init_process_info_queue() {
    process_info_queue_head = NULL;
}

void add_to_process_info_queue(struct SYSTEM_PROCESS_INFO *process_info) {
    struct ProcessInfoQueueNode *new_node = malloc(sizeof(struct ProcessInfoQueueNode));
    assert(new_node);
    new_node->process_info = process_info;
    new_node->next = NULL;

    pthread_mutex_lock(&process_info_queue_lock);
    struct ProcessInfoQueueNode *current_node = process_info_queue_head;
    while (current_node != NULL) {
        if (strcmp(process_info->process_id, current_node->process_info->process_id) == 0) {
            free(new_node);
            return;
        }
        current_node = current_node->next;
    }
    if (process_info_queue_head == NULL) {
        process_info_queue_head = new_node;
    } else {
        struct ProcessInfoQueueNode *current_node = process_info_queue_head;
        while (current_node->next != NULL) {
            current_node = current_node->next;
        }
        current_node->next = new_node;
    }
    pthread_mutex_unlock(&process_info_queue_lock);
}

void remove_from_process_info_queue(struct SYSTEM_PROCESS_INFO *process_info) {
    struct ProcessInfoQueueNode *current_node = process_info_queue_head;
    while (current_node != NULL) {
        if (strcmp(process_info->process_id, current_node->process_info->process_id) == 0) {
            struct ProcessInfoQueueNode *next_node = current_node->next;
            free(current_node);
            process_info_queue_head = next_node;
            return;
        }
        current_node = current_node->next;
    }
}

struct SYSTEM_PROCESS_INFO* get_process_info_from_queue(char *process_id) {
    struct ProcessInfoQueueNode *current_node = process_info_queue_head;
    while (current_node != NULL) {
        if (strcmp(process_id, current_node->process_info->process_id) == 0) {
            return current_node->process_info;
        }
        current_node = current_node->next;
    }
    return NULL;
}

void manage_processes(char **memory_pool, int num_inputs) {
    // initialize memory pool and process info queue
    init_memory_pool(memory_pool);
    init_process_info_queue();

    for (int i = 0; i < num_inputs; ++i) {
        char *input = fgets(stdin);
        int input_length = strlen(input);
        if (input_length > MAX_INPUT_SIZE) {
            printf("Input too long, maximum input length is %d\n", MAX_INPUT_SIZE);
            continue;
        }
        char *process_id = malloc(PROCESS_ID_LEN + 1);
        assert(process_id);
        strncpy(process_id, input, PROCESS_ID_LEN);
        process_id[PROCESS_ID_LEN] = '\0';

        struct SYSTEM_PROCESS_INFO *process_info = get_process_info_from_queue(process_id);
        if (process_info != NULL) {
            // process already exists, update status
            process_info->status = random() % RANDOM_NUM_GENERATION_LIMIT;
        } else {
            // allocate memory for process info structure and populate with unique id and random status
            process_info = malloc(sizeof(struct SYSTEM_PROCESS_INFO));
            assert(process_info);
            strncpy(process_info->process_id, process_id, PROCESS_ID_LEN);
            process_info->status = random() % RANDOM_NUM_GENERATION_LIMIT;
            add_to_process_info_queue(process_info);
        }

        // allocate memory for input and copy to memory pool
        int memory_index = num_inputs - (i + 1);
        memory_pool[memory_index] = malloc(input_length + 1);
        assert(memory_pool[memory_index]);
        strncpy(memory_pool[memory_index], input, input_length);
        memory_pool[memory_index][input_length] = '\0';
    }
}

void free_memory_pool(char **memory_pool) {
    for (int i = 0; i < MEMORY_POOL_SIZE / sizeof(struct SYSTEM_PROCESS_INFO); ++i) {
        free(memory_pool[i]);
    }
}

void free_process_info_queue() {
    struct ProcessInfoQueueNode *current_node = process_info_queue_head;
    while (current_node != NULL) {
        struct ProcessInfoQueueNode *next_node = current_node->next;
        remove_from_process_info_queue(current_node->process_info);
        free(current_node);
        current_node = next_node;
    }
}

int main() {
    char **memory_pool = malloc(MEMORY_POOL_SIZE / sizeof(struct SYSTEM_PROCESS_INFO) * sizeof(char*));
    assert(memory_pool);

    int num_inputs;
    printf("Enter number of inputs: ");
    scanf("%d", &num_inputs);

    manage_processes(memory_pool, num_inputs);

    free_memory_pool(memory_pool);
    free_process_info_queue();

    return 0;
}
