// Define a memory pool to optimize memory usage and reduce fragmentation
#define MEMORY_POOL_SIZE 1024 * 1024 // Size of the memory pool in bytes
static char* memory_pool = NULL;

// Function to allocate memory for up to N structures, ensuring no duplicates
int allocate_memory(int num_structures) {
    if (num_structures > MEMORY_POOL_SIZE / sizeof(SYSTEM_PROCESS_INFO)) {
        // Memory pool is full, cannot allocate more memory
        return -1;
    }

    // Allocate memory for the structures in the pool
    SYSTEM_PROCESS_INFO* structures = (SYSTEM_PROCESS_INFO*)memory_pool;
    int i;
    for (i = 0; i < num_structures; i++) {
        structures[i].PROCESS_ID = 0;
        structures[i].status = NULL;
        structures[i].timestamp = 0;
    }

    // Set the memory pool size to the number of structures allocated
    MEMORY_POOL_SIZE = num_structures * sizeof(SYSTEM_PROCESS_INFO);

    return 0;
}

// Function to add a new structure to the list, ensuring no duplicates
