// Define the record structure
typedef struct {
    int value;
} Record;

// Define the function to initialize the arrays
void init_arrays(long arraySize, int minValue, int maxValue) {
    // Validate the input parameters
    if (arraySize <= 0 || !isPowerOfTwo(arraySize)) {
        fprintf(stderr, "Invalid array size: %ld\n", arraySize);
        exit(1);
    }
    if (minValue > maxValue) {
        fprintf(stderr, "Min value must be less than or equal to max value: %d, %d\n", minValue, maxValue);
        exit(1);
    }

    // Allocate memory for the arrays
    long *offsets = calloc(arraySize, sizeof(long));
    Record **keys = calloc(arraySize, sizeof(Record*));
    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        exit(1);
    }

    // Initialize the offsets and keys arrays
    long offset = 0;
    for (long i = 0; i < arraySize; i++) {
        offsets[i] = offset;
        Record *key = calloc(1, sizeof(Record));
        if (!key) {
            fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
            exit(1);
        }
        key->value = (int)(minValue + ((double)(maxValue - minValue) * rand()) / RAND_MAX);
        keys[i] = key;
    }

    // Initialize the mutex for thread safety
    pthread_mutex_t mutex;
    if (pthread_mutex_init(&mutex, NULL)) {
        fprintf(stderr, "Mutex initialization failed: %s\n", strerror(errno));
        exit(1);
    }

    // Define a function to free the memory allocated for the arrays
    void free_arrays() {
        if (offsets) {
            free(offsets);
        }
        if (keys) {
            free(keys);
        }
        if (mutex) {
            pthread_mutex_destroy(&mutex);
        }
    }

    // Define a function to clean up the memory allocated for the arrays in case of failure
    void cleanup() {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        free_arrays();
    }

    // Return the initialized arrays and mutex
    return offsets, keys, &mutex;
}

// Define a function to update a record in the array
void update_record(long index, int value) {
    // Check if the index is valid
    if (index >= 0 && index < arraySize) {
        Record *key = keys[index];
        if (key) {
            key->value = value;
        } else {
            fprintf(stderr, "Record not found at index %ld\n", index);
        }
    } else {
        fprintf(stderr, "Invalid record index: %ld\n", index);
    }
}

// Define a function to retrieve a record from the array
int get_record(long index) {
    // Check if the index is valid
    if (index >= 0 && index < arraySize) {
        Record *key = keys[index];
        if (key) {
            return key->value;
        } else {
            fprintf(stderr, "Record not found at index %ld\n", index);
        }
    } else {
        fprintf(stderr, "Invalid record index: %ld\n", index);
    }
}

// Define a function to release the memory allocated for the arrays
void free_arrays() {
    if (offsets) {
        free(offsets);
    }
    if (keys) {
        free(keys);
    }
    if (mutex) {
        pthread_mutex_destroy(&mutex);
    }
}
