    CONFIG_FLOAT,
    // Add more config types as needed
} ConfigType;

// Define the structure for a configuration setting
typedef struct {
    char* key;
    char* value;
    ConfigType type;
} ConfigSetting;

// Define the structure for a collection of configuration settings
typedef struct {
    int count; // Number of settings in the collection
    ConfigSetting* settings[]; // Array of configuration settings
} ConfigCollection;

// Function to manage dynamic configuration settings in a high-performance, multi-threaded environment
bool configure(ConfigCollection* config, const char* filename) {
    int configCount = 0;

    // Validate the input parameter and handle errors gracefully
    if (config == NULL || filename == NULL) {
        return false;
    }

    // Read the configuration file into a temporary buffer
    FILE* fp = fopen(filename, "r");
    char* buffer = malloc(1024);
    if (buffer == NULL) {
        perror("malloc");
        return false;
    }
    while (!feof(fp)) {
        fgets(buffer, 1024, fp);
        // Skip comments and empty lines
        if (buffer[0] != '#' && buffer[0] != '\n') {
            configCount++;
        }
    }
    fclose(fp);

    // Validate the input parameter and handle errors gracefully
    if (configCount <= 0 || configCount > MAX_CONFIG_COUNT) {
        return false;
    }

    // Allocate an array of ConfigSetting structures and initialize each setting's value based on a default configuration file provided as input
    ConfigSetting* settings = malloc(sizeof(ConfigSetting) * configCount);
    if (settings == NULL) {
        perror("malloc");
        return false;
    }
    for (int i = 0; i < configCount; i++) {
        char* key = strtok(buffer, "=");
        char* value = strtok(NULL, "\n");
        settings[i].key = key;
        settings[i].value = value;
        settings[i].type = CONFIG_STRING; // Default type is string
    }

    // Initialize the ConfigCollection structure and populate it with the configuration settings
    config->count = configCount;
    config->settings = malloc(sizeof(ConfigSetting*) * configCount);
    for (int i = 0; i < configCount; i++) {
        config->settings[i] = &settings[i];
    }

    // Implement a thread-safe mechanism to manage concurrent access to the configuration settings
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    for (int i = 0; i < configCount; i++) {
        pthread_mutex_lock(&mutex);
        if (config->settings[i] == NULL) {
            config->settings[i] = malloc(sizeof(ConfigSetting));
            config->settings[i]->key = settings[i].key;
            config->settings[i]->value = settings[i].value;
            config->settings[i]->type = CONFIG_STRING; // Default type is string
        }
        pthread_mutex_unlock(&mutex);
    }

    // Provide a mechanism to dynamically load and unload configuration files, allowing the application to adapt to changes in the environment without requiring a restart
    char* loadedFile = NULL;
    bool loading = false;
    while (true) {
        if (loading) {
            // Load the new configuration file into the ConfigCollection structure
            FILE* fp = fopen(loadedFile, "r");
            if (fp == NULL) {
                perror("fopen");
                return false;
            }
            while (!feof(fp)) {
                char* buffer = malloc(1024);
                if (buffer == NULL) {
                    perror("malloc");
                    return false;
                }
                fgets(buffer, 1024, fp);
                // Skip comments and empty lines
                if (buffer[0] != '#' && buffer[0] != '\n') {
                    int keyIndex = -1;
                    for (int i = 0; i < configCount; i++) {
                        if (strcmp(config->settings[i]->key, buffer) == 0) {
                            keyIndex = i;
                            break;
                        }
                    }
                    if (keyIndex >= 0) {
                        // Update the existing setting with the new value
                        config->settings[keyIndex]->value = strtok(buffer, "=");
                        config->settings[keyIndex]->type = CONFIG_STRING; // Default type is string
                    } else {
                        // Add a new setting to the collection
                        ConfigSetting* setting = malloc(sizeof(ConfigSetting));
                        setting->key = buffer;
                        setting->value = strtok(NULL, "\n");
                        setting->type = CONFIG_STRING; // Default type is string
                        config->settings[configCount] = setting;
                        config->count++;
                    }
                }
            }
            fclose(fp);
            loading = false;
        } else {
            // Wait for a new configuration file to be loaded or the current one to be unloaded
            pthread_mutex_lock(&mutex);
            if (loadedFile != NULL) {
                // Unload the current configuration file and reset the loadedFile pointer
                free(loadedFile);
                loadedFile = NULL;
            } else {
                loading = true;
            }
            pthread_cond_wait(&cond, &mutex);
            pthread_mutex_unlock(&mutex);
        }
    }
