        return;
    }
    // Allocate memory for the random integers
    int* random_arr = (int*)malloc(sizeof(int) * size);
    if (random_arr == NULL) {
        perror("Error allocating memory");
        exit(EXIT_FAILURE);
    }
    // Generate random integers within the specified range, and set each element in the array to a unique value.
    for (int i = 0; i < size; i++) {
        random_arr[i] = rand() % (max - min + 1) + min;
        arr[i] = random_arr[i];
    }
    // Free the memory allocated for the random integers.
    free(random_arr);
}

