using namespace std;

// Custom delimiters for parsing lines
const char DELIMITER = ',';
const char ESCAPE_CHARACTER = '\\';

// Memory management constants
const int MAX_ALLOCATION_SIZE = 1500000; // 1.5 MB
const int MEMORY_POOL_SIZE = 5000000; // 5 MB

// Random number generator settings
const int RANDOM_SEED = time(NULL);
const int RANDOM_MIN = 1;
const int RANDOM_MAX = 100;

// Error codes
const int ERROR_INSUFFICIENT_MEMORY = -1;
const int ERROR_INVALID_INPUT = -2;

class Program {
private:
    // Memory pool for allocating memory in large chunks
    class MemoryPool {
    private:
        vector<char*> freeList;
        int currentSize;
        int maxSize;

    public:
        MemoryPool(int size) : currentSize(0), maxSize(size) {}

        char* alloc(int size) {
            if (currentSize + size > maxSize) {
                return NULL;
            }

            for (auto it = freeList.begin(); it != freeList.end(); ++it) {
                if (*it == NULL || *it - (char*)NULL >= size) {
                    char* result = *it;
                    *it = NULL;
                    return result;
                }
            }

            char* result = new char[size];
            currentSize += size;
            return result;
        }

        void free(char* memory) {
            if (memory == NULL) {
                return;
            }

            for (auto it = freeList.begin(); it != freeList.end(); ++it) {
                if (*it == NULL || *it - (char*)NULL >= memory - (char*)NULL) {
                    *it = memory;
                    break;
                }
            }
        }
    };

    // Random number generator settings
    struct RandomNumberSettings {
        int seed;
        int min;
        int max;
