FILE_SYSTEM_RECORD_T** allocate_file_system_records(size_t n) {
    // Check if the input value is valid
    if (n == 0) {
        return NULL;
    }

    // Allocate memory for the list of records
    FILE_SYSTEM_RECORD_T** records = malloc(sizeof(FILE_SYSTEM_RECORD_T*) * n);
    if (records == NULL) {
        return NULL;
    }

    // Initialize each record with a unique file path and default permissions
    for (size_t i = 0; i < n; i++) {
        records[i] = malloc(sizeof(FILE_SYSTEM_RECORD_T));
        if (records[i] == NULL) {
            return NULL;
        }
        // Generate a unique file path until a non-duplicate one is found
        char* path = generate_unique_file_path();
        while (has_duplicate_file_path(path)) {
            free(path);
            path = generate_unique_file_path();
        }
        records[i]->handle = NULL;
        records[i]->path = path;
        records[i]->permissions.read = false;
        records[i]->permissions.write = false;
        records[i]->permissions.execute = false;
    }

    return records;
}

// Function to deallocate a dynamic list of FILE_SYSTEM_RECORD_T structures
void deallocate_file_system_records(FILE_SYSTEM_RECORD_T** records) {
    // Check if the input value is valid
    if (records == NULL) {
        return;
    }

    // Deallocate each record's memory
    for (size_t i = 0; i < n; i++) {
        free(records[i]->path);
        free(records[i]);
    }

    // Deallocate the list of records
    free(records);
}

// Function to generate a unique file path
char* generate_unique_file_path() {
    char* path = malloc(sizeof(char) * 1024);
    if (path == NULL) {
        return NULL;
    }
    sprintf(path, "/tmp/file-%ld.txt", time(NULL));
    return path;
}

// Function to check if a file path is already in use
bool has_duplicate_file_path(const char* path) {
    // Check if the input value is valid
    if (path == NULL) {
        return false;
    }

    // Iterate through each record and compare the file paths
    for (size_t i = 0; i < n; i++) {
        if (strcmp(records[i]->path, path) == 0) {
            return true;
        }
    }

    return false;
}

// Function to implement a memory pool for reuse of FILE_SYSTEM_RECORD_T structures
FILE_SYSTEM_RECORD_T* get_from_pool() {
    // Check if the pool is empty
    if (pool == NULL) {
        return NULL;
    }

    // Return the first record in the pool
    FILE_SYSTEM_RECORD_T* record = pool->records[0];
    pool->records[0] = NULL;

    return record;
}

// Function to add a record to the memory pool
void add_to_pool(FILE_SYSTEM_RECORD_T* record) {
    // Check if the input value is valid
    if (record == NULL) {
        return;
    }

    // Add the record to the end of the pool
    pool->records[pool->size++] = record;
}

// Function to check for memory leaks in the function
void check_for_leaks() {
    // Check if any records have been allocated but not deallocated
    for (size_t i = 0; i < n; i++) {
        if (records[i] != NULL) {
            printf("Memory leak detected: record %lu is still in use\n", i);
        }
    }
}
