        }
        // Allocate memory for the processing context
        allocate_processing_context(num_packets - 1);
        // Process the data packet
        process_data_packet(num_packets - 1);
    }
    // End the timer for measuring the duration of the batch processing
    gettimeofday(&end, NULL);
    duration = (double)((end.tv_sec * 1000000 + end.tv_usec) - (start.tv_sec * 1000000 + start.tv_usec)) / 1000000;
    // Print the average packet size and throughput for the batch processing
    printf("Average packet size: %d bytes\n", PACKET_SIZE);
    printf("Throughput: %.2f packets/second\n", (double)num_packets / duration);
