struct bloom_filter *create_bloom_filter(int size, int time_frame) {
    // Allocate memory for the bloom filter structure
    struct bloom_filter *filter = malloc(sizeof(struct bloom_filter));
    if (filter == NULL) {
        fprintf(stderr, "Failed to allocate memory for bloom filter\n");
        return NULL;
    }
    // Initialize the size and time frame of the bloom filter
    filter->size = size;
    filter->time_frame = time_frame;
    // Allocate memory for the array of bits
    filter->bits = malloc(sizeof(char) * (filter->size / 8));
    if (filter->bits == NULL) {
        fprintf(stderr, "Failed to allocate memory for bloom filter bits\n");
        free(filter);
        return NULL;
    }
    // Initialize the array of bits with all zeroes
    memset(filter->bits, 0x00, sizeof(char) * (filter->size / 8));
    // Return the initialized bloom filter structure
    return filter;
