// Define a function to check if a data packet has already been processed within the time frame of the bloom filter
int bloom_filter_check(struct bloom_filter *filter, void *data) {
    // Get the hash value for the data packet
    int hash = get_hash(data);
    // Check if the bit corresponding to the hash value is set in the array of bits
    return filter->bits[hash / 8] & (1 << (hash % 8));
}

// Define a function to add a data packet to the bloom filter for future reference
void bloom_filter_add(struct bloom_filter *filter, void *data) {
    // Get the hash value for the data packet
    int hash = get_hash(data);
    // Set the bit corresponding to the hash value in the array of bits
    filter->bits[hash / 8] |= (1 << (hash % 8));
}

// Define a function to get the hash value for a data packet
int get_hash(void *data) {
    // Calculate the hash value using the Fowler-Noll-Vo hash function
    return fnv_32a((char *)data, strlen(data), 0x811c9dc5);
