    // Initialize arrays of sensor data, device status, and records
    sensorData *sensor_data = (sensorData *)calloc(MAX_SENSOR_DATA_SIZE, sizeof(sensorData));
    deviceStatus *device_status = (deviceStatus *)calloc(MAX_DEVICE_STATUS_SIZE, sizeof(deviceStatus));
    record *records = (record *)calloc(MAX_RECORD_SIZE, sizeof(record));

