struct record* allocateRecords(int numRecords, int minKey, int maxKey) {
    // Validate input parameters to prevent memory usage from exceeding 1 MB and 500 KB limits
    if (numRecords > 10000 || maxKey - minKey > 500000) {
        printf("Invalid input parameters. Memory usage limit exceeded.");
        return NULL;
    }

    // Allocate memory for the array of records
    struct record* records = (struct record*)malloc(numRecords * sizeof(struct record));
    if (!records) {
        printf("Memory allocation failed. Retrying operation...");
        return NULL;
    }

    // Initialize each record with a unique int value within the specified range using a non-blocking random number generator
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        records[i].key = minKey + (rand() % (maxKey - minKey));
    }

    // Return the array of records
    return records;
}

// Function to handle memory allocation failures gracefully, providing user feedback and retrying the operation if necessary
