#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdio.h>
#include <stdint.h>
#include <limits.h>

#define MAX_RECORDS 1000
#define MIN_TIMESTAMP INT_MIN
#define MAX_TIMESTAMP INT_MAX
#define MIN_VALUE -FLT_MAX
#define MAX_VALUE FLT_MAX

typedef struct {
    int timestamp;
    float value;
    bool validity_flag;
} record;

typedef struct {
    record* records;
    long offset[MAX_RECORDS];
    int key[MAX_RECORDS];
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} data_store;

void init_data_store(data_store* store, size_t initial_capacity) {
    if (initial_capacity > MAX_RECORDS) {
        initial_capacity = MAX_RECORDS;
    }
    store->records = malloc(sizeof(record) * initial_capacity);
    if (!store->records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        exit(1);
    }
    memset(store->records, 0, sizeof(record) * initial_capacity);
    store->offset = malloc(sizeof(long) * initial_capacity);
    if (!store->offset) {
        fprintf(stderr, "Failed to allocate memory for offset\n");
        exit(1);
    }
    memset(store->offset, 0, sizeof(long) * initial_capacity);
    store->key = malloc(sizeof(int) * initial_capacity);
    if (!store->key) {
        fprintf(stderr, "Failed to allocate memory for key\n");
        exit(1);
    }
    memset(store->key, 0, sizeof(int) * initial_capacity);
    store->capacity = initial_capacity;
    pthread_mutex_init(&store->mutex, NULL);
    pthread_cond_init(&store->cond, NULL);
}

void deinit_data_store(data_store* store) {
    free(store->records);
    free(store->offset);
    free(store->key);
    pthread_mutex_destroy(&store->mutex);
    pthread_cond_destroy(&store->cond);
}

void insert_record(data_store* store, record* new_record) {
    int i;
    bool found = false;
    long timestamp = new_record->timestamp;
    float value = new_record->value;
    bool validity_flag = new_record->validity_flag;
    pthread_mutex_lock(&store->mutex);
    for (i = 0; i < store->capacity; ++i) {
        if (store->records[i].timestamp == timestamp && store->records[i].value == value && store->records[i].validity_flag == validity_flag) {
            found = true;
            break;
        }
    }
    if (!found) {
        for (i = 0; i < store->capacity; ++i) {
            if (store->offset[i] != -1 && store->records[i].timestamp > timestamp) {
                break;
            }
        }
        if (i == store->capacity) {
            pthread_cond_wait(&store->cond, &store->mutex);
            for (i = 0; i < store->capacity; ++i) {
                if (store->offset[i] != -1 && store->records[i].timestamp > timestamp) {
                    break;
                }
            }
        }
        if (i == store->capacity) {
            fprintf(stderr, "Insufficient capacity in data store\n");
            pthread_mutex_unlock(&store->mutex);
            return;
        }
        store->offset[i] = i + 1;
        memcpy(&store->records[i], new_record, sizeof(record));
    }
    pthread_mutex_unlock(&store->mutex);
}

void delete_record(data_store* store, long offset) {
    int i;
    for (i = 0; i < store->capacity; ++i) {
        if (store->offset[i] == offset) {
            break;
        }
    }
    if (i == store->capacity) {
        fprintf(stderr, "Invalid offset specified\n");
        return;
    }
    pthread_mutex_lock(&store->mutex);
    store->offset[i] = -1;
    memset(&store->records[i], 0, sizeof(record));
    pthread_cond_signal(&store->cond);
    pthread_mutex_unlock(&store->mutex);
}

void update_record(data_store* store, long offset, record* new_record) {
    int i;
    for (i = 0; i < store->capacity; ++i) {
        if (store->offset[i] == offset) {
            break;
        }
    }
    if (i == store->capacity) {
        fprintf(stderr, "Invalid offset specified\n");
        return;
    }
    pthread_mutex_lock(&store->mutex);
    memcpy(&store->records[i], new_record, sizeof(record));
    pthread_cond_signal(&store->cond);
    pthread_mutex_unlock(&store->mutex);
}

void* thread_routine(void* arg) {
    int i;
    data_store* store = (data_store*)arg;
    for (i = 0; i < store->capacity; ++i) {
        if (store->offset[i] != -1) {
            record* rec = &store->records[i];
            printf("Record %d: timestamp=%ld, value=%.2f, validity_flag=%d\n", i, rec->timestamp, rec->value, rec->validity_flag);
        }
    }
    return NULL;
}

int main() {
    data_store store;
    init_data_store(&store, 10);
    int i;
    for (i = 0; i < 20; ++i) {
        record rec = {i, i / 10.0, (i % 2 == 0)};
        insert_record(&store, &rec);
    }
    pthread_t thread;
    pthread_create(&thread, NULL, thread_routine, &store);
    pthread_join(thread, NULL);
    deinit_data_store(&store);
    return 0;
}
