#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>

// Define a struct to represent each record in the database
typedef struct Record {
    long offset;
    int key;
    double value;
} Record;

// Define a struct to represent the managed database
typedef struct Database {
    // Array of records
    Record* records;
    // Number of records in the database
    size_t num_records;
    // Size of the array of records
    size_t capacity;
} Database;

// Function to initialize a new empty database
Database* db_init() {
    // Allocate memory for the database structure
    Database* db = malloc(sizeof(Database));
    if (db == NULL) {
        return NULL;
    }
    // Initialize the number of records and capacity
    db->num_records = 0;
    db->capacity = 10000;
    // Allocate memory for the array of records
    db->records = malloc(db->capacity * sizeof(Record));
    if (db->records == NULL) {
        free(db);
        return NULL;
    }
    return db;
}

// Function to add a new record to the database
void db_add(Database* db, long offset, int key, double value) {
    // Check if the database is full
    if (db->num_records == db->capacity) {
        // Increase the capacity of the array of records by 10%
        size_t new_capacity = (size_t)(1.1 * db->capacity);
        Record* new_records = realloc(db->records, new_capacity * sizeof(Record));
        if (new_records == NULL) {
            // If reallocation failed, return
            return;
        }
        db->records = new_records;
        db->capacity = new_capacity;
    }
    // Add the record to the array of records
    db->records[db->num_records].offset = offset;
    db->records[db->num_records].key = key;
    db->records[db->num_records].value = value;
    // Increment the number of records
    db->num_records++;
}

// Function to remove a record from the database by key
void db_remove(Database* db, int key) {
    // Find the index of the record with the given key
    size_t i = 0;
    while (i < db->num_records && db->records[i].key != key) {
        i++;
    }
    // If the record was found, move the last record to its position and decrement the number of records
    if (i < db->num_records) {
        Record tmp = db->records[db->num_records - 1];
        db->records[i] = tmp;
        db->num_records--;
    }
}

// Function to retrieve a record from the database by key
Record* db_get(Database* db, int key) {
    // Find the index of the record with the given key
    size_t i = 0;
    while (i < db->num_records && db->records[i].key != key) {
        i++;
    }
    // If the record was found, return a pointer to it
    if (i < db->num_records) {
        return &db->records[i];
    } else {
        // Return NULL if the record was not found
        return NULL;
    }
}

// Function to free the memory allocated by the database
void db_free(Database* db) {
    // Free the array of records
    free(db->records);
    // Free the database structure itself
    free(db);
}

int main() {
    Database* db = db_init();
    // Add some records to the database
    db_add(db, 0, 123, 4.56);
    db_add(db, 1, 789, 1.23);
    db_add(db, 2, 456, -1.23);
    // Remove a record from the database
    db_remove(db, 123);
    // Retrieve a record from the database by key
    Record* rec = db_get(db, 789);
    if (rec != NULL) {
        printf("Record found: offset=%ld, key=%d, value=%.2f\n", rec->offset, rec->key, rec->value);
    } else {
        printf("Record not found\n");
    }
    // Free the memory allocated by the database
    db_free(db);
    return 0;
}']

