#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

// Define the data structure for each item in the list
typedef struct {
    float value;
    char status;
} DataItem;

// Define a linked list node to hold the data items
typedef struct Node {
    DataItem *data;
    struct Node *next;
} Node;

// Function to insert a new data item into the list
void insertData(Node **head, const float value, const char status) {
    // Create a new node for the new data item
    Node *new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Memory allocation failed! Cannot insert new data item.\n");
        return;
    }

    // Initialize the data field of the new node
    new_node->data = malloc(sizeof(DataItem));
    if (new_node->data == NULL) {
        free(new_node);
        printf("Memory allocation failed! Cannot insert new data item.\n");
        return;
    }
    new_node->data->value = value;
    new_node->data->status = status;

    // Insert the new node into the list
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node *curr = *head;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = new_node;
    }
}

// Function to retrieve a data item from the list by value
DataItem* getDataByValue(Node **head, const float value) {
    if (*head == NULL) {
        return NULL;
    }

    Node *curr = *head;
    while (curr != NULL) {
        if (curr->data->value == value) {
            return curr->data;
        }
        curr = curr->next;
    }

    return NULL;
}

// Function to delete a data item from the list by value
void deleteDataByValue(Node **head, const float value) {
    if (*head == NULL) {
        return;
    }

    Node *curr = *head;
    while (curr != NULL) {
        if (curr->data->value == value) {
            Node *prev = curr->previous;
            Node *next = curr->next;
            free(curr->data);
            free(curr);
            if (prev != NULL && next != NULL) {
                prev->next = next;
                next->previous = prev;
            } else if (prev == NULL && next != NULL) {
                *head = next;
            } else if (prev != NULL && next == NULL) {
                prev->next = NULL;
            } else {
                *head = NULL;
            }
            return;
        }
        curr = curr->next;
    }
}

// Function to traverse the list and print each data item
void traverseList(Node **head) {
    if (*head == NULL) {
        return;
    }

    Node *curr = *head;
    while (curr != NULL) {
        printf("Value: %f, Status: %c\n", curr->data->value, curr->data->status);
        curr = curr->next;
    }
}

// Function to clear all allocated memory when the data collection is no longer in use
void clearData(Node **head) {
    if (*head == NULL) {
        return;
    }

    Node *curr = *head;
    while (curr != NULL) {
        free(curr->data);
        curr = curr->next;
    }
}
