#include <string.h>
#include <assert.h>

typedef struct dataItem {
    float value;
    char statusFlag;
    void *metadataPtr;
} dataItem;

typedef struct doublyLinkedListNode {
    dataItem *data;
    struct doublyLinkedListNode *next;
    struct doublyLinkedListNode *prev;
} doublyLinkedListNode;

typedef struct dataCollection {
    doublyLinkedListNode *head;
    doublyLinkedListNode *tail;
    size_t count;
    size_t capacity;
} dataCollection;

dataItem* allocateDataItem(float value, char statusFlag, void *metadataPtr) {
    dataItem *newItem = malloc(sizeof(dataItem));
    newItem->value = value;
    newItem->statusFlag = statusFlag;
    newItem->metadataPtr = metadataPtr;
    return newItem;
}

void freeDataItem(dataItem *item) {
    free(item);
}

doublyLinkedListNode* allocateDoublyLinkedListNode(dataItem *data) {
    doublyLinkedListNode *newNode = malloc(sizeof(doublyLinkedListNode));
    newNode->data = data;
    newNode->next = NULL;
    newNode->prev = NULL;
    return newNode;
}

void freeDoublyLinkedListNode(doublyLinkedListNode *node) {
    free(node);
}

dataCollection* allocateDataCollection() {
    dataCollection *newCollection = malloc(sizeof(dataCollection));
    newCollection->head = NULL;
    newCollection->tail = NULL;
    newCollection->count = 0;
    newCollection->capacity = 10000; // maximum capacity of 10,000 items
    return newCollection;
}

void freeDataCollection(dataCollection *collection) {
    doublyLinkedListNode *current = collection->head;
    while (current != NULL) {
        doublyLinkedListNode *next = current->next;
        freeDoublyLinkedListNode(current);
        current = next;
    }
    free(collection);
}

int insertDataItem(dataCollection *collection, dataItem *item) {
    if (collection->count == collection->capacity) {
        return 1; // overflow
    }
    doublyLinkedListNode *newNode = allocateDoublyLinkedListNode(item);
    if (collection->tail == NULL) {
        collection->head = newNode;
        collection->tail = newNode;
    } else {
        collection->tail->next = newNode;
        newNode->prev = collection->tail;
        collection->tail = newNode;
    }
    collection->count++;
    return 0; // success
}

dataItem* removeDataItem(dataCollection *collection, size_t index) {
    if (index >= collection->count) {
        return NULL; // out of bounds
    }
    doublyLinkedListNode *target = collection->head;
    for (size_t i = 0; i < index; i++) {
        target = target->next;
    }
    dataItem *item = target->data;
    if (target == collection->head) {
        collection->head = target->next;
    }
    if (target == collection->tail) {
        collection->tail = target->prev;
    }
    if (target->next != NULL) {
        target->next->prev = target->prev;
    }
    if (target->prev != NULL) {
        target->prev->next = target->next;
    }
    freeDoublyLinkedListNode(target);
    collection->count--;
    return item;
}

void traverseDataCollection(dataCollection *collection, void (*visitor)(dataItem *item)) {
    doublyLinkedListNode *current = collection->head;
    while (current != NULL) {
        visitor(current->data);
        current = current->next;
    }
}

void clearDataCollection(dataCollection *collection) {
    traverseDataCollection(collection, &freeDataItem);
    freeDataCollection(collection);
}

int serializeDataCollection(dataCollection *collection, FILE *outputFile) {
    doublyLinkedListNode *current = collection->head;
    while (current != NULL) {
        dataItem *item = current->data;
        fwrite(&item->value, sizeof(float), 1, outputFile);
        fwrite(&item->statusFlag, sizeof(char), 1, outputFile);
        if (item->metadataPtr == NULL) {
            // metadata is null, write a single byte indicating this
            unsigned char metadataNull = 0;
            fwrite(&metadataNull, sizeof(unsigned char), 1, outputFile);
        } else {
            // metadata is not null, write the length of the string followed by the string
            size_t metadataLength = strlen(item->metadataPtr) + 1;
            fwrite(&metadataLength, sizeof(size_t), 1, outputFile);
            fwrite(item->metadataPtr, metadataLength, 1, outputFile);
        }
        current = current->next;
    }
    return 0; // success
}

dataCollection* deserializeDataCollection(FILE *inputFile) {
    dataCollection *newCollection = allocateDataCollection();
    while (true) {
        float value;
        fread(&value, sizeof(float), 1, inputFile);
        if (feof(inputFile)) {
            break; // end of file reached
        } else if (ferror(inputFile)) {
            freeDataCollection(newCollection);
            return NULL; // error occurred while reading from file
        }
        char statusFlag;
        fread(&statusFlag, sizeof(char), 1, inputFile);
        unsigned char metadataNull;
        fread(&metadataNull, sizeof(unsigned char), 1, inputFile);
        if (metadataNull == 0) { // metadata is null
            dataItem *item = allocateDataItem();
            item->value = value;
            item->statusFlag = statusFlag;
            item->metadataPtr = NULL;
            insertDataItem(newCollection, item);
        } else { // metadata is not null
            size_t metadataLength;
            fread(&metadataLength, sizeof(size_t), 1, inputFile);
            char *metadata = malloc(metadataLength);
            if (fread(metadata, metadataLength, 1, inputFile) != metadataLength) {
                freeDataCollection(newCollection);
                return NULL; // error occurred while reading from file
            }
            dataItem *item = allocateDataItem();
            item->value = value;
            item->statusFlag = statusFlag;
            item->metadataPtr = metadata;
            insertDataItem(newCollection, item);
        }
    }
    return newCollection; // success
}
```

