    return timestamp % HASH_TABLE_SIZE;
}

void insertIntoHashTable(hashTable *table, sensorReading reading) {
    int index = getHashIndex(reading.timestamp);
    while (table->readings[index] != NULL && table->readings[index]->timestamp < reading.timestamp) {
        index++;
        if (index == HASH_TABLE_SIZE) {
            index = 0;
        }
