#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

// Define a struct to represent a product in the collection
typedef struct Product {
    char* name;
    int quantity;
    double price;
} Product;

// Define a dynamic array of products that can grow and shrink as needed
typedef struct ProductCollection {
    Product* products; // Pointer to an array of products
    size_t capacity;   // The current capacity of the array
    size_t count;      // The number of elements in the array
} ProductCollection;

// Function to create a new product collection with a given initial capacity
ProductCollection* productCollectionCreate(size_t capacity) {
    ProductCollection* collection = (ProductCollection*) malloc(sizeof(ProductCollection));
    if (!collection) {
        fprintf(stderr, "Error: Failed to allocate memory for product collection\n");
        return NULL;
    }
    collection->products = (Product*) malloc(capacity * sizeof(Product));
    if (!collection->products) {
        free(collection);
        fprintf(stderr, "Error: Failed to allocate memory for product array\n");
        return NULL;
    }
    collection->capacity = capacity;
    collection->count = 0;
    return collection;
}

// Function to add a new product to the collection
int productCollectionAdd(ProductCollection* collection, char* name, int quantity, double price) {
    if (collection == NULL || name == NULL) {
        fprintf(stderr, "Error: Invalid arguments\n");
        return -1;
    }

    // Check if the collection has reached its capacity and trigger a resize if necessary
    if (collection->count >= collection->capacity) {
        size_t newCapacity = collection->capacity * 2;
        Product* newProducts = realloc(collection->products, newCapacity * sizeof(Product));
        if (!newProducts) {
            fprintf(stderr, "Error: Failed to resize product array\n");
            return -1;
        }
        collection->products = newProducts;
        collection->capacity = newCapacity;
    }

    // Add the new product to the end of the array
    collection->products[collection->count].name = name;
    collection->products[collection->count].quantity = quantity;
    collection->products[collection->count].price = price;
    collection->count++;
    return 0;
}

// Function to remove a product from the collection by its index
int productCollectionRemove(ProductCollection* collection, size_t index) {
    if (collection == NULL || index >= collection->count) {
        fprintf(stderr, "Error: Invalid arguments\n");
        return -1;
    }

    // Shift all the elements after the removed element to the left
    for (size_t i = index + 1; i < collection->count; i++) {
        collection->products[i - 1] = collection->products[i];
    }
    collection->count--;
    return 0;
}

// Function to update a product in the collection by its index
int productCollectionUpdate(ProductCollection* collection, size_t index, char* name, int quantity, double price) {
    if (collection == NULL || index >= collection->count) {
        fprintf(stderr, "Error: Invalid arguments\n");
        return -1;
    }

    // Update the product at the given index
    collection->products[index].name = name;
    collection->products[index].quantity = quantity;
    collection->products[index].price = price;
    return 0;
}

// Function to search for a product in the collection by its name
int productCollectionFind(ProductCollection* collection, char* name) {
    if (collection == NULL || name == NULL) {
        fprintf(stderr, "Error: Invalid arguments\n");
        return -1;
    }

    // Iterate through the products and compare their names to the given name
    for (size_t i = 0; i < collection->count; i++) {
        if (strcmp(collection->products[i].name, name) == 0) {
            return i;
        }
    }
    fprintf(stderr, "Error: Product not found\n");
    return -1;
}

// Function to free the memory used by the product collection
void productCollectionFree(ProductCollection* collection) {
    if (collection == NULL) {
        fprintf(stderr, "Error: Invalid arguments\n");
        return;
    }
    free(collection->products);
    free(collection);
}

// Function to resize the product collection when it reaches a certain threshold
void productCollectionResize(ProductCollection* collection) {
    if (collection == NULL) {
        fprintf(stderr, "Error: Invalid arguments\n");
        return;
    }

    // Double the capacity of the array and copy all elements to it
    size_t newCapacity = collection->capacity * 2;
    Product* newProducts = realloc(collection->products, newCapacity * sizeof(Product));
    if (!newProducts) {
        fprintf(stderr, "Error: Failed to resize product array\n");
        return;
    }
    collection->products = newProducts;
    collection->capacity = newCapacity;
}

// Function to handle concurrent access to the product collection
void productCollectionLock(ProductCollection* collection) {
    if (collection == NULL) {
        fprintf(stderr, "Error: Invalid arguments\n");
        return;
    }
    pthread_mutex_lock(&collection->mutex);
}

// Function to unlock the product collection after a critical section
void productCollectionUnlock(ProductCollection* collection) {
    if (collection == NULL) {
        fprintf(stderr, "Error: Invalid arguments\n");
        return;
    }
    pthread_mutex_unlock(&collection->mutex);
}

// Function to trigger a background process for asynchronously resizing the product collection
void productCollectionBackgroundResize(ProductCollection* collection) {
    if (collection == NULL) {
        fprintf(stderr, "Error: Invalid arguments\n");
        return;
    }

    // Create a new thread to handle the resize operation
    pthread_t backgroundThread;
    int error = pthread_create(&backgroundThread, NULL, productCollectionBackgroundResizeFunc, collection);
    if (error != 0) {
        fprintf(stderr, "Error: Failed to create background thread\n");
        return;
    }
}

// Function to handle the asynchronously resizing of the product collection in a new thread
void* productCollectionBackgroundResizeFunc(void* arg) {
    ProductCollection* collection = (ProductCollection*) arg;
    if (collection == NULL) {
        fprintf(stderr, "Error: Invalid arguments\n");
        return NULL;
    }

    // Check if the collection has reached its capacity and resize it if necessary
    if (collection->count >= collection->capacity) {
        productCollectionResize(collection);
    }
    return NULL;
}

// Function to handle external inventory management systems for real-time data synchronization
void productCollectionSync(ProductCollection* collection, InventorySystem system) {
    if (collection == NULL || system == NULL) {
        fprintf(stderr, "Error: Invalid arguments\n");
        return;
    }

    // Iterate through the products and synchronize their inventory levels with the external system
    for (size_t i = 0; i < collection->count; i++) {
        InventoryItem item = {collection->products[i].name, collection->products[i].quantity};
        inventorySystemUpdate(system, item);
    }
}
