// Dynamic array implementation using a linked list
struct NetworkInterfaceConfig {
    struct in_addr ip;
    struct in_addr subnet;
    struct in_addr gateway;
    char mac[6]; // MAC address as a string
};

struct NetworkInterfaceConfigList {
    struct NetworkInterfaceConfig *head;
    size_t count;
};

// Function to add a new network interface configuration
int addNetworkInterfaceConfig(struct NetworkInterfaceConfigList *list, struct in_addr ip, struct in_addr subnet, struct in_addr gateway, const char* mac) {
    // Check if the IP address is already in use
    for (struct NetworkInterfaceConfig *cur = list->head; cur != NULL; cur = cur->next) {
        if (memcmp(&ip, &(cur->ip), sizeof(struct in_addr)) == 0) {
            return -1; // Return error code
        }
    }

    // Allocate memory for the new configuration
    struct NetworkInterfaceConfig *config = malloc(sizeof(struct NetworkInterfaceConfig));
    if (config == NULL) {
        return -2; // Return error code
    }

    // Set the fields of the new configuration
    config->ip = ip;
    config->subnet = subnet;
    config->gateway = gateway;
    memcpy(config->mac, mac, 6);

    // Add the new configuration to the list
    if (list->head == NULL) {
        list->head = config;
    } else {
        struct NetworkInterfaceConfig *cur = list->head;
        while (cur->next != NULL) {
            cur = cur->next;
        }
        cur->next = config;
    }
    list->count++;

    return 0; // Return success code
}

// Function to remove a network interface configuration by IP address
int removeNetworkInterfaceConfigByIp(struct NetworkInterfaceConfigList *list, struct in_addr ip) {
    // Find the configuration with the given IP address
    for (struct NetworkInterfaceConfig *cur = list->head; cur != NULL; cur = cur->next) {
        if (memcmp(&ip, &(cur->ip), sizeof(struct in_addr)) == 0) {
            break;
        }
    }

    // If the configuration was not found, return an error code
    if (cur == NULL) {
        return -1;
    }

    // Remove the configuration from the list
    struct NetworkInterfaceConfig *prev = cur->prev;
    prev->next = cur->next;
    free(cur);
    list->count--;

    return 0; // Return success code
}

// Function to update a network interface configuration based on MAC address
int updateNetworkInterfaceConfigByMac(struct NetworkInterfaceConfigList *list, const char* mac) {
    // Find the configuration with the given MAC address
    for (struct NetworkInterfaceConfig *cur = list->head; cur != NULL; cur = cur->next) {
        if (memcmp(mac, cur->mac, 6) == 0) {
            break;
        }
    }

    // If the configuration was not found, return an error code
    if (cur == NULL) {
        return -1;
    }

    // Update the fields of the configuration
    struct in_addr ip = cur->ip;
    struct in_addr subnet = cur->subnet;
    struct in_addr gateway = cur->gateway;
    addNetworkInterfaceConfig(list, ip, subnet, gateway, mac);

    return 0; // Return success code
}

// Function to display the current network interface configurations
void printNetworkInterfaceConfigs(struct NetworkInterfaceConfigList *list) {
    printf("Current network interface configurations:\n");
    for (struct NetworkInterfaceConfig *cur = list->head; cur != NULL; cur = cur->next) {
        printf("\tIP address: %s\n", inet_ntoa(cur->ip));
        printf("\tSubnet mask: %s\n", inet_ntoa(cur->subnet));
        printf("\tGateway address: %s\n", inet_ntoa(cur->gateway));
        printf("\tMAC address: %s\n", cur->mac);
    }
}
```

