#include <pthread.h>

#define MAX_INTERFACES 1024
#define MIN_INTERVAL 5
#define MAX_RETRIES 3
#define RETRY_DELAY 5

// Struct to represent a network interface configuration
typedef struct {
    char *name;
    int type; // Ethernet, Wi-Fi, etc.
    int speed;
} interface_config_t;

// Array of interfaces to manage
interface_config_t *interfaces[MAX_INTERFACES];
int num_interfaces = 0;

// Mutex for thread safety
pthread_mutex_t lock;

// Fallback mechanism for caching data when the API is unavailable
struct {
    char name[256];
    int type;
    int speed;
} cached_data;

// Function to add a new interface configuration
int add_interface(const char *name, int type, int speed) {
    // Check for duplicate entries and invalid input
    if (get_interface_by_name(name)) {
        return -1;
    }

    // Create a new interface config structure
    interface_config_t *config = malloc(sizeof(interface_config_t));
    if (!config) {
        return -2;
    }

    // Initialize the configuration fields
    config->name = strdup(name);
    config->type = type;
    config->speed = speed;

    // Lock the mutex for thread safety
    pthread_mutex_lock(&lock);

    // Add the new interface to the array of interfaces
    if (num_interfaces >= MAX_INTERFACES) {
        pthread_mutex_unlock(&lock);
        return -3;
    }
    interfaces[num_interfaces++] = config;

    // Unlock the mutex
    pthread_mutex_unlock(&lock);

    return 0;
}

// Function to remove an existing interface configuration
int remove_interface(const char *name) {
    // Check for invalid input
    if (!name || !get_interface_by_name(name)) {
        return -1;
    }

    // Lock the mutex for thread safety
    pthread_mutex_lock(&lock);

    // Find the interface to remove and update the array of interfaces accordingly
    int i = 0;
    while (i < num_interfaces) {
        if (!strcmp(name, interfaces[i]->name)) {
            free(interfaces[i]);
            memmove(&interfaces[i], &interfaces[i+1], sizeof(interface_config_t*) * (num_interfaces - i));
            num_interfaces--;
            break;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&lock);

    return 0;
}

// Function to update an existing interface configuration
int update_interface(const char *name, int type, int speed) {
    // Check for invalid input
    if (!name || !get_interface_by_name(name)) {
        return -1;
    }

    // Lock the mutex for thread safety
    pthread_mutex_lock(&lock);

    // Find the interface to update and update its fields accordingly
    int i = 0;
    while (i < num_interfaces) {
        if (!strcmp(name, interfaces[i]->name)) {
            interfaces[i]->type = type;
            interfaces[i]->speed = speed;
            break;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&lock);

    return 0;
}

// Function to retrieve an existing interface configuration by name
interface_config_t *get_interface_by_name(const char *name) {
    if (!name) {
        return NULL;
    }

    // Lock the mutex for thread safety
    pthread_mutex_lock(&lock);

    // Find the interface by name and unlock the mutex
    int i = 0;
    while (i < num_interfaces) {
        if (!strcmp(name, interfaces[i]->name)) {
            return interfaces[i];
        }
    }

    pthread_mutex_unlock(&lock);

    return NULL;
}

// Function to retrieve an existing interface configuration by index
interface_config_t *get_interface_by_index(int index) {
    if (index < 0 || index >= num_interfaces) {
        return NULL;
    }

    // Lock the mutex for thread safety
    pthread_mutex_lock(&lock);

    // Find the interface by index and unlock the mutex
    int i = 0;
    while (i < num_interfaces) {
        if (index == i++) {
            return interfaces[i];
        }
    }

    pthread_mutex_unlock(&lock);

    return NULL;
}
