    int statusFlags;
    long lastUpdated;
    struct sensorID* idNode;
};

struct configParams {
    float thresholdValues[2];
    int loggingIntervals[2];
    int enableFeatures[2];
};

// Hash table for fast lookup of sensor IDs
struct hashTable {
    struct sensorID** sensorIDs;
    size_t size;
    size_t count;
};

// Memory pool for record structures
struct recordPool {
    struct record* records;
    size_t capacity;
    size_t count;
};

// Semaphore for synchronizing access to the hash table and memory pool
sem_t semaphore;

// Function to initialize the memory pool and hash table
void initMemory(struct recordPool* pool, struct hashTable* table) {
    // Initialize the record pool with a fixed size of M records
    pool->records = malloc(sizeof(struct record) * M);
    assert(pool->records != NULL);
    pool->capacity = M;
    pool->count = 0;

    // Initialize the hash table with a fixed size of N entries
    table->sensorIDs = malloc(sizeof(struct sensorID*) * N);
    assert(table->sensorIDs != NULL);
    table->size = N;
    table->count = 0;
}

// Function to manage memory for a complex system involving multiple interconnected data structures
void manageMemory(struct recordPool* pool, struct hashTable* table) {
    // Acquire the semaphore for synchronizing access to the hash table and memory pool
    sem_wait(&semaphore);

    // Check if the memory pool is full
    if (pool->count == pool->capacity) {
        // Double the capacity of the memory pool
        pool->records = realloc(pool->records, sizeof(struct record) * pool->capacity * 2);
        assert(pool->records != NULL);
        pool->capacity *= 2;
    }

    // Check if the hash table is full
    if (table->count == table->size) {
        // Double the size of the hash table
        table->sensorIDs = realloc(table->sensorIDs, sizeof(struct sensorID*) * table->size * 2);
        assert(table->sensorIDs != NULL);
        table->size *= 2;
    }

    // Release the semaphore
    sem_post(&semaphore);
}

// Function to allocate a new record structure and add it to the memory pool
void allocRecord(struct recordPool* pool, struct hashTable* table) {
    manageMemory(pool, table);

    // Allocate a new record structure
    struct record* record = malloc(sizeof(struct record));
    assert(record != NULL);

    // Set the value of the record to a random value within a specified range
    record->value = (rand() % 10) + 1;

    // Add the record to the memory pool and hash table
    pool->records[pool->count] = record;
    table->sensorIDs[table->count] = &record->idPtr;

    pool->count++;
    table->count++;
}

// Function to allocate a new sensor data structure and add it to the memory pool
void allocSensorData(struct recordPool* pool, struct hashTable* table) {
    manageMemory(pool, table);

