    char gateway_address[INET_ADDRSTRLEN];
    char mac_address[18];
} network_interface_config;

// Define a dynamic array to store the network interface configurations
network_interface_config *configs = NULL;
size_t configs_capacity = 0;

// Define a function to add a new configuration to the dynamic array
void add_configuration(const char *ip, const char *subnet, const char *gateway, const char *mac) {
    // Check if the dynamic array has enough capacity for a new configuration
    if (configs_capacity == 0 || configs_capacity == SIZE_MAX / sizeof(*configs)) {
        return;
    }

    // Allocate memory for a new network interface configuration structure
    network_interface_config *new_config = malloc(sizeof(*new_config));
    if (new_config == NULL) {
        return;
    }

    // Copy the IP address, subnet mask, gateway address, and MAC address into the new configuration structure
    strncpy(new_config->ip_address, ip, INET_ADDRSTRLEN);
    strncpy(new_config->subnet_mask, subnet, INET_ADDRSTRLEN);
    strncpy(new_config->gateway_address, gateway, INET_ADDRSTRLEN);
    strncpy(new_config->mac_address, mac, 18);

    // Append the new configuration to the dynamic array
    configs = realloc(configs, (++configs_capacity) * sizeof(*configs));
    if (configs == NULL) {
        free(new_config);
        return;
    }
    configs[configs_capacity - 1] = new_config;
}

// Define a function to remove an existing configuration from the dynamic array by IP address
void remove_configuration(const char *ip) {
    // Iterate over the dynamic array and find the index of the configuration with the matching IP address
    size_t config_index = 0;
    for (; config_index < configs_capacity; ++config_index) {
        if (strncmp(ip, configs[config_index]->ip_address, INET_ADDRSTRLEN) == 0) {
            break;
        }
    }

    // Check if the configuration was found and remove it from the dynamic array
    if (config_index < configs_capacity) {
        free(configs[config_index]);
        --configs_capacity;
        memmove(&configs[config_index], &configs[config_index + 1], (configs_capacity - config_index) * sizeof(*configs));
    }
}

// Define a function to update an existing configuration in the dynamic array based on MAC address
void update_configuration(const char *mac, const char *ip, const char *subnet, const char *gateway) {
    // Iterate over the dynamic array and find the index of the configuration with the matching MAC address
    size_t config_index = 0;
    for (; config_index < configs_capacity; ++config_index) {
        if (strncmp(mac, configs[config_index]->mac_address, 18) == 0) {
            break;
        }
    }

    // Check if the configuration was found and update it with the new IP address, subnet mask, gateway address, and MAC address
    if (config_index < configs_capacity) {
        strncpy(configs[config_index]->ip_address, ip, INET_ADDRSTRLEN);
        strncpy(configs[config_index]->subnet_mask, subnet, INET_ADDRSTRLEN);
        strncpy(configs[config_index]->gateway_address, gateway, INET_ADDRSTRLEN);
    }
}

// Define a function to revalidate the configurations against updated routing tables in response to detected network topology changes
void revalidate_configurations() {
    // Iterate over the dynamic array and check if each configuration's IP address is still reachable
    size_t config_index = 0;
    for (; config_index < configs_capacity; ++config_index) {
