struct record* allocate_records(int num_records, int range_start, int range_end, size_t offset_size) {
    if (num_records < 0 || range_start > range_end || offset_size == 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    struct record* records = malloc(sizeof(*records) * num_records);
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records: %s\n", strerror(errno));
        return NULL;
    }

    // Initialize the offsets array
    long* offsets = malloc(offset_size * num_records);
    if (offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offsets: %s\n", strerror(errno));
        free(records);
        return NULL;
    }

    // Initialize the keys array
    int* keys = malloc(sizeof(*keys) * num_records);
    if (keys == NULL) {
        fprintf(stderr, "Failed to allocate memory for keys: %s\n", strerror(errno));
        free(offsets);
        free(records);
        return NULL;
    }

    // Initialize the records array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        int key = rand() % (range_end - range_start + 1) + range_start;
        long offset = (long)(key * 100.0);
        records[i].offset = offsets + i * offset_size;
        records[i].key = keys[i] = key;
    }

    // Handle memory allocation failures gracefully
    if (records == NULL || offsets == NULL || keys == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    return records;
}

