// Structure to represent a node in the linked list
typedef struct NFAP_CRC_INDICATION_PDU {
    RX_UE_INFORMATION_TAG *rxUETag;
    RNTI rnti;
    CRCFLAG crcFlag;
} NFAP_CRC_INDICATION_PDU_T;

// Structure to represent the linked list
typedef struct NFAP_CRC_INDICATION_LIST {
    pthread_mutex_t lock; // Mutex to prevent race conditions
    NFAP_CRC_INDICATION_PDU_T *head; // Pointer to the first node in the list
    size_t size; // Number of nodes in the list
} NFAP_CRC_INDICATION_LIST_T;

// Function to allocate a new node and add it to the list
void addToNFAP_CRC_INDICATION_LIST(NFAP_CRC_INDICATION_LIST_T *list, RX_UE_INFORMATION_TAG *rxUETag, RNTI rnti, CRCFLAG crcFlag) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&list->lock);

    // Allocate a new node and initialize it with the given data
    NFAP_CRC_INDICATION_PDU_T *newNode = (NFAP_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAP_CRC_INDICATION_PDU_T));
    newNode->rxUETag = rxUETag;
    newNode->rnti = rnti;
    newNode->crcFlag = crcFlag;

    // Add the new node to the list, keeping track of its size
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        NFAP_CRC_INDICATION_PDU_T *currNode = list->head;
        while (currNode->next != NULL) {
            currNode = currNode->next;
        }
        currNode->next = newNode;
