#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_CRC_INDICATION_LIST {
    pthread_mutex_t mutex;
    semaphore_t semaphore;
    size_t capacity;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T* entries;
} NFAPI_CRC_INDICATION_LIST;

void init_crc_indication_list(NFAPI_CRC_INDICATION_LIST* list) {
    pthread_mutex_init(&list->mutex, NULL);
    semaphore_init(&list->semaphore, 0, SEM_PRIO_NONE);
    list->capacity = 10; // initial capacity of 10 entries
    list->count = 0;
    list->entries = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
}

void destroy_crc_indication_list(NFAPI_CRC_INDICATION_LIST* list) {
    pthread_mutex_destroy(&list->mutex);
    semaphore_destroy(&list->semaphore);
    free(list->entries);
}

void add_crc_indication(NFAPI_CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T* entry) {
    pthread_mutex_lock(&list->mutex);
    semaphore_wait(&list->semaphore);

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_entries = realloc(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (new_entries == NULL) {
            // handle allocation failure gracefully
            pthread_mutex_unlock(&list->mutex);
            semaphore_post(&list->semaphore);
            return;
        }

        list->entries = new_entries;
        list->capacity = new_capacity;
    }

    list->entries[list->count++] = *entry;
    semaphore_post(&list->semaphore);
    pthread_mutex_unlock(&list->mutex);
}

void remove_crc_indication(NFAPI_CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T* entry) {
    pthread_mutex_lock(&list->mutex);
    semaphore_wait(&list->semaphore);

    size_t index = 0;
    while (index < list->count && list->entries[index].rnti != entry->rnti) {
        index++;
    }

    if (index == list->count) {
        pthread_mutex_unlock(&list->mutex);
        semaphore_post(&list->semaphore);
        return;
    }

    size_t last = list->count - 1;
    list->entries[index] = list->entries[last];
    list->count--;

    if (list->count < list->capacity / 4) {
        // shrink the capacity if fewer than 1/4 are used
        size_t new_capacity = list->capacity / 2;
        NFAPI_CRC_INDICATION_PDU_T* new_entries = realloc(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (new_entries == NULL) {
            // handle allocation failure gracefully
            pthread_mutex_unlock(&list->mutex);
            semaphore_post(&list->semaphore);
            return;
        }

        list->entries = new_entries;
        list->capacity = new_capacity;
    }

    semaphore_post(&list->semaphore);
    pthread_mutex_unlock(&list->mutex);
}

void clear_crc_indication_list(NFAPI_CRC_INDICATION_LIST* list) {
    pthread_mutex_lock(&list->mutex);
    semaphore_wait(&list->semaphore);

    free(list->entries);
    list->capacity = 10; // initial capacity of 10 entries
    list->count = 0;
    list->entries = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);

    semaphore_post(&list->semaphore);
    pthread_mutex_unlock(&list->mutex);
}
