#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Custom comparison function to handle ties in priority by string length
int compare_nodes(const void* node1, const void* node2) {
    // Get the node structures from the void pointers
    struct node* n1 = (struct node*)node1;
    struct node* n2 = (struct node*)node2;

    // Compare priorities first
    if (n1->priority > n2->priority) {
        return 1;
    } else if (n1->priority < n2->priority) {
        return -1;
    }

    // If priorities are equal, compare string lengths
    if (strlen(n1->data) > strlen(n2->data)) {
        return 1;
    } else if (strlen(n1->data) < strlen(n2->data)) {
        return -1;
    }

    // If all else fails, compare the strings lexicographically
    return strcmp(n1->data, n2->data);
}

// Node structure for the priority queue
struct node {
    char* data;  // dynamically allocated string
    int priority;
    struct node* next;
};

// Function to insert a new node with a given priority and string into the queue
void insert_node(struct node** head, int priority, const char* data) {
    // Allocate memory for the new node
    struct node* new_node = (struct node*)malloc(sizeof(struct node));
    if (!new_node) {
        fprintf(stderr, "Error: failed to allocate memory for new node\n");
        return;
    }

    // Copy the string and set its priority
    new_node->data = strdup(data);
    new_node->priority = priority;
    new_node->next = NULL;

    // Insert the new node into the queue
    struct node* current = *head;
    while (current && compare_nodes(&new_node, &current) > 0) {
        current = current->next;
    }
    new_node->next = current;
    if (current == NULL) {
        *head = new_node;
    }
}

// Function to remove the node with the highest priority from the queue
struct node* pop_node(struct node** head) {
    // If the queue is empty, return NULL
    if (*head == NULL) {
        return NULL;
    }

    // Remove the first node and update the head pointer
    struct node* current = *head;
    *head = current->next;

    // Free the memory for the popped node
    free(current);
}

// Function to access the front node of the queue without modifying it
struct node* peek_node(const struct node* head) {
    return head;
}
```
This implementation includes efficient insertion and deletion operations based on priority, ensuring nodes are sorted correctly upon insertion. It also includes a custom comparison function to handle ties in priority by string length, which is called from the `compare_nodes` function.

