// Structure to represent each node in the tree
typedef struct Node {
    char* string; // dynamically allocated string
    int priority;
    struct Node* parent; // pointer to parent node
    struct Node** children; // array of pointers to child nodes
} Node;

// Function to create a new node with the given string and priority
Node* newNode(char* string, int priority) {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        return NULL;
    }
    node->string = strdup(string);
    node->priority = priority;
    node->parent = NULL;
    node->children = NULL;
    return node;
}

// Function to insert a new node into the tree
Node* insertNode(Node* root, char* string, int priority) {
    if (!root) {
        // If the tree is empty, create a new root node
        root = newNode(string, priority);
    } else {
        // Otherwise, search for the appropriate location to insert the node
        Node* current = root;
        while (current->children) {
            if (strcmp(current->string, string) < 0) {
                current = current->children[0];
            } else if (strcmp(current->string, string) > 0) {
                current = current->children[1];
            } else {
                // If the node already exists, update its priority and return
                current->priority = priority;
                return current;
            }
        }
        // Add a new child node to the current node
        Node* child = newNode(string, priority);
        if (!child) {
            return NULL;
        }
        current->children[1] = child;
        child->parent = current;
    }
    return root;
}

// Function to delete a node from the tree
void deleteNode(Node* root, char* string) {
    if (!root) {
        // If the tree is empty, do nothing
        return;
    } else if (strcmp(root->string, string) == 0) {
        // If the node to be deleted is the root, replace it with its child
        Node* child = root->children[1];
        free(root);
        root = child;
        return;
    } else if (strcmp(root->string, string) > 0) {
        // Otherwise, recursively search for the appropriate location to delete the node
        deleteNode(root->children[0], string);
    } else {
        // If the node is not found, do nothing
        return;
    }
}

// Function to traverse the tree in-order and print each node's string
void traverseTree(Node* root) {
    if (!root) {
        return;
    }
    traverseTree(root->children[0]);
    printf("%d: %s\n", root->priority, root->string);
    traverseTree(root->children[1]);
}

// Function to search for a node in the tree based on priority and string content
Node* findNode(Node* root, char* string) {
    if (!root) {
        return NULL;
    } else if (strcmp(root->string, string) == 0) {
        // If the node is found, return it
        return root;
    } else if (strcmp(root->string, string) > 0) {
        // Otherwise, recursively search for the appropriate location to find the node
        return findNode(root->children[0], string);
    } else {
        // If the node is not found, return NULL
        return NULL;
    }
}
