int establishConnection(struct ConnectionManager *manager, struct sockaddr_in *server_address) {
    // Check if the maximum number of connections has been reached
    if (manager->num_connections >= manager->max_connections) {
        printf("Maximum number of connections reached\n");
        return -1;
    }
    // Create a new socket for the connection
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        printf("Socket creation error: %s\n", strerror(errno));
        return -1;
    }
    // Establish the connection with the server
    if (connect(sock, (struct sockaddr *) server_address, sizeof(struct sockaddr)) < 0) {
        printf("Connection establishment error: %s\n", strerror(errno));
        close(sock);
        return -1;
    }
    // Increment the number of established connections
    manager->num_connections++;
    return sock;
}

void closeConnection(struct ConnectionManager *manager, int sock) {
    // Check if the socket is valid
    if (sock < 0) {
        printf("Invalid socket\n");
        return;
    }
    // Close the connection
    if (close(sock) < 0) {
        printf("Connection closure error: %s\n", strerror(errno));
        return;
    }
    // Decrement the number of established connections
    manager->num_connections--;
}

