    // Check if the arrays were allocated successfully
    if (offset_arr == NULL || key_arr == NULL || record_arr == NULL) {
        printf("Error: Failed to allocate memory for arrays.\n");
        return;
    }

    // Fill the offset, key, and record arrays with random integers within a specified range
    srand(time(NULL));
    for (int i = 0; i < MAX_INPUT_SIZE; i++) {
        offset_arr[i] = rand() % 100 + 1;
        key_arr[i] = rand() % 1000 + 1;
        record_arr[i].value = rand() % 10000 + 1;
    }

    // Read a series of integers from standard input and store them in a separate array
    int *input_arr = malloc(sizeof(int) * MAX_INPUT_SIZE);
    if (input_arr == NULL) {
        printf("Error: Failed to allocate memory for input array.\n");
        return;
    }

    // Read the input and store it in the separate array
    int i = 0;
    while (i < MAX_INPUT_SIZE && scanf("%d", &input_arr[i]) == 1) {
        i++;
    }

    // Identify the largest integer among all inputs
    int largest_input = -1;
    for (int j = 0; j < i; j++) {
        if (largest_input < input_arr[j]) {
            largest_input = input_arr[j];
        }
    }

    // Print the largest integer
