    while (fgets(line, sizeof(line), config_file)) {
        // Trim newline character and validate string
        char* str = trim_newline(line);
        if (!is_valid_string(str)) {
            fprintf(stderr, "Invalid string: %s\n", str);
            continue;
        }

        // Generate random UUID for each string and append as suffix
        char uuid[MAX_UUID_LENGTH];
        if (uuid_generate(uuid) != 0) {
            fprintf(stderr, "Failed to generate UUID\n");
            continue;
        }

        // Allocate memory for string and copy with UUID suffix
        char* new_str = malloc(sizeof(char) * (strlen(str) + strlen(uuid) + 1));
        if (!new_str) {
            fprintf(stderr, "Memory allocation failed\n");
            continue;
        }
        sprintf(new_str, "%s%s", str, uuid);

        // Add string to list and check for memory limit
        if (list->num_strings == MAX_STRINGS) {
            fprintf(stderr, "Maximum number of strings exceeded\n");
            free(new_str);
            continue;
        }
        list->strings[list->num_strings++] = new_str;

        // Check for memory limit and handle under-allocation
        if (MEMORY_LIMIT - malloc_size() < sizeof(char) * strlen(new_str)) {
            fprintf(stderr, "Memory limit exceeded\n");
            destroy_string_list(list);
            exit(1);
        }
    }
}

void print_longest_string(StringList* list) {
    // Find longest string in list and print it
    size_t longest = 0;
    for (size_t i = 0; i < list->num_strings; ++i) {
        if (strlen(list->strings[i]) > longest) {
            longest = strlen(list->strings[i]);
        }
    }
    printf("%s\n", list->strings[longest]);
}

void free_memory(StringList* list) {
    for (size_t i = 0; i < list->num_strings; ++i) {
        free(list->strings[i]);
    }
    free(list);
}
