// Custom memory management system using pooling mechanism
struct MemoryPool {
    void *memory;
    size_t size;
};

struct MemoryPoolNode {
    struct MemoryPoolNode *next;
    struct MemoryPool *pool;
};

void initMemoryPool(struct MemoryPoolNode **head) {
    // Initialize the head node and set it to NULL
    *head = NULL;
}

void addToMemoryPool(struct MemoryPoolNode **head, void *memory, size_t size) {
    struct MemoryPoolNode *newNode = malloc(sizeof(struct MemoryPoolNode));
    newNode->pool = (struct MemoryPool *)malloc(sizeof(struct MemoryPool));
    newNode->pool->memory = memory;
    newNode->pool->size = size;
    newNode->next = *head;
    *head = newNode;
}

void* allocateFromMemoryPool(struct MemoryPoolNode **head, size_t size) {
    struct MemoryPoolNode *currNode = *head;
    while (currNode != NULL && currNode->pool->size < size) {
        currNode = currNode->next;
    }
    if (currNode == NULL) {
        return NULL;
    } else {
        void *memory = currNode->pool->memory;
        currNode->pool->memory += size;
        currNode->pool->size -= size;
        return memory;
    }
}

