    // Constructor to initialize with capacity
    explicit dynamic_array(size_t capacity) : data(capacity) {}

    // Adds an element to the end of the dynamic array
    void push_back(const T& element) {
        data.push_back(element);
    }

    // Removes the last element from the dynamic array
    void pop_back() {
        data.pop_back();
    }

    // Returns a reference to the element at a given position in the dynamic array
    T& operator[](size_t index) {
        return data[index];
    }

    // Returns a reference to the element at a given position in the dynamic array (same as `operator[]`)
    const T& at(size_t index) const {
        return data[index];
    }
};
```
This implementation uses a `std::vector` instead of raw memory to store the elements. The `push_back()` function adds an element to the end of the dynamic array, while the `pop_back()` function removes the last element from the dynamic array. The `at()` and `operator[]` functions return references to elements in the dynamic array at a given position.

