#define MAX_MAC_FRAMES 1024 // maximum number of MAC frames that can be stored in the array

// structure to represent a single MAC frame
typedef struct {
    uint8_t macHeader[];
    uint8_t macPayload[];
    time_t timestamp;
} MAC_RX_FRAME;

static MAC_RX_FRAME *macFrames = NULL; // array of dynamically allocated MAC frames
static size_t numMacFrames = 0; // number of MAC frames stored in the array
static size_t maxMacFrames = MAX_MAC_FRAMES; // maximum capacity of the array

void initializeAndConfigureMacFrames(void) {
    if (macFrames == NULL) {
        macFrames = calloc(maxMacFrames, sizeof(*macFrames));
        if (macFrames == NULL) {
            fprintf(stderr, "Failed to allocate memory for MAC frames\n");
            return;
        }
    }
}

void handleNewMacFrame(const uint8_t *macHeader, const uint8_t *macPayload, time_t timestamp) {
    if (numMacFrames == maxMacFrames) { // check if array is full
        MAC_RX_FRAME *newMacFrames = realloc(macFrames, 2 * maxMacFrames * sizeof(*macFrames));
        if (newMacFrames == NULL) {
            fprintf(stderr, "Failed to allocate memory for new MAC frames\n");
            return;
        }
        macFrames = newMacFrames;
        maxMacFrames *= 2; // double the capacity of the array
    }
    MAC_RX_FRAME *newFrame = &macFrames[numMacFrames];
    memcpy(newFrame->macHeader, macHeader, sizeof(*macHeader));
    memcpy(newFrame->macPayload, macPayload, sizeof(*macPayload));
    newFrame->timestamp = timestamp;
    numMacFrames++; // increment the number of MAC frames stored in the array
}

void filterMacFramesByAddress(const uint8_t *macAddress) {
    size_t i = 0;
    while (i < numMacFrames) {
        if (memcmp(macFrames[i].macHeader, macAddress, sizeof(*macAddress)) == 0) { // check if the current MAC frame matches the given address
            // do something with the filtered MAC frame, e.g., send it to an external network management system (NMS) for logging and monitoring purposes
            i++;
        } else {
            memmove(&macFrames[i], &macFrames[i + 1], sizeof(*macFrames) * (numMacFrames - i)); // move the current MAC frame to the front of the array
            numMacFrames--;
        }
    }
}

void freeMacFrames(void) {
    if (macFrames != NULL) {
        free(macFrames);
        macFrames = NULL;
        maxMacFrames = 0;
        numMacFrames = 0;
    }
}
```
