        crc_indication_pdu[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Generate a random CRCFLAG value
    }

    // Search and print the largest integer in the array using a third-party library
    int* sorted_array = (int*)malloc(total_num_integers * sizeof(int));
    if (!sorted_array) {
        // If the memory allocation fails, print an error message and exit.
        printf("Error: Unable to allocate memory for the sorted array.\n");
        return;
    }
    memcpy(sorted_array, integer_array, total_num_integers * sizeof(int));
    qsort(sorted_array, total_num_integers, sizeof(int), compare); // Sort the array using the compare function
    largest_integer = sorted_array[total_num_integers - 1];
    printf("The largest integer in the array is %d.\n", largest_integer);

    // Clean up memory
    free(sorted_array);
    free(crc_indication_pdu);
    free(integer_array);
