        pdu->RX_UE_INFORMATION_TAG = 1; // valid RX UE information tag
        pdu->RNTI = rand() % 65536; // random RNTI value
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = 0; // set CRCFLAG to 0
        num_pdus++;
