    // Free the memory allocated for the list of CRC indication PDUs if DNS resolution fails
    if (getaddrinfo(hostname, port, &hints, &addr) != 0) {
        free(*pdus);
        perror("getaddrinfo failed");
        return -1;
    }

    // Integrate the function into an existing network stack by using a socket
    struct sockaddr_in server_addr = {
        .sin_family = AF_INET,
        .sin_port = htons(port),
    };
    memcpy(&server_addr.sin_addr, addr->ai_addr, sizeof(server_addr.sin_addr));
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket failed");
        return -1;
    }
    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect failed");
        close(sock);
        return -1;
    }
    send(sock, *pdus, limit * sizeof(**pdus), MSG_NOSIGNAL); // send the list of CRC indication PDUs to the network stack
    close(sock);

    freeaddrinfo(addr); // free memory allocated for DNS resolution

    return 0;
}
