std::vector<Record*> allocateDataStructures(int numRecords, size_t maxMemoryPerInstance) {
  // Determine the size of each data structure based on user input and memory constraints.
  size_t recordSize = sizeof(Record);
  size_t totalMemoryRequired = numRecords * recordSize;
  if (totalMemoryRequired > maxMemoryPerInstance) {
    // Handle potential memory allocation failure gracefully by providing feedback to the user about the failure reason.
    std::cout << "Insufficient memory available to allocate " << numRecords << " records with a maximum of " << maxMemoryPerInstance << " bytes per instance.";
    return {};
  }

  // Allocate an array of record structures, where each record contains a single integer value.
  std::vector<Record*> records(numRecords);
  for (int i = 0; i < numRecords; ++i) {
    records[i] = new Record{i, static_cast<long>(i)};
  }

  // Return the allocated memory to the user.
  return records;
}

void freeDataStructures(std::vector<Record*> records) {
  // Free the allocated memory for each data structure.
  for (int i = 0; i < records.size(); ++i) {
    delete records[i];
  }
}

int main() {
  // User input: number of records and maximum memory per instance.
  int numRecords = 1000000;
  size_t maxMemoryPerInstance = 2 * 1024 * 1024;

  // Allocate the data structures and initialize them with unique random values.
