    public void addToCache(String source, long offset) {
        synchronized (cache) {
            if (cache.size() >= MAX_CACHE_SIZE) {
                // evict the least recently used item from the cache
                Long lruOffset = getLRUOffset();
                removeFromCache(lruOffset);
            }
            cache.put(offset, source);
            offsetMap.put(source, offset);
        }
    }

    public String getFromCache(long offset) {
        synchronized (cache) {
            return cache.get(offset);
        }
    }

    private void removeFromCache(long offset) {
        synchronized (cache) {
            if (cache.containsKey(offset)) {
                cache.remove(offset);
            }
            if (offsetMap.containsValue(offset)) {
                String source = getSourceForOffset(offset);
                if (source != null) {
                    offsetMap.remove(source);
                }
            }
        }
    }

    private Long getLRUOffset() {
        long minOffset = Long.MAX_VALUE;
        Long lruOffset = null;
        synchronized (cache) {
            for (Long offset : cache.keySet()) {
                if (offset < minOffset) {
                    minOffset = offset;
                    lruOffset = offset;
                }
            }
        }
        return lruOffset;
    }

    private String getSourceForOffset(long offset) {
        synchronized (cache) {
            for (String source : offsetMap.keySet()) {
