#define RECORD_SIZE 1000
#define MAX_RECORD_COUNT 750000

// Define structs for offsets, keys, and records
typedef struct {
    size_t offset;
} Offset;

typedef struct {
    char key[MAX_KEY_SIZE];
} Key;

typedef struct {
    size_t record_id;
    int value;
