    char* keys = (char*)malloc(sizeof(Key) * MEM_POOL_SIZE);
    if (!keys) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Allocate memory for records
    Record* records = (Record*)malloc(sizeof(Record) * MEM_POOL_SIZE);
