    node = yaml_document_get_root_node(&document);
    if (!node) {
        fprintf(stderr, "Failed to get root node\n");
        ret = -1;
        goto cleanup;
    }

    // Check that the root node is a mapping
    if (node->type != YAML_MAPPING_NODE) {
        fprintf(stderr, "Root node is not a mapping\n");
        ret = -1;
        goto cleanup;
    }

    // Get the configuration mapping
    config = (yaml_mapping_t *)node->data;
    if (!config) {
        fprintf(stderr, "Failed to get configuration mapping\n");
        ret = -1;
        goto cleanup;
    }

    // Check that the required parameters are present in the mapping
    int num_params = yaml_mapping_get_num_pairs(config);
    for (int i = 0; i < num_params; i++) {
        yaml_node_t *key, *value;
        key = yaml_mapping_get_pair(config, i)->key;
        value = yaml_mapping_get_pair(config, i)->value;
        if (!strcmp(yaml_node_get_tag(key), "tag:yaml.org,2002:str")) {
            const char *param = (const char *)yaml_node_get_scalar(value);
            if (strcmp(param, REQUIRED_PARAMS)) {
                fprintf(stderr, "Required parameter '%s' is missing\n", param);
                ret = -1;
                goto cleanup;
            }
        } else if (!strcmp(yaml_node_get_tag(key), "tag:yaml.org,2002:seq")) {
            size_t num_bindings = yaml_sequence_get_num_nodes(value);
            for (size_t j = 0; j < num_bindings; j++) {
                yaml_node_t *binding = yaml_sequence_get_node(value, j);
                if (!strcmp(yaml_node_get_tag(binding), "tag:yaml.org,2002:int")) {
                    uint64_t port = (uint64_t)yaml_node_get_scalar(binding);
                    if (port < 1024 || port > MAX_PORTS) {
                        fprintf(stderr, "Invalid port number %lu\n", port);
                        ret = -1;
                        goto cleanup;
                    }
                } else {
                    fprintf(stderr, "Invalid binding format for '%s'\n", param);
                    ret = -1;
                    goto cleanup;
                }
            }
        } else if (!strcmp(yaml_node_get_tag(key), "tag:yaml.org,2002:int")) {
            uint64_t port = (uint64_t)yaml_node_get_scalar(value);
            if (port < 1024 || port > MAX_PORTS) {
                fprintf(stderr, "Invalid port number %lu\n", port);
                ret = -1;
                goto cleanup;
            }
        } else if (!strcmp(yaml_node_get_tag(key), "tag:yaml.org,2002:map")) {
            size_t num_bindings = yaml_mapping_get_num_pairs(value);
            for (size_t j = 0; j < num_bindings; j++) {
                yaml_node_t *key, *value;
                key = yaml_mapping_get_pair(value, j)->key;
                value = yaml_mapping_get_pair(value, j)->value;
                if (!strcmp(yaml_node_get_tag(key), "tag:yaml.org,2002:str") &&
                    !strcmp(yaml_node_get_tag(value), "tag:yaml.org,2002:int")) {
                    const char *binding = (const char *)yaml_node_get_scalar(key);
                    uint64_t port = (uint64_t)yaml_node_get_scalar(value);
                    if (!strcmp(binding, "port") && (port < 1024 || port > MAX_PORTS)) {
                        fprintf(stderr, "Invalid port number %lu\n", port);
                        ret = -1;
                        goto cleanup;
                    } else if (!strcmp(binding, "bind") && (port < 0 || port > MAX_PORTS)) {
                        fprintf(stderr, "Invalid binding number %lu\n", port);
                        ret = -1;
                        goto cleanup;
                    }
                } else {
                    fprintf(stderr, "Invalid binding format for '%s'\n", param);
                    ret = -1;
                    goto cleanup;
                }
            }
        }
    }

cleanup:
    // Clean up the YAML parser and document
    yaml_parser_delete(&parser);
    yaml_document_delete(&document);
    fclose(fp);

    return ret;
}

int main() {
