void processTransactionRequest(int sessionId, int userId, char* jsonPayload) {
  // Validate the JSON payload against a set of predefined rules
  // Ensure the sender has sufficient funds and adhere to daily and monthly transaction limits
  if (validateJsonPayload(jsonPayload)) {
    // Handle potential network latency and timeouts during communication with the external payment gateway
    bool isTransactionSuccessful = makePaymentGatewayRequest(sessionId, userId, jsonPayload);

    // Ensure reliable message delivery via WebSocket for real-time notifications
    if (isTransactionSuccessful) {
      // Manage transaction retries in case of transient errors
      bool isTransactionRetryRequired = false;
      while (!isTransactionRetryRequired) {
        isTransactionSuccessful = makePaymentGatewayRequest(sessionId, userId, jsonPayload);
        if (isTransactionSuccessful) {
          break;
        } else {
          // Handle transient errors and retry if necessary
          isTransactionRetryRequired = handleTransientError();
        }
      }

      // Update the distributed ledger system with the successful transaction
      updateDistributedLedger(sessionId, userId, jsonPayload);
    } else {
      // Log error messages and debugging information for failed transactions
