static size_t system_process_pool_used = 0;

// Memory pool for storing TX_POWER_REPORT_INDICATION structures
static TX_POWER_REPORT_INDICATION *tx_power_report_indication_pool = NULL;
static size_t tx_power_report_indication_pool_size = 0;
static size_t tx_power_report_indication_pool_used = 0;

// Hash map for detecting duplicate PROCESS_IDs
