// Array of int values for storing keys
static int *key_array = NULL;

// Function to allocate memory for SYSTEM_PROCESS_INFO structures
SYSTEM_PROCESS_INFO *allocate_system_process(int process_id, int status) {
    // Allocate memory from the pool if available
    if (system_process_pool_used < system_process_pool_size) {
        SYSTEM_PROCESS_INFO *new_process = &system_process_pool[system_process_pool_used++];
        new_process->process_id = process_id;
        new_process->status = status;
        return new_process;
    } else {
        // If pool is full, allocate memory directly from the heap
        SYSTEM_PROCESS_INFO *new_process = (SYSTEM_PROCESS_INFO *)malloc(sizeof(SYSTEM_PROCESS_INFO));
        if (new_process == NULL) {
            return NULL;
        } else {
            new_process->process_id = process_id;
            new_process->status = status;
            return new_process;
        }
    }
}

// Function to deallocate memory for SYSTEM_PROCESS_INFO structures
void deallocate_system_process(SYSTEM_PROCESS_INFO *process) {
    if (process == NULL) {
        return;
    }

    // Deallocate from the pool if possible
    if (system_process_pool_used > 0) {
        system_process_pool[--system_process_pool_used] = NULL;
    } else {
        // If pool is empty, deallocate directly from the heap
        free(process);
    }
}

