// Function to add a new record to the collections
void add_record(int process_id, int rnti, long offset) {
    pthread_mutex_lock(&process_id_map_lock);

    if (process_id_map == NULL || process_id_map[process_id] == 0) {
        // If the map is not initialized or the process ID does not exist, add a new entry
        size_t new_size = process_id_map == NULL ? 1 : process_id_map->size * 2;
        size_t *new_map = (size_t *)malloc(sizeof(size_t) * new_size);
        if (new_map == NULL) {
            pthread_mutex_unlock(&process_id_map_lock);
            return;
        }
        memset(new_map, 0, sizeof(size_t) * new_size);
        if (process_id_map != NULL) {
            memcpy(new_map, process_id_map, sizeof(size_t) * process_id_map->size);
            free(process_id_map);
