    // Check if there are any available structures in the memPool
    int availStructures = memPoolSize - (sizeof(memPool) / sizeof(SYSTEM_PROCESS_INFO));
    if (availStructures < numStructures) {
        // Reallocate the memPool to fit more structures
        memPool = realloc(memPool, POOL_SIZE * 2 * sizeof(SYSTEM_PROCESS_INFO));
        memset(memPool + availStructures, 0, (POOL_SIZE - availStructures) * sizeof(SYSTEM_PROCESS_INFO));
        memPoolSize = POOL_SIZE * 2;
    }

    // Allocate new structures and populate them with unique PROCESS_IDs and random statuses
    int i = 0;
    while (i < numStructures) {
        SYSTEM_PROCESS_INFO* structure = &memPool[i];
        structure->PROCESS_ID = i + 1; // Initialize the PROCESS_ID to be unique
        structure->status = rand() % 2; // Initialize the status randomly
        i++;
    }
}

// Add a new session to the cache, allocating memory if necessary
void addSession(int sessionID) {
    // Check if there are any available slots in the sessionCache
    int availSlots = sessionCacheSize - (sizeof(sessionCache) / sizeof(UserSessionState));
    if (availSlots == 0) {
        // Reallocate the sessionCache to fit more sessions
        sessionCache = realloc(sessionCache, POOL_SIZE * 2 * sizeof(UserSessionState));
        memset(sessionCache + availSlots, 0, (POOL_SIZE - availSlots) * sizeof(UserSessionState));
        sessionCacheSize = POOL_SIZE * 2;
    }

    // Allocate a new session in the cache
    UserSessionState* newSession = &sessionCache[availSlots];
    memset(newSession, 0, sizeof(UserSessionState));
    newSession->sessionID = sessionID;
}

// Remove a session from the cache, deallocating its memory if necessary
void removeSession(int sessionID) {
    // Find the index of the specified session in the cache
    int i = 0;
    while (i < sessionCacheSize && sessionCache[i].sessionID != sessionID) {
        i++;
    }

    if (i == sessionCacheSize) {
        // The specified session was not found in the cache, return
        return;
    }

    // Deallocate the memory of the removed session
    UserSessionState* removedSession = &sessionCache[i];
    memset(removedSession, 0, sizeof(UserSessionState));

    // Shift all subsequent sessions in the cache to fill the gap
    int j = i + 1;
    while (j < sessionCacheSize) {
        UserSessionState* shiftedSession = &sessionCache[j];
        memmove(shiftedSession, shiftedSession + 1, sizeof(UserSessionState));
        j++;
    }

    // Decrement the cache size
    sessionCacheSize--;
}

