uint32_t generate_session_id() {
    // Use a lock to prevent concurrent access to shared resources
    pthread_mutex_lock(&session_id_lock);

    uint32_t session_id = 1;
    while (session_id <= MAX_SESSION_ID) {
        if (!is_session_id_used(session_id)) {
            break;
        }
        session_id++;
