    pthread_mutex_lock(&session_id_lock);

    bool used = false;
    for (int i = 0; i < num_connections; i++) {
        if (connection_records[i].session_id == session_id) {
            used = true;
            break;
        }
    }

    pthread_mutex_unlock(&session_id_lock);
    return used;
}

// Create a function to set a `SESSION_ID` as used
void set_session_id_used(uint32_t session_id) {
    // Use a lock to prevent concurrent access to shared resources
    pthread_mutex_lock(&session_id_lock);

    for (int i = 0; i < num_connections; i++) {
        if (connection_records[i].session_id == session_id) {
