        }
    }

    pthread_mutex_unlock(&session_id_lock);
}

// Create a function to allocate memory for up to N records
USER_CONNECTION_RECORD_T* allocate_memory(int n) {
    // Use a lock to prevent concurrent access to shared resources
    pthread_mutex_lock(&connection_records_lock);

    USER_CONNECTION_RECORD_T* records = malloc(sizeof(USER_CONNECTION_RECORD_T) * n);
    if (records == NULL) {
        // Handle memory allocation failure
    }

    num_connections += n;
    pthread_mutex_unlock(&connection_records_lock);
    return records;
}

// Create a function to populate each record with a unique `SESSION_ID` and timestamp
void populate_records(int n) {
    // Use a lock to prevent concurrent access to shared resources
    pthread_mutex_lock(&connection_records_lock);

    for (int i = 0; i < num_connections; i++) {
        USER_CONNECTION_RECORD_T* record = &connection_records[i];
        record->session_id = generate_session_id();
        record->last_activity_timestamp = time(NULL);
    }

    pthread_mutex_unlock(&connection_records_lock);
}

// Create a function to deallocate memory for up to N records
