#define MAX_CUSTOMER_IDS 1000000
#define MIN_ALLOCATION_SIZE (sizeof(CUSTOMER_PROFILE_T) * MAX_CUSTOMER_IDS)
#define ALLOCATION_GRANULARITY (16 * 1024) // 16KB
#define LOGGING_LEVEL_ERROR 0
#define LOGGING_LEVEL_WARNING 1
#define LOGGING_LEVEL_INFO 2
#define LOGGING_LEVEL_DEBUG 3

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static CUSTOMER_PROFILE_T* customer_profiles = NULL;
static unsigned long num_customer_ids = 0;
static unsigned long max_num_customer_ids = MAX_CUSTOMER_IDS;
static FILE* logfile = NULL;
static int logging_level = LOGGING_LEVEL_ERROR;

void init_logging(int level) {
    if (level >= LOGGING_LEVEL_DEBUG) {
        logfile = fopen("memory_allocation.log", "a");
        logging_level = level;
    } else {
        logfile = NULL;
        logging_level = 0;
    }
}

void log(int level, const char* message) {
    if (logging_level >= level && logfile != NULL) {
        fprintf(logfile, "%s", message);
        fflush(logfile);
    }
}

long allocate_customer_id() {
    long id = -1;
    pthread_mutex_lock(&mutex);
    if (num_customer_ids < max_num_customer_ids) {
        customer_profiles[num_customer_ids].customer_id = num_customer_ids + 1;
        id = num_customer_ids++;
    } else {
        log(LOGGING_LEVEL_WARNING, "Maximum number of customer IDs reached. Could not allocate new ID.\n");
    }
    pthread_mutex_unlock(&mutex);
    return id;
}

CUSTOMER_PROFILE_T* get_customer_profile(long customer_id) {
    CUSTOMER_PROFILE_T* profile = NULL;
    pthread_mutex_lock(&mutex);
    if (customer_id >= 1 && customer_id <= num_customer_ids) {
        profile = &customer_profiles[customer_id - 1];
    } else {
        log(LOGGING_LEVEL_WARNING, "Invalid customer ID. Could not retrieve customer profile.\n");
    }
    pthread_mutex_unlock(&mutex);
    return profile;
}

void deallocate_customer_id(long customer_id) {
    pthread_mutex_lock(&mutex);
    if (customer_id >= 1 && customer_id <= num_customer_ids) {
        num_customer_ids--;
        // Move the last element to the freed position and update the ID.
        memcpy(&customer_profiles[customer_id - 1], &customer_profiles[num_customer_ids], sizeof(CUSTOMER_PROFILE_T));
        customer_profiles[num_customer_ids].customer_id = num_customer_ids + 1;
    } else {
        log(LOGGING_LEVEL_WARNING, "Invalid customer ID. Could not deallocate.\n");
    }
    pthread_mutex_unlock(&mutex);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfapi_crc_indication(int size) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = NULL;
    if (size > 0) {
        pthread_mutex_lock(&mutex);
        if ((num_customer_ids + size) <= max_num_customer_ids) {
            // Allocate memory for the PDU and set its fields.
            pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memset(pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pdu->rx_ue_information_tag = 1;
            pdu->rnti = num_customer_ids + size + 1;
            pdu->crc_indication_rel8_tag = 2;
            // Set a random value for the CRCFLAG.
            pdu->crcflag = rand() % 3;
            // Increment the number of customer IDs by the size of the allocation.
            num_customer_ids += size;
        } else {
            log(LOGGING_LEVEL_WARNING, "Could not allocate memory for NFAPI CRC Indication.\n");
        }
        pthread_mutex_unlock(&mutex);
    }
    return pdu;
}

void deallocate_nfapi_crc_indication(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu != NULL) {
        // Decrement the number of customer IDs by the size of the allocation.
        num_customer_ids -= pdu->rx_ue_information_tag;
        free(pdu);
    } else {
        log(LOGGING_LEVEL_WARNING, "Invalid NFAPI CRC Indication PDU. Could not deallocate memory.\n");
    }
}

int main() {
    init_logging(LOGGING_LEVEL_DEBUG);
    allocate_customer_id();
    get_customer_profile(1);
    deallocate_customer_id(1);
    NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_nfapi_crc_indication(3);
    deallocate_nfapi_crc_indication(pdu);
    return 0;
}
```

The `allocate_customer_id` function uses the `malloc` function to allocate memory for a new customer ID. It locks the mutex before accessing the shared data, and then checks if there is still enough space in the array to add a new element. If there is not enough space, it logs a warning message and returns `-1`. Otherwise, it assigns the next available ID to the new customer profile and increments the number of customer IDs.

The `get_customer_profile` function also uses the mutex to ensure thread safety. It checks if the requested customer ID is valid, and then returns a pointer to the corresponding customer profile structure. If the customer ID is invalid, it logs a warning message and returns `NULL`.

The `deallocate_customer_id` function also uses the mutex to ensure thread safety. It decrements the number of customer IDs by one, and then moves the last element in the array to the freed position. This updates all the subsequent customer IDs. If the requested customer ID is invalid, it logs a warning message and does not modify the shared data.

The `allocate_nfapi_crc_indication` function also uses the mutex to ensure thread safety. It checks if there is enough space in the array for the new allocation, and then allocates memory using the `malloc` function. If there is not enough space, it logs a warning message and returns `NULL`. Otherwise, it sets the fields of the allocated PDU structure and increments the number of customer IDs by the size of the allocation.

The `deallocate_nfapi_crc_indication` function also uses the mutex to ensure thread safety. It decrements the number of customer IDs by the size of the allocation, and then frees the allocated memory using the `free` function. If the requested PDU is `NULL`, it logs a warning message and does not modify the shared data.

The `main` function initializes logging at the debug level and demonstrates how to use these functions. It allocates a customer ID, retrieves the corresponding profile, deallocates the customer ID, and then allocates and frees an NFAPI CRC Indication PDU.']

