// Define a custom message structure to hold timestamp, priority, and payload
typedef struct {
  uint64_t timestamp;
  int priority;
  char* payload;
} message_t;

// Define the queue structure with a lock-free data structure for messages
struct dynamic_queue {
  pthread_mutex_t mutex;
  pthread_cond_t cond;
  int head, tail, count;
  message_t* buffer[50000];
};

// Initialize the queue with a given size (in this case 50000)
void init(struct dynamic_queue* q) {
  pthread_mutex_init(&q->mutex, NULL);
  pthread_cond_init(&q->cond, NULL);
  q->head = 0;
  q->tail = 0;
  q->count = 0;
}

// Push a message onto the queue
void push(struct dynamic_queue* q, message_t* msg) {
  pthread_mutex_lock(&q->mutex);
  while (q->count == 50000) {
    pthread_cond_wait(&q->cond, &q->mutex);
  }
  q->buffer[q->tail++] = msg;
  q->count++;
  pthread_mutex_unlock(&q->mutex);
}

// Pop a message from the queue
message_t* pop(struct dynamic_queue* q) {
  pthread_mutex_lock(&q->mutex);
  while (q->count == 0) {
    pthread_cond_wait(&q->cond, &q->mutex);
  }
  message_t* msg = q->buffer[q->head++];
  q->count--;
  pthread_mutex_unlock(&q->mutex);
  return msg;
}

// Periodically purge expired messages based on their timestamps
void purge(struct dynamic_queue* q) {
  uint64_t current_time = get_current_time();
  for (int i = q->head; i < q->tail; i++) {
    message_t* msg = q->buffer[i];
    if (msg->timestamp < current_time) {
      // Message has expired, remove it from the queue
      q->count--;
      memmove(q->buffer + i, q->buffer + i + 1, sizeof(message_t*) * (q->tail - i));
    }
  }
