// Function to allocate memory from the memory pool
void* allocate_memory(size_t size) {
    if (mempool.allocated + size > MEMORY_POOL_SIZE) {
        // If the allocation would exceed the size of the memory pool, return NULL
        return NULL;
    } else {
        // Otherwise, allocate the memory from the pool and update the allocated field
        void* ptr = mempool.block + mempool.allocated;
        mempool.allocated += size;
        return ptr;
    }
}

