    // Allocate memory for the timestamp array
    long* timestamps = (long*)malloc(numFiles * sizeof(long));
    if (!timestamps) {
        printf("Error: unable to allocate memory for timestamp array\n");
        return;
    }

    // Initialize the timestamp array with zeros
    memset(timestamps, 0, numFiles * sizeof(long));

    // Allocate memory for the sensor reading array
    double* readings = (double*)malloc(numFiles * sizeof(double));
    if (!readings) {
        printf("Error: unable to allocate memory for sensor reading array\n");
        return;
    }

    // Initialize the sensor reading array with zeros
    memset(readings, 0, numFiles * sizeof(double));

    // Allocate memory for the status flag array
    int* statusFlags = (int*)malloc(numFiles * sizeof(int));
    if (!statusFlags) {
        printf("Error: unable to allocate memory for status flag array\n");
        return;
    }

    // Initialize the status flag array with zeros
    memset(statusFlags, 0, numFiles * sizeof(int));

    // Allocate memory for the sensorData array
    sensorData* data = (sensorData*)malloc(numFiles * sizeof(sensorData));
    if (!data) {
        printf("Error: unable to allocate memory for sensorData array\n");
        return;
    }

    // Initialize the sensorData array with zeros
    memset(data, 0, numFiles * sizeof(sensorData));

    // Loop through each file and read in the data
    for (int i = 0; i < numFiles; i++) {
        FILE* fp = fopen(fileNames[i], "r");
        if (!fp) {
            printf("Error: unable to open file %s\n", fileNames[i]);
            continue;
        }

        // Read in the timestamp from the first line of the file
        char* line = NULL;
        size_t len = 0;
        ssize_t read;
        long timestamp = 0;
        while ((read = getline(&line, &len, fp)) != -1) {
            if (sscanf(line, "%ld", &timestamp) == 1) {
                break;
            }
        }
        free(line);

        // Read in the sensor reading and status flag from the second line of the file
        double reading = 0.0;
        int statusFlag = 0;
        while ((read = getline(&line, &len, fp)) != -1) {
            if (sscanf(line, "%lf %d", &reading, &statusFlag) == 2) {
                break;
            }
        }
        free(line);

        // Add the data to the corresponding arrays
        timestamps[i] = timestamp;
        readings[i] = reading;
        statusFlags[i] = statusFlag;

        // Close the file
        fclose(fp);
    }

    // Print the contents of the sensorData array in a human-readable format
    for (int i = 0; i < numFiles; i++) {
        printf("Timestamp: %ld\n", timestamps[i]);
        printf("Sensor Reading: %lf\n", readings[i]);
        printf("Status Flag: %d\n", statusFlags[i]);
    }
}
