```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <pthread.h>

#define MAX_RESOURCES 1000
#define RESOURCE_SIZE sizeof(resource)
#define TIMESTAMP_RANGE 1000000 // 1 million timestamps
#define FLOATING_POINT_RANGE 10.0f // 10.0 floating-point values
#define VALIDITY_FLAG 1

typedef struct {
    long timestamp;
    float value;
    int validity;
} resource;

typedef struct {
    resource* resources[MAX_RESOURCES];
    pthread_mutex_t mutex; // synchronization mechanism for accessing the resources array
} resource_manager;

resource_manager manager = { NULL };

void init_manager() {
    manager.resources = malloc(sizeof(resource*) * MAX_RESOURCES);
    memset(manager.resources, 0, sizeof(resource*) * MAX_RESOURCES);
}

void free_manager() {
    for (int i = 0; i < MAX_RESOURCES; i++) {
        if (manager.resources[i]) {
            free(manager.resources[i]);
        }
    }
    free(manager.resources);
}

void add_resource(resource* resource) {
    pthread_mutex_lock(&manager.mutex);
    int index = 0;
    for (int i = 0; i < MAX_RESOURCES; i++) {
        if (!manager.resources[i]) {
            index = i;
            break;
        }
    }
    manager.resources[index] = resource;
    pthread_mutex_unlock(&manager.mutex);
}

void remove_resource(int index) {
    pthread_mutex_lock(&manager.mutex);
    free(manager.resources[index]);
    manager.resources[index] = NULL;
    pthread_mutex_unlock(&manager.mutex);
}

void update_resource(int index, resource* resource) {
    pthread_mutex_lock(&manager.mutex);
    if (manager.resources[index]) {
        free(manager.resources[index]);
        manager.resources[index] = NULL;
    }
    manager.resources[index] = resource;
    pthread_mutex_unlock(&manager.mutex);
}

void* get_resource(int index) {
    pthread_mutex_lock(&manager.mutex);
    resource* resource = NULL;
    if (manager.resources[index]) {
        resource = manager.resources[index];
    }
    pthread_mutex_unlock(&manager.mutex);
    return resource;
}

void handle_request(request* request) {
    // Handle the request from the client
    switch (request->type) {
        case ADD:
            add_resource(request->resource);
            break;
        case REMOVE:
            remove_resource(request->index);
            break;
        case UPDATE:
            update_resource(request->index, request->resource);
            break;
        case GET:
            get_resource(request->index);
            break;
    }
}
```
