Here is an example implementation of a C function to manage a dynamic task scheduling environment:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Task record structure
typedef struct {
    int task_id;
    time_t start_time;
    int estimated_duration;
    float current_progress;
} TASK_RECORD_T;

// Priority queue structure
typedef struct {
    TASK_RECORD_T* tasks;
    size_t num_tasks;
    size_t max_tasks;
} PRIORITY_QUEUE_T;

// Function to allocate and initialize a new task record
TASK_RECORD_T* alloc_task_record(int task_id, time_t start_time, int estimated_duration) {
    TASK_RECORD_T* record = (TASK_RECORD_T*) malloc(sizeof(TASK_RECORD_T));
    if (!record) {
        printf("Error: could not allocate task record.\n");
        return NULL;
    }
    record->task_id = task_id;
    record->start_time = start_time;
    record->estimated_duration = estimated_duration;
    record->current_progress = 0.0f;
    return record;
}

// Function to free a task record and remove it from the priority queue
void free_task_record(TASK_RECORD_T* record) {
    if (!record) {
        printf("Error: could not free task record.\n");
        return;
    }
    free(record);
}

// Function to add a new task to the priority queue
void add_task(PRIORITY_QUEUE_T* queue, TASK_RECORD_T* record) {
    if (!queue || !record) {
        printf("Error: could not add task to queue.\n");
        return;
    }
    // If the queue is full, resize it by doubling its capacity
    if (queue->num_tasks == queue->max_tasks) {
        queue->max_tasks *= 2;
        queue->tasks = (TASK_RECORD_T*) realloc(queue->tasks, sizeof(TASK_RECORD_T) * queue->max_tasks);
    }
    // Insert the new task at the end of the queue
    queue->tasks[queue->num_tasks] = record;
    queue->num_tasks++;
}

// Function to remove a task from the priority queue
void remove_task(PRIORITY_QUEUE_T* queue, int task_id) {
    if (!queue) {
        printf("Error: could not remove task from queue.\n");
        return;
    }
    // Find the index of the task to be removed
    size_t index = 0;
    while (index < queue->num_tasks && queue->tasks[index]->task_id != task_id) {
        index++;
    }
    // If the task was found, remove it by shifting all tasks after it back one index
    if (index < queue->num_tasks) {
        for (size_t i = index; i < queue->num_tasks - 1; i++) {
            queue->tasks[i] = queue->tasks[i + 1];
        }
        queue->num_tasks--;
    } else {
        printf("Error: task not found in queue.\n");
    }
}

// Function to update the progress of a task in the priority queue
void update_task(PRIORITY_QUEUE_T* queue, int task_id, float current_progress) {
    if (!queue) {
        printf("Error: could not update task.\n");
        return;
    }
    // Find the index of the task to be updated
    size_t index = 0;
    while (index < queue->num_tasks && queue->tasks[index]->task_id != task_id) {
        index++;
    }
    // If the task was found, update its progress and return it
    if (index < queue->num_tasks) {
        queue->tasks[index]->current_progress = current_progress;
        return;
    } else {
        printf("Error: task not found in queue.\n");
    }
}

// Function to get the next task from the priority queue
TASK_RECORD_T* get_next_task(PRIORITY_QUEUE_T* queue) {
    if (!queue) {
        printf("Error: could not get next task.\n");
        return NULL;
    }
    // If there are no tasks in the queue, return NULL
    if (queue->num_tasks == 0) {
        return NULL;
    }
    // Return the first task in the queue and remove it from the queue
    TASK_RECORD_T* task = queue->tasks[0];
    for (size_t i = 1; i < queue->num_tasks; i++) {
        queue->tasks[i - 1] = queue->tasks[i];
    }
    queue->num_tasks--;
    return task;
}

// Function to print the contents of the priority queue
void print_queue(PRIORITY_QUEUE_T* queue) {
    if (!queue) {
        printf("Error: could not print queue.\n");
        return;
    }
    for (size_t i = 0; i < queue->num_tasks; i++) {
        TASK_RECORD_T* task = queue->tasks[i];
        printf("%d - %f%%\n", task->task_id, task->current_progress);
    }
}
```
