// Initialize the linked list with default values for each node
void init_linked_list(LinkedList* head) {
    head->header = (PacketHeader*) malloc(sizeof(PacketHeader));
    head->header->protocol_type = 'U';
    head->header->source_ip = NULL;
    head->header->dest_ip = NULL;
    head->header->payload_length = 0;
    head->next = NULL;
}

// Add a new node to the linked list with the given packet header
void add_node(LinkedList* head, PacketHeader* header) {
    // Check if the linked list is empty
    if (head == NULL) {
        init_linked_list(head);
    }

    // Create a new node and set its value to the given packet header
    LinkedList* new_node = (LinkedList*) malloc(sizeof(LinkedList));
    new_node->header = header;
    new_node->next = NULL;

    // If the linked list is not empty, append the new node at the end of the list
    if (head != NULL) {
        LinkedList* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Remove a node from the linked list with the given packet header
void remove_node(LinkedList* head, PacketHeader* header) {
    // Check if the linked list is empty
    if (head == NULL) {
        return;
    }

    // If the linked list has only one node, free it and set the head to NULL
    if (head->next == NULL) {
        free(head);
        head = NULL;
        return;
