// Function to allocate memory for arrays and initialize them
void init_arrays(int *offset_arr, int *key_arr, int offset_count, int key_count) {
    // Check if input sizes are valid
    if (offset_count <= 0 || key_count <= 0) {
        printf("Invalid input size\n");
        return;
    }

    // Calculate total memory required for arrays
    int total_mem = offset_count * sizeof(int) + key_count * sizeof(double);
    if (total_mem > MAX_MEMORY) {
        printf("Total memory required exceeds 1 MB\n");
        return;
    }

    // Allocate memory for arrays
    offset_arr = malloc(offset_count * sizeof(int));
    key_arr = malloc(key_count * sizeof(double));
    if (!offset_arr || !key_arr) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize arrays with default values
    memset(offset_arr, 0, offset_count * sizeof(int));
    memset(key_arr, 0.0, key_count * sizeof(double));
}

// Function to allocate memory for records and initialize them
void init_records(Record *record_arr, int record_count) {
    // Check if input size is valid
    if (record_count <= 0) {
        printf("Invalid input size\n");
        return;
    }

    // Calculate total memory required for records
    int total_mem = record_count * sizeof(Record);
    if (total_mem > MAX_MEMORY / 2) {
        printf("Total memory required exceeds 500 KB\n");
        return;
    }

    // Allocate memory for records
    record_arr = malloc(record_count * sizeof(Record));
    if (!record_arr) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize records with default values
    memset(record_arr, 0.0, record_count * sizeof(Record));
}

// Function to release all allocated memory when complete
void cleanup(int *offset_arr, int *key_arr, Record *record_arr) {
    // Release memory for arrays
    free(offset_arr);
    free(key_arr);

    // Release memory for records
    free(record_arr);
}

// Function to set a random value for each record's int field
void set_random_values(Record *record_arr, int record_count) {
    // Initialize RNG with a random seed
    srand(time(NULL));

    // Set a random value for each record's int field
    for (int i = 0; i < record_count; i++) {
        record_arr[i].key = rand() % MAX_RANDOM_VALUE;
    }
}
