    if (n > 10000 || m > 5000) {
        fprintf(stderr, "Error: Invalid number of records or keys\n");
        return NULL;
    }

    // Allocate memory for the offset and key arrays
    long* offsets = (long*)malloc(sizeof(long) * n);
    int* keys = (int*)malloc(sizeof(int) * m);
    if (!offsets || !keys) {
