    LogEntry **log_entries;
    // The number of log entries in the array
    size_t count;
} LogManager;

// A data structure that represents a single log entry
typedef struct {
    // An integer array of timestamp offsets
    long *offsets;
    // An integer key representing the log level (e.g., INFO, ERROR)
    int key;
    // The reference count for the log entry, initialized to zero
    size_t refcount;
} LogEntry;

// Allocate memory for a new LogManager structure with capacity for at least `capacity` log entries
LogManager *log_manager_new(size_t capacity) {
    // Validate input parameters
    if (capacity == 0) {
        return NULL;
    }

    // Allocate memory for the LogManager structure and its array of LogEntry pointers
    LogManager *manager = malloc(sizeof(LogManager));
    manager->log_entries = calloc(capacity, sizeof(LogEntry *));
    manager->count = 0;

    return manager;
}

// Free the memory allocated for a LogManager structure and its array of LogEntry pointers
void log_manager_free(LogManager *manager) {
    // Validate input parameters
    if (manager == NULL || manager->log_entries == NULL) {
        return;
    }

    // Free the memory allocated for each LogEntry structure in the array
    size_t i;
    for (i = 0; i < manager->count; ++i) {
        log_entry_free(manager->log_entries[i]);
    }

    // Free the memory allocated for the array of LogEntry pointers
    free(manager->log_entries);

    // Free the memory allocated for the LogManager structure itself
    free(manager);
}

// Allocate memory for a new LogEntry structure and initialize its reference count to zero
LogEntry *log_entry_new() {
    LogEntry *entry = malloc(sizeof(LogEntry));
    entry->refcount = 0;

    return entry;
}

// Free the memory allocated for a LogEntry structure and decrement its reference count
void log_entry_free(LogEntry *entry) {
    // Validate input parameters
    if (entry == NULL) {
        return;
    }

    // Decrement the reference count for the LogEntry structure
    --entry->refcount;

    // Free the memory allocated for the LogEntry structure if its reference count reaches zero
    if (entry->refcount == 0) {
        free(entry);
    }
}

// Add a new log entry to the LogManager structure, incrementing its reference count
void log_manager_add(LogManager *manager, const char *message, int key) {
    // Validate input parameters
    if (manager == NULL || message == NULL) {
        return;
    }

    // Allocate memory for a new LogEntry structure and initialize its reference count to zero
    LogEntry *entry = log_entry_new();

    // Populate the LogEntry structure with the specified key and message
    entry->key = key;
    entry->offsets = malloc(strlen(message) + 1);
    strcpy(entry->offsets, message);

    // Increment the reference count for the LogEntry structure
    ++entry->refcount;

    // Add the new log entry to the LogManager structure's array of LogEntry pointers
    manager->log_entries[manager->count++] = entry;
}

// Implement a custom deallocation function that handles decrementing the reference count and releasing resources when the reference count reaches zero
void log_entry_dealloc(LogEntry *entry) {
    // Validate input parameters
    if (entry == NULL || entry->refcount == 0) {
        return;
    }

    // Decrement the reference count for the LogEntry structure
    --entry->refcount;

    // Free the memory allocated for the LogEntry structure if its reference count reaches zero
    if (entry->refcount == 0) {
        free(entry->offsets);
        free(entry);
    }
}

// Simulate a scenario where log entries are generated at high frequency and require immediate processing
void high_frequency_logging() {
    // Create a new LogManager structure with capacity for 1000 log entries
    LogManager *manager = log_manager_new(1000);

    // Define a thread-safe logging function that adds a new log entry to the LogManager structure using a custom deallocation function
    void (*add_log)(const char *message, int key) = &log_manager_add;

    // Define a thread-safe deallocation function for LogEntry structures using the custom deallocation function implemented above
    void (*deallocate_entry)(LogEntry *entry) = &log_entry_dealloc;

    // Create 100 threads to simulate high frequency logging
    int i;
    pthread_t thread[100];
    for (i = 0; i < 100; ++i) {
        // Create a new thread to generate log entries and add them to the LogManager structure using the logging function defined above
        pthread_create(&thread[i], NULL, &add_log, "Log Entry #%d", i + 1);
    }

    // Wait for all threads to complete before freeing the memory allocated for the LogManager structure and its array of LogEntry pointers
    for (i = 0; i < 100; ++i) {
        pthread_join(thread[i], NULL);
    }

    log_manager_free(manager);
}
