#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <errno.h>

struct node {
    float data;
    char identifier;
    struct node* next;
};

struct hash_table {
    struct node** buckets;
    size_t num_buckets;
};

void init_hash_table(struct hash_table* table, size_t num_buckets) {
    table->num_buckets = num_buckets;
    table->buckets = calloc(num_buckets, sizeof(struct node*));
}

int hash(char identifier) {
    return identifier % table->num_buckets;
}

void insert_node(struct node* node, struct hash_table* table) {
    int index = hash(node->identifier);
    node->next = table->buckets[index];
    table->buckets[index] = node;
}

struct node* find_node(char identifier, struct hash_table* table) {
    int index = hash(identifier);
    struct node* current = table->buckets[index];
    while (current != NULL && current->identifier != identifier) {
        current = current->next;
    }
    return current;
}

void traverse_list(struct node* head, void (*callback)(struct node*)) {
    struct node* current = head;
    while (current != NULL) {
        callback(current);
        current = current->next;
    }
}

void free_nodes(struct node* head) {
    struct node* current = head;
    while (current != NULL) {
        struct node* next = current->next;
        free(current);
        current = next;
    }
}

void process_nodes(struct hash_table* table, void (*callback)(struct node*)) {
    size_t i;
    for (i = 0; i < table->num_buckets; i++) {
        struct node* current = table->buckets[i];
        while (current != NULL) {
            traverse_list(current, callback);
            current = current->next;
        }
    }
}

void destroy_hash_table(struct hash_table* table) {
    size_t i;
    for (i = 0; i < table->num_buckets; i++) {
        free_nodes(table->buckets[i]);
    }
    free(table->buckets);
}

void insert_data(float data, char identifier) {
    struct node* new_node = malloc(sizeof(struct node));
    if (new_node == NULL) {
        fprintf(stderr, "Error: could not allocate memory for node\n");
        return;
    }
    new_node->data = data;
    new_node->identifier = identifier;
    struct hash_table* table = malloc(sizeof(struct hash_table));
    if (table == NULL) {
        fprintf(stderr, "Error: could not allocate memory for hash table\n");
        free(new_node);
        return;
    }
    init_hash_table(table, 10000);
    insert_node(new_node, table);
    process_nodes(table, callback);
    destroy_hash_table(table);
}
