void log_error(int error_code, char *function_name) {
    if (!LOGGING_ENABLED) return;
    fprintf(logfile, "Error %d: %s failed in function %s\n", error_code, error_strings[error_code], function_name);
}

// define thread-safe memory allocation and deallocation functions
void *allocate_memory(uint32_t size) {
    pthread_mutex_lock(&mutex);
    void *ptr = NULL;
    if ((size + memory_pool_offset) <= MEMORY_POOL_SIZE) {
        ptr = &memory_pool[memory_pool_offset];
        memory_pool_offset += size;
    } else {
        log_error(ERROR_MEMORY_POOL_EXHAUSTION, "allocate_memory");
    }
    pthread_mutex_unlock(&mutex);
    return ptr;
}

void deallocate_memory(void *ptr) {
    pthread_mutex_lock(&mutex);
    if (ptr != NULL && &memory_pool[0] <= ptr && ptr < &memory_pool[MEMORY_POOL_SIZE]) {
        uint32_t size = (uint32_t)((char *)ptr - memory_pool);
        memory_pool_offset -= size;
    } else {
        log_error(ERROR_MEMORY_ALLOCATION, "deallocate_memory");
    }
    pthread_mutex_unlock(&mutex);
}

// define functions for managing SYSTEM_PROCESS_INFO structures
static uint32_t allocate_system_process_info(uint32_t record_size, bool *error) {
    // allocate memory for the structure
    void *ptr = allocate_memory(sizeof(SYSTEM_PROCESS_INFO));
    if (ptr == NULL) {
        log_error(ERROR_MEMORY_ALLOCATION, "allocate_system_process_info");
        *error = true;
        return 0;
    }
    // initialize the structure and allocate memory for the record array
    SYSTEM_PROCESS_INFO *spi = (SYSTEM_PROCESS_INFO *)ptr;
    spi->record_size = record_size;
    void *record_array_ptr = allocate_memory(record_size * sizeof(int64_t));
    if (record_array_ptr == NULL) {
        log_error(ERROR_MEMORY_ALLOCATION, "allocate_system_process_info");
        deallocate_memory(spi);
        *error = true;
        return 0;
    }
    spi->record = (int64_t *)record_array_ptr;
    // set the record array size and initialize its elements to random values within a specified range
    uint32_t i, j;
    for (i = 0; i < record_size; i++) {
        spi->record[i] = generate_random_value(MIN_RANDOM_VALUE, MAX_RANDOM_VALUE);
        for (j = 0; j < i; j++) {
            if (spi->record[i] == spi->record[j]) {
                spi->record[i] = generate_random_value(MIN_RANDOM_VALUE, MAX_RANDOM_VALUE);
            }
        }
    }
    // add the structure to the hash map and return its process ID
    uint32_t process_id = (uint32_t)((char *)spi - memory_pool);
    if (add_hash_map_entry(process_id, error)) {
        log_error(ERROR_HASH_MAP_CREATION, "allocate_system_process_info");
        deallocate_memory(record_array_ptr);
        deallocate_memory(spi);
    }
    return process_id;
}

static bool add_hash_map_entry(uint32_t process_id, bool *error) {
    // check if the entry already exists in the hash map
    void *ptr = hash_map_get(&process_id);
    if (ptr != NULL) {
        log_error(ERROR_DUPLICATE_KEY, "add_hash_map_entry");
        return true;
    }
    // add the entry to the hash map and return success
    void *entry = allocate_memory(sizeof(struct hash_map_entry));
    if (entry == NULL) {
        log_error(ERROR_MEMORY_ALLOCATION, "add_hash_map_entry");
        return true;
    }
    struct hash_map_entry *hme = (struct hash_map_entry *)entry;
    hme->process_id = process_id;
    hme->next = NULL;
    hash_map_put(&process_id, entry);
    return false;
}

static void deallocate_system_process_info(uint32_t process_id) {
    // check if the structure is in the hash map and remove it
    void *ptr = hash_map_remove(&process_id);
    if (ptr == NULL) return;
    SYSTEM_PROCESS_INFO *spi = (SYSTEM_PROCESS_INFO *)ptr;
