```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the data structure for the record
struct record {
    long timestamp;
    float value;
    bool validity;
};

// Define the cache data structure
struct cache {
    struct record** data; // Array of pointers to records
    int size; // Current size of the cache
    int capacity; // Maximum capacity of the cache
    long timestamp_incr; // Timestamp increment for new records
    pthread_mutex_t lock; // Mutex for thread-safe access
};

// Function to initialize the cache
void init_cache(struct cache* cache) {
    // Allocate memory for the data array and set its size to zero
    cache->data = malloc(sizeof(struct record*) * 1000);
    cache->size = 0;
    cache->capacity = 1000;
    cache->timestamp_incr = 1;
    pthread_mutex_init(&cache->lock, NULL);
}

// Function to add a new record to the cache
void add_record(struct cache* cache, long timestamp, float value, bool validity) {
    // Lock the cache mutex to prevent concurrent access
    pthread_mutex_lock(&cache->lock);

    // Check if the cache is full and needs to be resized
    if (cache->size == cache->capacity) {
        resize_cache(cache);
    }

    // Allocate memory for the new record and set its fields
    struct record* new_record = malloc(sizeof(struct record));
    new_record->timestamp = timestamp;
    new_record->value = value;
    new_record->validity = validity;

    // Add the new record to the cache and update its size
    cache->data[cache->size++] = new_record;

    // Unlock the cache mutex
    pthread_mutex_unlock(&cache->lock);
}

// Function to resize the cache when it is full
void resize_cache(struct cache* cache) {
    // Double the capacity of the cache and reallocate memory for the data array
    cache->capacity *= 2;
    cache->data = realloc(cache->data, sizeof(struct record*) * cache->capacity);

    // Lock the cache mutex to prevent concurrent access
    pthread_mutex_lock(&cache->lock);

    // Iterate over all records in the cache and move them to the new data array
    for (int i = 0; i < cache->size; i++) {
        struct record* old_record = cache->data[i];
        int new_index = i % cache->capacity;
        cache->data[new_index] = old_record;
    }

    // Unlock the cache mutex
    pthread_mutex_unlock(&cache->lock);
}

// Function to retrieve a record from the cache by timestamp
struct record* get_record(struct cache* cache, long timestamp) {
    // Lock the cache mutex to prevent concurrent access
    pthread_mutex_lock(&cache->lock);

    // Iterate over all records in the cache and search for a match
    for (int i = 0; i < cache->size; i++) {
        struct record* current_record = cache->data[i];
        if (current_record->timestamp == timestamp) {
            // Unlock the cache mutex and return the matching record
            pthread_mutex_unlock(&cache->lock);
            return current_record;
        }
    }

    // Unlock the cache mutex and return NULL if no match was found
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}
