        inbuf = malloc(inbuf_size);
        inbuf_used = recv(client_fd, inbuf, inbuf_size, MSG_WAITALL);
        if (inbuf_used < 0) {
            perror("recv");
            free(inbuf);
            close(client_fd);
            return;
        }
        // Validate IP address and handle error
        if (!validate_ip(inet_ntoa((struct in_addr){.s_addr = client_fd}))) {
            fprintf(stderr, "Invalid IP address\n");
            free(inbuf);
            close(client_fd);
            return;
        }
        // Create connection state and initialize fields
        conn = malloc(sizeof(connection_state_t));
        conn->client_fd = client_fd;
        conn->inbuf = inbuf;
        conn->inbuf_size = inbuf_size;
        conn->inbuf_used = inbuf_used;
        conn->outbuf = NULL;
        conn->outbuf_size = 0;
        conn->outbuf_used = 0;

        // Process request and send response
        handle_request(conn);

        free(inbuf);
        close(client_fd);
        return;
    }
}

void *handle_connection_wrapper(void *ptr) {
    int client_fd = (int) ptr;
    pthread_mutex_lock(&lock);
    handle_connection(client_fd);
    pthread_mutex_unlock(&lock);
    return NULL;
}

int main() {
    struct sockaddr_in server_addr;
    int listen_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (listen_fd < 0) {
        perror("socket");
        return 1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(listen_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        return 1;
    }

    if (listen(listen_fd, MAX_CONNS) < 0) {
        perror("listen");
        return 1;
    }

    while (1) {
        struct sockaddr_in client_addr;
        int client_len = sizeof(client_addr);
        int client_fd = accept(listen_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            perror("accept");
            return 1;
        }
        pthread_t thread;
        pthread_create(&thread, NULL, handle_connection_wrapper, (void *) client_fd);
    }
}
```
This code creates a scalable pool of connection states for an HTTP server using a lock mechanism to prevent race conditions. The `allowed_addrs` array contains the list of allowed IP addresses for incoming connections. The `validate_ip` function checks if the given address is in the allowed list, and returns 1 if it is or 0 otherwise.

The `handle_connection` function first tries to receive data from the client socket using `recv`. If the call fails, it prints an error message and closes the connection. Otherwise, it creates a new connection state object and initializes its fields using `malloc` and `socket`. The function then checks if the IP address is valid and handles any errors accordingly.

The `handle_request` function processes the incoming request and sends a response back to the client socket using `send`. It also frees the memory allocated for the connection state object when it is no longer needed.

The `main` function creates a listen socket, binds it to port 80, and starts listening for incoming connections using `listen`. The loop in the main function accepts incoming connections and creates a new thread for each client using `accept` and `pthread_create`. The thread calls `handle_connection` to process the connection.

Note that this is a very basic example of an HTTP server, and there are many other things you might want to consider when building a production-ready HTTP server, such as handling multiple requests concurrently, handling errors gracefully, and using more robust networking functions like `select` or `epoll`.']

