void allocateAndInitializeRecords(int numRecords, int rangeMin, int rangeMax, int *arr) {
    // Dynamically allocate memory for the record array
    arr = (int *)malloc(numRecords * sizeof(Record));
    if (arr == NULL) {
        printf("Error: failed to allocate memory for the record array\n");
        return;
    }

