    {
        private readonly Stopwatch _stopwatch = new Stopwatch();

        public PerformanceMonitor()
        {
            _stopwatch.Start();
        }

        public void Dispose()
        {
            _stopwatch.Stop();
            Console.WriteLine($"Processing time: {_stopwatch.ElapsedMilliseconds}ms");
        }
