        {
            // Validate input parameters and ensure they are properly formatted
            if (string.IsNullOrEmpty(pageSectionId) || string.IsNullOrEmpty(elementId) || string.IsNullOrEmpty(htmlContent))
            {
                throw new ArgumentException("Invalid input parameters");
            }

            // Manage 'offset' array size up to 1000 due to limited memory resources
            if (_offsets.Count >= MAX_OFFSET_ARRAY_SIZE)
            {
                _offsets.RemoveRange(0, _offsets.Count - MAX_OFFSET_ARRAY_SIZE);
            }

            // Manage 'key' structures and ensure they are properly formatted
            foreach (var key in _keys.Values)
            {
                if (!int.TryParse(key.Record.Value, out int recordValue))
                {
                    throw new ArgumentException("Invalid input parameters");
                }
            }

            // Update element's HTML content
            var element = new Element()
            {
                PageSectionId = pageSectionId,
                Id = elementId,
                HtmlContent = htmlContent
            };

            _keys.Add(element.Id, new Key() { Record = new Record() { Value = recordValue } });
            _offsets.Add(new Offset() { Long = 0L });
        }
    }

    private class Element
    {
        public string PageSectionId { get; set; }
        public string Id { get; set; }
        public string HtmlContent { get; set; }
    }

