        printf("Error opening file: %s\n", strerror(errno));
        return -1;
    }

    int num_records = 0;
    long current_offset = 0;
    while (fscanf(file, "%ld%d", &current_offset, &num_records) == 2) {
        if (current_offset > MAX_LONG || num_records < MIN_INT || num_records > MAX_INT) {
            printf("Invalid input: %ld %d\n", current_offset, num_records);
            fclose(file);
            return -1;
        }

        long* offset = realloc(*offset_array, sizeof(long) * (num_records + 1));
        if (offset == NULL) {
            printf("Error allocating memory for offset array\n");
            fclose(file);
            return -2;
        }
        *offset_array = offset;
        (*offset)[num_records] = current_offset;

        int* key = realloc(*key_array, sizeof(int) * (num_records + 1));
        if (key == NULL) {
            printf("Error allocating memory for key array\n");
            fclose(file);
            return -3;
        }
        *key_array = key;
        (*key)[num_records] = num_records;

        record* rec = realloc(*record_array, sizeof(record) * (num_records + 1));
        if (rec == NULL) {
            printf("Error allocating memory for record array\n");
            fclose(file);
            return -4;
        }
        *record_array = rec;
        (*record)[num_records].key = num_records;
        (*record)[num_records].buffer[0] = '\0';
    }

    fclose(file);
    return num_records;
}

