    if (num_records < 0) {
        printf("Error reading file\n");
        return -1;
    }

    for (int i = 0; i < num_records; i++) {
        printf("%ld %d %s\n", (*offset_array)[i], (*key_array)[i], (*record_array)[i].buffer);
    }

    free(offset_array);
    free(key_array);
    for (int i = 0; i < num_records; i++) {
        free((*record_array)[i].buffer);
