// C function that manages a dynamic list of SYSTEM_PROCESS_INFO structures alongside 'record' structures, each containing a single 'int' value. Dynamically allocated memory is ensured to be unique and within the specified limits.

#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>
#include <unistd.h>

#define MAX_RECORDS 10000
#define MIN_RECORD_SIZE 500000
#define MAX_RECORD_SIZE 1000000
#define MAX_PROCESS_ID 10000000
#define MEMORY_POOL_SIZE 1500000

// Structures for the system process info and records
struct SYSTEM_PROCESS_INFO {
    int PROCESS_ID;
};

struct RECORD {
    int value;
};

// Function to generate a random number within a specified range
int randInt(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to check for duplicates in the hash map
bool isDuplicate(int key, void *data) {
    struct SYSTEM_PROCESS_INFO *info = (struct SYSTEM_PROCESS_INFO *) data;
    return info->PROCESS_ID == key;
}

// Function to add a new record to the hash map and memory pool
void addRecord(int value, void **data) {
    struct RECORD *record = malloc(sizeof(struct RECORD));
    if (record != NULL) {
        record->value = value;
        *data = record;
    } else {
        printf("Memory allocation failed\n");
    }
}

// Function to remove a record from the hash map and memory pool
void removeRecord(int key, void **data) {
    struct SYSTEM_PROCESS_INFO info;
    info.PROCESS_ID = key;
    if (isDuplicate(key, *data)) {
        free(*data);
        *data = NULL;
    } else {
        printf("Key not found\n");
    }
}

// Function to update a record in the hash map and memory pool
void updateRecord(int key, int value) {
    struct RECORD *record = (struct RECORD *) malloc(sizeof(struct RECORD));
    if (record != NULL) {
        record->value = value;
        *data = record;
    } else {
        printf("Memory allocation failed\n");
    }
}

// Function to retrieve a record from the hash map and memory pool
struct RECORD *getRecord(int key, void **data) {
    struct SYSTEM_PROCESS_INFO info;
    info.PROCESS_ID = key;
    if (isDuplicate(key, *data)) {
        return *data;
    } else {
        printf("Key not found\n");
        return NULL;
    }
}

// Function to log successful allocations and errors
void logAllocation(int record_size) {
    FILE *logFile = fopen("allocation_log.txt", "a+");
    if (logFile != NULL) {
        fprintf(logFile, "%d\n", record_size);
        fclose(logFile);
    } else {
        printf("Error opening allocation log file\n");
    }
}

// Function to handle memory allocation failures gracefully
void handleAllocationFailure() {
    printf("Memory allocation failed\n");
}

// Function to set the 'int' values in the 'record' structures to random values within a specified range, ensuring uniqueness.
int main(void) {
    srand(time(NULL));
    int record_size = randInt(MIN_RECORD_SIZE, MAX_RECORD_SIZE);
    struct RECORD *record;
    while (1) {
        // Generate a random 'int' value within the specified range
        int value = randInt(0, MAX_PROCESS_ID);
        // Check if the 'int' value is already in the hash map and memory pool
        if (!isDuplicate(value, record)) {
            // Add the new record to the hash map and memory pool
            addRecord(value, &record);
            logAllocation(record_size);
        } else {
            handleAllocationFailure();
        }
    }
}']

