}

void removeDuplicates(vector<int> &integers) {
    sort(integers.begin(), integers.end());
    int i = 0;
    while (i < integers.size() - 1) {
        if (integers[i] == integers[i + 1]) {
            integers.erase(integers.begin() + i);
        } else {
            ++i;
        }
    }
}

void handleDuplicates(vector<int> &integers) {
