// Define structure for CRC indication PDU
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T crc_ind;
    pthread_mutex_t mutex;
} CrcIndPdu;

// Define list of CRC indication PDUs
static CrcIndPdu *crc_ind_list = NULL;
static int max_list_size = 10000; // configurable maximum list size

// Define mutex for protecting access to list
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void insertCrcIndPdu(NFAPI_CRC_INDICATION_PDU_T crc_ind) {
    // Acquire mutex to protect access to list
    pthread_mutex_lock(&list_mutex);

    // Check if list is full
    if (crc_ind_list == NULL || num_elements >= max_list_size) {
        printf("CRC indication list is full, dropping new element\n");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    // Allocate memory for new CRC indication PDU
    CrcIndPdu *new_pdu = malloc(sizeof(CrcIndPdu));
    if (new_pdu == NULL) {
        printf("Failed to allocate memory for new CRC indication PDU\n");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    // Initialize mutex for new PDU
    pthread_mutex_init(&new_pdu->mutex, NULL);

    // Copy CRC indication data to new PDU
    memcpy(&new_pdu->crc_ind, &crc_ind, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Validate structure integrity
    if (!validateCrcIndPdu(new_pdu)) {
        printf("Invalid CRC indication PDU, dropping new element\n");
        pthread_mutex_unlock(&list_mutex);
        free(new_pdu);
        return;
    }

    // Insert new PDU into list
    if (crc_ind_list == NULL) {
        crc_ind_list = malloc(sizeof(CrcIndPdu));
    } else {
        CrcIndPdu *last_pdu = crc_ind_list;
        while (last_pdu->next != NULL) {
            last_pdu = last_pdu->next;
        }
        last_pdu->next = malloc(sizeof(CrcIndPdu));
    }
    new_pdu->next = NULL;

    // Release mutex
    pthread_mutex_unlock(&list_mutex);
}

void deleteCrcIndPdu(NFAPI_CRC_INDICATION_PDU_T crc_ind) {
    // Acquire mutex to protect access to list
    pthread_mutex_lock(&list_mutex);

    // Find PDU in list and remove it
    CrcIndPdu *pdu = crc_ind_list;
    while (pdu != NULL && memcmp(&pdu->crc_ind, &crc_ind, sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
        pdu = pdu->next;
    }
    if (pdu == NULL) {
        printf("Could not find CRC indication PDU to delete\n");
        pthread_mutex_unlock(&list_mutex);
        return;
    }
    if (pdu == crc_ind_list) {
        crc_ind_list = pdu->next;
    } else {
        CrcIndPdu *last_pdu = crc_ind_list;
        while (last_pdu->next != pdu) {
            last_pdu = last_pdu->next;
        }
        last_pdu->next = pdu->next;
    }

    // Release mutex
    pthread_mutex_unlock(&list_mutex);
}

void updateCrcIndPdu(NFAPI_CRC_INDICATION_PDU_T crc_ind) {
    // Acquire mutex to protect access to list
    pthread_mutex_lock(&list_mutex);

    // Find PDU in list and update it
    CrcIndPdu *pdu = crc_ind_list;
    while (pdu != NULL && memcmp(&pdu->crc_ind, &crc_ind, sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
        pdu = pdu->next;
    }
    if (pdu == NULL) {
        printf("Could not find CRC indication PDU to update\n");
        pthread_mutex_unlock(&list_mutex);
        return;
    }
    memcpy(&pdu->crc_ind, &crc_ind, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Release mutex
    pthread_mutex_unlock(&list_mutex);
}

int validateCrcIndPdu(CrcIndPdu *pdu) {
    if (pdu == NULL || !validateRxUeInformationTag(pdu->crc_ind.rx_ue_information_tag)) {
        return 0;
    }
    // Check that CRC flag is correctly initialized
    if (!(pdu->crc_ind.crc_flag == NFAPI_CRC_FLAG_ON || pdu->crc_ind.crc_flag == NFAPI_CRC_FLAG_OFF)) {
        return 0;
    }
    // Check that RNTI is correctly initialized
    if (!validateRnti(pdu->crc_ind.rnti)) {
        return 0;
    }
    return 1;
}

int validateRxUeInformationTag(NFAPI_RX_UE_INFORMATION_TAG rx_ue_information_tag) {
    if (!validateRxAntennaIndex(rx_ue_information_tag.rx_antenna_index)) {
        return 0;
    }
    if (!validateRxTimestamp(rx_ue_information_tag.rx_timestamp)) {
        return 0;
    }
    if (!validateRxUeInformationTag(rx_ue_information_tag.ul_cqi_information)) {
        return 0;
    }
    return 1;
}

int validateRnti(NFAPI_RNTI rnti) {
    // Check that RNTI is positive and less than 65536
    if (rnti < 0 || rnti >= 65536) {
        return 0;
    }
    return 1;
}

int validateRxAntennaIndex(NFAPI_RX_ANTENNA_INDEX rx_antenna_index) {
    // Check that RX antenna index is positive and less than or equal to 8
    if (rx_antenna_index <= 0 || rx_antenna_index > 8) {
        return 0;
    }
    return 1;
}

int validateRxTimestamp(NFAPI_RX_TIMESTAMP rx_timestamp) {
    // Check that RX timestamp is positive and less than or equal to 2^31-1
    if (rx_timestamp <= 0 || rx_timestamp > 2147483647) {
        return 0;
    }
    return 1;
}
