#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <stdio.h>

typedef struct {
    long *offset_array;
    int *key_array;
} record_struct;

void allocate_memory(int num_records, size_t max_size) {
    if (num_records <= 0 || max_size == 0) {
        // Handle invalid input
        return;
    }

    // Check for potential integer overflow and buffer overflows
    if (max_size > SIZE_MAX / sizeof(record_struct)) {
        printf("Error: total allocated memory exceeds maximum allowed\n");
        return;
    }

    size_t array_size = num_records * sizeof(record_struct);
    if (array_size > max_size) {
        printf("Error: requested memory exceeds maximum allowed\n");
        return;
    }

    // Allocate memory for the offset and key arrays
    record_struct *records = malloc(array_size);
    if (records == NULL) {
        printf("Error: unable to allocate memory\n");
        return;
    }

    // Initialize the offset and key arrays
    for (int i = 0; i < num_records; i++) {
        records[i].offset_array = malloc(sizeof(long));
        if (records[i].offset_array == NULL) {
            printf("Error: unable to allocate memory\n");
            return;
        }
        records[i].key_array = malloc(sizeof(int));
        if (records[i].key_array == NULL) {
            printf("Error: unable to allocate memory\n");
            return;
        }
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    // Generate random numbers and fill in the offset and key arrays
    for (int i = 0; i < num_records; i++) {
        records[i].offset_array[i] = rand() % max_size + 1;
        records[i].key_array[i] = rand() % INT_MAX;
    }
}

void free_memory(record_struct *records) {
    if (records == NULL) {
        // Handle invalid input
        return;
    }

    // Release memory for the offset and key arrays
    for (int i = 0; i < num_records; i++) {
        free(records[i].offset_array);
        free(records[i].key_array);
    }

    // Release memory for the record structures
    free(records);
}
