using namespace std;

class RandomValueGenerator {
private:
    float minimum;
    float maximum;
public:
    RandomValueGenerator(float min, float max) : minimum(min), maximum(max) {}

    float getRandomFloat() { return UnityEngine.Random.Range(minimum, maximum); }
    int getRandomInt() { return (int)(UnityEngine.Random.Range(minimum, maximum)); }

    string ToString() {
        return "Random value range: [" + to_string(minimum) + ", " + to_string(maximum) + "]";
    }
};

void insertAfterFirstOccurrence(forward_list<string>& list, mutex& mutex, condition_variable& cond_var, string search_str, string new_str) {
    unique_lock<mutex> lock(mutex);
    bool found = false;
    for (auto it = list.begin(); it != list.end(); ++it) {
        if (*it == search_str) {
            auto next_it = next(it);
            if (next_it != list.end()) {
                it = next_it;
            } else {
                list.push_back(new_str);
                break;
            }
        }
    }
    lock.unlock();
    cond_var.notify_all();
}

void testInsertAfterFirstOccurrence() {
