// Define a structure to represent a data point with timestamp, value, and validity flag
typedef struct {
  long timestamp;
  double value;
  bool validity_flag;
} dataPoint;

// Define a structure to represent a record with an integer key and a pointer to the corresponding data point
typedef struct {
  int key;
  dataPoint *data_point;
} record;

// Define a caching mechanism that stores up to 5000 unique records
#define CACHE_CAPACITY 5000
#define RECORD_SIZE sizeof(record)
#define DATA_POINT_SIZE sizeof(dataPoint)
typedef struct {
  record *records;
  int count;
} cache;

// Initialize a new cache with the given capacity and size of each record
cache* initCache(int capacity, int recordSize, int dataPointSize) {
  cache *c = malloc(sizeof(cache));
  c->records = malloc(capacity * sizeof(record));
  c->count = 0;

  // Initialize the records in the cache
  for (int i = 0; i < capacity; i++) {
    record *r = &c->records[i];
    r->key = -1;
    r->data_point = malloc(recordSize + dataPointSize);
    memset(r->data_point, 0, recordSize + dataPointSize);
  }

  return c;
}

// Add a new record to the cache if it is not already present and has enough space available
bool addRecordToCache(cache *c, int key, double value) {
  // Check if the record exists in the cache
  for (int i = 0; i < c->count; i++) {
    if (c->records[i].key == key) {
      return false;
    }
  }

  // If the cache is full, remove the least recently used entry and replace it with the new record
  if (c->count >= CACHE_CAPACITY) {
    record *lru = &c->records[0];
    while (lru->key != -1) {
      lru++;
    }
    c->count--;
    free(lru->data_point);
  }

  // Add the new record to the cache
  c->records[c->count].key = key;
  c->records[c->count].data_point->timestamp = time(NULL);
  c->records[c->count].data_point->value = value;
  c->records[c->count].data_point->validity_flag = true;
  c->count++;

  return true;
}

// Get the data point for the given key from the cache, if it exists
dataPoint* getDataPointFromCache(cache *c, int key) {
  // Check if the record exists in the cache
  for (int i = 0; i < c->count; i++) {
    if (c->records[i].key == key) {
      return c->records[i].data_point;
    }
  }

  return NULL;
}

// Clean up the cache and free all memory allocated for it
void cleanupCache(cache *c) {
  // Free the data points in each record
  for (int i = 0; i < c->count; i++) {
    free(c->records[i].data_point);
  }

  // Free the records array and the cache structure itself
  free(c->records);
  free(c);
}
```
