    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex; // Synchronization mechanism for thread safety
} NFAPI_CRC_LIST;

// Function to create a new list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_LIST* nfapi_crc_list_create(size_t capacity) {
    // Allocate memory for the list and its mutex
    NFAPI_CRC_LIST *list = (NFAPI_CRC_LIST*)malloc(sizeof(NFAPI_CRC_LIST));
    if (!list) {
        return NULL;
    }
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }
    list->capacity = capacity;
    list->size = 0;
    // Initialize the mutex
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Function to add a new NFAPI_CRC_INDICATION_PDU_T structure to the list
bool nfapi_crc_list_add(NFAPI_CRC_LIST *list, NFAPI_CRC_INDICATION_PDU_T *data) {
    // Acquire the mutex before modifying the list
    pthread_mutex_lock(&list->mutex);
    // Check if the list is full
    if (list->size >= list->capacity) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }
    // Validate that the RNTI value is not already present in the list
    for (int i = 0; i < list->size; ++i) {
        if (data->RX_UE_INFORMATION_TAG.RNTI == list->data[i].RX_UE_INFORMATION_TAG.RNTI) {
            pthread_mutex_unlock(&list->mutex);
            return false;
        }
    }
    // Randomly set the CRCFLAG value for the new structure
    data->CRC_INDICATION_REL8_TAG.CRCFLAG = random_number_library_generate(100) % 2;
    // Add the new structure to the list
    list->data[list->size++] = *data;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

// Function to remove an NFAPI_CRC_INDICATION_PDU_T structure from the list by RNTI value
bool nfapi_crc_list_remove(NFAPI_CRC_LIST *list, uint16_t rnti) {
    // Acquire the mutex before modifying the list
    pthread_mutex_lock(&list->mutex);
    // Find the index of the structure with the matching RNTI value
    for (int i = 0; i < list->size; ++i) {
        if (list->data[i].RX_UE_INFORMATION_TAG.RNTI == rnti) {
            // Remove the structure from the list by shifting all subsequent structures down
            for (int j = i; j < list->size - 1; ++j) {
                list->data[j] = list->data[j + 1];
            }
            --list->size;
            pthread_mutex_unlock(&list->mutex);
            return true;
        }
    }
    // Release the mutex if no matching structure was found
    pthread_mutex_unlock(&list->mutex);
    return false;
}

// Function to clear and free all allocated resources in the list
void nfapi_crc_list_clear(NFAPI_CRC_LIST *list) {
    // Acquire the mutex before modifying the list
    pthread_mutex_lock(&list->mutex);
    // Clear the list by setting its size to 0
    list->size = 0;
    // Release the mutex and free all allocated resources
    pthread_mutex_unlock(&list->mutex);
    free(list->data);
    free(list);
}

// Function to destroy the list and all its contents
void nfapi_crc_list_destroy(NFAPI_CRC_LIST *list) {
    // Acquire the mutex before modifying the list
    pthread_mutex_lock(&list->mutex);
    // Clear and free all allocated resources in the list
    nfapi_crc_list_clear(list);
    // Release the mutex and free the mutex itself
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
