#include <stdlib.h>
#include <string.h>
#include <assert.h>

// Define structure for entry with key and description
typedef struct {
    long key;
    char* description;
} Entry;

// Define collection type with initial capacity and threshold for resizing
typedef struct {
    size_t count;
    size_t capacity;
    size_t threshold;
    Entry** entries;
} Collection;

// Initialize a new collection with given initial capacity and resize threshold
Collection* init_collection(size_t initial_capacity, size_t resize_threshold) {
    // Allocate memory for collection structure
    Collection* collection = (Collection*)malloc(sizeof(Collection));
    assert(collection != NULL);

    // Initialize count and capacity to 0
    collection->count = 0;
    collection->capacity = initial_capacity;

    // Set resize threshold to given value
    collection->threshold = resize_threshold;

    // Allocate memory for entries array
    collection->entries = (Entry**)malloc(sizeof(Entry*) * initial_capacity);
    assert(collection->entries != NULL);

    return collection;
}

// Free memory allocated by collection structure
void free_collection(Collection* collection) {
    // Free entries array
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->entries[i]->description);
    }
    free(collection->entries);

    // Free collection structure
    free(collection);
}

// Add new entry to the collection, dynamically resizing it if necessary
void add_entry(Collection* collection, long key, const char* description) {
    // Check if threshold has been reached and resize collection if so
    if (collection->count == collection->capacity) {
        collection->capacity *= 2;
        collection->entries = realloc(collection->entries, sizeof(Entry*) * collection->capacity);
        assert(collection->entries != NULL);
    }

    // Allocate memory for new entry and copy key and description strings
    Entry* entry = (Entry*)malloc(sizeof(Entry));
    assert(entry != NULL);

    entry->key = key;
    entry->description = strdup(description);

    collection->entries[collection->count++] = entry;
}

// Remove entry from the collection by key, dynamically resizing it if necessary
void remove_entry(Collection* collection, long key) {
    // Find index of entry with given key
    size_t index = 0;
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->entries[i]->key == key) {
            index = i;
            break;
        }
    }

    // Check if entry was found and remove it from the collection
    if (index != 0) {
        Entry* entry = collection->entries[index];
        free(entry->description);
        memmove(&collection->entries[index], &collection->entries[index + 1], (collection->count - index - 1) * sizeof(Entry));
        --collection->count;
    }

    // Check if collection needs to be resized
    if (collection->capacity > collection->threshold && collection->count < collection->capacity / 2) {
        collection->capacity /= 2;
        collection->entries = realloc(collection->entries, sizeof(Entry*) * collection->capacity);
        assert(collection->entries != NULL);
    }
}

// Search for entry in the collection by key and return its index if found
size_t find_entry(Collection* collection, long key) {
    // Iterate over entries until the one with given key is found or end of collection reached
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->entries[i]->key == key) {
            return i;
        }
    }

    // Return -1 if entry was not found
    return -1;
}

// Update the description of an existing entry in the collection
void update_entry(Collection* collection, long key, const char* description) {
    // Find index of entry with given key
    size_t index = find_entry(collection, key);

    // Check if entry was found and update its description
    if (index != -1) {
        free(collection->entries[index]->description);
        collection->entries[index]->description = strdup(description);
    }
}

// Populate the descriptions of all entries in the collection with randomly generated strings
void populate_descriptions(Collection* collection, const char* seed) {
    // Set seed for random number generation
    srand((unsigned int)time(NULL));

    // Iterate over entries and generate random descriptions
    for (size_t i = 0; i < collection->count; ++i) {
        Entry* entry = collection->entries[i];
        size_t length = rand() % MAX_DESCRIPTION_LENGTH + MIN_DESCRIPTION_LENGTH;
        char* description = (char*)malloc(length);
        assert(description != NULL);

        for (size_t j = 0; j < length - 1; ++j) {
            description[j] = 'a' + rand() % ('z' - 'a');
        }

        description[length - 1] = '\0';
        entry->description = strdup(description);
        free(description);
    }
}
```
