    for (i = 0; i < MAX_DEVICES; i++) {
        if (pool[i].deviceSerialNumber != NULL && strcmp(pool[i].deviceSerialNumber, deviceSerialNumber) == 0) {
            break;
        }
    }
    if (i >= MAX_DEVICES || pool[i].deviceSerialNumber == NULL) {
        return -1; // Device serial number not found in the pool
    }

