import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Semaphore;

public class DynamicDataIngestionService {
    private final ConcurrentHashMap<String, Object> dataBuffer = new ConcurrentHashMap<>();
    private final ExecutorService executorService = Executors.newCachedThreadPool();
    private final Semaphore bufferLock = new Semaphore(1);

    public void ingestData(Object data) {
        try {
            bufferLock.acquire();
            dataBuffer.put(String.valueOf(data), data);
        } catch (InterruptedException e) {
            e.printStackTrace();
        } finally {
            bufferLock.release();
        }
    }

    public void flushData() {
        try {
            bufferLock.acquire();
            for (Object data : dataBuffer.values()) {
                // Perform data processing and storage here
            }
            dataBuffer.clear();
        } catch (InterruptedException e) {
            e.printStackTrace();
        } finally {
            bufferLock.release();
        }
    }

    public void pause() {
        try {
            bufferLock.acquire();
            for (Object data : dataBuffer.values()) {
                // Pause data processing and storage here
            }
        } catch (InterruptedException e) {
            e.printStackTrace();
        } finally {
            bufferLock.release();
        }
    }

    public void resume() {
        try {
            bufferLock.acquire();
            for (Object data : dataBuffer.values()) {
                // Resume data processing and storage here
            }
        } catch (InterruptedException e) {
            e.printStackTrace();
        } finally {
            bufferLock.release();
        }
    }

    public void shutdown() {
        executorService.shutdownNow();
    }
}
```
