    if (points_ptr == NULL) {
        fprintf(stderr, "Failed to allocate memory for the point array\n");
        exit(-1);
    }
    enum status* statuses_ptr = malloc(sizeof(enum status) * (length(statuses)));
    if (statuses_ptr == NULL) {
        fprintf(stderr, "Failed to allocate memory for the status array\n");
        exit(-1);
    }

    // initialize the arrays with input values
    memcpy(double_ptr, double_array, sizeof(double) * (length(double_array)));
    memcpy(identifiers_ptr, identifiers, sizeof(char) * (length(identifiers)));
    memcpy(points_ptr, points, sizeof(struct point) * (length(points)));
    memcpy(statuses_ptr, statuses, sizeof(enum status) * (length(statuses)));

    // initialize the distance field for each struct point object
    for (int i = 0; i < length(points); i++) {
        points_ptr[i].distance = round((sqrt((points_ptr[i].x * points_ptr[i].x) + (points_ptr[i].y * points_ptr[i].y))));
    }

    // check for duplicate distances and log an error if found
    for (int i = 0; i < length(points); i++) {
        for (int j = i + 1; j < length(points); j++) {
            if (points_ptr[i].distance == points_ptr[j].distance) {
                fprintf(stderr, "Error: Duplicate distance values found in the point array\n");
                exit(-1);
            }
        }
    }
}

// get the length of an array
int length(void* arr) {
    int length = 0;
    while (*((char*)arr + length) != '\0') {
        length++;
    }
    return length;
