// Define a memory pool for efficiently reusing memory blocks
typedef struct {
    size_t num_blocks;
    void *blocks[];
} MEMORY_POOL_T;

static MEMORY_POOL_T *memory_pool = NULL;

// Define a function to allocate a new memory pool with the given number of blocks
MEMORY_POOL_T* memory_pool_alloc(size_t num_blocks) {
    // Allocate memory for the pool structure and its block array
    size_t size = sizeof(MEMORY_POOL_T) + (num_blocks * sizeof(void*));
    MEMORY_POOL_T *pool = malloc(size);
    if (!pool) {
        return NULL;
    }

    // Initialize the pool structure and its block array
    memset(pool, 0, size);
    pool->num_blocks = num_blocks;

    return pool;
}

// Define a function to free an existing memory pool
void memory_pool_free(MEMORY_POOL_T *pool) {
    // Free the pool structure and its block array
    free(pool);
}

// Define a function to allocate a new memory block from the pool
void* memory_block_alloc(MEMORY_POOL_T *pool) {
    if (!pool || !pool->num_blocks) {
        return NULL;
    }

    // Allocate a new memory block from the pool
    size_t index = pool->num_blocks - 1;
    void *block = pool->blocks[index];
    if (block) {
        pool->blocks[index] = NULL;
    } else {
        // If there are no available blocks, allocate a new one using malloc()
        block = malloc(sizeof(void*));
        if (!block) {
            return NULL;
        }
    }

    return block;
}

// Define a function to free an existing memory block back to the pool
bool memory_block_free(MEMORY_POOL_T *pool, void *block) {
    if (!pool || !pool->num_blocks) {
        return false;
    }

    // Find the index of the given block in the pool's block array
    size_t index = 0;
    for (; index < pool->num_blocks; ++index) {
        if (pool->blocks[index] == block) {
            break;
        }
    }

    // If the block is found in the pool, free it and return true
    if (index < pool->num_blocks) {
        pool->blocks[index] = NULL;
        free(block);
        return true;
    }

    // Otherwise, return false
    return false;
}

