    if (customer_id < 0 || customer_id > 100000) {
        return;
    }

    // Acquire the mutex for protecting the hash map
    pthread_mutex_lock(&customer_id_map);

    // Remove the customer ID from the hash map
    for (int i = 0; i < CUSTOMER_ID_MAP_SIZE; i++) {
        if (customer_id_map[i] == customer_id) {
            customer_id_map[i] = 0;
            break;
        }
    }

    // Release the mutex for protecting the hash map
    pthread_mutex_unlock(&customer_id_map);
}
