    int lower_bound;
    int upper_bound;
    char* log_file_path;
};

// Initialize config struct from file
void init_config(const char* filename, struct Config* config) {
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: failed to open configuration file.\n");
        exit(1);
    }

    // Read max_entries and lower_bound from file
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "max_entries", 11) == 0) {
            config->max_entries = atoi(line + 11);
        } else if (strncmp(line, "lower_bound", 11) == 0) {
            config->lower_bound = atoi(line + 11);
        } else if (strncmp(line, "upper_bound", 12) == 0) {
            config->upper_bound = atoi(line + 12);
        } else if (strncmp(line, "log_file_path", 13) == 0) {
            config->log_file_path = strdup(line + 13);
        }
    }

    // Validate config struct and fall back to default values
    if (config->max_entries > 10000 || config->max_entries <= 0) {
        printf("Error: max_entries must be between 0 and 10,000.\n");
        exit(1);
    }
    if (config->lower_bound >= config->upper_bound) {
        printf("Error: lower_bound must be less than upper_bound.\n");
        exit(1);
    }
    if (config->log_file_path == NULL) {
        printf("Error: log_file_path must be specified.\n");
        exit(1);
    }
}

// Compute median value in array
double compute_median(int* arr, int n) {
    // Sort array in ascending order
    qsort(arr, n, sizeof(int), compare_ints);

    // Return median value
    if (n % 2 == 0) {
        return (arr[n / 2 - 1] + arr[n / 2]) / 2.0;
    } else {
        return arr[n / 2];
    }
}

// Generate random numbers within specified range using external library
void generate_random(int* arr, int n) {
    // Initialize PRNG with time seed
    srand(time(NULL));

    // Fill array with random values
    for (int i = 0; i < n; ++i) {
        arr[i] = rand() % (config.upper_bound - config.lower_bound + 1) + config.lower_bound;
    }
}

// Count disjoint pairs of elements using Union-F algorithm
int count_disjoint_pairs(int* arr, int n) {
    // Initialize Union-F structure
    struct UnionFind uf = init_union_find(n);

    // Iterate over array and perform Union-Find operations
    for (int i = 0; i < n; ++i) {
        int root1 = find(uf, arr[i]);
        for (int j = i + 1; j < n; ++j) {
            if (arr[i] != arr[j]) {
                int root2 = find(uf, arr[j]);
                if (root1 != root2) {
                    union(uf, root1, root2);
                }
            }
        }
    }

    // Return number of disjoint pairs
    return uf.count;
}

// Thread-safe implementation of Union-Find algorithm
struct UnionFind {
    int* parent;
    int* rank;
    int count;
};

struct UnionFind init_union_find(int n) {
    struct UnionFind uf = {malloc(n * sizeof(int)), malloc(n * sizeof(int)), n};
    for (int i = 0; i < n; ++i) {
        uf.parent[i] = i;
        uf.rank[i] = 1;
    }
    return uf;
}

int find(struct UnionFind uf, int x) {
    if (uf.parent[x] == x) {
        return x;
    } else {
        uf.parent[x] = find(uf, uf.parent[x]);
        return uf.parent[x];
    }
}

void union(struct UnionFind uf, int root1, int root2) {
    if (root1 == root2) {
        return;
    }
    if (uf.rank[root1] > uf.rank[root2]) {
        uf.parent[root2] = root1;
    } else if (uf.rank[root1] < uf.rank[root2]) {
        uf.parent[root1] = root2;
    } else {
        uf.parent[root1] = root2;
        uf.rank[root2]++;
    }
    uf.count--;
}

// Release all allocated memory upon completion
void cleanup(struct Config* config, int** arr_ptr) {
    free(config->log_file_path);
    free(*arr_ptr);
    free(uf.parent);
    free(uf.rank);
}

int main() {
    struct Config config = init_config();
    int* arr;

    // Initialize array with random values
    generate_random(&arr, config.n);

    // Compute median value and count disjoint pairs
    double median = compute_median(arr, config.n);
    int disjoint_pairs = count_disjoint_pairs(arr, config.n);

    // Print results to log file
    FILE* fp = fopen(config.log_file_path, "w");
    fprintf(fp, "Median: %lf\n", median);
    fprintf(fp, "Disjoint Pairs: %d\n", disjoint_pairs);
    fclose(fp);

    // Cleanup memory
    cleanup(&config, &arr);

    return 0;
}
```

This is a longer code example that demonstrates how to use the Union-Find algorithm to count disjoint pairs of elements in an array. The code first initializes the Union-Find structure using the `init_union_find` function, and then iterates over the array and performs Union-Find operations using the `find` and `union` functions. Finally, it prints the results to a log file using the `fprintf` function and releases all allocated memory using the `cleanup` function.']

