// Function to process an integer list from either standard input or a binary file
void processIntegerList(const char* filename, int range) {
    // Variable to store the total number of integers processed
    int num_integers = 0;
    // Variable to store the largest integer in the array
    int largest_integer = 0;
    // Variable to store the current integer being processed
    int current_integer;

    // Check if the input file exists and is not empty
    if (filename != NULL && strlen(filename) > 0) {
        // Open the input file in binary mode
        FILE* fp = fopen(filename, "rb");
        if (fp == NULL) {
            // Handle file open error
            printf("Error opening file: %s\n", filename);
            return;
        }

        // Initialize the integer array with a size of MAX_ARRAY_SIZE bytes
        int* integers = malloc(MAX_ARRAY_SIZE);
        if (integers == NULL) {
            // Handle memory allocation error
            printf("Error allocating memory for integer array: %s\n", strerror(errno));
            fclose(fp);
            return;
        }

        // Read the integers from the file and store them in the integer array
        while (fread(&current_integer, sizeof(int), 1, fp) == 1) {
            if (num_integers < MAX_INTEGERS) {
                integers[num_integers++] = current_integer;
            } else {
                // Handle overflow error
                printf("Error: integer array is full. Cannot process any more integers.\n");
                break;
            }
        }

        // Close the input file
        fclose(fp);

        // Find and print the largest integer in the array
        if (num_integers > 0) {
            largest_integer = findLargestInteger(integers, num_integers);
            printf("Largest integer: %d\n", largest_integer);
        } else {
            printf("No integers to process.\n");
        }

        // Release the memory allocated for the integer array
        free(integers);
    } else {
        // Handle input file not found or empty error
        printf("Error: file not found or empty. Cannot process any integers.\n");
    }
}

// Helper function to find and print the largest integer in an array of integers
int findLargestInteger(int* integers, int num_integers) {
    // Initialize the largest integer as the first element in the array
    int largest_integer = integers[0];

    // Loop through each element in the array and compare it to the current largest integer
    for (int i = 1; i < num_integers; i++) {
        if (integers[i] > largest_integer) {
            largest_integer = integers[i];
        }
    }

    return largest_integer;
}

// Function to generate a random integer within the specified range
int generateRandomInteger(int range) {
    // Initialize a random number generator with the current time
    srand((unsigned int)time(NULL));

    // Generate a random integer between 0 and the range (inclusive of both ends)
    return rand() % range + 1;
}
