void add_long_offset(long offset) {
    // Add a long offset value to the array, ensuring bounds checking and overflow prevention
    pthread_mutex_lock(&mutex);
    if (long_offset[offset] != 0 || offset > MAX_LONG_OFFSET - 1) {
        printf("Overflow error: long offset %ld is out of range\n", offset);
        pthread_mutex_unlock(&mutex);
        return;
    }
    long_offset[offset] = offset;
    pthread_mutex_unlock(&mutex);
}

void add_int_key(int key) {
    // Add an int key to the array, ensuring bounds checking and overflow prevention
    pthread_mutex_lock(&mutex);
    if (int_keys[key] != 0 || key > MAX_INT_KEYS - 1) {
        printf("Overflow error: int key %d is out of range\n", key);
        pthread_mutex_unlock(&mutex);
        return;
    }
    int_keys[key] = key;
    pthread_mutex_unlock(&mutex);
}

void add_record(long offset, int key, char status, int value) {
    // Add a record to the array, ensuring bounds checking and overflow prevention
    pthread_mutex_lock(&mutex);
    if (records[offset].status != 0 || offset > MAX_RECORDS - 1) {
        printf("Overflow error: record %ld is out of range\n", offset);
        pthread_mutex_unlock(&mutex);
        return;
    }
    records[offset].offset = offset;
    records[offset].key = key;
    records[offset].status = status;
    records[offset].value = value;
    pthread_mutex_unlock(&mutex);
}

