        txo_size--;
    }
}

// Function to add a new RNTI value to the hash map
void add_rnti_to_hash_map(unsigned int rnti) {
    // Check if there are enough entries in the hash map
    if (hash_map_size == 0) {
        // Reallocate more memory for the hash map
        hash_map = realloc(hash_map, sizeof(unsigned int) * 1);
        hash_map[0] = rnti;
        hash_map_size++;
    } else {
        // Add the entry to the hash map
        hash_map[hash_map_size++] = rnti;
    }
}

// Function to remove an RNTI value from the hash map
void remove_rnti_from_hash_map(unsigned int rnti) {
    // Find the index of the entry in the hash map
    size_t index = 0;
    while (index < hash_map_size && hash_map[index] != rnti) {
        index++;
    }

    // If the entry is found, remove it from the hash map
    if (index < hash_map_size) {
        memmove(&hash_map[index], &hash_map[index + 1], sizeof(unsigned int) * (hash_map_size - index));
        hash_map = realloc(hash_map, sizeof(unsigned int) * (hash_map_size - 1));
        hash_map_size--;
    }
}

// Function to check if a given RNTI value is in use
bool rnti_in_use(unsigned int rnti) {
    // Check if the RNTI is already in use in the hash map
    return (rnti_in_hash_map(rnti));
}

// Function to check if a given RNTI value is in the hash map
bool rnti_in_hash_map(unsigned int rnti) {
    // Check if there are enough entries in the hash map
    if (hash_map_size == 0) {
        return false;
    }

    // Check if the RNTI is already in the hash map
    size_t index = 0;
    while (index < hash_map_size && hash_map[index] != rnti) {
        index++;
    }

    return (index < hash_map_size);
}
