    reduceRecords(numRecords, records);

    for (int i = 0; i < numRecords; i++) {
        printf("%d: offsetValue=%ld, keyValue=%d, crcflag=%s\n", i, (*offsetValues)[i], (*keyValues)[i], (*records)[i]->crcflag ? "YES" : "NO");
    }

    return 0;
}
