// Structure to store the UE contexts and associated buffers
typedef struct ue_context {
    int tid;
    char* mac_pdu;
    void* sdu_buffer;
} ue_context_t;

// Global data structure to store all the UE contexts
static ue_context_t ue_contexts[MAX_NUM_UE_CONTEXTS];

// Lock for thread-safe access to the global data structure
static pthread_mutex_t ue_contexts_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate and initialize a new SDU buffer with a specified size
void* alloc_sdu_buffer(size_t size) {
    void* buf = malloc(size);
    if (!buf) {
        printf("Error: failed to allocate %zu bytes for SDU buffer\n", size);
        return NULL;
    }
    memset(buf, 0, size);
    return buf;
}

// Function to add a new UE context with a specified MAC control information (CI) field and TID
void add_ue_context(int tid, char* mac_pdu) {
    // Acquire the lock for thread-safe access to the global data structure
    pthread_mutex_lock(&ue_contexts_lock);

    // Check if there is space in the global data structure for a new UE context
    if (num_ue_contexts >= MAX_NUM_UE_CONTEXTS) {
        printf("Error: maximum number of UE contexts reached\n");
        pthread_mutex_unlock(&ue_contexts_lock);
        return;
    }

    // Allocate a new SDU buffer with the specified size
    void* sdu_buffer = alloc_sdu_buffer(SDU_BUFFER_SIZE);
    if (!sdu_buffer) {
        printf("Error: failed to allocate %zu bytes for SDU buffer\n", SDU_BUFFER_SIZE);
        pthread_mutex_unlock(&ue_contexts_lock);
        return;
    }

    // Initialize the new UE context with the specified MAC control information (CI) field and TID
    ue_context_t* new_context = &ue_contexts[num_ue_contexts++];
    new_context->tid = tid;
    memcpy(new_context->mac_pdu, mac_pdu, strlen(mac_pdu));
    new_context->sdu_buffer = sdu_buffer;

    // Release the lock for thread-safe access to the global data structure
    pthread_mutex_unlock(&ue_contexts_lock);
}

// Function to remove an existing UE context with a specified TID
void remove_ue_context(int tid) {
    // Acquire the lock for thread-safe access to the global data structure
    pthread_mutex_lock(&ue_contexts_lock);

    // Check if there is an existing UE context with the specified TID
    int i;
    for (i = 0; i < num_ue_contexts; i++) {
        ue_context_t* current_context = &ue_contexts[i];
        if (current_context->tid == tid) {
            break;
        }
    }

    // If there is no such UE context, exit the function
    if (i >= num_ue_contexts) {
        printf("Error: no existing UE context with TID %d\n", tid);
        pthread_mutex_unlock(&ue_contexts_lock);
        return;
    }

    // Deallocate the SDU buffer associated with the UE context
    free(current_context->sdu_buffer);

    // Update the global data structure to remove the existing UE context
    int j = i + 1;
    while (j < num_ue_contexts) {
        ue_context_t* current_context = &ue_contexts[j];
        memcpy(&ue_contexts[i], current_context, sizeof(ue_context_t));
        i++;
        j++;
    }
    num_ue_contexts--;

    // Release the lock for thread-safe access to the global data structure
    pthread_mutex_unlock(&ue_contexts_lock);
}

// Function to dynamically manage UE contexts and allocate/deallocate SDU buffers as needed
void manage_ue_contexts() {
    // Acquire the lock for thread-safe access to the global data structure
    pthread_mutex_lock(&ue_contexts_lock);

    // Check if there are any new UE contexts that need to be added or removed
    for (int i = 0; i < num_ue_contexts; i++) {
        ue_context_t* current_context = &ue_contexts[i];

        // If the SDU buffer is full, deallocate it and add a new one with double the size
        if (current_context->sdu_buffer_size >= 2 * SDU_BUFFER_SIZE) {
            free(current_context->sdu_buffer);
            current_context->sdu_buffer = alloc_sdu_buffer(2 * SDU_BUFFER_SIZE);
        }
    }

    // Release the lock for thread-safe access to the global data structure
    pthread_mutex_unlock(&ue_contexts_lock);
}

// Function to log any errors that occur during the management of UE contexts
void log_error(char* message) {
    printf("Error: %s\n", message);
}
