#define MAX_SENSORS 500
#define MIN_TEMP -100.0f
#define MAX_TEMP 100.0f
#define MIN_HUMIDITY 0
#define MAX_HUMIDITY 100
#define MIN_THRESHOLD -50.0f
#define MAX_THRESHOLD 50.0f
#define MIN_DEVICE_ID 1
#define MAX_DEVICE_ID 1000
#define MIN_LAST_UPDATED_TIMESTAMP 0
#define MAX_LAST_UPDATED_TIMESTAMP 9999999999
#define MIN_LOGGING_INTERVAL 1
#define MAX_LOGGING_INTERVAL 60
#define DEFAULT_LOGGING_INTERVAL 5
#define FEATURES_ENABLED 1
#define FEATURES_DISABLED 0

typedef struct SensorData {
    int timestamp;
    float temperature;
    int humidity;
    char **sensorIDs;
    char *uniqueSensorID;
} SensorData;

typedef struct DeviceStatus {
    int deviceID;
    unsigned short statusFlags;
    int lastUpdatedTimestamp;
    struct SensorID *sensorIDNode;
} DeviceStatus;

typedef struct SensorID {
    char *deviceID;
    float temperatureThreshold;
} SensorID;

typedef struct ConfigParams {
    float thresholdValues[2];
    int loggingInterval;
    unsigned short featuresEnabled;
} ConfigParams;

void *cache_memory(int n, size_t size) {
    void **mem = (void**)malloc(n * sizeof(void*));
    for (int i = 0; i < n; i++) {
        mem[i] = malloc(size);
    }
    return mem;
}

void cache_release(void *mem, int n) {
    void **cache = (void**)mem;
    for (int i = 0; i < n; i++) {
        free(cache[i]);
    }
    free(cache);
}

SensorData *create_sensor_data() {
    SensorData *data = malloc(sizeof(SensorData));
    data->timestamp = 0;
    data->temperature = 0.0f;
    data->humidity = 0;
    data->sensorIDs = NULL;
    data->uniqueSensorID = NULL;
    return data;
}

void destroy_sensor_data(SensorData *data) {
    free(data->sensorIDs);
    free(data->uniqueSensorID);
    free(data);
}

DeviceStatus *create_device_status() {
    DeviceStatus *status = malloc(sizeof(DeviceStatus));
    status->deviceID = 0;
    status->statusFlags = 0;
    status->lastUpdatedTimestamp = 0;
    status->sensorIDNode = NULL;
    return status;
}

void destroy_device_status(DeviceStatus *status) {
    free(status);
}

SensorID *create_sensor_id() {
    SensorID *id = malloc(sizeof(SensorID));
    id->deviceID = NULL;
    id->temperatureThreshold = 0.0f;
    return id;
}

void destroy_sensor_id(SensorID *id) {
    free(id);
}

ConfigParams *create_config_params() {
    ConfigParams *params = malloc(sizeof(ConfigParams));
    params->thresholdValues[0] = 0.0f;
    params->thresholdValues[1] = 0.0f;
    params->loggingInterval = DEFAULT_LOGGING_INTERVAL;
    params->featuresEnabled = FEATURES_ENABLED;
    return params;
}

void destroy_config_params(ConfigParams *params) {
    free(params);
}

int populate_sensor_data(SensorData *data, int n, float minTemp, float maxTemp, int minHumidity, int maxHumidity) {
    for (int i = 0; i < n; i++) {
        data[i].timestamp = time(NULL);
        data[i].temperature = ((float)rand() / RAND_MAX) * (maxTemp - minTemp) + minTemp;
        data[i].humidity = ((int)rand() % maxHumidity) + minHumidity;
    }
    return n;
}

void populate_device_status(DeviceStatus *status, int deviceID, unsigned short statusFlags, float temperatureThreshold) {
    status->deviceID = deviceID;
    status->statusFlags = statusFlags;
    status->temperatureThreshold = temperatureThreshold;
}

SensorID *create_sensor_id(int deviceID, float temperatureThreshold) {
    SensorID *id = malloc(sizeof(SensorID));
    id->deviceID = malloc(sizeof(char*) * 64);
    sprintf(id->deviceID, "%d", deviceID);
    id->temperatureThreshold = temperatureThreshold;
    return id;
}

void destroy_sensor_id(SensorID *id) {
    free(id->deviceID);
    free(id);
}

int populate_hash_table(SensorID **hashTable, int n) {
    for (int i = 0; i < n; i++) {
        hashTable[i] = create_sensor_id();
    }
    return n;
}

void release_hash_table(SensorID **hashTable, int n) {
    for (int i = 0; i < n; i++) {
        destroy_sensor_id(hashTable[i]);
    }
    free(hashTable);
}

void populate_config_params(ConfigParams *params, float thresholdValues[2], int loggingInterval, unsigned short featuresEnabled) {
    params->thresholdValues[0] = thresholdValues[0];
    params->thresholdValues[1] = thresholdValues[1];
    params->loggingInterval = loggingInterval;
    params->featuresEnabled = featuresEnabled;
}

void destroy_config_params(ConfigParams *params) {
    free(params);
}

int main() {
    int n = 5; // number of sensors
    float minTemp = 20.0f, maxTemp = 30.0f; // temperature range
    int minHumidity = 40, maxHumidity = 60; // humidity range
    SensorData *data = cache_memory(n, sizeof(SensorData));
    populate_sensor_data(data, n, minTemp, maxTemp, minHumidity, maxHumidity);
    DeviceStatus **statuses = (DeviceStatus**)cache_memory(n, sizeof(DeviceStatus*));
    for (int i = 0; i < n; i++) {
        statuses[i] = create_device_status();
    }
    SensorID **hashTable = cache_memory(n, sizeof(SensorID*));
    populate_hash_table(hashTable, n);
    ConfigParams *params = create_config_params();
    float thresholdValues[2] = {30.0f, 35.0f}; // temperature thresholds
    int loggingInterval = DEFAULT_LOGGING_INTERVAL; // logging interval
    unsigned short featuresEnabled = FEATURES_ENABLED; // enabled features
    populate_config_params(params, thresholdValues, loggingInterval, featuresEnabled);
    for (int i = 0; i < n; i++) {
        printf("Sensor %d: temperature = %.2f, humidity = %d\n", data[i].timestamp, data[i].temperature, data[i].humidity);
        populate_device_status(statuses[i], hashTable[i]->deviceID, statuses[i]->temperatureThreshold, thresholdValues[0]);
    }
    release_hash_table(hashTable, n);
    destroy_sensor_data(data);
    for (int i = 0; i < n; i++) {
        destroy_device_status(statuses[i]);
    }
    free(statuses);
    destroy_config_params(params);
    return 0;
}
