typedef struct {
    int count;
    nfapi_crc_indication_pdu_t* entries;
} nfapi_crc_indication_list_t;

void nfapi_crc_indication_list_init(nfapi_crc_indication_list_t* list) {
    list->count = 0;
    list->entries = NULL;
}

int nfapi_crc_indication_list_add(nfapi_crc_indication_list_t* list, int rx_ue_information_tag, uint16_t rnti, nfapi_crc_indication_rel8_t crc_indication_rel8) {
    // Check for duplicate RNTI
    if (nfapi_crc_indication_list_find(list, rnti)) {
        return 0;
    }

    // Allocate memory for new entry
    nfapi_crc_indication_pdu_t* new_entry = (nfapi_crc_indication_pdu_t*)malloc(sizeof(nfapi_crc_indication_pdu_t));
    if (!new_entry) {
        return 0;
    }

    // Set fields of new entry
    new_entry->rx_ue_information_tag = rx_ue_information_tag;
    new_entry->rnti = rnti;
    new_entry->crc_indication_rel8 = crc_indication_rel8;

    // Add new entry to list
    if (!list->entries) {
        list->entries = (nfapi_crc_indication_pdu_t*)malloc(sizeof(nfapi_crc_indication_pdu_t));
        if (!list->entries) {
            free(new_entry);
            return 0;
        }
    } else {
        nfapi_crc_indication_pdu_t* temp = (nfapi_crc_indication_pdu_t*)realloc(list->entries, sizeof(nfapi_crc_indication_pdu_t) * (list->count + 1));
        if (!temp) {
            free(new_entry);
            return 0;
        }
        list->entries = temp;
    }
    list->entries[list->count] = new_entry;
    list->count++;

    return 1;
}

void nfapi_crc_indication_list_remove(nfapi_crc_indication_list_t* list, uint16_t rnti) {
    // Find entry to remove
    int index = -1;
    for (int i = 0; i < list->count; i++) {
        if (list->entries[i]->rnti == rnti) {
            index = i;
            break;
        }
    }

    // Remove entry from list
    if (index >= 0) {
        nfapi_crc_indication_pdu_t* removed_entry = list->entries[index];
        free(removed_entry);
        for (int i = index; i < list->count - 1; i++) {
            list->entries[i] = list->entries[i + 1];
        }
        list->count--;
    }
}

nfapi_crc_indication_pdu_t* nfapi_crc_indication_list_find(nfapi_crc_indication_list_t* list, uint16_t rnti) {
    for (int i = 0; i < list->count; i++) {
        if (list->entries[i]->rnti == rnti) {
            return list->entries[i];
        }
    }
    return NULL;
}

void nfapi_crc_indication_list_clear(nfapi_crc_indication_list_t* list) {
    for (int i = 0; i < list->count; i++) {
        free(list->entries[i]);
    }
    free(list->entries);
    list->count = 0;
}
