// function to read and validate user input
int read_and_validate_input(char* input, int size) {
  if (size > MAX_INPUT_SIZE || strlen(input) > size) {
    printf("Error: Input must be within %d integers.\n", MAX_INPUT_SIZE);
    return -1;
  }

  // check for invalid characters and convert to int
  int i = 0;
  while (i < strlen(input)) {
    if (!isdigit(input[i]) || input[i] > INT_MAX_VALUE) {
      printf("Error: Invalid character in input.\n");
      return -1;
    }
    i++;
  }
  return atoi(input);
}

// function to calculate sum of integers and check for overflow
int calculate_sum(int* arr, int size) {
  int sum = 0;
  for (int i = 0; i < size; i++) {
    if ((sum + arr[i]) > INT_MAX_VALUE) {
      printf("Error: Integer overflow.\n");
      return -1;
    }
    sum += arr[i];
  }
  return sum;
}

// function to find largest integer in array and print it
void print_largest(int* arr, int size) {
  int max = INT_MIN_VALUE; // initialize with minimum value of int type
  for (int i = 0; i < size; i++) {
    if (arr[i] > max) {
      max = arr[i];
    }
  }
  printf("Largest integer: %d\n", max);
}

// function to find median value in array and print it
void print_median(int* arr, int size) {
  if (size % 2 == 0) { // even-sized array
    int med = (arr[size / 2 - 1] + arr[size / 2]) / 2;
    printf("Median integer: %d\n", med);
  } else { // odd-sized array
    int med = arr[size / 2];
    printf("Median integer: %d\n", med);
  }
}

// function to find and print the largest and median values in an array
void process_and_randomize_integers(int* arr, int size) {
  // check for duplicate values and handle appropriately
  if (size > MAX_DUPLICATES) {
    printf("Error: Too many duplicate values.\n");
    return;
  } else if (size == 0) {
    printf("Error: No input provided.\n");
    return;
  }

  // calculate sum of integers and check for overflow
  int sum = calculate_sum(arr, size);
  if (sum < 0) {
    printf("Error: Integer overflow.\n");
    return;
  }

  // find largest integer in array and print it
  print_largest(arr, size);

  // find median value in array and print it
  print_median(arr, size);

  // randomize integers using a custom allocator for efficient memory usage
  int* rand_arr = (int*)my_custom_allocator.allocate(size * sizeof(int));
  if (!rand_arr) {
    printf("Error: Memory allocation failed.\n");
    return;
  }

  // set random values for each integer in the array, handling overlap with original values
  for (int i = 0; i < size; i++) {
    if (!RANDOM_PRIMES || !is_prime(arr[i])) {
      rand_arr[i] = get_random(RANGE_MIN, RANGE_MAX);
    } else {
      rand_arr[i] = arr[i]; // keep prime values as is
    }
  }

  // free memory allocated for random integers
  my_custom_allocator.deallocate(rand_arr, size * sizeof(int));
}

// function to generate random integers within a specified range
int get_random(int min, int max) {
  srand((unsigned)time(NULL)); // seed with current time for unpredictable results
  return (rand() % (max - min + 1)) + min;
}

// function to check if an integer is prime
bool is_prime(int n) {
  if (n <= 1 || n == 2) {
    return false;
  } else if (n % 2 == 0 && n != 2) {
    return true; // even numbers except 2 are prime
  } else {
    for (int i = 3; i * i <= n; i += 2) {
      if (n % i == 0) {
        return false; // not prime if divisible by any number between 3 and sqrt(n)
      }
    }
  }
  return true; // prime if no factors other than itself found
}
