// Function to initialize a new device instance
void initDeviceInstance(DeviceInstance *instance, const char *interface_name) {
    // Initialize the interface name and buffer size
    instance->interface_name = strdup(interface_name);
    instance->buffer_size = BUFFER_SIZE;

    // Allocate memory for the buffer
    instance->buffer = (unsigned char *) malloc(instance->buffer_size);
    if (instance->buffer == NULL) {
        perror("Failed to allocate memory for device instance");
        exit(1);
    }
}

