void addDeviceInstance(const char *interface_name) {
    // Check if the interface name already exists in the registry
    if (deviceRegistryContains(interface_name)) {
        return;
    }

    // Allocate memory for the new device instance
    DeviceInstance *instance = (DeviceInstance *) malloc(sizeof(DeviceInstance));
    if (instance == NULL) {
        perror("Failed to allocate memory for new device instance");
