// Struct to represent a cache configuration
typedef struct {
    int size;      // Size of the cache in bytes
    int ttl;       // Time-to-live value for cached items
    char* eviction; // Eviction policy (e.g., "LRU", "LFU")
} CacheConfig;

// Function to parse and validate a configuration file
CacheConfig parse_config(char* filename) {
    FILE* config = fopen(filename, "r");
    if (!config) {
        perror("Error opening configuration file");
        exit(EXIT_FAILURE);
    }

    // Read the cache size and TTL values from the configuration file
    char line[1024];
    while (fgets(line, sizeof(line), config)) {
        if (!strncmp(line, "CacheSize", 9) && line[10] == '=') {
            // Parse the cache size and validate it against the operational constraints
            char* endptr;
            int size = strtol(line + 11, &endptr, 10);
            if (size <= 0 || size > INT_MAX) {
                fprintf(stderr, "Error: cache size must be a positive integer\n");
                exit(EXIT_FAILURE);
            } else if ((size % PAGESIZE) != 0) {
                // Round up the cache size to the nearest page boundary
                size = round_up(size, PAGESIZE);
            }
            return (CacheConfig){size, DEFAULT_TTL, "LRU"};
        } else if (!strncmp(line, "TTL", 3) && line[4] == '=') {
            // Parse the TTL value and validate it against the operational constraints
            char* endptr;
            int ttl = strtol(line + 5, &endptr, 10);
            if (ttl < 0 || ttl > INT_MAX) {
                fprintf(stderr, "Error: TTL value must be non-negative\n");
                exit(EXIT_FAILURE);
            } else if (ttl > DEFAULT_TTL) {
                fprintf(stderr, "Warning: TTL value is larger than the default value\n");
                ttl = DEFAULT_TTL;
            }
            return (CacheConfig){DEFAULT_CACHE_SIZE, ttl, "LRU"};
        } else if (!strncmp(line, "EvictionPolicy", 13) && line[14] == '=') {
            // Parse the eviction policy and validate it against the supported policies
            char* policy = strchr(line + 15, '\'');
            if (policy) {
                if (!strncmp(policy + 1, "LRU", 3)) {
                    return (CacheConfig){DEFAULT_CACHE_SIZE, DEFAULT_TTL, "LRU"};
                } else if (!strncmp(policy + 1, "LFU", 3)) {
                    return (CacheConfig){DEFAULT_CACHE_SIZE, DEFAULT_TTL, "LFU"};
                } else {
                    fprintf(stderr, "Error: unsupported eviction policy\n");
                    exit(EXIT_FAILURE);
                }
            }
        }
    }

    // If no configuration is found, use the default values
    return (CacheConfig){DEFAULT_CACHE_SIZE, DEFAULT_TTL, "LRU"};
}
