// Struct to represent a cache item
typedef struct {
    void* data;      // Pointer to the cached data
    int size;        // Size of the cached data in bytes
    char* metadata;  // Metadata for the cached item (e.g., timestamps and access counts)
} CacheItem;

// Function to dynamically allocate memory for a cache buffer
CacheItem* alloc_cache_buffer(int size) {
    // Allocate memory for the cache buffer
    CacheItem* buffer = malloc(size);
    if (!buffer) {
        perror("Error allocating memory for cache buffer");
        exit(EXIT_FAILURE);
    }

    // Initialize the cache buffer with metadata and empty data
    for (int i = 0; i < size / sizeof(CacheItem); i++) {
        buffer[i].data = NULL;
        buffer[i].size = 0;
        buffer[i].metadata = malloc(sizeof(char) * 128);
        if (!buffer[i].metadata) {
            perror("Error allocating memory for cache metadata");
            exit(EXIT_FAILURE);
        }
    }

    return buffer;
}

// Function to free the memory allocated for a cache buffer
void free_cache_buffer(CacheItem* buffer) {
    // Free the memory allocated for the cache buffer and metadata
    for (int i = 0; i < size / sizeof(CacheItem); i++) {
        free(buffer[i].metadata);
    }
    free(buffer);
}
