3. Data Fetch and Caching:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <math.h>

// Struct to represent a cache
typedef struct {
    CacheItem* buffer;  // The cache buffer
    int size;           // The total size of the cache in bytes
    int capacity;       // The maximum number of items that can be cached
} Cache;

// Function to initialize a cache
Cache init_cache(int capacity) {
    // Calculate the total size of the cache based on the requested capacity
    int size = PAGESIZE * ((capacity + 1) / 2);

    // Allocate memory for the cache buffer
    CacheItem* buffer = alloc_cache_buffer(size);

    return (Cache){buffer, size, capacity};
}

// Function to free the memory allocated for a cache
void free_cache(Cache cache) {
    // Free the memory allocated for the cache buffer and metadata
    free_cache_buffer(cache.buffer);
}

// Function to fetch data from a cache and add it if necessary
void* fetch(Cache cache, void* data, int size) {
    // Check if the data is already cached
    for (int i = 0; i < cache.capacity; i++) {
        if (cache.buffer[i].data == data && cache.buffer[i].size == size) {
            return &cache.buffer[i];
        }
    }

    // If the data is not cached, add it to the cache buffer
    int index = cache.capacity - 1;
    while (index >= 0 && cache.buffer[index].size > size) {
        cache.buffer[index] = NULL;
        --index;
    }
    if (index < 0 || cache.buffer[index].data == data) {
        fprintf(stderr, "Error: cache is full\n");
        exit(EXIT_FAILURE);
    } else {
        cache.buffer[index] = (CacheItem){data, size};
    }

    return &cache.buffer[index];
}
