#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <assert.h>
#include <stdbool.h>
#include <pthread.h>

// Define the entry struct
typedef struct Entry {
    char* string;
    unsigned int index;
} Entry;

// Define the bucket struct
typedef struct Bucket {
    LinkedList* entries; // Pointer to a linked list of entries
} Bucket;

// Define the memory pool
typedef struct StringPool {
    char** strings; // Array of pointers to allocated strings
    size_t capacity; // Capacity of the string pool
    size_t size; // Current number of strings in the pool
} StringPool;

// Initialize the memory pool with a given capacity
void init_string_pool(StringPool* pool, size_t capacity) {
    assert(pool != NULL);
    pool->strings = malloc(capacity * sizeof(char*));
    if (pool->strings == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for string pool.\n");
        exit(EXIT_FAILURE);
    }
    pool->capacity = capacity;
    pool->size = 0;
}

// Allocate a new string from the memory pool and return its pointer
char* alloc_string(StringPool* pool, size_t length) {
    assert(pool != NULL);
    if (pool->size == pool->capacity) {
        fprintf(stderr, "Error: String pool is full.\n");
        exit(EXIT_FAILURE);
    }
    char* string = malloc(length + 1); // Allocate memory for the string
    if (string == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for new string.\n");
        exit(EXIT_FAILURE);
    }
    pool->strings[pool->size++] = string; // Add the string to the pool
    return string;
}

// Initialize a hash table with a given number of buckets
void init_hash_table(Bucket* buckets, size_t num_buckets) {
    assert(buckets != NULL);
    for (size_t i = 0; i < num_buckets; i++) {
        buckets[i].entries = malloc(sizeof(LinkedList)); // Allocate memory for the linked list
        if (buckets[i].entries == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for bucket %zu.\n", i);
            exit(EXIT_FAILURE);
        }
    }
}

// Add a new entry to the hash table
void add_entry(Bucket* buckets, size_t num_buckets, Entry* entry) {
    assert(buckets != NULL && entry != NULL);
    size_t bucket = entry->index % num_buckets; // Calculate the bucket for the entry
    LinkedListNode* node = malloc(sizeof(LinkedListNode)); // Allocate memory for the linked list node
    if (node == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for new node.\n");
        exit(EXIT_FAILURE);
    }
    node->data = entry; // Set the data for the linked list node
    node->next = buckets[bucket].entries; // Add the node to the linked list
    buckets[bucket].entries = node; // Update the head of the linked list
}

// Look up an entry in the hash table by its index
Entry* lookup_entry(Bucket* buckets, size_t num_buckets, unsigned int index) {
    assert(buckets != NULL);
    size_t bucket = index % num_buckets; // Calculate the bucket for the entry
    LinkedListNode* node = buckets[bucket].entries; // Get the head of the linked list
    while (node != NULL && node->data->index != index) {
        node = node->next; // Move to the next node
    }
    if (node == NULL) {
        return NULL; // Return NULL if no entry was found
    } else {
        return node->data; // Return the data of the found entry
    }
}

// Free all allocated resources
void cleanup(Bucket* buckets, size_t num_buckets, StringPool* pool) {
    assert(buckets != NULL && pool != NULL);
    for (size_t i = 0; i < num_buckets; i++) {
        LinkedListNode* node = buckets[i].entries; // Get the head of the linked list
        while (node != NULL) {
            Entry* entry = node->data; // Get the data of the current node
            free(entry); // Free the entry's memory
            node = node->next; // Move to the next node
        }
    }
    for (size_t i = 0; i < pool->capacity; i++) {
        free(pool->strings[i]); // Free each string in the pool
    }
    free(buckets); // Free the memory for the buckets
    free(pool->strings); // Free the memory for the string pool
    free(pool); // Free the memory for the pool
}

int main() {
    // Initialize the hash table with 1024 buckets
    Bucket* buckets = malloc(1024 * sizeof(Bucket));
    if (buckets == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for hash table.\n");
        exit(EXIT_FAILURE);
    }
    init_hash_table(buckets, 1024);

    // Initialize the string pool with a capacity of 1024 strings
    StringPool* pool = malloc(sizeof(StringPool));
    if (pool == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for string pool.\n");
        exit(EXIT_FAILURE);
    }
    init_string_pool(pool, 1024);

    // Generate and add entries to the hash table
    srand(time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < 1000; i++) {
        Entry* entry = malloc(sizeof(Entry)); // Allocate memory for the entry
        if (entry == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for new entry.\n");
            exit(EXIT_FAILURE);
        }
        char* string = alloc_string(pool, 10); // Allocate a random string from the pool
        if (string == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for new string.\n");
            exit(EXIT_FAILURE);
        }
        entry->string = string; // Set the entry's string
        entry->index = rand() % 1024; // Set the entry's index
        add_entry(buckets, 1024, entry); // Add the entry to the hash table
    }

    // Look up an entry by its index
    Entry* entry = lookup_entry(buckets, 1024, 512);
    if (entry == NULL) {
        printf("No entry found with index 512.\n");
    } else {
        printf("Entry found with index 512: %s\n", entry->string);
    }

    // Free all allocated resources
    cleanup(buckets, 1024, pool);

    return 0;
}
