#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

typedef struct Record {
    int key;
    char* string_key;
    int value;
} Record;

// Opaque data structure containing pointers to all arrays and the count of successfully initialized records
typedef struct {
    size_t count;
    Record** records;
} MemoryManager;

MemoryManager init_array(size_t initial_capacity) {
    // Allocate memory for the array of records
    Record* records = (Record*)malloc(initial_capacity * sizeof(Record));
    if (!records) {
        printf("Error: Out of memory\n");
        return NULL;
    }

    MemoryManager manager = {0, records};

    // Initialize the array with empty records
    for (size_t i = 0; i < initial_capacity; ++i) {
        Record* record = &records[i];
        record->key = -1;
        record->string_key = NULL;
        record->value = -1;
    }

    return manager;
}

void add_record(MemoryManager* manager, int key, char* string_key, int value) {
    // Check if the array needs to be resized
    if (manager->count == manager->records->size) {
        size_t new_capacity = manager->records->size * 2;
        Record* new_records = (Record*)realloc(manager->records, new_capacity * sizeof(Record));
        if (!new_records) {
            printf("Error: Out of memory\n");
            return;
        }

        manager->records = new_records;
    }

    // Find a unique string key for the record
    while (true) {
        char* unique_key = generate_unique_key(string_key);
        if (!unique_key) {
            break;
        }

        Record* existing_record = find_record(manager, unique_key);
        if (!existing_record) {
            manager->records[manager->count].key = key;
            manager->records[manager->count].string_key = unique_key;
            manager->records[manager->count].value = value;
            ++manager->count;
            break;
        }
    }
}

void free_array(MemoryManager* manager) {
    // Free the memory allocated for the array of records
    for (size_t i = 0; i < manager->records->size; ++i) {
        Record* record = &manager->records[i];
        if (record->string_key) {
            free(record->string_key);
        }
    }

    free(manager->records);
}

char* generate_unique_key(const char* string_key) {
    // Generate a unique key for the record by appending a random integer to the end of the string
    int random_int = rand() % INT_MAX;
    size_t new_size = strlen(string_key) + 10;
    char* new_key = (char*)malloc(new_size);
    if (!new_key) {
        return NULL;
    }

    snprintf(new_key, new_size, "%s%d", string_key, random_int);
    return new_key;
}

Record* find_record(MemoryManager* manager, const char* key) {
    // Search for a record with the given string key in the array
    for (size_t i = 0; i < manager->count; ++i) {
        Record* record = &manager->records[i];
        if (!strcmp(record->string_key, key)) {
            return record;
        }
    }

    return NULL;
}
