    uint8_t crc_indication_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_nfapi_crc_indication(uint16_t num_elements) {
    // Allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (nfapi_crc_indication == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < num_elements; i++) {
        nfapi_crc_indication[i].rx_ue_information_tag = 0x1234;
        nfapi_crc_indication[i].rnti = rand() % (65536 - 1) + 1; // Generate random RNTI between 1 and 65535
        nfapi_crc_indication[i].crc_indication_rel8_tag = 0xAABB;
        nfapi_crc_indication[i].crcflag = rand() % 2; // Generate random CRCFLAG between 0 and 1
    }

    return nfapi_crc_indication;
}
