// Define the function to insert an entry into the hash table with efficient collision resolution strategies
void insert_entry(entry_t* new_entry, bucket_t** buckets) {
    // Declare and initialize variables
    int i;
    bool collision = false;
    entry_t* current_entry;

    // Loop through the hash table until a collision is detected or an empty slot is found
    for (i = 0; i < MAX_BUCKETS && !collision; ++i) {
        current_entry = buckets[i]->entries[buckets[i]->num_entries - 1];
        if (current_entry == NULL) {
            // Insert the new entry into the next available slot in the hash table
            buckets[i]->entries[buckets[i]->num_entries++] = new_entry;
        } else {
            // Check for a collision by comparing the hash values of the existing and new entries
            if (current_entry->hash == new_entry->hash) {
                collision = true;
            }
        }
    }
}

// Define the function to search for an entry in the hash table with efficient collision resolution strategies
void* search_entry(void* key, bucket_t** buckets) {
    // Declare and initialize variables
    int i;
    bool collision = false;
    entry_t* current_entry;
    void* found_key;

    // Loop through the hash table until a collision is detected or an empty slot is found
    for (i = 0; i < MAX_BUCKETS && !collision; ++i) {
        current_entry = buckets[i]->entries[buckets[i]->num_entries - 1];
        if (current_entry == NULL) {
            // No collision detected, return the value corresponding to the key
            found_key = current_entry->value;
        } else {
            // Check for a collision by comparing the hash values of the existing and new entries
            if (current_entry->hash == ((key_t*)key)->hash) {
                collision = true;
            }
        }
    }

    return found_key;
}
