    NFAPI_RRC_CU_MESSAGE* messages = malloc(sizeof(NFAPI_RRC_CU_MESSAGE) * num_messages);
    if (messages == NULL) {
        fprintf(stderr, "Failed to allocate memory for %d messages\n", num_messages);
        *num_errors = 1;
        return NULL;
    }

    // Populate the array of messages with random configuration parameter sets
    srand(time(NULL));
    int i;
    for (i = 0; i < num_messages; ++i) {
        int config_param_set = rand() % NUM_CONFIG_PARAMS;
        char* message = generate_message(config_param_sets[config_param_set]);
        if (message == NULL) {
            fprintf(stderr, "Failed to generate RRC Connection Reconfiguration message for configuration set %d\n", config_param_set);
            *num_errors = *num_errors + 1;
            continue;
        }
        messages[i].message = message;
    }

    // Return the populated array of messages
    return messages;
}

// Define the function to generate an RRC Connection Reconfiguration message for a given configuration parameter set
char* generate_message(int config_param_set) {
    // Check if the configuration parameter set is valid
    if (config_param_set < 1 || config_param_set > NUM_CONFIG_PARAMS) {
        fprintf(stderr, "Invalid configuration parameter set: %d\n", config_param_set);
        return NULL;
    }

    // Generate the RRC Connection Reconfiguration message
    char* message = malloc(sizeof(char) * (256 + 1)); // 256 is the maximum length of an RRC Connection Reconfiguration message
    if (message == NULL) {
        fprintf(stderr, "Failed to allocate memory for the RRC Connection Reconfiguration message\n");
        return NULL;
    }
    memset(message, 0, 256 + 1); // Zero-initialize the buffer

    // Generate the configuration parameter set and store it in the message
    char* config_param = generate_config_param(config_param_set);
    if (config_param == NULL) {
        fprintf(stderr, "Failed to generate the configuration parameter for configuration set %d\n", config_param_set);
        free(message);
        return NULL;
    }
    strncpy(message, config_param, 256); // Copy the configuration parameter to the message buffer

    // Return the generated RRC Connection Reconfiguration message
    return message;
}

// Define the function to generate a configuration parameter for a given configuration parameter set
char* generate_config_param(int config_param_set) {
    // Check if the configuration parameter set is valid
    if (config_param_set < 1 || config_param_set > NUM_CONFIG_PARAMS) {
        fprintf(stderr, "Invalid configuration parameter set: %d\n", config_param_set);
        return NULL;
    }

    // Generate the configuration parameter based on the specified set
