    if (config_param == NULL) {
        fprintf(stderr, "Failed to allocate memory for the configuration parameter\n");
        return NULL;
    }
    memset(config_param, 0, 256 + 1); // Zero-initialize the buffer

    // Generate the configuration parameter based on the specified set
    switch (config_param_set) {
        case 1:
            strcpy(config_param, "configuration_parameter_1");
