// Record structure definition
typedef struct {
    long offset;
    int key;
    double data_value;
    char* string_key;
} record;

// Hash table for storing records
static record* hash_table = NULL;

// Array to store the unique keys
static int* unique_keys = NULL;

// Number of records in the database
static int num_records = 0;

// Memory limit for the database
#define MEMORY_LIMIT (1024 * 1024 * 10) // 10 MB

// Function to dynamically allocate a new record
record* create_record(long offset, int key, double data_value, char* string_key) {
    record* new_record = malloc(sizeof(record));
    if (!new_record) {
        return NULL;
    }
    new_record->offset = offset;
    new_record->key = key;
    new_record->data_value = data_value;
    new_record->string_key = string_key;
    return new_record;
}

// Function to dynamically allocate a new string key for a record
char* create_string_key(int length) {
    char* new_key = malloc((length + 1) * sizeof(char));
    if (!new_key) {
        return NULL;
    }
    for (int i = 0; i < length + 1; ++i) {
        new_key[i] = 'A' + ((rand() % ('Z' - 'A' + 1)) + 'A'); // Generate a random string key with the specified length
    }
    return new_key;
}

// Function to add a record to the database
int add_record(long offset, int key, double data_value, char* string_key) {
    if (num_records == MEMORY_LIMIT / sizeof(record)) { // Check for memory limit reached
        return -1;
    }
    record* new_record = create_record(offset, key, data_value, string_key);
    if (!new_record) {
        return -2;
    }
    int index = hash_table[key % MEMORY_LIMIT]; // Calculate the index for the new record in the hash table
    while (hash_table[index].offset != 0) { // Check if a collision occurs
        index++;
    }
    hash_table[index] = *new_record; // Store the new record in the hash table
    unique_keys[key] = 1; // Mark the key as unique
    num_records++; // Increment the number of records in the database
    return 0;
}

// Function to remove a record from the database
int delete_record(int key) {
    if (num_records == 0) {
        return -1;
    }
    int index = hash_table[key % MEMORY_LIMIT]; // Calculate the index for the record in the hash table
    while (hash_table[index].offset != key) {
        index++;
        if (index == MEMORY_LIMIT) {
            return -2; // Record not found
        }
    }
    free(hash_table[index].string_key); // Free the string key of the record
    memset(&hash_table[index], 0, sizeof(record)); // Clear the memory for the record
    unique_keys[key] = 0; // Mark the key as non-unique
    num_records--; // Decrement the number of records in the database
    return 0;
}

// Function to retrieve a record from the database
record* get_record(int key) {
    if (num_records == 0) {
        return NULL;
    }
    int index = hash_table[key % MEMORY_LIMIT]; // Calculate the index for the record in the hash table
    while (hash_table[index].offset != key) {
        index++;
        if (index == MEMORY_LIMIT) {
            return NULL; // Record not found
        }
    }
    return &hash_table[index]; // Return a pointer to the record
}

// Function to check if a string key is unique
int is_unique(char* string_key) {
    for (int i = 0; i < num_records; ++i) { // Iterate through all records in the database
        int index = hash_table[i].offset % MEMORY_LIMIT; // Calculate the index for the record in the hash table
        while (hash_table[index].offset != 0) {
            if (!strcmp(string_key, hash_table[index].string_key)) { // Check if the string key is already used
                return 0;
            }
            index++;
            if (index == MEMORY_LIMIT) {
                break;
            }
        }
    }
    return 1; // String key is unique
}

// Function to generate a new string key for a record
char* generate_string_key(int length) {
    char* new_key = create_string_key(length);
    if (!new_key) {
        return NULL;
    }
    while (is_unique(new_key)) { // Check if the string key is unique
        free(new_key);
        new_key = create_string_key(length);
        if (!new_key) {
            return NULL;
        }
    }
    return new_key;
}

// Function to initialize the database
int init_database() {
    srand((unsigned int)time(NULL)); // Seed the random number generator
    hash_table = malloc(MEMORY_LIMIT * sizeof(record)); // Allocate memory for the hash table
    if (!hash_table) {
        return -1;
    }
    unique_keys = malloc(MEMORY_LIMIT * sizeof(int)); // Allocate memory for the unique keys array
    if (!unique_keys) {
        free(hash_table);
        return -2;
    }
    memset(hash_table, 0, MEMORY_LIMIT * sizeof(record)); // Clear the hash table and unique keys array
    num_records = 0; // Set the number of records to zero
    return 0;
}

// Function to destroy the database
int destroy_database() {
    if (hash_table) {
        free(hash_table);
    }
    if (unique_keys) {
        free(unique_keys);
    }
    hash_table = NULL;
    unique_keys = NULL;
    num_records = 0;
    return 0;
}
