size_t read_file(const char* filename, void** buf) {
    // Open the file in binary mode and check for errors
    FILE *f = fopen(filename, "rb");
    if (!f) {
        // Log the error and return an error code
        log_error("Error opening file: %s", strerror(errno));
        return FILE_READ_ERROR;
    }

    // Get the size of the file
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    rewind(f);

    // Allocate a buffer to read the file into
    *buf = malloc((size_t)size);
    if (*buf == NULL) {
        // Log an error and return an error code
        log_error("Error allocating memory for file contents");
        fclose(f);
        return FILE_READ_ERROR;
    }

    // Read the entire file into the buffer
    size_t nread = fread(*buf, 1, (size_t)size, f);
    if (nread < size) {
        log_error("Error reading file: %s", strerror(errno));
        free(*buf);
        *buf = NULL;
    }

    // Close the file and return the buffer
    fclose(f);
    return nread;
}

