int insert_record(struct array* arr, int key, const char* str_key, int value) {
    if (arr->count >= initial_size) {
        // Expand the record array if it is full
        size_t new_size = arr->count * 2;
        record** new_records = realloc(arr->records, new_size * sizeof(record*));
        if (!new_records) {
            fprintf(stderr, "Failed to allocate memory for expanded record array\n");
            return -1;
        }
        arr->records = new_records;
