    if (!new_record) {
        fprintf(stderr, "Failed to allocate memory for new record\n");
        return -1;
    }
    new_record->key = unique_key;
    new_record->str_key = strdup(str_key);
    new_record->value = value;
    arr->records[arr->count++] = new_record;

    return 0;
}

int generate_unique_key() {
    // Generate a random unique key
    int unique_key = rand();
    while (unique_key == 0) {
        unique_key = rand();
    }
    return unique_key;
}

void free_array(struct array* arr) {
    if (!arr) {
        return;
    }
    for (int i = 0; i < arr->count; ++i) {
        free(arr->records[i]->str_key);
        free(arr->records[i]);
    }
