typedef struct DataPacket {
    uint32_t SourceID;
    uint32_t DestinationID;
    char PacketPayload[100];
} DataPacket;

struct DataPacketArray {
    DataPacket *packets;
    size_t count;
    pthread_mutex_t mutex;
};

void initializeDataPacketArray(struct DataPacketArray *array) {
    array->packets = NULL;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

bool insertDataPacketIntoArray(struct DataPacketArray *array, DataPacket packet) {
    bool success = false;
    pthread_mutex_lock(&array->mutex);
    array->packets = realloc(array->packets, (array->count + 1) * sizeof(DataPacket));
    if (array->packets != NULL) {
        array->packets[array->count] = packet;
        array->count++;
        success = true;
    }
    pthread_mutex_unlock(&array->mutex);
    return success;
}

bool deleteDataPacketFromArray(struct DataPacketArray *array, uint32_t index) {
    bool success = false;
    pthread_mutex_lock(&array->mutex);
    if (index < array->count) {
        memmove(&array->packets[index], &array->packets[index + 1],
            sizeof(DataPacket) * (array->count - index));
        array->count--;
        success = true;
    }
    pthread_mutex_unlock(&array->mutex);
    return success;
