    nfapi_crc_indication_pdu_t *head;
    nfapi_crc_indication_pdu_t *tail;
} nfapi_crc_indication_list_t;

// Define a locking mechanism to protect the list from concurrent access
typedef struct {
    pthread_mutex_t mutex;
} nfapi_crc_indication_lock_t;

// Function to add an entry to the list
void nfapi_crc_indication_list_add(nfapi_crc_indication_list_t *list, int rx_ue_information_tag, unsigned long rnti, int crc_indication_rel8_tag, unsigned char crcflag, void *auxiliary_data) {
    // Validate the input parameters
    assert(list != NULL);
    assert(rnti != 0);
    assert(crc_indication_rel8_tag >= 0 && crc_indication_rel8_tag <= 255);
    assert(auxiliary_data != NULL);

    // Create a new entry in the list
    nfapi_crc_indication_pdu_t *entry = malloc(sizeof(nfapi_crc_indication_pdu_t));
    if (entry == NULL) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Initialize the entry with the input parameters
    entry->rx_ue_information_tag = rx_ue_information_tag;
    entry->rnti = rnti;
    entry->crc_indication_rel8_tag = crc_indication_rel8_tag;
    entry->crcflag = crcflag;
    entry->auxiliary_data = auxiliary_data;

    // Acquire the lock to protect the list from concurrent access
    nfapi_crc_indication_lock_t *lock = (nfapi_crc_indication_lock_t *) list->mutex;
    pthread_mutex_lock(&lock->mutex);

    // Add the entry to the end of the list
    if (list->tail != NULL) {
        list->tail->next = entry;
        list->tail = entry;
    } else {
        list->head = entry;
        list->tail = entry;
    }

    // Release the lock and return
    pthread_mutex_unlock(&lock->mutex);
}

// Function to remove an entry from the list based on RNTI
void nfapi_crc_indication_list_remove(nfapi_crc_indication_list_t *list, unsigned long rnti) {
    // Validate the input parameters
    assert(list != NULL);
    assert(rnti != 0);

    // Acquire the lock to protect the list from concurrent access
    nfapi_crc_indication_lock_t *lock = (nfapi_crc_indication_lock_t *) list->mutex;
    pthread_mutex_lock(&lock->mutex);

    // Iterate over the list to find the entry with the matching RNTI
    nfapi_crc_indication_pdu_t *entry = list->head;
    while (entry != NULL) {
        if (entry->rnti == rnti) {
            // Remove the entry from the list and release the lock
            if (entry->previous != NULL) {
                entry->previous->next = entry->next;
            } else {
                list->head = entry->next;
            }
            if (entry->next != NULL) {
                entry->next->previous = entry->previous;
            } else {
                list->tail = entry->previous;
            }
            free(entry);
            pthread_mutex_unlock(&lock->mutex);
            return;
        }
        entry = entry->next;
    }

    // If the RNTI was not found in the list, release the lock and print an error message
    printf("Error: RNTI %lu not found in the list\n", rnti);
    pthread_mutex_unlock(&lock->mutex);
}

// Function to iterate over the list
void nfapi_crc_indication_list_iterate(nfapi_crc_indication_list_t *list, void (*callback)(nfapi_crc_indication_pdu_t *)) {
    // Validate the input parameters
    assert(list != NULL);
    assert(callback != NULL);

    // Acquire the lock to protect the list from concurrent access
    nfapi_crc_indication_lock_t *lock = (nfapi_crc_indication_lock_t *) list->mutex;
    pthread_mutex_lock(&lock->mutex);

    // Iterate over the list and invoke the callback function for each entry
    nfapi_crc_indication_pdu_t *entry = list->head;
    while (entry != NULL) {
        (*callback)(entry);
        entry = entry->next;
    }

    // Release the lock and return
    pthread_mutex_unlock(&lock->mutex);
}

// Function to clear the list
void nfapi_crc_indication_list_clear(nfapi_crc_indication_list_t *list) {
    // Validate the input parameters
    assert(list != NULL);

    // Acquire the lock to protect the list from concurrent access
    nfapi_crc_indication_lock_t *lock = (nfapi_crc_indication_lock_t *) list->mutex;
    pthread_mutex_lock(&lock->mutex);

    // Iterate over the list and free each entry
    nfapi_crc_indication_pdu_t *entry = list->head;
    while (entry != NULL) {
        nfapi_crc_indication_pdu_t *next = entry->next;
        free(entry);
        entry = next;
    }

    // Reset the list and release the lock
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_unlock(&lock->mutex);
}

// Function to print the list
void nfapi_crc_indication_list_print(nfapi_crc_indication_list_t *list) {
    // Validate the input parameters
