// Structures for Task and Result
typedef struct {
    char *command;
    int priority;
    double time;
} Task;

typedef struct {
    int status_code;
    double timestamp;
} Result;

void manageTasks(Task **tasks, size_t *num_tasks) {
    // Initialize task list
    if (*tasks == NULL) {
        *tasks = malloc(sizeof(Task) * 10);
        *num_tasks = 10;
    }

    // Create a new task with random priority and current time
    Task *new_task = malloc(sizeof(Task));
    new_task->command = NULL;
    new_task->priority = rand() % 10 + 1;
    new_task->time = time(NULL);

    // Add task to list and update number of tasks
    (*tasks)[*num_tasks] = new_task;
    *num_tasks += 1;

    // Free memory if no longer needed
    if (*num_tasks > 20) {
        free(*tasks);
        *tasks = NULL;
        *num_tasks = 0;
    }
}

void executeTask(Task *task, Result *result) {
    // Execute the task and get result
    double start_time = time(NULL);
    int status_code = system(task->command);
    double end_time = time(NULL);

    // Assign result
    result->status_code = status_code;
    result->timestamp = (end_time - start_time) / 100.0;
}

int main() {
    Task *tasks = NULL;
    size_t num_tasks = 0;

    // Manage tasks and execute them
    while (1) {
        manageTasks(&tasks, &num_tasks);
        if (num_tasks > 0) {
            Result result;
            executeTask(tasks[num_tasks - 1], &result);
            printf("Status code: %d\n", result.status_code);
            printf("Time taken: %.2lf seconds\n", result.timestamp);
        }
    }

    // Free memory if needed
    if (tasks != NULL) {
        free(tasks);
        tasks = NULL;
    }

    return 0;
}
```
