    char response[BUFFER_SIZE];
    size_t filesize = 0;

    // Create a new curl handle and set the URL
    curl = curl_easy_init();
    if (curl) {
        // Set the HTTP OPTIONS method and URL
        curl_easy_setopt(curl, CURLOPT_URL, "http://example.com/list");
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, response);
        curl_easy_setopt(curl, CURLOPT_NOBODY, 1L);

        // Perform the HTTP OPTIONS request
        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Failed to list files: %s\n", curl_easy_strerror(res));
            return;
        }

        // Get the response size and data
        filesize = strlen(response);
        if (filesize > 0) {
            file_metadata_t *metadata = allocate_memory(filesize / sizeof(file_metadata_t));
            if (metadata == NULL) {
                perror("Failed to allocate memory for file metadata");
                return;
            }

            // Parse the response data and extract file names and sizes
            char *token = strtok(response, " ");
            int i = 0;
            while (token != NULL && i < filesize / sizeof(file_metadata_t)) {
                metadata[i].filename = token;
                token = strtok(NULL, " ");
                metadata[i].filesize = atoi(token);
                token = strtok(NULL, "\r\n");
                i++;
            }

            // Print the file names and sizes to stdout
            for (int j = 0; j < filesize / sizeof(file_metadata_t); j++) {
                printf("%s %lu\n", metadata[j].filename, metadata[j].filesize);
            }
        }
    }
}

// Main function to handle the input requests
