// Define data structures for the index
struct record {
    long id;
    char *key;
    float value;
    int metadata[2]; // for indexing purposes only
};

struct index {
    struct record **records;
    unsigned int size;
    unsigned int capacity;
    pthread_mutex_t mutex;
    unsigned long long hits;
    unsigned long long misses;
};

// Function to create a new index with the given capacity
struct index *index_create(unsigned int capacity) {
    struct index *idx = malloc(sizeof(struct index));
    idx->records = calloc(capacity, sizeof(struct record*));
    idx->size = 0;
    idx->capacity = capacity;
    pthread_mutex_init(&idx->mutex, NULL);
    return idx;
}

// Function to insert a new record into the index
int index_insert(struct index *idx, struct record *rec) {
    // Lock the mutex to avoid concurrent modifications
    pthread_mutex_lock(&idx->mutex);

    // Check if the record already exists in the index
    for (int i = 0; i < idx->size; i++) {
        struct record *cur = idx->records[i];
        if (strcmp(cur->key, rec->key) == 0 && cur->value == rec->value) {
            // If the record exists, update its metadata and unlock the mutex
            cur->metadata[0] = rec->metadata[0];
            cur->metadata[1] = rec->metadata[1];
            pthread_mutex_unlock(&idx->mutex);
            return 0;
        }
    }

    // If the record doesn't exist, insert it into the index
    if (idx->size == idx->capacity) {
        // If the index is full, double its capacity and reinsert all records
        idx->records = realloc(idx->records, 2 * idx->capacity * sizeof(struct record*));
        idx->capacity *= 2;
    }

    // Insert the new record into the index
    idx->records[idx->size++] = rec;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&idx->mutex);
    return 0;
}

// Function to delete a record from the index
int index_delete(struct index *idx, struct record *rec) {
    // Lock the mutex to avoid concurrent modifications
    pthread_mutex_lock(&idx->mutex);

    // Find the record in the index and remove it
    for (int i = 0; i < idx->size; i++) {
        struct record *cur = idx->records[i];
        if (strcmp(cur->key, rec->key) == 0 && cur->value == rec->value) {
            // Remove the record from the index
            memmove(idx->records + i, idx->records + i + 1, (idx->size - i - 1) * sizeof(struct record*));
            idx->size--;

            // If the index is 50% full or less, halve its capacity and compact the records
            if (idx->size < idx->capacity / 2) {
                idx->records = realloc(idx->records, idx->capacity / 2 * sizeof(struct record*));
                idx->capacity /= 2;
            }

            // Unlock the mutex and return success
            pthread_mutex_unlock(&idx->mutex);
            return 0;
        }
    }

    // If the record doesn't exist, unlock the mutex and return failure
    pthread_mutex_unlock(&idx->mutex);
    return -1;
}

// Function to search for a record in the index
struct record *index_search(struct index *idx, char *key) {
    // Lock the mutex to avoid concurrent modifications
    pthread_mutex_lock(&idx->mutex);

    // Search for the record in the index
    for (int i = 0; i < idx->size; i++) {
        struct record *cur = idx->records[i];
        if (strcmp(cur->key, key) == 0) {
            // Unlock the mutex and return the found record
            pthread_mutex_unlock(&idx->mutex);
            return cur;
        }
    }

    // If the record doesn't exist, unlock the mutex and return NULL
    pthread_mutex_unlock(&idx->mutex);
    return NULL;
}

// Function to update a record in the index
int index_update(struct index *idx, struct record *rec) {
    // Lock the mutex to avoid concurrent modifications
    pthread_mutex_lock(&idx->mutex);

    // Find the record in the index and update its metadata
    for (int i = 0; i < idx->size; i++) {
        struct record *cur = idx->records[i];
        if (strcmp(cur->key, rec->key) == 0 && cur->value == rec->value) {
            // Update the record's metadata and unlock the mutex
            cur->metadata[0] = rec->metadata[0];
            cur->metadata[1] = rec->metadata[1];
            pthread_mutex_unlock(&idx->mutex);
            return 0;
        }
    }

    // If the record doesn't exist, unlock the mutex and return failure
    pthread_mutex_unlock(&idx->mutex);
    return -1;
}

// Function to print the index statistics
void index_print_stats(struct index *idx) {
    // Lock the mutex to avoid concurrent modifications
    pthread_mutex_lock(&idx->mutex);

    // Print the number of records in the index and unlock the mutex
    printf("Index size: %d\n", idx->size);
    pthread_mutex_unlock(&idx->mutex);
}

// Function to print a record from the index
void index_print(struct index *idx, struct record *rec) {
    // Lock the mutex to avoid concurrent modifications
    pthread_mutex_lock(&idx->mutex);

    // Print the found record and unlock the mutex
    printf("Key: %s\nValue: %d\n", rec->key, rec->value);
    pthread_mutex_unlock(&idx->mutex);
}
