아래는 이전에 만들어진 `hashmap.c` 파일의 내용을 바탕으로 코드를 테스트하기 위한 코드를 추가한 것이다.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "hashmap.h"

int main() {
    // Create a new hash map with an initial size of 10 and a load factor of 2
    struct hashmap *hm = hashmap_new(10, 2);

    // Insert key-value pairs into the hash map
    hashmap_put(hm, "apple", 5);
    hashmap_put(hm, "banana", 6);
    hashmap_put(hm, "cherry", 7);

    // Search for a key in the hash map
    struct record *rec = hashmap_get(hm, "apple");
    printf("Value for 'apple': %d\n", rec->value);

    // Update a value in the hash map
    hashmap_put(hm, "banana", 8);
    printf("Updated value for 'banana': %d\n", rec->value);

    // Delete a key-value pair from the hash map
    hashmap_delete(hm, "cherry");

    // Search for a deleted key in the hash map
    rec = hashmap_get(hm, "cherry");
    if (rec == NULL) {
        printf("Deleted key 'cherry' not found\n");
    }

    // Print the statistics of the hash map
    hashmap_print_stats(hm);

    // Clean up
    hashmap_free(hm);
    return 0;
}
```

