typedef struct SYSTEM_PROCESS_INFO {
    pid_t process_id;
    PROCESS_STATUS_T status;
    time_t timestamp;
} SYSTEM_PROCESS_INFO;

int create_process(SYSTEM_PROCESS_INFO *info) {
    // Check if the allocated process ID has already been used in the current session
    if (is_used(info->process_id)) {
        // Generate a new process ID until a unique one is found
        while (true) {
            info->process_id = get_new_process_id();
            if (!is_used(info->process_id)) {
                break;
            }
        }
    }

    // Populate the structure with a random process status
    info->status = RANDOM_PROCESS_STATUS();

    // Save the timestamp for later reference
    info->timestamp = time(NULL);

    return 0;
}

int is_used(pid_t process_id) {
    // Implement a mechanism to handle memory leaks and ensure the function can scale to handle large values of N without significant performance degradation
    static pid_t *used_ids = NULL;
    if (used_ids == NULL) {
        used_ids = malloc(sizeof(pid_t) * 100);
        memset(used_ids, 0, sizeof(pid_t) * 100);
    }

    for (int i = 0; i < 100; ++i) {
        if (used_ids[i] == process_id) {
            return true;
        }
    }
    return false;
}

pid_t get_new_process_id() {
    // Implement a mechanism to handle memory leaks and ensure the function can scale to handle large values of N without significant performance degradation
    static pid_t current_id = 100;
    return current_id++;
}

int main() {
