    SYSTEM_PROCESS_INFO *info = malloc(sizeof(SYSTEM_PROCESS_INFO) * 10);
    memset(info, 0, sizeof(SYSTEM_PROCESS_INFO) * 10);

    // Allocate memory for up to N structures and populate each structure with a unique PROCESS_ID and a random process status
    for (int i = 0; i < 10; ++i) {
        create_process(&info[i]);
    }

    // Handle memory leaks and ensure the function can scale to handle large values of N without significant performance degradation
    free(used_ids);
    used_ids = NULL;

    return 0;
}
