#include <stdlib.h>
#include <string.h>
#include <assert.h>

struct Record {
    long offset;
    int key;
    int value;
};

struct List {
    struct Record* data;
    size_t capacity;
    size_t size;
};

struct List* createList(size_t initialCapacity) {
    struct List* list = malloc(sizeof(struct List));
    if (!list) {
        return NULL;
    }
    list->data = calloc(initialCapacity, sizeof(struct Record));
    if (!list->data) {
        free(list);
        return NULL;
    }
    list->capacity = initialCapacity;
    list->size = 0;
    return list;
}

void destroyList(struct List* list) {
    assert(list != NULL);
    free(list->data);
    free(list);
}

int insertRecord(struct List* list, long offset, int key, int value) {
    if (list->size == list->capacity) {
        // Double the capacity of the list
        size_t newCapacity = list->capacity * 2;
        struct Record* newData = realloc(list->data, newCapacity * sizeof(struct Record));
        if (!newData) {
            return -1;
        }
        list->data = newData;
        list->capacity = newCapacity;
    }
    list->size++;
    list->data[list->size].offset = offset;
    list->data[list->size].key = key;
    list->data[list->size].value = value;
    return 0;
}

int deleteRecord(struct List* list, long offset) {
    for (size_t i = 0; i < list->size; i++) {
        if (list->data[i].offset == offset) {
            // Shift all records after the deleted record one position backward
            memmove(&list->data[i], &list->data[i + 1], (list->size - i) * sizeof(struct Record));
            list->size--;
            return 0;
        }
    }
    // Return an error if the record was not found in the list
    return -1;
}

int searchRecord(struct List* list, long offset, int* key, int* value) {
    for (size_t i = 0; i < list->size; i++) {
        if (list->data[i].offset == offset) {
            *key = list->data[i].key;
            *value = list->data[i].value;
            return 0;
        }
    }
    // Return an error if the record was not found in the list
    return -1;
}
```
