    // initialize the number of free elements in the pool
    pool->num_free = size;

    // initialize the array of free elements
    for (int i = 0; i < size; i++) {
        pool->free[i] = malloc(sizeof(struct SYSTEM_PROCESS_INFO));
    }
}

void destroyMemoryPool(struct MemoryPool* pool) {
