/* Function to dynamically allocate memory for the arrays */
void allocate_memory(long *offsets, int *keys, record **records, size_t num_records) {
    /* Calculate total memory needed for the arrays */
    long total_memory = (num_records * sizeof(record)) + ((2 * num_records) * sizeof(long)) + (sizeof(int) * num_records);

    /* Validate that total memory does not exceed 1.5 MB */
    if (total_memory > 1500000) {
        printf("Error: Total memory requested exceeds 1.5 MB\n");
        exit(EXIT_FAILURE);
    }

    /* Allocate memory for the offsets and keys arrays */
    *offsets = malloc((2 * num_records) * sizeof(long));
    *keys = malloc(sizeof(int) * num_records);

    if (*offsets == NULL || *keys == NULL) {
        printf("Error: Memory allocation failed for offsets and keys arrays\n");
        exit(EXIT_FAILURE);
    }

    /* Allocate memory for the records array */
    *records = malloc(total_memory);

    if (*records == NULL) {
        printf("Error: Memory allocation failed for records array\n");
        exit(EXIT_FAILURE);
    }
}

/* Function to generate random numbers within a specified range */
void generate_random_numbers(int *random_numbers, size_t num_numbers, long min, long max) {
    /* Validate that the minimum and maximum values are not negative */
    if (min < 0 || max < 0) {
        printf("Error: Minimum and maximum values must be non-negative\n");
        exit(EXIT_FAILURE);
    }

    /* Validate that the range is within acceptable limits */
    if ((max - min) > INT_MAX) {
        printf("Error: Range of random numbers exceeds %d\n", INT_MAX);
        exit(EXIT_FAILURE);
    }

    /* Seed the random number generator with the current time */
    srand(time(NULL));

    /* Generate random numbers within the specified range */
    for (size_t i = 0; i < num_numbers; i++) {
        *(random_numbers + i) = rand() % ((max - min) + 1) + min;
    }
}

/* Function to merge contiguous free blocks */
void merge_free_blocks(void **blocks, size_t num_blocks) {
    /* Sort the blocks in ascending order based on their sizes */
    qsort(blocks, num_blocks, sizeof(void *), compare_block_sizes);

    /* Merge contiguous free blocks by adjusting the sizes of adjacent blocks */
    size_t i = 0;
    while (i < (num_blocks - 1)) {
        void *current_block = blocks[i];
        void *next_block = blocks[i + 1];
        if ((char *)current_block + current_block->size == next_block) {
            current_block->size += next_block->size;
            free(next_block);
            num_blocks--;
        } else {
            i++;
        }
    }
}

/* Comparison function to sort blocks based on their sizes */
int compare_block_sizes(const void *a, const void *b) {
    return (*(void **)a)->size - (*(void **)b)->size;
}

/* Function to validate the user-provided range and provide feedback if it is unsafe */
void validate_range(long min, long max) {
    /* Check that the minimum and maximum values are not negative */
    if (min < 0 || max < 0) {
        printf("Error: Minimum and maximum values must be non-negative\n");
        exit(EXIT_FAILURE);
    }

    /* Check that the range is within acceptable limits */
    if ((max - min) > INT_MAX) {
        printf("Warning: Range of random numbers exceeds %d, may cause errors in some cases\n", INT_MAX);
    }
}

/* Function to generate a random number within a specified range with custom seeding */
int generate_random_number(long min, long max) {
    /* Validate the user-provided range and provide feedback if it is unsafe */
    validate_range(min, max);

    /* Seed the random number generator with a custom value */
    srand(get_custom_seed());

    /* Generate random numbers within the specified range */
    return rand() % ((max - min) + 1) + min;
}

/* Function to get a custom seed for the random number generator */
long get_custom_seed() {
    /* Use an external library for generating random numbers, handling any potential errors from this integration */
    random_numbers *random = get_random_numbers();

    /* Seed the random number generator with a custom value */
    return (random->generate_random_number(10) + 1) % 10;
}

/* Function to allocate memory using an external memory pool manager, addressing potential alignment issues */
void *allocate_memory_pool_manager(size_t size) {
    /* Use an external memory pool manager to optimize allocation efficiency and reduce fragmentation */
    memory_pool_manager *manager = get_memory_pool_manager();

    /* Allocate memory from the pool manager, addressing potential alignment issues */
    void *block = (void *)manager->allocate(size);

    return block;
}

/* Function to free memory using an external memory pool manager, addressing potential alignment issues */
void free_memory_pool_manager(void **block) {
    /* Use an external memory pool manager to optimize allocation efficiency and reduce fragmentation */
    memory_pool_manager *manager = get_memory_pool_manager();

    /* Free the memory block from the pool manager, addressing potential alignment issues */
    manager->free(block);
}']

