#define INITIAL_SIZE 1024
#define MAX_SIZE 65536

struct Connection {
    int socket;
    struct sockaddr_in remote_address;
};

typedef struct Connection Connection;

Connection *connections = NULL;
int num_connections = 0;
pthread_mutex_t connections_lock = PTHREAD_MUTEX_INITIALIZER;

void add_connection(int socket) {
    pthread_mutex_lock(&connections_lock);
    if (num_connections >= MAX_SIZE) {
        fprintf(stderr, "Too many connections\n");
        return;
    }
    Connection *new_connection = malloc(sizeof(Connection));
    new_connection->socket = socket;
    new_connection->remote_address.sin_family = AF_INET;
    int res = getpeername(socket, (struct sockaddr *)&new_connection->remote_address, sizeof(struct sockaddr_in));
    if (res == -1) {
        perror("getpeername");
        return;
    }
    connections[num_connections++] = new_connection;
    pthread_mutex_unlock(&connections_lock);
}

void remove_connection(int socket) {
    pthread_mutex_lock(&connections_lock);
    for (int i = 0; i < num_connections; i++) {
        if (connections[i]->socket == socket) {
            free(connections[i]);
            connections[i] = connections[--num_connections];
            pthread_mutex_unlock(&connections_lock);
            return;
        }
    }
    pthread_mutex_unlock(&connections_lock);
}

Connection *get_connection(int socket) {
    pthread_mutex_lock(&connections_lock);
    for (int i = 0; i < num_connections; i++) {
        if (connections[i]->socket == socket) {
            Connection *ret = connections[i];
            pthread_mutex_unlock(&connections_lock);
            return ret;
        }
    }
    pthread_mutex_unlock(&connections_lock);
    return NULL;
}

void check_inactive_connections() {
    time_t current_time = time(NULL);
    for (int i = 0; i < num_connections; i++) {
        Connection *connection = connections[i];
        if ((current_time - connection->last_activity) > TIMEOUT) {
            pthread_mutex_lock(&connections_lock);
            free(connection);
            connections[i] = connections[--num_connections];
            pthread_mutex_unlock(&connections_lock);
        }
    }
}
