void initCRCIndicationList(CRCIndicationList *list) {
    // Allocate memory for the head and tail nodes
    list->head = (UniqueRNTINode *)malloc(sizeof(UniqueRNTINode));
    list->tail = (UniqueRNTINode *)malloc(sizeof(UniqueRNTINode));

    // Initialize the head and tail nodes
    list->head->next = NULL;
    list->tail->next = NULL;
}

