    UniqueRNTINode *current = list->head;
    while (current != NULL) {
        if (current->RNTI == RNTI) {
            // The RNTI value is already in the list, update the existing NFAPI_CRC_INDICATION_PDU structure
            current->pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
            current->pdu->RNTI = RNTI;
            current->pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
            current->pdu->CRCFLAG = CRCFLAG;

            // Return immediately to avoid inserting a duplicate entry
            return;
        }
        current = current->next;
    }

    // The RNTI value is not in the list, add a new NFAPI_CRC_INDICATION_PDU structure
    UniqueRNTINode *newNode = (UniqueRNTINode *)malloc(sizeof(UniqueRNTINode));
    newNode->next = NULL;
    newNode->RNTI = RNTI;
    newNode->pdu = pdu;

    // Add the new node to the end of the list
