    UniqueRNTINode *current = list->head;
    while (current != NULL) {
        if (current->RNTI == RNTI) {
            // Remove the node from the list and free its memory
            UniqueRNTINode *prev = current->next;
            UniqueRNTINode *next = prev->next;
            free(current);
            next->prev = prev;
            return;
        }
        current = current->next;
    }
