    string key;
    string value;
};

class BatchUpdateAndMerge {
public:
    static void updateAndMerge(list<ConfigEntry>& configList, const string& key, const string& value, const string& mergeStrategy, const string& externalSource) {
        // Check if the key is found in the list
        auto it = find_if(configList.begin(), configList.end(), [key](const ConfigEntry& entry) { return entry.key == key; });
        bool keyFound = it != configList.end();

        // Update the value using the specified merge strategy
        if (keyFound && mergeStrategy == "replace") {
            it->value = value;
        } else if (keyFound && mergeStrategy == "concatenate") {
            it->value += value;
        } else if (!keyFound && mergeStrategy == "add") {
            ConfigEntry newEntry{key, value};
            configList.push_back(newEntry);
        }

        // Log successful operations and errors
        ofstream logFile("batch-update-and-merge-log.txt", ios::app);
        if (logFile) {
            logFile << "Service: " << externalSource << endl;
            logFile << "External Configuration Source: " << externalSource << endl;
            logFile << "Config Key: " << key << endl;
            logFile << "Config Value: " << value << endl;
            if (keyFound) {
                logFile << "Updated Config Entry: " << it->value << endl;
            } else {
                logFile << "New Config Entry: " << value << endl;
            }
        }
    }
};
