  // Validate the RNTI against the LTE standard range (1..65535)
  if (rnti < 1 || rnti > 65535) {
    printf("Invalid RNTI value: %d\n", rnti);
    return -1;
  }

  // Acquire the lock for thread safety
  pthread_mutex_lock(&crc_indication_lock);

  // Check if the buffer is full and needs to be resized
  if (num_crc_indications == max_num_crc_indications) {
    NFAPI_CRC_INDICATION_PDU *new_buffer = realloc(crc_indications, max_num_crc_indications * 2 * sizeof(NFAPI_CRC_INDICATION_PDU));
    if (new_buffer == NULL) {
      printf("Failed to resize buffer for CRC indications\n");
      pthread_mutex_unlock(&crc_indication_lock);
      return -1;
    }
    crc_indications = new_buffer;
    max_num_crc_indications *= 2;
  }

  // Create a new structure and add it to the array
  NFAPI_CRC_INDICATION_PDU new_structure = {rx_ue_information_tag, rnti, crc_indication_rel8_tag, crcflag};
  crc_indications[num_crc_indications++] = new_structure;

  // Release the lock
  pthread_mutex_unlock(&crc_indication_lock);

  return 0;
}

// Function to handle a CRC indication request from the radio network
void *handle_crc_indication(void *arg) {
  // Get the arguments passed in by the calling thread
  NFAPI_CRC_INDICATION_PDU *crc_ind = (NFAPI_CRC_INDICATION_PDU *) arg;

  // Create a new CRC indication structure and add it to the array
  int ret = create_crc_indication(crc_ind->rx_ue_information_tag, crc_ind->rnti, crc_ind->crc_indication_rel8_tag, crc_ind->crcflag);
  if (ret < 0) {
    printf("Failed to create CRC indication structure\n");
  }

  return NULL;
}

int main() {
  // Initialize the buffer for CRC indications
  crc_indications = malloc(max_num_crc_indications * sizeof(NFAPI_CRC_INDICATION_PDU));

  // Define a thread pool for handling concurrent CRC indication requests
  pthread_t threads[10];
  for (int i = 0; i < 10; i++) {
    pthread_create(&threads[i], NULL, handle_crc_indication, NULL);
  }

  // Wait for the thread pool to finish
  for (int i = 0; i < 10; i++) {
    pthread_join(threads[i], NULL);
  }

  // Log statistics about the CRC indications
  printf("Number of successfully created structures: %lu\n", num_crc_indications);
  printf("Number of invalid RNTI entries: %d\n", (int) (max_num_crc_indications - num_crc_indications));
  printf("Average time taken per structure creation: %.3f ms\n", (float) get_time() / num_crc_indications);

  // Free the buffer for CRC indications
  free(crc_indications);
}
