void manageMemory(int identifiers[], float floatingPoints[], struct Point* points[], int statuses[], char tags[]) {
    // Validate input parameters
    if (identifiers == NULL || floatingPoints == NULL || points == NULL || statuses == NULL || tags == NULL) {
        return;
    }

    // Calculate total number of elements in all arrays
    int totalElements = 0;
    for (int i = 0; i < identifiersLength; i++) {
        totalElements += identifiers[i];
    }

    // Allocate memory for all data structures
    float* floatingPointNumbers = malloc(sizeof(float) * totalElements);
    struct Point* pointsArray = malloc(sizeof(struct Point) * totalElements);
    int* statusesArray = malloc(sizeof(int) * totalElements);
    char* tagsArray = malloc(sizeof(char) * totalElements);

    // Initialize all data structures to default values
    for (int i = 0; i < totalElements; i++) {
        floatingPointNumbers[i] = NAN;
        pointsArray[i].x = 0.0f;
        pointsArray[i].y = 0.0f;
        statusesArray[i] = -1;
        tagsArray[i] = '\0';
    }

    // Copy data from input arrays to output arrays
    int currentIndex = 0;
    for (int i = 0; i < identifiersLength; i++) {
        if (identifiers[i] > 0) {
            memcpy(floatingPointNumbers + currentIndex, floatingPoints + i, sizeof(float) * identifiers[i]);
            memcpy(pointsArray + currentIndex, points + i, sizeof(struct Point) * identifiers[i]);
            memcpy(statusesArray + currentIndex, statuses + i, sizeof(int) * identifiers[i]);
            memcpy(tagsArray + currentIndex, tags + i, sizeof(char) * identifiers[i]);
            currentIndex += identifiers[i];
        }
    }

    // Free unused memory
    free(floatingPoints);
    free(points);
    free(statuses);
    free(tags);

    return;
}

