    uint32_t sourceID;
    uint32_t destinationID;
    uint64_t sequenceNumber;
    char payload[MAX_PACKET_SIZE];
} DATA_PACKET_T;

// Hash table for the sessions
static Session_t* sessionTable[MAX_NUM_SESSIONS];

// Lock to synchronize access to the hash table
static pthread_mutex_t sessionLock = PTHREAD_MUTEX_INITIALIZER;

// Condition variable for waiting on a session to become available
static pthread_cond_t sessionAvailable = PTHREAD_COND_INITIALIZER;

// Function to add a new session to the cache
int addSession(uint64_t sessionID, DATA_PACKET_T packetInfo) {
    // Lock the hash table for writing
    pthread_mutex_lock(&sessionLock);

    // Check if there is space in the cache for a new session
    bool cacheFull = (sessionTable[MAX_NUM_SESSIONS - 1] != NULL);
    if (cacheFull) {
        printf("Cache full, cannot add new session\n");
        pthread_mutex_unlock(&sessionLock);
        return -1;
    }

