    while (fgets(line, sizeof(line), conf_file) != NULL) {
        MAC_CONTEXT_T *new_context = (MAC_CONTEXT_T *)malloc(sizeof(MAC_CONTEXT_T));
        if (new_context == NULL) {
            printf("Failed to allocate memory for new MAC context. Retrying...\n");
            sleep(1);  // Exponential backoff with a factor of 2
            continue;
        }

        char *token = strtok(line, " \t");
        if (token == NULL) {
            printf("Failed to parse configuration file. Giving up...\n");
            free(new_context);
            return NULL;
        }

        new_context->RB_ID = atoi(token);
        token = strtok(NULL, " \t");
        if (token == NULL) {
            printf("Failed to parse configuration file. Giving up...\n");
            free(new_context);
            return NULL;
        }

        new_context->PHY_LAYER_REFERENCE = atoi(token);
        token = strtok(NULL, " \t");
        if (token == NULL) {
            printf("Failed to parse configuration file. Giving up...\n");
            free(new_context);
            return NULL;
        }

        new_context->BUFFER_POOL_MANAGER = atoi(token);

        // Add new context to array
        if (i == 0) {
            context = (MAC_CONTEXT_T *)malloc(sizeof(MAC_CONTEXT_T));
            memcpy(context, new_context, sizeof(MAC_CONTEXT_T));
            i++;
        } else {
            MAC_CONTEXT_T **new_contexts = (MAC_CONTEXT_T **)realloc(context, (i + 1) * sizeof(MAC_CONTEXT_T));
            if (new_contexts == NULL) {
                printf("Failed to allocate memory for new MAC context. Giving up...\n");
                free(new_context);
                return NULL;
            }
            context = new_contexts[i - 1] = new_context;
            i++;
        }
    }
    fclose(conf_file);

    // Check for errors in configuration file
    if (context == NULL) {
        printf("Configuration file contains errors. Giving up...\n");
        return NULL;
    }

    // Set up logging mechanism
    FILE *log_file = fopen("/path/to/log/file", "w");
    if (log_file == NULL) {
        printf("Failed to open log file. Using stderr instead...\n");
        log_file = stderr;
    }
    bool logging_enabled = true;

    // Initialize and access MAC contexts in a thread-safe manner
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    bool initialization_complete = false;

    // Function to initialize MAC contexts in a thread-safe manner
    void init_context(MAC_CONTEXT_T *context) {
        pthread_mutex_lock(&mutex);
        while (!initialization_complete) {
            pthread_cond_wait(&cond, &mutex);
        }
        pthread_mutex_unlock(&mutex);
    }

    // Function to access MAC contexts in a thread-safe manner
    void access_context(MAC_CONTEXT_T *context) {
        pthread_mutex_lock(&mutex);
        while (!initialization_complete) {
            pthread_cond_wait(&cond, &mutex);
        }
        // TODO: Access context here...
        pthread_mutex_unlock(&mutex);
    }

    // Function to free MAC contexts in a thread-safe manner
    void free_context(MAC_CONTEXT_T *context) {
