// Define the function for initializing the scalable event logging system
void initEventLoggingSystem(int bufferSize, int flushFrequency, int concurrencyLevel) {
    // Allocate memory for the event log and initialize it to NULL
    Event *eventLog = (Event *)malloc(bufferSize * sizeof(Event));
    if (!eventLog) {
        perror("Failed to allocate memory for the event log");
        exit(EXIT_FAILURE);
    }
    memset(eventLog, 0, bufferSize * sizeof(Event));

    // Set the flush frequency and concurrency level
    int flushInterval = (flushFrequency == 0) ? bufferSize : flushFrequency;
    int numThreads = (concurrencyLevel == 0) ? get_nprocs() : concurrencyLevel;

    // Initialize the event log buffer for each thread
    Event **threadEventLogs = (Event **)malloc(numThreads * sizeof(Event *));
    if (!threadEventLogs) {
        perror("Failed to allocate memory for the thread event logs");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < numThreads; ++i) {
        threadEventLogs[i] = (Event *)malloc(bufferSize * sizeof(Event));
        if (!threadEventLogs[i]) {
            perror("Failed to allocate memory for the event log buffer");
            exit(EXIT_FAILURE);
        }
    }

    // Initialize the thread-safe queue for managing concurrent logging operations
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int head = 0, tail = 0;
    int numEvents = 0;
    if (pthread_mutex_init(&lock, NULL) != 0 || pthread_cond_init(&cond, NULL) != 0) {
        perror("Failed to initialize the mutex and condition variable");
        exit(EXIT_FAILURE);
    }

    // Define a thread function for logging events in parallel
    void *loggingThread(void *arg) {
        int tid = (int)arg;
        while (1) {
            pthread_mutex_lock(&lock);
            if (head == tail) { // No more events to process
                pthread_cond_wait(&cond, &lock);
            }
            Event *event = threadEventLogs[tid][head];
            head = (head + 1) % bufferSize;
            numEvents--;
            pthread_mutex_unlock(&lock);

            // Process the event and store it in the event log
            processEvent(event);
        }
    }

    // Create threads for logging events in parallel
    pthread_t *threads = (pthread_t *)malloc(numThreads * sizeof(pthread_t));
    if (!threads) {
        perror("Failed to allocate memory for the thread IDs");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < numThreads; ++i) {
        pthread_create(&threads[i], NULL, loggingThread, (void *)i);
