    // Wait for all threads to finish before exiting the program
    for (int i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Clean up resources
    free(lock);
    free(cond);
    free(threads);
    free(eventLog);
    for (int i = 0; i < numThreads; ++i) {
        free(threadEventLogs[i]);
    }
    free(threadEventLogs);
}

