// Function to create a new buffer pool for pre-allocated memory blocks
BufferPool* create_buffer_pool(size_t num_buffers, size_t buffer_size) {
  if (!num_buffers || !buffer_size) {
    return NULL;
  }
  BufferPool* pool = malloc(sizeof(BufferPool));
  if (!pool) {
    return NULL;
  }
  pool->num_buffers = num_buffers;
  pool->buffer_size = buffer_size;
  pool->buffers = calloc(num_buffers, sizeof(void*));
  if (!pool->buffers) {
    free(pool);
    return NULL;
  }
  return pool;
}

// Function to allocate a new memory block from the buffer pool
void* allocate_buffer(BufferPool* pool) {
  if (!pool || !pool->num_buffers || !pool->buffer_size) {
    return NULL;
  }
  void* buffer = calloc(1, pool->buffer_size);
  if (!buffer) {
    return NULL;
