  if (pool->num_buffers > 0) {
    --pool->num_buffers;
    pool->buffers[pool->num_buffers] = buffer;
  } else {
    free(buffer);
    buffer = NULL;
  }
  pthread_mutex_unlock(&list_mutex);
  return buffer;
}

// Function to deallocate a memory block from the buffer pool
void deallocate_buffer(BufferPool* pool, void* buffer) {
  if (!pool || !pool->num_buffers || !pool->buffer_size || !buffer) {
    return;
  }
  pthread_mutex_lock(&list_mutex);
  for (size_t i = 0; i < pool->num_buffers; ++i) {
    if (pool->buffers[i] == buffer) {
      pool->buffers[i] = NULL;
      ++pool->num_buffers;
      break;
    }
  }
  pthread_mutex_unlock(&list_mutex);
}

