#include <pthread.h>

// Define structure for project object
typedef struct {
    char* title;
    double budget_estimate;
    struct datetime completion_target;
} project;

// Declare concurrent data structure for storing projects
static pthread_mutex_t projects_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t projects_condition = PTHREAD_COND_INITIALIZER;
static project* projects = NULL;

// Function to add a new project to the list, sorted by budget in descending order
void add_project(const char* title, double budget_estimate, struct datetime completion_target) {
    pthread_mutex_lock(&projects_mutex);
    int num_projects = sizeof(projects) / sizeof(project);
    for (int i = 0; i < num_projects; i++) {
        if (projects[i].budget_estimate <= budget_estimate) {
            break;
        }
    }
    project new_project = { title, budget_estimate, completion_target };
    memmove(&projects[i + 1], &projects[i], sizeof(project) * (num_projects - i - 1));
    projects[i] = new_project;
    pthread_cond_broadcast(&projects_condition);
    pthread_mutex_unlock(&projects_mutex);
}

// Function to update a project in the list, sorted by budget in descending order
void update_project(const char* title, double new_budget_estimate, struct datetime new_completion_target) {
    pthread_mutex_lock(&projects_mutex);
    for (int i = 0; i < sizeof(projects) / sizeof(project); i++) {
        if (strcmp(projects[i].title, title) == 0) {
            projects[i].budget_estimate = new_budget_estimate;
            projects[i].completion_target = new_completion_target;
            break;
        }
    }
    pthread_cond_broadcast(&projects_condition);
    pthread_mutex_unlock(&projects_mutex);
}

// Function to delete a project from the list, sorted by budget in descending order
void delete_project(const char* title) {
    pthread_mutex_lock(&projects_mutex);
    for (int i = 0; i < sizeof(projects) / sizeof(project); i++) {
        if (strcmp(projects[i].title, title) == 0) {
            memmove(&projects[i], &projects[i + 1], sizeof(project) * (sizeof(projects) / sizeof(project) - i));
            break;
        }
    }
    pthread_cond_broadcast(&projects_condition);
    pthread_mutex_unlock(&projects_mutex);
}

// Function to query the budget estimate of a project by title, sorted by budget in descending order
double query_budget_estimate(const char* title) {
    double budget_estimate = 0;
    pthread_mutex_lock(&projects_mutex);
    for (int i = 0; i < sizeof(projects) / sizeof(project); i++) {
        if (strcmp(projects[i].title, title) == 0) {
            budget_estimate = projects[i].budget_estimate;
            break;
        }
    }
    pthread_mutex_unlock(&projects_mutex);
    return budget_estimate;
}

// Function to query the completion target of a project by title, sorted by budget in descending order
struct datetime query_completion_target(const char* title) {
    struct datetime completion_target = { 0 };
    pthread_mutex_lock(&projects_mutex);
    for (int i = 0; i < sizeof(projects) / sizeof(project); i++) {
        if (strcmp(projects[i].title, title) == 0) {
            completion_target = projects[i].completion_target;
            break;
        }
    }
    pthread_mutex_unlock(&projects_mutex);
    return completion_target;
}

// Function to query the total budget estimate of all projects, sorted by budget in descending order
double query_total_budget_estimate() {
