    pthread_mutex_lock(&projects_mutex);
    for (int i = 0; i < sizeof(projects) / sizeof(project); i++) {
        total_budget_estimate += projects[i].budget_estimate;
    }
    pthread_mutex_unlock(&projects_mutex);
    return total_budget_estimate;
}

// Background scheduler to periodically assess project progress and trigger alerts based on predefined thresholds
void project_scheduler(void* args) {
    while (1) {
        // Acquire lock on projects data structure
        pthread_mutex_lock(&projects_mutex);
        // Query current time to check for delays and cost overruns
        struct timespec current_time;
        clock_gettime(CLOCK_REALTIME, &current_time);
        // Iterate through projects and check for delays or cost overruns
        for (int i = 0; i < sizeof(projects) / sizeof(project); i++) {
            struct datetime completion_target = projects[i].completion_target;
            double budget_estimate = projects[i].budget_estimate;
            if (current_time.tv_sec > completion_target.seconds || current_time.tv_nsec > completion_target.nanoseconds) {
                // Trigger alert for delay or cost overrun
                printf("Project '%s' is delayed or has a cost overrun\n", projects[i].title);
            } else if (current_time.tv_sec < completion_target.seconds - 7 * 24 * 60 * 60) {
                // Trigger alert for upcoming delay or cost overrun
                printf("Project '%s' is due to be completed soon\n", projects[i].title);
            } else if (current_time.tv_sec < completion_target.seconds - 30 * 24 * 60 * 60) {
                // Trigger alert for upcoming cost overrun
                printf("Project '%s' is due to have a cost overrun soon\n", projects[i].title);
            }
        }
        // Release lock on projects data structure
        pthread_mutex_unlock(&projects_mutex);
        // Sleep for 1 hour before checking for delays or cost overruns again
        sleep(3600);
    }
}
