public class EnvironmentalDataProcessor {
    private static final int MAX_MEMORY = 1024 * 1024; // 1 MB
    private static final int NORMALIZATION_RANGE = 100;

    public static void processEnvironmentalData(List<EnvironmentalData> data) {
        List<Float> normalizedValues = new ArrayList<>();
        for (EnvironmentalData point : data) {
            float value = point.getValue();
            if (value > 100 || value < -100) {
                // handle out-of-range values
                continue;
            }
            normalizedValues.add((float) (value / NORMALIZATION_RANGE));
        }
        // add preprocessing layer if needed
    }

    public static List<Float> getAverageHighestLowest(List<Float> values) {
        float average = 0;
        float highest = Float.MIN_VALUE;
        float lowest = Float.MAX_VALUE;
        for (float value : values) {
            average += value;
            if (value > highest) {
                highest = value;
            }
            if (value < lowest) {
                lowest = value;
            }
        }
        return List.of(average / values.size(), highest, lowest);
    }

    public static void releaseMemory() {
        // release allocated memory
    }

    private static class EnvironmentalData {
        float value;

        public EnvironmentalData(float value) {
            this.value = value;
        }
    }
}
