// Define a structure to represent a status report PDU
typedef struct {
    uint32_t ue_identifier;
    uint16_t measurement_id;
    uint8_t phy_layer_event_tag;
} NRUE_STATUS_REPORT_PDU_T;

// Define a list of status report PDUs to store the events
NRUE_STATUS_REPORT_PDU_T *events = NULL;
size_t num_events = 0;

// Define a mutex for synchronizing access to the event list
pthread_mutex_t event_list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the dynamic list of status report PDUs
int init_events(size_t max_num_events) {
    // Allocate memory for the list of events
    events = malloc(max_num_events * sizeof(*events));
    if (!events) {
        return -1;
    }

    // Initialize the event list with empty structures
    memset(events, 0, max_num_events * sizeof(*events));

    num_events = max_num_events;

    return 0;
}

// Function to add a new status report PDU to the list
int add_event(NRUE_STATUS_REPORT_PDU_T *event) {
    // Acquire the mutex for synchronizing access to the event list
    pthread_mutex_lock(&event_list_mutex);

    // Check if there is enough memory available to store the new event
    if (num_events >= max_num_events) {
        pthread_mutex_unlock(&event_list_mutex);
        return -1;
    }

    // Add the new event to the list
    memcpy(events + num_events, event, sizeof(*event));
    num_events++;

    // Release the mutex for synchronizing access to the event list
    pthread_mutex_unlock(&event_list_mutex);

    return 0;
}

// Function to publish status reports to an MQTT broker asynchronously
int publish_events(void *args) {
    // Acquire the mutex for synchronizing access to the event list
    pthread_mutex_lock(&event_list_mutex);

    // Loop over each event in the list and publish it to the MQTT broker
    for (size_t i = 0; i < num_events; i++) {
        // Get the current event from the list
        NRUE_STATUS_REPORT_PDU_T *event = events + i;

        // Publish the event to the MQTT broker asynchronously
        int rc = mosquitto_publish(NULL, "status/report", &event->ue_identifier, sizeof(event->ue_identifier), NULL, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            printf("Error publishing status report: %s\n", mosquitto_strerror(rc));
            break;
        }
    }

    // Release the mutex for synchronizing access to the event list
    pthread_mutex_unlock(&event_list_mutex);

    return 0;
}

// Function to handle network disconnections and reconnections
int handle_disconnect(void *args) {
    // Acquire the mutex for synchronizing access to the event list
    pthread_mutex_lock(&event_list_mutex);

    // Check if there are any events in the list that have not been published yet
    size_t num_unpublished_events = 0;
    for (size_t i = 0; i < num_events; i++) {
        // Get the current event from the list
        NRUE_STATUS_REPORT_PDU_T *event = events + i;

        // Check if the event has been published yet
        if (!event->published) {
            num_unpublished_events++;
        }
    }

    // If there are any unpublished events, retry publishing them after a back-off period
    if (num_unpublished_events > 0) {
        printf("Reconnecting and resuming operations...\n");

        // Retry publishing the unpublished events with an exponential back-off strategy
        for (size_t i = 0; i < num_events; i++) {
            // Get the current event from the list
            NRUE_STATUS_REPORT_PDU_T *event = events + i;

            // Check if the event has been published yet
            if (!event->published) {
                // Publish the event to the MQTT broker asynchronously
                int rc = mosquitto_publish(NULL, "status/report", &event->ue_identifier, sizeof(event->ue_identifier), NULL, 0);
                if (rc != MOSQ_ERR_SUCCESS) {
                    printf("Error publishing status report: %s\n", mosquitto_strerror(rc));
                    break;
                }

                // Set the event as published to prevent retrying it again
                event->published = true;
            }
        }
    }

    // Release the mutex for synchronizing access to the event list
    pthread_mutex_unlock(&event_list_mutex);

    return 0;
}

// Function to handle incoming status reports from an MQTT broker and add them to the list of events
int handle_status_report(void *args) {
    // Acquire the mutex for synchronizing access to the event list
    pthread_mutex_lock(&event_list_mutex);

    // Get the incoming status report from the MQTT broker
    NRUE_STATUS_REPORT_PDU_T *status = (NRUE_STATUS_REPORT_PDU_T *)args;

    // Add the incoming status report to the list of events
    add_event(status);

    // Release the mutex for synchronizing access to the event list
    pthread_mutex_unlock(&event_list_mutex);

    return 0;
}
