// Define a global variable to hold the collection of task execution contexts
TaskExecutionContextCollection g_taskContextCollection = {NULL, 0};

// Define a mutex for synchronizing access to the collection of task execution contexts
pthread_mutex_t g_taskContextMutex;

// Initialize the collection of task execution contexts
void initTaskExecutionContextCollection(int numContexts) {
    // Allocate memory for the array of task execution context structures
    TaskExecutionContext *contexts = (TaskExecutionContext *)malloc(numContexts * sizeof(TaskExecutionContext));

    // Initialize each task execution context structure with default values
    for (int i = 0; i < numContexts; i++) {
        contexts[i].id = -1;
        contexts[i].status = 'R';
        contexts[i].startTime = time(NULL);
        contexts[i].endTime = 0;
        contexts[i].resultSize = 0;
        contexts[i].resultBuffer = NULL;
    }

    // Initialize the global variable to hold the collection of task execution contexts
    g_taskContextCollection.contexts = contexts;
    g_taskContextCollection.numContexts = numContexts;
}

// Add a new task execution context to the collection
void addTaskExecutionContext(int id, char status) {
    // Lock the mutex for synchronizing access to the collection of task execution contexts
    pthread_mutex_lock(&g_taskContextMutex);

    // Check if there is enough space in the array for the new task execution context
    if (g_taskContextCollection.numContexts >= g_taskContextCollection.contexts) {
        printf("Not enough space in the array for the new task execution context!\n");
        pthread_mutex_unlock(&g_taskContextMutex);
        return;
    }

    // Allocate memory for the new task execution context structure
    TaskExecutionContext *context = (TaskExecutionContext *)malloc(sizeof(TaskExecutionContext));

    // Initialize the new task execution context structure with default values
    context->id = id;
    context->status = status;
    context->startTime = time(NULL);
    context->endTime = 0;
    context->resultSize = 0;
    context->resultBuffer = NULL;

    // Add the new task execution context to the collection
    g_taskContextCollection.contexts[g_taskContextCollection.numContexts++] = context;

    // Unlock the mutex for synchronizing access to the collection of task execution contexts
    pthread_mutex_unlock(&g_taskContextMutex);
}

// Remove a task execution context from the collection
void removeTaskExecutionContext(int id) {
    // Lock the mutex for synchronizing access to the collection of task execution contexts
    pthread_mutex_lock(&g_taskContextMutex);

    // Find the index of the task execution context with the specified ID in the array
    int index = -1;
    for (int i = 0; i < g_taskContextCollection.numContexts; i++) {
        if (g_taskContextCollection.contexts[i].id == id) {
            index = i;
            break;
        }
    }

    // Check if the task execution context with the specified ID was found in the array
    if (index < 0) {
        printf("Task execution context with ID %d not found!\n", id);
        pthread_mutex_unlock(&g_taskContextMutex);
        return;
    }

    // Remove the task execution context from the collection by swapping it with the last element in the array and decrementing the size of the array
    TaskExecutionContext *context = g_taskContextCollection.contexts[index];
    g_taskContextCollection.contexts[index] = g_taskContextCollection.contexts[--g_taskContextCollection.numContexts];
    free(context);

    // Unlock the mutex for synchronizing access to the collection of task execution contexts
    pthread_mutex_unlock(&g_taskContextMutex);
}

// Update the status and end time of a task execution context in the collection
