// Define the maximum number of measurements to allocate memory for
#define MAX_MEASUREMENTS 10000

typedef struct {
    long offset;
    float temperature;
} measurement;

void initialize_measurements(const char* config_file) {
    // Check if the configuration file exists and is readable
    FILE *config = fopen(config_file, "r");
    if (config == NULL) {
        printf("Error: unable to read configuration file '%s'\n", config_file);
        return;
    }

    // Read the number of measurements from the configuration file
    int num_measurements = 0;
    fscanf(config, "%d", &num_measurements);

    // Ensure the number of measurements does not exceed the maximum allowed
    if (num_measurements > MAX_MEASUREMENTS) {
        printf("Error: too many measurements (%d), maximum is %d\n", num_measurements, MAX_MEASUREMENTS);
        fclose(config);
        return;
    }

    // Allocate memory for the arrays
    long *offsets = malloc(num_measurements * sizeof(long));
    measurement *measurements = malloc(num_measurements * sizeof(measurement));
    char **device_ids = malloc(num_measurements * sizeof(char*));

    // Check if memory allocation failed
    if (offsets == NULL || measurements == NULL || device_ids == NULL) {
        printf("Error: unable to allocate memory for arrays\n");
        free(offsets);
        free(measurements);
        free(device_ids);
        fclose(config);
        return;
    }

    // Read the offset, temperature, and device ID values from the configuration file
    int i = 0;
    while (fscanf(config, "%ld %f %s", &offsets[i], &measurements[i].temperature, device_ids[i]) == 3) {
        ++i;
    }

    // Validate that the number of values in each array matches the sum of the lengths of the other arrays
    if (i != num_measurements || offsets[0] != measurements[0].offset || device_ids[0] != measurements[0].device_id) {
        printf("Error: invalid configuration file format\n");
        free(offsets);
        free(measurements);
        free(device_ids);
        fclose(config);
        return;
    }

    // Set the random seed for the temperature values, if specified
    int seed = 0;
    if (argc > 2) {
        seed = atoi(argv[2]);
    }
    srand(seed);

    // Initialize the temperature values for each measurement
    for (int i = 0; i < num_measurements; ++i) {
        measurements[i].temperature = rand() % 100;
    }

    // Check if any two temperatures are the same, and if so, log an error and terminate gracefully
    for (int i = 0; i < num_measurements - 1; ++i) {
        for (int j = i + 1; j < num_measurements; ++j) {
            if (measurements[i].temperature == measurements[j].temperature) {
                printf("Error: duplicate temperature value found\n");
                free(offsets);
                free(measurements);
                free(device_ids);
                fclose(config);
                return;
            }
        }
    }

    // Free the memory allocated for the arrays, as it is no longer needed
    free(offsets);
    free(measurements);
    free(device_ids);
    fclose(config);
}
