        if (array[i].pdu.RX_UE_INFORMATION_TAG != i + 1 || array[i].pdu.RNTI != rand() % seed || array[i].pdu.CRC_INDICATION_REL8_TAG != (rand() % seed) << 4 || array[i].crcflag != true) {
