void manage_dynamic_array(TX_POWER_REPORT_INDICATION_T** array, size_t* capacity, size_t* count) {
    // Check if the current capacity is sufficient to accommodate N structures
    if (*count >= *capacity) {
        // If not, increase the capacity by a factor of 2
        *capacity = *capacity > 0 ? *capacity * 2 : 1;
        // Allocate memory for the new capacity
        TX_POWER_REPORT_INDICATION_T* new_array = malloc(*capacity * sizeof(TX_POWER_REPORT_INDICATION_T));
        if (new_array == NULL) {
            // If allocation fails, log an error and exit the function
            fprintf(stderr, "Failed to allocate memory for dynamic array of TX power report indication structures\n");
            return;
        }
        // Copy the old array to the new array
        memcpy(new_array, *array, (*count) * sizeof(TX_POWER_REPORT_INDICATION_T));
        free(*array);
        *array = new_array;
    }
