// Define a distributed key-value store environment for managing user contexts and session data
struct DistributedKeyValueStore {
  pthread_mutex_t mutex; // Mutex to protect concurrent access to the hash table
  struct SessionData **hashTable; // Hash table to store key-value pairs
  int numBuckets; // Number of buckets in the hash table
  int bucketSize; // Size of each bucket in the hash table
};

// Initialize a distributed key-value store environment
struct DistributedKeyValueStore *initDistributedKeyValueStore(int numBuckets, int bucketSize) {
  struct DistributedKeyValueStore *store = malloc(sizeof(struct DistributedKeyValueStore));
  store->numBuckets = numBuckets;
  store->bucketSize = bucketSize;

  // Allocate memory for the hash table and initialize each bucket to NULL
  store->hashTable = calloc(numBuckets, sizeof(struct SessionData *));

  // Initialize a mutex to protect concurrent access to the hash table
  pthread_mutexattr_t attr;
  pthread_mutexattr_init(&attr);
  pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
  pthread_mutex_init(&store->mutex, &attr);

  return store;
}

// Add a new user context to the distributed key-value store environment
void addUserContext(struct DistributedKeyValueStore *store, int USER_ID) {
  // Lock the mutex before accessing the hash table
  pthread_mutex_lock(&store->mutex);

  // Find an empty bucket in the hash table
  int i = 0;
  while (i < store->numBuckets && store->hashTable[i] != NULL) {
    i++;
  }

  if (i == store->numBuckets) {
    // Hash table is full, resize it
    struct SessionData **newHashTable = realloc(store->hashTable, store->numBuckets * 2 * sizeof(struct SessionData *));
    for (int j = store->numBuckets; j < store->numBuckets * 2; j++) {
      newHashTable[j] = NULL;
    }
    store->hashTable = newHashTable;
    store->numBuckets *= 2;
  }

  // Initialize the user context and add it to the hash table
  struct SessionData *sessionData = malloc(sizeof(struct SessionData));
  sessionData->key = malloc(sizeof(int) + sizeof(long long));
  memcpy(&sessionData->key, &USER_ID, sizeof(int));
  sessionData->value = NULL;
  store->hashTable[i] = sessionData;

  // Unlock the mutex and return
  pthread_mutex_unlock(&store->mutex);
}

// Get a user context from the distributed key-value store environment
struct SessionData *getUserContext(struct DistributedKeyValueStore *store, int USER_ID) {
  // Lock the mutex before accessing the hash table
  pthread_mutex_lock(&store->mutex);

  // Find the bucket in the hash table that contains the user context
  int i = 0;
  while (i < store->numBuckets && store->hashTable[i] != NULL) {
    if (memcmp(&store->hashTable[i]->key, &USER_ID, sizeof(int)) == 0) {
      break;
    }
    i++;
  }

  struct SessionData *sessionData = store->hashTable[i];

  // Unlock the mutex and return the user context
  pthread_mutex_unlock(&store->mutex);

  return sessionData;
}

// Update a user context in the distributed key-value store environment
void updateUserContext(struct DistributedKeyValueStore *store, int USER_ID, void *newSessionData) {
  // Lock the mutex before accessing the hash table
  pthread_mutex_lock(&store->mutex);

  // Find the bucket in the hash table that contains the user context
  int i = 0;
  while (i < store->numBuckets && store->hashTable[i] != NULL) {
    if (memcmp(&store->hashTable[i]->key, &USER_ID, sizeof(int)) == 0) {
      break;
    }
    i++;
  }

  // Replace the existing user context with the new one
  store->hashTable[i] = newSessionData;

  // Unlock the mutex and return
  pthread_mutex_unlock(&store->mutex);
}

// Remove a user context from the distributed key-value store environment
void removeUserContext(struct DistributedKeyValueStore *store, int USER_ID) {
  // Lock the mutex before accessing the hash table
  pthread_mutex_lock(&store->mutex);

  // Find the bucket in the hash table that contains the user context
  int i = 0;
  while (i < store->numBuckets && store->hashTable[i] != NULL) {
    if (memcmp(&store->hashTable[i]->key, &USER_ID, sizeof(int)) == 0) {
      break;
    }
    i++;
  }

  // Remove the user context from the hash table
  free(store->hashTable[i]);
  store->hashTable[i] = NULL;

  // Unlock the mutex and return
  pthread_mutex_unlock(&store->mutex);
}
