// structure to hold a MAC PDU and associated header fields
typedef struct {
    unsigned char l2_message[1024];
    unsigned int header_length;
    unsigned int payload_length;
} mac_pdu;

// global variable to store the collection of MAC PDUs
mac_pdu* pdu_collection = NULL;

// lock for thread-safe access to the collection
pthread_mutex_t pdu_lock = PTHREAD_MUTEX_INITIALIZER;

void init_pdu_collection(int num_pdus) {
    // initialize the collection with the given number of PDUs
    pdu_collection = (mac_pdu*)malloc(num_pdus * sizeof(mac_pdu));
    if (!pdu_collection) {
        printf("Error: failed to allocate memory for PDU collection\n");
        return;
    }

    // initialize the header fields for each PDU
    for (int i = 0; i < num_pdus; i++) {
        pdu_collection[i].header_length = 14;
        pdu_collection[i].payload_length = 1024 - 14;
    }
}

void config_pdu(int idx, unsigned char* l2_message) {
    // validate the input L2 message and its length
    if (l2_message == NULL || strlen((char*)l2_message) > 1024 - 14) {
        printf("Error: invalid L2 message or length\n");
        return;
    }

    // acquire the lock for thread-safe access to the PDU collection
    pthread_mutex_lock(&pdu_lock);

    // copy the input L2 message into the PDU at the given index
    memcpy(pdu_collection[idx].l2_message, l2_message, strlen((char*)l2_message));

    // release the lock and return
    pthread_mutex_unlock(&pdu_lock);
}

void free_pdu_collection() {
    // acquire the lock for thread-safe access to the PDU collection
    pthread_mutex_lock(&pdu_lock);

    // release the memory allocated for the PDU collection
    if (pdu_collection) {
        free(pdu_collection);
    }

    // release the lock and return
    pthread_mutex_unlock(&pdu_lock);
}
