    size_t index = find_element_index(dynamic_array, rnti);
    if (index == SIZE_MAX) {
        fprintf(stderr, "Error: Element not found\n");
        pthread_mutex_unlock(&mutex);
        return false;
    }
    // Remove the element from the dynamic array
    for (size_t i = index + 1; i < dynamic_array->count; i++) {
        dynamic_array->elements[i - 1] = dynamic_array->elements[i];
    }
    dynamic_array->count--;
    pthread_mutex_unlock(&mutex);
    return true;
}

