// Struct for a log entry, containing timestamp offsets and a reference count
typedef struct LogEntry {
    long* offsets; // Pointer to a variable-sized array of long integers representing timestamp offsets
    int level; // Log level (e.g., INFO, ERROR) as a key
    size_t ref_count; // Reference count initialized to zero
} LogEntry;

// Function to allocate memory for and initialize an array of LogEntries
LogEntry* log_entry_alloc(size_t num_entries) {
    assert(num_entries > 0);
    LogEntry* entries = (LogEntry*)malloc(sizeof(LogEntry) * num_entries);
    if (!entries) {
        return NULL;
    }
    for (int i = 0; i < num_entries; ++i) {
        entries[i].offsets = (long*)malloc(sizeof(long)); // Allocate memory for one offset
        if (!entries[i].offsets) {
            return NULL;
        }
        entries[i].ref_count = 0;
    }
    return entries;
}

// Function to free the memory allocated by log_entry_alloc
void log_entry_free(LogEntry* entries, size_t num_entries) {
    assert(num_entries > 0);
    for (int i = 0; i < num_entries; ++i) {
        free(entries[i].offsets); // Free the memory allocated for one offset
    }
    free(entries); // Free the memory allocated for the LogEntry array
}

// Function to add a new log entry, incrementing the reference count for the corresponding LogEntry structure
void log_add_entry(LogEntry* entries, size_t num_entries, long offset, int level) {
    assert(num_entries > 0);
    pthread_mutex_lock(&mutex); // Lock the mutex to prevent concurrent access
    for (int i = 0; i < num_entries; ++i) {
        if (entries[i].level == level) {
            entries[i].ref_count++; // Increment the reference count
            break;
        }
    }
    pthread_mutex_unlock(&mutex); // Unlock the mutex to allow other threads to access the array
}

// Function to decrement the reference count and release resources when a LogEntry is no longer needed
void log_release_entry(LogEntry* entries, size_t num_entries, int level) {
    assert(num_entries > 0);
    pthread_mutex_lock(&mutex); // Lock the mutex to prevent concurrent access
    for (int i = 0; i < num_entries; ++i) {
        if (entries[i].level == level && entries[i].ref_count > 0) {
            entries[i].ref_count--; // Decrement the reference count
            if (entries[i].ref_count == 0) {
                free(entries[i].offsets); // Free the memory allocated for one offset
            }
            break;
        }
    }
    pthread_mutex_unlock(&mutex); // Unlock the mutex to allow other threads to access the array
}
