    int block_index = ((char*)tx_power_report_indication - (char*)mempool.blocks) / sizeof(int);
    mempool.head--;

    // deallocate the structure and move the last element to the freed position
    void* block = malloc(mempool.blocks[mempool.tail]);
    if (!block) {
        return;
    }
    memcpy(block, tx_power_report_indication, mempool.blocks[mempool.tail] * sizeof(int));
    free(tx_power_report_indication);

    // move the last element to the freed position and decrement the tail pointer
    mempool.blocks[block_index] = mempool.blocks[mempool.tail];
    mempool.blocks[mempool.tail--] = 0;
}

// define the function to allocate memory for the SYSTEM_PROCESS_INFO structures
void* alloc_system_process_info(size_t size) {
    // check if the memory pool is full, if so expand it by 50%
    if (mempool.head == NUM_BLOCKS - 1) {
        int new_blocks = mempool.head + (NUM_BLOCKS / 2);
        int* new_blocks = realloc(mempool.blocks, new_blocks * sizeof(int));
        if (!new_blocks) {
            return NULL;
        }
        memcpy(new_blocks, mempool.blocks, mempool.head * sizeof(int));
        mempool.blocks = new_blocks;
        mempool.tail += (NUM_BLOCKS / 2);
    }

    // allocate memory for the structure and increment the head pointer
    int block_index = mempool.head++;
    void* block = malloc(size * sizeof(int));
    if (!block) {
        return NULL;
    }
    mempool.blocks[block_index] = (char*)block - (char*)mempool.blocks;

    // initialize the structure and return a pointer to it
    SYSTEM_PROCESS_INFO* system_process_info = block;
    memset(system_process_info, 0, size * sizeof(int));
    return system_process_info;
}

// define the function to deallocate memory for the SYSTEM_PROCESS_INFO structures
void free_system_process_info(SYSTEM_PROCESS_INFO* system_process_info) {
    // find the index of the structure in the memory pool and decrement the head pointer
    int block_index = ((char*)system_process_info - (char*)mempool.blocks) / sizeof(int);
    mempool.head--;

    // deallocate the structure and move the last element to the freed position
    void* block = malloc(mempool.blocks[mempool.tail]);
    if (!block) {
        return;
    }
    memcpy(block, system_process_info, mempool.blocks[mempool.tail] * sizeof(int));
    free(system_process_info);

    // move the last element to the freed position and decrement the tail pointer
    mempool.blocks[block_index] = mempool.blocks[mempool.tail];
    mempool.blocks[mempool.tail--] = 0;
}

// define the function to create a new collection of structures
