  pthread_mutex_t* mutex = malloc(sizeof(pthread_mutex_t));
  if (mutex == NULL) {
    log("Error allocating memory for mutex\n");
    return -1;
  }
  ret = pthread_mutex_init(mutex, NULL);
  if (ret != 0) {
    log("Error initializing mutex\n");
    free(mutex);
    return -2;
  }
  LongOffsetT* longOffsets = malloc(sizeof(LongOffsetT) * n);
  if (longOffsets == NULL) {
