// Define data structure to store records
typedef struct record {
    int key;
    double value;
    char status;
} Record;

// Define cache data structure
typedef struct cache {
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
    Record *records;
} Cache;

// Initialize cache with specified size and capacity
void initCache(Cache *cache, size_t size, size_t capacity) {
    cache->size = 0;
    cache->capacity = capacity;
    cache->mutex = PTHREAD_MUTEX_INITIALIZER;
    cache->records = malloc(sizeof(Record) * capacity);
}

// Add new record to cache
void addRecordToCache(Cache *cache, int key, double value, char status) {
    // Acquire lock on cache mutex
    pthread_mutex_lock(&cache->mutex);

    // Check if cache is full and evict least recently used record if necessary
    if (cache->size == cache->capacity) {
        int leastRecentlyUsed = 0;
        for (int i = 1; i < cache->size; ++i) {
            if (cache->records[leastRecentlyUsed].lastAccessed < cache->records[i].lastAccessed) {
                leastRecentlyUsed = i;
            }
        }
        cache->records[leastRecentlyUsed] = NULL;
    }

    // Insert new record into cache
    cache->records[cache->size].key = key;
    cache->records[cache->size].value = value;
    cache->records[cache->size].status = status;
    ++cache->size;

    // Release lock on cache mutex
    pthread_mutex_unlock(&cache->mutex);
}

// Retrieve record from cache by key
Record *getRecordFromCache(Cache *cache, int key) {
    // Acquire lock on cache mutex
    pthread_mutex_lock(&cache->mutex);

    // Check if key exists in cache
    for (int i = 0; i < cache->size; ++i) {
        if (cache->records[i].key == key) {
            cache->records[i].lastAccessed = time(NULL);
            return &cache->records[i];
        }
    }

    // Release lock on cache mutex
    pthread_mutex_unlock(&cache->mutex);

    return NULL;
}

// Update record in cache by key
void updateRecordInCache(Cache *cache, int key, double value) {
    // Acquire lock on cache mutex
    pthread_mutex_lock(&cache->mutex);

    // Check if key exists in cache
    for (int i = 0; i < cache->size; ++i) {
        if (cache->records[i].key == key) {
            cache->records[i].value = value;
            cache->records[i].lastAccessed = time(NULL);
            break;
        }
    }

    // Release lock on cache mutex
    pthread_mutex_unlock(&cache->mutex);
}

// Remove record from cache by key
void removeRecordFromCache(Cache *cache, int key) {
    // Acquire lock on cache mutex
    pthread_mutex_lock(&cache->mutex);

    // Check if key exists in cache
    for (int i = 0; i < cache->size; ++i) {
        if (cache->records[i].key == key) {
            cache->records[i] = NULL;
            --cache->size;
            break;
        }
    }

    // Release lock on cache mutex
    pthread_mutex_unlock(&cache->mutex);
}
```
