    memcpy(cur, new, sizeof(TX_POWER_REPORT_INDICATION_T));

    // Add the new structure to the end of the array
    arr[(*size)++] = cur;

    // Shrink the memory pool if necessary
    if (*size >= mempool.shrink_threshold) {
        shrink_memory_pool();
    }

    // Return the updated array
    return arr;
}

// Define the function to shrink the memory pool by half
void shrink_memory_pool() {
    // Check if the memory pool is already at its minimum size
    if (mempool.size == mempool.initial_size) {
