    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
};

struct NFAPI_CRC_INDICATION_PDU_T_LIST {
    struct NFAPI_CRC_INDICATION_PDU_T *data;
    int size;
    int capacity;
};

struct NFAPI_CRC_INDICATION_PDU_T_LIST *list = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
semaphore_t semaphore;

void init_crc_indication_pdu_list() {
    list = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T_LIST));
    if (list == NULL) {
        printf("Failed to allocate memory for CRC indication PDU list\n");
        return;
    }
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
}

void free_crc_indication_pdu_list() {
    if (list == NULL) {
        return;
    }
    for (int i = 0; i < list->size; i++) {
        free(list->data[i].rx_ue_information_tag);
        free(list->data[i].rnti);
        free(list->data[i].crc_indication_rel8_tag);
    }
    free(list->data);
    list = NULL;
}

void add_crc_indication_pdu(struct NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list_lock);
    if (list->size == list->capacity) {
        int new_capacity = list->capacity + 10;
        struct NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            printf("Failed to allocate memory for CRC indication PDU list\n");
            return;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    memcpy(&list->data[list->size], pdu, sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    list->size++;
    pthread_mutex_unlock(&list_lock);
}

void update_crc_indication_pdu(RX_UE_INFORMATION_TAG rx_ue_information_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
    pthread_mutex_lock(&list_lock);
    for (int i = 0; i < list->size; i++) {
