            free(list->data[i].rx_ue_information_tag);
            free(list->data[i].rnti);
            free(list->data[i].crc_indication_rel8_tag);
            memmove(&list->data[i], &list->data[i + 1], (list->size - i) * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
            list->size--;
        }
    }
    pthread_mutex_unlock(&list_lock);
}

void print_crc_indication_pdu_list() {
