        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n", list->data[i].rx_ue_information_tag, list->data[i].rnti, list->data[i].crc_indication_rel8_tag);
