#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

// Define the cache structure
struct Cache {
    // Hash table to store the responses
    struct hash_table* responses;
    // Linked list for managing the order of the responses
    struct linked_list* response_order;
    // Lock for protecting concurrent access to the cache
    pthread_mutex_t mutex;
};

// Define a function to create a new cache entry
struct CacheEntry* create_cache_entry(char* url, int status_code, char* headers, char* body) {
    // Allocate memory for the cache entry
    struct CacheEntry* entry = malloc(sizeof(struct CacheEntry));
    if (entry == NULL) {
        return NULL;
    }

    // Initialize the cache entry with the provided data
    entry->url = url;
    entry->status_code = status_code;
    entry->headers = headers;
    entry->body = body;

    return entry;
}

// Define a function to add a new response to the cache
void add_response_to_cache(struct Cache* cache, struct CacheEntry* entry) {
    // Lock the cache mutex
    pthread_mutex_lock(&cache->mutex);

    // Add the response to the hash table
    bool added = hash_table_add(cache->responses, entry->url, entry);

    // If the response was not already in the cache, add it to the linked list
    if (added) {
        struct linked_list* new_entry = malloc(sizeof(struct linked_list));
        new_entry->data = entry;
        new_entry->next = cache->response_order;
        cache->response_order = new_entry;
    }

    // Unlock the cache mutex
    pthread_mutex_unlock(&cache->mutex);
}

// Define a function to retrieve a response from the cache
struct CacheEntry* get_response_from_cache(struct Cache* cache, char* url) {
    // Lock the cache mutex
    pthread_mutex_lock(&cache->mutex);

    // Retrieve the response from the hash table
    struct CacheEntry* entry = hash_table_get(cache->responses, url);

    // If the response was found, move it to the front of the linked list
    if (entry != NULL) {
        struct linked_list* node = cache->response_order;
        while (node != NULL && node->data != entry) {
            node = node->next;
        }
        if (node != NULL) {
            node->next = node->next->next;
        }
        struct linked_list* new_entry = malloc(sizeof(struct linked_list));
        new_entry->data = entry;
        new_entry->next = cache->response_order;
        cache->response_order = new_entry;
    }

    // Unlock the cache mutex
    pthread_mutex_unlock(&cache->mutex);

    return entry;
}

// Define a function to remove a response from the cache
void remove_response_from_cache(struct Cache* cache, char* url) {
    // Lock the cache mutex
    pthread_mutex_lock(&cache->mutex);

    // Remove the response from the hash table and linked list
    struct CacheEntry* entry = hash_table_remove(cache->responses, url);
    if (entry != NULL) {
        struct linked_list* node = cache->response_order;
        while (node != NULL && node->data != entry) {
            node = node->next;
        }
        if (node != NULL) {
            node->next = node->next->next;
        }
        free(entry);
    }

    // Unlock the cache mutex
    pthread_mutex_unlock(&cache->mutex);
}

// Define a function to evict stale responses from the cache
void evict_stale_responses(struct Cache* cache) {
    // Lock the cache mutex
    pthread_mutex_lock(&cache->mutex);

    // Iterate through the linked list and remove any stale responses
    struct linked_list* node = cache->response_order;
    while (node != NULL) {
        struct CacheEntry* entry = node->data;
        if (entry->timestamp < time(NULL) - 30) { // Evict responses older than 30 seconds
            remove_response_from_cache(cache, entry->url);
        } else {
            node = node->next;
        }
    }

    // Unlock the cache mutex
    pthread_mutex_unlock(&cache->mutex);
}

// Define a function to handle incoming requests and add or retrieve responses from the cache
void handle_incoming_request(struct Cache* cache, char* url) {
    // Check if the response is already in the cache
    struct CacheEntry* entry = get_response_from_cache(cache, url);
    if (entry != NULL) {
        printf("Found a cached response for %s\n", url);
        return;
    }

    // If the response is not in the cache, make an external request to retrieve it
    struct http_request* request = malloc(sizeof(struct http_request));
    request->url = url;
    int status_code = send_http_request(request);
    char* headers = get_response_headers(request);
    char* body = get_response_body(request);

    // Add the response to the cache
    entry = create_cache_entry(url, status_code, headers, body);
    add_response_to_cache(cache, entry);
}

// Define a function to handle the producer-consumer pattern for incoming requests
void handle_incoming_requests(struct Cache* cache) {
    // Lock the cache mutex
    pthread_mutex_lock(&cache->mutex);

    // Check if there are any incoming requests to handle
    while (!queue_is_empty()) {
        char* url = queue_pop();
        handle_incoming_request(cache, url);
    }

    // Unlock the cache mutex
    pthread_mutex_unlock(&cache->mutex);
}

// Define a function to handle the eviction of stale responses from the cache
void handle_eviction(struct Cache* cache) {
    // Lock the cache mutex
    pthread_mutex_lock(&cache->mutex);

    // Evict any stale responses from the cache
    evict_stale_responses(cache);

    // Unlock the cache mutex
    pthread_mutex_unlock(&cache->mutex);
}
```

This implementation uses a `hash table` to store the responses and a `linked list` to keep track of the order in which they were received. It also includes a function for handling incoming requests, another function for handling the eviction of stale responses, and another function for handling the producer-consumer pattern for incoming requests.

The implementation uses `pthread_mutex` to lock and unlock the cache during accesses to prevent race conditions.']

