// Struct for a node in the array of nodes
typedef struct {
    char identifier;
    long* values;
} Node;

// Function to manage dynamic memory allocation for an array of nodes
Node** alloc_nodes(size_t num_nodes, size_t initial_values) {
    // Check for valid input sizes
    if (num_nodes == 0 || initial_values == 0) {
        return NULL;
    }

    // Allocate memory for the array of nodes
    Node** nodes = malloc(sizeof(Node*) * num_nodes);
    if (!nodes) {
        perror("Error allocating memory for nodes");
        exit(EXIT_FAILURE);
    }

    // Initialize each node's array of long values with a specified number of elements, each initialized to zero
    for (size_t i = 0; i < num_nodes; i++) {
        nodes[i] = malloc(sizeof(Node));
        if (!nodes[i]) {
            perror("Error allocating memory for node");
            exit(EXIT_FAILURE);
        }
        nodes[i]->identifier = 0;
        nodes[i]->values = calloc(initial_values, sizeof(long));
        if (!nodes[i]->values) {
            perror("Error allocating memory for node values");
            exit(EXIT_FAILURE);
        }
    }

    return nodes;
}

// Function to safely free all allocated memory when the function is done
void free_nodes(Node** nodes, size_t num_nodes) {
    // Check for valid input sizes
    if (!nodes || num_nodes == 0) {
        return;
    }

    // Free each node's array of long values and the memory allocated for the node struct itself
    for (size_t i = 0; i < num_nodes; i++) {
        free(nodes[i]->values);
        free(nodes[i]);
    }

    // Free the memory allocated for the array of pointers to nodes
    free(nodes);
}
