#include <arpa/inet.h>
#include <errno.h>
#include <assert.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

#define MAX_POWER_REPORTS 100000
#define CACHE_SIZE 5000
#define RX_UE_INFORMATION_TAG 1
#define CRC_INDICATION_REL8_TAG 2
#define DATA_VALIDITY_MASK 0x80000000
#define TIMESTAMP_MASK 0x7fffffff
#define MAX_TIMESTAMP (unsigned int)-1
#define MIN_VALUE -5.0f
#define MAX_VALUE 20.0f
#define CACHE_RECYCLE_THRESHOLD 0.5f
#define RESIZE_FACTOR 2
#define RESIZE_LIMIT (unsigned int)-1

typedef struct {
    unsigned int rnti;
    unsigned int crcIndicationRel8Tag;
} txPowerReportIndicationT;

typedef struct {
    float value;
    unsigned int timestamp;
    unsigned char validityFlag;
} dataPointT;

typedef struct {
    unsigned int recordId;
    txPowerReportIndicationT report;
    dataPointT* dataPoints;
} recordT;

// Dynamic array of TX power report indications
txPowerReportIndicationT* txPowerReports = NULL;
unsigned int numTxPowerReports = 0;
pthread_mutex_t txPowerReportsMutex;

// Caching mechanism for records
recordT* records = NULL;
unsigned int numRecords = 0;
pthread_mutex_t recordsMutex;

// Memory pool for data points
dataPointT* dataPointsPool = NULL;
unsigned int nextDataPointIdx = 0;
pthread_mutex_t dataPointsPoolMutex;

// Utility functions for working with timestamps
static inline unsigned int getTimestamp() {
    return (unsigned int)time(NULL);
}

static inline float getValue(unsigned int timestamp, float minValue, float maxValue) {
    return minValue + ((float)(timestamp % MAX_TIMESTAMP) / TIMESTAMP_MASK) * (maxValue - minValue);
}

// Function to resolve hostname and store the resulting IP address in a u_char array
int dynamicNetworkDataHandler(const char* hostname, unsigned int* ipAddr) {
    // Resolve hostname using DNS
    struct addrinfo* res;
    if (getaddrinfo(hostname, NULL, NULL, &res) != 0) {
        return -1;
    }

    // Store IP address in u_char array
    *ipAddr = *((unsigned int*)res->ai_addr);

    freeaddrinfo(res);
    return 0;
}

// Thread-safe function to allocate a new data point
dataPointT* allocateDataPoint() {
    pthread_mutex_lock(&dataPointsPoolMutex);
    if (nextDataPointIdx >= numDataPoints) {
        resizeDataPointArray();
    }
    dataPointT* dataPoint = &(dataPointsPool[nextDataPointIdx]);
    nextDataPointIdx++;
    pthread_mutex_unlock(&dataPointsPoolMutex);
    return dataPoint;
}

// Thread-safe function to deallocate a data point
void deallocateDataPoint(dataPointT* dataPoint) {
    pthread_mutex_lock(&dataPointsPoolMutex);
    nextDataPointIdx--;
    dataPoint->validityFlag = 0;
    pthread_mutex_unlock(&dataPointsPoolMutex);
}

// Thread-safe function to resize the data point array
void resizeDataPointArray() {
    unsigned int newSize = numDataPoints * RESIZE_FACTOR;
    if (newSize > RESIZE_LIMIT) {
        return;
    }
    dataPointT* newDataPointsPool = malloc(sizeof(dataPointT) * newSize);
    memcpy(newDataPointsPool, dataPointsPool, sizeof(dataPointT) * numDataPoints);
    free(dataPointsPool);
    dataPointsPool = newDataPointsPool;
    nextDataPointIdx = numDataPoints;
}

// Function to handle insertion of a new TX power report indication
void insertTxPowerReportIndication(const txPowerReportIndicationT* report) {
    pthread_mutex_lock(&txPowerReportsMutex);
    if (numTxPowerReports >= MAX_POWER_REPORTS) {
        resizeTxPowerReportArray();
    }
    txPowerReports[numTxPowerReports] = *report;
    numTxPowerReports++;
    pthread_mutex_unlock(&txPowerReportsMutex);
}

// Function to handle deletion of a TX power report indication
void deleteTxPowerReportIndication(unsigned int idx) {
    pthread_mutex_lock(&txPowerReportsMutex);
    if (idx >= numTxPowerReports) {
        return;
    }
    txPowerReports[idx] = txPowerReports[numTxPowerReports - 1];
    numTxPowerReports--;
    pthread_mutex_unlock(&txPowerReportsMutex);
}

// Function to handle modification of a TX power report indication
void modifyTxPowerReportIndication(unsigned int idx, const txPowerReportIndicationT* report) {
    pthread_mutex_lock(&txPowerReportsMutex);
    if (idx >= numTxPowerReports) {
        return;
    }
    txPowerReports[idx] = *report;
    pthread_mutex_unlock(&txPowerReportsMutex);
}

// Function to handle insertion of a new record
void insertRecord(const recordT* record) {
    pthread_mutex_lock(&recordsMutex);
    if (numRecords >= MAX_RECORDS) {
        resizeRecordArray();
    }
    records[numRecords] = *record;
    numRecords++;
    pthread_mutex_unlock(&recordsMutex);
}

// Function to handle deletion of a record
void deleteRecord(unsigned int idx) {
    pthread_mutex_lock(&recordsMutex);
    if (idx >= numRecords) {
        return;
    }
    records[idx] = records[numRecords - 1];
    numRecords--;
    pthread_mutex_unlock(&recordsMutex);
}

// Function to handle modification of a record
void modifyRecord(unsigned int idx, const recordT* record) {
    pthread_mutex_lock(&recordsMutex);
    if (idx >= numRecords) {
        return;
    }
    records[idx] = *record;
    pthread_mutex_unlock(&recordsMutex);
}

// Thread-safe function to resize the TX power report array
void resizeTxPowerReportArray() {
    unsigned int newSize = numTxPowerReports * RESIZE_FACTOR;
    if (newSize > RESIZE_LIMIT) {
        return;
    }
    txPowerReportIndicationT* newTxPowerReportsPool = malloc(sizeof(txPowerReportIndicationT) * newSize);
    memcpy(newTxPowerReportsPool, txPowerReportsPool, sizeof(txPowerReportIndicationT) * numTxPowerReports);
    free(txPowerReportsPool);
    txPowerReportsPool = newTxPowerReportsPool;
}

// Thread-safe function to resize the record array
