#define MAX_SESSIONS 10000
#define SESSION_METADATA_SIZE 128 // Size of session-specific metadata in bytes
#define INITIAL_BUFFER_SIZE 4096 // Initial size of incoming data buffer in bytes
#define BUFFER_GROWTH_FACTOR 2 // Factor by which to grow the incoming data buffer

typedef struct UserSessionState {
    int session_id;
    enum ConnectionState {
        DISCONNECTED,
        CONNECTING,
        CONNECTED,
        CLOSING,
        CLOSED
    } connection_state;
    time_t last_activity;
    char* incoming_data_buffer;
    size_t incoming_data_size;
    void* metadata;
} UserSessionState;

typedef struct SessionArray {
    pthread_mutex_t mutex;
    int num_sessions;
    UserSessionState* sessions[MAX_SESSIONS];
} SessionArray;

void session_array_init(SessionArray* array) {
    assert(array != NULL);

    // Initialize the mutex for thread-safe access to the session array
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&array->mutex, &attr);

    // Initialize the number of sessions to 0
    array->num_sessions = 0;
}

void session_array_destroy(SessionArray* array) {
    assert(array != NULL);

    // Release all resources associated with the session array
    pthread_mutex_lock(&array->mutex);

    for (int i = 0; i < array->num_sessions; ++i) {
        UserSessionState* session = array->sessions[i];
        free(session->incoming_data_buffer);
        free(session);
    }

    pthread_mutex_unlock(&array->mutex);

    // Destroy the mutex for thread-safe access to the session array
    pthread_mutex_destroy(&array->mutex);
}

int session_array_add(SessionArray* array, int session_id, enum ConnectionState connection_state) {
    assert(array != NULL);

    // Acquire the mutex for thread-safe access to the session array
    pthread_mutex_lock(&array->mutex);

    if (array->num_sessions == MAX_SESSIONS) {
        printf("Reached maximum number of sessions\n");
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }

    // Allocate a new session state and initialize its fields
    UserSessionState* session = (UserSessionState*)malloc(sizeof(UserSessionState));
    if (!session) {
        printf("Failed to allocate memory for session state\n");
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }
    session->session_id = session_id;
    session->connection_state = connection_state;
    session->last_activity = time(NULL);
    session->incoming_data_buffer = (char*)malloc(INITIAL_BUFFER_SIZE);
    if (!session->incoming_data_buffer) {
        printf("Failed to allocate memory for incoming data buffer\n");
        free(session);
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }
    session->incoming_data_size = INITIAL_BUFFER_SIZE;
    session->metadata = NULL; // Initialize session-specific metadata to null

    // Add the new session state to the end of the array
    array->sessions[array->num_sessions++] = session;

    pthread_mutex_unlock(&array->mutex);

    return 0;
}

int session_array_remove(SessionArray* array, int session_id) {
    assert(array != NULL);

    // Acquire the mutex for thread-safe access to the session array
    pthread_mutex_lock(&array->mutex);

    // Find the session state with the specified ID and remove it from the array
    for (int i = 0; i < array->num_sessions; ++i) {
        if (array->sessions[i]->session_id == session_id) {
            UserSessionState* session = array->sessions[i];
            free(session->incoming_data_buffer);
            free(session);
            for (int j = i + 1; j < array->num_sessions; ++j) {
                array->sessions[j - 1] = array->sessions[j];
            }
            --array->num_sessions;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }

    printf("Session with ID %d not found\n", session_id);

    pthread_mutex_unlock(&array->mutex);

    return -1;
}

UserSessionState* session_array_find(SessionArray* array, int session_id) {
    assert(array != NULL);

    // Acquire the mutex for thread-safe access to the session array
    pthread_mutex_lock(&array->mutex);

    // Find the session state with the specified ID and return it
    for (int i = 0; i < array->num_sessions; ++i) {
        if (array->sessions[i]->session_id == session_id) {
            UserSessionState* session = array->sessions[i];
            pthread_mutex_unlock(&array->mutex);
            return session;
        }
    }

    printf("Session with ID %d not found\n", session_id);

    pthread_mutex_unlock(&array->mutex);

    return NULL;
}

void session_array_update(SessionArray* array, int session_id, enum ConnectionState connection_state) {
    assert(array != NULL);

    // Acquire the mutex for thread-safe access to the session array
    pthread_mutex_lock(&array->mutex);

    UserSessionState* session = session_array_find(array, session_id);
    if (session) {
        session->connection_state = connection_state;
        session->last_activity = time(NULL);
    } else {
        printf("Session with ID %d not found\n", session_id);
    }

    pthread_mutex_unlock(&array->mutex);
}

void session_array_incoming_data(SessionArray* array, int session_id, const void* data, size_t length) {
    assert(array != NULL);

    // Acquire the mutex for thread-safe access to the session array
    pthread_mutex_lock(&array->mutex);

    UserSessionState* session = session_array_find(array, session_id);
    if (session) {
        size_t remaining_capacity = session->incoming_data_size - session->incoming_data_length;
        if (length <= remaining_capacity) {
            memcpy(session->incoming_data_buffer + session->incoming_data_length, data, length);
            session->incoming_data_length += length;
        } else {
            printf("Incoming data overflow\n");
        }
    } else {
        printf("Session with ID %d not found\n", session_id);
    }

    pthread_mutex_unlock(&array->mutex);
}

void session_array_outgoing_data(SessionArray* array, int session_id, const void* data, size_t length) {
    assert(array != NULL);

    // Acquire the mutex for thread-safe access to the session array
    pthread_mutex_lock(&array->mutex);

    UserSessionState* session = session_array_find(array, session_id);
    if (session) {
        size_t remaining_capacity = session->incoming_data_size - session->incoming_data_length;
        if (length <= remaining_capacity) {
            memcpy(session->outgoing_data_buffer + session->outgoing_data_length, data, length);
            session->outgoing_data_length += length;
        } else {
            printf("Outgoing data overflow\n");
        }
    } else {
        printf("Session with ID %d not found\n", session_id);
    }

    pthread_mutex_unlock(&array->mutex);
}
