```c
#include <stdbool.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Structure to represent a session
typedef struct Session {
    int id;
    char ip_address[16];
    time_t last_active;
    bool active;
} Session;

// Hash table for fast lookups
static Session* sessions[1024];

// Locking mechanism to ensure thread safety
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to insert a new session into the list
void insertSession(int id, char* ip_address) {
    // Acquire the lock
    pthread_mutex_lock(&lock);

    // Create a new session structure
    Session* new_session = (Session*) malloc(sizeof(Session));
    if (!new_session) {
        printf("Error: Out of memory!\n");
        return;
    }

    // Initialize the session fields
    new_session->id = id;
    strcpy(new_session->ip_address, ip_address);
    new_session->last_active = time(NULL);
    new_session->active = true;

    // Insert the new session into the hash table
    sessions[id % 1024] = new_session;

    // Release the lock
    pthread_mutex_unlock(&lock);
}

// Function to update an existing session in the list
void updateSession(int id, char* ip_address) {
    // Acquire the lock
    pthread_mutex_lock(&lock);

    // Look up the session in the hash table
    Session* session = sessions[id % 1024];
    if (!session) {
        printf("Error: Session not found!\n");
        return;
    }

    // Update the session fields
    strcpy(session->ip_address, ip_address);
    session->last_active = time(NULL);

    // Release the lock
    pthread_mutex_unlock(&lock);
}

// Function to remove an existing session from the list
void removeSession(int id) {
    // Acquire the lock
    pthread_mutex_lock(&lock);

    // Look up the session in the hash table
    Session* session = sessions[id % 1024];
    if (!session) {
        printf("Error: Session not found!\n");
        return;
    }

    // Remove the session from the hash table
    sessions[id % 1024] = NULL;

    // Release the lock
    pthread_mutex_unlock(&lock);
}

// Function to query a session based on its last active timestamp
Session* querySession(time_t last_active) {
    // Acquire the lock
    pthread_mutex_lock(&lock);

    // Loop through the hash table and find the first matching session
    for (int i = 0; i < 1024; i++) {
        Session* session = sessions[i];
        if (!session) continue;
        if (session->last_active <= last_active) return session;
    }

    // No matching session found, return NULL
    return NULL;
}

// Function to track session activity and provide accurate reports
void trackSessionActivity(int id, char* ip_address, time_t last_active) {
    // Acquire the lock
    pthread_mutex_lock(&lock);

    // Look up the session in the hash table
    Session* session = sessions[id % 1024];
    if (!session) {
        printf("Error: Session not found!\n");
        return;
    }

    // Update the session fields
    strcpy(session->ip_address, ip_address);
    session->last_active = last_active;

    // Release the lock
    pthread_mutex_unlock(&lock);
}
```
The above implementation uses a hash table to store the sessions, with each slot in the table corresponding to a specific range of IDs. This allows for fast lookups and efficient usage of memory. The `insertSession`, `updateSession`, and `removeSession` functions use the same locking mechanism as the `querySession` function to ensure thread safety.

The `trackSessionActivity` function is used to track session activity and provide accurate reports. It uses a similar locking mechanism as the other functions to ensure that the data remains consistent during updates. The `time_t last_active` field in the `Session` structure is used to keep track of when each session was last active, allowing for efficient querying of sessions based on their last active timestamp.

