// Function to allocate memory for arrays of long and int values, initialize them, and validate their initialization
int init_arrays(long *offsets, int *keys, int num_records) {
  // Allocate memory for the arrays
  offsets = malloc(sizeof(long) * num_records);
  keys = malloc(sizeof(int) * num_records);

  // Initialize the arrays with random values within a specified range
  srand(time(NULL));
  for (int i = 0; i < num_records; i++) {
    offsets[i] = rand() % 10000;
    keys[i] = rand() % 10000;
  }

  // Validate that the arrays are correctly initialized
  for (int i = 0; i < num_records; i++) {
    if (offsets[i] == 0 || keys[i] == 0) {
      return -1;
    }
  }

  // Sort the records in ascending order based on their int values
  for (int i = 0; i < num_records - 1; i++) {
    for (int j = i + 1; j < num_records; j++) {
      if (keys[i] > keys[j]) {
        int temp = keys[i];
        keys[i] = keys[j];
        keys[j] = temp;
      }
    }
  }

  // Return the number of records initialized successfully
  return num_records;
}

// Function to sort the records in descending order based on their int values
void sort_records(Record *records, int num_records) {
  for (int i = 0; i < num_records - 1; i++) {
    for (int j = i + 1; j < num_records; j++) {
      if (records[i].value > records[j].value) {
        Record temp = records[i];
        records[i] = records[j];
        records[j] = temp;
      }
    }
  }
}

// Function to handle potential memory allocation failures gracefully and provide informative error messages or fallback behaviors
void *safe_malloc(size_t size) {
  void *ptr = malloc(size);
  if (ptr == NULL) {
    fprintf(stderr, "Memory allocation failed. Falling back to alternative method.\n");
    ptr = calloc(size, sizeof(char));
    if (ptr == NULL) {
      fprintf(stderr, "Alternative memory allocation method also failed. Exiting program.\n");
      exit(1);
    }
  }
  return ptr;
}

