// Function to dynamically create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void populateNFAPICrcIndicationList(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Check if the list has exceeded its capacity
    if (list->count >= list->capacity) {
        // Dynamically resize the list by 50% to prevent frequent resizing
        size_t newCapacity = list->capacity + (list->capacity >> 1);
        NFAPI_CRC_INDICATION_PDU_T *newElements = realloc(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * newCapacity);
        if (!newElements) {
            // Handle memory allocation failure
            printf("Error: failed to resize NFAPI CRC indication list\n");
            return;
        }
        list->elements = newElements;
        list->capacity = newCapacity;
    }

    // Generate random RNTIs and CRCFLAGS
    srand(time(NULL));
    for (size_t i = 0; i < 1000; ++i) {
        uint32_t rnti = rand() % 10000;
        bool crcflag = (bool)(rand() % 2);

        // Check if the RNTI is unique within the list
        for (size_t j = 0; j < list->count; ++j) {
            if (list->elements[j].RNTI == rnti) {
                --i; // Try again with a new RNTI
                break;
            }
        }
        if (i < 1000) {
            list->elements[list->count].RX_UE_INFORMATION_TAG = 1;
            list->elements[list->count].RNTI = rnti;
            list->elements[list->count].CRC_INDICATION_REL8_TAG = 1;
            list->elements[list->count].CRCFLAG = crcflag;
            ++list->count;
        } else {
            printf("Error: unable to populate NFAPI CRC indication list with unique RNTIs\n");
            return;
        }
    }
}
