void allocateMemory(int numCounters, int numTimestamps, int numEvents, int maxSize) {
	// Dynamic memory allocation for counters, timestamps, and events
	int* counterPtr = (int*)malloc(numCounters * sizeof(int));
	if (counterPtr == NULL) {
		printf("Error: Failed to allocate memory for counter array\n");
	}

	long long* timestampPtr = (long long*)malloc(numTimestamps * sizeof(long long));
	if (timestampPtr == NULL) {
		printf("Error: Failed to allocate memory for timestamp array\n");
	}

	struct EventRecord* eventRecords = (struct EventRecord*)malloc(numEvents * sizeof(struct EventRecord));
	if (eventRecords == NULL) {
		printf("Error: Failed to allocate memory for event record array\n");
	}

	// Memory pool allocation for performance-critical sections of the code
	int* counterPool = (int*)calloc(maxSize, sizeof(int));
	long long* timestampPool = (long long*)calloc(maxSize, sizeof(long long));
	struct EventRecord* eventPool = (struct EventRecord*)calloc(maxSize, sizeof(struct EventRecord));

	// Error handling and feedback to user
	if (counterPtr == NULL || timestampPtr == NULL || eventRecords == NULL) {
		printf("Error: Insufficient memory available for allocation\n");
		return;
	}

	// Initialize memory pool and counters
	for (int i = 0; i < maxSize; i++) {
		counterPool[i] = 0;
		timestampPool[i] = 0;
		eventPool[i].timestamp = 0;
		eventPool[i].eventType = 0;
		eventPool[i].priorityLevel = 0;
	}

	// Memory management for dynamic arrays
	counterPtr = counterPool;
	timestampPtr = timestampPool;
	eventRecords = eventPool;

	// Release memory pool when not in use
	free(counterPool);
	free(timestampPool);
	free(eventPool);
}

void logEvent(struct EventRecord* event, int numEvents) {
	// Update counters and timestamps based on event type
	if (event->eventType == 1) {
		counterPtr[0]++;
		timestampPtr[0] = event->timestamp;
	} else if (event->eventType == 2) {
		counterPtr[1]++;
		timestampPtr[1] = event->timestamp;
	} else if (event->eventType == 3) {
		counterPtr[2]++;
		timestampPtr[2] = event->timestamp;
	}

	// Write event record to memory pool
	if (eventRecords != NULL) {
		eventRecords[numEvents].timestamp = event->timestamp;
		eventRecords[numEvents].eventType = event->eventType;
		eventRecords[numEvents].priorityLevel = event->priorityLevel;
	}
}

void releaseMemory() {
	// Release memory pool when not in use
	free(counterPtr);
	free(timestampPtr);
	free(eventRecords);
}

void printLog() {
