	printf("Timestamp 2: %lld\n", timestampPtr[1]);
	printf("Timestamp 3: %lld\n", timestampPtr[2]);
}

void printError() {
	// Print error message to console
	printf("Error: Insufficient memory available for allocation\n");
}']

