    uint8_t crc_indication_rel8_tag; // CRC_INDICATION_REL8_TAG
    bool crcflag; // CRCFLAG
} nfapi_crc_indication_pdu_t;

// Dynamic array to hold the CRC indications
static nfapi_crc_indication_pdu_t *crc_array = NULL;
static size_t crc_array_size = 0; // current size of the array

// Function to add a new element to the dynamic array
void add_element(uint8_t rx_ue_information_tag, uint16_t rnti, bool crcflag) {
    // Check if the array is full
    if (crc_array_size == MAX_ARRAY_SIZE) {
        printf("Error: CRC array is full\n");
        return;
    }

    // Allocate memory for a new element
    nfapi_crc_indication_pdu_t *new_element = malloc(sizeof(nfapi_crc_indication_pdu_t));
    if (new_element == NULL) {
        printf("Error: Failed to allocate memory for new CRC element\n");
        return;
    }

    // Initialize the fields of the new element
    new_element->rx_ue_information_tag = rx_ue_information_tag;
    new_element->rnti = rnti;
    new_element->crc_indication_rel8_tag = 0;
    new_element->crcflag = crcflag;

    // Add the new element to the array
    crc_array[crc_array_size++] = new_element;
}

// Function to remove an element from the dynamic array by index
void remove_element(size_t index) {
    // Check if the index is valid
    if (index >= crc_array_size) {
        printf("Error: Index out of range\n");
        return;
    }

    // Free the memory used by the element to be removed
    free(crc_array[index]);

    // Shift all elements after the index to fill the gap
    for (size_t i = index; i < crc_array_size - 1; i++) {
        crc_array[i] = crc_array[i + 1];
    }

    // Decrement the size of the array
    crc_array_size--;
}

// Function to update an element in the dynamic array based on RNTI
void update_element(uint16_t rnti, bool crcflag) {
    // Find the index of the element with the given RNTI
    size_t index = 0;
    while (index < crc_array_size && crc_array[index]->rnti != rnti) {
        index++;
    }

    // Check if the element was found
    if (index >= crc_array_size) {
        printf("Error: No CRC element with RNTI %u found\n", rnti);
        return;
    }

    // Update the CRCFLAG field of the element
    crc_array[index]->crcflag = crcflag;
}

// Function to recalculate the CRC for all elements in the dynamic array and compare it with the stored value
void validate_integrity() {
    // Recalculate the CRC for each element in the array
    for (size_t i = 0; i < crc_array_size; i++) {
        nfapi_crc_indication_pdu_t *element = crc_array[i];
        uint16_t recalculated_crc = calculate_crc(element->rx_ue_information_tag, element->rnti);
        if (recalculated_crc != element->crc_indication_rel8_tag) {
            printf("Error: CRC integrity check failed for element %zu\n", i);
        }
    }
}

// Function to calculate the CRC for a given RX UE information and RNTI
uint16_t calculate_crc(uint8_t rx_ue_information_tag, uint16_t rnti) {
    // Calculate the CRC for the given parameters
    uint16_t crc = 0;
    for (size_t i = 0; i < sizeof(rx_ue_information_tag); i++) {
        crc += ((uint8_t *)&rx_ue_information_tag)[i];
    }
    for (size_t i = 0; i < sizeof(rnti); i++) {
        crc += ((uint8_t *)&rnti)[i];
    }
    return crc;
}
