// Function to manage the dynamic collection of products
void manage_products(struct product* products, size_t num_products) {
    // Create an array of mutexes to protect each product in the collection
    pthread_mutex_t* product_mutexes = (pthread_mutex_t*)calloc(num_products, sizeof(pthread_mutex_t));

    // Initialize the mutexes
    for (size_t i = 0; i < num_products; ++i) {
        pthread_mutex_init(&product_mutexes[i], NULL);
    }

    // Function to add a product to the collection
    void add_product(struct product* new_product) {
        // Find an unused product in the collection
        size_t index = 0;
        while (index < num_products && products[index].name != NULL) {
            ++index;
        }

        // If no more space, resize the underlying storage and retry
        if (index == num_products) {
            // Resize the collection to twice the current size
            struct product* new_products = (struct product*)realloc(products, 2 * num_products * sizeof(struct product));
            if (new_products != NULL) {
                products = new_products;
                num_products *= 2;
            } else {
                // Failed to resize the collection, try again next time
                return;
            }
        }

        // Lock the product mutex
        pthread_mutex_lock(&product_mutexes[index]);

        // Add the new product to the collection
        products[index] = *new_product;

        // Unlock the product mutex
        pthread_mutex_unlock(&product_mutexes[index]);
    }

    // Function to remove a product from the collection
    void remove_product(struct product* product) {
        // Find the product in the collection
        size_t index = 0;
        while (index < num_products && products[index].name != NULL) {
            if (strcmp(products[index].name, product->name) == 0) {
                break;
            }
            ++index;
        }

        // If the product is not found, do nothing
        if (index == num_products || products[index].name == NULL) {
            return;
        }

        // Lock the product mutex
        pthread_mutex_lock(&product_mutexes[index]);

        // Remove the product from the collection
        free(products[index].name);
        products[index] = (struct product){};

        // Unlock the product mutex
        pthread_mutex_unlock(&product_mutexes[index]);
    }

    // Function to update a product in the collection
    void update_product(struct product* updated_product) {
        // Find the product in the collection
        size_t index = 0;
        while (index < num_products && products[index].name != NULL) {
            if (strcmp(products[index].name, updated_product->name) == 0) {
                break;
            }
            ++index;
        }

        // If the product is not found, do nothing
        if (index == num_products || products[index].name == NULL) {
            return;
        }

        // Lock the product mutex
        pthread_mutex_lock(&product_mutexes[index]);

        // Update the product in the collection
        free(products[index].name);
        products[index] = *updated_product;

        // Unlock the product mutex
        pthread_mutex_unlock(&product_mutexes[index]);
    }

    // Function to trigger a background process to resize the underlying storage
    void resize() {
        // Create a new thread to perform the resizing operation
        pthread_t resize_thread;
        if (pthread_create(&resize_thread, NULL, resize_background, NULL) != 0) {
            return;
        }

        // Detach the thread and continue with the program
        pthread_detach(resize_thread);
    }

    // Function to asynchronously resize the underlying storage of the collection
    void* resize_background(void* args) {
        // Double the size of the collection
        num_products *= 2;

        // Reallocate the memory for the products
        struct product* new_products = (struct product*)realloc(products, num_products * sizeof(struct product));
        if (new_products == NULL) {
            return NULL;
        }

        // Initialize the mutexes for the new products
        for (size_t i = 0; i < num_products; ++i) {
            pthread_mutex_init(&product_mutexes[i], NULL);
        }

        return NULL;
    }

    // Function to handle concurrent access to the collection, minimizing contention and ensuring data integrity
    void protect(size_t index) {
        pthread_mutex_lock(&product_mutexes[index]);
    }

    void unprotect(size_t index) {
        pthread_mutex_unlock(&product_mutexes[index]);
    }
}

