        } else {
            // If the key index is out of bounds, reset the value to 0
            record->value = 0;
        }
    }

    pthread_mutex_unlock(&mutex); // Unlock the mutex
}

// Function to retrieve a record from the system
Record* get_record(long offset) {
    if (offset < 0 || offset >= max_offset) {
        return NULL;
    }

    pthread_mutex_lock(&mutex); // Lock the mutex for thread-safe access

    Record* record = &records[offset];
    int key_index = record->key_index;
    if (key_index < 0 || key_index >= max_key_value) {
        return NULL;
    }

    pthread_mutex_unlock(&mutex); // Unlock the mutex
    return record;
}

// Function to release memory for the data structures
