    int random_min = 1;
    int random_max = INT_MAX - 1;
    for (size_t i = 0; i < num_events; i++) {
        (*offset_arr)[i] = rand() % (random_max - random_min + 1) + random_min;
        (*key_arr)[i] = rand() % (random_max - random_min + 1) + random_min;
        (*record_arr)[i].value = rand() % (random_max - random_min + 1) + random_min;
    }
