  pthread_mutex_lock(&mutex); // Lock the mutex
  free(customers[index].name); // Free the name string
  customers[index] = customers[customer_count - 1]; // Move the last customer to the removed position
  customer_count--; // Decrement the customer count
  pthread_cond_signal(&condition); // Signal the condition variable
  pthread_mutex_unlock(&mutex); // Unlock the mutex
}

// Function to update a customer
void update_customer(int index, const char* name, int age, double balance) {
  pthread_mutex_lock(&mutex); // Lock the mutex
  free(customers[index].name); // Free the old name string
  customers[index].name = strdup(name); // Duplicate the new name string
  customers[index].age = age;
  customers[index].balance = balance;
  pthread_cond_signal(&condition); // Signal the condition variable
  pthread_mutex_unlock(&mutex); // Unlock the mutex
}

// Function to trigger background resizing of the underlying storage
void resize() {
  pthread_mutex_lock(&mutex); // Lock the mutex
  size_t old_size = customer_count;
  customer_count += 10000; // Add the threshold
  customers = realloc(customers, sizeof(customer_t) * customer_count); // Reallocate the memory
  if (customers == NULL) { // If reallocation fails
    customer_count -= 10000; // Restore the old size
    pthread_mutex_unlock(&mutex); // Unlock the mutex
    return;
  }
  for (size_t i = old_size; i < customer_count; i++) { // Initialize the new memory
    customers[i].name = NULL;
    customers[i].age = -1;
    customers[i].balance = -1.0;
  }
  pthread_mutex_unlock(&mutex); // Unlock the mutex
}

// Function to handle real-time transaction processing
void process_transaction(order_t* order) {
  pthread_mutex_lock(&mutex); // Lock the mutex
  for (size_t i = 0; i < order->product_count; i++) { // Loop through the products
    customer_t* customer = &customers[order->customer_index];
    product_t* product = &customer->products[i];
    if (product->quantity <= 0) { // If the quantity is zero or negative
      printf("Error: Insufficient inventory for %s\n", product->sku);
      pthread_mutex_unlock(&mutex); // Unlock the mutex and return
      return;
    }
    if (product->price <= 0.0) { // If the price is zero or negative
      printf("Error: Invalid price for %s\n", product->sku);
      pthread_mutex_unlock(&mutex); // Unlock the mutex and return
      return;
    }
    customer->balance -= order->total_price; // Subtract the total price from the balance
  }
  if (customer->balance < 0.0) { // If the balance is negative
    printf("Error: Insufficient funds for %s\n", customer->name);
    pthread_mutex_unlock(&mutex); // Unlock the mutex and return
    return;
  }
  customer->balance -= order->shipping_fee; // Subtract the shipping fee from the balance
  if (customer->balance < 0.0) { // If the balance is negative after subtracting the shipping fee
    printf("Error: Insufficient funds for %s\n", customer->name);
    pthread_mutex_unlock(&mutex); // Unlock the mutex and return
    return;
  }
  printf("Successfully processed transaction for %s with balance of %.2f\n", customer->name, customer->balance);
  pthread_mutex_unlock(&mutex); // Unlock the mutex
}
