#include <stdlib.h>
#include <string.h>
#include <time.h>

// Struct for storing sensor readings and device IDs
typedef struct {
    double reading;
    char* device_id;
    time_t timestamp;
} sensor_record;

// Linked list node for storing sensor records
typedef struct node {
    sensor_record record;
    struct node* next;
} node;

// Function to insert a new sensor reading into the linked list
void insert(node** head, sensor_record* record) {
    // Create a new node and set its value
    node* new_node = (node*)malloc(sizeof(node));
    new_node->record = *record;

    // Add the new node to the front of the linked list
    new_node->next = *head;
    *head = new_node;
}

// Function to remove a sensor reading from the linked list
void delete(node** head, char* device_id) {
    // Find the node with the matching device ID
    node* current = *head;
    while (current != NULL && strcmp(current->record.device_id, device_id) != 0) {
        current = current->next;
    }

    // If the node is found, remove it from the linked list
    if (current != NULL) {
        *head = current->next;
        free(current);
    }
}

// Function to retrieve a sensor reading from the linked list
sensor_record* find(node** head, char* device_id) {
    // Find the node with the matching device ID
    node* current = *head;
    while (current != NULL && strcmp(current->record.device_id, device_id) != 0) {
        current = current->next;
    }

    // If the node is found, return its value
    if (current != NULL) {
        return &current->record;
    } else {
        return NULL;
    }
}
```
This implementation uses a linked list to store the sensor records in memory. The `insert()` function adds a new node to the front of the linked list, and the `delete()` function removes a node with a matching device ID from the linked list. The `find()` function retrieves a node with a matching device ID from the linked list, or returns NULL if no such node is found.

