void manage_file_system_records(int N) {
    // Create a memory pool for reusing FILE_SYSTEM_RECORD_T structures
    FILE_SYSTEM_RECORD_T *memory_pool = NULL;
    size_t memory_pool_size = 0;

    // Initialize the memory pool and allocate memory for N records
    if (N > 0) {
