void hashTableResize(HashTable *table, int new_size);
int hash(char *key);
int hashTableGet(HashTable *table, char *key);
void hashTablePut(HashTable *table, char *key, int value);
void hashTableRemove(HashTable *table, char *key);

// Define thread-safe operations for graph manipulation and logging
pthread_mutex_t graphMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

