void initGraph(Graph *graph) {
    pthread_mutex_lock(&graphMutex);
    graph->vertices[GRAPH_MAX_VERTICES] = NULL;
    graph->edges[GRAPH_MAX_EDGES] = NULL;
    customAllocatorInit();
    hashTableResize(graph->edgeWeights, GRAPH_MAX_EDGES);
    pthread_mutex_unlock(&graphMutex);
}

void destroyGraph(Graph *graph) {
    pthread_mutex_lock(&graphMutex);
    customAllocatorDestroy();
    pthread_mutex_unlock(&graphMutex);
}

void addVertex(Graph *graph, Vertex *vertex) {
    pthread_mutex_lock(&graphMutex);
    if (graph->numVertices < GRAPH_MAX_VERTICES) {
        graph->vertices[graph->numVertices++] = vertex;
    } else {
        LogEntry error = logError("Graph is full", 1);
        printf("%s\n", error.message);
    }
    pthread_mutex_unlock(&graphMutex);
}

void removeVertex(Graph *graph, int vertex_id) {
    pthread_mutex_lock(&graphMutex);
    if (vertex_id < graph->numVertices) {
        // Remove edges connected to the vertex
        for (int i = 0; i < GRAPH_MAX_EDGES; i++) {
            if (graph->edges[i] != NULL && graph->edges[i]->srcId == vertex_id) {
                removeEdge(graph, i);
            }
        }
        // Remove the vertex from the array
        for (int i = vertex_id; i < graph->numVertices - 1; i++) {
            graph->vertices[i] = graph->vertices[i + 1];
        }
        graph->numVertices--;
    } else {
        LogEntry error = logError("Vertex not found", 2);
        printf("%s\n", error.message);
    }
    pthread_mutex_unlock(&graphMutex);
}

void addEdge(Graph *graph, int src_id, int dst_id, int weight) {
    pthread_mutex_lock(&graphMutex);
    if (src_id < graph->numVertices && dst_id < graph->numVertices) {
        // Add the edge to the graph
        Edge *edge = customAllocatorMalloc(sizeof(Edge));
        edge->srcId = src_id;
        edge->dstId = dst_id;
        edge->weight = weight;
        graph->edges[graph->numEdges++] = edge;

        // Update the edge weights hash table
        char key[16];
        sprintf(key, "%d:%d", src_id, dst_id);
        int value = hashTableGet(graph->edgeWeights, key) + weight;
        hashTablePut(graph->edgeWeights, key, value);
    } else {
        LogEntry error = logError("Vertex not found", 2);
        printf("%s\n", error.message);
    }
    pthread_mutex_unlock(&graphMutex);
}

void removeEdge(Graph *graph, int edge_id) {
    pthread_mutex_lock(&graphMutex);
    if (edge_id < graph->numEdges) {
        // Remove the edge from the array
        for (int i = edge_id; i < graph->numEdges - 1; i++) {
            graph->edges[i] = graph->edges[i + 1];
        }
        graph->numEdges--;

        // Update the edge weights hash table
        Edge *edge = graph->edges[edge_id];
        char key[16];
        sprintf(key, "%d:%d", edge->srcId, edge->dstId);
        int value = hashTableGet(graph->edgeWeights, key) - edge->weight;
        hashTablePut(graph->edgeWeights, key, value);
    } else {
        LogEntry error = logError("Edge not found", 3);
        printf("%s\n", error.message);
    }
    pthread_mutex_unlock(&graphMutex);
}

int hash(char *key) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++) != '\0') {
        hash = ((hash << 5) + hash) + c;
    }
    return (int)(hash % GRAPH_MAX_EDGES);
}

int hashTableGet(HashTable *table, char *key) {
    pthread_mutex_lock(&graphMutex);
    int value = table->entries[hash(key)];
    pthread_mutex_unlock(&graphMutex);
    return value;
}

void hashTablePut(HashTable *table, char *key, int value) {
    pthread_mutex_lock(&graphMutex);
    table->entries[hash(key)] = value;
    pthread_mutex_unlock(&graphMutex);
}

void hashTableRemove(HashTable *table, char *key) {
    pthread_mutex_lock(&graphMutex);
    table->entries[hash(key)] = NULL;
    pthread_mutex_unlock(&graphMutex);
}

int hashTableResize(HashTable *table, int newSize) {
    pthread_mutex_lock(&graphMutex);
    int oldSize = table->size;
    int i;
    for (i = 0; i < oldSize; i++) {
        if (table->entries[i] != NULL) {
            char key[16];
            sprintf(key, "%d:%d", table->entries[i]->srcId, table->entries[i]->dstId);
            int value = hashTableGet(graph->edgeWeights, key) - table->entries[i]->weight;
            hashTablePut(graph->edgeWeights, key, value);
        }
    }
    table->size = newSize;
    pthread_mutex_unlock(&graphMutex);
}

int getEdgeWeight(Graph *graph, int srcId, int dstId) {
    pthread_mutex_lock(&graphMutex);
    if (srcId < graph->numVertices && dstId < graph->numVertices) {
        char key[16];
        sprintf(key, "%d:%d", srcId, dstId);
        int weight = hashTableGet(graph->edgeWeights, key);
        pthread_mutex_unlock(&graphMutex);
        return weight;
    } else {
        LogEntry error = logError("Vertex not found", 2);
        printf("%s\n", error.message);
    }
}

void writeToDisk(Graph *graph, char *filename) {
    pthread_mutex_lock(&graphMutex);
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        perror("Error opening file");
        exit(1);
