        Edge *edge = graph->edges[i];
        fscanf(file, "%d", &edge->weight);
    }

    // Close the file
    fclose(file);
    pthread_mutex_unlock(&graphMutex);
}

void printGraph(Graph *graph) {
    pthread_mutex_lock(&graphMutex);
    int i, j;
    for (i = 0; i < graph->numVertices; i++) {
