// Data structures and functions for managing user connections
typedef struct {
    char user_id[USER_ID_LENGTH];
    time_t last_active_time;
    bool is_connected;
} USER_CONNECTION_STATUS_RECORD;

typedef struct {
    size_t num_records;
    size_t capacity;
    USER_CONNECTION_STATUS_RECORD* records;
} USER_CONNECTION_STATUS_TABLE;

// Function to generate a unique user ID based on the device's MAC address
char* generate_user_id(const char* mac_address) {
    // Calculate the hashed value of the MAC address using SHA-256
    unsigned char hash[SHA256_DIGEST_LENGTH];
    sha256((unsigned char*)mac_address, strlen(mac_address), hash);

    // Convert the hashed value to a hexadecimal string representation
    char* user_id = (char*)malloc(USER_ID_LENGTH + 1);
    for (int i = 0; i < USER_ID_LENGTH; ++i) {
        snprintf(&user_id[i * 2], 3, "%02x", hash[i]);
    }
    user_id[USER_ID_LENGTH] = '\0';

    return user_id;
}

// Function to add a new record to the connection status table
void add_connection_record(USER_CONNECTION_STATUS_TABLE* table, const char* mac_address) {
    // Generate a unique user ID based on the device's MAC address
    char* user_id = generate_user_id(mac_address);

    // Check if the record already exists in the table
    for (size_t i = 0; i < table->num_records; ++i) {
        if (strcmp(table->records[i].user_id, user_id) == 0) {
            // If the record already exists, update its timestamp and return
            table->records[i].last_active_time = time(NULL);
            table->records[i].is_connected = true;
            free(user_id);
            return;
        }
    }

    // If the record does not exist, allocate memory for a new record and insert it into the table
    USER_CONNECTION_STATUS_RECORD* new_record = (USER_CONNECTION_STATUS_RECORD*)malloc(USER_CONNECTION_STATUS_RECORD_SIZE);
    strcpy(new_record->user_id, user_id);
    new_record->last_active_time = time(NULL);
    new_record->is_connected = true;
    table->records[table->num_records++] = *new_record;
    free(user_id);
    return;
}

// Function to check the connection status of a user based on their MAC address
bool is_user_connected(USER_CONNECTION_STATUS_TABLE* table, const char* mac_address) {
    // Generate a unique user ID based on the device's MAC address
    char* user_id = generate_user_id(mac_address);

    // Check if the record exists in the table and return its connection status
    for (size_t i = 0; i < table->num_records; ++i) {
        if (strcmp(table->records[i].user_id, user_id) == 0) {
            bool is_connected = table->records[i].is_connected;
            free(user_id);
            return is_connected;
        }
    }

    // If the record does not exist, return false
    free(user_id);
    return false;
}
```
