```python
import json
import threading
import time
from collections import deque

class CacheManager:
    def __init__(self, capacity=10000):
        self.capacity = capacity
        self.cache = {}
        self.lock = threading.Lock()

    def get(self, key):
        with self.lock:
            if key in self.cache:
                return self.cache[key]
            else:
                return None

    def put(self, key, value):
        with self.lock:
            self.cache[key] = value
            return True

    def delete(self, key):
        with self.lock:
            if key in self.cache:
                del self.cache[key]
                return True
            else:
                return False

class CacheNode:
    def __init__(self, cache_manager, capacity=10000):
        self.cache_manager = cache_manager
        self.capacity = capacity
        self.cache = {}
        self.lock = threading.Lock()

    def get(self, key):
        with self.lock:
            if key in self.cache:
                return self.cache[key]
            else:
                return None

    def put(self, key, value):
        with self.lock:
            self.cache[key] = value
            return True

    def delete(self, key):
        with self.lock:
            if key in self.cache:
                del self.cache[key]
                return True
            else:
                return False

class CacheCluster:
    def __init__(self, cache_nodes=[]):
        self.cache_nodes = cache_nodes
        self.lock = threading.Lock()

    def get(self, key):
        with self.lock:
            for node in self.cache_nodes:
                if key in node.cache:
                    return node.get(key)
            return None

    def put(self, key, value):
        with self.lock:
            for node in self.cache_nodes:
                if key in node.cache:
                    node.put(key, value)
                    return True
            else:
                return False

    def delete(self, key):
        with self.lock:
            for node in self.cache_nodes:
                if key in node.cache:
                    node.delete(key)
                    return True
            else:
                return False

def main():
    # Initialize the cache manager and cache nodes
    cache_manager = CacheManager()
    cache_nodes = []
    for i in range(10):
        cache_node = CacheNode(cache_manager)
        cache_nodes.append(cache_node)

    # Create a cluster of cache nodes
    cache_cluster = CacheCluster(cache_nodes)

    # Put and get data from the cache cluster
    cache_cluster.put('key1', 'value1')
    value = cache_cluster.get('key1')
    print(f'Get: {value}')

if __name__ == "__main__":
    main()
