// Mutex to protect the list of metrics from concurrent access
pthread_mutex_t metricsMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the list of metrics
void initMetrics() {
    // Allocate memory for the list of metrics
    metrics.metrics = (ResourceMonitoringMetric*)malloc(sizeof(ResourceMonitoringMetric) * 10000);
    // Initialize the count to 0
    metrics.count = 0;
