// Function to add a new metric to the list
void addMetric(uint32_t metricID, uint16_t resourceType, float currentUsagePercentage, float peakUsageHistory[], uint16_t alertThresholds[], char loggingDetails[]) {
    // Lock the mutex before modifying the list of metrics
    pthread_mutex_lock(&metricsMutex);
    // Allocate memory for the new metric
    ResourceMonitoringMetric *newMetric = (ResourceMonitoringMetric*)malloc(sizeof(ResourceMonitoringMetric));
    // Initialize the fields of the new metric
    newMetric->metricID = metricID;
    newMetric->resourceType = resourceType;
    newMetric->currentUsagePercentage = currentUsagePercentage;
    memcpy(newMetric->peakUsageHistory, peakUsageHistory, sizeof(float) * 10);
    memcpy(newMetric->alertThresholds, alertThresholds, sizeof(uint16_t) * 2);
    strncpy(newMetric->loggingDetails, loggingDetails, 50);
    // Add the new metric to the list of metrics
    metrics.metrics[metrics.count++] = newMetric;
    // Unlock the mutex after modifying the list of metrics
    pthread_mutex_unlock(&metricsMutex);
}

// Function to update a metric in the list
void updateMetric(uint32_t metricID, uint16_t resourceType, float currentUsagePercentage, float peakUsageHistory[], uint16_t alertThresholds[], char loggingDetails[]) {
    // Lock the mutex before modifying the list of metrics
    pthread_mutex_lock(&metricsMutex);
    // Find the metric with the specified ID in the list of metrics
    for (int i = 0; i < metrics.count; i++) {
        if (metrics.metrics[i]->metricID == metricID) {
            // Update the fields of the found metric
            metrics.metrics[i]->resourceType = resourceType;
            metrics.metrics[i]->currentUsagePercentage = currentUsagePercentage;
            memcpy(metrics.metrics[i]->peakUsageHistory, peakUsageHistory, sizeof(float) * 10);
            memcpy(metrics.metrics[i]->alertThresholds, alertThresholds, sizeof(uint16_t) * 2);
            strncpy(metrics.metrics[i]->loggingDetails, loggingDetails, 50);
            // Unlock the mutex after modifying the list of metrics
            pthread_mutex_unlock(&metricsMutex);
            return;
        }
    }
    // If the metric is not found, unlock the mutex and return
    pthread_mutex_unlock(&metricsMutex);
}

// Function to remove a metric from the list
void removeMetric(uint32_t metricID) {
    // Lock the mutex before modifying the list of metrics
    pthread_mutex_lock(&metricsMutex);
    // Find the metric with the specified ID in the list of metrics
    for (int i = 0; i < metrics.count; i++) {
        if (metrics.metrics[i]->metricID == metricID) {
            // Remove the found metric from the list
            memmove(metrics.metrics + i, metrics.metrics + i + 1, sizeof(ResourceMonitoringMetric*) * (metrics.count - i));
            metrics.count--;
            // Unlock the mutex after modifying the list of metrics
            pthread_mutex_unlock(&metricsMutex);
            return;
        }
    }
    // If the metric is not found, unlock the mutex and return
    pthread_mutex_unlock(&metricsMutex);
}

// Function to retrieve a metric from the list
void getMetric(uint32_t metricID, ResourceMonitoringMetric *metric) {
    // Lock the mutex before accessing the list of metrics
