#include <mutex>

// Define the data structure for storing record values
struct Record {
  int value;
};

// Define the memory management functions
class MemoryManager {
 public:
  // Constructor that sets up the memory manager with a maximum size of 1 MB
  MemoryManager(uint64_t max_size) : max_size_(max_size) {}

  // Allocate memory for a new record structure
  Record* allocateRecord() {
    // Acquire the mutex to prevent concurrent access to the memory manager
    std::unique_lock<std::mutex> lock(mutex_);

    // Check if there is enough memory available to allocate a new record
    if (available_memory_ < sizeof(Record)) {
      return nullptr;
    }

    // Allocate the memory for the new record
    Record* record = reinterpret_cast<Record*>(allocated_memory_.data());
    allocated_memory_.resize(allocated_memory_.size() + sizeof(Record));
    available_memory_ -= sizeof(Record);

    return record;
  }

  // Free memory for a record structure
  void freeRecord(Record* record) {
    // Acquire the mutex to prevent concurrent access to the memory manager
    std::unique_lock<std::mutex> lock(mutex_);

    // Check if the record is in the allocated memory pool
    auto it = std::find(allocated_memory_.begin(), allocated_memory_.end(), record);
    if (it == allocated_memory_.end()) {
      return;
    }

    // Free the memory for the record
    uint64_t index = it - allocated_memory_.begin();
    allocated_memory_.erase(it, it + 1);
    available_memory_ += sizeof(Record);
  }

 private:
  // The maximum size of the memory manager
  const uint64_t max_size_;

  // The current amount of available memory in the memory manager
  uint64_t available_memory_ = max_size_;

  // The memory pool for allocated record structures
  std::vector<Record*> allocated_memory_;

  // A mutex to prevent concurrent access to the memory manager
  std::mutex mutex_;
};

// Define the caching mechanism for frequently accessed `record` values
class RecordCache {
 public:
  // Constructor that sets up the cache with an initial size of 100 entries
  RecordCache(uint64_t max_size) : max_size_(max_size) {}

  // Allocate memory for a new `record` structure in the cache
  Record* allocateRecord() {
    // Acquire the mutex to prevent concurrent access to the cache
    std::unique_lock<std::mutex> lock(mutex_);

    // Check if there is enough space available in the cache for a new `record` structure
    if (cache_.size() >= max_size_) {
      return nullptr;
    }

    // Allocate a new `record` structure in the cache
    Record* record = reinterpret_cast<Record*>(allocated_memory_.data());
    allocated_memory_.resize(allocated_memory_.size() + sizeof(Record));
    cache_.push_back(record);

    return record;
  }

  // Free memory for a `record` structure in the cache
  void freeRecord(Record* record) {
    // Acquire the mutex to prevent concurrent access to the cache
    std::unique_lock<std::mutex> lock(mutex_);

    // Check if the `record` structure is in the cache
    auto it = std::find(cache_.begin(), cache_.end(), record);
    if (it == cache_.end()) {
      return;
    }

    // Free the memory for the `record` structure
    uint64_t index = it - cache_.begin();
    cache_.erase(it, it + 1);
    allocated_memory_.resize(allocated_memory_.size() - sizeof(Record));
  }

 private:
  // The maximum size of the cache
  const uint64_t max_size_;

  // The current amount of space available in the cache
  uint64_t available_space_ = max_size_;

  // The cache of `record` structures
  std::vector<Record*> cache_;

  // The memory pool for allocated `record` structures
  std::vector<Record*> allocated_memory_;

  // A mutex to prevent concurrent access to the cache
  std::mutex mutex_;
};

// Define the random number generation function using an external library
class RandomNumberGenerator {
 public:
  // Constructor that sets up the random number generator with a seed value
  RandomNumberGenerator(uint64_t seed) : seed_(seed) {}

  // Generate a random number within a specified range
  uint64_t generateRandomNumber(uint64_t min, uint64_t max) {
    std::mt19937 rng(seed_);
    std::uniform_int_distribution<uint64_t> distribution(min, max);
    return distribution(rng);
  }

 private:
  // The seed value for the random number generator
  const uint64_t seed_;
};
