    if (!dynamic_buffer) {
        printf("Error: Failed to allocate dynamic buffer\n");
        free(offsets);
        free(keys);
        free(records);
        exit(1);
    }

    // Update the string pointers in each record to point to the appropriate offset in the dynamic buffer
    for (int i = 0; i < num_records; i++) {
        int offset = offsets[i];
        strcpy(&dynamic_buffer[offset], records[i].str); // copy the string to the appropriate offset in the dynamic buffer
        free(records[i].str); // free the memory allocated for the original string
        records[i].str = &dynamic_buffer[offset]; // update the string pointer in the record to point to the new offset in the dynamic buffer
