    if (numRecords < 0 || numRecords > MAX_RECORDS) {
        cerr << "Error: Invalid number of records. Must be between 0 and " << MAX_RECORDS << endl;
        return;
    }

    int totalMemory = numRecords * sizeof(Record);
    if (totalMemory > MEMORY_LIMIT) {
        cerr << "Error: Total memory usage exceeds the limit of 1 MB. Reduce the number of records." << endl;
        return;
    }

    // Generate unique integer values for each record using an external random number generation library
    vector<int> keys(numRecords);
    generate(keys.begin(), keys.end(), [&] { return distrib(gen); });

    // Create a map to store the allocated records and their corresponding offsets
    unordered_map<int, long> recordMap;

    // Allocate memory for each record and store its offset in the map
    for (int i = 0; i < numRecords; ++i) {
        Record* record = new Record();
        if (!record) {
            cerr << "Error: Memory allocation failed. Retrying..." << endl;
            // If memory allocation fails, try using an alternative storage strategy (e.g., persistent database or cloud-based solution)
            continue;
        }

        record->offset = offsetof(Record, field);
        record->key = keys[i];
        record->field = 0;
        recordMap[keys[i]] = record->offset;
    }

    // Synchronize access to the map using a mutex
    lock_guard<mutex> lock(mtx);

    // Write the allocated records to disk for persistent storage
    ofstream outfile("records.txt", ios::binary | ios::out);
    if (!outfile) {
        cerr << "Error: Could not open output file." << endl;
        return;
    }

    // Write the map entries to disk in a cache-line aligned manner
    for (const auto& entry : recordMap) {
        outfile.write((char*)&entry, sizeof(entry));
    }

    // Close the output file and release any resources used by it
    outfile.close();
}
