#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

// Structure to represent a record
struct Record {
  int value;
};

// Global variables for managing memory and synchronization
long *offsets = NULL;
int *keys = NULL;
Record **records = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
size_t num_records = 0;

// Function to dynamically manage memory for arrays of long offset values, int keys, and Record structures
void *dynamically_manage_memory(size_t size) {
  // Allocate memory for the arrays
  offsets = malloc(sizeof(long) * size);
  keys = malloc(sizeof(int) * size);
  records = malloc(sizeof(Record *) * size);

  // Initialize the arrays with default values
  memset(offsets, 0, sizeof(long) * size);
  memset(keys, -1, sizeof(int) * size);
  for (size_t i = 0; i < size; i++) {
    records[i] = NULL;
  }

  // Return the allocated memory
  return records;
}

// Function to initialize a single record with a given value
void init_record(Record *rec, int value) {
  rec->value = value;
}

// Function to add a new record to the array of Records
int add_record(Record *records, int size, int value) {
  pthread_mutex_lock(&mutex);

  // Check if there is enough space in the array for the new record
  if (num_records >= size) {
    pthread_mutex_unlock(&mutex);
    return -1;
  }

  // Allocate memory for the new record
  Record *new_record = malloc(sizeof(Record));
  init_record(new_record, value);

  // Add the new record to the array and update the offset values
  records[num_records] = new_record;
  offsets[num_records] = (long)new_record - (long)records;
  keys[num_records] = num_records;

  // Increment the number of records and unlock the mutex
  num_records++;
  pthread_mutex_unlock(&mutex);

  return 0;
}

// Function to retrieve a record from the array by key
Record *get_record(int key) {
  pthread_mutex_lock(&mutex);

  // Check if the key is valid and within the range of the array
  if (key < 0 || key >= num_records) {
    pthread_mutex_unlock(&mutex);
    return NULL;
  }

  // Return the record at the specified key
  Record *record = records[key];

  // Unlock the mutex and return the record
  pthread_mutex_unlock(&mutex);
  return record;
}

// Function to delete a record from the array by key
int delete_record(int key) {
  pthread_mutex_lock(&mutex);

  // Check if the key is valid and within the range of the array
  if (key < 0 || key >= num_records) {
    pthread_mutex_unlock(&mutex);
    return -1;
  }

  // Mark the record as deleted by setting its offset to -1
  long offset = offsets[key];
  if (offset == -1) {
    pthread_mutex_unlock(&mutex);
    return -1;
  }
  Record *record = (Record *)((long)records + offset);
  record->value = -1;

  // Update the offset values for the remaining records and decrement the number of records
  size_t new_num_records = num_records - 1;
  long *new_offsets = malloc(sizeof(long) * new_num_records);
  memset(new_offsets, 0, sizeof(long) * new_num_records);
  int i = 0;
  for (int j = 0; j < num_records; j++) {
    if (j == key) continue;
    new_offsets[i] = offsets[j];
    i++;
  }
  free(offsets);
  offsets = new_offsets;

  // Unlock the mutex and return success
  pthread_mutex_unlock(&mutex);
  return 0;
}
```
