// Define the configuration object structure
typedef struct Config {
  char *name;
  int value;
  void (*function_ptr)();
} Config;

// Define a caching mechanism for frequently accessed configurations
static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
static Config *cache[MAX_CACHE_SIZE]; // Replace MAX_CACHE_SIZE with an appropriate value

Config* init_configs(Config **configs, int num_configs) {
  Config *result = NULL;
  int i;

  // Allocate memory for the configuration objects and initialize them
  result = malloc(num_configs * sizeof(Config));
  if (result == NULL) {
    return NULL;
  }

  for (i = 0; i < num_configs; i++) {
    result[i].name = strdup(configs[i].name);
    result[i].value = configs[i].value;
    result[i].function_ptr = configs[i].function_ptr;
  }

  // Allocate memory for the cache and initialize it with the configuration objects
  int cache_size = num_configs / CACHE_FACTOR; // Replace CACHE_FACTOR with an appropriate value
  cache[0] = malloc(cache_size * sizeof(Config));
  if (cache[0] == NULL) {
    return NULL;
  }

  for (i = 1; i < cache_size; i++) {
    cache[i] = result + i * CACHE_FACTOR; // Replace CACHE_FACTOR with an appropriate value
  }

  return result;
}

void free_configs(Config **configs) {
  int i;

  if (configs == NULL) {
    return;
  }

  for (i = 0; i < num_configs; i++) {
    free(configs[i].name);
  }

  free(configs);
}

Config* get_config(const char *name) {
  int i;
  Config *result = NULL;

  pthread_mutex_lock(&cache_lock);

  // Search the cache for the configuration object with the specified name
  for (i = 0; i < MAX_CACHE_SIZE; i++) {
    if (cache[i] != NULL && strcmp(name, cache[i].name) == 0) {
      result = cache[i];
      break;
    }
  }

  // If the configuration object is not found in the cache, allocate memory for it and store it in the cache
  if (result == NULL) {
    result = malloc(sizeof(Config));
    if (result != NULL) {
      result->name = strdup(name);
      result->value = -1; // Replace with an appropriate default value
      result->function_ptr = NULL; // Replace with an appropriate default value

      int cache_idx = 0;
      while (cache[cache_idx] != NULL) {
        cache_idx++;
      }

      if (cache_idx < MAX_CACHE_SIZE) {
        cache[cache_idx] = result;
      } else {
        // Evict the least frequently used configuration object from the cache to make room for the new one
        int least_frequently_used = 0;
        int frequency = INT_MAX;

        for (i = 1; i < MAX_CACHE_SIZE; i++) {
          if (cache[i] != NULL && cache[i].frequency < frequency) {
            least_frequently_used = i;
            frequency = cache[least_frequently_used].frequency;
          }
        }

        free(cache[least_frequently_used].name);
        free(cache[least_frequently_used].function_ptr);
        cache[least_frequently_used] = result;
      }
    } else {
      return NULL;
    }
  }

  // Update the frequency of the configuration object in the cache
  for (i = 0; i < MAX_CACHE_SIZE; i++) {
    if (cache[i] == result) {
      int frequency = cache[i].frequency;
      cache[i].frequency++;
      break;
    }
  }

  pthread_mutex_unlock(&cache_lock);

  return result;
}

void update_config(const char *name, int value) {
  Config *config = get_config(name);
  if (config != NULL) {
    config->value = value;
  }
}

void free_config(Config **config) {
  int i;

  if (config == NULL) {
    return;
  }

  for (i = 0; i < num_configs; i++) {
    free(config[i].name);
  }

  free(config);
}
