    bool crc_indication_rel8_tag;
} TX_POWER_REPORT_INDICATION_T;

// Structure to hold a list of TX_POWER_REPORT_INDICATION_T structures
typedef struct {
    uint16_t size;
    TX_POWER_REPORT_INDICATION_T* entries[];
} TX_POWER_REPORT_LIST_T;

// Function to manage a dynamic array of TX_POWER_REPORT_INDICATION_T structures
TX_POWER_REPORT_LIST_T* tx_power_report_list_create(uint16_t max_size) {
    // Allocate memory for the list structure and its entries array
    TX_POWER_REPORT_LIST_T* list = malloc(sizeof(TX_POWER_REPORT_LIST_T));
    list->entries = calloc(max_size, sizeof(TX_POWER_REPORT_INDICATION_T));
    list->size = 0;
    return list;
}

// Function to allocate a new entry in the TX_POWER_REPORT_LIST_T structure
TX_POWER_REPORT_INDICATION_T* tx_power_report_list_allocate(TX_POWER_REPORT_LIST_T* list) {
    // If there is space available in the list, allocate a new entry and return it
    if (list->size < max_size) {
        uint16_t index = list->size++;
        TX_POWER_REPORT_INDICATION_T* entry = &list->entries[index];
        memset(entry, 0, sizeof(TX_POWER_REPORT_INDICATION_T));
        return entry;
    } else {
        // If the list is full, try to allocate from a secondary pool (if available)
        TX_POWER_REPORT_LIST_T* secondary_pool = NULL;
        if (secondary_pool != NULL) {
            TX_POWER_REPORT_INDICATION_T* entry = tx_power_report_list_allocate(secondary_pool);
            return entry;
        } else {
            // If the secondary pool is not available, log a warning and return NULL
            printf("Warning: TX power report list is full. Cannot allocate new entry.\n");
            return NULL;
        }
    }
}

// Function to deallocate an entry in the TX_POWER_REPORT_LIST_T structure
void tx_power_report_list_deallocate(TX_POWER_REPORT_LIST_T* list, uint16_t index) {
    // If the index is valid, deallocate the entry and update the size of the list
    if (index < list->size) {
        TX_POWER_REPORT_INDICATION_T* entry = &list->entries[index];
        memset(entry, 0, sizeof(TX_POWER_REPORT_INDICATION_T));
        list->size--;
    } else {
        // If the index is invalid, log a warning and return
        printf("Warning: Invalid index. Cannot deallocate entry.\n");
    }
}

// Function to populate a new TX_POWER_REPORT_INDICATION_T structure with a unique RNTI and CRC flag
TX_POWER_REPORT_INDICATION_T* tx_power_report_list_populate(TX_POWER_REPORT_LIST_T* list, uint16_t index) {
    // If the index is valid, populate the entry with a unique RNTI and CRC flag
    if (index < list->size) {
        TX_POWER_REPORT_INDICATION_T* entry = &list->entries[index];
        uint32_t rnti;
        // Generate a random RNTI using a cryptographically secure PRNG
        if (rng_generate(&rnti) != 0) {
            printf("Error: Failed to generate random RNTI. Using default value.\n");
            rnti = 0;
        }
        entry->rnti = rnti;
        // Calculate a unique CRC flag for the RNTI using a hash function
        uint32_t crc_flag = hash(entry->rnti);
        entry->crc_indication_rel8_tag = (crc_flag == 0) ? false : true;
        return entry;
    } else {
        // If the index is invalid, log a warning and return NULL
        printf("Warning: Invalid index. Cannot populate entry.\n");
        return NULL;
    }
}

// Function to add a new TX_POWER_REPORT_INDICATION_T structure to the list
bool tx_power_report_list_add(TX_POWER_REPORT_LIST_T* list, uint16_t index) {
    // If there is space available in the list and the index is valid, add a new entry
