// Structure for storing word frequencies
typedef struct {
    char* word; // Word string
    int freq; // Frequency count
} WordFreq;

// Function to scan a directory for text files
void scanDirectory(const char* dirPath) {
    DIR *dir;
    struct dirent *ent;
    if ((dir = opendir(dirPath)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;
            // Add file to the queue for processing
        }
    } else {
        perror("Could not open directory");
        exit(EXIT_FAILURE);
    }
}

// Function to allocate memory for an array of file paths
void allocateMemoryForFiles(FileInfo** files, size_t* capacity) {
    *files = (FileInfo*)malloc(*capacity * sizeof(FileInfo));
    if (*files == NULL) {
        perror("Could not allocate memory");
        exit(EXIT_FAILURE);
    }
}

// Function to read a file and count word occurrences using a hash table
void processFile(const char* path, size_t* totalWords) {
    FILE *file = fopen(path, "r");
    if (file == NULL) {
        perror("Could not open file");
        exit(EXIT_FAILURE);
    }

    // Hash table for storing word frequencies
    WordFreq** freqTable = (WordFreq**)malloc(sizeof(WordFreq*));
    if (freqTable == NULL) {
        perror("Could not allocate memory");
        exit(EXIT_FAILURE);
    }

    // Initialize hash table with a default size
    int size = 1024;
    for (int i = 0; i < size; i++) {
        freqTable[i] = NULL;
    }

    char buffer[MAX_WORD_LENGTH + 1];
    while (fgets(buffer, MAX_WORD_LENGTH + 1, file)) {
        // Extract the word from the buffer
        int len = strlen(buffer);
        if (len > 0 && buffer[len - 1] == '\n') buffer[len - 1] = '\0';
        char* word = buffer;

        // Increment the frequency count for the word in the hash table
        int index = hash(word);
        WordFreq* freq = freqTable[index];
        if (freq == NULL) {
            freq = (WordFreq*)malloc(sizeof(WordFreq));
            if (freq == NULL) {
                perror("Could not allocate memory");
                exit(EXIT_FAILURE);
            }
            freq->word = word;
            freq->freq = 1;
            freqTable[index] = freq;
        } else if (strcmp(freq->word, word) == 0) {
            freq->freq++;
        } else {
            WordFreq* newFreq = (WordFreq*)malloc(sizeof(WordFreq));
            if (newFreq == NULL) {
                perror("Could not allocate memory");
                exit(EXIT_FAILURE);
            }
            newFreq->word = word;
            newFreq->freq = 1;
            freqTable[index] = newFreq;
        }
    }

    // Sort the hash table by frequency count and extract the top N words
    qsort(freqTable, size, sizeof(WordFreq*), compare);
    WordFreq** topWords = (WordFreq**)malloc(WORDS_TO_EXTRACT * sizeof(WordFreq*));
    if (topWords == NULL) {
        perror("Could not allocate memory");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < WORDS_TO_EXTRACT && i < size; i++) {
        topWords[i] = freqTable[i];
    }

    // Free the hash table and close the file
    for (int i = 0; i < size; i++) {
        WordFreq* freq = freqTable[i];
        if (freq != NULL) free(freq);
    }
    free(freqTable);
    fclose(file);
}

// Function to extract the top N most frequent words from a list of file paths
void extractTopNWords(FileInfo* files, size_t fileCount, WordFreq** topWords) {
    // Allocate memory for the top N words and initialize them to NULL
    for (int i = 0; i < WORDS_TO_EXTRACT; i++) {
        topWords[i] = NULL;
    }

    // Process each file and extract the top N most frequent words
    size_t totalWords = 0;
    for (int i = 0; i < fileCount; i++) {
        processFile(files[i].path, &totalWords);
    }
}

// Function to compare two WordFreq structures based on their frequency count
int compare(const void* a, const void* b) {
    WordFreq* wa = *((WordFreq**)a);
    WordFreq* wb = *((WordFreq**)b);
    return (wa->freq > wb->freq) - (wa->freq < wb->freq);
}

// Function to hash a word into an index in the hash table
int hash(char* word) {
    size_t len = strlen(word);
    int index = 0;
    for (int i = 0; i < len; i++) {
        index += word[i];
    }
    return index % size;
}

// Function to free the top N most frequent words and close the file
void cleanup() {
    // Free the hash table and close the file
    for (int i = 0; i < size; i++) {
        WordFreq* freq = freqTable[i];
        if (freq != NULL) free(freq);
    }
    free(freqTable);
    fclose(file);
}

int main() {
    // Declare and allocate memory for the array of file paths and the top N most frequent words
    FileInfo* files = NULL;
    WordFreq** topWords = NULL;
    size_t capacity = 1024;
    allocateMemoryForFiles(&files, &capacity);
    allocateMemoryForTopNWords(&topWords, WORDS_TO_EXTRACT);

    // Read the list of file paths from a text file and add them to the queue for processing
    readFilePathsFromText("file_paths.txt", &files, &capacity);

    // Extract the top N most frequent words from each file in the queue and store them in the hash table
    extractTopNWords(files, capacity, topWords);

    // Sort the hash table by frequency count and print the top N most frequent words
    qsort(topWords, WORDS_TO_EXTRACT, sizeof(WordFreq*), compare);
    for (int i = 0; i < WORDS_TO_EXTRACT; i++) {
        WordFreq* freq = topWords[i];
        if (freq != NULL) {
            printf("%s - %d\n", freq->word, freq->freq);
        }
    }

    // Clean up memory and close the file
    cleanup();

    return 0;
}
```

This code uses a hash table to store the word frequencies for each file in the queue. It also uses a separate hash table to store the top N most frequent words found across all files. The `processFile()` function reads a single file and updates the hash table with the word frequencies found in the file. The `extractTopNWords()` function iterates over each file in the queue, extracts the top N most frequent words for each file, and adds them to the hash table of top N words. Finally, the `compare()` function is used to sort the hash table by frequency count and print the top N most frequent words.

This code uses a separate function, `readFilePathsFromText()`, to read the list of file paths from a text file and add them to the queue for processing. The `allocateMemoryForFiles()` function is used to allocate memory for the array of file paths and the `allocateMemoryForTopNWords()` function is used to allocate memory for the hash table of top N words. The `cleanup()` function is used to free the memory allocated for the arrays and close the file after processing.

