    // Acquire a lock on the graph database to ensure thread-safe access
    pthread_mutex_lock(&db->mutex);

    // Find the edge between the two vertices in the graph database and remove it
    for (int i = 0; i < db->num_edges; i++) {
        if ((db->edges[i].src == src) && (db->edges[i].dst == dst)) {
