    long total_memory_usage = record_count * sizeof(Record) + (record_count * 2) * sizeof(int);
    if (total_memory_usage > OFFSET_ARRAY_SIZE + KEY_ARRAY_SIZE) {
        printf("Error: Memory usage exceeds maximum limit. Exiting...\n");
        exit(-1);
    }
}

