    // Release all allocated memory
    free(transactions);
    free(records);
}

// Main function for testing the memory management functionality
int main() {
    // Set up logging and error handling
    openlog("transaction-manager", LOG_PID, LOG_USER);
    setlogmask(LOG_UPTO(LOG_INFO));
    log_message(LOG_INFO, "Starting transaction manager");

