    for (size_t i = 0; i < n; ++i) {
        log_message(LOG_INFO, "Transaction %d: timestamp=%ld, transaction_id=%d", i, ((struct transaction*)transactions)[i].timestamp, ((struct transaction*)transactions)[i].transaction_id);
    }

    // Clean up allocated resources
    cleanup();

    return 0;
}
