    return ++crc_flag;
}

// Function to validate that a specified RNTI is within the valid range
bool validate_rnti(uint32_t rnti) {
    if (rnti < MIN_RNTI || rnti > MAX_RNTI) {
        return false;
    } else {
        return true;
    }
}

// Function to find a duplicate RNTI value in an array of structures
bool find_duplicate_rnti(NFAPI_CRC_INDICATION_PDU_T* pdu_array, int n) {
    // Initialize flag to indicate presence of duplicate RNTIs
    bool duplicate = false;

    // Iterate over each structure in the array and check for duplicate RNTIs
    int i;
    for (i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu1 = &pdu_array[i];
        for (int j = i + 1; j < n; j++) {
            NFAPI_CRC_INDICATION_PDU_T* pdu2 = &pdu_array[j];
            if (pdu1->rnti == pdu2->rnti) {
                duplicate = true;
                break;
            }
        }
    }

    // Return flag indicating presence of duplicate RNTIs
    return duplicate;
}
