#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define cache parameters
#define CACHE_SIZE 10000
#define EVICTION_POLICY LRU

typedef struct record {
    int value;
} Record;

typedef struct cache_entry {
    long offset;
    Record *record;
    pthread_mutex_t mutex;
} CacheEntry;

// Define the cache structure
struct cache {
    CacheEntry *entries[CACHE_SIZE];
    pthread_mutex_t mutex;
};

// Function to initialize the cache
void init_cache(CacheEntry **cache) {
    // Allocate memory for the cache entries
    *cache = (CacheEntry *)malloc(sizeof(CacheEntry) * CACHE_SIZE);
    if (*cache == NULL) {
        perror("Failed to allocate memory for cache");
        exit(1);
    }

    // Initialize mutexes for each cache entry
    for (int i = 0; i < CACHE_SIZE; i++) {
        pthread_mutex_init(&((*cache)[i].mutex), NULL);
    }
}

// Function to insert a new record into the cache
void insert_record(CacheEntry *cache, long offset, Record *record) {
    // Lock the mutex for the specific cache entry
    pthread_mutex_lock(&(cache[offset % CACHE_SIZE].mutex));

    // Check if the cache is full and evict the least recently used record
    if (cache->num_entries == CACHE_SIZE) {
        long lru_offset = 0;
        Record *lru_record = NULL;
        for (int i = 1; i < CACHE_SIZE; i++) {
            if (cache[i].timestamp < cache[lru_offset].timestamp) {
                lru_offset = i;
                lru_record = cache[i].record;
            }
        }
        free(lru_record);
        pthread_mutex_destroy(&(cache[lru_offset].mutex));
        memmove(cache + lru_offset, cache + (lru_offset + 1), sizeof(CacheEntry) * (CACHE_SIZE - lru_offset));
    }

    // Insert the new record into the cache
    cache[offset % CACHE_SIZE].offset = offset;
    cache[offset % CACHE_SIZE].record = record;
    pthread_mutex_unlock(&(cache[offset % CACHE_SIZE].mutex));
}

// Function to retrieve a record from the cache
Record *get_record(CacheEntry *cache, long offset) {
    // Lock the mutex for the specific cache entry
    pthread_mutex_lock(&(cache[offset % CACHE_SIZE].mutex));

    // Check if the record is present in the cache
    if (cache[offset % CACHE_SIZE].record == NULL) {
        pthread_mutex_unlock(&(cache[offset % CACHE_SIZE].mutex));
        return NULL;
    } else {
        // Return a copy of the record
        Record *result = malloc(sizeof(Record));
        memcpy(result, cache[offset % CACHE_SIZE].record, sizeof(Record));
        pthread_mutex_unlock(&(cache[offset % CACHE_SIZE].mutex));
        return result;
    }
}

// Function to update a record in the cache
void update_record(CacheEntry *cache, long offset, Record *new_record) {
    // Lock the mutex for the specific cache entry
    pthread_mutex_lock(&(cache[offset % CACHE_SIZE].mutex));

    // Check if the record is present in the cache
    if (cache[offset % CACHE_SIZE].record == NULL) {
        pthread_mutex_unlock(&(cache[offset % CACHE_SIZE].mutex));
    } else {
        free(cache[offset % CACHE_SIZE].record);
        cache[offset % CACHE_SIZE].record = new_record;
        pthread_mutex_unlock(&(cache[offset % CACHE_SIZE].mutex));
    }
}

// Function to delete a record from the cache
void delete_record(CacheEntry *cache, long offset) {
    // Lock the mutex for the specific cache entry
    pthread_mutex_lock(&(cache[offset % CACHE_SIZE].mutex));

    // Check if the record is present in the cache
    if (cache[offset % CACHE_SIZE].record == NULL) {
        pthread_mutex_unlock(&(cache[offset % CACHE_SIZE].mutex));
    } else {
        free(cache[offset % CACHE_SIZE].record);
        cache[offset % CACHE_SIZE].record = NULL;
        pthread_mutex_unlock(&(cache[offset % CACHE_SIZE].mutex));
    }
}

// Function to release the cache resources
void release_cache(CacheEntry *cache) {
    // Release all mutexes for each cache entry
    for (int i = 0; i < CACHE_SIZE; i++) {
        pthread_mutex_destroy(&(cache[i].mutex));
    }

    // Free the memory allocated for the cache entries
    free(cache);
}
