// structure to hold a MAC_PDU and its corresponding MAC header
struct mac_pdu {
  L2_MESSAGE message;
  MAC_HEADER header;
};

// dynamic array of mac_pdu structures
struct mac_pdu *mac_pdus = NULL;

// maximum number of elements in the mac_pdus array
#define MAX_MAC_PDUS 10000

// total allocated memory for the mac_pdus array
size_t total_memory = 0;

// critical section for modifying the mac_pdus array
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// initialize the function with an initial size for the mac_pdus array
void mac_pdus_init(size_t init_size) {
  // allocate memory for the mac_pdu structures
  mac_pdus = (struct mac_pdu *)calloc(init_size, sizeof(struct mac_pdu));
  if (!mac_pdus) {
    fprintf(stderr, "Error: failed to allocate memory for mac_pdus\n");
    exit(EXIT_FAILURE);
  }
  // initialize the total allocated memory
  total_memory = init_size * sizeof(struct mac_pdu);
}

// add a new MAC_PDU structure to the mac_pdus array
int mac_pdus_add(L2_MESSAGE message, MAC_HEADER header) {
  // acquire the critical section
  pthread_mutex_lock(&mutex);

  // check if there is enough space for a new structure
  if (total_memory + sizeof(struct mac_pdu) > 2 * 1024 * 1024) {
    fprintf(stderr, "Error: memory allocation failure\n");
    pthread_mutex_unlock(&mutex);
    return -1;
  }

  // allocate memory for the new structure
  struct mac_pdu *new_mac_pdu = (struct mac_pdu *)malloc(sizeof(struct mac_pdu));
  if (!new_mac_pdu) {
    fprintf(stderr, "Error: failed to allocate memory for new_mac_pdu\n");
    pthread_mutex_unlock(&mutex);
    return -1;
  }

  // initialize the new structure with the given message and header
  new_mac_pdu->message = message;
  new_mac_pdu->header = header;

  // add the new structure to the mac_pdus array
  mac_pdus[total_memory / sizeof(struct mac_pdu)] = *new_mac_pdu;

  // update the total allocated memory
  total_memory += sizeof(struct mac_pdu);

  pthread_mutex_unlock(&mutex);

  return 0;
}

// remove a MAC_PDU structure from the mac_pdus array
int mac_pdus_remove(size_t index) {
  // acquire the critical section
  pthread_mutex_lock(&mutex);

  // check if the given index is valid
  if (index >= total_memory / sizeof(struct mac_pdu)) {
    fprintf(stderr, "Error: invalid index for mac_pdus_remove\n");
    pthread_mutex_unlock(&mutex);
    return -1;
  }

  // free the memory allocated for the structure at the given index
  free(mac_pdus[index]);

  // update the total allocated memory
  total_memory -= sizeof(struct mac_pdu);

  pthread_mutex_unlock(&mutex);

  return 0;
}

// perform a statistical calculation on the MAC_PDUS within the mac_pdus array
void mac_pdus_statistics(void) {
  // acquire the critical section
  pthread_mutex_lock(&mutex);

  // check if there are any elements in the mac_pdus array
  if (total_memory == 0) {
    fprintf(stderr, "Error: no MAC_PDUS to perform statistics on\n");
    pthread_mutex_unlock(&mutex);
    return;
  }

  // initialize the statistical library
  Statistics stats = statistics_init();

  // loop over each MAC_PDU structure in the array and add its message to the statistical library
  for (size_t i = 0; i < total_memory / sizeof(struct mac_pdu); i++) {
    statistics_add(&stats, mac_pdus[i].message);
  }

  // perform the statistical calculation using the statistical library
  statistics_print(&stats);

  // free the memory allocated for the statistical library
  statistics_free(&stats);

  pthread_mutex_unlock(&mutex);
}

// filter the MAC_PDUS within the mac_pdus array based on a given predicate function
void mac_pdus_filter(int (*predicate)(L2_MESSAGE, MAC_HEADER)) {
  // acquire the critical section
  pthread_mutex_lock(&mutex);

  // check if there are any elements in the mac_pdus array
  if (total_memory == 0) {
    fprintf(stderr, "Error: no MAC_PDUS to filter\n");
    pthread_mutex_unlock(&mutex);
    return;
  }

  // loop over each MAC_PDU structure in the array and check if it should be filtered out using the predicate function
  for (size_t i = 0; i < total_memory / sizeof(struct mac_pdu); i++) {
    if (predicate(mac_pdus[i].message, mac_pdus[i].header) == -1) {
      // remove the structure from the array
      mac_pdus_remove(i);

      // decrement the index to account for the removed element
      i--;
    }
  }

  pthread_mutex_unlock(&mutex);
}

// release all allocated memory upon completion of the function
void mac_pdus_cleanup(void) {
  // acquire the critical section
  pthread_mutex_lock(&mutex);

  // loop over each MAC_PDU structure in the array and free its memory
  for (size_t i = 0; i < total_memory / sizeof(struct mac_pdu); i++) {
    free(mac_pdus[i]);
  }

  // free the memory allocated for the mac_pdus array
  free(mac_pdus);

  pthread_mutex_unlock(&mutex);
}
