#include <string.h>
#include <stdio.h>
#include <stdint.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>

// Structure to represent a single NFMMAC message
typedef struct {
    MAC_HEADER macHeader;
    SEQUENCE_NUMBER sequenceNumber;
    FRAME_CONTROL_INFO frameControlInfo;
} NFMMAC_MESSAGE_T;

// Protocol buffer-like scheme for serializing NFMMAC messages
typedef struct {
    uint8_t macHeader[4];
    uint16_t sequenceNumber;
    uint32_t frameControlInfo;
} NFMMAC_PROTOBUF;

// Custom serialization function for NFMMAC messages
void serializeNFMMACMessage(NFMMAC_MESSAGE_T *message, void *buffer) {
    // Serialize the MAC header
    memcpy(((uint8_t *) buffer) + 0, &(message->macHeader), sizeof(message->macHeader));

    // Serialize the sequence number
    memcpy(((uint8_t *) buffer) + 4, &(message->sequenceNumber), sizeof(message->sequenceNumber));

    // Serialize the frame control info
    memcpy(((uint8_t *) buffer) + 6, &(message->frameControlInfo), sizeof(message->frameControlInfo));
}

// Custom deserialization function for NFMMAC messages
void deserializeNFMMACMessage(void *buffer, NFMMAC_MESSAGE_T *message) {
    // Deserialize the MAC header
    memcpy(&(message->macHeader), ((uint8_t *) buffer) + 0, sizeof(message->macHeader));

    // Deserialize the sequence number
    memcpy(&(message->sequenceNumber), ((uint8_t *) buffer) + 4, sizeof(message->sequenceNumber));

    // Deserialize the frame control info
    memcpy(&(message->frameControlInfo), ((uint8_t *) buffer) + 6, sizeof(message->frameControlInfo));
}

// Dynamic array of NFMMAC messages for a specified number of nodes
typedef struct {
    NFMMAC_MESSAGE_T **messages;
    size_t nodeCount;
    size_t messageSize;
    semaphore_t *semaphore;
} NFMMAC_MESSAGES;

// Function to initialize an array of NFMMAC messages for a specified number of nodes
NFMMAC_MESSAGES *initNFMMACMessages(size_t nodeCount, size_t messageSize) {
    // Allocate memory for the array of messages and semaphore
    NFMMAC_MESSAGES *messages = (NFMMAC_MESSAGES *) malloc(sizeof(NFMMAC_MESSAGES));
    messages->semaphore = (semaphore_t *) malloc(sizeof(semaphore_t));

    // Initialize the semaphore to protect concurrent access
    sem_init(messages->semaphore, 0, nodeCount);

    // Allocate memory for each message in the array
    messages->messages = (NFMMAC_MESSAGE_T **) malloc(nodeCount * sizeof(NFMMAC_MESSAGE_T *));
    for (size_t i = 0; i < nodeCount; i++) {
        messages->messages[i] = (NFMMAC_MESSAGE_T *) malloc(messageSize);
    }

    // Set the node count and message size
    messages->nodeCount = nodeCount;
    messages->messageSize = messageSize;

    return messages;
}

// Function to populate an array of NFMMAC messages with random data
void populateNFMMACMessages(NFMMAC_MESSAGES *messages) {
    // Acquire the semaphore for concurrent access
    sem_wait(messages->semaphore);

    // Loop over each message in the array and populate it with random data
    for (size_t i = 0; i < messages->nodeCount; i++) {
        NFMMAC_MESSAGE_T *message = messages->messages[i];
        // Set the MAC header to a random value
        memcpy(&(message->macHeader), &(generateRandomMacHeader()), sizeof(message->macHeader));

        // Set the sequence number to a random value
        message->sequenceNumber = generateRandomSequenceNumber();

        // Set the frame control info to a random value
        message->frameControlInfo = generateRandomFrameControlInfo();
    }

    // Release the semaphore for concurrent access
    sem_post(messages->semaphore);
}

// Function to validate that all messages in an array are properly initialized
bool validateNFMMACMessages(NFMMAC_MESSAGES *messages) {
    bool valid = true;

    // Acquire the semaphore for concurrent access
    sem_wait(messages->semaphore);

    // Loop over each message in the array and check that it is properly initialized
    for (size_t i = 0; i < messages->nodeCount; i++) {
        NFMMAC_MESSAGE_T *message = messages->messages[i];
        if (message->macHeader.preambleType == 0 || message->sequenceNumber == 0 || message->frameControlInfo == 0) {
            valid = false;
        }
    }

    // Release the semaphore for concurrent access
    sem_post(messages->semaphore);

    return valid;
}

// Function to free an array of NFMMAC messages and associated memory
void destroyNFMMACMessages(NFMMAC_MESSAGES *messages) {
    // Acquire the semaphore for concurrent access
    sem_wait(messages->semaphore);

    // Loop over each message in the array and free its memory
    for (size_t i = 0; i < messages->nodeCount; i++) {
        NFMMAC_MESSAGE_T *message = messages->messages[i];
        free(message);
    }

    // Free the memory for the array and semaphore
    free(messages->messages);
    free(messages->semaphore);

    // Release the semaphore for concurrent access
    sem_post(messages->semaphore);
}

// Function to write an array of NFMMAC messages to a file
void writeNFMMACMessagesToFile(NFMMAC_MESSAGES *messages, const char *filename) {
    // Open the output file for writing
    FILE *output = fopen(filename, "wb");
    if (output == NULL) {
        printf("Failed to open output file\n");
        return;
    }

    // Loop over each message in the array and write it to the file
    size_t i;
    for (i = 0; i < messages->nodeCount; i++) {
        NFMMAC_MESSAGE_T *message = messages->messages[i];
        fwrite(message, messages->messageSize, 1, output);
    }

    // Close the output file
    fclose(output);
}

// Function to read an array of NFMMAC messages from a file
NFMMAC_MESSAGES *readNFMMACMessagesFromFile(const char *filename) {
    // Open the input file for reading
    FILE *input = fopen(filename, "rb");
    if (input == NULL) {
        printf("Failed to open input file\n");
        return NULL;
    }

    // Get the size of the file
    fseek(input, 0, SEEK_END);
    long fileSize = ftell(input);
    rewind(input);

    // Allocate memory for the array of messages and semaphore
    NFMMAC_MESSAGES *messages = (NFMMAC_MESSAGES *) malloc(sizeof(NFMMAC_MESSAGES));
    messages->semaphore = (semaphore_t *) malloc(sizeof(semaphore_t));

    // Initialize the semaphore to protect concurrent access
    sem_init(messages->semaphore, 0, 1);

    // Calculate the number of nodes and message size based on the file size
    messages->nodeCount = fileSize / (sizeof(NFMMAC_MESSAGE_T) + sizeof(int));
    messages->messageSize = sizeof(NFMMAC_MESSAGE_T);

    // Allocate memory for each message in the array
    messages->messages = (NFMMAC_MESSAGE_T **) malloc(messages->nodeCount * sizeof(NFMMAC_MESSAGE_T *));
    for (size_t i = 0; i < messages->nodeCount; i++) {
        messages->messages[i] = (NFMMAC_MESSAGE_T *) malloc(messages->messageSize);
    }

    // Read the data from the file and populate the array of messages
    size_t count = 0;
    while (fread(messages->messages[count], messages->messageSize, 1, input) == 1) {
        count++;
    }

    // Close the input file
    fclose(input);

    return messages;
}

// Function to generate a random MAC header
MAC_HEADER generateRandomMacHeader() {
    MAC_HEADER macHeader;
    macHeader.preambleType = (uint8_t) rand();
    macHeader.preambleLength = (uint16_t) rand();
    return macHeader;
}

// Function to generate a random sequence number
uint32_t generateRandomSequenceNumber() {
    uint32_t sequenceNumber = (uint32_t) rand();
    return sequenceNumber;
}

// Function to generate a random frame control info
FRAME_CONTROL_INFO generateRandomFrameControlInfo() {
    FRAME_CONTROL_INFO frameControlInfo;
    frameControlInfo.sequenceNumber = (uint16_t) rand();
    return frameControlInfo;
}

// Function to print an array of NFMMAC messages for debugging purposes
void printNFMMACMessages(NFMMAC_MESSAGES *messages) {
    size_t i, j;
    for (i = 0; i < messages->nodeCount; i++) {
        printf("Message %lu:\n", i);
        for (j = 0; j < sizeof(NFMMAC_MESSAGE_T) / sizeof(int); j++) {
            printf("%d\t", ((int *) messages->messages[i])[j]);
        }
        printf("\n");
    }
}
