// Define the structure for SYSTEM_PROCESS_INFO
typedef struct {
    int process_id;
    bool active;
    time_t timestamp;
} SYSTEM_PROCESS_INFO;

// Define the memory pool manager
struct memory_pool_manager {
    // Hash map for storing allocated addresses
    void* addresses[N];

    // Mutex to protect concurrent access to the hash map
    pthread_mutex_t mutex;
};

// Function to allocate memory for a SYSTEM_PROCESS_INFO structure
void* allocate_memory(struct memory_pool_manager* manager) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&manager->mutex);

    // Check if there is any available memory in the pool
    for (int i = 0; i < N; i++) {
        if (manager->addresses[i] != NULL) {
            // If an address is found, return it and remove it from the hash map
            void* address = manager->addresses[i];
            manager->addresses[i] = NULL;
            pthread_mutex_unlock(&manager->mutex);
            return address;
        }
    }

    // If no memory is available, allocate a new block of memory
    void* address = malloc(sizeof(SYSTEM_PROCESS_INFO));
    if (address == NULL) {
        pthread_mutex_unlock(&manager->mutex);
        return NULL;
    }

    // Add the allocated address to the hash map
    manager->addresses[i] = address;
    pthread_mutex_unlock(&manager->mutex);
    return address;
}

// Function to deallocate memory for a SYSTEM_PROCESS_INFO structure
void deallocate_memory(struct memory_pool_manager* manager, void* address) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&manager->mutex);

    // Check if the given address is in the hash map
    for (int i = 0; i < N; i++) {
        if (manager->addresses[i] == address) {
            // If found, set it to NULL and return
            manager->addresses[i] = NULL;
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
    }

    // If the address is not in the hash map, free it
    free(address);
    pthread_mutex_unlock(&manager->mutex);
}

// Function to manage a dynamic list of SYSTEM_PROCESS_INFO structures
void manage_processes(struct memory_pool_manager* manager) {
    // Initialize the array of offsets and keys for quick duplicate checks
    int offsets[N];
    int keys[N];

    // Initialize the hash map with NULL values
    for (int i = 0; i < N; i++) {
        manager->addresses[i] = NULL;
    }

    // Loop until a stop condition is reached
    while (true) {
        // Get the next available process ID and active status flag from an external source
        int process_id = get_next_process_id();
        bool active = get_process_status(process_id);

        // Check if the process is active or inactive
        if (active) {
            // If the process is active, add it to the hash map with a unique offset and key
            int offset = 0;
            while (true) {
                keys[offset] = process_id + offset * sizeof(int);
                offsets[offset] = offset;
                if (keys[offset] != keys[offsets[offset]]) {
                    break;
                }
                offset++;
            }

            // Allocate memory for the SYSTEM_PROCESS_INFO structure and set its values
            void* address = allocate_memory(manager);
            if (address == NULL) {
                // If allocation failed, handle the error gracefully
                deallocate_memory(manager, address);
                continue;
            }
            SYSTEM_PROCESS_INFO* process_info = (SYSTEM_PROCESS_INFO*) address;
            process_info->process_id = process_id;
            process_info->active = active;
            process_info->timestamp = time(NULL);
        } else {
            // If the process is inactive, remove it from the hash map
            int offset = 0;
            while (true) {
                keys[offset] = process_id + offset * sizeof(int);
                offsets[offset] = offset;
                if (keys[offset] != keys[offsets[offset]]) {
                    break;
                }
                offset++;
            }

            // Deallocate memory for the SYSTEM_PROCESS_INFO structure
            void* address = NULL;
            for (int i = 0; i < N; i++) {
                if (manager->addresses[i] != NULL && keys[offsets[i]] == process_id) {
                    address = manager->addresses[i];
                    break;
                }
            }
            deallocate_memory(manager, address);
        }

        // Monitor total memory usage to prevent resource exhaustion
        monitor_memory_usage();

        // Send alerts upon process start or stop through an external monitoring system
        send_alert(process_id, active);
    }
}
