// Define struct for holding record data
typedef struct {
    int value;
    long *offset;
    int ref_count;
} Record;

// Define struct for holding offset and key data
typedef struct {
    long *offset;
    char *key;
} OffsetKeyPair;

// Define function to initialize record with random value and CRC indication
void init_record(Record *record) {
    record->value = rand() % (MAX_RANDOM_VALUE - MIN_RANDOM_VALUE + 1) + MIN_RANDOM_VALUE;
    // Generate a unique CRC indication for the record
    char crc[8];
    sprintf(crc, "%02x%02x%02x%02x%02x%02x%02x%02x", rand() % 256, rand() % 256, rand() % 256, rand() % 256,
            rand() % 256, rand() % 256, rand() % 256, rand() % 256);
    memcpy(record->offset, crc, sizeof(long));
}

// Define function to update record reference count
void update_ref_count(Record *record) {
    pthread_mutex_lock(&record->ref_count);
    if (record->ref_count > 0) {
        --record->ref_count;
    }
    pthread_mutex_unlock(&record->ref_count);
}

// Define function to increment record reference count
void incr_ref_count(Record *record) {
    pthread_mutex_lock(&record->ref_count);
    ++record->ref_count;
    pthread_mutex_unlock(&record->ref_count);
}

// Define function to deallocate record when reference count reaches zero
void free_record(Record *record) {
    if (record->ref_count == 0) {
        free(record->offset);
        free(record);
    }
}

