// Function to process user session data
int processUserSessionData(SessionData *session, Configuration *config) {
  // Initialize variables
  int status = 0;
  pthread_t thread;
  List *notifications = NULL;

  // Validate session ID and expiration policy
  if (session->id == -1 || session->expirationPolicy != EXPIRATION_POLICY) {
    return -1;
  }

  // Initialize notification list
  notifications = createList();

  // Process user actions
  for (int i = 0; i < session->actionsToProcess.count; i++) {
    Action action = session->actionsToProcess[i];

    // Handle action based on expiration policy
    if (action.type == ACTION_TYPE_EXPIRATION && action.expired) {
      // Remove user session from memory
      freeSession(session);

      // Return error status
      return -1;
    } else if (action.type == ACTION_TYPE_NOTIFICATION) {
      // Add notification to list
      NotificationData *notification = createNotification(action.userId, action.id);
      addToList(notifications, notification);
    }
  }

  // Handle notifications asynchronously
  for (int i = 0; i < notifications->count && status == 0; i++) {
    NotificationData *notification = notifications[i];

    // Create thread to handle notification
    pthread_create(&thread, NULL, handleNotification, notification);

    // Join thread to wait for completion
    pthread_join(thread, NULL);
  }

  // Clean up memory
  freeList(notifications);

  return status;
}

// Function to handle notifications asynchronously
