    if (!offsets) {
        perror("Failed to allocate memory for offsets array");
        exit(EXIT_FAILURE);
    }

    // Initialize the array of int keys
    keys = malloc(sizeof(int) * total_elements);
    if (!keys) {
        perror("Failed to allocate memory for keys array");
        exit(EXIT_FAILURE);
    }

    // Initialize the array of record structures
    records = malloc(sizeof(struct record*) * total_elements);
    if (!records) {
        perror("Failed to allocate memory for records array");
        exit(EXIT_FAILURE);
    }

    // Loop to initialize each record structure
    for (int i = 0; i < total_elements; i++) {
        records[i] = malloc(sizeof(struct record));
        if (!records[i]) {
            perror("Failed to allocate memory for record structure");
            exit(EXIT_FAILURE);
        }
    }

    // Initialize the int value in each record structure to a unique random value within a specified range
    srand(time(NULL));
    for (int i = 0; i < total_elements; i++) {
        records[i]->value = rand() % RANGE + MIN_VALUE;
        if (records[i]->value == records[i-1]->value) {
            printf("Duplicate value detected. Retrying...\n");
            init_data(offsets, keys, records); // Recursively call the function to retry initialization
            return;
        }
    }

    // Enforce a check at the beginning of the function to prevent excessive resource consumption if the total number of elements across all arrays exceeds the predefined maximum threshold
    if (total_elements > MAX_ELEMENTS) {
        printf("Excessive resource consumption detected. Function terminated.\n");
        return;
    }

    // Dynamically resize the records array if the initial capacity is insufficient to accommodate all required records, optimizing for efficient memory usage without causing excessive reallocations
    if (total_elements > INITIAL_CAPACITY) {
        records = realloc(records, sizeof(struct record*) * total_elements);
        if (!records) {
            perror("Failed to reallocate memory for records array");
            exit(EXIT_FAILURE);
        }
    }

    // Integrate logging to document critical operations and error conditions
    printf("Initialized %d elements in the offsets, keys, and records arrays\n", total_elements);
}
```
