// Structure to hold record data
typedef struct {
    long timestamp;
    int status_flag;
    int value;
} record;

// Global variables for memory management
long total_memory = 500 * 1024; // 500 KB
int max_records = 10000; // maximum number of records allowed
record *records = NULL;

// Thread-safe mechanism using compare-and-swap operations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_memory(long size) {
    // Check if the requested size is within limits
    if (size > total_memory || size < 0) {
        printf("Invalid memory allocation request: %ld\n", size);
        return;
    }

    // Acquire lock on mutex
    pthread_mutex_lock(&mutex);

    // Dynamically allocate memory for the array of records
    long record_size = sizeof(record) * max_records;
    records = (record *)mmap(NULL, record_size, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
    if (records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Initialize each record with a random value within the specified range
    srand(time(NULL));
    for (int i = 0; i < max_records; i++) {
        records[i].value = rand() % (size + 1);
    }

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);
}

void free_memory() {
    // Acquire lock on mutex
    pthread_mutex_lock(&mutex);

    // Free memory for the array of records
    if (records != NULL) {
        munmap(records, sizeof(record) * max_records);
    }

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);
}

void set_value(int index, int value) {
    // Acquire lock on mutex
    pthread_mutex_lock(&mutex);

    // Check if the requested index is within limits
    if (index < 0 || index >= max_records) {
        printf("Invalid record index: %d\n", index);
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Set the value for the specified record
    records[index].value = value;

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);
}
```
