['package com.example.connectionpool;

import java.sql.Connection;
import java.sql.DriverManager;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Level;
import java.util.logging.Logger;

public class ConnectionPool {
    private static final Logger LOGGER = Logger.getLogger(ConnectionPool.class.getName());

    // Configuration variables
    private int minConnections;
    private int maxConnections;
    private int idleTimeout;
    private long cacheSize;
    private boolean validationEnabled;
    private int validationThreshold;

    // Internal data structures
    private Map<String, Connection> connections = new ConcurrentHashMap<>();
    private Map<String, Long> lastAccessedTimes = new HashMap<>();
    private Map<String, Boolean> cache = new HashMap<>();

    public ConnectionPool(int minConnections, int maxConnections, int idleTimeout, long cacheSize, boolean validationEnabled, int validationThreshold) {
        this.minConnections = minConnections;
        this.maxConnections = maxConnections;
        this.idleTimeout = idleTimeout;
        this.cacheSize = cacheSize;
        this.validationEnabled = validationEnabled;
        this.validationThreshold = validationThreshold;
    }

    public Connection getConnection(String database) throws Exception {
        // Check if the connection is in the pool and it's still valid
        if (connections.containsKey(database) && !isValid(connections.get(database))) {
            replaceConnection(database);
        }

        // If there are no connections, create a new one
        if (connections.isEmpty()) {
            addConnection(database);
        }

        // Check if the cache has a hit
        if (cache.containsKey(database) && cache.get(database)) {
            return getCachedConnection(database);
        }

        // If the cache doesn't have a hit, create a new connection and add it to the pool
        Connection connection = addConnection(database);

        // Add the connection to the cache
        cache.put(database, true);

        return connection;
    }

    public void releaseConnection(String database) {
        if (connections.containsKey(database)) {
            connections.get(database).close();
            connections.remove(database);
            lastAccessedTimes.remove(database);
            cache.remove(database);
        }
    }

    public void closeConnections() {
        for (Connection connection : connections.values()) {
            try {
                connection.close();
            } catch (Exception e) {
                LOGGER.log(Level.WARNING, "Error closing connection", e);
            }
        }
        connections.clear();
    }

    private boolean isValid(Connection connection) {
        try {
            return !connection.isClosed() && connection.isValid(validationThreshold);
        } catch (Exception e) {
            LOGGER.log(Level.WARNING, "Error validating connection", e);
            return false;
        }
    }

    private void replaceConnection(String database) {
        Connection oldConnection = connections.get(database);
        try {
            oldConnection.close();
        } catch (Exception e) {
            LOGGER.log(Level.WARNING, "Error closing connection", e);
        }
        addConnection(database);
    }

    private Connection addConnection(String database) {
        try {
            Class.forName("com.mysql.cj.jdbc.Driver");
            Connection connection = DriverManager.getConnection("jdbc:mysql://localhost/" + database, "root", "password");
            connections.put(database, connection);
            lastAccessedTimes.put(database, System.currentTimeMillis());
            return connection;
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error creating new connection", e);
            throw new RuntimeException("Failed to create new connection");
        }
    }

    private Connection getCachedConnection(String database) {
        return connections.get(database);
    }
}

