// Define structure for TX Power Report Indication
typedef struct {
  uint16_t rnti;
  bool crcIndicationRel8Tag;
} TX_POWER_REPORT_INDICATION_T;

// Define a memory pool for reusing TX Power Report Indication structures
static TX_POWER_REPORT_INDICATION_T *memPool = NULL;
static int memPoolSize = 0;

// Function to allocate memory for N TX Power Report Indication structures
void allocTXPowerReportIndications(int n) {
  // Check if the memory pool has enough space for N structures
  if (n > memPoolSize) {
    // If not, double the size of the memory pool and reallocate memory
    memPoolSize *= 2;
    TX_POWER_REPORT_INDICATION_T *newMemPool = realloc(memPool, sizeof(TX_POWER_REPORT_INDICATION_T) * memPoolSize);
    if (newMemPool == NULL) {
      // If memory allocation fails, handle the error and return
      printf("Error: Unable to allocate memory for TX Power Report Indications\n");
      return;
    } else {
      // Update the memory pool and its size
      memPool = newMemPool;
      memPoolSize = memPoolSize / 2;
    }
  }

  // Loop through each structure in the memory pool and populate it with a unique RNTI and CRC indication tag
  for (int i = 0; i < n; i++) {
    TX_POWER_REPORT_INDICATION_T *structPtr = &memPool[i];
    structPtr->rnti = generateUniqueRNTI();
    structPtr->crcIndicationRel8Tag = generateRandomCRC();
  }
}

// Function to deallocate memory for N TX Power Report Indication structures
void deallocTXPowerReportIndications(int n) {
  // If the memory pool is large enough, shrink it to fit the number of structures that need to be dealt with
  if (n < memPoolSize / 2) {
    memPoolSize = n * 2;
    TX_POWER_REPORT_INDICATION_T *newMemPool = realloc(memPool, sizeof(TX_POWER_REPORT_INDICATION_T) * memPoolSize);
    if (newMemPool == NULL) {
      // If memory allocation fails, handle the error and return
      printf("Error: Unable to deallocate memory for TX Power Report Indications\n");
      return;
    } else {
      // Update the memory pool and its size
      memPool = newMemPool;
      memPoolSize = memPoolSize / 2;
    }
  }
}

// Function to generate a unique RNTI for each structure in the memory pool
uint16_t generateUniqueRNTI() {
  // Initialize a random seed based on the current time
  srand(time(NULL));

  // Generate a random number between 0 and 65535 (2^16 - 1)
  uint16_t rnti = rand() & 0xFFFF;

  // Check if the RNTI has already been used in the current session
  for (int i = 0; i < memPoolSize; i++) {
    TX_POWER_REPORT_INDICATION_T *structPtr = &memPool[i];
    if (structPtr->rnti == rnti) {
      // If the RNTI has already been used, generate a new one until a unique one is found
      rnti = generateUniqueRNTI();
      break;
    }
  }

  return rnti;
}

// Function to generate a random CRC indication tag for each structure in the memory pool
