// Define the struct for TrafficEvent
typedef struct {
    uint64_t timestamp;
    uint32_t sourceID;
    uint16_t eventCode;
    uint64_t hash;
} TrafficEvent;

// Function to initialize an array of TrafficEvents with randomized event codes within a specified range
TrafficEvent* initializeEvents(int numEvents, int minEventCode, int maxEventCode) {
    // Allocate memory for the array of events
    TrafficEvent* events = (TrafficEvent*)malloc(numEvents * sizeof(TrafficEvent));
    assert(events != NULL);

    // Initialize each event with a random event code within the specified range and compute its hash value
    for (int i = 0; i < numEvents; i++) {
        events[i].timestamp = time(NULL);
        events[i].sourceID = rand() % UINT32_MAX;
        events[i].eventCode = minEventCode + (rand() % (maxEventCode - minEventCode));
        events[i].hash = computeHash(&events[i]);
    }

    // Return the pointer to the array of events
    return events;
}

// Function to compute the hash value for a TrafficEvent structure
uint64_t computeHash(TrafficEvent* event) {
    // Combine the timestamp, source ID, and event code into a single 64-bit integer using XOR
    uint64_t hash = (event->timestamp ^ event->sourceID ^ event->eventCode);
    return hash;
}

// Function to retrieve an event from the array of events based on its hash value
TrafficEvent* findEvent(TrafficEvent* events, uint64_t hash) {
    // Iterate over the events and compare their hash values with the given hash
    for (int i = 0; i < numEvents; i++) {
        if (events[i].hash == hash) {
            return &events[i];
        }
    }
    return NULL;
}

// Function to modify an event in the array of events based on its hash value
void modifyEvent(TrafficEvent* events, uint64_t hash, int newEventCode) {
    // Find the event with the given hash and update its event code
    TrafficEvent* event = findEvent(events, hash);
    if (event != NULL) {
        event->eventCode = newEventCode;
    }
}
