    if (!key) {
        free(offset);
        return NULL;
    }

    // Allocate memory for the record array
    size_t record_size = sizeof(Record) * num_records;
    Record *record = malloc(record_size);
    if (!record) {
        free(key);
        free(offset);
        return NULL;
    }

    // Allocate memory for the age array
    size_t age_size = sizeof(int) * num_records;
    int *age = malloc(age_size);
    if (!age) {
        free(record);
        free(key);
        free(offset);
        return NULL;
    }

    // Initialize the offset array with sequential values starting at 0
    for (int i = 0; i < num_records; ++i) {
        offset[i] = i * sizeof(Record);
    }

    // Initialize the key array with random integers between the lower and upper bounds
    srand(seed);
    for (int i = 0; i < num_records; ++i) {
        key[i] = rand() % (upper_bound - lower_bound + 1) + lower_bound;
    }

    // Initialize the record array with random values and timestamps
    for (int i = 0; i < num_records; ++i) {
        Record *current = &record[i];
        current->key = key[i];
        current->timestamp = time(NULL);
        // Initialize the buffer to null bytes
        memset(current->buffer, '\0', sizeof(current->buffer));
    }

    // Initialize the age array with 0 for all records
    for (int i = 0; i < num_records; ++i) {
        age[i] = 0;
    }

    // Create a pointer to a struct containing the initialized arrays
    struct record_struct {
        long *offset;
        int *key;
        Record *record;
        int *age;
    };
    struct record_struct *result = malloc(sizeof(*result));
    result->offset = offset;
    result->key = key;
    result->record = record;
    result->age = age;

    return result;
}

// Free the memory allocated for the arrays in the struct
void free_records(struct record_struct *ptr) {
    if (ptr) {
        free(ptr->offset);
        free(ptr->key);
        free(ptr->record);
        free(ptr->age);
        free(ptr);
    }
}
