// Define the maximum number of structures to allocate at a time
#define MAX_STRUCTURES 1000

// Define the cache size for storing temporary structures during high-load periods
#define CACHE_SIZE 100

// Function to dynamically manage a list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_list(NFAPI_CRC_INDICATION_PDU_T* list, size_t n) {
    // Create a mutex for protecting the list from concurrent access
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T* temp = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);

    // Set the cache size and create a cache for storing temporary structures during high-load periods
    int cache_size = CACHE_SIZE;
    NFAPI_CRC_INDICATION_PDU_T* cache = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * cache_size);

    // Initialize the list and cache
    memset(list, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    memset(cache, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * cache_size);

    // Define the maximum number of structures to allocate at a time
    size_t allocation_size = MAX_STRUCTURES;

    // Allocate memory for the list of structures in increments of MAX_STRUCTURES
    while (n > 0) {
        // Try allocating memory for the list of structures with a delay between retries
        temp = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * allocation_size);
        if (temp == NULL) {
            sleep(1);
            continue;
        } else {
            break;
        }
    }

    // If the initial allocation fails, try allocating memory in increments of MAX_STRUCTURES until it succeeds
    while (temp == NULL) {
        temp = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * allocation_size);
        if (temp == NULL) {
            sleep(1);
            continue;
        } else {
            break;
        }
    }

    // If the initial allocation succeeds, set the cache size and create a cache for storing temporary structures during high-load periods
    if (temp != NULL) {
        cache_size = CACHE_SIZE;
        cache = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * cache_size);
        memset(cache, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * cache_size);
    }

    // Loop through the list of structures and validate that RNTI values are unique within the list
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* current = &list[i];
        if (current->valid == 1) {
            // If the RNTI value is a duplicate, log an error message but continue populating the remaining structures
            for (int j = i + 1; j < n; j++) {
                NFAPI_CRC_INDICATION_PDU_T* next = &list[j];
                if (next->valid == 1 && next->rnti == current->rnti) {
                    printf("Duplicate RNTI value detected. Skipping structure.\n");
                    continue;
                }
            }
        }
    }

    // If the cache is not empty, flush it to the list of structures
    if (cache != NULL && cache_size > 0) {
        for (int i = 0; i < cache_size; i++) {
            NFAPI_CRC_INDICATION_PDU_T* current = &cache[i];
            if (current->valid == 1) {
                // If the RNTI value is a duplicate, log an error message but continue populating the remaining structures
                for (int j = i + 1; j < cache_size; j++) {
                    NFAPI_CRC_INDICATION_PDU_T* next = &cache[j];
                    if (next->valid == 1 && next->rnti == current->rnti) {
                        printf("Duplicate RNTI value detected. Skipping structure.\n");
                        continue;
                    }
                }
            }
        }
    }

    // Free the cache memory if it is not empty
    if (cache != NULL && cache_size > 0) {
        free(cache);
    }

    // Release the mutex lock
    pthread_mutex_unlock(&lock);
}
