void* initialize_arrays(int num_records, int lower_bound, int upper_bound, struct config *config, bool enable_checksum) {
    if (num_records <= 0) {
        return NULL;
    }

    // Allocate memory for the offset array
    long *offset = malloc(num_records * sizeof(long));
    if (!offset) {
        free(offset);
        return NULL;
    }

    // Initialize the offset array with random values between lower and upper bounds
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offset[i] = rand() % (upper_bound - lower_bound) + lower_bound;
    }

    // Allocate memory for the key array
    int *key = malloc(num_records * sizeof(int));
    if (!key) {
        free(offset);
        free(key);
        return NULL;
    }

    // Initialize the key array with random values between lower and upper bounds
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        key[i] = rand() % (upper_bound - lower_bound) + lower_bound;
    }

    // Allocate memory for the record array
    struct record *record = malloc(num_records * sizeof(struct record));
    if (!record) {
        free(offset);
        free(key);
        free(record);
        return NULL;
    }

    // Initialize the record array with random values between lower and upper bounds
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        record[i].value = rand() % (upper_bound - lower_bound) + lower_bound;
        memset(record[i].buffer, 0, sizeof(record[i].buffer));
    }

    // Allocate memory for the string array
    struct string *string = malloc(num_records * sizeof(struct string));
    if (!string) {
        free(offset);
        free(key);
        free(record);
        free(string);
        return NULL;
    }

    // Initialize the string array with concatenated keys and record values
    for (int i = 0; i < num_records; i++) {
        int length = snprintf(NULL, 0, "%d%s", key[i], record[i].value);
        string[i].data = malloc(length + 1);
        if (!string[i].data) {
            free(offset);
            free(key);
            free(record);
            free(string);
            return NULL;
        }
        length = snprintf(string[i].data, length + 1, "%d%s", key[i], record[i].value);
        string[i].length = length;
    }

    // Allocate memory for the metadata array
    struct metadata *metadata = malloc(num_records * sizeof(struct metadata));
    if (!metadata) {
        free(offset);
        free(key);
        free(record);
        free(string);
        free(metadata);
        return NULL;
    }

    // Initialize the metadata array with length and data pointers
    for (int i = 0; i < num_records; i++) {
        metadata[i].length = sizeof(struct metadata);
        metadata[i].data = malloc(sizeof(struct metadata));
        if (!metadata[i].data) {
            free(offset);
            free(key);
            free(record);
            free(string);
            free(metadata);
            return NULL;
        }
    }

    // Return a pointer to the initialized arrays
    struct init_arrays *arrays = malloc(sizeof(struct init_arrays));
    if (!arrays) {
        free(offset);
        free(key);
        free(record);
        free(string);
        free(metadata);
        return NULL;
    }
    arrays->num_records = num_records;
    arrays->offset = offset;
    arrays->key = key;
    arrays->record = record;
    arrays->string = string;
    arrays->metadata = metadata;
    return arrays;
}
