    if (*offsets == NULL) {
        printf("Memory allocation failed: offsets\n");
        return;
    }

    // Allocate memory for the key array
    *keys = (key_t*) malloc(dataset_size * sizeof(key_t));
    if (*keys == NULL) {
        printf("Memory allocation failed: keys\n");
        free(*offsets);
        return;
    }

    // Allocate memory for the record array
    *records = (record_t*) malloc(dataset_size * sizeof(record_t));
    if (*records == NULL) {
        printf("Memory allocation failed: records\n");
        free(*offsets);
        free(*keys);
        return;
    }

    // Allocate memory for the dataPoint array
