        (*offsets)[i].offset = 0;
    }

    // Initialize the key array
    int random_key = rand() % (key_max - key_min + 1) + key_min;
    for (size_t i = 0; i < dataset_size; i++) {
        (*keys)[i].key = random_key;
    }

    // Initialize the record array
    unsigned long timestamp = initial_timestamp;
    float value = min_value + (float) rand() / RAND_MAX * (max_value - min_value);
    for (size_t i = 0; i < dataset_size; i++) {
        (*records)[i].timestamp = timestamp++;
        (*records)[i].value = value;
        (*records)[i].validity_flag = true;
    }

    // Initialize the dataPoint array
    for (size_t i = 0; i < dataset_size; i++) {
        (*dataPoints)[i].time = timestamp++;
        (*dataPoints)[i].value = value;
        (*dataPoints)[i].validity_flag = true;
    }
}
