#include <errno.h>

// Define the connection structure to hold information about each connection
typedef struct DB_CONNECTION_T {
    int socket;
    long timeout;
    char state; // A = active, I = idle
} DB_CONNECTION_T;

// Define the connection pool structure to hold all connections
typedef struct CONNECTION_POOL_T {
    DB_CONNECTION_T* connections;
    int capacity;
    int size;
} CONNECTION_POOL_T;

// Initialize the connection pool from a configuration file
int initConnectionPool(const char* configFile) {
    // Open the configuration file and read its contents into memory
    FILE* fp = fopen(configFile, "r");
    if (fp == NULL) {
        printf("Failed to open configuration file: %s\n", strerror(errno));
        return -1;
    }

    // Parse the configuration file and validate its contents
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        if (strncmp(line, "MaxConnections:", strlen("MaxConnections:")) == 0) {
            int maxConns = atoi(line + strlen("MaxConnections:"));
            // Check that the maximum number of connections is valid and error-free
            if (maxConns <= 0) {
                printf("Invalid maximum number of connections in configuration file\n");
                return -1;
            }
        } else if (strncmp(line, "Timeout:", strlen("Timeout:")) == 0) {
            long timeout = atol(line + strlen("Timeout:"));
            // Check that the timeout value is valid and error-free
            if (timeout <= 0) {
                printf("Invalid timeout value in configuration file\n");
                return -1;
            }
        }
    }

    // Allocate memory for the connection pool
    CONNECTION_POOL_T* pool = malloc(sizeof(CONNECTION_POOL_T));
    if (pool == NULL) {
        printf("Failed to allocate memory for connection pool\n");
        return -1;
    }

    // Initialize the connection pool with the parsed maximum number of connections and timeout value
    pool->capacity = maxConns;
    pool->size = 0;
    pool->connections = malloc(sizeof(DB_CONNECTION_T) * pool->capacity);
    if (pool->connections == NULL) {
        printf("Failed to allocate memory for connection array\n");
        return -1;
    }

    // Initialize each connection in the pool with a timeout value and mark them as idle
    for (int i = 0; i < pool->capacity; i++) {
        pool->connections[i].socket = -1;
        pool->connections[i].timeout = timeout;
        pool->connections[i].state = 'I';
    }

    // Close the configuration file and return the connection pool pointer
    fclose(fp);
    return (int)pool;
}

// Return a connection from the pool, or create a new one if necessary
DB_CONNECTION_T* getConnection(const char* hostname, int port, const char* username, const char* password) {
    // Check that the hostname and port are valid and error-free
    if (hostname == NULL || strlen(hostname) == 0 || port <= 0) {
        printf("Invalid hostname or port\n");
        return NULL;
    }

    // Check that the username and password are valid and error-free
    if (username == NULL || strlen(username) == 0 || password == NULL || strlen(password) == 0) {
        printf("Invalid username or password\n");
        return NULL;
    }

    // Lock the connection pool to prevent concurrent access during connection creation and recycling
    pthread_mutex_lock(&pool->lock);

    // Check if there are any idle connections in the pool
    for (int i = 0; i < pool->capacity; i++) {
        if (pool->connections[i].socket == -1) {
            // Create a new connection and return it
            DB_CONNECTION_T* conn = malloc(sizeof(DB_CONNECTION_T));
            if (conn == NULL) {
                printf("Failed to allocate memory for new connection\n");
                return NULL;
            }

            // Set the socket descriptor, timeout value, and state of the new connection
            conn->socket = socket(AF_INET, SOCK_STREAM, 0);
            if (conn->socket == -1) {
                printf("Failed to create socket: %s\n", strerror(errno));
                return NULL;
            }

            struct sockaddr_in serverAddr = {
                .sin_family = AF_INET,
                .sin_port = htons(port),
                .sin_addr.s_addr = inet_addr(hostname)
            };

            if (connect(conn->socket, (struct sockaddr*)&serverAddr, sizeof(serverAddr)) == -1) {
                printf("Failed to connect to server: %s\n", strerror(errno));
                return NULL;
            }

            conn->timeout = pool->connections[i].timeout;
            conn->state = 'I';

            // Return the new connection
            pthread_mutex_unlock(&pool->lock);
            return conn;
        }
    }

    // If there are no idle connections in the pool, check if the maximum number of connections has been reached
    if (pool->size == pool->capacity) {
        // Check that the maximum number of connections is not exceeded
        printf("Maximum number of connections has been reached\n");
        return NULL;
    }

    // Create a new connection and return it
    DB_CONNECTION_T* conn = malloc(sizeof(DB_CONNECTION_T));
    if (conn == NULL) {
        printf("Failed to allocate memory for new connection\n");
        return NULL;
    }

    // Set the socket descriptor, timeout value, and state of the new connection
    conn->socket = socket(AF_INET, SOCK_STREAM, 0);
    if (conn->socket == -1) {
        printf("Failed to create socket: %s\n", strerror(errno));
        return NULL;
    }

    struct sockaddr_in serverAddr = {
        .sin_family = AF_INET,
        .sin_port = htons(port),
        .sin_addr.s_addr = inet_addr(hostname)
    };

    if (connect(conn->socket, (struct sockaddr*)&serverAddr, sizeof(serverAddr)) == -1) {
        printf("Failed to connect to server: %s\n", strerror(errno));
        return NULL;
    }

    conn->timeout = pool->connections[i].timeout;
    conn->state = 'I';

    // Increment the number of connections in the pool
    pool->size++;

    // Return the new connection
    pthread_mutex_unlock(&pool->lock);
    return conn;
}

// Release a connection back to the pool
void releaseConnection(DB_CONNECTION_T* conn) {
    // Lock the connection pool to prevent concurrent access during connection creation and recycling
    pthread_mutex_lock(&pool->lock);

    // Check if the connection is still valid
    if (conn->socket == -1 || conn->state != 'C') {
        printf("Invalid connection\n");
        return;
    }

    // Set the state of the connection to idle and decrement the number of connections in the pool
    conn->state = 'I';
    pool->size--;

    // Check if there are any other connections that can be released back to the pool
    for (int i = 0; i < pool->capacity; i++) {
        if (pool->connections[i].socket == -1 && pool->connections[i].state != 'C') {
            // Release the connection back to the pool
            pool->connections[i].socket = conn->socket;
            pool->connections[i].timeout = conn->timeout;
            pool->connections[i].state = 'I';
            break;
        }
    }

    // Close the socket and free the connection
    close(conn->socket);
    free(conn);

    // Unlock the connection pool
    pthread_mutex_unlock(&pool->lock);
}

// Return the number of connections in the pool
int getNumConnections() {
    return pool->size;
}

// Destroy the connection pool and free all allocated memory
void destroyConnectionPool() {
    // Lock the connection pool to prevent concurrent access during destruction
    pthread_mutex_lock(&pool->lock);

    // Close and free each connection in the pool
    for (int i = 0; i < pool->capacity; i++) {
        if (pool->connections[i].socket != -1) {
            close(pool->connections[i].socket);
            free(pool->connections[i].socket);
        }
    }

    // Free the connection pool and unlock it
    free(pool);
    pthread_mutex_unlock(&pool->lock);
}
