#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <chrono>
#include <fstream>
#include <filesystem>

class LogEntry {
public:
    int timestamp;
    std::string level;
    std::string message;
};

class LogProcessor {
private:
    // Map of log levels to their corresponding colors
    std::map<std::string, std::string> colorMap = {
        {"DEBUG", "31"},
        {"INFO", "32"},
        {"WARN", "33"},
        {"ERROR", "31"}
    };

    // Vector of log entries to process
    std::vector<LogEntry> logEntries;

    // File stream for writing to output file
    std::ofstream outFileStream;

    // Current timestamp for filtering log entries by time
    int currentTimestamp = 0;

    // Log level filter for filtering log entries by log level
    std::string logLevelFilter = "";

    // Message content filter for filtering log entries by message content
    std::string msgContentFilter = "";

    // Output file path and name
    std::string outputFilePath;

public:
    // Constructor to initialize the LogProcessor object
    LogProcessor(std::vector<LogEntry> logEntries, std::string outputFilePath) : logEntries(logEntries), outputFilePath(outputFilePath) {}

    // Function to process the log entries and write them to a file
    void processLogs() {
        for (auto& entry : logEntries) {
            // Filter log entries by time
            if (entry.timestamp > currentTimestamp) {
                continue;
            }

            // Filter log entries by log level
            if (!logLevelFilter.empty() && entry.level != logLevelFilter) {
                continue;
            }

            // Filter log entries by message content
            if (!msgContentFilter.empty() && !std::string::npos(entry.message, msgContentFilter)) {
                continue;
            }

            // Write the filtered log entry to the output file stream
            outFileStream << "\x1b[" + colorMap[entry.level] + "m" + entry.timestamp << " " << entry.level << " " << entry.message << "\x1b[0m\n";
        }
    }
};

int main(int argc, char** argv) {
    // Parse command-line arguments for input directories and output destinations
    std::vector<std::string> inputDirectories;
    std::string outputFilePath;
    for (int i = 1; i < argc; ++i) {
        if (argv[i][0] == '-') {
            // Argument is a command-line option
            switch (argv[i][1]) {
                case 'i':
                    inputDirectories.push_back(argv[i + 1]);
                    break;
                case 'o':
                    outputFilePath = argv[i + 1];
                    break;
            }
        } else {
            // Argument is a file path
            inputDirectories.push_back(argv[i]);
        }
    }

    // Initialize the log processor with the given input directories and output file path
    LogProcessor processor(inputDirectories, outputFilePath);

    // Process the log entries from each input directory
    for (auto& dir : inputDirectories) {
        processor.processLogs();
    }

    // Close the output file stream
    processor.outFileStream.close();

    return 0;
}']

