// Define the structure for the USER_ACTIVITY_RECORDS
typedef struct {
    int user_id;
    long session_start_time;
    long last_active_timestamp;
} user_activity_record_t;

// Define a linked list node for storing the records
typedef struct record_node {
    user_activity_record_t *record;
    struct record_node *next;
} record_node_t;

// Define a dynamic array to store the records
typedef struct {
    int capacity;
    int count;
    record_node_t *head;
    record_node_t *tail;
} dynamic_array_t;

// Define the function to manage the dynamic list of USER_ACTIVITY_RECORDS structures
void user_activity_record_list(int M, int op) {
    // Initialize the dynamic array with capacity for M records
    dynamic_array_t *arr = (dynamic_array_t *)malloc(sizeof(dynamic_array_t));
    arr->capacity = M;
    arr->count = 0;
    arr->head = NULL;
    arr->tail = NULL;

    // Initialize the semaphore for locking the dynamic array
    sem_t *sem = (sem_t *)malloc(sizeof(sem_t));
    sem_init(sem, 0, 1);

    while (true) {
        // Wait for an operation to be performed on the dynamic array
        op = wait();

        switch (op) {
            case INSERT: {
                // Lock the dynamic array and allocate a new node for the record
                sem_wait(sem);
                int new_record_id = arr->count++;
                user_activity_record_t *new_record = (user_activity_record_t *)malloc(sizeof(user_activity_record_t));
                new_record->user_id = 0;
                new_record->session_start_time = 0;
                new_record->last_active_timestamp = 0;

                // Insert the new node into the linked list
                record_node_t *new_node = (record_node_t *)malloc(sizeof(record_node_t));
                new_node->next = NULL;
                new_node->record = new_record;

                if (arr->head == NULL) {
                    arr->head = new_node;
                    arr->tail = new_node;
                } else {
                    record_node_t *last_node = arr->tail;
                    last_node->next = new_node;
                    arr->tail = new_node;
                }

                // Unlock the dynamic array and release the semaphore
                sem_post(sem);
                break;
            }

            case UPDATE: {
                // Lock the dynamic array and find the node for the given record ID
                sem_wait(sem);
                int record_id = get_record_id();
                record_node_t *node = arr->head;
                while (node != NULL) {
                    if (node->record->user_id == record_id) {
                        break;
                    }
                    node = node->next;
                }

                // Update the record and unlock the dynamic array
                if (node != NULL) {
                    user_activity_record_t *record = node->record;
                    record->user_id = get_new_user_id();
                    record->session_start_time = get_new_session_start_time();
                    record->last_active_timestamp = get_new_last_active_timestamp();
                }
                sem_post(sem);
                break;
            }

            case DELETE: {
                // Lock the dynamic array and find the node for the given record ID
                sem_wait(sem);
                int record_id = get_record_id();
                record_node_t *node = arr->head;
                while (node != NULL) {
                    if (node->record->user_id == record_id) {
                        break;
                    }
                    node = node->next;
                }

                // Delete the node and unlock the dynamic array
                if (node != NULL) {
                    user_activity_record_t *record = node->record;
                    free(record);
                    record_node_t *prev_node = node->prev;
                    prev_node->next = node->next;
                    if (arr->tail == node) {
                        arr->tail = prev_node;
                    }
                }
                sem_post(sem);
                break;
            }

            case GET_STATISTICS: {
                // Lock the dynamic array and get the number of records, total allocated memory, and number of memory allocations and deallocations
                sem_wait(sem);
                int num_records = arr->count;
                long total_allocated_memory = 0;
                int num_allocations = 0;
                int num_deallocations = 0;

                // Iterate over the linked list and calculate the statistics
                record_node_t *node = arr->head;
                while (node != NULL) {
                    total_allocated_memory += node->record->user_id + node->record->session_start_time + node->record->last_active_timestamp;
                    num_allocations++;
                    if (node->next == NULL) {
                        break;
                    }
                    node = node->next;
                }

                // Unlock the dynamic array and release the semaphore
                sem_post(sem);

                // Print the statistics to the console
                printf("Number of records: %d\n", num_records);
                printf("Total allocated memory: %ld\n", total_allocated_memory);
                printf("Number of allocations: %d\n", num_allocations);
                printf("Number of deallocations: %d\n", num_deallocations);
                break;
            }
        }
    }
}

int main() {
    // Create a new thread for the dynamic array
    pthread_t thread;
    pthread_create(&thread, NULL, dynamic_array, NULL);

    // Insert 10 records into the dynamic array
    for (int i = 0; i < 10; i++) {
        insert(i, i * 2, i * 3);
    }

    // Update the record with ID 5 in the dynamic array
    update(5, 6, 7, 8);

    // Delete the record with ID 10 from the dynamic array
    delete(10);

    // Get the statistics for the dynamic array
    get_statistics();

    // Destroy the thread and release the resources
    pthread_destroy(&thread);

    return 0;
}']

