// Function declaration
void populate_file_info(const char *dir_path, struct file_info **files, size_t *num_files) {
    // Initialize variables
    int i = 0;
    time_t curr_time = 0;
    unsigned long file_size = 0;
    struct stat st = {0};
    glob_t globbuf = {0};

    // Get the list of files in the directory
    if (glob(dir_path, GLOB_TILDE | GLOB_MARK, NULL, &globbuf)) {
        fprintf(stderr, "Error: unable to read directory\n");
        return;
    }

    // Allocate memory for the file info array
    *files = malloc(sizeof(struct file_info) * globbuf.gl_pathc);
    if (*files == NULL) {
        fprintf(stderr, "Error: unable to allocate memory\n");
        return;
    }

    // Iterate over the list of files and populate the structs with information
    for (i = 0; i < globbuf.gl_pathc; i++) {
        // Get the file stat info
        if (stat(globbuf.gl_pathv[i], &st)) {
            fprintf(stderr, "Error: unable to get file stats\n");
            continue;
        }

        // Get the last modified time and size
        curr_time = st.st_mtime;
        file_size = st.st_size;

        // Populate the struct with the information
        (*files)[i].file_path = globbuf.gl_pathv[i];
        (*files)[i].last_modified = curr_time;
        (*files)[i].file_size = file_size;
    }

    // Set the number of files in the array
    *num_files = globbuf.gl_pathc;

    // Clean up memory
    globfree(&globbuf);
}

// Example usage:
int main() {
    struct file_info *files;
    size_t num_files = 0;

    populate_file_info("/path/to/directory", &files, &num_files);

    // Use the files array and num_files variable as needed...

    return 0;
}']

