static uint32_t *process_ids = NULL;
static size_t process_ids_size = 0;
static pthread_mutex_t process_ids_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a new PROCESS_ID
uint32_t generate_process_id() {
    // Generate a random number between MIN_PROCESS_ID and MAX_PROCESS_ID
    uint32_t process_id = rand() % (MAX_PROCESS_ID - MIN_PROCESS_ID + 1) + MIN_PROCESS_ID;

    // Check if the generated PROCESS_ID is already in use
    bool duplicate = false;
    pthread_mutex_lock(&process_ids_lock);
    for (size_t i = 0; i < process_ids_size && !duplicate; i++) {
        if (process_ids[i] == process_id) {
            duplicate = true;
        }
    }
    pthread_mutex_unlock(&process_ids_lock);

    // If the generated PROCESS_ID is already in use, generate a new one until a unique one is found
    while (duplicate) {
        process_id = rand() % (MAX_PROCESS_ID - MIN_PROCESS_ID + 1) + MIN_PROCESS_ID;
        pthread_mutex_lock(&process_ids_lock);
        for (size_t i = 0; i < process_ids_size && !duplicate; i++) {
            if (process_ids[i] == process_id) {
                duplicate = true;
            }
        }
        pthread_mutex_unlock(&process_ids_lock);
    }

    return process_id;
}

// Function to allocate memory for a SYSTEM_PROCESS_INFO structure
SYSTEM_PROCESS_INFO *allocate_system_process_info() {
    // Allocate memory for the SYSTEM_PROCESS_INFO structure from the pool
    SYSTEM_PROCESS_INFO *new_info = NULL;
    pthread_mutex_lock(&pool_lock);
    if (pool_size > 0) {
        new_info = pool[--pool_size];
    }
    pthread_mutex_unlock(&pool_lock);

    // If there is no memory available in the pool, allocate a new structure from the heap
    if (!new_info) {
        new_info = malloc(sizeof(SYSTEM_PROCESS_INFO));
        if (new_info == NULL) {
            return NULL;
        }
    }

    // Initialize the newly allocated SYSTEM_PROCESS_INFO structure
    new_info->process_id = generate_process_id();
    new_info->status = PROCESS_STATUS_T(rand() % 2);
    new_info->timestamp = time(NULL);

    return new_info;
}

// Function to deallocate memory for a SYSTEM_PROCESS_INFO structure
void deallocate_system_process_info(SYSTEM_PROCESS_INFO *info) {
    // Deallocate the SYSTEM_PROCESS_INFO structure from the pool
    pthread_mutex_lock(&pool_lock);
    pool[pool_size++] = info;
    pthread_mutex_unlock(&pool_lock);
}

// Function to populate a dynamic list of SYSTEM_PROCESS_INFO structures with up to N structures
void populate_system_process_info(size_t n) {
    // Allocate memory for the dynamic list
    SYSTEM_PROCESS_INFO **list = malloc(sizeof(SYSTEM_PROCESS_INFO *) * n);
    if (list == NULL) {
        return;
    }

    // Populate the dynamic list with up to N SYSTEM_PROCESS_INFO structures
    for (size_t i = 0; i < n; i++) {
        SYSTEM_PROCESS_INFO *new_info = allocate_system_process_info();
        if (!new_info) {
            break;
        }
        list[i] = new_info;
    }

    // Deallocate any unused memory in the dynamic list
    for (size_t i = n; i < n; i++) {
        deallocate_system_process_info(list[i]);
    }
}

int main() {
    // Populate a dynamic list of SYSTEM_PROCESS_INFO structures with up to 10 structures
    populate_system_process_info(10);
    return 0;
}
