### Using a linked list data structure

A linked list is a type of data structure that consists of nodes, where each node has a reference to the next node in the list. To implement a dynamic array using a linked list, you can create a separate class for the nodes and use them to represent the elements of the array. Each node will contain a value and a reference to the next node in the list.

Here is an example of how you could implement a dynamic array using a linked list:
```c
#include <iostream>

using namespace std;

// Node class for the linked list
class Node {
public:
    int value; // Value stored in the node
    Node *next; // Reference to the next node in the list
};

// DynamicArray class that uses a linked list to represent an array
class DynamicArray {
private:
    Node *head; // Head of the linked list
public:
    DynamicArray() {
        head = NULL;
    }

    void push(int value) {
        // Create a new node with the given value and add it to the end of the linked list
        Node *new_node = new Node();
        new_node->value = value;
        if (head == NULL) {
            head = new_node;
        } else {
            Node *curr = head;
            while (curr->next != NULL) {
                curr = curr->next;
            }
            curr->next = new_node;
        }
    }

    void pop() {
        // Remove the first node from the linked list
        if (head == NULL) {
            return;
        }
        Node *temp = head;
        head = head->next;
        delete temp;
    }

    int get(int index) {
        // Return the value of the node at the given index in the linked list
        if (index < 0 || index >= size()) {
            return -1;
        }
        Node *curr = head;
        for (int i = 0; i < index; i++) {
            curr = curr->next;
        }
        return curr->value;
    }

    int size() {
        // Return the number of nodes in the linked list
        if (head == NULL) {
            return 0;
        }
        int count = 0;
        Node *curr = head;
        while (curr != NULL) {
            count++;
            curr = curr->next;
        }
        return count;
    }
};
```
