### Using a vector data structure

A vector is a type of dynamic array that uses contiguous memory to store its elements. To implement a dynamic array using a vector, you can create a separate class for the vector and use it to represent an array. The vector will have a capacity (the number of elements it can hold) and a size (the current number of elements in the vector).

Here is an example of how you could implement a dynamic array using a vector:
```c
#include <iostream>

using namespace std;

// Vector class that uses contiguous memory to store its elements
class Vector {
private:
    int *data; // Pointer to the data stored in the vector
    int capacity; // Capacity of the vector
    int size; // Size of the vector (the number of elements currently stored)
public:
    Vector(int initial_capacity = 10) {
        capacity = initial_capacity;
        size = 0;
        data = new int[capacity];
    }

    ~Vector() {
        delete[] data;
    }

    void push(int value) {
        // Grow the vector if it is full
        if (size == capacity) {
            grow();
        }

        // Add the given value to the end of the vector
        data[size++] = value;
    }

    void pop() {
        // Remove the last element from the vector
        if (size > 0) {
            size--;
        }
    }

    int get(int index) {
        // Return the value of the element at the given index in the vector
        if (index < 0 || index >= size) {
            return -1;
        }
        return data[index];
    }

    int size() {
        // Return the number of elements currently stored in the vector
        return size;
    }

private:
    void grow() {
        // Double the capacity of the vector and copy its old elements to the new array
        capacity *= 2;
        int *new_data = new int[capacity];
        for (int i = 0; i < size; i++) {
            new_data[i] = data[i];
        }
        delete[] data;
        data = new_data;
    }
};
```
