// Function to initialize and allocate memory for the three arrays
void init_memory(double **doubles, char ***strings, struct point ***points) {
    // Allocate memory for the double array
    *doubles = (double *)malloc(MAX_SIZE * sizeof(double));
    assert(*doubles != NULL);

    // Allocate memory for the char string array
