    // Allocate memory for a new node in the linked list
    node_t *new_node = (node_t *)malloc(sizeof(node_t));
    assert(new_node != NULL);

    // Allocate memory for the new struct point array in the new node
    new_node->data = (struct point *)malloc(MAX_SIZE * sizeof(struct point));
    assert(new_node->data != NULL);

    // Set the next pointer of the new node to the head of the linked list
    new_node->next = head;

    // Update the head of the linked list to point to the new node
    head = new_node;

    // Update the struct point array in the function parameter to point to the new memory location
    *points = new_node->data;
}

// Function to free the memory allocated for the three arrays
