    // Free the memory allocated for the double array
    free(*doubles);

    // Free the memory allocated for the char string array
    free(*strings);

    // Iterate through the linked list and free the memory allocated for each node
    while (head != NULL) {
        struct point *tmp = head->data;
        free(head);
        head = head->next;
        free(tmp);
    }
}
