    // Read the file into the array of Packet structures, one packet at a time
    size_t i = 0;
    while (i < num_packets) {
        // Allocate memory for the current packet and read it from the file
        Packet *current_packet = &packet_array[i];
        size_t length = fread(current_packet->data, 1, 65536, file);
        if (length <= 0) {
            break;
        }
        current_packet->length += length;
        // Update the index to read the next packet from the file
        i++;
    }
    fclose(file);
    return packet_array;
}

// Function to initialize and manage an array of Record structures
Record* record_array_init(size_t num_records) {
    // Allocate memory for the array of Record structures
    Record *record_array = malloc(num_records * sizeof(Record));
    if (!record_array) {
        perror("malloc");
        return NULL;
    }
    // Initialize each record in the array to zero values
    for (size_t i = 0; i < num_records; i++) {
        record_array[i].record_id = 0;
        record_array[i].hash_value = 0;
        record_array[i].random_int = 0;
    }
    return record_array;
}

// Function to process an array of Packet structures and generate an array of Record structures
Record* packet_process(Packet *packet_array, size_t num_packets) {
    // Initialize the priority queue for processing records
    Queue queue = NULL;
    // Process each packet in the array, one at a time
    for (size_t i = 0; i < num_packets; i++) {
        Packet *current_packet = &packet_array[i];
        size_t length = current_packet->length;
        // Allocate memory for the current record and initialize it to zero values
        Record *current_record = malloc(sizeof(Record));
        if (!current_record) {
            perror("malloc");
            return NULL;
        }
        current_record->record_id = i;
        current_record->hash_value = 0;
        current_record->random_int = rand() % 100; // Generate a random integer between 0 and 99
        // Compute the SHA-256 hash of the packet data, if necessary
        if (length > 0) {
            current_record->hash_value = sha256(current_packet->data, length);
        }
        // Enqueue the current record for processing
        queue = enqueue(queue, current_record);
    }
    return dequeue(queue);
}

// Function to compute the SHA-256 hash of a given byte array
int sha256(unsigned char *data, size_t length) {
    // Initialize the SHA-256 context and hash the data
    SHA256Context ctx;
    SHA256Init(&ctx);
    SHA256Update(&ctx, data, length);
    unsigned char *hash = malloc(32);
    if (!hash) {
        perror("malloc");
        return -1;
    }
    SHA256Final(hash, &ctx);
    // Free the temporary memory used for the hash computation
    free(hash);
    return 0;
}

// Function to release all allocated memory when the function is complete
void packet_release(Packet *packet_array, size_t num_packets) {
    // Release the memory allocated for each packet in the array
    for (size_t i = 0; i < num_packets; i++) {
        free(packet_array[i].data);
    }
}

// Function to release all allocated memory when the function is complete
void record_release(Record *record_array, size_t num_records) {
    // Release the memory allocated for each record in the array
    for (size_t i = 0; i < num_records; i++) {
        free(record_array[i].data);
    }
}
