    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
      if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
        continue; // Skip the current and parent directory
      }

      struct stat file_stat;
      char *file_path = malloc(strlen(dirs[j]) + strlen(entry->d_name) + 1);
      sprintf(file_path, "%s/%s", dirs[j], entry->d_name);
      if (lstat(file_path, &file_stat) == -1) {
        fprintf(stderr, "Error: Failed to get file status for %s\n", file_path);
        continue;
      }

      // Populate the file info structure
      (*file_infos)[i].file_path = file_path;
      (*file_infos)[i].last_modified = file_stat.st_mtime;
      (*file_infos)[i].file_size = file_stat.st_size;
      (*file_infos)[i].directory_name = dirs[j];
      // Populate additional metadata fields specific to the type of file (e.g., MIME type, creation time, etc.)

      i++;
    }
  }
}

// Function to dynamically resize buffers if necessary
void resize_buffers(struct file_info **file_infos, int num_files) {
  // Check if the current buffer size is sufficient for the new number of files
  if (num_files * sizeof(struct file_info) > (*file_infos)->size) {
    // Reallocate memory for the array of file infos
    struct file_info *new_buffer = (struct file_info *) realloc((*file_infos), num_files * sizeof(struct file_info));
    if (new_buffer == NULL) {
      fprintf(stderr, "Error: Failed to resize buffer\n");
      return;
    }
    (*file_infos) = new_buffer;
  }
}

// Function to handle potential issues during file system operations and memory allocation
void error_handling(int errno, char *operation) {
  if (errno != 0) {
    fprintf(stderr, "Error: %s failed with errno %d\n", operation, errno);
  }
}
```
In this sample code, the `init_arrays` function is used to dynamically allocate memory for and initialize arrays of file infos. The `read_files` function recursively traverses multiple specified directories and populates the file info structure with information about each file. The `resize_buffers` function dynamically resizes buffers if necessary, taking into account the impact on system performance and resource utilization. Finally, the `error_handling` function handles potential issues during file system operations and memory allocation.

It's important to note that this is just a basic implementation of reading files from multiple directories in C, and there are many other factors that need to be considered when writing robust and efficient code. For example, it's important to handle errors properly, use appropriate data structures and algorithms for searching and manipulating file information, and consider performance optimization techniques such as caching or parallelization.']

