    if (customer->num_orders == MAX_ORDERS) {
        printf("Error: maximum number of orders per customer exceeded\n");
        return false;
    }
    customer->orders[customer->num_orders++] = order;
    return true;
}

// Function to add a new transaction to the inventory system
bool add_transaction(struct transaction *transaction) {
    if (total_num_products + transaction->order.num_products > MAX_TOTAL_PRODUCTS) {
        printf("Error: maximum total number of products exceeded\n");
        return false;
    }
    for (size_t i = 0; i < transaction->customer->num_orders; i++) {
