            printf("Error: duplicate total price found in transaction\n");
            return false;
        }
    }
    if (max_total_price < transaction->order.total_price) {
        max_total_price = transaction->order.total_price;
    }
    total_num_products += transaction->order.num_products;
    num_transactions++;
    return true;
}

// Function to update the inventory system with new product data
void update_inventory(struct product *products, size_t num_products) {
    for (size_t i = 0; i < num_products; i++) {
        bool found = false;
        for (size_t j = 0; j < products[i].quantity; j++) {
            if (!add_product(create_order(products + i, 1))) {
                printf("Error: failed to add product %s\n", products[i].name);
            } else {
                found = true;
            }
        }
        if (!found) {
            printf("Warning: no more inventory available for product %s\n", products[i].name);
        }
    }
}

