    };

    // Initialize the inventory system with new product data
    update_inventory(products, sizeof(products) / sizeof(*products));

    // Define the transaction data
    struct transaction transactions[] = {
        create_transaction(create_customer("Customer A", "customer@example.com"), 0, 15),
        create_transaction(create_customer("Customer B", "customer2@example.com"), 0, 18)
    };

    // Add the transactions to the inventory system
    for (size_t i = 0; i < sizeof(transactions) / sizeof(*transactions); i++) {
