// Define a struct to represent a user session
typedef struct UserSession {
  RX_UE_INFORMATION_TAG rx_ue_information;
  RNTI crc_indication_rel8;
  bool crcflag;
} UserSession;

// Define a struct to represent a TCP connection state
typedef struct TCPConnectionState {
  int socket_descriptor;
  struct in_addr client_ip;
  ConnectionStateTag connection_state;
} TCPConnectionState;

// Define a hash table to store the user sessions and their associated TCP connection states
static HTable *user_sessions = NULL;

// Define a mutex for thread-safe access to the hash table
static pthread_mutex_t user_sessions_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new user session to the hash table and TCP connection state
void addUserSession(RX_UE_INFORMATION_TAG rx_ue_information, RNTI crc_indication_rel8, bool crcflag) {
  // Acquire lock on mutex to ensure thread-safe access
  pthread_mutex_lock(&user_sessions_mutex);

  // Allocate a new UserSession structure and set its fields
  UserSession *new_session = malloc(sizeof(UserSession));
  new_session->rx_ue_information = rx_ue_information;
  new_session->crc_indication_rel8 = crc_indication_rel8;
  new_session->crcflag = crcflag;

  // Add the new session to the hash table
  htable_put(user_sessions, &new_session->rx_ue_information.rnti, new_session);

  // Release lock on mutex
  pthread_mutex_unlock(&user_sessions_mutex);
}

// Function to remove a user session from the hash table and TCP connection state
void removeUserSession(RX_UE_INFORMATION_TAG rx_ue_information) {
  // Acquire lock on mutex to ensure thread-safe access
  pthread_mutex_lock(&user_sessions_mutex);

  // Find the session in the hash table using its RNTI field
  UserSession *session = htable_get(user_sessions, &rx_ue_information.rnti);

  // Check if the session was found
  if (session != NULL) {
    // Remove the session from the hash table
    htable_remove(user_sessions, &session->rx_ue_information.rnti);

    // Release lock on mutex
    pthread_mutex_unlock(&user_sessions_mutex);
  } else {
    // Release lock on mutex and log an error if the session was not found
    pthread_mutex_unlock(&user_sessions_mutex);
    printf("Error: User session not found.\n");
  }
}

// Function to update a user session in the hash table
void updateUserSession(RX_UE_INFORMATION_TAG rx_ue_information, RNTI crc_indication_rel8, bool crcflag) {
  // Acquire lock on mutex to ensure thread-safe access
  pthread_mutex_lock(&user_sessions_mutex);

  // Find the session in the hash table using its RNTI field
  UserSession *session = htable_get(user_sessions, &rx_ue_information.rnti);

  // Check if the session was found
  if (session != NULL) {
    // Update the fields of the session structure
    session->crc_indication_rel8 = crc_indication_rel8;
    session->crcflag = crcflag;

    // Release lock on mutex
    pthread_mutex_unlock(&user_sessions_mutex);
  } else {
    // Release lock on mutex and log an error if the session was not found
    pthread_mutex_unlock(&user_sessions_mutex);
    printf("Error: User session not found.\n");
  }
}

// Function to iterate over all user sessions in the hash table
void iterateUserSessions(void (*callback)(UserSession *)) {
  // Acquire lock on mutex to ensure thread-safe access
  pthread_mutex_lock(&user_sessions_mutex);

  // Iterate over all entries in the hash table and call the callback function for each session
  htable_iterate(user_sessions, (void (*)(void *))callback);

  // Release lock on mutex
  pthread_mutex_unlock(&user_sessions_mutex);
}

// Function to remove all user sessions from the hash table and TCP connection states
void clearUserSessions(void) {
  // Acquire lock on mutex to ensure thread-safe access
  pthread_mutex_lock(&user_sessions_mutex);

  // Remove all entries in the hash table and free all memory allocated for sessions
  htable_clear(user_sessions, (void (*)(void *))free);

  // Release lock on mutex
  pthread_mutex_unlock(&user_sessions_mutex);
}
