        systemState.txPowerReportIndications[i].CRCFlag = true;
    }
}

// Update the state of the system with new records and TX power report indications
void updateState(record_t *records, int numRecords) {
    // Lock the mutex to prevent concurrent access from multiple threads
    pthread_mutex_lock(&mutex);

    // Add the new records to the array of records
    for (int i = 0; i < numRecords; i++) {
        systemState.records[i].offset = rand() % 100 + 1;
        systemState.records[i].key = rand() % 100 + 1;
        systemState.records[i].dataPoint.timestamp = getCurrentTimestamp();
        systemState.records[i].dataPoint.value = (float)rand() / RAND_MAX * 100 - 50;
        systemState.records[i].dataPoint.validityFlag = true;
    }

    // Add the new TX power report indications to the array of TX power report indications
    for (int i = 0; i < numTxPowerReportIndications; i++) {
        systemState.txPowerReportIndications[i].RNTI = rand() % 100 + 1;
        systemState.txPowerReportIndications[i].CRCFlag = true;
    }

