    pthread_mutex_lock(&mutex);

    // Add the new TX power report indication to the array of TX power report indications
    systemState.txPowerReportIndications[numTxPowerReportIndications++] = *txPowerReportIndication;

    // Release the mutex to allow other threads to access the data structures
    pthread_mutex_unlock(&mutex);
}

// Get the current timestamp in nanoseconds
