// Data structure for storing project information
typedef struct Project {
    char* name;
    time_t deadline;
    bool status;
    double priority;
} Project;

// Linked list node for managing projects
typedef struct ProjectNode {
    Project project;
    struct ProjectNode* next;
} ProjectNode;

// Hash table for mapping indices to linked lists
typedef struct IndexMap {
    int index;
    struct ProjectNode* head;
} IndexMap;

// Mutex for synchronizing access to the data structure
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Linked list for storing projects
ProjectNode* projectListHead = NULL;

// Hash table for mapping indices to linked lists
IndexMap* indexMap = NULL;

// Function for adding a new project to the data structure
void addProject(char* name, time_t deadline, bool status, double priority) {
    // Acquire mutex lock
    pthread_mutex_lock(&mutex);

    // Create a new project node and initialize it with the given parameters
    ProjectNode* newNode = malloc(sizeof(ProjectNode));
    newNode->project.name = name;
    newNode->project.deadline = deadline;
    newNode->project.status = status;
    newNode->project.priority = priority;

    // Insert the new node at the beginning of the linked list
    newNode->next = projectListHead;
    projectListHead = newNode;

    // Update the hash table with a mapping from the index to the new node
    int index = 0;
    while (indexMap[index].head != NULL) {
        index++;
    }
    IndexMap* newIndexMap = malloc(sizeof(IndexMap));
    newIndexMap->index = index;
    newIndexMap->head = newNode;
    indexMap = realloc(indexMap, (index + 1) * sizeof(IndexMap));
    indexMap[index] = *newIndexMap;

    // Release mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function for modifying an existing project in the data structure
void modifyProject(int index, char* name, time_t deadline, bool status, double priority) {
    // Acquire mutex lock
    pthread_mutex_lock(&mutex);

    // Find the node corresponding to the given index and update its parameters
    ProjectNode* targetNode = NULL;
    for (int i = 0; i < indexMap[index].head->next; i++) {
        if (indexMap[i]->head == projectListHead) {
            targetNode = indexMap[i]->head;
            break;
        }
    }
    targetNode->project.name = name;
    targetNode->project.deadline = deadline;
    targetNode->project.status = status;
    targetNode->project.priority = priority;

    // Release mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function for removing an existing project from the data structure
void removeProject(int index) {
    // Acquire mutex lock
    pthread_mutex_lock(&mutex);

    // Find the node corresponding to the given index and delete it
    ProjectNode* targetNode = NULL;
    for (int i = 0; i < indexMap[index].head->next; i++) {
        if (indexMap[i]->head == projectListHead) {
            targetNode = indexMap[i]->head;
            break;
        }
    }
    ProjectNode* previousNode = NULL;
    for (int i = 0; i < indexMap[index].head->next; i++) {
        if (indexMap[i]->head == targetNode) {
            previousNode = indexMap[i];
            break;
        }
    }
    previousNode->next = targetNode->next;
    free(targetNode);

    // Update the hash table with a mapping from the new index to the next node after the deleted node
    int newIndex = 0;
    for (int i = 0; i < indexMap[index].head->next; i++) {
        if (indexMap[i]->head == previousNode->next) {
            newIndex = i;
            break;
        }
    }
    IndexMap* newIndexMap = malloc(sizeof(IndexMap));
    newIndexMap->index = newIndex;
    newIndexMap->head = previousNode->next;
    indexMap = realloc(indexMap, (newIndex + 1) * sizeof(IndexMap));
    indexMap[newIndex] = *newIndexMap;

    // Release mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function for serializing the data structure to a persistent storage format
void serialize() {
    // Acquire mutex lock
    pthread_mutex_lock(&mutex);

    // Create a file pointer and open it in write mode
    FILE* fp = fopen("projects.dat", "w");

    // Write the number of projects to the file
    int numProjects = projectListHead->next;
    fwrite(&numProjects, sizeof(int), 1, fp);

    // Write each project to the file in turn
    for (ProjectNode* node = projectListHead; node != NULL; node = node->next) {
        // Write the name of the project to the file
        int nameLen = strlen(node->project.name);
        fwrite(&nameLen, sizeof(int), 1, fp);
        fwrite(node->project.name, sizeof(char), nameLen, fp);

        // Write the deadline of the project to the file
        fwrite(&node->project.deadline, sizeof(time_t), 1, fp);

        // Write the status flag and priority score of the project to the file
        char status = node->project.status;
        double priority = node->project.priority;
        fwrite(&status, sizeof(char), 1, fp);
        fwrite(&priority, sizeof(double), 1, fp);
    }

    // Close the file pointer
    fclose(fp);

    // Release mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function for deserializing the data structure from a persistent storage format
void deserialize() {
    // Acquire mutex lock
    pthread_mutex_lock(&mutex);

    // Create a file pointer and open it in read mode
    FILE* fp = fopen("projects.dat", "r");

    // Read the number of projects from the file
    int numProjects;
    fread(&numProjects, sizeof(int), 1, fp);

    // Create a new linked list for storing the deserialized projects
    ProjectNode* projectListHead = NULL;

    // Read each project from the file in turn and add it to the linked list
    for (int i = 0; i < numProjects; i++) {
        // Read the name of the project from the file
        int nameLen;
        fread(&nameLen, sizeof(int), 1, fp);
        char* name = malloc(nameLen * sizeof(char));
        fread(name, sizeof(char), nameLen, fp);

        // Read the deadline of the project from the file
        time_t deadline;
        fread(&deadline, sizeof(time_t), 1, fp);

        // Read the status flag and priority score of the project from the file
        char status;
        double priority;
        fread(&status, sizeof(char), 1, fp);
        fread(&priority, sizeof(double), 1, fp);

        // Create a new node for the project and add it to the linked list
        ProjectNode* node = malloc(sizeof(ProjectNode));
        node->project.name = name;
        node->project.deadline = deadline;
        node->project.status = status;
        node->project.priority = priority;
        node->next = projectListHead;
        projectListHead = node;
    }

    // Close the file pointer and release mutex lock
    fclose(fp);
    pthread_mutex_unlock(&mutex);
}

int main() {
    // Initialize the data structure with some sample projects
    ProjectNode* projectListHead = NULL;
    for (int i = 0; i < 5; i++) {
        char name[20];
        sprintf(name, "Project %d", i);
        Project project = {.name = name, .deadline = time(NULL) + i * 86400};
        ProjectNode* node = malloc(sizeof(ProjectNode));
        node->project = project;
        node->next = projectListHead;
        projectListHead = node;
    }

    // Serialize the data structure to a persistent storage format
    serialize();

    // Deserialize the data structure from the persistent storage format
    deserialize();

    return 0;
}
