    char* string;
    int identifier;
    record* records;
} node_t;

// Record structure for 'int' value
typedef struct record {
    int value;
} record_t;

// Function to initialize a node with given 'long' offset and 'int' key
node_t* init_node(long offset, int key) {
    // Allocate memory for node structure
    node_t* new_node = malloc(sizeof(node_t));
    if (new_node == NULL) {
        fprintf(stderr, "Failed to allocate memory for new node\n");
        return NULL;
    }

    // Initialize node fields
    new_node->prev = NULL;
    new_node->next = NULL;
    new_node->string = (char*)malloc((strlen(offset) + 1) * sizeof(char));
    if (new_node->string == NULL) {
        fprintf(stderr, "Failed to allocate memory for node string\n");
        return NULL;
    }
    strcpy(new_node->string, offset);
    new_node->identifier = key;

    // Allocate memory for record array within node
    new_node->records = malloc((sizeof(record_t) * 10));
    if (new_node->records == NULL) {
        fprintf(stderr, "Failed to allocate memory for record array\n");
        return NULL;
    }

    // Initialize each record with a random value within given range
    srand(time(NULL));
    for (int i = 0; i < 10; i++) {
        new_node->records[i].value = rand() % 10 + 1;
    }

    return new_node;
}

// Function to insert a node at the head of the list
void insert_head(node_t* node) {
    // Acquire lock on list mutex
    pthread_mutex_lock(&list_mutex);

    // Set node as head of list and update next pointers
    if (list_head == NULL) {
        list_head = node;
    } else {
        node->next = list_head;
        list_head->prev = node;
        list_head = node;
    }

    // Release lock on list mutex
    pthread_mutex_unlock(&list_mutex);
}

// Function to insert a node at the tail of the list
void insert_tail(node_t* node) {
    // Acquire lock on list mutex
    pthread_mutex_lock(&list_mutex);

    // Set node as tail of list and update previous pointers
    if (list_tail == NULL) {
        list_tail = node;
    } else {
        node->prev = list_tail;
        list_tail->next = node;
        list_tail = node;
    }

    // Release lock on list mutex
    pthread_mutex_unlock(&list_mutex);
}

// Function to insert a node at the middle of the list
void insert_middle(node_t* node) {
    // Acquire lock on list mutex
    pthread_mutex_lock(&list_mutex);

    // Find middle node and update previous and next pointers
    node_t* current = list_head;
    while (current->next != NULL && current->next != list_tail) {
        current = current->next;
    }
    if (current == NULL) {
        fprintf(stderr, "Failed to find middle node\n");
        return;
    }
    current->prev->next = node;
    node->prev = current->prev;
    node->next = current;
    current->prev = node;

    // Release lock on list mutex
    pthread_mutex_unlock(&list_mutex);
}

// Function to delete a node from the list
void delete_node(node_t* node) {
    // Acquire lock on list mutex
    pthread_mutex_lock(&list_mutex);

    // Update previous and next pointers
    if (node->prev != NULL && node->next != NULL) {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    } else if (node->prev == NULL && node->next != NULL) {
        list_head = node->next;
    } else if (node->prev != NULL && node->next == NULL) {
        list_tail = node->prev;
    } else {
        fprintf(stderr, "Failed to delete node\n");
        return;
    }

    // Release lock on list mutex
    pthread_mutex_unlock(&list_mutex);
}

// Function to iterate over all nodes in the list
void iterate_nodes() {
    // Acquire lock on list mutex
    pthread_mutex_lock(&list_mutex);

    node_t* current = list_head;
    while (current != NULL) {
        printf("Node: %s, Identifier: %d\n", current->string, current->identifier);
        for (int i = 0; i < 10; i++) {
            printf("Record: %d\n", current->records[i].value);
        }
        current = current->next;
    }

    // Release lock on list mutex
    pthread_mutex_unlock(&list_mutex);
}
