    char *string;
} record_t;

// Define the cache data structure
typedef struct {
    int count;
    record_t *records;
} cache_t;

// Initialize the cache with the given number of records
void cache_init(cache_t *cache, int num_records) {
    cache->count = 0;
    cache->records = (record_t *) malloc(num_records * sizeof(record_t));
}

// Add a new record to the cache, if possible
void cache_add(cache_t *cache, record_t record) {
    // Check if the cache is full
    if (cache->count == MAX_RECORDS) {
        // Evict the least recently used record from the cache
        int lru = 0;
        for (int i = 1; i < cache->count; i++) {
            if (cache->records[i].value < cache->records[lru].value) {
                lru = i;
            }
        }
        // Free the evicted record
        free(cache->records[lru].string);
        free(cache->records[lru]);
        // Move all records after the evicted record to fill the gap
        for (int i = lru; i < cache->count - 1; i++) {
            cache->records[i] = cache->records[i + 1];
        }
        // Decrement the count
        cache->count--;
    }
    // Add the new record to the end of the cache
    cache->records[cache->count++] = record;
}

// Get a record from the cache, if possible
void cache_get(cache_t *cache, int index) {
    // Check if the index is valid
    if (index < 0 || index >= cache->count) {
        printf("Cache miss: invalid index\n");
        return;
    }
    // Increment the access count for the record
    cache->records[index].access++;
}

// Update a record in the cache, if possible
void cache_update(cache_t *cache, int index, double value, char *string) {
    // Check if the index is valid
    if (index < 0 || index >= cache->count) {
        printf("Cache miss: invalid index\n");
        return;
    }
    // Update the record in the cache
    cache->records[index].value = value;
    cache->records[index].string = string;
}

// Free the cache and all its records
void cache_free(cache_t *cache) {
    for (int i = 0; i < cache->count; i++) {
        free(cache->records[i].string);
        free(cache->records[i]);
    }
    free(cache->records);
}

