typedef struct mac_pdu {
    L2_MESSAGE message;
    MAC header;
    size_t num_packets;
    size_t packet_size[MAX_PACKETS];
    char data[MAX_BUFFER_SIZE];
} mac_pdu;

typedef struct buffer {
    int capacity;
    int size;
    char* data;
} buffer;

void allocate(buffer* buf, size_t size) {
    if (buf->capacity >= size) return;
    buf->data = realloc(buf->data, size);
    assert(buf->data != NULL);
    buf->capacity = size;
}

void deallocate(buffer* buf) {
    free(buf->data);
    buf->data = NULL;
    buf->size = 0;
    buf->capacity = 0;
}

void resize_buffer(buffer* buf, size_t new_size) {
    if (new_size <= buf->size) return;
    allocate(buf, new_size);
    buf->size = new_size;
}

int get_packet_size(mac_pdu* pdu, int index) {
    assert(index >= 0 && index < pdu->num_packets);
    return pdu->packet_size[index];
}

char* get_data_ptr(mac_pdu* pdu, int index) {
    assert(index >= 0 && index < pdu->num_packets);
    size_t offset = 0;
    for (int i = 0; i < index; ++i) {
        offset += get_packet_size(pdu, i);
    }
    return &pdu->data[offset];
}

void add_packet(mac_pdu* pdu, char* data, size_t size) {
    // check if there is enough space in the buffer
    if (pdu->size + size > pdu->capacity) {
        resize_buffer(&pdu->data, pdu->size + size);
    }

    // add the packet to the buffer
    memcpy(&pdu->data[pdu->size], data, size);
    pdu->size += size;

    // update the packet sizes
    pdu->packet_size[pdu->num_packets] = size;
    ++pdu->num_packets;
}

void remove_packet(mac_pdu* pdu, int index) {
    assert(index >= 0 && index < pdu->num_packets);

    // shift the remaining packets forward
    size_t offset = get_packet_size(pdu, index);
    for (int i = index + 1; i < pdu->num_packets; ++i) {
        memcpy(&pdu->data[offset], &pdu->data[get_packet_size(pdu, i)], pdu->packet_size[i]);
        offset += pdu->packet_size[i];
    }

    // update the packet sizes and buffer size
    pdu->num_packets--;
    pdu->size -= get_packet_size(pdu, index);
}

void process_packets(mac_pdu* pdu) {
    for (int i = 0; i < pdu->num_packets; ++i) {
        // process the packet
    }
}

void send_packets(mac_pdu* pdu, int sockfd) {
    for (int i = 0; i < pdu->num_packets; ++i) {
        size_t offset = get_packet_size(pdu, i);
        if (send(sockfd, &pdu->data[offset], pdu->packet_size[i], 0) <= 0) {
            perror("send");
        }
    }
}

void* handle_request(void* arg) {
    mac_pdu* pdu = (mac_pdu*)arg;
    process_packets(pdu);
    send_packets(pdu, socket_fd);
    return NULL;
}

int main(int argc, char** argv) {
    int sockfd = 0;
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket");
        return 1;
    }

    struct sockaddr_in serverAddr;
    memset(&serverAddr, 0, sizeof(struct sockaddr_in));
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(8080);
    if (inet_pton(AF_INET, "127.0.0.1", &serverAddr.sin_addr) <= 0) {
        perror("inet_pton");
        return 1;
    }

    connect(sockfd, (struct sockaddr*)&serverAddr, sizeof(struct sockaddr_in));

    while (true) {
        mac_pdu* pdu = malloc(sizeof(mac_pdu));
        memset(pdu, 0, sizeof(mac_pdu));
        read(sockfd, &pdu->message, sizeof(L2_MESSAGE));
        read(sockfd, &pdu->header, sizeof(MAC));

        buffer buf;
        allocate(&buf, MIN_BUFFER_SIZE);

        while (true) {
            char* data = malloc(MAX_PACKET_SIZE);
            size_t size = recv(sockfd, data, MAX_PACKET_SIZE, 0);
            if (size <= 0) {
                break;
            }
            add_packet(pdu, data, size);
        }

        pthread_t thread;
        if (pthread_create(&thread, NULL, handle_request, pdu) < 0) {
            perror("pthread_create");
        }
    }

    return 0;
}
