#define NUM_CONCURRENT_THREADS 8

// Struct to store user activity log entries
struct UserActivityLogEntry {
  double score;
  char* identifier;
  time_t timestamp;
};

// Global variable to store the next available identifier for new users
static int next_available_identifier = 0;

// Function to allocate memory for a user activity log entry
struct UserActivityLogEntry* createUserActivityLogEntry(double score, char* identifier) {
  // Allocate memory for the log entry struct and set its fields
  struct UserActivityLogEntry* entry = malloc(sizeof(struct UserActivityLogEntry));
  if (entry == NULL) {
    fprintf(stderr, "Error: Out of memory\n");
    return NULL;
  }
  entry->score = score;
  entry->identifier = identifier;
  entry->timestamp = time(NULL);

  // If the identifier is not unique, find a new one and assign it to the log entry
  if (strcmp(entry->identifier, "unique") != 0) {
    int unique_identifier = getNextAvailableIdentifier();
    sprintf(entry->identifier, "%d", unique_identifier);
  }

  // Return the allocated memory for the log entry struct
  return entry;
}

// Function to free memory for a user activity log entry
void freeUserActivityLogEntry(struct UserActivityLogEntry* entry) {
  // Check if the entry is NULL before attempting to free its memory
  if (entry == NULL) {
    fprintf(stderr, "Error: Entry is NULL\n");
    return;
  }

  // Free the memory allocated for the log entry struct
  free(entry);
}

// Function to get the next available identifier for a new user
int getNextAvailableIdentifier() {
  // If there are no more available identifiers, return an error code
  if (next_available_identifier == INT_MAX) {
    fprintf(stderr, "Error: All identifiers have been used\n");
    return -1;
  }

  // Increment the next available identifier and return it
  int new_identifier = next_available_identifier++;
  return new_identifier;
}

// Function to update a user activity log entry with a new score
void updateUserActivityLogEntry(struct UserActivityLogEntry* entry, double score) {
  // Check if the entry is NULL before attempting to update its score
  if (entry == NULL) {
    fprintf(stderr, "Error: Entry is NULL\n");
    return;
  }

  // Update the score for the log entry struct
  entry->score = score;
}

// Function to read a user activity log entry from disk
struct UserActivityLogEntry* readUserActivityLogEntry(char* filename, int line_number) {
  // Open the file containing the log entries
  FILE* fp = fopen(filename, "r");
  if (fp == NULL) {
    fprintf(stderr, "Error: Unable to open file %s\n", filename);
    return NULL;
  }

  // Read the log entry from the file and allocate memory for it
  struct UserActivityLogEntry* entry = malloc(sizeof(struct UserActivityLogEntry));
  if (entry == NULL) {
    fprintf(stderr, "Error: Out of memory\n");
    return NULL;
  }

  // Read the score, identifier, and timestamp for the log entry
  fscanf(fp, "%lf %s %d", &entry->score, entry->identifier, &entry->timestamp);

  // Close the file
  fclose(fp);

  // Return the read log entry
  return entry;
}

// Function to write a user activity log entry to disk
void writeUserActivityLogEntry(struct UserActivityLogEntry* entry, char* filename) {
  // Open the file containing the log entries
  FILE* fp = fopen(filename, "a");
  if (fp == NULL) {
    fprintf(stderr, "Error: Unable to open file %s\n", filename);
    return;
  }

  // Write the score, identifier, and timestamp for the log entry to the file
  fprintf(fp, "%lf %s %d\n", entry->score, entry->identifier, entry->timestamp);

  // Close the file
  fclose(fp);
}
