// Define a struct to hold information about each process
typedef struct SYSTEM_PROCESS_INFO {
    int PROCESS_ID;
    bool STATUS;
    time_t TIMESTAMP;
} SYSTEM_PROCESS_INFO;

// Define a function to allocate and populate the list of processes
void allocateProcesses(int N) {
    // Initialize the list of processes with NULL pointers
    SYSTEM_PROCESS_INFO* processes = malloc(N * sizeof(SYSTEM_PROCESS_INFO));
    for (int i = 0; i < N; i++) {
        processes[i] = NULL;
    }

    // Generate unique PROCESS_IDs and random status flags for each process
    for (int i = 0; i < N; i++) {
        SYSTEM_PROCESS_INFO* currentProcess = &processes[i];

        // Check if the allocated PROCESS_ID has already been used in the current session
        bool duplicateIdFound = false;
        int timeout = 100; // 100 milliseconds
        while (duplicateIdFound && timeout > 0) {
            srand((unsigned int)time(NULL));
            currentProcess->PROCESS_ID = rand() % INT_MAX;
            for (int j = 0; j < i; j++) {
                if (currentProcess->PROCESS_ID == processes[j].PROCESS_ID) {
                    duplicateIdFound = true;
                    break;
                }
            }
            timeout--;
        }

        // If the PROCESS_ID is not unique, generate a new one
        if (duplicateIdFound) {
            continue;
        }

        // Set the status flag to true or false randomly
        currentProcess->STATUS = rand() % 2 == 0 ? true : false;

        // Update the timestamp for the process
        time_t currentTime = time(NULL);
        currentProcess->TIMESTAMP = currentTime;
    }

    // Memory pool to reuse SYSTEM_PROCESS_INFO structures
    int numActiveProcesses = 0;
    for (int i = 0; i < N; i++) {
        if (processes[i].STATUS) {
            numActiveProcesses++;
        }
    }
    SYSTEM_PROCESS_INFO* activeProcesses = malloc(numActiveProcesses * sizeof(SYSTEM_PROCESS_INFO));
    for (int i = 0; i < N; i++) {
        if (processes[i].STATUS) {
            activeProcesses[activeProcesses.length++] = processes[i];
        }
    }

    // Integration with external monitoring system
    sendMonitoringAlerts(activeProcesses, N);
}

// Function to integrate with an external monitoring system
void sendMonitoringAlerts(SYSTEM_PROCESS_INFO* activeProcesses, int N) {
    for (int i = 0; i < N; i++) {
        if (activeProcesses[i].STATUS) {
            // Send alert for process start
            printf("Process started: PROCESS_ID=%d\n", activeProcesses[i].PROCESS_ID);
        } else {
            // Send alert for process stop
            printf("Process stopped: PROCESS_ID=%d\n", activeProcesses[i].PROCESS_ID);
        }
    }
}
