    Entry* result = NULL;
    for (int i = 0; i < num_entries; i++) {
        if (keys[i] == key) {
            result = &entries[i];
            break;
        }
    }
    pthread_mutex_unlock(&lock); // Release lock
    return result;
}

// Function to resize the arrays when necessary
void resize() {
    max_num_entries *= 2; // Double the size of the arrays
    entries = (Entry*)realloc(entries, max_num_entries * sizeof(Entry));
    offsets = (long*)realloc(offsets, max_num_entries * sizeof(long));
    keys = (int*)realloc(keys, max_num_entries * sizeof(int));
}

// Function to compact the data structures periodically
void compact() {
    // Remove any unused memory
    for (int i = 0; i < num_entries; i++) {
        if (offsets[i] == 0) {
            entries[i].key = 0;
            entries[i].offset = 0;
            entries[i].value = 0.0;
            keys[i] = 0;
        }
    }
}

// Function to free the memory allocated by the data structures
