    // Allocate memory for the arrays and initialize them to zero
    float* arr1 = (float*)malloc(num_arrays * sizeof(float));
    char** arr2 = (char**)malloc(num_arrays * sizeof(char*));
    sensor_data* arr3 = (sensor_data*)malloc(num_sensor_data_points * sizeof(sensor_data));
    memset(arr1, 0, num_arrays * sizeof(float));
    memset(arr2, 0, num_arrays * sizeof(char*));
    memset(arr3, 0, num_sensor_data_points * sizeof(sensor_data));

    // Set the values of the arrays based on user input
