// Function to design a caching mechanism to store up to 1000 frequently accessed UserSessionState instances, evicting less recently used records when full
void CacheUserSessions(int numSessions) {
    // Initialize the cache with the maximum number of sessions
    struct Cache cache = {numSessions, 0, NULL};

    for (int i = 0; i < numSessions; i++) {
        // Allocate memory for the UserSessionState object and initialize its fields
        cache.nodes[i] = malloc(sizeof(struct CacheNode));
        cache.nodes[i]->session = malloc(sizeof(struct UserSessionState));
        cache.nodes[i]->lastAccessed = time(NULL);

        // Initialize the unique identifier derived from a hash of session attributes
        unsigned long long uid = generateUID(cache.nodes[i]->session->sessionID);
        cache.nodes[i]->session->uid = uid;

        // Populate the buffer for incoming data
        cache.nodes[i]->session->buffer = malloc(BUFFER_SIZE);

        // Add the session to the cache, evicting less recently used records when full
        if (cache.count < cache.size) {
            cache.nodes[cache.count++] = &cache.nodes[i];
        } else {
            struct CacheNode* leastRecentlyUsed = NULL;
            for (int j = 0; j < cache.size; j++) {
                if (leastRecentlyUsed == NULL || leastRecentlyUsed->lastAccessed > cache.nodes[j].lastAccessed) {
                    leastRecentlyUsed = &cache.nodes[j];
                }
            }
            leastRecentlyUsed->session->buffer = malloc(BUFFER_SIZE); // Reallocate the buffer for the less recently used session
            leastRecentlyUsed->session->uid = generateUID(leastRecentlyUsed->session->sessionID); // Regenerate the unique identifier derived from a hash of session attributes
            leastRecentlyUsed->lastAccessed = time(NULL); // Update the last accessed timestamp for the less recently used session
            cache.nodes[i] = &cache.nodes[leastRecentlyUsed]; // Replace the less recently used session with the new session in the cache
        }
    }
}

