// Function to read and validate integers from standard input
void read_integers(int* arr, int* size) {
    // Get the total number of integers to read
    int num_ints;
    scanf("%d", &num_ints);

    // Validate the number of integers does not exceed 10,000
    if (num_ints > 10000) {
        printf("Too many integers provided. Exiting...\n");
        exit(1);
    }

    // Dynamically allocate memory for the integer array
    int* temp = (int*)malloc(sizeof(int) * num_ints);
    if (!temp) {
        printf("Memory allocation failed. Exiting...\n");
        exit(1);
    }

    // Validate each integer falls within the specified range
    for (int i = 0; i < num_ints; ++i) {
        scanf("%d", &temp[i]);
        if (temp[i] < -1000 || temp[i] > 1000) {
            printf("Invalid integer provided. Exiting...\n");
            exit(1);
        }
    }

    // Copy the validated integers to the output array
    memcpy(arr, temp, num_ints * sizeof(int));

    // Free the temporary memory
    free(temp);

    // Set the size of the output array
    *size = num_ints;
}

// Function to set each integer in the array to a random value within a specified range
void set_random_values(int* arr, int size, int min, int max) {
    // Generate a random seed for the RNG
    unsigned int seed = (unsigned int)time(NULL);
    srand(seed);

    #pragma omp parallel for schedule(static) default(none) shared(arr, size, min, max) firstprivate(seed)
    for (int i = 0; i < size; ++i) {
        // Generate a random integer within the specified range
        int rand_val = rand() % (max - min + 1) + min;

        // Set the value of the current integer to the random value
        arr[i] = rand_val;
    }
}

