void generate_random_numbers(int* arr, int size) {
    // Initialize the external library
    #pragma omp parallel for schedule(static) default(none) shared(arr, size) firstprivate(seed)
    for (int i = 0; i < size; ++i) {
        // Generate a random integer within the specified range using the external library
        int rand_val = generate_random_number();

        // Set the value of the current integer to the random value
        arr[i] = rand_val;
    }
}

