void initialize(const char *config_file_path) {
    if (initialized) {
        return;
    }

    // Load configuration file and parse it
    json_error_t error;
    json_t *root = json_load_file(config_file_path, 0, &error);
    if (!root) {
        fprintf(stderr, "Error parsing config file: %s\n", error.text);
        return;
    }

    // Allocate memory for the transaction bundle and its items
    size_t num_transactions = json_array_size(json_object_get(root, "transactions"));
    if (num_transactions > MAX_ELEMENTS) {
        fprintf(stderr, "Too many transactions in config file: %zu\n", num_transactions);
        return;
    }

    data = malloc(sizeof(*data) * num_transactions);
    if (!data) {
        fprintf(stderr, "Failed to allocate memory for data structures\n");
        return;
    }

    // Parse each transaction and populate the data structures
    size_t i;
    json_t *transaction = NULL;
    for (i = 0; i < num_transactions; i++) {
        transaction = json_array_get(json_object_get(root, "transactions"), i);
        if (!transaction) {
            fprintf(stderr, "Failed to retrieve transaction %zu from config file\n", i);
            continue;
        }

        // Parse the transaction and populate the data structures
        char *identifier = json_string_value(json_object_get(transaction, "identifier"));
        if (!identifier) {
            fprintf(stderr, "Failed to retrieve identifier for transaction %zu\n", i);
            continue;
        }
        strncpy(data[i].identifier, identifier, sizeof(data[i].identifier));

        data[i].floating_point_value = (float)json_number_value(json_object_get(transaction, "amount"));
        if (!isfinite(data[i].floating_point_value)) {
            fprintf(stderr, "Invalid floating-point value for transaction %zu\n", i);
            continue;
        }

        data[i].timestamp = (time_t)json_number_value(json_object_get(transaction, "timestamp"));
        if (!isfinite(data[i].timestamp)) {
            fprintf(stderr, "Invalid timestamp for transaction %zu\n", i);
            continue;
        }

        data[i].status = (int)json_number_value(json_object_get(transaction, "status"));
    }

    element_count = num_transactions;
    initialized = true;
}

void destroy() {
    if (!initialized) {
        return;
    }

    // Free the allocated memory for the transaction bundle and its items
    free(data);
    data = NULL;
    element_count = 0;
    initialized = false;
}

void serialize() {
    if (!initialized) {
        return;
    }

    // Serialize the transaction data into a JSON format
    json_t *root = json_array();
    for (size_t i = 0; i < element_count; i++) {
        json_t *transaction = json_object();
        if (!transaction) {
            fprintf(stderr, "Failed to allocate memory for serialized transaction %zu\n", i);
            continue;
        }

        // Populate the JSON object with data from the transaction structure
        char identifier[256];
        strncpy(identifier, data[i].identifier, sizeof(identifier));
        json_object_set_new(transaction, "identifier", json_string(identifier));

        json_object_set_new(transaction, "amount", json_real(data[i].floating_point_value));
        json_object_set_new(transaction, "timestamp", json_integer(data[i].timestamp));
