// Function to load and validate a media file
int loadMediaFile(const char *filename, struct mediaFile *media) {
    // Check if the filename is valid
    if (strlen(filename) > MAX_FILENAME_LENGTH) {
        return -1;
    }

    // Open the media file for reading
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        perror("Error opening media file");
        return MEMORY_ALLOCATION_FAILURE;
    }

    // Read the media file's metadata and check its consistency
    struct stat sb;
    int status = fstat(fd, &sb);
    if (status < 0) {
        perror("Error reading media file metadata");
        return MEMORY_ALLOCATION_FAILURE;
    }

    // Check the file's size and type
    off_t fileSize = sb.st_size;
    int fileType = sb.st_mode & S_IFMT;
    if (fileSize == 0 || fileType != S_IFREG) {
        return -1;
    }

    // Allocate memory for the media file's data and read it from disk
    int dataLength = fileSize;
    void *data = malloc(dataLength);
    if (data == NULL) {
        perror("Error allocating memory for media file");
        return MEMORY_ALLOCATION_FAILURE;
    }
    ssize_t bytesRead = read(fd, data, dataLength);
    if (bytesRead < 0) {
        perror("Error reading media file data");
        free(data);
        return MEMORY_ALLOCATION_FAILURE;
    }
    close(fd);

    // Set the media file's properties and mark it as valid
    media->filename = strdup(filename);
    media->mediaType = 0;
    media->timestamp = time(NULL);
    media->validityFlag = true;

    return 0;
}

