// Memory pool for reuse of TX_POWER_REPORT_INDICATION_T structures
struct MemoryPool {
    struct TX_POWER_REPORT_INDICATION_T *next;
    uint32_t size;
};

void initMemoryPool(struct MemoryPool *pool) {
    pool->next = NULL;
    pool->size = 0;
}

void addToMemoryPool(struct MemoryPool *pool, struct TX_POWER_REPORT_INDICATION_T *ptr) {
    ptr->next = pool->next;
    pool->next = ptr;
    pool->size++;
}

struct TX_POWER_REPORT_INDICATION_T* getFromMemoryPool(struct MemoryPool *pool) {
    if (pool->next == NULL) return NULL;
    struct TX_POWER_REPORT_INDICATION_T *ptr = pool->next;
    pool->next = ptr->next;
    pool->size--;
    return ptr;
}

// Function to manage a dynamic array of TX_POWER_REPORT_INDICATION_T structures
void manageArray(struct TX_POWER_REPORT_INDICATION_T *array, uint32_t N) {
    struct MemoryPool pool;
    initMemoryPool(&pool);

    // Check for duplicate RNTIs and handle conflicts
    for (uint32_t i = 0; i < N; i++) {
        uint16_t RNTI = generateRNTI();
