void init_cache(cache_t *cache) {
    memset(&cache->mutex, 0, sizeof(pthread_mutex_t));
    for (int i = 0; i < 1000; i++) {
        cache->records[i] = NULL;
    }
}

void add_record_to_cache(cache_t *cache, record_t *record) {
    pthread_mutex_lock(&cache->mutex);
    int index = -1;
    for (int i = 0; i < 1000; i++) {
        if (cache->records[i] == NULL) {
            cache->records[i] = record;
            break;
        } else if (cache->records[i]->offset == record->offset && cache->records[i]->key == record->key) {
            index = i;
            break;
        }
    }
    if (index != -1) {
        cache->records[index] = record;
    } else {
        free_memory((void **)&record);
    }
    pthread_mutex_unlock(&cache->mutex);
}

record_t *get_record_from_cache(cache_t *cache, long offset, int key) {
    record_t *record = NULL;
    pthread_mutex_lock(&cache->mutex);
    for (int i = 0; i < 1000; i++) {
        if (cache->records[i] != NULL && cache->records[i]->offset == offset && cache->records[i]->key == key) {
            record = cache->records[i];
