        keys[i] = rand() % 10000;
        values[i] = (float)rand() / RAND_MAX * 100.0f;
        validity_flags[i] = true;
    }
    allocate_TX_POWER_REPORT_INDICATION_T(N);
    handle_duplicate_RNTI(N);
    transmit_data(N, offsets, keys, values, validity_flags);
    receive_data(N, offsets, keys, values, validity_flags);
    return 0;
}
