// Initialize a new distributed system environment for user sessions and traffic events
void init_distributed_system(int num_users, int num_traffic_events) {
    // Allocate memory for the array of user contexts
    USER_CONTEXT_T *user_contexts = (USER_CONTEXT_T *)calloc(num_users, sizeof(USER_CONTEXT_T));

    // Initialize each user context structure with a valid ID and last activity timestamp
    for (int i = 0; i < num_users; i++) {
        USER_CONTEXT_T *user_context = &user_contexts[i];
        user_context->user_id = i + 1;
        user_context->session_id = i + 1;
        user_context->last_activity_timestamp = time(NULL);
    }

