        hash_table_entry->key = generate_random_string(10);
        hash_table_entry->value = generate_random_integer(1, 1000);
    }
}

// Add a new user context to the distributed system
void add_user_context(USER_CONTEXT_T *user_context) {
    // Acquire lock on the user context array
    pthread_mutex_lock(&user_contexts_lock);

    // Check if there is enough memory available for a new user context
    if (num_users < MAX_NUM_USERS) {
        USER_CONTEXT_T *new_user = &user_contexts[num_users];
        new_user->user_id = user_context->user_id;
        new_user->session_id = user_context->session_id;
        new_user->last_activity_timestamp = time(NULL);
        num_users++;
    } else {
        // Release lock on the user context array if there is not enough memory available
        pthread_mutex_unlock(&user_contexts_lock);
        return;
    }

    // Release lock on the user context array after adding a new user context
    pthread_mutex_unlock(&user_contexts_lock);
}

// Remove a user context from the distributed system
void remove_user_context(int user_id) {
    // Acquire lock on the user context array
    pthread_mutex_lock(&user_contexts_lock);

    // Check if the specified user ID exists in the user context array
    for (int i = 0; i < num_users; i++) {
        USER_CONTEXT_T *user_context = &user_contexts[i];
        if (user_id == user_context->user_id) {
            // Swap the user context with the last element in the array
            USER_CONTEXT_T *last_user = &user_contexts[num_users - 1];
            user_context->user_id = last_user->user_id;
            user_context->session_id = last_user->session_id;
            user_context->last_activity_timestamp = time(NULL);
            num_users--;
            break;
        }
    }

    // Release lock on the user context array after removing a user context
    pthread_mutex_unlock(&user_contexts_lock);
}

// Add a new traffic event to the distributed system
void add_traffic_event(TRAFFIC_EVENT_T *traffic_event) {
    // Acquire lock on the traffic events array
    pthread_mutex_lock(&traffic_events_lock);

    // Check if there is enough memory available for a new traffic event
    if (num_traffic_events < MAX_NUM_TRAFFIC_EVENTS) {
        TRAFFIC_EVENTS_ARRAY_T *new_event = &traffic_events[num_traffic_events];
        new_event->event_type = traffic_event->event_type;
        new_event->timestamp = time(NULL);
        num_traffic_events++;
    } else {
        // Release lock on the traffic events array if there is not enough memory available
        pthread_mutex_unlock(&traffic_events_lock);
        return;
    }

    // Release lock on the traffic events array after adding a new traffic event
    pthread_mutex_unlock(&traffic_events_lock);
}

// Remove a traffic event from the distributed system
void remove_traffic_event(int event_type, int timestamp) {
    // Acquire lock on the traffic events array
    pthread_mutex_lock(&traffic_events_lock);

    // Check if the specified traffic event exists in the array
    for (int i = 0; i < num_traffic_events; i++) {
        TRAFFIC_EVENTS_ARRAY_T *traffic_event = &traffic_events[i];
        if (event_type == traffic_event->event_type && timestamp == traffic_event->timestamp) {
            // Swap the traffic event with the last element in the array
            TRAFFIC_EVENTS_ARRAY_T *last_event = &traffic_events[num_traffic_events - 1];
            traffic_event->event_type = last_event->event_type;
            traffic_event->timestamp = last_event->timestamp;
            num_traffic_events--;
            break;
        }
    }

    // Release lock on the traffic events array after removing a traffic event
    pthread_mutex_unlock(&traffic_events_lock);
}

// Update the last activity timestamp for a user context in the distributed system
void update_user_context(int user_id, time_t *last_activity) {
    // Acquire lock on the user context array
    pthread_mutex_lock(&user_contexts_lock);

    // Check if the specified user ID exists in the user context array
    for (int i = 0; i < num_users; i++) {
        USER_CONTEXT_T *user_context = &user_contexts[i];
        if (user_id == user_context->user_id) {
            user_context->last_activity_timestamp = time(NULL);
            break;
        }
    }

    // Release lock on the user context array after updating a user context
    pthread_mutex_unlock(&user_contexts_lock);
}

