// Record structure with timestamp, value, and validity flag
typedef struct record {
    int timestamp;
    float value;
    bool valid;
} record_t;

// Data store for records
typedef struct data_store {
    // Array of records
    record_t* records;

    // Offset array for efficient access based on keys
    int* offsets;

    // Key array for fast access to records
    int* keys;

    // Number of records in the store
    int num_records;

    // Maximum number of records that can be stored
    int max_num_records;
} data_store_t;

// Function to allocate memory for a new record
record_t* alloc_record() {
    record_t* new_record = (record_t*) malloc(sizeof(record_t));
    if (!new_record) {
        printf("Error: failed to allocate memory for new record\n");
        return NULL;
    }
    return new_record;
}

// Function to free the memory of a record
void free_record(record_t* record) {
    free(record);
}

// Function to add a new record to the data store
int add_record(data_store_t* store, int timestamp, float value, bool validity) {
    // Check if there is enough space in the store for another record
    if (store->num_records >= store->max_num_records) {
        printf("Error: data store is full\n");
        return -1;
    }

    // Allocate memory for a new record
