    // Populate the new record with the given values
    new_record->timestamp = timestamp;
    new_record->value = value;
    new_record->valid = validity;

    // Add the new record to the store
    store->records[store->num_records] = new_record;
    store->offsets[store->num_records] = store->num_records;
    store->keys[store->num_records] = timestamp;
    store->num_records++;

    return 0;
}

// Function to retrieve a record from the data store by key
record_t* get_record(data_store_t* store, int key) {
    // Check if the key exists in the store
    int index = get_index(store, key);
    if (index == -1) {
        printf("Error: record with key %d does not exist\n", key);
        return NULL;
    }

    // Return the record at the given index
    return store->records[index];
}

// Function to retrieve a record from the data store by offset
record_t* get_record_by_offset(data_store_t* store, int offset) {
    // Check if the offset is within the bounds of the store
    if (offset < 0 || offset >= store->num_records) {
        printf("Error: offset %d is out of bounds\n", offset);
        return NULL;
    }

    // Return the record at the given offset
    return store->records[offset];
}

// Function to update a record in the data store by key
int update_record(data_store_t* store, int key, int new_timestamp, float new_value) {
    // Check if the key exists in the store
    int index = get_index(store, key);
    if (index == -1) {
        printf("Error: record with key %d does not exist\n", key);
        return -1;
    }

    // Update the record at the given index
    store->records[index]->timestamp = new_timestamp;
    store->records[index]->value = new_value;

    return 0;
}

// Function to delete a record from the data store by key
int delete_record(data_store_t* store, int key) {
    // Check if the key exists in the store
    int index = get_index(store, key);
    if (index == -1) {
        printf("Error: record with key %d does not exist\n", key);
        return -1;
    }

    // Remove the record at the given index from the store
    free_record(store->records[index]);
    store->num_records--;

    return 0;
}

// Function to get the index of a record in the data store by key
int get_index(data_store_t* store, int key) {
    // Check if the key exists in the store
    for (int i = 0; i < store->num_records; i++) {
        if (store->keys[i] == key) {
            return i;
        }
    }

    // Return -1 if the key does not exist
    return -1;
}

// Function to get the index of a record in the data store by offset
int get_offset(data_store_t* store, int offset) {
    // Check if the offset is within the bounds of the store
    if (offset < 0 || offset >= store->num_records) {
        printf("Error: offset %d is out of bounds\n", offset);
        return -1;
    }

    // Return the record at the given offset
    return store->offsets[offset];
}

// Function to check if a key exists in the data store
int key_exists(data_store_t* store, int key) {
    // Check if the key exists in the store
    for (int i = 0; i < store->num_records; i++) {
        if (store->keys[i] == key) {
            return 1;
        }
    }

    // Return 0 if the key does not exist
    return 0;
}
```
In this example, we define a data structure called `data_store` that stores a set of records with integer keys and values. The `data_store` struct contains three arrays: `records`, `offsets`, and `keys`. The `records` array is used to store the actual records in the data store, while the `offsets` array is used to keep track of the offset of each record in the `records` array. The `keys` array is used to map between integer keys and offsets in the `records` array.

The `add_record`, `get_record`, `update_record`, and `delete_record` functions are used to add, retrieve, update, and delete records from the data store, respectively. The `get_index` function is used to get the index of a record in the `records` array by its key, while the `get_offset` function is used to get the offset of a record in the `records` array by its key. The `key_exists` function is used to check if a key exists in the data store.

The `data_store` struct also contains some utility functions for checking if the data store is full, and for getting the size of the data store. These functions are used to handle edge cases where the user tries to add too many records to the data store, or when they try to retrieve a record that does not exist in the data store.

