class ConcurrentForwardListDB {
public:
    // Constructor to initialize the forward list and database
    ConcurrentForwardListDB(int capacity, int minKey, int maxKey) : capacity_(capacity), minKey_(minKey), maxKey_(maxKey) {}

    // Function to insert a record into the forward list and database
    void insertRecord(string value1, string value2) {
        std::lock_guard<std::mutex> lock(mutex_);
        // Search for the first occurrence of value1 in the forward list
        auto it = find(forwardList_.begin(), forwardList_.end(), value1);
        if (it != forwardList_.end()) {
            // Insert value2 immediately after the occurrence of value1
            insertAfter(it, value2);
        } else {
            // Append value2 to the end of the forward list if value1 is not found
            forwardList_.push_back(value2);
        }
        // Update the database with the new record
        database_[value1] = Record{minKey_, value2};
    }

    // Function to evict records from the database based on LRU policy
    void evictRecords() {
        std::lock_guard<std::mutex> lock(mutex_);
        // Get the least recently used record in the database
        auto it = database_.begin();
        int minKey = it->first;
        while (++it != database_.end()) {
            if (it->second.key < minKey) {
                minKey = it->second.key;
            }
        }
        // Evict the records with keys less than the least recently used record
        for (auto it = database_.begin(); it != database_.end(); ++it) {
            if (it->second.key < minKey) {
                database_.erase(it);
            }
        }
    }

private:
