int load_data(const char* filename, item** items, int* num_items) {
    // Open the file for reading
    FILE* fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening file");
        return -1;
    }

    // Initialize variables
    *num_items = 0;
    item* item_array = NULL;

    // Read the CSV file line by line
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Skip empty lines or comments
        if (strlen(line) == 0 || line[0] == '#') continue;

        // Split the line into fields using a comma as delimiter
        char* field = strtok(line, ",");
        int i = 0;
        while (field != NULL) {
            if (i == 0) {
                // Convert string to double and store in data_item
                item_array[*num_items].value = atof(field);
            } else if (i == 1) {
                // Copy the string into a new buffer and store in data_item
                size_t len = strlen(field) + 1;
                char* buf = malloc(len);
                if (!buf) {
                    perror("Error allocating memory");
                    return -1;
                }
                memcpy(buf, field, len);
                item_array[*num_items].string = buf;
            } else if (i == 2) {
                // Convert string to integer and store in data_item
                item_array[*num_items].integer = atoi(field);
            }

            i++;
            field = strtok(NULL, ",");
        }

        (*num_items)++;
    }

    // Allocate memory for the array of items
    item_array = malloc(*num_items * sizeof(item));
    if (!item_array) {
        perror("Error allocating memory");
        return -1;
    }

    // Copy the data from the temporary array to the final array
    for (int i = 0; i < *num_items; i++) {
        item_array[i] = items[i];
    }

    fclose(fp);
    return 0;
}

// Function to initialize the arrays of data
void init_data(double** double_array, char*** string_array, data_item*** data_item_array, int* num_items) {
    // Allocate memory for the arrays
    *double_array = malloc(*num_items * sizeof(double));
    if (!*double_array) {
        perror("Error allocating memory");
        return;
    }
    *string_array = malloc(*num_items * sizeof(char*));
    if (!*string_array) {
        perror("Error allocating memory");
        free(*double_array);
        return;
    }
    *data_item_array = malloc(*num_items * sizeof(data_item*));
    if (!*data_item_array) {
        perror("Error allocating memory");
        free(*double_array);
        free(*string_array);
        return;
    }

    // Initialize the arrays with default values
    for (int i = 0; i < *num_items; i++) {
        (*double_array)[i] = 0.0;
        (*string_array)[i] = NULL;
        (*data_item_array)[i] = NULL;
    }
}

// Function to handle errors during memory allocation
void error_handler(const char* msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}
