#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>

typedef struct entity {
    double value;
    char* string;
    data_item item;
} entity;

struct list_node {
    entity* data;
    struct list_node* next;
};

struct list {
    struct list_node* head;
    struct list_node* tail;
    size_t size;
    pthread_mutex_t lock;
};

void list_init(list* l) {
    assert(l != NULL);
    l->head = NULL;
    l->tail = NULL;
    l->size = 0;
    pthread_mutex_init(&l->lock, NULL);
}

void list_destroy(list* l) {
    assert(l != NULL);
    struct list_node* node = l->head;
    while (node != NULL) {
        struct list_node* next = node->next;
        free(node->data);
        free(node);
        node = next;
    }
    pthread_mutex_destroy(&l->lock);
}

void list_add(list* l, entity* e) {
    assert(l != NULL && e != NULL);
    struct list_node* node = malloc(sizeof(struct list_node));
    if (node == NULL) {
        // handle allocation failure gracefully
    }
    node->data = e;
    node->next = NULL;
    pthread_mutex_lock(&l->lock);
    if (l->tail != NULL) {
        l->tail->next = node;
    } else {
        l->head = node;
    }
    l->tail = node;
    l->size++;
    pthread_mutex_unlock(&l->lock);
}

void list_remove(list* l, size_t index) {
    assert(l != NULL && index < l->size);
    struct list_node* node = l->head;
    if (index == 0) {
        pthread_mutex_lock(&l->lock);
        l->head = node->next;
        free(node->data);
        free(node);
        l->size--;
        pthread_mutex_unlock(&l->lock);
    } else {
        for (size_t i = 0; i < index - 1; i++) {
            node = node->next;
        }
        pthread_mutex_lock(&l->lock);
        struct list_node* next = node->next->next;
        free(node->data);
        free(node);
        l->size--;
        node->next = next;
        pthread_mutex_unlock(&l->lock);
    }
}

entity* list_get(list* l, size_t index) {
    assert(l != NULL && index < l->size);
    struct list_node* node = l->head;
    for (size_t i = 0; i < index; i++) {
        node = node->next;
    }
    return node->data;
}

void list_clear(list* l) {
    assert(l != NULL);
    struct list_node* node = l->head;
    while (node != NULL) {
        struct list_node* next = node->next;
        free(node->data);
        free(node);
        node = next;
    }
    pthread_mutex_destroy(&l->lock);
}

void list_report_stats(list* l) {
