        node = node->next;
    }
    size_t min_size = *std::min_element(sizes, sizes + l->size);
    size_t max_size = *std::max_element(sizes, sizes + l->size);
    printf("Entity size distribution: %zu (%.2f%%), %zu (%.2f%%), %zu (%.2f%%)\n", min_size, 100.0 * min_size / total_size,
        max_size, 100.0 * max_size / total_size, total_size - min_size - max_size, 100.0 * (total_size - min_size - max_size) / total_size);
    free(sizes);
}
