  private static final ImmutableSet<String> AGGREGATABLE_METRICS = new ImmutableSet.Builder()
      .add("metric_1")
      .add("metric_2")
      .add("metric_3")
      .build();

  private final LoadingCache<String, MetricData> metricDataCache;
  private final RateLimiter rateLimiter;
  private final ExecutorService executor;
  private final AtomicLong metricsProcessedCount = new AtomicLong(0);
  private final AtomicLong metricsSkippedCount = new AtomicLong(0);
  private final AtomicLong anomaliesDetectedCount = new AtomicLong(0);
  private final FastDateFormat dateFormat;
  private final String[] logTemplate;

  public RealtimeMetricsAggregator() {
    this.metricDataCache = CacheBuilder.newBuilder().maximumSize(METRIC_DATA_SIZE).build(
        new CacheLoader<String, MetricData>() {
          @Override
