    this.dateFormat = FastDateFormat.getInstance("yyyy-MM-dd HH:mm:ss");
    this.logTemplate = new String[] {"%s", "%d", "%d", "%d"};
  }

  public void processMetrics(String metricsJson) {
    try {
      rateLimiter.acquire();
      executor.submit(() -> {
        long startTime = System.nanoTime();
        MetricData data = deserializeMetrics(metricsJson);
        long endTime = System.nanoTime();
        metricsProcessedCount.incrementAndGet();
        if (isAggregatable(data)) {
          metricDataCache.put(data.getKey(), data);
          aggregateMetrics(data);
        } else {
          metricsSkippedCount.incrementAndGet();
        }
        long duration = endTime - startTime;
        logStatus(duration, "processMetrics");
      });
    } catch (Exception e) {
      metricsSkippedCount.incrementAndGet();
      logError("processMetrics", e);
    }
  }

  public void aggregateMetrics(MetricData data) {
    long startTime = System.nanoTime();
    MetricData cachedData = metricDataCache.getIfPresent(data.getKey());
    if (cachedData == null) {
      metricDataCache.put(data.getKey(), data);
    } else {
      for (String key : AGGREGATABLE_METRICS) {
        double value = data.getValue(key);
        if (!Double.isNaN(value)) {
          cachedData.addValue(key, value);
        }
      }
    }
    long endTime = System.nanoTime();
    long duration = endTime - startTime;
    logStatus(duration, "aggregateMetrics");
  }

  public void detectAnomalies() {
    long startTime = System.nanoTime();
    ImmutableSet<String> keys = metricDataCache.asMap().keySet();
    for (String key : keys) {
      MetricData data = metricDataCache.getIfPresent(key);
      if (data != null && isAnomaly(data)) {
        anomaliesDetectedCount.incrementAndGet();
        logStatus(0, "anomaly detected: " + key);
      }
    }
    long endTime = System.nanoTime();
    long duration = endTime - startTime;
    logStatus(duration, "detectAnomalies");
  }

  public void resetMetricDataCache() {
    metricDataCache.invalidateAll();
    logStatus(0, "resetMetricDataCache");
  }

  private MetricData deserializeMetrics(String metricsJson) throws Exception {
