  }

  private boolean isAggregatable(MetricData data) {
    return AGGREGATABLE_METRICS.containsAll(data.getKeys());
  }

  private double calculateRollingAverage(List<Double> values, int windowSize) {
    // Implement rolling average calculation using an external library here
  }

  private boolean isAnomaly(MetricData data) {
