  private void logStatus(long duration, String message) {
    long timestamp = System.currentTimeMillis();
    String[] logs = new String[logTemplate.length];
    logs[0] = dateFormat.format(timestamp);
    logs[1] = String.valueOf(metricsProcessedCount.get());
    logs[2] = String.valueOf(metricsSkippedCount.get());
    logs[3] = String.valueOf(anomaliesDetectedCount.get());
    logs[4] = message;
    logs[5] = String.valueOf(duration);
    System.out.println(String.format(logTemplate, logs));
  }

  private void logError(String message, Exception e) {
    long timestamp = System.currentTimeMillis();
    System.err.println(String.format("[%d] %s: %s", timestamp, message, e.getMessage()));
