// Define a function to allocate and initialize arrays for 'long' offsets, 'int' keys, and 'record' structures
void init_arrays(size_t num_records, size_t **offset_arr, int **key_arr, struct Record ***record_arr) {
    // Allocate memory for the offset array
    *offset_arr = (size_t *)malloc(num_records * sizeof(size_t));
    if (*offset_arr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Allocate memory for the key array
    *key_arr = (int *)malloc(num_records * sizeof(int));
    if (*key_arr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Allocate memory for the record array
    *record_arr = (struct Record **)malloc(num_records * sizeof(struct Record));
    if (*record_arr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
}

// Define a function to handle memory allocation failures gracefully
void handle_memory_allocation_failure() {
    // Log the error message
    fprintf(stderr, "Memory allocation failure\n");

    // Exit the program with an error code
    exit(EXIT_FAILURE);
}

// Define a function to initialize each record in the array
void init_records(size_t num_records, size_t *offset_arr, int *key_arr, struct Record **record_arr) {
    for (int i = 0; i < num_records; i++) {
        // Set a random value within the specified range for the key field using a pseudo-random number generator seeded with the current time
        key_arr[i] = rand() % MAX_KEY_VALUE + MIN_KEY_VALUE;

        // Allocate memory for the string buffer
        record_arr[i]->value = (char *)malloc(MAX_STRING_LENGTH * sizeof(char));
        if (record_arr[i]->value == NULL) {
            handle_memory_allocation_failure();
        }

        // Initialize the string buffer with a random value
        for (int j = 0; j < MAX_STRING_LENGTH; j++) {
            record_arr[i]->value[j] = 'a' + rand() % 26;
        }
    }
}

// Define a function to insert a new record into the array
void insert_record(size_t num_records, size_t *offset_arr, int *key_arr, struct Record **record_arr, struct Record *new_record) {
    // Insert the new record at the end of the array
    offset_arr[num_records - 1] = new_record->offset;
    key_arr[num_records - 1] = new_record->key;
    record_arr[num_records - 1] = new_record;
}

// Define a function to retrieve a record from the array
struct Record *retrieve_record(size_t num_records, size_t *offset_arr, int *key_arr, struct Record **record_arr, long offset) {
    // Search for the record with the given offset
    for (int i = 0; i < num_records; i++) {
        if (offset == offset_arr[i]) {
            return record_arr[i];
        }
    }

    // Return NULL if the record is not found
    return NULL;
}

// Define a function to delete a record from the array
void delete_record(size_t num_records, size_t *offset_arr, int *key_arr, struct Record **record_arr, long offset) {
    // Search for the record with the given offset
    for (int i = 0; i < num_records; i++) {
        if (offset == offset_arr[i]) {
            // Remove the record from the array
            offset_arr[i] = offset_arr[num_records - 1];
            key_arr[i] = key_arr[num_records - 1];
            record_arr[i] = record_arr[num_records - 1];
            num_records--;
            break;
        }
    }
}

// Define a function to clean up unused records based on age
void cleanup_unused_records(size_t num_records, size_t *offset_arr, int *key_arr, struct Record **record_arr) {
    // Use a thread-safe lock to ensure concurrent access is managed
    pthread_mutex_lock(&cleanup_lock);

    // Iterate over the records and check if they are still in use
    for (int i = 0; i < num_records; i++) {
        if (!is_record_in_use(num_records, offset_arr, key_arr, record_arr, i)) {
            // Remove the unused record from the array
            offset_arr[i] = offset_arr[num_records - 1];
            key_arr[i] = key_arr[num_records - 1];
            record_arr[i] = record_arr[num_records - 1];
            num_records--;
        }
    }

    // Release the lock to allow other threads to access the array
    pthread_mutex_unlock(&cleanup_lock);
}

