void allocateNASPDUS(int numPdus, int rxInfoSize, int rntiSize) {
    // Check if the requested sizes are valid
    if (rxInfoSize < 0 || rntiSize < 0) {
        std::cout << "Invalid size request" << std::endl;
        return;
    }

    // Set the maximum combined size of the RX_UE_INFORMATION_TAG and RNTI to 1 MB
    const int maxSize = 1024 * 1024;

    // Check if the requested sizes exceed the maximum size
    if (rxInfoSize + rntiSize > maxSize) {
        std::cout << "Requested size exceeds maximum" << std::endl;
        return;
    }

    // Set the maximum size of the CRC_INDICATION_REL8_TAG array to 500 KB
    const int crcIndMaxSize = 1024 * 500;

    // Allocate memory for the NAS PDUs
    try {
        nasPdus.resize(numPdus);
    } catch (const std::bad_alloc& e) {
        std::cout << "Memory allocation failed: " << e.what() << std::endl;
        return;
    }

    // Initialize the NAS PDUs
    for (int i = 0; i < numPdus; ++i) {
        // Generate random values for the RX_UE_INFORMATION_TAG and RNTI
        std::mt19937 gen(std::random_device()());
        std::uniform_int_distribution<> rxInfoDist(0, maxSize - 1);
        std::uniform_int_distribution<> rntiDist(0, maxSize - 1);

        // Set the RX_UE_INFORMATION_TAG and RNTI
        nasPdus[i].rxInfo = {rxInfoDist(gen), rxInfoSize};
        nasPdus[i].rnti = {rntiDist(gen), rntiSize};

        // Set the CRC_INDICATION_REL8_TAG
        std::uniform_int_distribution<> crcIndDist(0, 1);
        nasPdus[i].crcInd.flag = crcIndDist(gen);
    }
}

// Function to free the NAS PDU structures
void freeNASPDUS() {
    // Free the memory allocated for the NAS PDUs
    nasPdus.clear();
}

