    // Check if the requested number of points exceeds available memory
    if (num_points > INT_MAX / sizeof(double)) {
        return -1;
    }

    // Calculate the total amount of memory needed for the arrays and structures
    size_t bytes = num_points * sizeof(double) + num_points * sizeof(data_point);

    // Check if the total memory request exceeds available memory
    if (bytes > MEMORY_LIMIT) {
        return -2;
    }

    // Allocate memory for the arrays and structures
    double* values = malloc(num_points * sizeof(double));
    data_point* points = malloc(num_points * sizeof(data_point));

