    int PROCESS_ID;
    char STATUS;
};

// Define hash map data structure for efficient PROCESS_ID checks
typedef struct HashMap {
    int *keys;
    struct SYSTEM_PROCESS_INFO *values;
} HashMap;

// Define function to initialize hash map
void initHashMap(HashMap *map) {
    map->keys = NULL;
    map->values = NULL;
}

// Define function to insert key-value pair into hash map
void insertIntoHashMap(HashMap *map, int key, struct SYSTEM_PROCESS_INFO value) {
    // Check if hash map is initialized
    if (map->keys == NULL || map->values == NULL) {
        return;
    }

    // Find empty slot for key-value pair
    int i = 0;
    while (i < map->size && map->keys[i] != INT_MAX) {
        if (map->keys[i] == key) {
            map->values[i].PROCESS_ID = value.PROCESS_ID;
            map->values[i].STATUS = value.STATUS;
            return;
        }
        i++;
    }

    // If no empty slot found, resize hash map and retry insertion
    if (i == map->size) {
        int newSize = map->size * 2;
        map->keys = realloc(map->keys, newSize * sizeof(int));
        map->values = realloc(map->values, newSize * sizeof(struct SYSTEM_PROCESS_INFO));
        for (int j = map->size; j < newSize; j++) {
            map->keys[j] = INT_MAX;
            map->values[j].PROCESS_ID = -1;
            map->values[j].STATUS = '\0';
        }
        insertIntoHashMap(map, key, value);
    }
}

