                printf("Updated process %d with status U\n", key);
            } else {
                // If PROCESS_ID is not in hash map, allocate memory for SYSTEM_PROCESS_INFO structure
                struct SYSTEM_PROCESS_INFO *value = malloc(sizeof(struct SYSTEM_PROCESS_INFO));
                if (value == NULL) {
                    printf("Memory allocation failed\n");
                } else {
                    // Initialize SYSTEM_PROCESS_INFO structure and add to hash map
                    value->PROCESS_ID = key;
                    value->STATUS = 'N';
                    insertIntoHashMap(map, key, value);
                    printf("Added process %d with status N\n", key);
                }
            }
        }
    }

    // Find largest integer in hash map and print result within 1-second time limit
    struct SYSTEM_PROCESS_INFO *largest = NULL;
    clock_t startTime = clock();
