using namespace std;

struct NAS_PDU {
    string RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
};

class NAS_PDU_Collection {
private:
    vector<NAS_PDU> pdu_list;
    map<int, NAS_PDU*> pdu_map;

public:
    NAS_PDU_Collection() {}

    ~NAS_PDU_Collection() {
        for (auto it = pdu_map.begin(); it != pdu_map.end(); ++it) {
            delete it->second;
        }
    }

    void add(const NAS_PDU& pdu) {
        // Check if the PDU already exists in the map
        auto it = pdu_map.find(pdu.RNTI);
        if (it != pdu_map.end()) {
            return;
        }

        // Add the PDU to the list and map
        pdu_list.push_back(pdu);
        pdu_map[pdu.RNTI] = &pdu_list.back();
    }

    void remove(int rnti) {
        // Check if the PDU exists in the map
        auto it = pdu_map.find(rnti);
        if (it == pdu_map.end()) {
            return;
        }

        // Remove the PDU from the list and map
        NAS_PDU* pdu = it->second;
        pdu_list.erase(remove(pdu_list.begin(), pdu_list.end(), *pdu), pdu_list.end());
        pdu_map.erase(it);
    }

    NAS_PDU* get(int rnti) {
        // Check if the PDU exists in the map
        auto it = pdu_map.find(rnti);
        if (it == pdu_map.end()) {
            return nullptr;
        }

        return it->second;
    }

    void update(int rnti, const NAS_PDU& pdu) {
        // Check if the PDU exists in the map
        auto it = pdu_map.find(rnti);
        if (it == pdu_map.end()) {
            return;
        }

        // Update the PDU in the list and map
        NAS_PDU* existing_pdu = it->second;
        *existing_pdu = pdu;
    }

    int size() {
        return pdu_list.size();
    }

    void clear() {
        pdu_map.clear();
        pdu_list.clear();
    }
};

class MemoryPool {
private:
    vector<NAS_PDU> pool;
    int pool_size;

public:
    MemoryPool(int size) : pool_size(size) {}

    ~MemoryPool() {
        for (auto it = pool.begin(); it != pool.end(); ++it) {
            delete it->second;
        }
    }

    NAS_PDU* allocate() {
        if (pool.empty()) {
            return nullptr;
        }

        NAS_PDU* pdu = &pool.back();
        pool.pop_back();
        return pdu;
    }

    void deallocate(NAS_PDU* pdu) {
        if (pdu == nullptr) {
            return;
        }

        pool.push_back(*pdu);
    }
};

class NAS_PDU_Manager {
private:
    MemoryPool* memory_pool;
    NAS_PDU_Collection nas_pdus;

public:
    NAS_PDU_Manager(int size) : memory_pool(new MemoryPool(size)) {}

    ~NAS_PDU_Manager() {
        delete memory_pool;
    }

    void add(const NAS_PDU& pdu) {
        // Check if the PDU already exists in the collection
        auto it = nas_pdus.find(pdu.RNTI);
        if (it != nas_pdus.end()) {
            return;
        }

        // Allocate a new PDU from the memory pool
        NAS_PDU* new_pdu = nullptr;
        try {
            new_pdu = memory_pool->allocate();
        } catch (exception& e) {
            cerr << "Memory allocation error: " << e.what() << endl;
            return;
        }

        // Copy the input PDU to the new PDU and add it to the collection
        *new_pdu = pdu;
        nas_pdus.add(*new_pdu);
    }

    void remove(int rnti) {
        // Check if the PDU exists in the collection
        auto it = nas_pdus.find(rnti);
        if (it == nas_pdus.end()) {
            return;
        }

        // Remove the PDU from the collection and deallocate its memory
        NAS_PDU* pdu = it->second;
        nas_pdus.remove(rnti);
        memory_pool->deallocate(pdu);
    }

    void update(int rnti, const NAS_PDU& pdu) {
        // Check if the PDU exists in the collection
        auto it = nas_pdus.find(rnti);
        if (it == nas_pdus.end()) {
            return;
        }

        // Update the PDU in the collection and deallocate its memory
        NAS_PDU* existing_pdu = it->second;
        *existing_pdu = pdu;
        memory_pool->deallocate(existing_pdu);
    }

    void clear() {
        nas_pdus.clear();
        memory_pool->clear();
    }
};
