#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>
#include <sys/mman.h>
#include <limits.h>

#define MAX_RECORDS 1000000
#define MAX_OFFSETS 1000000
#define MAX_KEYS 1000000
#define MAX_MEMORY 1024 * 1024 * 1024 // 1 GB
#define DEFAULT_COMPRESSION_RATIO 5
#define COMPRESSION_ALGORITHM "lz4"

struct record {
    long offset;
    int key;
    float value;
    bool validity;
};

struct dataPoint {
    long timestamp;
    float value;
    bool validity;
};

struct cache {
    struct record *records;
    size_t num_records;
    struct semaphore *locks;
    size_t num_locks;
};

void initializeCache(struct cache *cache) {
    // allocate memory for the records, offset and key arrays
    cache->records = (struct record *) malloc(MAX_RECORDS * sizeof(struct record));
    memset(cache->records, 0, MAX_RECORDS * sizeof(struct record));
    cache->offset = (long *) malloc(MAX_OFFSETS * sizeof(long));
    memset(cache->offset, 0, MAX_OFFSETS * sizeof(long));
    cache->key = (int *) malloc(MAX_KEYS * sizeof(int));
    memset(cache->key, 0, MAX_KEYS * sizeof(int));

    // initialize the locks for concurrent access
    cache->locks = (struct semaphore *) malloc(MAX_LOCKS * sizeof(struct semaphore));
    for (size_t i = 0; i < MAX_LOCKS; ++i) {
        semaphore_init(&cache->locks[i], NULL, 1);
    }

    // initialize the number of locks
    cache->num_locks = MAX_LOCKS;
}

void updateCache(struct cache *cache, struct dataPoint *data) {
    // acquire the lock for the given key
    semaphore_wait(&cache->locks[data->key % cache->num_locks]);

    // check if the record exists in the cache
    size_t index = findRecord(cache, data->key);

    // update the record if it already exists
    if (index != SIZE_MAX) {
        struct record *record = &cache->records[index];
        record->value = data->value;
        record->validity = true;
    } else {
        // add a new record to the cache
        struct record *newRecord = &cache->records[cache->num_records++];
        newRecord->offset = 0;
        newRecord->key = data->key;
        newRecord->value = data->value;
        newRecord->validity = true;
    }

    // release the lock
    semaphore_post(&cache->locks[data->key % cache->num_locks]);
}

size_t findRecord(struct cache *cache, int key) {
    for (size_t i = 0; i < cache->num_records; ++i) {
        if (cache->records[i].key == key) {
            return i;
        }
    }
    return SIZE_MAX;
}

void evictRecords(struct cache *cache, size_t num_records) {
    // acquire the lock for the cache
    semaphore_wait(&cache->locks[0]);

    // update the offset and key arrays
    for (size_t i = 0; i < num_records; ++i) {
        struct record *record = &cache->records[cache->num_records - i];
        cache->offset[record->offset] = SIZE_MAX;
        cache->key[record->key] = INT_MIN;
    }

    // update the number of records
    cache->num_records -= num_records;

    // release the lock
    semaphore_post(&cache->locks[0]);
}

void compressRecords(struct cache *cache) {
    // acquire the lock for the cache
    semaphore_wait(&cache->locks[0]);

    // compress the records if necessary
    size_t new_num_records = 0;
    for (size_t i = 0; i < cache->num_records; ++i) {
        struct record *record = &cache->records[i];
        if (record->validity) {
            cache->offset[new_num_records] = record->offset;
            cache->key[new_num_records] = record->key;
            new_num_records++;
        }
    }

    // update the number of records
    cache->num_records = new_num_records;

    // release the lock
    semaphore_post(&cache->locks[0]);
}

void cleanupCache(struct cache *cache) {
    // free the memory for the records, offset and key arrays
    free(cache->records);
    free(cache->offset);
    free(cache->key);

    // free the locks
    for (size_t i = 0; i < cache->num_locks; ++i) {
        semaphore_destroy(&cache->locks[i]);
    }
    free(cache->locks);
}
