#include <unistd.h>

#define MAX_POOL_SIZE 1024 * 1024 * 8 // 8 MB
#define MAX_BATCH_SIZE 5000
#define MIN_PROCESS_ID 1
#define MAX_PROCESS_ID 65535
#define PROCESS_STATUS_T int
#define TIMESTAMP time_t

typedef struct {
    PROCESS_ID pid;
    PROCESS_STATUS_T status;
    TIMESTAMP timestamp;
} SYSTEM_PROCESS_INFO;

// Memory pool for reusing SYSTEM_PROCESS_INFO structures
struct memory_pool {
    size_t size;
    size_t count;
    SYSTEM_PROCESS_INFO* items;
};

// Hash map to detect duplicate PROCESS_IDs efficiently
struct hash_map {
    size_t capacity;
    size_t count;
    size_t* keys;
    SYSTEM_PROCESS_INFO** values;
};

// Batch processing mechanism for reducing updates frequency
struct batch_processing {
    size_t batch_size;
    size_t update_interval;
    time_t last_update;
    bool active;
    SYSTEM_PROCESS_INFO* batch[MAX_BATCH_SIZE];
};

// Function to allocate and initialize a memory pool for SYSTEM_PROCESS_INFO structures
struct memory_pool* create_memory_pool(size_t size) {
    if (size > MAX_POOL_SIZE) {
        return NULL;
    }

    struct memory_pool* pool = (struct memory_pool*)malloc(sizeof(struct memory_pool));
    pool->size = size;
    pool->count = 0;
    pool->items = (SYSTEM_PROCESS_INFO*)calloc(pool->size, sizeof(SYSTEM_PROCESS_INFO));

    return pool;
}

// Function to allocate and initialize a hash map for detecting duplicate PROCESS_IDs
struct hash_map* create_hash_map(size_t capacity) {
    if (capacity > MAX_POOL_SIZE / sizeof(SYSTEM_PROCESS_INFO)) {
        return NULL;
    }

    struct hash_map* map = (struct hash_map*)malloc(sizeof(struct hash_map));
    map->capacity = capacity;
    map->count = 0;
    map->keys = (size_t*)calloc(map->capacity, sizeof(size_t));
    map->values = (SYSTEM_PROCESS_INFO**)calloc(map->capacity, sizeof(SYSTEM_PROCESS_INFO*));

    return map;
}

// Function to allocate and initialize a batch processing mechanism for reducing updates frequency
struct batch_processing* create_batch_processing() {
    struct batch_processing* batch = (struct batch_processing*)malloc(sizeof(struct batch_processing));
    batch->batch_size = MAX_BATCH_SIZE;
    batch->update_interval = 10; // 10 seconds
    batch->last_update = time(NULL);
    batch->active = false;

    return batch;
}

// Function to allocate and initialize a SYSTEM_PROCESS_INFO structure
SYSTEM_PROCESS_INFO* create_process_info() {
    SYSTEM_PROCESS_INFO* process_info = (SYSTEM_PROCESS_INFO*)malloc(sizeof(SYSTEM_PROCESS_INFO));
    process_info->pid = 0;
    process_info->status = 0;
    process_info->timestamp = time(NULL);

    return process_info;
