// Define a cache entry struct to store the key, value, and timestamp
struct CacheEntry {
    string key;
    vector<unsigned char> value;
    chrono::time_point<chrono::steady_clock> timestamp;

    // Overload operator== for easier comparison of cache entries
    bool operator==(const CacheEntry& other) const {
        return key == other.key && value == other.value && timestamp == other.timestamp;
    }
};

// Define a cache class to manage the LRU eviction policy and compression
class Cache {
    public:
        // Constructor to initialize the cache with a given capacity
        explicit Cache(size_t capacity) : capacity_(capacity), size_(0) {}

        // Insert a new key-value pair into the cache, update the timestamp
        void insert(const string& key, const vector<unsigned char>& value) {
            auto it = cache_.find(key);
            if (it != cache_.end()) {
                // Update the existing entry's timestamp and value
                it->second.value = value;
                it->second.timestamp = chrono::steady_clock::now();
            } else {
                // Insert a new entry into the cache
                cache_.emplace(key, CacheEntry{ key, value, chrono::steady_clock::now() });
                size_++;
            }

            // Remove the least recently used entry if the cache is full
            if (size_ > capacity_) {
                auto it = find_if(cache_.begin(), cache_.end(), [this](const pair<string, CacheEntry>& p) { return p.second.timestamp < cache_.begin()->second.timestamp; });
                cache_.erase(it);
            }
        }

        // Lookup a key in the cache and return its associated value
        vector<unsigned char> lookup(const string& key) const {
            auto it = cache_.find(key);
            if (it != cache_.end()) {
                // Update the entry's timestamp
                it->second.timestamp = chrono::steady_clock::now();
                return it->second.value;
            } else {
                return {};
            }
        }

        // Refresh a key-value pair in the cache based on its timestamp, update the value and timestamp
        void refresh(const string& key, const vector<unsigned char>& value) {
            auto it = cache_.find(key);
            if (it != cache_.end()) {
                it->second.value = Compressor::compress(value);
                it->second.timestamp = chrono::steady_clock::now();
            } else {
                // Insert a new entry into the cache
                cache_.emplace(key, CacheEntry{ key, value, chrono::steady_clock::now() });
                size_++;
            }
        }

        // Clear the cache and reset its capacity
        void clear() {
            cache_.clear();
            size_ = 0;
        }

    private:
        // Capacity of the cache
        const size_t capacity_;
        // Size of the cache
        size_t size_;
        // Map to store the key-value pairs
        unordered_map<string, CacheEntry> cache_;
};

// Define a distributed cache class to manage the cache across multiple instances
class DistributedCache {
    public:
        // Constructor to initialize the cache with a given capacity and number of instances
        explicit DistributedCache(size_t capacity, size_t num_instances) : capacity_(capacity), num_instances_(num_instances), cache_(capacity / num_instances) {}

        // Insert a new key-value pair into the cache, update the timestamp and broadcast the insertion to other instances
        void insert(const string& key, const vector<unsigned char>& value) {
            auto it = cache_.find(key);
            if (it != cache_.end()) {
                // Update the existing entry's timestamp and value
                it->second.value = value;
                it->second.timestamp = chrono::steady_clock::now();
            } else {
                // Insert a new entry into the cache
                cache_.emplace(key, CacheEntry{ key, value, chrono::steady_clock::now() });
                size_++;
            }

            // Broadcast the insertion to other instances
            for (size_t i = 1; i < num_instances_; ++i) {
                cache_[key].value = value;
                cache_[key].timestamp = chrono::steady_clock::now();
            }
        }

        // Lookup a key in the cache and return its associated value, fetching from other instances if necessary
        vector<unsigned char> lookup(const string& key) const {
            auto it = cache_.find(key);
            if (it != cache_.end()) {
                // Update the entry's timestamp
                it->second.timestamp = chrono::steady_clock::now();
                return it->second.value;
            } else {
                // Fetch the value from other instances and update the cache
                for (size_t i = 1; i < num_instances_; ++i) {
                    auto it = cache_.find(key);
                    if (it != cache_.end()) {
                        cache_[key].value = it->second.value;
                        cache_[key].timestamp = chrono::steady_clock::now();
                        return cache_[key].value;
                    }
                }
                return {};
            }
        }

        // Refresh a key-value pair in the cache based on its timestamp, update the value and broadcast the refreshment to other instances
        void refresh(const string& key, const vector<unsigned char>& value) {
            auto it = cache_.find(key);
            if (it != cache_.end()) {
                it->second.value = Compressor::compress(value);
                it->second.timestamp = chrono::steady_clock::now();
            } else {
                // Insert a new entry into the cache
                cache_.emplace(key, CacheEntry{ key, value, chrono::steady_clock::now() });
                size_++;
            }

            // Broadcast the refreshment to other instances
            for (size_t i = 1; i < num_instances_; ++i) {
                cache_[key].value = value;
                cache_[key].timestamp = chrono::steady_clock::now();
            }
        }

        // Clear the cache and reset its capacity and number of instances
        void clear() {
            cache_.clear();
            size_ = 0;
        }

    private:
        // Capacity of the cache
        const size_t capacity_;
        // Number of instances in the distributed cache
        const size_t num_instances_;
        // Map to store the key-value pairs across multiple instances
        unordered_map<string, CacheEntry> cache_;
};
