typedef struct {
    float* values;
    size_t count;
} input_data_t;

float median(input_data_t* data) {
    if (data->count == 0) {
        return 0.0f;
    } else if (data->count % 2 == 0) {
        return (data->values[data->count / 2 - 1] + data->values[data->count / 2]) / 2.0f;
    } else {
        return data->values[data->count / 2];
    }
}

float* get_weights(input_data_t* data, float* weights) {
    if (data->count == 0) {
        return NULL;
    }
    for (size_t i = 0; i < data->count; i++) {
        weights[i] = data->values[i];
    }
    return weights;
}

float weighted_median(input_data_t* data, float* weights) {
    if (data->count == 0 || weights == NULL) {
        return 0.0f;
    }
    size_t total_weight = 0;
    for (size_t i = 0; i < data->count; i++) {
        total_weight += fabs(weights[i]);
    }
    float median_value = 0.0f;
    float current_total_weight = 0.0f;
    for (size_t i = 0; i < data->count; i++) {
        if (current_total_weight + fabs(weights[i]) >= total_weight / 2) {
            median_value = data->values[i];
            break;
        }
        current_total_weight += fabs(weights[i]);
    }
    return median_value;
}

void process_input(float* input, size_t count) {
    if (count > MAX_VALUE_COUNT) {
        printf("Input exceeds the maximum value count of %zu. Please reduce the input size.\n", MAX_VALUE_COUNT);
        return;
    }
    input_data_t data = {input, count};
    float median_value = median(&data);
    float* weights = get_weights(&data, NULL);
    if (weights != NULL) {
        float weighted_median_value = weighted_median(&data, weights);
        printf("Weighted median: %f\n", weighted_median_value);
    } else {
        printf("Median: %f\n", median_value);
    }
}

int main() {
    float* input = NULL;
    size_t count = 0;
    while (count < MAX_VALUE_COUNT) {
        // Read a single floating-point value from standard input
        float value;
        scanf("%f", &value);
        if (value == -1.0f) {
            break;
        }
        // Reallocate memory for the array if necessary
        if (input == NULL || count >= MAX_VALUE_COUNT / 2) {
            input = realloc(input, sizeof(float) * (count + 1));
            if (input == NULL) {
                printf("Memory allocation failed. Please reduce the input size.\n");
                break;
            }
        }
        // Add the value to the array and update the count
        input[count] = value;
        count++;
    }
    // Process the input values
    process_input(input, count);
    // Free allocated memory
    free(input);
    return 0;
}
