} SESSION_STATS_RECORD;

// Define the function to manage dynamic array of SESSION_STATS_RECORD structures
void manage_session_stats(SESSION_STATS_RECORD** stats, int M) {
    // Initialize the array with NULL pointers
    for (int i = 0; i < M; i++) {
        stats[i] = NULL;
    }

    // Memory pool for reuse of SESSION_STATS_RECORD structures
    SESSION_STATS_RECORD* mem_pool = malloc(sizeof(SESSION_STATS_RECORD) * M);

