        // Update the BYTES_TRANSFERRED value based on simulated network traffic model
        update_bytes_transferred(stats, i);

        // Increment i and check if we have reached the end of the array
        i++;
        if (i == M) {
            break;
        }
    }

    // Handle memory leaks and ensure the function can scale to handle large values of M without significant performance degradation
    for (int j = 0; j < i; j++) {
        free(stats[j]);
    }
    free(mem_pool);
    free(stats);
}

// Check if a given USER_ID is already used in the current session
int check_duplicate_user_id(SESSION_STATS_RECORD** stats, int M, int user_id) {
    for (int i = 0; i < M; i++) {
        if (stats[i] && stats[i]->USER_ID == user_id) {
            return 1;
        }
    }
    return 0;
}

// Update the BYTES_TRANSFERRED value based on simulated network traffic model
void update_bytes_transferred(SESSION_STATS_RECORD** stats, int i) {
    // Simulate a random amount of data transfer in kilobytes per second
    double data_transfer = (double)(rand() % 1024 * rand()) / 1024;
