#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>

// Define the structures used for sensor data and temperature reports
struct SensorData {
    long long timestamp;
    float temperature;
    double location[2];
    bool quality_flag;
};

struct TemperatureReportIndication {
    int sensor_id;
    long crcflag;
    float temperature;
};

// Define the linked list structure for sensor devices
struct SensorDevice {
    struct SensorDevice* next;
    struct SensorData data;
};

// Define the memory pool structure for temperature reports
struct TemperatureReportPool {
    int size;
    struct TemperatureReportIndication** reports;
};

// Define the cache structure for sensor data
struct Cache {
    pthread_mutex_t mutex;
    struct SensorData* data;
    int capacity;
};

// Initialize the cache with the given capacity
void initCache(struct Cache* cache, int capacity) {
    // Allocate memory for the cache data structure
    cache->data = (struct SensorData*)malloc(sizeof(struct SensorData) * capacity);
    if (cache->data == NULL) {
        perror("Failed to allocate memory for cache");
        exit(1);
    }

    // Initialize the mutex for protecting the cache data structure
    pthread_mutex_init(&cache->mutex, NULL);

    // Set the capacity of the cache
    cache->capacity = capacity;
}

// Add a new sensor data entry to the cache
void addCacheEntry(struct Cache* cache, struct SensorData data) {
    pthread_mutex_lock(&cache->mutex);

    // Check if there is space in the cache for another entry
    if (cache->capacity == 0) {
        perror("Cache is full");
        exit(1);
    }

    // Add the new data to the cache
    cache->data[cache->size++] = data;

    pthread_mutex_unlock(&cache->mutex);
}

// Remove a sensor data entry from the cache
void removeCacheEntry(struct Cache* cache, int index) {
    pthread_mutex_lock(&cache->mutex);

    // Check if the given index is valid
    if (index >= cache->size || index < 0) {
        perror("Invalid index");
        exit(1);
    }

    // Shift all elements after the given index down by one
    for (int i = index + 1; i < cache->size; ++i) {
        cache->data[i - 1] = cache->data[i];
    }

    // Decrement the size of the cache
    --cache->size;

    pthread_mutex_unlock(&cache->mutex);
}

// Get a sensor data entry from the cache
struct SensorData getCacheEntry(struct Cache* cache, int index) {
    pthread_mutex_lock(&cache->mutex);

    // Check if the given index is valid
    if (index >= cache->size || index < 0) {
        perror("Invalid index");
        exit(1);
    }

    struct SensorData data = cache->data[index];

    pthread_mutex_unlock(&cache->mutex);

    return data;
}

// Initialize the memory pool for temperature reports with the given size
void initTemperatureReportPool(struct TemperatureReportPool* pool, int size) {
    // Allocate memory for the report pool data structure
    pool->reports = (struct TemperatureReportIndication**)malloc(sizeof(struct TemperatureReportIndication*) * size);
    if (pool->reports == NULL) {
        perror("Failed to allocate memory for temperature report pool");
        exit(1);
    }

    // Initialize the size of the report pool
    pool->size = size;
}

// Add a new temperature report to the report pool
void addTemperatureReport(struct TemperatureReportPool* pool, struct TemperatureReportIndication report) {
    pthread_mutex_lock(&pool->mutex);

    // Check if there is space in the report pool for another report
    if (pool->size == 0) {
        perror("Temperature report pool is full");
        exit(1);
    }

    // Allocate memory for the new report and copy the given data to it
    struct TemperatureReportIndication* new_report = (struct TemperatureReportIndication*)malloc(sizeof(struct TemperatureReportIndication));
    memcpy(new_report, &report, sizeof(struct TemperatureReportIndication));

    // Add the new report to the pool
    pool->reports[pool->size++] = new_report;

    pthread_mutex_unlock(&pool->mutex);
}

// Remove a temperature report from the report pool
void removeTemperatureReport(struct TemperatureReportPool* pool, int index) {
    pthread_mutex_lock(&pool->mutex);

    // Check if the given index is valid
    if (index >= pool->size || index < 0) {
        perror("Invalid index");
        exit(1);
    }

    // Free the memory allocated for the report at the given index
    free(pool->reports[index]);

    // Shift all elements after the given index down by one
    for (int i = index + 1; i < pool->size; ++i) {
        pool->reports[i - 1] = pool->reports[i];
    }

    // Decrement the size of the report pool
    --pool->size;

    pthread_mutex_unlock(&pool->mutex);
}

// Get a temperature report from the report pool
struct TemperatureReportIndication getTemperatureReport(struct TemperatureReportPool* pool, int index) {
    pthread_mutex_lock(&pool->mutex);

    // Check if the given index is valid
    if (index >= pool->size || index < 0) {
        perror("Invalid index");
        exit(1);
