int manageNfapiCrcIndicationList(NFAPI_CRC_INDICATION_PDU_T** pduList, uint16_t* crcCount) {
    // Check if the list is empty and initialize it if necessary
    if (*pduList == NULL) {
        *pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memset(*pduList, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Check if the maximum number of PDUs has been reached and add a new one if necessary
    if ((*crcCount + 1) > MAX_NFAPI_PDU_COUNT) {
        *pduList = (NFAPI_CRC_INDICATION_PDU_T*)realloc(*pduList, (*crcCount + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Update the list and increment the total number of CRC indications
    if ((*crcCount + 1) <= MAX_NFAPI_PDU_COUNT) {
        (*pduList)[(*crcCount)].rxUeInformationTag = (RX_UE_INFORMATION_TAG){ .numberOfSamples = 0, .rnti = 0 };
        (*pduList)[(*crcCount)].rnti = rnti;
        (*pduList)[(*crcCount)].crcIndicationRel8Tag = (CRC_INDICATION_REL8_TAG){ .crcFlag = CRC_FLAG_SET };
        (*crcCount)++;
    }

    // Return the populated list and the total number of CRC indications
    return *pduList;
}

