    if (array == NULL || array->values == NULL) {
        printf("Error: Invalid input\n");
        return;
    }
    // Use the external library to generate random numbers
    srand(time(NULL));
    for (int i = 0; i < array->capacity; i++) {
        int r = rand() % max + min;
        if (r == INT_MIN) {
            printf("Error: Failed to generate random number\n");
            break;
        }
        array->values[i] = r;
    }
}

// Function to set the value of each integer in the array to a random value within a specified range, ensuring no duplicates
void setRandomIntegers(IntArray *array, int min, int max) {
    if (array == NULL || array->values == NULL) {
        printf("Error: Invalid input\n");
        return;
    }
    // Use a hash set to track unique values and handle duplicates efficiently
    HashSet *set = createHashSet(MAX_INTEGERS);
    if (set == NULL) {
        printf("Error: Failed to allocate memory for hash set\n");
        return;
    }
    for (int i = 0; i < array->capacity; i++) {
        // Generate a random integer within the specified range and add it to the hash set if unique
        int r = rand() % max + min;
        if (!addToHashSet(set, &r)) {
            printf("Error: Failed to add value to hash set\n");
            break;
        }
        array->values[i] = r;
    }
    destroyHashSet(set);
}

// Function to release all allocated memory when the function is complete
void cleanup(IntArray *array) {
    if (array != NULL && array->values != NULL) {
        free(array->values);
        array->values = NULL;
    }
}

int main() {
    // Read integers from standard input and allocate memory as needed
    IntArray *array = readIntegers();
    if (array == NULL) {
        printf("Error: Failed to read integers\n");
        return 1;
    }

    // Find the largest integer in the array and print it
    findLargestInteger(array);

    // Generate random integers within a specified range
    generateRandomIntegers(array, MIN_RANDOM_VALUE, MAX_RANDOM_VALUE);

    // Set the value of each integer in the array to a random value within a specified range, ensuring no duplicates
    setRandomIntegers(array, MIN_RANDOM_VALUE, MAX_RANDOM_VALUE);

    // Release all allocated memory when the function is complete
    cleanup(array);

    return 0;
}
```
