    // Check if the RNTI is already in the table
    bool exists = false;
    for (int i = 0; i < table->size && !exists; i++) {
        if (table->elements[i] == true) {
            exists = true;
        }
    }
    // If the RNTI is not in the table, add it and return true
    if (!exists) {
        for (int i = 0; i < table->size && !exists; i++) {
            if (!table->elements[i]) {
                table->elements[i] = true;
                exists = true;
