            if (table->elements[i] == true) {
                table->elements[i] = false;
                exists = true;
            }
        }
    }
    return exists;
}

// Allocate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures for a specified number of users
NFAPI_CRC_INDICATION_PDU_T* allocateAndPopulateCRCIndicationArray(uint16_t numUsers) {
    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* crcIndicationArray = (NFAPI_CRC_INDICATION_PDU_T*) malloc(numUsers * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the hash table to store RNTIs
    RNTIHashTable rntiHashTable;
    initRNTIHashTable(&rntiHashTable);

    // Loop through each user and populate the NFAPI_CRC_INDICATION_PDU_T structure for that user
    for (int i = 0; i < numUsers; i++) {
        // Generate a random RNTI between 1 and 65535
        uint16_t rnti = rand() % 65536 + 1;

        // Check if the RNTI is already in the hash table
        bool exists = addRNTIToHashTable(&rntiHashTable, rnti);

        // If the RNTI is not in the hash table, add it and populate the NFAPI_CRC_INDICATION_PDU_T structure
        if (!exists) {
            crcIndicationArray[i].rnti = rnti;
            crcIndicationArray[i].crcFlag = rand() % 256; // Set the CRCFlag to a random value between 0 and 255
        } else {
            // If the RNTI is already in the hash table, try again with a new RNTI
            i--;
        }
    }

    // Clean up the hash table
    free(rntiHashTable.elements);

    return crcIndicationArray;
}
