// Define a flag to track the total number of UL_RLC_AM_PDU instances with DL_ACK_FLAG set
static volatile bool dl_ack_flag_set = false;

// Define a function to resize the list when it reaches its maximum capacity
void resize_list(int new_size) {
    // Lock the list before resizing
    pthread_mutex_lock(&list_lock);

    // Reallocate memory for the list
    NFAPI_RLC_AM_PDU_T *new_list = realloc(list, new_size * sizeof(NFAPI_RLC_AM_PDU_T));

    // If the allocation was successful, update the list pointer and size
    if (new_list != NULL) {
        list = new_list;
        list_size = new_size;
    } else {
        // If the allocation failed, log an error message
        fprintf(stderr, "Failed to resize list: %s\n", strerror(errno));
    }

    // Unlock the list after resizing
    pthread_mutex_unlock(&list_lock);
}

// Define a function to add an NFAPI_RLC_AM_PDU_T structure to the list
void add_pdu(NFAPI_RLC_AM_PDU_T *pdu) {
    // Lock the list before adding a PDU
    pthread_mutex_lock(&list_lock);

    // If the list is full, resize it to accommodate the new PDU
    if (list_size == MAX_NFAPI_PDU_COUNT) {
        resize_list(list_size * 2);
    }

    // Add the new PDU to the end of the list
    list[list_size++] = *pdu;

    // If the DL_ACK_FLAG is set, increment the flag counter
    if (pdu->DL_RLC_AM_PDU.DL_ACK_FLAG) {
        dl_ack_flag_set++;
    }

    // Unlock the list after adding the PDU
    pthread_mutex_unlock(&list_lock);
}

// Define a function to get the total number of UL_RLC_AM_PDU instances with DL_ACK_FLAG set
int get_dl_ack_flag_count(void) {
    // Lock the list before reading the flag counter
    pthread_mutex_lock(&list_lock);

    // Return the current value of the flag counter
    int count = dl_ack_flag_set;

    // Unlock the list after reading the flag counter
    pthread_mutex_unlock(&list_lock);

    return count;
}

// Define a function to get the populated list of NFAPI_RLC_AM_PDU_T structures
NFAPI_RLC_AM_PDU_T *get_pdu_list(void) {
    // Lock the list before returning it
    pthread_mutex_lock(&list_lock);

    // Return a copy of the list
    NFAPI_RLC_AM_PDU_T *copy = malloc(list_size * sizeof(NFAPI_RLC_AM_PDU_T));
    memcpy(copy, list, list_size * sizeof(NFAPI_RLC_AM_PDU_T));

    // Unlock the list after returning it
    pthread_mutex_unlock(&list_lock);

    return copy;
}
