// Define the maximum number of integers that can be read from standard input
#define MAX_INTEGERS 10000
// Define the minimum and maximum values for the random range
#define MIN_RANDOM -1000000
#define MAX_RANDOM 1000000
// Define the maximum amount of memory that can be allocated for the integer array
#define MAX_MEMORY 1048576

// Function to read a list of integers from standard input and validate them
void readIntegers(int *integers, int *numIntegers) {
    // Initialize variables
    int i = 0;
    int maxValue = -INT_MAX;
    int minValue = INT_MAX;
    // Read integers from standard input until the maximum number of integers is reached or a failure occurs
    while (i < MAX_INTEGERS && scanf("%d", &integers[i]) == 1) {
        if (integers[i] > maxValue) maxValue = integers[i];
        if (integers[i] < minValue) minValue = integers[i];
        i++;
    }
    // If the maximum number of integers was reached, print a message to the user
    if (i == MAX_INTEGERS) {
        printf("Maximum number of integers reached. Please try again with fewer values.\n");
    }
    // If any out-of-range values were entered, prompt the user to re-enter them
    for (int j = 0; j < i; j++) {
        if (integers[j] > MAX_RANDOM || integers[j] < MIN_RANDOM) {
            printf("Out of range value entered. Please enter a value between %d and %d: ", MIN_RANDOM, MAX_RANDOM);
            scanf("%d", &integers[j]);
        }
    }
    // Store the number of integers read in the numIntegers variable
    *numIntegers = i;
}

// Function to dynamically allocate memory for an integer array based on the number of integers read
int* allocateMemory(int numIntegers) {
    // Calculate the amount of memory required for the integer array
    int memSize = sizeof(int) * numIntegers;
    // If the amount of memory is too large, print a message to the user and return nullptr
    if (memSize > MAX_MEMORY) {
        printf("Memory allocation failed. Please try again with fewer values.\n");
        return NULL;
    }
    // Dynamically allocate the memory for the integer array
    int *integers = (int *)malloc(memSize);
    if (!integers) {
        printf("Memory allocation failed. Please try again with fewer values.\n");
        return NULL;
    }
    return integers;
}

// Function to find and print the largest integer in an array of integers
void printLargestInteger(int *integers, int numIntegers) {
    // If there are no integers, print a message to the user and return
    if (numIntegers == 0) {
        printf("No integers to find the largest value for.\n");
        return;
    }
    // Initialize variables
    int largest = integers[0];
    // Loop through the array of integers and find the largest value
    for (int i = 1; i < numIntegers; i++) {
        if (integers[i] > largest) {
            largest = integers[i];
        }
    }
    // Print the largest integer to the user
    printf("The largest integer in the array is %d\n", largest);
}

// Function to generate random numbers within a specified range and set them as values for an array of integers
void generateRandomIntegers(int *integers, int numIntegers) {
    // If there are no integers, print a message to the user and return
    if (numIntegers == 0) {
        printf("No integers to set random values for.\n");
        return;
    }
    // Initialize variables
    int i = 0;
    int range = MAX_RANDOM - MIN_RANDOM + 1;
    // Loop through the array of integers and generate a random value for each one
    while (i < numIntegers) {
        // Generate a random integer within the specified range
        int randomInteger = rand() % range + MIN_RANDOM;
        // If the generated value is already present in the array, regenerate it until it is not
        while (findValue(integers, numIntegers, randomInteger)) {
            randomInteger = rand() % range + MIN_RANDOM;
        }
        integers[i] = randomInteger;
        i++;
    }
}

// Function to find a value within an array of integers and return its index if present, otherwise return -1
int findValue(int *integers, int numIntegers, int value) {
    // Loop through the array of integers and check for the presence of the specified value
    for (int i = 0; i < numIntegers; i++) {
        if (integers[i] == value) return i;
    }
    return -1;
}

// Function to set a value within an array of integers and return true if successful, otherwise return false
int setValue(int *integers, int numIntegers, int index, int value) {
    // If the specified index is out of bounds, return false
    if (index < 0 || index >= numIntegers) return false;
    integers[index] = value;
    return true;
}

// Function to check for under-allocation and allocate more memory as needed
int* reallocateMemory(int *integers, int numIntegers, int memSize) {
    // If the amount of memory is too large, print a message to the user and return nullptr
    if (memSize > MAX_MEMORY) {
        printf("Memory allocation failed. Please try again with fewer values.\n");
        return NULL;
    }
    // Dynamically allocate the new memory for the integer array
    int *newIntegers = (int *)malloc(memSize);
    if (!newIntegers) {
        printf("Memory allocation failed. Please try again with fewer values.\n");
        return NULL;
    }
    // Copy the old integers to the new memory
    for (int i = 0; i < numIntegers; i++) {
        newIntegers[i] = integers[i];
    }
    free(integers);
    return newIntegers;
}

// Main function
int main() {
    // Declare variables for the integer array and its size
    int *integers;
    int numIntegers;
    // Read input from the user for the number of integers to allocate memory for
    printf("Enter the number of integers: ");
    scanf("%d", &numIntegers);
    // Dynamically allocate memory for the integer array and read input from the user for the values
    integers = allocateMemory(numIntegers);
    if (!integers) return 1;
    printf("Enter the values: ");
    for (int i = 0; i < numIntegers; i++) {
        scanf("%d", &integers[i]);
    }
    // Find and print the largest integer in the array of integers
    printLargestInteger(integers, numIntegers);
    // Generate random numbers within a specified range and set them as values for an array of integers
    generateRandomIntegers(integers, numIntegers);
    // Find and print the largest integer in the array of integers after generating new random values
    printf("\n");
    printLargestInteger(integers, numIntegers);
    // Free the memory for the integer array
    free(integers);
    return 0;
}
