// Data structure to store the records
typedef struct {
    long offset;
    int key;
    status_t *status;
} record_t;

// Linked list node for storing and traversing the records
typedef struct {
    record_t *data;
    struct node *next, *prev;
} node_t;

// Locking mechanism to prevent concurrent access to the linked list
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate memory for and initialize four separate arrays:
// one for 'long' offset values, one for 'int' keys, one for 'record' structures, and another for 'status' flags.
// Each 'record' structure should contain a single 'int' value, a pointer to a 'long' offset, and a pointer to a 'status' flag.
// The function should also maintain a doubly linked list of these records for efficient traversal and modification.
void init_records(size_t num_records) {
    // Allocate memory for the arrays
    long *offset_arr = (long *)malloc(sizeof(long) * num_records);
    int *key_arr = (int *)malloc(sizeof(int) * num_records);
    record_t **record_arr = (record_t **)malloc(sizeof(record_t *) * num_records);
    status_t **status_arr = (status_t **)malloc(sizeof(status_t *) * num_records);

    // Initialize the arrays with random 'int' values within a specified range, ensuring no duplicate keys
    for (size_t i = 0; i < num_records; ++i) {
        offset_arr[i] = rand() % INT_MAX;
        key_arr[i] = rand() % INT_MAX;
        status_arr[i] = NULL;
    }

    // Initialize the linked list of records
    node_t *head = NULL, *tail = NULL;
    for (size_t i = 0; i < num_records; ++i) {
        record_t *record = (record_t *)malloc(sizeof(record_t));
        record->offset = offset_arr[i];
        record->key = key_arr[i];
        record->status = status_arr[i];

        if (!head) {
            head = tail = record;
        } else {
            tail->next = record;
            record->prev = tail;
            tail = record;
        }
    }

    // Serialize the linked list to disk using a custom binary format
    FILE *file = fopen("records.bin", "wb");
    if (!file) {
        perror("Error opening file");
        return;
    }

    node_t *node = head;
    while (node) {
        // Write the record data to disk in a custom binary format
        fwrite(&node->data->offset, sizeof(long), 1, file);
        fwrite(&node->data->key, sizeof(int), 1, file);
        fwrite(&node->data->status, sizeof(status_t *), 1, file);

        // Move to the next node in the linked list
        node = node->next;
    }

    fclose(file);
}

// Function to retrieve the offset associated with a specific key
long get_offset(int key) {
    pthread_mutex_lock(&mutex);

    // Search for the record with the given key in the linked list
    node_t *node = head;
    while (node) {
        if (node->data->key == key) {
            break;
        }
        node = node->next;
    }

    long offset = 0;
    if (node) {
        offset = node->data->offset;
    }

    pthread_mutex_unlock(&mutex);

    return offset;
}

// Function to update the status flag for a given key
void update_status(int key, status_t new_status) {
    pthread_mutex_lock(&mutex);

    // Search for the record with the given key in the linked list
    node_t *node = head;
    while (node) {
        if (node->data->key == key) {
            break;
        }
        node = node->next;
    }

    if (node) {
        // Update the status flag for the record
        node->data->status = new_status;
    }

    pthread_mutex_unlock(&mutex);
}

// Function to safely lock and unlock the linked list for concurrent operations
void lock() {
    pthread_mutex_lock(&mutex);
}

void unlock() {
    pthread_mutex_unlock(&mutex);
}

// Function to handle edge cases, such as insufficient memory or invalid data input
static void handle_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    exit(EXIT_FAILURE);
}
